window.claimPaymentReference = async function(reference, studentId, source) {
    if (!window.supabaseClient) {
        throw new Error('Supabase is not ready to verify this payment reference.');
    }

    const normalizedReference = String(reference || '').trim().toUpperCase();
    if (!normalizedReference) throw new Error('A payment reference is required before it can be claimed.');

    const { error } = await window.supabaseClient.from('payment_reference_claims').insert([{
        reference: normalizedReference,
        student_id: String(studentId),
        source: source
    }]);
    if (error && error.code === '23505') return false;
    if (error) throw new Error(`Could not claim payment reference: ${error.message}`);
    return true;
};

window.releasePaymentReference = async function(reference) {
    // Safety check - ensure Supabase is ready
    if (!window.supabaseClient) {
        console.warn('⚠️ Supabase not ready for releasePaymentReference');
        return;
    }

    const normalizedReference = String(reference || '').trim().toUpperCase();
    if (!normalizedReference) return;
    
    try {
        const { error } = await window.supabaseClient.from('payment_reference_claims').delete().eq('reference', normalizedReference);
        if (error) console.error('Could not release payment reference:', error);
    } catch (e) {
        console.error('Payment reference release error:', e);
    }
};

