window.verifyActivationCode = async function() {
    const input = document.getElementById('activationKeyInput').value.trim().toUpperCase();
    const errorBox = document.getElementById('activationError');
    
    if (!input) {
        errorBox.innerText = "Please enter an activation key.";
        errorBox.style.display = 'block';
        return;
    }

    let isValid = false;
    let newExpiry = "";
    let matchedSchoolName = ""; // Will store the name fetched from the database

    // 1. Check for the Master Lifetime Override
    if (input === "HVN-LIFETIME-9999") {
        isValid = true;
        newExpiry = "LIFETIME";
    } 
    // 2. Decode Time-Binded Keys via Auto-Discovery
    else if (input.startsWith("HVN-") && input.split('-').length === 3) {
        const parts = input.split('-');
        const datePart = parts[1]; 
        const checksumPart = parts[2]; 
        
        if (datePart.length === 8) {
            let officialSchools = []; 
            
            // Fetch from the EXACT SAME SOURCE as your Key Generator
            if (typeof window.supabaseClient !== 'undefined') {
                try {
                    const { data } = await window.supabaseClient
                        .from('schools') // Connecting to the master generator table
                        .select('school_name');
                        
                    if (data && data.length > 0) {
                        officialSchools = data.map(row => row.school_name);
                    }
                } catch (e) {
                    console.warn("Could not reach master schools table.");
                }
            }

            // Fallback just in case the database is offline
            if (officialSchools.length === 0) {
                officialSchools = [window.settings?.schoolName || "Your School"];
            }

            // Test the entered key against EVERY official school in the database
            for (let officialName of officialSchools) {
                if (!officialName) continue;
                
                const cleanSchool = officialName.replace(/\s+/g, '').toUpperCase();
                const fingerprint = datePart + cleanSchool;
                
                let sum = 0;
                for(let i = 0; i < fingerprint.length; i++) {
                    sum += fingerprint.charCodeAt(i);
                }
                const expectedChecksum = (sum * 123).toString(16).toUpperCase();
                
                // If the math perfectly aligns, we have found the correct school identity!
                if (checksumPart === expectedChecksum) {
                    isValid = true;
                    newExpiry = `${datePart.slice(0,4)}-${datePart.slice(4,6)}-${datePart.slice(6,8)}`;
                    matchedSchoolName = officialName; 
                    break; // Stop searching, we found the match
                }
            }
        }
    }

    if (isValid) {
        // Prepare memory
        if (!window.settings) window.settings = {};
        
        // 🌟 FORCE SYNCHRONIZATION: Save the exact database name into the system's memory
        if (matchedSchoolName) {
            window.settings.schoolName = matchedSchoolName;
        }
        window.settings.licenseExpiry = newExpiry;
        localStorage.setItem('haven_settings', JSON.stringify(window.settings));

        errorBox.style.color = "#27ae60";
        errorBox.innerText = `✅ Key Accepted! Unlocking ${matchedSchoolName || "System"}...`;
        errorBox.style.display = 'block';

        // Sync to cloud (saving the updated, perfectly matched settings)
        if (typeof window.supabaseClient !== 'undefined') {
            try {
                await window.supabaseClient.from('school_data').upsert({ 
                    id: 'master_settings', 
                    settings: window.settings,
                    last_updated: new Date().toISOString() 
                });
            } catch (e) {
                console.log("Cloud sync paused - unlocking offline.");
            }
        }

        // Clean UI Transition
        setTimeout(() => { 
            const overlay = document.getElementById('havenLockOverlay');
            if (overlay) overlay.remove(); 
            
            // Only reload the page if we discovered a NEW school name 
            // so the text changes on the rest of the dashboard
            if (matchedSchoolName) {
                location.reload(); 
            }
        }, 1500);

    } else {
        errorBox.style.color = "#e74c3c";
        errorBox.innerText = "❌ Invalid key. Ensure the key matches a school in the master database.";
        errorBox.style.display = 'block';
    }
};

