window.populateOnlineEnrollmentDropdown = function() {
    // Look for the "Level/Grade" dropdown in the Online Application form
    const gradeSelect = document.getElementById('appLevel'); 
    if (!gradeSelect) return;

    // Reset dropdown
    gradeSelect.innerHTML = '<option value="">Select Grade / Level...</option>';

    // Grab your MOCL classes (Official Classes & Limits)
    const allClasses = window.officialClasses || window.settings.classes || []; 
    const combinedGrades = {};

    // Group them by Base Grade
    allClasses.forEach(cls => {
        let baseGradeName = cls.level || cls.name || cls.className;
        if(!baseGradeName) return;

        // Grouping regex (e.g. groups "Grade 2 Pink" -> "Grade 2")
        const match = baseGradeName.match(/^(Grade \d+|Form \d+|ECD [A-Z])/i);
        if (match) {
            baseGradeName = match[1].trim();
        }

        if (!combinedGrades[baseGradeName]) {
            combinedGrades[baseGradeName] = { limit: 0, enrolled: 0 };
        }

        combinedGrades[baseGradeName].limit += parseInt(cls.limit) || 0;
        combinedGrades[baseGradeName].enrolled += parseInt(cls.enrolled) || 0;
    });

    // Populate the dropdown
    for (const [gradeName, stats] of Object.entries(combinedGrades)) {
        const availableSpots = stats.limit - stats.enrolled;
        const option = document.createElement('option');
        
        option.value = gradeName;

        if (stats.limit > 0 && availableSpots <= 0) {
            option.text = `${gradeName} - (CLASS FULL)`;
            option.disabled = true;
        } else {
            option.text = gradeName;
        }

        gradeSelect.appendChild(option);
    }
};

