// ==========================================
window.saveData = async function(options = {}) {
    console.log("💾 Starting Secure Sync...");

    // Helper: Safely handle UI status indicators if present
    const safeShowSyncStatus = (msg, color) => {
        if (typeof showSyncStatus === 'function') showSyncStatus(msg, color);
        else console.log(`Sync Status: ${msg}`);
    };

    // Helper: Audit ledger history to calculate absolute real-time balances
    const calculateBalance = (ledger) => {
        if (!ledger || !Array.isArray(ledger)) return 0;
        return ledger.reduce((acc, entry) => {
            const status = String(entry.status || '').toUpperCase();
            if (['VOID', 'VOIDED', 'REVERSAL'].includes(status)) return acc;

            const type = String(entry.type || '').toLowerCase();
            const amount = parseFloat(entry.amount) || 0;
            if (type === 'charge' || type === 'fee') return acc + amount;
            if (['payment', 'discount', 'waiver', 'credit', 'overpayment'].includes(type)) return acc - amount;
            return acc;
        }, 0);
    };

    // 1. Safely update local memory immediately (This prevents zombies!)
    if (window.students) {
        localStorage.setItem('haven_students', JSON.stringify(window.students));
    }
    if (window.settings) {
        localStorage.setItem('haven_settings', JSON.stringify(window.settings));
    }
    
    // Save EcoCash transactions if the function exists
    if (typeof window.saveEcoCashTransactions === 'function') {
        window.saveEcoCashTransactions();
    }

    // Network Radar: Stop execution if offline to prevent fetch failure exceptions
    if (!navigator.onLine) {
        console.warn("Working offline. Data saved to device but Cloud Sync is paused.");
        safeShowSyncStatus("Offline - Saved Locally", "#f39c12");
        return;
    }

    try {
        // 1. Bulletproof Database Data-Mapping for Supabase
        const changedIds = Array.isArray(options.changedIds)
            ? options.changedIds
            : (Array.isArray(window.changedStudentIds) ? window.changedStudentIds : []);
        const sourceStudents = changedIds.length > 0
            ? window.students.filter(s => changedIds.includes(String(s.id)))
            : window.students;
        const updates = sourceStudents.map(s => {
            const currentLedger = s.ledger || [];
            const trueBalance = typeof window.calculateStudentBalance === 'function'
                ? window.calculateStudentBalance({ ledger: currentLedger })
                : calculateBalance(currentLedger);
            s.balanceOwing = trueBalance; 

            return {
                id: s.id,
                name: s.name,
                grade: s.grade,
                gender: s.gender || '',
                // 🎯 FIX: Safely check both formats for all fields
                status: s.enrollmentStatus || s.enrollment_status || s.status || 'active',
                phone: s.phone || s.cell || '',   
                dob: s.dob || '',
                address: s.address || '',
                billing_plan: s.billingPlan || s.billing_plan || 'termly',
                balance_owing: trueBalance,
                payment_deadline: s.paymentDeadline || s.payment_deadline || '', 
                enroll_date: s.enrollDate || s.enroll_date || '',
                transport_tier: s.transportTier || s.transport_tier || 0,
                transport_mode: s.transportMode || s.transport_mode || 'full',
                
                // Use strict boolean checks so 'false' doesn't accidentally trigger a fallback
                food_program: s.foodProgram !== undefined ? s.foodProgram : (s.food_program || false),
                stationery_pack: s.stationeryPack !== undefined ? s.stationeryPack : (s.stationery_pack || false),
            };
        });

        // 2. BATCHED STUDENT UPSERT (Eradicates ERR_HTTP2_PROTOCOL_ERROR)
        // Splits large student lists into chunks of 50 to maintain fast throughput
        const BATCH_SIZE = 50;
        for (let i = 0; i < updates.length; i += BATCH_SIZE) {
            const batch = updates.slice(i, i + BATCH_SIZE);
            // Ensure window.supabaseClient is used
            const { error: studentError } = await window.supabaseClient.from('students').upsert(batch, { onConflict: 'id' });
            if (studentError) throw studentError;
        }

        // 3. PAYLOAD STRIPPING (Protects Network Bandwidth)
        // Deep clone global configurations and strip massive base64 school logo data 
        // to prevent API gateway timeouts during frequent background operations.
        let settingsToSync = JSON.parse(JSON.stringify(window.settings)); 
        if (settingsToSync.logoUrl && settingsToSync.logoUrl.length > 2500000) {
            delete settingsToSync.logoUrl; 
            delete settingsToSync.logo;
        }

        // Settings are independent from student transactions and are synced separately.
        if (options.syncSettings === true) {
            const { error: settingsError } = await window.supabaseClient.from('school_data').upsert({
                id: 'master_settings',
                settings: settingsToSync,
                last_updated: new Date().toISOString()
            });
            if (settingsError) throw settingsError;
        }

        window.changedStudentIds = [];

        console.log("✅ Cloud Sync Successful: Ledgers, Balances, and Settings are safe.");
        safeShowSyncStatus("Synced", "#27ae60"); 

    } catch (err) {
        console.error("❌ Critical Sync Failure:", err);
        safeShowSyncStatus("Sync Failed", "#e74c3c");
        
        // 5. CRITICAL LOCKDOWN TRIGGER
        // Visually alert the user and disable payments to prevent data loss
        const topNavBar = document.getElementById('top-nav-bar');
        if (topNavBar) topNavBar.style.backgroundColor = "red";
        
        const systemStatus = document.getElementById('system-status');
        if (systemStatus) systemStatus.innerText = "⚠️ OFFLINE: DO NOT PROCESS PAYMENTS";
        
        alert("CRITICAL ERROR: The system failed to connect to the live database. You are viewing old, offline data. Do not process any new payments until this is resolved.");
        
        const processBtn = document.getElementById('process-payment-btn'); 
        if (processBtn) processBtn.disabled = true;
    }
};

