// 7. BILLING ENGINE & FEES (MONTHLY AWARE)
// ==========================================
window.requireLevel3BillingAccess = function() {
    const role = typeof window.getNormalizedRole === 'function'
        ? window.getNormalizedRole(window.currentUser?.role)
        : String(window.currentUser?.role || '').trim();
    if (role === 'Level 3') return true;
    window.alert('Access denied. Only Level 3 users can run billing actions.');
    return false;
};

const getStudentTransportFare = student => {
    const tier = Number(student.transportTier ?? student.transport_tier);
    if (!Number.isFinite(tier) || tier <= 0) return 0;
    if (!Number.isInteger(tier) || tier > 6) return tier;

    const zone = String.fromCharCode(64 + tier);
    const settings = window.settings || {};
    const fares = settings.transportFares || {};
    const fullFare = parseFloat(fares[`zone${zone}`] || settings[`transZone${zone}Full`]) || 0;
    const configuredOneWayFare = parseFloat(fares[`zone${zone}OneWay`] || settings[`transZone${zone}OneWay`]) || 0;
    const oneWayFare = configuredOneWayFare || (fullFare > 0 ? fullFare / 2 : 0);
    const mode = student.transportMode || student.transport_mode || 'full';

    return mode === 'one_way' ? oneWayFare : fullFare;
};

window.generateFees = async function() {
    if (!window.requireLevel3BillingAccess()) return;

    const targetTerm = window.getCurrentTerm(); 
    const globalTermly = parseFloat(document.getElementById('globalTermlyFee').value) || 0;
    const globalMonthly = parseFloat(document.getElementById('globalMonthlyFee').value) || 0;

    const currentDate = new Date();
    const currentMonthName = currentDate.toLocaleString('default', { month: 'long' });
    const billingPeriod = `${currentMonthName} ${currentDate.getFullYear()}`;

    if (!confirm(`⚠️ Generate standard tuition fees for ${targetTerm} (${currentMonthName})?\n\nThis will only bill students who haven't been billed for this cycle yet.`)) return;
    if (!window.requireLevel3BillingAccess()) return;

    let billCount = 0;

    for (let student of window.students) {
        if (!student.ledger) student.ledger = [];

        // 1. SMART DUPLICATE CHECK: Differentiate between Termly and Monthly
        const isMonthly = (student.billingPlan === 'monthly' || student.billing_plan === 'monthly');
        
        let alreadyBilled = false;
        if (isMonthly) {
            // Check if they already have a fee specifically for THIS month
            alreadyBilled = student.ledger.some(entry => entry.type === 'charge' && entry.desc && entry.desc.includes(currentMonthName));
        } else {
            // Check if they already have a term fee
            alreadyBilled = student.ledger.some(entry => entry.term === targetTerm && entry.type === 'charge' && !(entry.desc || "").includes('Monthly Installment'));
        }

        if (alreadyBilled) continue; 

        // 2. INITIALIZE BILLING
        let amountToBill = 0;
        let breakdownArr = [];

        let gradeFees = [];
        if (Array.isArray(window.feeStructures)) {
            const struct = window.feeStructures.find(f => (f.id === student.grade || f.grade === student.grade));
            gradeFees = struct ? (struct.fees || struct.items || struct) : [];
        } else if (window.feeStructures && window.feeStructures[student.grade]) {
            gradeFees = window.feeStructures[student.grade]; 
        }

        // 3. CALCULATE TOTAL (FRACTIONAL MONTHLY SAFE)
        if (gradeFees && gradeFees.length > 0) {
            gradeFees.forEach(fee => {
                let amt = parseFloat(fee.amount) || 0;
                let feeName = fee.name;
                
                if (isMonthly) {
                    amt = amt / 3; 
                    feeName += ` - Monthly Installment (${currentMonthName})`;
                }
                
                amountToBill += amt;
                breakdownArr.push({ desc: feeName, amt: amt });
            });
        } else {
            let fallbackAmt = isMonthly ? globalMonthly : globalTermly;
            let feeName = isMonthly ? `Standard Tuition - Monthly Installment (${currentMonthName})` : "Standard Tuition";
            
            amountToBill += fallbackAmt;
            breakdownArr.push({ desc: feeName, amt: fallbackAmt });
        }

        // 4. INJECT RECURRING SERVICES
        const transportFare = getStudentTransportFare(student);
        if (transportFare > 0) {
            amountToBill += transportFare;
            const transportLabel = (student.transportMode || student.transport_mode) === 'one_way' ? 'One-Way' : 'Full Route';
            breakdownArr.push({ desc: `Transport Service (${transportLabel}) - ${billingPeriod}`, amt: transportFare });
        }
        if (student.foodProgram) {
            let foodCost = parseFloat(localStorage.getItem('setFoodFee')) || window.settings?.foodFee || 20; 
            amountToBill += foodCost;
            breakdownArr.push({ desc: `Food Program - ${billingPeriod}`, amt: foodCost });
        }
        if (student.stationeryPack) {
            let statCost = parseFloat(localStorage.getItem('setStationeryFee')) || 20;
            amountToBill += statCost;
            breakdownArr.push({ desc: "Stationery Pack", amt: statCost });
        }

        // 5. APPLY THE CHARGE
        if (amountToBill > 0) {
            let desc = isMonthly 
                ? `Monthly Tuition & Fees - ${billingPeriod}` 
                : `Full Term Fees - ${targetTerm}`;

            const transactionId = "INV-" + Date.now() + Math.random().toString(36).substr(2, 5);
            const dateStr = currentDate.toISOString().split('T')[0];

            student.ledger.push({
                id: transactionId,
                date: dateStr,
                type: 'charge',
                amount: amountToBill,
                desc: desc,
                term: targetTerm,
                breakdown: breakdownArr
            });

            student.balanceOpening = (parseFloat(student.balanceOwing) || parseFloat(student.balance_opening) || 0) + amountToBill;
            student.balanceOwing = student.balanceOpening;
            student.balance_owing = student.balanceOpening; 

            billCount++;
        }
    }

    if (billCount > 0) {
        if (typeof window.saveData === 'function') await window.saveData(); 
        alert(`✅ Success! Billed ${billCount} students for ${targetTerm} (${currentMonthName}) and synced to cloud.`);
    } else {
        alert(`ℹ️ No new fees generated. All students were already billed for this period, or fees are set to $0.`);
    }

    if (typeof window.updateDashboard === 'function') window.updateDashboard();
    if (typeof window.filterDirectory === 'function') window.filterDirectory();
    if (typeof window.calculateAdminFinanceStats === 'function') window.calculateAdminFinanceStats();
};


// ==========================================
// ⚡ TARGETED TOP-UP ENGINE (MAGIC BUTTON)
// ==========================================
window.applyBulkTopUp = async function() {
    if (!window.requireLevel3BillingAccess()) return;

    // 2. Extract Data from UI
    const desc = document.getElementById('topupDesc').value.trim();
    const amount = parseFloat(document.getElementById('topupAmount').value);
    const targetGrade = document.getElementById('topupGrade').value;
    const targetTerm = document.getElementById('generateTargetTerm') ? document.getElementById('generateTargetTerm').value : "General";

    // 3. Validation Rules
    if (!desc) return alert("⚠️ Please enter a description for this charge (e.g., 'Term 1 Bus Fare').");
    if (isNaN(amount) || amount <= 0) return alert("⚠️ Please enter a valid amount greater than 0.");
    if (!targetGrade) return alert("⚠️ Please select a target class or 'All Grades'.");

    // 🎯 4. SMART CATEGORIZATION (Matches viewLedger perfectly)
    const dLower = desc.toLowerCase();
    let detectedCategory = 'Standard Tuition / Fee';
    let idPrefix = 'CHG-TOPUP-'; // Default for standard fees

    if (dLower.includes('shop') || dLower.includes('uniform')) {
        detectedCategory = 'Shop / Uniform';
        idPrefix = 'CHG-RCPT-'; // viewLedger looks for 'RCPT' in the ID for Shop
    } else if (dLower.includes('event') || dLower.includes('trip')) {
        detectedCategory = 'Event / Trip';
        idPrefix = 'CHG-EVT-'; // viewLedger looks for 'EVT' in the ID for Events
    }

    // 5. Safe Gatekeeper (Now shows the detected category so the admin knows where it's going!)
    const groupName = targetGrade === 'ALL' ? 'EVERY ACTIVE STUDENT in the school' : `everyone in ${targetGrade}`;
    if (!confirm(`⚠️ MAGIC WARNING: You are about to charge $${amount.toFixed(2)} for "${desc}" to ${groupName}.\n\n📂 Detected Category: ${detectedCategory}\n\nThis will instantly update their ledgers and sync to the cloud. Proceed?`)) return;
    if (!window.requireLevel3BillingAccess()) return;

    let appliedCount = 0;
    const dateStr = new Date().toISOString().split('T')[0];

    // 6. The Ledger Injection Engine
    window.students.forEach(student => {
        // Only target active students who match the grade criteria
        if (targetGrade === 'ALL' || student.grade === targetGrade) {
            
            if (!student.ledger) student.ledger = [];
            
            // Generates an ID that viewLedger will instantly recognize based on prefix
            const transactionId = idPrefix + Date.now() + Math.random().toString(36).substr(2, 5);

            // Inject the new invoice into the student's personal ledger
            student.ledger.push({
                id: transactionId,
                date: dateStr,
                type: 'charge',
                amount: amount,
                category: detectedCategory, // Explicitly tag the category
                desc: desc,                 // JS Frontend key
                description: desc,          // 🛑 CRITICAL SUPABASE FIX: SQL Backend key
                term: targetTerm,
                breakdown: [{ desc: desc, amt: amount }] // Itemized for your receipt engine
            });

            // Update Master Balance Safely
            student.balanceOwing = (parseFloat(student.balanceOwing) || parseFloat(student.balance_owing) || 0) + amount;
            student.balance_owing = student.balanceOwing; 

            appliedCount++;
        }
    });

    // 7. Empty Target Validation
    if (appliedCount === 0) {
        return alert(`ℹ️ No students found in ${targetGrade}. No fees were applied.`);
    }

    // 8. Fire the Cloud Sync
    if (typeof window.saveData === 'function') {
        await window.saveData(); // Securely saves all modified students back to Supabase
    }

    // 9. Refresh the Visuals
    if (typeof window.updateDashboard === 'function') window.updateDashboard();
    if (typeof window.filterDirectory === 'function') window.filterDirectory();
    
    // Clear the form to prevent accidental double-clicks
    document.getElementById('topupDesc').value = '';
    document.getElementById('topupAmount').value = '';
    
    alert(`💥 BOOM! Magic happened.\n\nSuccessfully applied a $${amount.toFixed(2)} charge for "${desc}" to ${appliedCount} student(s) in ${targetGrade}.\n\nCategory applied: ${detectedCategory}`);
};
// ==========================================
// MASTER WATERFALL ALLOCATION ENGINE
// ==========================================
// Centralized logic used by both Walk-In logging and Auto-Reconciliation
window.executeWaterfallAllocation = function(student, amountToAllocate, referenceNumber, processedBy = 'Admin') {
    if (!student.ledger) student.ledger = [];
    
    // Check if this EcoCash transaction had a target event pinned to it
    const targetEvent = window.activePppsTx && window.activePppsTx.targetEvent ? window.activePppsTx.targetEvent : null;
    
    let remainingAmount = parseFloat(amountToAllocate);
    const originalPayment = remainingAmount;
    let breakdown = [];
    let autoCreatedCharge = null; // 🎯 Tracks if we had to build a bill
    
    breakdown.push(`Payment Received: $${originalPayment.toFixed(2)} (Ref: ${referenceNumber})`);
    if (targetEvent) breakdown.push(`🎯 Priority Target Override: ${targetEvent}`);
    breakdown.push(`-----------------------------------`);

    // 🎯 AUTO-GENERATE THE TRIP BILL IF IT DOESN'T EXIST YET
    if (targetEvent) {
        const targetDesc = `Event/Trip: ${targetEvent}`;
        let chargeExists = student.ledger.find(l => 
            (l.type === 'charge' || l.type === 'fee') && 
            (l.description || l.desc || '').toLowerCase().includes(targetEvent.toLowerCase()) && 
            l.status !== 'VOID'
        );

        if (!chargeExists) {
            // Find the original expected cost from announcements
            let expectedCost = parseFloat(originalPayment); // Fallback to what they paid
            if (window.settings && window.settings.announcements) {
                const ann = window.settings.announcements.find(a => a.title.toLowerCase() === targetEvent.toLowerCase());
                if (ann && ann.amount > 0) expectedCost = ann.amount;
            }

            const newChargeId = "CHG-AUTO-" + Date.now();
            autoCreatedCharge = {
                id: newChargeId,
                date: new Date().toISOString().split('T')[0],
                type: 'charge',
                amount: expectedCost,
                desc: targetDesc,
                description: targetDesc,
                status: 'ACTIVE',
                paid: 0,
                balance: expectedCost,
                term: '-'
            };
            student.ledger.push(autoCreatedCharge); // Push to local ledger instantly
            breakdown.push(`⚙️ System Auto-Created Bill: ${targetDesc} ($${expectedCost.toFixed(2)})`);
        }
    }

    let priorityOrder = [];
    if (window.schoolSettings && window.schoolSettings.feePriority) {
        priorityOrder = window.schoolSettings.feePriority;
    } else if (window.settings && window.settings.feePriority) {
        priorityOrder = window.settings.feePriority;
    } else {
        priorityOrder = ["TRANSPORT", "ARREARS", "PREVIOUS", "FOOD", "MEAL", "TUITION", "FEE", "ADMISSION"];
    }

    const getPriority = (item) => {
        if (!item) return 99;
        const desc = (item.description || item.desc || item.title || item.name || '').toUpperCase();
        if (desc.includes('TRANSPORT') || desc.includes('BUS')) return -1;
        for (let i = 0; i < priorityOrder.length; i++) {
            if (desc.includes(priorityOrder[i].toUpperCase())) return i;
        }
        return 99; 
    };

    // Include 'ACTIVE' and 'active' status check (Shop Bug Fix)
    let unpaidCharges = student.ledger.filter(l => 
        (l.type === 'charge' || l.type === 'fee') && 
        (l.status === 'unpaid' || l.status === 'partial' || l.status === 'ACTIVE' || l.status === 'active') && 
        parseFloat(l.balance !== undefined ? l.balance : (l.amount - (l.paid || 0))) > 0.01 
    );

    // Event Targeting Sort Override
    if (targetEvent) {
        const targetDesc = `Event/Trip: ${targetEvent}`.toLowerCase();
        unpaidCharges.sort((a, b) => {
            const aDesc = (a.description || a.desc || '').toLowerCase();
            const bDesc = (b.description || b.desc || '').toLowerCase();
            const aIsTarget = aDesc.includes(targetDesc) || aDesc.includes(targetEvent.toLowerCase());
            const bIsTarget = bDesc.includes(targetDesc) || bDesc.includes(targetEvent.toLowerCase());
            
            if (aIsTarget && !bIsTarget) return -1; // Force Target to absolute top
            if (!aIsTarget && bIsTarget) return 1;
            return getPriority(a) - getPriority(b);
        });
    } else {
        unpaidCharges.sort((a, b) => getPriority(a) - getPriority(b));
    }

    // Waterfall distribution logic
    unpaidCharges.forEach(charge => {
        if (remainingAmount <= 0) return;
        
        let owedOnCharge = parseFloat(charge.balance !== undefined ? charge.balance : (charge.amount - (charge.paid || 0)));
        let paymentAmount = 0;

        if (remainingAmount >= owedOnCharge) {
            paymentAmount = owedOnCharge;
            charge.status = 'paid';
            charge.balance = 0;
            charge.paid = (charge.paid || 0) + paymentAmount;
        } else {
            paymentAmount = remainingAmount;
            charge.status = 'partial';
            charge.balance = owedOnCharge - remainingAmount;
            charge.paid = (charge.paid || 0) + paymentAmount;
        }

        remainingAmount -= paymentAmount;
        const chargeName = charge.description || charge.desc || charge.title || 'General Fee';
        breakdown.push(`✅ Allocated to ${chargeName}: $${paymentAmount.toFixed(2)}`);
    });

    if (remainingAmount > 0) {
        breakdown.push(`💰 Unallocated Overpayment (Credit): $${remainingAmount.toFixed(2)}`);
    }

    const transactionId = "TXN-" + Date.now();
    student.ledger.push({
        id: transactionId,
        date: new Date().toISOString().split('T')[0],
        type: 'payment',
        description: targetEvent ? `EcoCash Payment (Ref: ${referenceNumber}) - ${targetEvent}` : `PPPS Auto-Allocation (Ref: ${referenceNumber})`,
        desc: targetEvent ? `EcoCash Payment (Ref: ${referenceNumber}) - ${targetEvent}` : `PPPS Auto-Allocation (Ref: ${referenceNumber})`,
        method: 'EcoCash',
        amount: originalPayment,
        zig: 0,
        status: 'cleared',
        reconciled: false,
        breakdown: breakdown,
        receiptNo: referenceNumber,
        receipt_no: referenceNumber,
        processed_by: processedBy
    });

    // Vault Math Corrector
    let trueBilled = 0, truePaid = 0;
    student.ledger.forEach(l => {
        if (l.status !== 'VOID' && l.status !== 'VOIDED') {
            if (l.type === 'charge' || l.type === 'fee') trueBilled += (parseFloat(l.amount) || 0);
            // 🛑 FIX: Include overpayment and credit in balance calculation
            if (l.type === 'payment' || l.type === 'waiver' || l.type === 'discount' || l.type === 'credit' || l.type === 'overpayment') truePaid += (parseFloat(l.amount) || 0);
        }
    });
    
    let trueBalanceOwing = Math.max(0, trueBilled - truePaid); 
    student.balanceOwing = trueBalanceOwing;
    student.balance = trueBalanceOwing; 
    student.balance_owing = trueBalanceOwing;

    if (trueBalanceOwing <= 0) student.enrollmentStatus = 'active';

    return {
        paymentBreakdown: breakdown,
        finalInvoiceText: breakdown.join('\n'),
        transactionId: transactionId,
        autoCreatedCharge: autoCreatedCharge // Passed to cloud sync
    };
};


