// 5. CORE APP UI NAVIGATION & INITIALIZATION
// ==========================================

// ==========================================
// 🚀 SMART NAVIGATION ENGINE (MASTER VERSION)
// ==========================================
window.renderSectionQuickLinks = function(section) {
    document.querySelectorAll('.section-quick-nav').forEach(nav => nav.remove());
    if (!section || ['dashboard', 'settings', 'finance'].includes(section.id)) return;

    const sectionHeader = section.querySelector(':scope > .section-header');
    if (!sectionHeader) return;

    const headings = Array.from(section.querySelectorAll('h2, h3, h4, .form-section-title')).filter(heading => {
        if (heading.closest('.modal, .modal-content, .settings-content, .fin-tab-content, [style*="display: none"]')) return false;
        const label = heading.textContent.trim();
        return label.length > 0 && !heading.matches('.section-header');
    });

    const uniqueHeadings = [];
    const seenLabels = new Set();
    headings.forEach(heading => {
        const label = heading.textContent.trim().replace(/\s+/g, ' ');
        const normalizedLabel = label.toLowerCase();
        if (seenLabels.has(normalizedLabel)) return;
        seenLabels.add(normalizedLabel);
        uniqueHeadings.push({ heading, label });
    });
    if (uniqueHeadings.length < 2) return;

    const quickNav = document.createElement('details');
    quickNav.className = 'section-quick-nav';
    const summary = document.createElement('summary');
    summary.textContent = 'Jump to a form or section';
    quickNav.appendChild(summary);

    const linkList = document.createElement('nav');
    linkList.className = 'section-quick-links';
    uniqueHeadings.forEach(({ heading, label }, index) => {
        if (!heading.id) heading.id = `${section.id}-jump-${index + 1}`;
        const link = document.createElement('button');
        link.type = 'button';
        link.className = 'section-quick-link';
        link.textContent = label;
        link.title = `Go to ${label}`;
        link.addEventListener('click', () => {
            heading.scrollIntoView({ behavior: 'smooth', block: 'start' });
            quickNav.open = false;
        });
        linkList.appendChild(link);
    });
    quickNav.appendChild(linkList);
    sectionHeader.insertAdjacentElement('afterend', quickNav);
};

// SMART NAVIGATION ENGINE (CRASH-FREE VERSION)
window.navTo = function(tabId) {
    const normalizedRole = window.getNormalizedRole(window.currentUser && window.currentUser.role);

    if (normalizedRole === 'Level 1' && !['dashboard', 'attendance', 'academics'].includes(tabId)) {
        alert('❌ Access denied: Teachers can only view Register, Attendance, and Academic Reports.');
        return;
    }

    if (normalizedRole === 'Level 2') {
        if (['payroll', 'teachers'].includes(tabId)) {
            alert('❌ Access denied: Cashier/Admin level 2 cannot access salaries or Teacher & Allocation.');
            return;
        }
    }

    // 1. Find all pages (sections) and hide them completely
    const allSections = document.querySelectorAll('.main-content .section');
    allSections.forEach(sec => {
        sec.style.display = 'none';
        sec.classList.remove('active');
    });

    // 2. Find the exact page you clicked and show it
    const targetPage = document.getElementById(tabId);
    if (targetPage) {
        targetPage.style.display = 'block';
        targetPage.classList.add('active');
        window.renderSectionQuickLinks(targetPage);
        if (!['dashboard', 'visitLog'].includes(tabId) && typeof window.recordVisit === 'function') {
            const name = window.currentUser?.user || window.currentUser?.username || 'Unknown';
            const role = window.currentUser?.role || 'Unknown';
            window.recordVisit(name, role, 'Page View', tabId);
        }
    }

    // 3. Highlight the correct button on the sidebar
    const navButtons = document.querySelectorAll('.sidebar .nav-btn');
    navButtons.forEach(btn => btn.classList.remove('active'));
    
    const activeBtn = Array.from(navButtons).find(b => b.getAttribute('onclick') && b.getAttribute('onclick').includes(tabId));
    if (activeBtn) {
        activeBtn.classList.add('active');
    }

    if (!window.appDataReady) {
        window.pendingAppNavigation = tabId;
        console.info(`Navigation to ${tabId} selected; section controls remain locked until cloud verification finishes.`);
        return;
    }

    if (normalizedRole === 'Level 2' && tabId === 'settings') {
        setTimeout(() => window.openSetTab('setTabFees'), 50);
    }
    if (normalizedRole === 'Level 2' && tabId === 'finance') {
        // 🛡️ No access to Cash Reconciliation — land on a neutral finance tab instead
        setTimeout(() => { if (typeof window.openFinTab === 'function') window.openFinTab('finTabExpense'); }, 50);
    }

    // Auto-open School Settings tab so it doesn't show a blank page
    if (tabId === 'settings' && typeof window.openSetTab === 'function') {
        window.openSetTab('setTabSchool');
    }
    
    // Legacy support for older permissions 
    if (typeof window.applyPermissions === 'function') {
        window.applyPermissions(); 
    }

    // 4. Data Refreshes for specific tabs
    if (tabId === 'enrollment' && typeof filterDirectory === 'function') filterDirectory();
    if (tabId === 'dashboard' && typeof updateDashboard === 'function') updateDashboard();
    if (tabId === 'shop' && typeof renderInventory === 'function') renderInventory();
    if (tabId === 'stores' && typeof window.loadStoreData === 'function') window.loadStoreData();
    if (tabId === 'groceries' && typeof window.loadGroceryData === 'function') window.loadGroceryData();
    if (tabId === 'stationery' && typeof window.loadStationeryData === 'function') window.loadStationeryData();
    if (tabId === 'attendance' && typeof initAttendanceTab === 'function') initAttendanceTab(); 
    
    // 🎯 UPGRADED PAYROLL TRIGGER: Updates the dropdowns AND loads history instantly
    if (tabId === 'payroll') {
        if (typeof window.updatePayrollDropdown === 'function') {
            window.updatePayrollDropdown();
        }
        if (typeof renderPayrollHistory === 'function') {
            renderPayrollHistory();
        }
    }
};

window.closeModal = function(id) { 
    const m = document.getElementById(id);
    if(m) m.style.display = 'none'; 
};

window.updateDashboard = function() {
    const dashTotal = document.getElementById('dashTotalStudents');
    if(dashTotal) dashTotal.innerText = window.students.length;

    // 👋 Personalized greeting + avatar
    const greetingEl = document.getElementById('dashWelcomeMsg');
    if (greetingEl) {
        const hour = new Date().getHours();
        const timeGreeting = hour < 12 ? "Good morning" : hour < 17 ? "Good afternoon" : "Good evening";
        const displayName = (window.currentUser && (window.currentUser.name || window.currentUser.user)) || "there";
        greetingEl.innerText = `${timeGreeting}, ${displayName}! 👋`;
    }
    const avatarEl = document.getElementById('dashWelcomeAvatar');
    if (avatarEl) {
        const displayName = (window.currentUser && (window.currentUser.name || window.currentUser.user)) || "";
        avatarEl.innerText = displayName ? displayName.trim().charAt(0).toUpperCase() : "👋";
    }

    // 📱 Pending EcoCash Funds (unclaimed references awaiting verification)
    const pendingEcoEl = document.getElementById('dashPendingEco');
    if (pendingEcoEl) {
        window.ecoCashTransactions = window.ecoCashTransactions || [];
        const pendingCount = window.ecoCashTransactions.filter(t => t.status !== 'claimed').length;
        pendingEcoEl.innerText = pendingCount;
    }

    // 🌐 Real system/network status instead of a hardcoded label
    const statusEl = document.getElementById('dashSystemStatus');
    if (statusEl) {
        if (navigator.onLine) {
            statusEl.innerText = "Online & Synced";
            statusEl.style.color = "#10b981";
        } else {
            statusEl.innerText = "Offline";
            statusEl.style.color = "#e74c3c";
        }
    }
    
    let tBilled = 0, tPaid = 0;
    window.students.forEach(s => {
        // Locate this block in window.updateDashboard and add the return line
if(s.ledger && Array.isArray(s.ledger)) {
    s.ledger.forEach(l => {
        if (l.status === 'VOID' || l.status === 'VOIDED') return; // 🎯 ADD THIS FIX
        
        if(l.type === 'payment') tPaid += (parseFloat(l.amount) || 0);
        if(l.type === 'charge') tBilled += (parseFloat(l.amount) || 0);
    });
}
    });
    
    const left = tBilled - tPaid;
    
    if(document.getElementById('statTotalSt')) document.getElementById('statTotalSt').innerText = window.students.length;
    if(document.getElementById('statExpected')) document.getElementById('statExpected').innerText = tBilled.toFixed(2);
    if(document.getElementById('statCollected')) document.getElementById('statCollected').innerText = tPaid.toFixed(2);
    if(document.getElementById('statLeft')) document.getElementById('statLeft').innerText = left > 0 ? left.toFixed(2) : "0.00";
    if (typeof renderPendingReferences === 'function') renderPendingReferences();
};

