// 7. ULTIMATE STUDENT REGISTRATION ENGINE
// ==========================================
// 7. ULTIMATE STUDENT REGISTRATION ENGINE
// ==========================================
window.registerStudent = async function(event) {
    if (event) event.preventDefault();
            
    // 1. GATHER FORM DATA & HTML ELEMENTS
    const sNameBox = document.getElementById('stName') || document.getElementById('regName') || document.getElementById('name');
    const sIdBox = document.getElementById('stId') || document.getElementById('regId');
    const gradeBox = document.getElementById('regGrade') || document.getElementById('grade');
    const genderBox = document.getElementById('regGender') || document.getElementById('gender');
    const phoneBox = document.getElementById('regCell') || document.getElementById('regPhone') || document.getElementById('stPhone');
    const addressBox = document.getElementById('regAddress') || document.getElementById('stAddress');
    const dobBox = document.getElementById('regDOB') || document.getElementById('regDob') || document.getElementById('stDob');
    const planBox = document.getElementById('regBillingPlan'); 
    const admissionCheckbox = document.getElementById('regChargeAdmission');
    const termValue = document.getElementById('regTermBilling')?.value || "Unknown Term";

    const transportBox = document.getElementById('regTransport');
    const driverBox = document.getElementById('regDriver'); 
    const foodBox = document.getElementById('regFood');
    const stationeryBox = document.getElementById('regStationery');
    const textbooksBox = document.getElementById('regTextbooks'); 

    const sName = sNameBox ? sNameBox.value.trim() : '';
    const selectedGrade = gradeBox ? gradeBox.value : '';
    const studentPlan = planBox ? planBox.value : 'termly';
    const selectedTransportMode = transportBox?.selectedOptions?.[0]?.dataset.mode || document.getElementById('regTransportMode')?.value || 'full';
    const selectedDriver = driverBox ? driverBox.value : ''; 

    const todayStr = new Date().toISOString().split('T')[0];

    let sId = sIdBox ? sIdBox.value.trim() : null;
    if (!sId || sId === "") {
        sId = null;
        if (sIdBox) sIdBox.value = '';
    }

    if (!sName || !selectedGrade) return alert("⚠️ Please enter a name and select a grade/class.");
    if (!termValue || termValue === "Unknown Term") return alert("⚠️ Please select a valid billing term before proceeding.");

    const confirmTerm = confirm(`📅 You are about to enroll this student and generate invoices for:\n\n👉 "${termValue}"\n\nIs this the correct term and year? Click OK to proceed or Cancel to change it.`);
    if (!confirmTerm) return; 

    // SMART SIMILARITY CHECK
    if (!window.students) window.students = [];
    const cleanNewName = sName.toLowerCase().replace(/\s+/g, ' ').trim();
    const newNameParts = cleanNewName.split(' ');
    const similarStudent = window.students.find(s => {
        const existingName = (s.name || '').toLowerCase().replace(/\s+/g, ' ').trim();
        if (existingName === cleanNewName) return true; 
        
        const existingParts = existingName.split(' ');
        const matchingParts = newNameParts.filter(part => existingParts.includes(part));
        return matchingParts.length >= 2 && newNameParts.length > 1;
    });

    if (similarStudent) {
        const proceed = confirm(`⚠️ POTENTIAL DUPLICATE DETECTED\n\nA student named "${similarStudent.name}" (ID: ${similarStudent.id}) has a very similar name to "${sName}".\n\nDo you still want to proceed with this registration?`);
        if (!proceed) return; 
    }

    let admissionAlreadyHandled = false;
    
    // 👇 RENAMED TO AVOID CONFUSION: This strictly tracks the FULL BILL being charged to the account
    let totalCharges = 0; 
    const ledgerEntries = [];

    if (studentPlan === 'exempt') {
        console.log("🛡️ Student is Fully Exempt. Skipping all ledger charges.");
        admissionAlreadyHandled = true; 
    } else {
        // Find Grade Fees
        let gradeFees = [];
        if (Array.isArray(window.feeStructures)) {
            const struct = window.feeStructures.find(f => (f.id === selectedGrade || f.grade === selectedGrade));
            gradeFees = struct ? (struct.fees || struct.items || struct) : [];
        }

        gradeFees.forEach(f => {
            let feeName = f.name || f.desc || 'Fee';
            let feeAmount = parseFloat(f.amount) || 0;
            const isWaived = window.waivedEnrollmentFees && window.waivedEnrollmentFees.includes(feeName);
            
            if (feeAmount > 0 && !isWaived) {
                const isAdmission = feeName.toLowerCase().includes('admission') || feeName.toLowerCase().includes('enroll');
                
                if (isAdmission) {
                    admissionAlreadyHandled = true;
                    if (admissionCheckbox && !admissionCheckbox.checked) return; 
                    feeName = "Admission Fee"; 
                } else {
                    let isTuition = feeName.toLowerCase().includes('term') || feeName.toLowerCase().includes('tuition');
                    if (!isTuition && feeName.toLowerCase() === 'fee') isTuition = true; 

                    if (isTuition) feeName = `Tuition Fee (${feeName.replace('Tuition Fee (', '').replace(')', '')})`; 
                    
                    if (studentPlan === 'monthly' && isTuition) {
                        const monthName = new Date().toLocaleString('default', { month: 'long' });
                        const currentYear = new Date().getFullYear();
                        feeAmount = parseFloat((feeAmount / 3).toFixed(2));
                        feeName += ` - ${monthName} ${currentYear} (Monthly Billing)`;
                    } else if (studentPlan === 'monthly') {
                        feeName += ' (On Monthly Plan)'; 
                    }
                }

                const actualFeeName = feeName.includes(termValue) ? feeName : `${feeName} (${termValue})`;

                ledgerEntries.push({
                    id: "CHG-" + Date.now() + Math.random().toString(36).substr(2, 5),
                    student_id: sId,
                    date: todayStr,
                    type: 'charge',
                    amount: feeAmount,
                    description: actualFeeName, 
                    term: termValue,
                    status: 'ACTIVE'
                });
                totalCharges += feeAmount; // 👈 ADDING TO THE FULL BILL
            }
        }); 

        // Optional Services
        const currentDate = new Date();
        const enrollmentMonth = `${currentDate.toLocaleString('default', { month: 'long' })} ${currentDate.getFullYear()}`;
        const enrollmentYear = currentDate.getFullYear();

        const safeSettings = window.settings || {};
        const foodBase = parseFloat(safeSettings.foodFee) || 0;
        const textBase = parseFloat(safeSettings.textbookFeeGrade) || 0; // Fixed variable name
        const isECD = String(selectedGrade).toLowerCase().includes('ecd');
        const statBase = isECD ? (parseFloat(safeSettings.stationeryFeeECD) || 0) : (parseFloat(safeSettings.stationeryFeeGrades) || 0);
        
        const transportVal = transportBox ? parseFloat(transportBox.value) : 0;
        const foodSelected = foodBox ? (foodBox.value === 'true') : false;
        const statSelected = stationeryBox ? (stationeryBox.value === 'true') : false;
        const textSelected = textbooksBox ? (textbooksBox.value === 'true') : false;

        const addServiceCharge = (desc, amount, termTag) => {
            if (amount > 0 && !(window.waivedEnrollmentFees && window.waivedEnrollmentFees.includes(desc))) {
                ledgerEntries.push({ 
                    id: "CHG-SRV-" + Date.now() + Math.random().toString(36).substr(2, 5),
                    student_id: sId,
                    date: todayStr, 
                    type: 'charge', 
                    amount: amount, 
                    description: desc, 
                    term: termTag,
                    status: 'ACTIVE'
                });
                totalCharges += amount; // 👈 ADDING TO THE FULL BILL
            }
        };

        addServiceCharge(`Transport Service (${selectedTransportMode === 'one_way' ? 'One-Way' : 'Full Route'}) - ${enrollmentMonth}`, transportVal, enrollmentMonth);
        if (foodSelected) addServiceCharge(`Food Program - ${enrollmentMonth}`, foodBase, enrollmentMonth);
        if (statSelected) addServiceCharge(`Stationery Pack - ${enrollmentYear}`, statBase, enrollmentYear.toString());
        if (textSelected) addServiceCharge(`Textbook Fee - ${enrollmentYear}`, textBase, enrollmentYear.toString());
        
        // Global Admission Fallback
        const applyGlobal = admissionCheckbox ? admissionCheckbox.checked : true;
        if (!admissionAlreadyHandled && applyGlobal) {
            let globalAdm = isECD 
                ? (parseFloat(safeSettings.admissionFeeECD) || parseFloat(safeSettings.admissionFee) || 0) 
                : (parseFloat(safeSettings.admissionFeeGrades) || parseFloat(safeSettings.admissionFee) || 0);

            if (globalAdm > 0) {
                ledgerEntries.push({ 
                    id: "ADM-" + Date.now(), 
                    student_id: sId,
                    date: todayStr, 
                    type: 'charge', 
                    amount: globalAdm, 
                    description: "Admission / Enrollment Fee", 
                    term: "Once-Off",
                    status: 'ACTIVE'
                });
                totalCharges += globalAdm; // 👈 ADDING TO THE FULL BILL
            }
        }
    } 

    // 3. BUILD RELATIONAL STUDENT OBJECT
    const newStudent = {
        ...(sId && { id: sId }), 
        name: sName,
        grade: selectedGrade,
        gender: genderBox ? genderBox.value : '',
        phone: phoneBox ? phoneBox.value.trim() : '',
        address: addressBox ? addressBox.value.trim() : '',
        dob: dobBox ? dobBox.value : '',
        enroll_date: todayStr,
        billing_plan: studentPlan,
        balance_owing: totalCharges, // 👈 SAVING THE FULL BILL TO THE DATABASE
        enrollment_status: (totalCharges <= 0) ? 'active' : 'pending_payment',
        transport_tier: transportBox ? parseFloat(transportBox.value) : 0,
        transport_mode: selectedTransportMode,
        driver: selectedDriver, 
        food_program: foodBox ? (foodBox.value === 'true') : false,
        stationery_pack: stationeryBox ? (stationeryBox.value === 'true') : false,
        textbooks: textbooksBox ? (textbooksBox.value === 'true') : false,
    };

    // 4. CLOUD SYNC & VAULT COMMIT
    try {
        if (!window.supabaseClient) throw new Error("Database client not found. Are you offline?");

        const { data: savedStudent, error: stuError } = await window.supabaseClient
            .from('students')
            .insert([newStudent]) 
            .select()            
            .single();            

        if (stuError) throw stuError;

        const finalStudentId = savedStudent.id; 

        if (ledgerEntries.length > 0) {
            ledgerEntries.forEach(entry => { entry.student_id = finalStudentId; });
            const { error: ledgerError } = await window.supabaseClient
                .from('student_ledger')
                .insert(ledgerEntries);
            if (ledgerError) throw ledgerError;
        }

        // 5. LOCAL SAVE & UI RESET
        newStudent.id = finalStudentId;
        newStudent.ledger = ledgerEntries; 
        
        window.students.push(newStudent);
        
        if (typeof window.saveData === 'function') window.saveData();
        if (typeof window.filterDirectory === 'function') window.filterDirectory();
        if (typeof window.updateDashboard === 'function') window.updateDashboard();
        if (typeof window.populateStudentDatalist === 'function') window.populateStudentDatalist();
        if (typeof window.fetchStudents === 'function') window.fetchStudents(); 

        // --- 👇 NEW LOGIC: Capture the parent's actual physical deposit before clearing the form ---
        const initialPaymentBox = document.getElementById('regInitialPayment');
        const parentDepositAmount = initialPaymentBox ? parseFloat(initialPaymentBox.value) : 0;

        if (parentDepositAmount > 0) {
            alert(`✅ ${newStudent.name} enrolled!\n\nTotal Bill: $${totalCharges.toFixed(2)}\n\nRedirecting to process their $${parentDepositAmount.toFixed(2)} deposit...`);
        } else {
            alert(`✅ ${newStudent.name} enrolled!\n\nTotal Bill: $${totalCharges.toFixed(2)}`);
        }

        // Reset the form fields
        if (transportBox) transportBox.value = "0";
        if (driverBox) driverBox.value = ""; 
        if (foodBox) foodBox.value = "false";
        if (stationeryBox) stationeryBox.value = "false";
        
        if (typeof window.clearEnrollmentForm === 'function') window.clearEnrollmentForm();

        if (initialPaymentBox) initialPaymentBox.value = '';
        if (admissionCheckbox) admissionCheckbox.checked = false;

        const allFields = [sNameBox, sIdBox, gradeBox, genderBox, phoneBox, addressBox, dobBox];
        allFields.forEach(field => { if (field) field.value = ''; });

        // --- 👇 NEW LOGIC: Pass the deposit to the Finance Tab for Admin processing ---
        if (parentDepositAmount > 0) {
            const payIdInput = document.getElementById('payId');
            const payUsdInput = document.getElementById('payUsd');

            if (payIdInput) payIdInput.value = finalStudentId;
            if (payUsdInput) payUsdInput.value = parentDepositAmount;

            if (typeof window.previewStudentBalance === 'function') window.previewStudentBalance();

            const financeTabBtn = document.getElementById('tab-finance') || document.querySelector('[onclick*="showTab(\'finance\')"]');
            if (financeTabBtn) financeTabBtn.click();
        }

    } catch (error) {
        console.error("Registration/Database Sync Failed:", error);
        alert(`❌ Enrollment failed to save to the database. Error: ${error.message || "Network issue."}`);
    } 
};

