window.openEditModal = function(id) {
    if (!window.currentUser) return;
    const role = window.currentUser.role || "";
    const isAdmin = role.includes('Level 2') || role.includes('Level 3') || role === 'Admin' || role === 'Chief Admin';
    
    if (!isAdmin) {
        alert("❌ Access Denied: Only Admins can edit student profiles.");
        return; 
    }

    const s = (window.students || []).find(st => String(st.id) === String(id));
    if (!s) {
        alert("Student record could not be located.");
        return;
    }

    const gradeSelect = document.getElementById('editGrade');
    if (gradeSelect && window.officialClasses) {
        gradeSelect.innerHTML = ''; 
        window.officialClasses.forEach(c => {
            const isSelected = (String(s.grade) === String(c.level)) ? 'selected' : '';
            gradeSelect.innerHTML += `<option value="${c.level}" ${isSelected}>${c.level}</option>`;
        });
    }

    const setFieldVal = (elementId, val) => {
        const el = document.getElementById(elementId);
        if (!el) return;
        if (el.type === 'checkbox') {
            el.checked = val === true || String(val).toLowerCase() === 'true';
        } else {
            el.value = val !== undefined && val !== null ? val : '';
        }
    };

    setFieldVal('editStuId', s.id);
    setFieldVal('editStudentId', s.id); 
    setFieldVal('editName', s.name);
    setFieldVal('editCell', s.phone);
    setFieldVal('editPhone', s.phone); 
    setFieldVal('editDOB', s.dob);
    setFieldVal('editDob', s.dob);
    setFieldVal('editEnroll', s.enrollDate);
    setFieldVal('editGender', s.gender || 'Male');
    setFieldVal('editAddress', s.address);
    setFieldVal('editEmail', s.email);
    setFieldVal('editGuardianName', s.guardian_name || s.guardianName);
    setFieldVal('editStatus', s.enrollmentStatus || s.enrollment_status || 'active');

    setFieldVal('editBillingPlan', s.billing_plan || s.billingPlan || 'termly');
    if (typeof window.populateEditTransportDropdown === 'function') {
        window.populateEditTransportDropdown(s.transport_tier !== undefined ? s.transport_tier : (s.transportTier || 0), s.transport_mode || s.transportMode || 'full');
    }
    setFieldVal('editTransport', s.transport_tier !== undefined ? s.transport_tier : (s.transportTier || 0));
    setFieldVal('editTransportTier', s.transport_tier !== undefined ? s.transport_tier : (s.transportTier || 0));
    setFieldVal('editTransportMode', s.transport_mode || s.transportMode || 'full');
    // 👇 UPGRADED: BULLETPROOF DRIVER MODAL MAPPING 👇
const driverEl = document.getElementById('editDriver');
if (driverEl) {
    const dbDriver = String(s.driver || '').trim().toLowerCase();
    let foundMatch = false;
    for (let i = 0; i < driverEl.options.length; i++) {
        if (driverEl.options[i].value.toLowerCase().trim() === dbDriver) {
            driverEl.selectedIndex = i;
            foundMatch = true;
            break;
        }
    }
    if (!foundMatch) driverEl.value = ""; // Default to blank if no match
}
    setFieldVal('editFood', s.food_program !== undefined ? s.food_program : (s.foodProgram || false));
    setFieldVal('editFoodProgram', s.food_program !== undefined ? s.food_program : (s.foodProgram || false));
    setFieldVal('editStationery', s.stationery_pack !== undefined ? s.stationery_pack : (s.stationeryPack || false));
    setFieldVal('editStationeryPack', s.stationery_pack !== undefined ? s.stationery_pack : (s.stationeryPack || false));
    setFieldVal('editTextbooks', s.textbooks || false); 

    const editModal = document.getElementById('editModal') || document.getElementById('editStudentModal');
    if (editModal) {
        editModal.style.display = 'flex';
        setTimeout(() => {
            const nameInput = document.getElementById('editName');
            if (nameInput) nameInput.focus();
        }, 100);
    } else {
        console.warn("⚠️ Edit modal DOM element ('editModal') not found in HTML.");
    }
};

// ==========================================
// DIRECTORY FILTER ENGINE
// ==========================================
window.currentFilteredStudents = [];
window.filterDirectoryCore = function() {
    const searchInput = document.getElementById('filterSearch');
    const gradeInput = document.getElementById('filterGrade');
    const periodInput = document.getElementById('filterPeriod'); 
    const driverInput = document.getElementById('filterDriver'); // 👇 DRIVER INPUT
    const feeInput = document.getElementById('filterFees');
    const serviceInput = document.getElementById('filterService');
    
    if (!window.students) return; 

    const search = searchInput ? searchInput.value.toLowerCase() : "";
    const grade = gradeInput ? gradeInput.value : "ALL";
    const period = periodInput ? periodInput.value.toLowerCase().trim() : ""; 
    const driverStat = driverInput ? driverInput.value : "ALL"; // 👇 DRIVER STATUS
    const feeStat = feeInput ? feeInput.value : "ALL";
    const serviceStat = serviceInput ? serviceInput.value : "ALL";

    const filtered = window.students.filter(s => {
        const studentName = (s.name || "").toLowerCase();
        const studentId = (s.id || "").toLowerCase();
        
        const mSearch = studentName.includes(search) || studentId.includes(search);
        const mGrade = grade === "ALL" || s.grade === grade;
        
        // 👇 DRIVER FILTER MATCH 👇
        const mDriver = driverStat === "ALL" || (s.driver && String(s.driver).trim().toLowerCase() === String(driverStat).trim().toLowerCase());
        
        let mPeriod = true;
        if (period !== "") {
            const searchWords = period.split(' ').filter(word => word.trim() !== '');
            const hasMatchingCharge = s.ledger && s.ledger.some(l => {
                const combinedData = `${l.term || ''} ${l.date || ''} ${l.description || ''}`.toLowerCase();
                return searchWords.every(word => combinedData.includes(word));
            });
            const hasMatchingEnrollDate = s.enrollDate && searchWords.every(word => s.enrollDate.includes(word));
            mPeriod = hasMatchingCharge || hasMatchingEnrollDate;
        }
        
        let tBilled = 0, tPaid = 0; 
        let pureTuitionBilled = 0, pureTuitionPaid = 0; 
        let eBilled = 0, ePaid = 0; 
        let sBilled = 0, sPaid = 0; 
        
        const isService = (desc) => {
            const d = desc.toLowerCase();
            return d.includes('transport') || d.includes('bus') || d.includes('food') || d.includes('stationery') || d.includes('textbook');
        };
        
        let transportBilled = 0, transportPaid = 0;
        let foodBilled = 0, foodPaid = 0;
        let stationeryBilled = 0, stationeryPaid = 0;
        let textbookBilled = 0, textbookPaid = 0;

        let billedForTransportThisMonth = false;
        const currentMonth = new Date().getMonth();
        const currentYear = new Date().getFullYear();

        const cleanDesc = (d) => (d || "").toLowerCase();
        const isEvt = (d, r, id) => d.includes('event') || d.includes('trip') || r.startsWith('evt') || String(id).toLowerCase().includes('evt');
        const isShp = (d, r, id) => d.includes('shop') || d.includes('uniform') || r.startsWith('rcpt') || String(id).toLowerCase().includes('rcpt');

        if(s.ledger && Array.isArray(s.ledger)) {
            s.ledger.forEach(l => {
                if (l.status === 'VOID' || l.status === 'VOIDED') return; 
                
                const amount = parseFloat(l.amount) || 0;
                const d = cleanDesc(l.description || l.desc || l.notes || l.category || l.item);
                const r = cleanDesc(l.receiptNo || l.receipt_no);
                const m = cleanDesc(l.method); 
                const id = l.id || "";

                if (d.includes('credit allocation (reversal)')) return;

                const isCreditPayment = l.is_credit_backed === true || m.includes('advance credit') || d.includes('paid via advance credit');

                if (l.type === 'charge' || l.type === 'fee') {
                   if (isShp(d, r, id)) sBilled += amount;
                    else if (isEvt(d, r, id)) eBilled += amount;
                    else {
                        tBilled += amount;
                        if (!isService(d)) pureTuitionBilled += amount; 
                    }

                    if (d.includes('transport') || d.includes('bus')) {
                        transportBilled += amount;
                        if (l.date) {
                            const chargeDate = new Date(l.date);
                            if (chargeDate.getMonth() === currentMonth && chargeDate.getFullYear() === currentYear) {
                                billedForTransportThisMonth = true;
                            }
                        }
                    }
                    if (d.includes('food')) foodBilled += amount;
                    if (d.includes('stationery')) stationeryBilled += amount;
                    if (d.includes('textbook')) textbookBilled += amount;
                } 
                else if(l.type === 'payment' || l.type === 'discount' || l.type === 'waiver' || l.type === 'credit' || l.type === 'overpayment') {
                    
                    if (isCreditPayment) return; 
                    
                    if (l.breakdown && Array.isArray(l.breakdown) && l.breakdown.length > 0) {
                        l.breakdown.forEach(b => {
                            const bAmount = parseFloat(b.amount || b.amt) || 0; 
                            const bd = cleanDesc(b.desc || b.description);
                            
                           if (isShp(bd, "", "")) sPaid += bAmount;
                            else if (isEvt(bd, "", "")) ePaid += bAmount;
                            else {
                                tPaid += bAmount;
                                if (!isService(bd)) pureTuitionPaid += bAmount; 
                            }

                            if (bd.includes('transport') || bd.includes('bus')) transportPaid += bAmount;
                            if (bd.includes('food')) foodPaid += bAmount;
                            if (bd.includes('stationery')) stationeryPaid += bAmount;
                            if (bd.includes('textbook')) textbookPaid += bAmount;
                        });
                    } 
                    else {
                       if (isShp(d, r, id)) sPaid += amount;
                        else if (isEvt(d, r, id)) ePaid += amount;
                        else {
                            tPaid += amount;
                            if (!isService(d)) pureTuitionPaid += amount;
                        }

                        if (d.includes('transport') || d.includes('bus')) transportPaid += amount;
                        if (d.includes('food')) foodPaid += amount;
                        if (d.includes('stationery')) stationeryPaid += amount;
                        if (d.includes('textbook')) textbookPaid += amount;
                    }
                }
            }); 
        } 
        
        const tOwe = tBilled - tPaid;
        const pureTuitionOwe = pureTuitionBilled - pureTuitionPaid; 
        const eOwe = eBilled - ePaid;
        const sOwe = sBilled - sPaid;
        let overallOwe = tOwe + eOwe + sOwe;

        let mFee = true;
        
        s._tempDebt = overallOwe; 
        if (feeStat === "OVERALL_OWING") mFee = overallOwe > 0.01;
        else if (feeStat === "TUITION_OWING") mFee = pureTuitionOwe > 0.01; 
        else if (feeStat === "TUITION_PAID") mFee = pureTuitionOwe <= 0.01 && pureTuitionOwe >= -0.01; 
        else if (feeStat === "TUITION_OVERPAID") mFee = pureTuitionOwe < -0.01; 
        
        else if (feeStat === "EVENT_BILLED") mFee = eBilled > 0;
        else if (feeStat === "EVENT_OWING") mFee = eBilled > 0 && eOwe > 0.01;
        else if (feeStat === "EVENT_PAID") mFee = eBilled > 0 && eOwe <= 0.01 && eOwe >= -0.01;
        
        else if (feeStat === "SHOP_BILLED") mFee = sBilled > 0;
        else if (feeStat === "SHOP_OWING") mFee = sBilled > 0 && sOwe > 0.01;
        else if (feeStat === "SHOP_PAID") mFee = sBilled > 0 && sOwe <= 0.01 && sOwe >= -0.01;
        
        else if (feeStat === "OWING") mFee = overallOwe > 0.01;
        else if (feeStat === "PAID") mFee = overallOwe <= 0.01 && overallOwe >= -0.01;
        else if (feeStat === "OVERALL_OVERPAID") mFee = overallOwe < -0.01;

        const transportOwe = transportBilled - transportPaid;
        const foodOwe = foodBilled - foodPaid;
        const stationeryOwe = stationeryBilled - stationeryPaid;
        const textbookOwe = textbookBilled - textbookPaid;

        const transportVal = parseFloat(s.transportTier) || parseFloat(s.transport_tier) || 0;
        const isCurrentlyUsingTransport = transportVal > 0 || billedForTransportThisMonth;
        
        const isCurrentlyUsingFood = String(s.foodProgram) === 'true' || String(s.food_program) === 'true' || s.foodProgram === true || s.food_program === true;
        const isCurrentlyUsingStationery = String(s.stationeryPack) === 'true' || String(s.stationery_pack) === 'true' || s.stationeryPack === true || s.stationery_pack === true;
        const isCurrentlyUsingTextbooks = String(s.textbooks) === 'true' || s.textbooks === true;
        
        let mService = true;
        
        if (serviceStat === "USE_TRANSPORT") mService = isCurrentlyUsingTransport; 
        if (serviceStat === "NO_TRANSPORT") mService = !isCurrentlyUsingTransport;
        if (serviceStat === "PAID_TRANSPORT") mService = isCurrentlyUsingTransport && (transportOwe <= 0.01);
        if (serviceStat === "UNPAID_TRANSPORT") mService = transportOwe > 0.01; 
        
        if (serviceStat === "USE_FOOD") mService = isCurrentlyUsingFood;
        if (serviceStat === "PAID_FOOD") mService = isCurrentlyUsingFood && (foodOwe <= 0.01);
        if (serviceStat === "UNPAID_FOOD") mService = foodOwe > 0.01;
        
        if (serviceStat === "USE_STATIONERY") mService = isCurrentlyUsingStationery;
        if (serviceStat === "NO_STATIONERY") mService = !isCurrentlyUsingStationery;
        if (serviceStat === "PAID_STATIONERY") mService = isCurrentlyUsingStationery && (stationeryOwe <= 0.01);
        if (serviceStat === "UNPAID_STATIONERY") mService = stationeryOwe > 0.01;
        
        const isGrade1 = String(s.grade).toLowerCase().includes("grade 1");
        if (serviceStat === "GRADE1_TEXTBOOKS_PAID") mService = isGrade1 && textbookBilled > 0 && (textbookOwe <= 0.01);
        if (serviceStat === "GRADE1_TEXTBOOKS_UNPAID") mService = isGrade1 && (textbookOwe > 0.01);
        
        // 👇 CRITICAL FIX: ENSURE mDriver IS RETURNED 👇
        return mSearch && mGrade && mPeriod && mFee && mService && mDriver;
    });

    filtered.sort((a, b) => {
        if (feeStat === "OVERALL_OWING") {
            const debtA = parseFloat(a._tempDebt) || 0;
            const debtB = parseFloat(b._tempDebt) || 0;
            return debtB - debtA; 
        } 
        
        const numA = parseInt(String(a.id).replace(/\D/g, '')) || 0;
        const numB = parseInt(String(b.id).replace(/\D/g, '')) || 0;
        return numA - numB; 
    });

    window.currentFilteredStudents = filtered; 
    
    const countDisplay = document.getElementById('filterStudentCount');
    if (countDisplay) {
        countDisplay.innerText = `Showing ${filtered.length} student(s)`;
    }

    if(typeof renderTable === 'function') {
        window.renderTable(filtered);
    }
};

window.directoryPage = 1;
window.directoryPageSize = 50;
window.filterDirectory = function(force = false) {
    if (window.directoryFilterTimer) clearTimeout(window.directoryFilterTimer);
    const execute = () => {
        window.directoryPage = 1;
        if (typeof window.filterDirectoryCore === 'function') window.filterDirectoryCore();
    };
    if (force === true) execute();
    else window.directoryFilterTimer = setTimeout(execute, 120);
};

// Ensure both button calls route to the same master function
window.saveStudent = window.registerStudent;
// ==========================================
// 8. CORE LEDGER HELPER
// ==========================================

window.addChargeToLedger = function(studentId, amount, description, term) {
    let student = window.students.find(s => s.id === studentId);
    if (student) {
        if (!student.ledger) student.ledger = [];
        
        const newInvoice = {
            id: "INV-" + Date.now(),
            date: new Date().toISOString().split('T')[0], 
            desc: description, 
            term: term || "General",                
            type: "charge",            
            amount: parseFloat(amount) || 0
        };

        student.ledger.push(newInvoice);
        student.balanceOwing = (parseFloat(student.balanceOwing) || 0) + parseFloat(amount);
        
        if (typeof window.saveData === 'function') window.saveData();
    }
};

