window.populateEditTransportDropdown = function(selectedTier, selectedMode) {
    const editTransportSelect = document.getElementById('editTransport') || document.getElementById('editTransportTier');
    const editModeSelect = document.getElementById('editTransportMode');
    
    if (!editTransportSelect) return;

    // 1. Determine which mode is currently active
    // If the user just clicked the dropdown, use that value. Otherwise, use what was loaded from the database.
    const currentMode = (editModeSelect && editModeSelect.value) ? editModeSelect.value : (selectedMode || 'full');

    // 2. Build the dropdown options
    let html = '<option value="0">None ($0)</option>';
    const zones = ['A', 'B', 'C', 'D', 'E', 'F'];
    
    zones.forEach((zone, index) => {
        const tierValue = index + 1; // Maps A=1, B=2, C=3
        
        // Fetch prices from memory
        let fullFare = window.settings?.transportFares?.[`zone${zone}`] || window.settings?.[`transZone${zone}Full`] || 0;
        fullFare = parseFloat(fullFare);

        let oneWayFare = window.settings?.transportFares?.[`zone${zone}OneWay`] || window.settings?.[`transZone${zone}OneWay`];
        oneWayFare = parseFloat(oneWayFare) || (fullFare > 0 ? fullFare / 2 : 0); // Fallback: half price

        // Choose which price to display based on the active mode
        const displayPrice = (currentMode === 'one_way') ? oneWayFare : fullFare;

        if (fullFare > 0) {
            html += `<option value="${tierValue}">Zone ${zone} ($${displayPrice.toFixed(2)})</option>`;
        }
    });

    // 3. Inject options and keep the student's currently selected zone highlighted
    const activeTier = selectedTier !== undefined ? selectedTier : editTransportSelect.value;
    editTransportSelect.innerHTML = html;
    editTransportSelect.value = String(activeTier || 0);

    // 4. Set the mode dropdown to match the database (only runs on initial open)
    if (editModeSelect && selectedMode) {
        editModeSelect.value = selectedMode;
    }

    // 5. 🌟 THE FIX: Link the two dropdowns together!
    // Whenever the Mode dropdown changes, it immediately runs this function again to update the $ prices.
    if (editModeSelect && !editModeSelect.dataset.syncAttached) {
        editModeSelect.addEventListener('change', function() {
            // Re-populate the zones using the newly selected mode, keeping the same zone selected
            window.populateEditTransportDropdown(editTransportSelect.value, this.value);
        });
        editModeSelect.dataset.syncAttached = "true"; // Prevents attaching multiple times
    }
};

window.syncEditTransportMode = function() {
    const transportSelect = document.getElementById('editTransport');
    const modeSelect = document.getElementById('editTransportMode');
    const selectedOption = transportSelect?.selectedOptions?.[0];
    if (modeSelect && selectedOption?.dataset.mode) modeSelect.value = selectedOption.dataset.mode;
};

window.saveEditedStudent = async function() {
    const id = document.getElementById('editStuId').value;
    const s = window.students.find(st => st.id === id);
    if(!s) return;
    const originalStudent = JSON.parse(JSON.stringify(s));
    
    // 1. Capture OLD states before we change them
    const oldPlan = s.billing_plan || s.billingPlan || 'termly';
    const oldTransport = parseFloat(s.transport_tier !== undefined ? s.transport_tier : (s.transportTier || 0)) || 0;
    const oldTransportMode = s.transport_mode || s.transportMode || 'full';
    const oldFood = String(s.food_program) === 'true' || String(s.foodProgram) === 'true';
    const oldStat = String(s.stationery_pack) === 'true' || String(s.stationeryPack) === 'true';
    const oldBooks = s.textbooks === true || String(s.textbooks).toLowerCase() === 'true';

    // 2. Strict Memory Mapping Save
    s.name = document.getElementById('editName') ? document.getElementById('editName').value : s.name; 

    // FIX 1: Target BOTH possible ID variants for the phone number
    const cellInput = document.getElementById('editPhone') || document.getElementById('editCell');
    s.phone = cellInput ? cellInput.value : s.phone;

    // FIX 2: Capture the missing fields
    const emailInput = document.getElementById('editEmail');
    s.email = emailInput ? emailInput.value : s.email;

    const guardianInput = document.getElementById('editGuardianName');
    s.guardian_name = guardianInput ? guardianInput.value : (s.guardian_name || s.guardianName);

    const statusInput = document.getElementById('editStatus');
    s.enrollment_status = statusInput ? statusInput.value : (s.enrollment_status || s.enrollmentStatus);

    s.dob = document.getElementById('editDOB') ? document.getElementById('editDOB').value : s.dob; 
    s.enrollDate = document.getElementById('editEnroll') ? document.getElementById('editEnroll').value : (s.enrollDate || s.enroll_date);
    s.gender = document.getElementById('editGender') ? document.getElementById('editGender').value : s.gender; 
    s.grade = document.getElementById('editGrade') ? document.getElementById('editGrade').value : s.grade;
    s.address = document.getElementById('editAddress') ? document.getElementById('editAddress').value : s.address;
    
    const newPlan = document.getElementById('editBillingPlan') ? document.getElementById('editBillingPlan').value : oldPlan;
    s.billing_plan = newPlan;
    s.billingPlan = newPlan;

    // 🎯 FIX: Save Optional Services back to the Student Object (Syncing both memory styles)
    if(document.getElementById('editTransport')) {
        s.transportTier = parseFloat(document.getElementById('editTransport').value) || 0;
        s.transport_tier = s.transportTier; // Sync to database naming
        s.uses_transport = s.transportTier > 0; 
    }
    s.transportMode = document.getElementById('editTransportMode')?.value || s.transportMode || 'full';
    s.transport_mode = s.transportMode;
    
    // 👇 NEW: DRIVER UI CAPTURE 👇
    const driverInput = document.getElementById('editDriver');
    s.driver = driverInput ? driverInput.value : (s.driver || '');

    if(document.getElementById('editFood')) {
        s.foodProgram = document.getElementById('editFood').value === 'true';
        s.food_program = s.foodProgram; 
    }
    if(document.getElementById('editStationery')) {
        s.stationeryPack = document.getElementById('editStationery').value === 'true';
        s.stationery_pack = s.stationeryPack;
    }
    if (document.getElementById('editTextbooks')) {
        s.textbooks = document.getElementById('editTextbooks').value === 'true';
    }
    
    let newLedgerEntries = [];
    const dateStr = new Date().toISOString().split('T')[0];
    const termVal = typeof window.getCurrentTerm === 'function' ? window.getCurrentTerm() : "Current Term";
    if (!s.ledger) s.ledger = [];

    const currentMonthName = new Date().toLocaleString('default', { month: 'long' });
    const currentYear = new Date().getFullYear();
    const currentMonthPrefix = `${currentYear}-${String(new Date().getMonth() + 1).padStart(2, '0')}`;

    // Only adjust unpaid charges from the current billing period.
    const voidActiveCharges = (keyword) => {
        s.ledger.forEach(entry => {
            const description = (entry.description || entry.desc || '').toLowerCase();
            const isCurrentPeriod = entry.term === termVal || String(entry.date || '').startsWith(currentMonthPrefix);
            const hasRecordedPayment = (parseFloat(entry.paid) || 0) > 0 || (entry.balance !== undefined && parseFloat(entry.balance) <= 0) || s.ledger.some(other => {
                if (!['payment', 'discount', 'waiver', 'credit', 'overpayment'].includes(other.type)) return false;
                const breakdowns = Array.isArray(other.breakdown) ? other.breakdown : [];
                return breakdowns.some(item => {
                    const allocation = String(item.desc || item.description || '').toLowerCase();
                    return allocation && (allocation.includes(description) || description.includes(allocation));
                });
            });

            if (entry.type === 'charge' && entry.status === 'ACTIVE' && description.includes(keyword.toLowerCase()) && isCurrentPeriod && !hasRecordedPayment) {
                entry.status = 'VOID';
                entry.voided_at = new Date().toISOString();
                newLedgerEntries.push(entry); // Push the update to cloud queue
            }
        });
    };

    // ==========================================
    // 🧠 FEATURE 1: SYMMETRIC PLAN SWITCHER
    // ==========================================
    if (oldPlan !== newPlan) {
        voidActiveCharges('tuition');

        if (newPlan === 'monthly' || newPlan === 'termly') {
            let tuitionAmount = 0;
            if (newPlan === 'monthly') {
                tuitionAmount = parseFloat(window.localStorage.getItem('setMonthlyTuition')) || (window.settings && window.settings.monthlyTuition) || 50;
            } else {
                let gradeFees = [];
                if (Array.isArray(window.feeStructures)) {
                    const structure = window.feeStructures.find(f => (f.id || f.grade) === s.grade);
                    gradeFees = structure ? (structure.fees || structure.items || []) : [];
                } else if (window.feeStructures && window.feeStructures[s.grade]) {
                    gradeFees = window.feeStructures[s.grade];
                }
                tuitionAmount = gradeFees.reduce((total, fee) => {
                    const feeName = String(fee.name || fee.desc || '').toLowerCase();
                    return total + (feeName.includes('tuition') || feeName.includes('term') || feeName === 'fee' ? (parseFloat(fee.amount) || 0) : 0);
                }, 0);
            }

            if (tuitionAmount > 0) {
                const planLabel = newPlan === 'monthly'
                    ? `Tuition Fee - ${currentMonthName} ${currentYear} (Monthly Billing)`
                    : `Tuition Fee - ${termVal} (Termly Billing)`;
                const replacementCharge = {
                    id: `CHG-${newPlan.toUpperCase()}-${Date.now()}`,
                    student_id: s.id,
                    date: dateStr,
                    type: 'charge',
                    amount: tuitionAmount,
                    description: planLabel,
                    term: termVal,
                    status: 'ACTIVE'
                };
                s.ledger.push(replacementCharge);
                newLedgerEntries.push(replacementCharge);
            }
        }
    }

    // ==========================================
    // 🧠 FEATURE 2: TWO-WAY SERVICE BILLING (ADD & REMOVE)
    // ==========================================
    const safeSettings = window.settings || {};
    
    // 🚚 FIXED: TRANSPORT CHECK
    if (s.transportTier !== oldTransport || s.transportMode !== oldTransportMode) {
        voidActiveCharges('transport'); // Clear old transport charges to avoid double billing
        if (s.transportTier > 0) {
            
            // 1. Calculate actual dollar amount based on tier (1-6) and mode
            let trnCost = 0;
            const zoneLetters = ['A', 'B', 'C', 'D', 'E', 'F'];
            const targetZone = zoneLetters[s.transportTier - 1]; // Maps 1 to 'A', 2 to 'B'
            
            if (targetZone) {
                // Fetch full and one-way prices from memory
                let fFare = parseFloat(safeSettings.transportFares?.[`zone${targetZone}`]) || parseFloat(safeSettings[`transZone${targetZone}Full`]) || 0;
                let oFare = parseFloat(safeSettings.transportFares?.[`zone${targetZone}OneWay`]) || parseFloat(safeSettings[`transZone${targetZone}OneWay`]) || (fFare > 0 ? fFare / 2 : 0);
                
                // Assign correct price
                trnCost = (s.transportMode === 'one_way') ? oFare : fFare;
            }

            // 2. Apply the actual dollar amount ($) instead of the tier index
            if (trnCost > 0) {
                const transportLabel = s.transportMode === 'one_way' ? 'One-Way' : 'Full Route';
                let trnCharge = { 
                    id: "CHG-TRN-" + Date.now() + Math.random().toString(36).substr(2, 4), 
                    student_id: s.id, 
                    date: dateStr, 
                    type: 'charge', 
                    amount: trnCost, // 👈 FIXED: Now charges actual dollars, not $1 or $2
                    description: `Transport Service (Zone ${targetZone} - ${transportLabel}) - ${currentMonthName} ${currentYear}`, 
                    term: termVal, 
                    status: 'ACTIVE' 
                };
                s.ledger.push(trnCharge); 
                newLedgerEntries.push(trnCharge);
            }
        }
    }

    // Food Check
    if (s.foodProgram !== oldFood) {
        if (s.foodProgram) {
            let fFee = parseFloat(safeSettings.foodFee) || parseFloat(localStorage.getItem('setFoodFee')) || 0;
            if (fFee > 0) {
                let fCharge = { id: "CHG-FOD-" + Date.now() + Math.random().toString(36).substr(2, 4), student_id: s.id, date: dateStr, type: 'charge', amount: fFee, description: `Food Program - ${termVal}`, term: termVal, status: 'ACTIVE' };
                s.ledger.push(fCharge); newLedgerEntries.push(fCharge);
            }
        } else {
            voidActiveCharges('food'); // Removed food, void the charge
        }
    }

    // Stationery Check
    if (s.stationeryPack !== oldStat) {
        if (s.stationeryPack) {
            const isECD = String(s.grade).toLowerCase().includes('ecd');
            let statFee = isECD ? (parseFloat(safeSettings.stationeryFeeECD) || 0) : (parseFloat(safeSettings.stationeryFeeGrades) || 0);
            if (statFee > 0) {
                let sCharge = { id: "CHG-STN-" + Date.now() + Math.random().toString(36).substr(2, 4), student_id: s.id, date: dateStr, type: 'charge', amount: statFee, description: `Stationery Pack - ${currentYear}`, term: termVal, status: 'ACTIVE' };
                s.ledger.push(sCharge); newLedgerEntries.push(sCharge);
            }
        } else {
            voidActiveCharges('stationery'); // Removed stationery, void the charge
        }
    }

    // 📚 FIXED: TEXTBOOK CHECK
    if (s.textbooks !== oldBooks) {
        if (s.textbooks) {
            let tbFee = parseFloat(safeSettings.textbookFeeGrade) || 0; // 👈 FIXED: Variable Name Corrected
            if (tbFee > 0) {
                let tbCharge = { id: "CHG-TBK-" + Date.now() + Math.random().toString(36).substr(2, 4), student_id: s.id, date: dateStr, type: 'charge', amount: tbFee, description: `Textbook Fee (Once-Off)`, term: termVal, status: 'ACTIVE' };
                s.ledger.push(tbCharge); newLedgerEntries.push(tbCharge);
            }
        } else {
            voidActiveCharges('textbook'); // Removed textbooks, void the charge
        }
    }

    // ==========================================
    // 🧠 FEATURE 3: UNIVERSAL BALANCE RECALCULATION
    // ==========================================
    let activeBilled = 0;
    let totalPaid = 0;
    
    s.ledger.forEach(l => {
        if (l.status === 'ACTIVE') {
            if (l.type === 'charge' || l.type === 'fee') {
                activeBilled += (parseFloat(l.amount) || 0);
            } else if (['payment', 'discount', 'waiver', 'credit', 'overpayment'].includes(l.type)) {
                totalPaid += (parseFloat(l.amount) || 0);
            }
        }
    });

    s.balanceOwing = activeBilled - totalPaid;
    s.balance_owing = s.balanceOwing; // Ensure both variants are synced

    // ==========================================
    // 💾 SAVE & SYNC TO SUPABASE (CORRECTED)
    // ==========================================
    const db = window.supabase || window.supabaseClient; 
    let insertedLedgerIds = [];
    let voidedLedgerIds = [];

    if (db) {
        try {
            const itemsToInsert = newLedgerEntries.filter(e => e.status === 'ACTIVE');
            const itemsToUpdate = newLedgerEntries.filter(e => e.status === 'VOID');
            insertedLedgerIds = itemsToInsert.map(entry => entry.id);
            voidedLedgerIds = itemsToUpdate.map(entry => entry.id);

            if (itemsToInsert.length > 0) {
                const { error: insertErr } = await db.from('student_ledger').insert(itemsToInsert);
                if (insertErr) throw insertErr;
            }

            for (let voidedItem of itemsToUpdate) {
                const { error: voidErr } = await db.from('student_ledger')
                    .update({ status: 'VOID', voided_at: voidedItem.voided_at })
                    .eq('id', voidedItem.id);
                if (voidErr) throw voidErr;
            }
            
            // FIX 3: Push the missing fields to the database payload
            const { error: profileError } = await db.from('students').update({
                name: s.name,
                phone: s.phone,
                email: s.email,                         // Added missing field
                guardian_name: s.guardian_name,         // Added missing field
                enrollment_status: s.enrollment_status, // Added missing field
                dob: s.dob,
                enroll_date: s.enrollDate,
                gender: s.gender,
                grade: s.grade,
                address: s.address,
                billing_plan: s.billing_plan,
                transport_tier: String(s.transportTier), 
                transport_mode: s.transportMode,
                uses_transport: s.uses_transport,
                driver: s.driver,                       // 👇 NEW: DRIVER SYNCED TO SUPABASE
                food_program: s.foodProgram ? 'true' : 'false',
                stationery_pack: s.stationeryPack ? 'true' : 'false',
                textbooks: !!s.textbooks, 
                balance_owing: s.balanceOwing
            }).eq('id', s.id);

            if (profileError) throw profileError; 
            
        } catch(e) {
            console.error("Could not sync profile adjustments to cloud:", e);
            try {
                if (insertedLedgerIds.length > 0) {
                    await db.from('student_ledger').delete().in('id', insertedLedgerIds);
                }
                if (voidedLedgerIds.length > 0) {
                    await db.from('student_ledger').update({ status: 'ACTIVE', voided_at: null }).in('id', voidedLedgerIds);
                }
            } catch (rollbackError) {
                console.error("Could not roll back ledger changes:", rollbackError);
            }
            Object.keys(s).forEach(key => delete s[key]);
            Object.assign(s, originalStudent);
            alert("⚠️ Saved locally, but failed to reach the cloud database. Error: " + e.message);
            return; 
        }
    } else {
        console.warn("⚠️ No Supabase connection found. Data only saved to local browser memory.");
    }

    if (typeof window.saveData === 'function') window.saveData(); 
    if (typeof window.closeModal === 'function') window.closeModal('editModal'); 
    
    if (typeof window.filterDirectory === 'function') window.filterDirectory();
    if (typeof window.updateDashboard === 'function') window.updateDashboard();
    
    alert(`✅ ${s.name}'s profile synced. New Balance: $${s.balanceOwing.toFixed(2)}`);
};

window.voidLedgerCharge = async function(studentId, chargeId, button) {
    if (window.__ledgerVoidInProgress) return;

    // 1. Admin Security Check (Level 3 only — Level 2 must not void/reverse transactions)
    const role = window.currentUser?.role || "";
    if (!(role.includes('Level 3') || role === 'Chief Admin')) {
        return alert("❌ Access Denied: Only Level 3 (Chief Admins) can void charges.");
    }

    if (!navigator.onLine || !window.supabaseClient) {
        return alert("⚠️ Connect to the cloud before reversing a charge so the ledger and balance stay synchronized.");
    }

    const student = (window.students || []).find(s => String(s.id) === String(studentId));
    if (!student) return alert("Student not found.");
    const charge = (student.ledger || []).find(entry => String(entry.id) === String(chargeId));
    if (!charge) return alert("Charge not found in this student's ledger.");
    if (['VOID', 'VOIDED'].includes(String(charge.status || '').toUpperCase())) return alert("This charge is already reversed.");

    const chargeDescription = charge.description || charge.desc || 'Student charge';
    const chargeAmount = parseFloat(charge.amount) || 0;
    if (!confirm(`Reverse this charge?\n\n${chargeDescription}\nAmount: $${chargeAmount.toFixed(2)}\n\nThe original charge will remain in the audit history as VOID.`)) return;

    window.__ledgerVoidInProgress = true;
    const originalButtonText = button ? button.textContent : '';
    if (button) {
        button.disabled = true;
        button.textContent = 'Reversing...';
    }

    try {
        const previousStatus = charge.status;
        const previousVoidedAt = charge.voided_at;
        const voidedAt = new Date().toISOString();
        const balanceAfterVoid = window.calculateStudentBalance({
            ...student,
            ledger: student.ledger.map(entry => String(entry.id) === String(chargeId)
                ? { ...entry, status: 'VOID', voided_at: voidedAt }
                : entry)
        });

        const { data: updatedCharge, error: chargeError } = await window.supabaseClient
            .from('student_ledger')
            .update({ status: 'VOID', voided_at: voidedAt })
            .eq('id', chargeId)
            .eq('student_id', studentId)
            .not('status', 'in', '(VOID,VOIDED)')
            .select('id');
        if (chargeError) throw chargeError;
        if (!updatedCharge || updatedCharge.length === 0) throw new Error('The charge was not updated. Refresh the ledger and try again.');

        const { error: balanceError } = await window.supabaseClient
            .from('students')
            .update({ balance_owing: balanceAfterVoid })
            .eq('id', studentId);
        if (balanceError) {
            const { error: rollbackError } = await window.supabaseClient.from('student_ledger')
                .update({ status: previousStatus || 'ACTIVE', voided_at: previousVoidedAt || null })
                .eq('id', chargeId)
                .eq('student_id', studentId);
            if (rollbackError) throw new Error(`Balance update failed (${balanceError.message}) and charge rollback failed (${rollbackError.message}).`);
            throw balanceError;
        }

        charge.status = 'VOID';
        charge.voided_at = voidedAt;
        student.balanceOwing = balanceAfterVoid;
        student.balance_owing = balanceAfterVoid;

        if (typeof window.filterDirectory === 'function') window.filterDirectory();
        if (typeof window.updateDashboard === 'function') window.updateDashboard();
        if (document.getElementById('currentLedgerStudentId')?.value === String(studentId)) window.viewLedger(studentId);
        alert(`✅ Charge reversed. New balance: $${balanceAfterVoid.toFixed(2)}.`);
    } catch (error) {
        console.error("Cloud Void Error:", error);
        alert(`⚠️ Charge reversal failed. No local balance was changed. ${error.message || ''}`);
    } finally {
        window.__ledgerVoidInProgress = false;
        if (button && button.isConnected) {
            button.disabled = false;
            button.textContent = originalButtonText;
        }
    }
};


