window.addPayBreakdownRow = function(desc = '', amt = '') {
    const list = document.getElementById('payBreakdownList');
    
    // Safety check from original: stops execution if the HTML element isn't found
    if (!list) return; 

    const row = document.createElement('div');
    
    // Modern flexbox layout for the smart-table look
    row.style.cssText = "display: flex; gap: 10px; align-items: center; margin-bottom: 8px;";
    
    row.innerHTML = `
        <input type="text" class="p-desc input-standard" placeholder="Fee Description" value="${desc}" style="flex: 2; height: 30px; font-size: 12px; border: 1px solid #bdc3c7;">
        <input type="number" class="p-amt input-standard" placeholder="0.00" value="${amt}" style="flex: 1; height: 30px; font-size: 12px; text-align: right; border: 1px solid #bdc3c7;" oninput="if(typeof updatePaymentLiveTotals === 'function') updatePaymentLiveTotals(); else if(typeof calcTotalPay === 'function') window.calcTotalPay();">
        <button type="button" onclick="this.parentElement.remove(); if(typeof updatePaymentLiveTotals === 'function') updatePaymentLiveTotals(); else if(typeof calcTotalPay === 'function') window.calcTotalPay();" style="background: #e74c3c; color: white; border: none; border-radius: 3px; width: 30px; height: 30px; cursor: pointer; display: flex; align-items: center; justify-content: center; font-size: 12px;" title="Remove Item">✖</button>
    `;
    
    list.appendChild(row);
    
    // Trigger the calculation immediately when a row is dynamically added
    if (typeof updatePaymentLiveTotals === 'function') {
        updatePaymentLiveTotals();
    } else if (typeof calcTotalPay === 'function') {
        window.calcTotalPay();
    }
};

window.calcTotalPay = function() {
    const rows = document.getElementById('payBreakdownList').children;
    let total = 0;
    for(let i=0; i<rows.length; i++) {
        total += parseFloat(rows[i].querySelector('.p-amt').value) || 0;
    }
    const payUsd = document.getElementById('payUsd');
    if(payUsd) payUsd.value = total.toFixed(2);
};

