// STUDENT EVENT AND TRIP TRIGGER
// ===========================================

window.checkEventBalance = function() {
    const studentInput = document.getElementById('eventStudentId').value.trim();
    const eventName = document.getElementById('eventName').value.trim();
    const eventDate = document.getElementById('eventDate').value;
    const statsDiv = document.getElementById('eventStats');
    const totalBillInput = document.getElementById('eventTotalBill');

    if (!studentInput || !eventName) {
        statsDiv.style.display = 'none';
        return;
    }

    let studentId = studentInput.includes(' - ') ? studentInput.split(' - ')[0].trim() : studentInput;
    const student = window.students.find(s => s.id === studentId);

    // Calculate Days Left
    let daysLeftText = "";
    if (eventDate) {
        const diffTime = new Date(eventDate).setHours(0,0,0,0) - new Date().setHours(0,0,0,0);
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
        if (diffDays > 0) daysLeftText = `⏱️ <strong>${diffDays} days left</strong> until event.`;
        else if (diffDays === 0) daysLeftText = `⏱️ Event is <strong>Today</strong>.`;
        else daysLeftText = `⏱️ Event passed <strong>${Math.abs(diffDays)} days ago</strong>.`;
    }

    if (!student || !student.ledger) {
        if (daysLeftText) {
            statsDiv.innerHTML = daysLeftText;
            statsDiv.style.display = 'block';
        }
        return;
    }

    // Tally Existing Ledger Matches
    let billed = 0;
    let paid = 0;
    const targetDesc = `Event/Trip: ${eventName}`.toLowerCase();

    student.ledger.forEach(item => {
        if (item.status === 'VOID' || item.status === 'VOIDED') return;
        
        if (item.type === 'charge' && item.desc && item.desc.toLowerCase() === targetDesc) {
            billed += parseFloat(item.amount) || 0;
        }
        if (item.type === 'payment') {
            if (item.breakdown && item.breakdown.length > 0) {
                item.breakdown.forEach(b => {
                    if (b.desc && b.desc.toLowerCase() === targetDesc) paid += (parseFloat(b.amt) || 0);
                });
            } else if (item.desc && item.desc.toLowerCase().includes(eventName.toLowerCase())) {
                paid += parseFloat(item.amount) || 0;
            }
        }
    });

    const owed = billed - paid;
    
    // Prevent double-billing if charge already exists
    if (billed > 0) {
        totalBillInput.value = billed;
        totalBillInput.disabled = true; 
    } else {
        totalBillInput.disabled = false;
    }

    statsDiv.innerHTML = `
        ${daysLeftText}${daysLeftText ? '<br><br>' : ''}
        💰 Expected Bill: <strong>$${billed.toFixed(2)}</strong><br>
        ✅ Total Paid: <strong>$${paid.toFixed(2)}</strong><br>
        ⚖️ Remaining Balance: <strong style="color:${owed > 0 ? '#c0392b' : '#27ae60'}">$${owed.toFixed(2)}</strong>
    `;
    statsDiv.style.display = 'block';
};


// ==========================================
// EVENTS & TRIPS PAYMENT PROCESSOR
// ==========================================
// HELPER 1: Calculates and displays Days Left
window.calculateDaysLeft = function() {
    const dateVal = document.getElementById('eventDate').value;
    const badge = document.getElementById('daysLeftBadge');
    if (!dateVal) {
        badge.innerText = "";
        return;
    }
    const eventDateObj = new Date(dateVal);
    const today = new Date();
    today.setHours(0,0,0,0);
    const diffTime = eventDateObj - today;
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    
    if (diffDays < 0) badge.innerText = "(Passed)";
    else if (diffDays === 0) badge.innerText = "(Today)";
    else badge.innerText = `(${diffDays} days left)`;
};

// HELPER 2: Pulls student ledger and shows Event Arrears/Paid instantly
window.checkEventStats = function() {
    const rawStudentInput = document.getElementById('eventStudentId').value.trim();
    const eventName = document.getElementById('eventName').value.trim();
    const statsDiv = document.getElementById('eventStats');
    const billInput = document.getElementById('eventTotalBill');
    const dateInput = document.getElementById('eventDate');
    const amountNowInput = document.getElementById('eventAmount');
    
    // 1. 🪄 AUTO-FILL LOGIC: If a known event is selected, fill its date and bill
    if (eventName && window.availableEventsMap && window.availableEventsMap.has(eventName)) {
        const knownEventData = window.availableEventsMap.get(eventName);
        
        if (!dateInput.value && knownEventData.date) {
            dateInput.value = knownEventData.date;
            if (typeof window.calculateDaysLeft === 'function') window.calculateDaysLeft();
        }
        
        if (!billInput.value && knownEventData.bill) {
            billInput.value = knownEventData.bill;
        }
    }

    // 2. Clear stats if inputs are empty
    if (!rawStudentInput || !eventName) {
        statsDiv.style.display = 'none';
        billInput.disabled = false;
        return;
    }

    let studentId = rawStudentInput.includes(' - ') ? rawStudentInput.split(' - ')[0].trim() : rawStudentInput;
    const student = (window.students || []).find(s => s.id === studentId);
    
    if (!student || !student.ledger) {
        statsDiv.style.display = 'none';
        return;
    }

    const targetDescLower = eventName.toLowerCase();
    let expected = 0;
    let paid = 0;

    // 3. 🧠 STRICT EVENT-ONLY LEDGER SCANNER
    student.ledger.forEach(item => {
        if (item.status === 'VOID' || item.status === 'VOIDED') return;
        
        const itemDesc = (item.description || item.desc || "").toLowerCase();
        const itemId = String(item.id || "").toLowerCase();
        const itemCategory = (item.category || "").toLowerCase();
        const rNo = String(item.receiptNo || item.receipt_no || "").toLowerCase();

        // 🛑 STRICT GUARD: Is this item actually an Event, Trip, or labeled with an EVT identifier?
        const isEventItem = 
            itemCategory.includes('event') || 
            itemCategory.includes('trip') || 
            itemCategory.includes('event / trip') ||
            itemId.includes('evt') || 
            rNo.startsWith('evt') || 
            itemDesc.includes('event/trip:') || 
            itemDesc.includes('trip:');

        if (!isEventItem) return; // Skip completely if it's Tuition or Shop!

        // Find Expected Bill for THIS specific event
        if (item.type === 'charge' && itemDesc.includes(targetDescLower)) {
            expected += parseFloat(item.amount || 0);
        }
        
        // Find Payments toward THIS specific event (checking direct or breakdown arrays)
        if (item.type === 'payment' || item.type === 'discount' || item.type === 'waiver') {
            if (item.breakdown && item.breakdown.length > 0) {
                item.breakdown.forEach(b => {
                    const bDescLower = (b.desc || b.description || "").toLowerCase();
                    if (bDescLower.includes(targetDescLower)) {
                        paid += parseFloat(b.amt || 0);
                    }
                });
            } else if (itemDesc.includes(targetDescLower)) {
                paid += parseFloat(item.amount || 0);
            }
        }
    });

    // 4. Update the UI
    if (expected > 0) {
        const arrears = expected - paid;
        billInput.value = expected; 
        billInput.disabled = true; // Lock field because the bill is already set
        
        let statusHtml = `<strong>${student.name}</strong><br>💰 Expected: <strong>$${expected.toFixed(2)}</strong> | ✅ Paid: <strong>$${paid.toFixed(2)}</strong> | ⚠️ Arrears: <strong style="color: ${arrears > 0.01 ? '#c0392b' : '#27ae60'}">$${arrears.toFixed(2)}</strong>`;
        
        if (arrears <= 0.01) {
            statusHtml += `<br><span style="color:#27ae60; font-weight:bold; font-size:14px;">✅ FULLY PAID!</span>`;
            if(amountNowInput) amountNowInput.value = '0';
        } else {
            if(amountNowInput) amountNowInput.value = arrears.toFixed(2); // Auto-suggest remaining balance
        }

        statsDiv.innerHTML = statusHtml;
        statsDiv.style.display = 'block';
    } else {
        // Unrecognized event (Brand new)
        billInput.disabled = false;
        statsDiv.innerHTML = `<em>No previous charges found for "${eventName}".<br>Processing this will create a brand new charge.</em>`;
        statsDiv.style.display = 'block';
    }
};
// 1. Function to fetch and populate the dropdown list
window.populateEventHistory = async function() {
    const dataList = document.getElementById('eventHistoryList');
    if (!dataList) return;

    // We use a Map to store unique event names and their known Dates and Bills
    let uniqueEvents = new Map(); 

    // A. Fetch from Active Announcements (Events & Trips)
    if (typeof window.supabase !== 'undefined' || typeof window.supabaseClient !== 'undefined') {
        const db = window.supabase || window.supabaseClient;
        try {
            const { data: annData } = await db.from('announcements')
                .select('title, date, type')
                .or('type.eq.📅 Event,type.eq.🚌 Trip');
            
            if (annData) {
                annData.forEach(a => {
                    uniqueEvents.set(a.title.trim(), { date: a.date, bill: '' });
                });
            }
        } catch(e) { 
            console.warn("Could not fetch announcements for dropdown", e); 
        }
    }

    // B. Fetch from Student Ledgers (in case an event wasn't published)
    (window.students || []).forEach(student => {
        (student.ledger || []).forEach(item => {
            const itemDesc = item.description || item.desc || "";
            if (item.type === 'charge' && itemDesc.startsWith('Event/Trip: ')) {
                const eventName = itemDesc.replace('Event/Trip: ', '').trim();
                
                if (!uniqueEvents.has(eventName)) {
                    uniqueEvents.set(eventName, { date: item.date, bill: item.amount });
                } else {
                    // If it exists but has no bill amount logged yet, add it
                    let existing = uniqueEvents.get(eventName);
                    if (!existing.bill) existing.bill = item.amount;
                    uniqueEvents.set(eventName, existing);
                }
            }
        });
    });

    // C. Inject options into the HTML Datalist
    dataList.innerHTML = '';
    uniqueEvents.forEach((data, name) => {
        const opt = document.createElement('option');
        opt.value = name;
        dataList.appendChild(opt);
    });
    
    // Save to global window so we can auto-fill date/bill later
    window.availableEventsMap = uniqueEvents;
};


// 2. Updated checkEventStats to auto-fill Date and Bill when a dropdown item is clicked


// 3. Trigger population when the page loads
document.addEventListener('DOMContentLoaded', () => {
    // Give it a brief delay to ensure window.students and window.supabase are loaded
    setTimeout(() => {
        if (typeof window.populateEventHistory === 'function') {
            window.populateEventHistory();
        }
    }, 1500); 
});
// UPDATED MAIN FUNCTION
window.processEventPaymentOnce = async function() {
    const db = window.supabase || window.supabaseClient;
    if (!navigator.onLine || !db) {
        alert("⚠️ An active internet connection is required to record this event payment. Please reconnect and try again. No receipt has been issued.");
        return;
    }
    if (!window.appDataReady) {
        alert("⚠️ Cloud synchronization is still in progress. Please wait until the system is ready before recording this payment.");
        return;
    }

    const rawStudentInput = document.getElementById('eventStudentId').value.trim();
    const eventTerm = document.getElementById('eventTerm').value;
    const cashierName = window.currentUser?.user || window.currentUser?.username || window.currentUser?.name || 'Admin';
    const eventName = document.getElementById('eventName').value.trim();
    const eventDateStr = document.getElementById('eventDate').value; 
    
    const rawAmountNow = document.getElementById('eventAmount').value.trim();
    let amountNow = rawAmountNow === '' ? 0 : Number(rawAmountNow);
    const rawTotalBill = document.getElementById('eventTotalBill').value.trim();
    const totalBill = rawTotalBill === '' ? NaN : Number(rawTotalBill);
    const ecoRefField = document.getElementById('eventEcoRef');
    const ecoRef = ecoRefField ? ecoRefField.value.trim().toUpperCase() : "";

    if (!rawStudentInput) return alert("⚠️ Please select a student.");
    if (!eventTerm) return alert("⚠️ Please select the Academic Term.");
    if (!eventName) return alert("⚠️ Please enter or select the Event/Trip name.");
    if (!eventDateStr) return alert("⚠️ Please select the Date of the Event/Trip.");
    if (!Number.isFinite(amountNow) || amountNow < 0) return alert("⚠️ Enter a valid, non-negative payment amount.");
    if (rawTotalBill !== '' && (!Number.isFinite(totalBill) || totalBill < 0)) return alert("⚠️ Enter a valid, non-negative event bill.");

    window.ecoCashTransactions = window.ecoCashTransactions || [];
    if (ecoRef && ecoRef !== window.stagedEventEcoRef) {
        const alreadyUsed = window.ecoCashTransactions.some(t => String(t.ref || '').toUpperCase() === ecoRef && t.status === 'claimed');
        if (alreadyUsed) return alert("❌ This EcoCash Reference Number has already been used in the system.");
    }
    const paymentMethodLabel = ecoRef ? `EcoCash (${ecoRef})` : 'Cash';

    const currentMonth = new Date().getMonth() + 1; 
    let expectedTerm = "Term 3";
    if (currentMonth >= 1 && currentMonth <= 4) expectedTerm = "Term 1";
    else if (currentMonth >= 5 && currentMonth <= 8) expectedTerm = "Term 2";

    if (eventTerm !== expectedTerm) {
        const proceed = confirm(`⚠️ PERIOD MISMATCH WARNING\n\nYou selected ${eventTerm}, but we are currently in ${expectedTerm}.\n\nAre you intentionally logging a past/future event? Click OK to proceed.`);
        if (!proceed) return;
    }

    let studentId = rawStudentInput.includes(' - ') ? rawStudentInput.split(' - ')[0].trim() : rawStudentInput;
    const student = (window.students || []).find(s => String(s.id) === String(studentId));
    if (!student) return alert("❌ Student not found.");

    const eventStats = document.getElementById('eventStats');
    if (eventStats) {
        eventStats.textContent = 'Verifying the latest student balance with the database...';
        eventStats.style.display = 'block';
    }
    const { data: latestLedger, error: ledgerError } = await db
        .from('student_ledger')
        .select('*')
        .eq('student_id', student.id);
    if (ledgerError) throw new Error(`Could not verify the latest student ledger: ${ledgerError.message}`);
    if (!Array.isArray(latestLedger)) throw new Error('Could not verify the latest student ledger. No receipt has been issued.');
    student.ledger = latestLedger;

    let currentBalance = typeof window.calculateStudentBalance === 'function'
        ? window.calculateStudentBalance(student)
        : 0;
    let creditAvailable = currentBalance < 0 ? Math.abs(currentBalance) : 0;

    const targetDescLower = eventName.trim().toLowerCase();
    const existingCharge = student.ledger.find(item => {
        if (item.type !== 'charge' || ['VOID', 'VOIDED', 'REVERSAL'].includes(String(item.status || '').toUpperCase())) {
            return false;
        }
        const description = String(item.description || item.desc || '').trim().toLowerCase();
        const eventDescription = description.replace(/^event\/trip:\s*/, '');
        const category = String(item.category || '').toLowerCase();
        return eventDescription === targetDescLower &&
            (description.startsWith('event/trip:') || category.includes('event') || category.includes('trip'));
    });

    const alreadyPaidForEvent = existingCharge ? student.ledger.reduce((total, entry) => {
        if (['VOID', 'VOIDED', 'REVERSAL'].includes(String(entry.status || '').toUpperCase()) || !['payment', 'waiver', 'discount', 'credit'].includes(entry.type)) return total;
        if (String(entry.linked_charge_id || '') === String(existingCharge.id)) return total + (parseFloat(entry.amount) || 0);
        const receiptLinkedChargeId = String(entry.id || '').startsWith('PAY-')
            ? String(entry.id).replace(/^PAY-/, 'CHG-')
            : '';
        if (receiptLinkedChargeId && receiptLinkedChargeId === String(existingCharge.id)) return total + (parseFloat(entry.amount) || 0);
        const receiptNo = String(entry.receipt_no || entry.receiptNo || '');
        if (receiptNo && `CHG-EVT-${receiptNo}` === String(existingCharge.id)) return total + (parseFloat(entry.amount) || 0);

        if (Array.isArray(entry.breakdown) && entry.breakdown.length > 0) {
            return total + entry.breakdown.reduce((amount, part) => {
                const partDesc = String(part.desc || part.description || '').toLowerCase();
                return amount + (partDesc.includes(targetDescLower) ? (parseFloat(part.amt || part.amount) || 0) : 0);
            }, 0);
        }

        const entryDesc = String(entry.description || entry.desc || '').toLowerCase();
        return total + (entryDesc.includes(targetDescLower) ? (parseFloat(entry.amount) || 0) : 0);
    }, 0) : 0;
    const eventAmountDue = existingCharge
        ? Math.max(0, (parseFloat(existingCharge.amount) || 0) - alreadyPaidForEvent)
        : totalBill;

    if (!existingCharge && (!Number.isFinite(totalBill) || totalBill <= 0)) {
        return alert("⚠️ This is a new event. Please enter the Expected Total Bill.");
    }
    if (existingCharge && eventAmountDue <= 0.01 && amountNow > 0) {
        return alert(`⚠️ ${student.name} has already paid the full bill for "${eventName}". No additional payment was recorded.`);
    }

    let isNewCharge = !existingCharge;
    let creditApplied = 0;

    if (creditAvailable > 0 && eventAmountDue > 0) {
        const useCredit = confirm(`💰 ADVANCE CREDIT FOUND!\n\n${student.name} has a pre-paid credit balance of $${creditAvailable.toFixed(2)}.\n\nDo you want to apply this credit to bill them for "${eventName}"?`);
        
        if (useCredit) {
            creditApplied = Math.min(creditAvailable, eventAmountDue);
            amountNow = Math.min(amountNow, Math.max(0, eventAmountDue - creditApplied));
            
            if (amountNow === 0 && creditApplied < eventAmountDue) {
                const payRest = confirm(`The credit ($${creditApplied.toFixed(2)}) covers part of the bill, but leaves a shortage of $${(eventAmountDue - creditApplied).toFixed(2)}.\n\nProceed without adding cash?`);
                if (!payRest) return;
            }
        }
    }

    if (amountNow + creditApplied > eventAmountDue + 0.01) {
        return alert(`⚠️ The entered payment exceeds the remaining event bill of $${eventAmountDue.toFixed(2)}. No payment was recorded.`);
    }

    if (amountNow <= 0 && creditApplied <= 0 && isNewCharge) {
        const justBill = confirm(`⚠️ No cash entered and no credit applied.\n\nDo you want to just BILL the student $${totalBill.toFixed(2)} for the trip without logging a payment?`);
        if (!justBill) return;
    } else if (amountNow <= 0 && creditApplied <= 0 && !isNewCharge) {
        return alert("⚠️ Please enter a payment amount. The student is already billed for this event.");
    }

    const dateStr = new Date().toISOString().split('T')[0];
    const receiptToken = typeof window.crypto?.randomUUID === 'function'
        ? window.crypto.randomUUID()
        : `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
    const receiptNo = `EVT-${receiptToken}`;
    const chargeId = "CHG-EVT-" + receiptNo;
    const eventChargeId = existingCharge ? existingCharge.id : chargeId;
    const finalDesc = existingCharge ? (existingCharge.description || existingCharge.desc) : `Event/Trip: ${eventName}`;
    const totalPaidNow = amountNow + creditApplied;
    const pendingLedgerEntries = [];

    if (isNewCharge) {
        pendingLedgerEntries.push({
            id: chargeId, date: dateStr, type: 'charge', amount: totalBill, 
            desc: finalDesc, description: finalDesc, category: 'Event / Trip', term: eventTerm, status: 'ACTIVE'
        });
    }

    if (creditApplied > 0) {
        pendingLedgerEntries.push({ id: "CHG-REV-" + receiptNo, date: dateStr, type: 'charge', amount: creditApplied, desc: `Credit Allocation (Reversal)`, description: `Credit Allocation (Reversal)`, term: eventTerm, status: 'ACTIVE' });
        pendingLedgerEntries.push({ id: "PAY-CRD-" + receiptNo, date: dateStr, type: 'payment', amount: creditApplied, desc: `Paid via Advance Credit`, description: `Paid via Advance Credit`, receiptNo: receiptNo, receipt_no: receiptNo, linked_charge_id: eventChargeId, method: 'Advance Credit', is_credit_backed: true, term: eventTerm, breakdown: [{ desc: `Covered by Advance Credit`, amt: creditApplied }], status: 'ACTIVE', processed_by: cashierName });
    }

    if (amountNow > 0) {
        pendingLedgerEntries.push({ id: "PAY-CSH-" + receiptNo, date: dateStr, type: 'payment', amount: amountNow, desc: `Event Payment: ${eventName}`, description: `Event Payment: ${eventName}`, receiptNo: receiptNo, receipt_no: receiptNo, linked_charge_id: eventChargeId, method: paymentMethodLabel, term: eventTerm, breakdown: [{ desc: finalDesc, amt: amountNow }], status: 'ACTIVE', processed_by: cashierName });
    }

    const ledgerIds = pendingLedgerEntries.map(entry => entry.id);
    const paymentRecordId = Date.now();
    const eventHistoryId = `EVH-${receiptNo}`;
    let ledgerSaved = false;
    let paymentSaved = false;
    let eventHistorySaved = false;
    let writeStatusUncertain = false;

    try {
        const databaseLedgerEntries = pendingLedgerEntries.map(entry => {
            const databaseEntry = {
                id: entry.id,
                student_id: student.id,
                date: entry.date,
                type: entry.type,
                description: entry.description || entry.desc,
                amount: entry.amount,
                status: entry.status,
                term: entry.term
            };
            ['receipt_no', 'linked_charge_id', 'method', 'is_credit_backed', 'breakdown', 'processed_by'].forEach(key => {
                if (entry[key] !== undefined) databaseEntry[key] = entry[key];
            });
            return databaseEntry;
        });
        const writeOperations = [];

        if (databaseLedgerEntries.length > 0) {
            writeOperations.push({
                name: 'ledger',
                request: db.from('student_ledger').insert(databaseLedgerEntries)
            });
        }

        if (amountNow > 0) {
            writeOperations.push({
                name: 'payment',
                request: db.from('payments').insert([{
                    id: paymentRecordId,
                    receipt_no: receiptNo,
                    student_id: student.id,
                    amount: amountNow,
                    date: dateStr,
                    method: paymentMethodLabel,
                    status: 'PAID',
                    notes: `Event/Trip Payment: ${eventName}`,
                    category: 'Events',
                    processed_by: cashierName
                }])
            });
        }

        if (totalPaidNow > 0) {
            writeOperations.push({
                name: 'event history',
                request: db.from('event_history').insert([{
                    id: eventHistoryId,
                    student_id: student.id,
                    student_name: student.name,
                    grade: student.grade || student.class || 'N/A',
                    event_name: eventName,
                    event_date: eventDateStr || null,
                    term: eventTerm,
                    amount_paid: totalPaidNow,
                    total_bill: Number.isFinite(totalBill) ? totalBill : (parseFloat(existingCharge?.amount) || 0),
                    receipt_no: receiptNo,
                    payment_date: dateStr,
                    processed_by: cashierName,
                    status: 'ACTIVE'
                }])
            });
        }

        const writeResults = await Promise.allSettled(writeOperations.map(operation => operation.request));
        const writeErrors = [];
        writeResults.forEach((result, index) => {
            const operation = writeOperations[index];
            if (result.status === 'rejected') {
                writeStatusUncertain = true;
                writeErrors.push(`${operation.name}: ${result.reason?.message || result.reason}`);
                return;
            }
            if (result.value?.error) {
                writeErrors.push(`${operation.name}: ${result.value.error.message}`);
                return;
            }
            if (operation.name === 'ledger') ledgerSaved = true;
            if (operation.name === 'payment') paymentSaved = true;
            if (operation.name === 'event history') eventHistorySaved = true;
        });
        if (writeErrors.length > 0) {
            throw new Error(writeErrors.join('; '));
        }
    } catch (err) {
        const rollbackErrors = [];
        const rollbackOperations = [];
        if (eventHistorySaved) rollbackOperations.push(db.from('event_history').delete().eq('id', eventHistoryId));
        if (paymentSaved) rollbackOperations.push(db.from('payments').delete().eq('id', paymentRecordId));
        if (ledgerSaved) rollbackOperations.push(db.from('student_ledger').delete().in('id', ledgerIds));

        try {
            const rollbackResults = await Promise.all(rollbackOperations);
            rollbackResults.forEach(result => {
                if (result?.error) rollbackErrors.push(result.error.message);
            });
        } catch (rollbackError) {
            rollbackErrors.push(rollbackError.message || String(rollbackError));
        }

        console.error("Cloud Sync Error:", err, rollbackErrors.length ? { rollbackErrors } : '');
        const rollbackNotice = rollbackErrors.length || writeStatusUncertain
            ? ` The database save could not be fully verified${rollbackErrors.length ? `, and rollback failed (${rollbackErrors.join('; ')})` : ''}. Do not retry this payment until an administrator verifies the records.`
            : ' No receipt was issued and the saved records were rolled back.';
        alert(`⚠️ Cloud save failed (${err.message || err}).${rollbackNotice}`);
        return;
    }

    student.ledger.push(...pendingLedgerEntries);

    if (ecoRef && amountNow > 0) {
        const existingTx = window.ecoCashTransactions.find(t => String(t.ref || '').toUpperCase() === ecoRef);
        if (existingTx) {
            existingTx.status = 'claimed';
            existingTx.claimedBy = student.id;
            existingTx.source = 'event-payment';
        } else {
            window.ecoCashTransactions.push({ date: dateStr, ref: ecoRef, studentId: student.id, amount: amountNow, zigAmount: 0, status: 'claimed', claimedBy: student.id, source: 'event-payment' });
        }
        window.stagedEventEcoRef = null;
    }

    if (typeof window.saveEcoCashTransactions === 'function') window.saveEcoCashTransactions();
    if (typeof window.calculateStudentBalance === 'function') {
        student.balanceOwing = window.calculateStudentBalance(student);
        student.balance_owing = student.balanceOwing;
    }

    document.getElementById('eventStudentId').value = '';
    document.getElementById('eventTerm').value = '';
    document.getElementById('eventName').value = '';
    document.getElementById('eventDate').value = '';
    document.getElementById('eventAmount').value = '';
    document.getElementById('eventTotalBill').value = '';
    document.getElementById('eventTotalBill').disabled = false;
    if (document.getElementById('eventEcoRef')) document.getElementById('eventEcoRef').value = '';
    if (document.getElementById('eventStats')) document.getElementById('eventStats').style.display = 'none';
    
    if (typeof window.saveData === 'function') window.saveData();
    if (typeof window.updateDashboard === 'function') window.updateDashboard();
    if (typeof window.populateEventHistory === 'function') window.populateEventHistory();
    if (typeof window.fetchAndRenderEventHistoryTable === 'function') window.fetchAndRenderEventHistoryTable();

    if (totalPaidNow <= 0) {
        alert(`✅ Event bill saved for ${student.name}. No payment was taken, so no receipt was issued.`);
        return;
    }

    const phone = (student.phone || student.cell || "").toString(); 
    let missedWhatsapp = false;

    if (phone.trim() !== "") {
        const wantsWhatsapp = confirm(`Do you want to send a WhatsApp receipt to ${student.name} at ${phone}?`);
        if (wantsWhatsapp) {
            let cleanPhone = phone.replace(/[^0-9+]/g, '');
            if (cleanPhone.startsWith('0')) cleanPhone = '263' + cleanPhone.substring(1); 
            
            const balanceNote = student.balanceOwing < 0 ? `Account Credit: $${Math.abs(student.balanceOwing).toFixed(2)}` : `Amount Still Owed: $${student.balanceOwing.toFixed(2)}`;
            let methodStr = [];
            if (amountNow > 0) methodStr.push(`${paymentMethodLabel} ($${amountNow.toFixed(2)})`);
            if (creditApplied > 0) methodStr.push(`Advance Credit ($${creditApplied.toFixed(2)})`);

            const waText = `*${window.settings?.schoolName || 'HAVEN ONLINE'} - Event Receipt*\n\n*Receipt No:* ${receiptNo}\n*Date:* ${dateStr}\n*Student:* ${student.name}\n*Student ID:* ${student.id}\n------------------------\n*Event/Trip:* ${eventName}\n*Academic Term:* ${eventTerm}\n------------------------\n*Amount Paid:* $${totalPaidNow.toFixed(2)}\n*Method:* ${methodStr.join(' + ')}\n------------------------\n*${balanceNote}*\n\n*Served By:* ${cashierName}\nThank you!`;
            
            window.open(`https://wa.me/${cleanPhone}?text=${encodeURIComponent(waText)}`, '_blank');
        }
    } else {
        missedWhatsapp = true;
    }

    if(typeof window.printClassicalReceipt === 'function') {
        const paymentBreakdown = [];
        if (amountNow > 0) paymentBreakdown.push({ method: paymentMethodLabel, amount: amountNow });
        if (creditApplied > 0) paymentBreakdown.push({ method: 'Advance Credit', amount: creditApplied });
        window.printClassicalReceipt(student, eventName, totalPaidNow, receiptNo, dateStr, cashierName, paymentBreakdown);
    }

    setTimeout(() => {
        if (missedWhatsapp) {
            alert(`✅ Event Saved!\n\n⚠️ Cannot send a WhatsApp receipt because there is no phone number saved in ${student.name}'s profile.`);
        } else {
            alert(`✅ Event Processed Successfully!`);
        }
    }, 500);
};

window.__eventPaymentInProgress = false;
window.processEventPayment = async function() {
    if (window.__eventPaymentInProgress) return;
    window.__eventPaymentInProgress = true;

    const button = document.getElementById('eventPaymentButton');
    if (button) {
        button.disabled = true;
        button.setAttribute('aria-busy', 'true');
        button.textContent = 'Verifying and saving...';
    }

    try {
        await window.processEventPaymentOnce();
    } catch (error) {
        console.error('Event payment processing failed:', error);
        alert(`⚠️ Event payment could not be completed: ${error.message || error}. No receipt was issued.`);
    } finally {
        window.__eventPaymentInProgress = false;
        const stats = document.getElementById('eventStats');
        if (stats && stats.textContent.startsWith('Verifying the latest student balance')) {
            stats.style.display = 'none';
        }
        if (button) {
            button.disabled = false;
            button.removeAttribute('aria-busy');
            button.textContent = '💾 Log Event Payment';
        }
    }
};

window.globalEventHistoryData = [];
window.__eventHistoryFetchPromise = null;

window.renderEventHistoryTable = function() {
    const tbody = document.getElementById('evHistoryTableBody');
    if (!tbody) return;

    const studentsById = new Map(
        (Array.isArray(window.students) ? window.students : [])
            .filter(student => student && student.id != null)
            .map(student => [String(student.id).trim().toLowerCase(), student])
    );
    const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g, character => ({
        '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    })[character]);
    const searchName = (document.getElementById('evFilterStudent')?.value || '').trim().toLowerCase();
    const searchGrade = (document.getElementById('evFilterGrade')?.value || '').trim().toLowerCase();
    const searchDate = document.getElementById('evFilterDate')?.value || '';
    const searchEvents = (document.getElementById('evFilterEvent')?.value || '')
        .toLowerCase().split(',').map(term => term.trim()).filter(Boolean);
    const targetBudget = parseFloat(document.getElementById('evTargetBudget')?.value) || 0;

    const rows = (window.globalEventHistoryData || []).map(event => {
        const studentId = String(event.student_id || event.studentId || '').trim();
        const student = studentsById.get(studentId.toLowerCase());
        return {
            ...event,
            student_id: studentId,
            student_name: student?.name || student?.studentName || event.student_name || event.name || 'Unknown Student',
            grade: student?.grade || student?.class || event.grade || event.class || 'N/A',
            event_name: event.event_name || event.description || event.notes || 'General Payment',
            receipt_no: event.receipt_no || event.receiptNo || '-',
            date: event.date || event.payment_date || 'N/A'
        };
    }).filter(event => {
        const name = String(event.student_name).toLowerCase();
        const id = String(event.student_id).toLowerCase();
        const grade = String(event.grade).toLowerCase();
        if (searchName && !name.includes(searchName) && !id.includes(searchName)) return false;
        if (searchGrade && !grade.includes(searchGrade)) return false;
        if (searchDate && event.date !== searchDate) return false;
        if (searchEvents.length && !searchEvents.some(term => String(event.event_name).toLowerCase().includes(term))) return false;
        return true;
    });

    let totalCollected = 0;
    const uniqueStudents = new Set();
    tbody.innerHTML = rows.length ? rows.map(event => {
        const amountPaid = parseFloat(event.amount_paid ?? event.amount) || 0;
        const amountBilled = parseFloat(event.amount_billed ?? event.total_bill ?? 0) || 0;
        totalCollected += amountPaid;
        if (event.student_id) uniqueStudents.add(event.student_id);
        return `
            <tr style="border-bottom: 1px solid #ecf0f1;">
                <td style="padding: 8px;">${escapeHtml(event.date)}</td>
                <td style="padding: 8px; font-weight: bold; color: #2c3e50;">${escapeHtml(event.student_name)}<br><small style="color: #7f8c8d; font-weight: normal;">${escapeHtml(event.student_id)}</small></td>
                <td style="padding: 8px;"><span style="background:#f4f6f7; padding:3px 8px; border-radius:4px; font-size:11px;">${escapeHtml(event.grade)}</span></td>
                <td style="padding: 8px; color: #8e44ad; font-weight: 500;">${escapeHtml(event.event_name)}</td>
                <td style="padding: 8px;">${escapeHtml(event.receipt_no)}</td>
                <td style="padding: 8px; text-align: right; color: #bdc3c7;">${amountBilled ? `$${amountBilled.toFixed(2)}` : '-'}</td>
                <td style="padding: 8px; text-align: right; font-weight: bold; color: #27ae60;">$${amountPaid.toFixed(2)}</td>
            </tr>
        `;
    }).join('') : '<tr><td colspan="7" style="padding: 15px; text-align: center; color: #95a5a6;">No confirmed event payments found.</td></tr>';

    const statStudents = document.getElementById('evStatStudents');
    const statCollected = document.getElementById('evStatCollected');
    if (statStudents) statStudents.innerText = uniqueStudents.size;
    if (statCollected) statCollected.innerText = `$${totalCollected.toFixed(2)}`;

    const remainingEl = document.getElementById('evStatRemaining');
    if (remainingEl) {
        const remaining = targetBudget > 0 ? targetBudget - totalCollected : 0;
        remainingEl.innerText = `$${Math.max(0, remaining).toFixed(2)}`;
        remainingEl.style.color = remaining <= 0 && targetBudget > 0 ? '#27ae60' : '#e74c3c';
    }
};

window.fetchAndRenderEventHistoryTable = async function() {
    const tbody = document.getElementById('evHistoryTableBody');
    if (!tbody || typeof window.supabaseClient === 'undefined') return;
    if (window.__eventHistoryFetchPromise) return window.__eventHistoryFetchPromise;

    window.__eventHistoryFetchPromise = (async () => {
        try {
            const { data, error } = await window.supabaseClient
                .from('event_payments_view')
                .select('*')
                .order('date', { ascending: false });
            if (error) throw error;
            window.globalEventHistoryData = Array.isArray(data) ? data : [];
            window.renderEventHistoryTable();
        } catch (error) {
            console.error('Error loading event history:', error);
            tbody.innerHTML = `<tr><td colspan="7" style="text-align:center; padding:20px; color:#e74c3c;">Error loading event data: ${String(error.message || error).replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character])}</td></tr>`;
        } finally {
            window.__eventHistoryFetchPromise = null;
        }
    })();

    return window.__eventHistoryFetchPromise;
};

window.renderEventAnalytics = async function() {
    return window.fetchAndRenderEventHistoryTable();
};

