window.migrateOldEventsToNewTable = async function() {
    if (!confirm("⚠️ This will wipe the broken ghosts and run a clean, bulletproof deep-scan.\n\nAre you sure you want to run this?")) return;
    
    if (typeof window.supabaseClient === 'undefined') return alert("Supabase not connected.");

    try {
        document.body.style.cursor = 'wait';
        
        // 1. WIPE BROKEN MIGRATIONS TO FIX DUPLICATES
        await window.supabaseClient.from('event_history').delete().like('id', 'EVH-MIG-%');
        
        // 2. Fetch fresh ledger data
        const { data: ledgerData } = await window.supabaseClient.from('student_ledger').select('*');
        let eventGroups = {}; 

        ledgerData.forEach(row => {
            if (row.status === 'VOID' || row.status === 'VOIDED') return;
            
            let isPayment = row.type === 'payment' || row.type === 'overpayment' || row.type === 'credit';
            let isCharge = row.type === 'charge';
            
            let breakdowns = [];
            try {
                breakdowns = typeof row.breakdown === 'string' ? JSON.parse(row.breakdown) : (row.breakdown || []);
            } catch(e) {}
            
            if (!Array.isArray(breakdowns) || breakdowns.length === 0) {
                breakdowns = [{ desc: row.description, amt: row.amount }];
            }
            
            breakdowns.forEach(b => {
                const descText = String(b.desc || b.description || '');
                const dLower = descText.toLowerCase();
                
                if (dLower.includes('event/trip:') || dLower.includes('event payment:') || (row.category && String(row.category).toLowerCase().includes('event'))) {
                    
                    // BULLETPROOF EVENT NAME EXTRACTION
                    let parsedEventName = descText;
                    const match = descText.match(/(?:Event\/Trip:|Event Payment:)\s*([^&]+)/i);
                    if (match) {
                        parsedEventName = match[1]; // Safely grabs everything AFTER the colon and BEFORE the next '&' symbol
                    }
                    
                    parsedEventName = parsedEventName.replace(/\(System Auto\)/ig, '').replace(/\(Admin Selected\)/ig, '').trim();
                    if (!parsedEventName) parsedEventName = "Unknown Event";

                    const safeName = parsedEventName.replace(/[^a-zA-Z0-9]/g, '').substring(0, 15).toUpperCase();
                    const key = `EVH-MIG-${row.student_id}-${safeName}`;
                    
                    let sName = 'Unknown Student';
                    let sGrade = 'N/A';
                    if (window.students && Array.isArray(window.students)) {
                        const match = window.students.find(s => s.id === row.student_id);
                        if (match) {
                            sName = match.name || match.studentName || match.id;
                            sGrade = match.grade || match.class || 'N/A';
                        }
                    }

                    if (!eventGroups[key]) {
                        eventGroups[key] = {
                            id: key, 
                            student_id: row.student_id,
                            student_name: sName,
                            grade: sGrade,
                            event_name: parsedEventName,
                            event_date: row.date,
                            term: row.term || 'Unknown',
                            amount_paid: 0,
                            total_bill: 0,
                            receipt_no: '-',
                            payment_date: row.date,
                            processed_by: row.processed_by || 'Migration',
                            status: 'ACTIVE'
                        };
                    }

                    let amt = parseFloat(b.amt || b.amount || row.amount) || 0;

                    if (isCharge) {
                        eventGroups[key].total_bill += amt;
                        eventGroups[key].event_date = row.date; 
                    }
                    if (isPayment) {
                        eventGroups[key].amount_paid += amt;
                        eventGroups[key].receipt_no = row.receipt_no && row.receipt_no !== '-' ? row.receipt_no : eventGroups[key].receipt_no;
                        eventGroups[key].payment_date = row.date; 
                    }
                }
            });
        });

        const recordsToInsert = Object.values(eventGroups);

        if (recordsToInsert.length > 0) {
            const { error } = await window.supabaseClient.from('event_history').upsert(recordsToInsert, { onConflict: 'id' });
            if (error) throw error;
        }
        
        alert(`✅ Clean Migration Complete!\n\nWiped old errors and successfully built ${recordsToInsert.length} perfect event records.`);
        
        window.fetchAndRenderEventHistoryTable();

    } catch (e) {
        console.error("Migration error:", e);
        alert("❌ Migration failed: " + e.message);
    } finally {
        document.body.style.cursor = 'default';
    }
};

window.printClassicalReceipt = function(student, eventName, amountPaid, receiptNo, dateStr, processedBy = '', paymentBreakdown = []) {
    const safeSettings = window.settings || {};
    const schoolName = safeSettings.schoolName || 'HAVEN MASTER SYSTEM';
    const cashierName = processedBy || window.currentUser?.user || window.currentUser?.username || window.currentUser?.name || 'Admin';
    const paymentMethodRows = paymentBreakdown.map(payment => `
        <tr>
            <td>${payment.method}</td>
            <td align="right">$${Number(payment.amount).toFixed(2)}</td>
        </tr>
    `).join('');

    // 1. Calculate the student's overall balance from their ledger (V1's accurate math + V2's breakdown safety)
    let totalBilled = 0;
    let totalPaid = 0;
    
    if (student && student.ledger && Array.isArray(student.ledger)) {
        student.ledger.forEach(item => {
            if (item.status === 'VOID' || item.status === 'VOIDED') return;
            
            let amt = parseFloat(item.amount || item.amt || 0);
            
            if (item.type === 'charge') {
                totalBilled += amt;
            } 
            // 🎯 FIX: Includes overpayment and credit to ensure perfect accuracy in all receipts
            else if (item.type === 'payment' || item.type === 'waiver' || item.type === 'discount' || item.type === 'overpayment' || item.type === 'credit') {
                if (item.breakdown && item.breakdown.length > 0) {
                    item.breakdown.forEach(b => totalPaid += parseFloat(b.amt || 0));
                } else {
                    totalPaid += amt;
                }
            }
        });
    }
    
    let balance = totalBilled - totalPaid;
    let balanceDisplay = "";
    
    // 2. Format the balance statement dynamically (From V1)
    if (balance > 0.01) {
        balanceDisplay = `CURRENT ARREARS : $${balance.toFixed(2)}`;
    } else if (balance < -0.01) {
        balanceDisplay = `ACCOUNT CREDIT  : $${Math.abs(balance).toFixed(2)}`;
    } else {
        balanceDisplay = `CURRENT BALANCE : $0.00 (CLEARED)`;
    }

    // 3. Build the Classical/Thermal Receipt HTML (Merged layouts)
    const receiptHtml = `
        <!DOCTYPE html>
        <html>
        <head>
            <title>Event Receipt - ${receiptNo}</title>
            <style>
                body {
    font-family: 'Courier New', Courier, monospace;
    font-size: 13px;
    color: #000;
    width: 300px;
    margin: 0 auto;
    padding: 10px;
    font-weight: bold !important; /* 👈 ADD THIS LINE */
}
                * { color: #000 !important; }
                .text-center { text-align: center; }
                .dashed-line { border-top: 1px dashed #000; margin: 10px 0; }
                .bold { font-weight: bold; }
                table { width: 100%; border-collapse: collapse; font-size: 13px; margin-bottom: 5px; }
                .signature-block { margin-top: 20px; text-align: left; }
                .sig-line { border-bottom: 1px solid #000; width: 180px; display: inline-block; margin-bottom: 5px; margin-top: 25px; }
            </style>
        </head>
        <body>
            <div class="text-center">
                <h2 style="margin: 5px 0; font-size: 18px; text-transform: uppercase;">${schoolName}</h2>
                <div style="font-size: 12px;">Events & Trips Department</div>
            </div>
            
            <div class="dashed-line"></div>
            
            <div>Date: ${dateStr}</div>
            <div>Receipt: ${receiptNo}</div>
            <!-- 👇 Changes to show "Student Name (ID)" -->
            <div>Student: ${student ? (student.name + ' (' + student.id + ')') : 'Unknown'}</div>
            
            <div class="dashed-line"></div>
            
            <table>
                <tr class="bold"><td>DESCRIPTION</td><td align="right">AMOUNT</td></tr>
                <tr>
                    <td style="padding: 3px 0;">${eventName.length > 18 ? eventName.substring(0, 18) + '...' : eventName}</td>
                    <td align="right" style="padding: 3px 0;">$${parseFloat(amountPaid).toFixed(2)}</td>
                </tr>
                ${paymentMethodRows}
            </table>
            
            <div class="dashed-line"></div>
            
            <table class="bold" style="font-size: 15px;">
                <tr>
                    <td>PAID NOW:</td>
                    <td align="right">$${parseFloat(amountPaid).toFixed(2)}</td>
                </tr>
            </table>
            
            <div class="dashed-line"></div>
            
            <div class="text-center bold" style="margin: 15px 0; font-size: 13px; padding: 5px; border: 1px solid #000;">
                ${balanceDisplay}
            </div>

            <!-- 🎯 Signature Block (From V2) -->
            <div class="dashed-line"></div>
            <div class="signature-block">
                <div><strong>Processed By:</strong> ${cashierName}</div>
                <div class="sig-line"></div>
                <div style="font-size: 11px; color: #555;">Cashier Signature</div>
            </div>

            <div class="dashed-line"></div>
            <div class="text-center" style="font-size: 11px;">
                Thank you for your payment!<br>
                System Generated Receipt
            </div>
            
            <script>
                window.onload = function() { 
                    window.print();
                    setTimeout(() => { window.close(); }, 500); 
                }
            </script>
        </body>
        </html>
    `;

    // 4. Open and Print with Popup Blocker Safeguard (From V1)
    const printWindow = window.open('', '_blank', 'width=350,height=600');
    if (printWindow) {
        printWindow.document.open();
        printWindow.document.write(receiptHtml);
        printWindow.document.close();
    } else {
        alert("⚠️ Please allow pop-ups to print receipts.");
    }
};
//-------Instant Charge Payment
// NEW FUNCTION: Adds an instant charge to the ledger so the payment algorithm can pick it up.
window.addInstantCharge = async function(mode = 'waterfall') {
    const studentIdEl = document.getElementById('payId');
    if (!studentIdEl || !studentIdEl.value) return alert("⚠️ Please select a student first.");

    let studentId = studentIdEl.value;
    if (studentId.includes('STU-')) {
        let match = studentId.match(/(STU-\d+)/);
        if (match) studentId = match[1];
    }

    const student = window.students.find(s => String(s.id) === String(studentId));
    if (!student) return alert("⚠️ Student not found.");

    const cashierName = window.currentUser?.user || window.currentUser?.username || window.currentUser?.name || "Admin";
    const descEl = document.getElementById('customChargeDesc');
    const amtEl = document.getElementById('customChargeAmt');
    
    const desc = descEl.value.trim();
    const amt = parseFloat(amtEl.value);

    if (!desc || !amt || amt <= 0) return alert("⚠️ Please enter a valid description and amount.");

    // =======================================
    // MODE 1: WATERFALL (Add to bill)
    // =======================================
    if (mode === 'waterfall') {
        if (!confirm(`📝 ADD TO BILL:\n\nAdd a permanent charge of $${amt.toFixed(2)} for "${desc}" to ${student.name}'s account?`)) return;

        const newCharge = {
            id: 'CHG-' + Date.now(),
            student_id: student.id,
            date: new Date().toISOString().split('T')[0],
            type: 'charge',
            amount: amt,
            description: desc,
            status: 'ACTIVE', // Saved as ACTIVE to match your database schema
            zig: 0
        };

        // ☁️ Save Charge to Supabase IMMEDIATELY
        try {
            const { error: chgError } = await window.supabase.from('student_ledger').insert([newCharge]);
            if (chgError) throw chgError;
        } catch (err) {
            console.error("Supabase Charge Save Error:", err);
            return alert("⚠️ Failed to save charge to database. Error: " + err.message);
        }

        // Add locally & refresh UI
        if (!student.ledger) student.ledger = [];
        student.ledger.push(newCharge);

        descEl.value = '';
        amtEl.value = '';
        document.getElementById('instantChargePreset').value = 'custom';

        if (typeof window.saveData === 'function') window.saveData();
        if (typeof window.previewStudentBalance === 'function') window.previewStudentBalance();

        alert(`✅ Charge permanently added to bill! The Smart Table is updated.`);
        return;
    }

    // =======================================
    // MODE 2: DIRECT PAYMENT (Skip Waterfall)
    // =======================================
    if (mode === 'direct') {
        const methodEl = document.getElementById('payMethod');
        const method = methodEl ? methodEl.value : 'Cash';
        const termCycle = document.getElementById('payCycle') ? document.getElementById('payCycle').value : 'Current Term';

        if (!confirm(`💰 DIRECT PAYMENT:\n\nCharge and IMMEDIATELY pay $${amt.toFixed(2)} for "${desc}" via ${method}?`)) return;

        const paymentDate = new Date().toISOString().split('T')[0];
        const sharedId = Date.now().toString();
        let receiptNo = "RCPT-" + sharedId.slice(-6);

        // 1. Create the permanent Charge record
        const directCharge = {
            id: 'CHG-' + sharedId,
            student_id: student.id,
            date: paymentDate,
            type: 'charge',
            amount: amt,
            description: desc,
            status: 'ACTIVE',
            zig: 0
        };

        // ☁️ 2. Save Charge to Supabase FIRST (To ensure the ledger balances)
        try {
            const { error: chgError } = await window.supabase.from('student_ledger').insert([directCharge]);
            if (chgError) throw chgError;
        } catch (err) {
            console.error("Supabase Direct Charge Error:", err);
            return alert("⚠️ Failed to create the charge record in the database. Error: " + err.message);
        }

        // 3. Build Cloud Payload for the Payment RPC
        const directPayment = {
            id: sharedId,
            student_id: student.id,
            date: paymentDate,
            type: 'payment',
            amount: amt,
            zig: 0,
            method: method,
            desc: desc,
            receiptNo: receiptNo,
            receipt_no: receiptNo,
            processed_by: cashierName,
            breakdown: [{ desc: desc, amt: amt, cleanDesc: desc }]
        };

        const ledgerInserts = [{
            date: paymentDate,
            type: 'payment',
            description: desc,
            amount: amt,
            zig: 0,
            processed_by: cashierName,
            breakdown: [{ desc: desc, amt: amt }]
        }];
        const cloudBreakdowns = [{ description: desc, amount: amt }];

        // ☁️ 4. Save Payment to Supabase via RPC
        try {
            const { data: generatedReceiptNo, error } = await window.supabase.rpc('process_student_payment', {
                p_student_id: student.id,
                p_amount: amt,
                p_zig: 0,
                p_method: method,
                p_cashier: cashierName,
                p_notes: desc,
                p_breakdowns: cloudBreakdowns,
                p_ledger_entries: ledgerInserts
            });

            if (error) throw error;
            if (generatedReceiptNo) receiptNo = generatedReceiptNo;

            directPayment.receiptNo = receiptNo;
            directPayment.receipt_no = receiptNo;

            const { error: cashierArchiveError } = await window.supabaseClient
                .from('payments')
                .update({ processed_by: cashierName, served_by: cashierName })
                .eq('receipt_no', receiptNo);
            if (cashierArchiveError) {
                console.error(`Direct payment ${receiptNo} was saved, but its cashier name could not be stored in the payment archive:`, cashierArchiveError);
                alert(`Direct payment ${receiptNo} was saved, but the cashier name could not be copied to its payment archive. The receipt will use the ledger/audit record when available.`);
            }
            
            if (typeof window.logActivity === 'function') window.logActivity("Processed Direct Payment", `Receipt: ${receiptNo} | Amount: $${amt.toFixed(2)} | Student: ${student.name}`);

        } catch (err) {
            console.error("Supabase Direct Save Error:", err.message);
            return alert("⚠️ Charge was saved, but the Payment transaction failed. Error: " + err.message);
        }

        // 5. Add to local memory & recalculate exact balance
        if (!student.ledger) student.ledger = [];
        student.ledger.push(directCharge);
        student.ledger.push(directPayment);

        let exactBalance = 0;
        student.ledger.forEach(l => {
            if (l.status === 'VOID' || l.status === 'VOIDED') return;
            if (l.type === 'charge' || l.type === 'fee') {
                exactBalance += (parseFloat(l.amount) || 0);
            } else if (['payment', 'discount', 'waiver', 'credit', 'overpayment'].includes(l.type)) {
                exactBalance -= (parseFloat(l.amount) || 0);
            }
        });
        student.balanceOwing = exactBalance;

        // 6. Clean up UI & Sync
        descEl.value = '';
        amtEl.value = '';
        document.getElementById('instantChargePreset').value = 'custom';

        if (typeof window.saveData === 'function') window.saveData();
        if (typeof window.previewStudentBalance === 'function') window.previewStudentBalance();
        if (typeof window.calculateVaultStats === 'function') window.calculateVaultStats();
        if (typeof window.calculateReconciliation === 'function') window.calculateReconciliation();

        // =======================================
        // 🖨️ DIRECT RECEIPT GENERATION 
        // =======================================
        const studentPhone = student.phone || student.cell || 'N/A';
        const studentGrade = student.grade || student.class || 'N/A';
        const displayBal = Math.abs(exactBalance).toFixed(2);
        const balanceLabel = exactBalance < 0 ? 'Total Overpayment Credit:' : 'Amount Still Owed:';

        const wantsPrint = document.getElementById('payPrintReceipt') ? document.getElementById('payPrintReceipt').checked : true;
        const wantsWa = document.getElementById('paySendWa') ? document.getElementById('paySendWa').checked : false;

        if (wantsPrint) {
            let printHTML = `
            <html><head><title>Receipt ${receiptNo}</title>
            <style>
                body { font-family: 'Courier New', Courier, monospace; color: #000 !important; font-weight: bold; max-width: 300px; margin: 0 auto; padding: 10px; font-size: 13px; }
                .center { text-align: center; } table { width: 100%; border-collapse: collapse; margin-bottom: 5px; }
                .divider { border-top: 1px dashed #000; margin: 10px 0; }
            </style></head>
            <body>
                <div class="center">
                    <h2 style="margin: 0 0 5px 0; font-size: 18px;">${window.settings?.schoolName || 'HAVEN ONLINE'}</h2>
                    <div><strong>Direct Payment Receipt</strong></div>
                    <div>Receipt: ${receiptNo}</div>
                    <div>Date: ${paymentDate}</div>
                    <div>Term: ${termCycle}</div>
                </div>
                <div class="divider"></div>
                <div><strong>ID:</strong> ${student.id}</div>
                <div><strong>Student:</strong> ${student.name}</div>
                <div><strong>Grade:</strong> ${studentGrade}</div>
                <div class="divider"></div>
                <table>
                    <tr><td style="padding: 4px 0;"><strong>${desc}</strong></td><td align="right"><strong>$${amt.toFixed(2)}</strong></td></tr>
                </table>
                <div class="divider"></div>
                <table>
                    <tr><td>Total Paid Today:</td><td align="right"><strong>$${amt.toFixed(2)}</strong></td></tr>
                    <tr style="font-size: 15px;">
                        <td style="padding-top: 5px;"><strong>${balanceLabel}</strong></td>
                        <td align="right" style="padding-top: 5px;"><strong>$${displayBal}</strong></td>
                    </tr>
                </table>
                <div class="divider"></div>
                <table><tr><td><strong>Method:</strong></td><td align="right"><strong>${method}</strong></td></tr></table>
                <div class="divider"></div>
                <div class="center" style="font-size: 12px;">
                    <div>Served By: ${cashierName}</div>
                    <div>Thank you!</div>
                </div>
                <script>window.onload=function(){window.print();setTimeout(()=>{window.close();},500);};</script>
            </body></html>`;

            const printWindow = window.open('', '_blank', 'width=400,height=600');
            if (printWindow) {
                printWindow.document.open();
                printWindow.document.write(printHTML);
                printWindow.document.close();
            }
        }

        if (wantsWa && studentPhone !== 'N/A') {
            const waText = `*${window.settings?.schoolName || 'HAVEN ONLINE'} - Direct Payment*\n\n*Receipt:* ${receiptNo}\n*Date:* ${paymentDate}\n*Term:* ${termCycle}\n------------------------\n*Student:* ${student.name}\n*ID:* ${student.id}\n------------------------\n▪️ ${desc}: $${amt.toFixed(2)}\n------------------------\n*Total Paid Today:* $${amt.toFixed(2)}\n*${balanceLabel}* $${displayBal}\n\n*Method:* ${method}\n*Served By:* ${cashierName}`;
            let cleanPhone = studentPhone.toString().replace(/[^0-9+]/g, '');
            if (cleanPhone.startsWith('0')) cleanPhone = '263' + cleanPhone.substring(1);
            window.open(`https://wa.me/${cleanPhone}?text=${encodeURIComponent(waText)}`, '_blank');
        }

        alert("✅ Direct Payment Processed Successfully!");
    }
};

// ==========================================
// 💰 MAIN PAYMENT PROCESSOR
// ==========================================

window.processPayment = async function() {
    if (!window.appDataReady) return alert('Payment is blocked until student, ledger, payment, and billing data are verified.');

    const studentIdEl = document.getElementById('payId'); 
    const methodEl = document.getElementById('payMethod'); 
    const wantsWhatsappEl = document.getElementById('paySendWa'); 
    const wantsPrintEl = document.getElementById('payPrintReceipt'); 
    
    // Identify the current cashier/user logged in
    const cashierName = window.currentUser?.user || window.currentUser?.username || window.currentUser?.name;
    if (!cashierName) return alert("Please log in again before processing a payment.");

    if (!studentIdEl || !studentIdEl.value) return alert("Please enter a Student ID or Name.");

    let studentId = studentIdEl.value;
    if (studentId.includes('STU-')) {
        let match = studentId.match(/(STU-\d+)/);
        if (match) studentId = match[1];
    }

    // 🎯 CRITICAL FIX: Fetch fresh data straight from Supabase to prevent memory duplication bugs!
    let student = null;
    try {
        const { data: freshStudents, error } = await window.supabase
            .from('students')
            .select('*, student_ledger(*)')
            .eq('id', studentId)
            .limit(1);

        if (error) throw error;
        if (!freshStudents || freshStudents.length === 0) {
            return alert("Student record could not be verified in the cloud. No payment was processed.");
        }

        student = freshStudents[0];
        student.ledger = student.student_ledger || [];
        
        // Sync the global memory array so it matches the exact database reality
        let memIndex = window.students.findIndex(s => String(s.id) === String(studentId));
        if (memIndex > -1) {
            window.students[memIndex] = student;
        }
    } catch (err) {
        console.error("Fresh student ledger fetch failed; payment stopped to avoid using stale balances:", err);
        return alert(`Could not verify the latest student balance from the cloud. No payment was processed. Please check the connection and retry.\n\n${err.message || ''}`);
    }
    
    if (!student) return alert("Student not found.");
    
    if (student.billing_plan === 'monthly') {
        console.log("Processing payment for a Monthly Billing student.");
    }
    
    // 🎯 RECALCULATE EXACT BALANCE FROM LEDGER to ensure previous overpayments are detected properly!
    let exactBalance = 0;
    if (student.ledger && Array.isArray(student.ledger)) {
        student.ledger.forEach(l => {
            if (l.status === 'VOID' || l.status === 'VOIDED') return;
            if (l.type === 'charge' || l.type === 'fee') {
                exactBalance += (parseFloat(l.amount) || 0);
            } else if (['payment', 'discount', 'waiver', 'credit', 'overpayment'].includes(l.type)) {
                exactBalance -= (parseFloat(l.amount) || 0);
            }
        });
    }
    const currentBalance = exactBalance;

    const usdEl = document.getElementById('payUsd');
    const zigEl = document.getElementById('payZig');
    const rateEl = document.getElementById('zigRate');

    let amount = 0;
    if (usdEl && usdEl.value) amount += parseFloat(usdEl.value);
    
    let paidZig = 0;
    if (zigEl && zigEl.value) {
        paidZig = parseFloat(zigEl.value) || 0;
        let rate = parseFloat(rateEl?.value) || 1;
        if (rate > 0) amount += (paidZig / rate);
    }

    if (!amount || amount <= 0) return alert("Please enter a valid amount in USD or ZiG.");

    const termCycleEl = document.getElementById('payCycle');
    const selectedTerm = termCycleEl ? termCycleEl.value : "Unknown Term";

    if (!selectedTerm) {
        return alert("⚠️ Please select a valid payment term/cycle before proceeding.");
    }

    const confirmPayment = confirm(`💰 You are about to process a payment for:\n\n👉 "${selectedTerm}"\n\nIs this the correct billing term? Click OK to process or Cancel to change it.`);
    if (!confirmPayment) return;

    // --- ECO CASH CLAIMING ---
    if (window.stagedEcoCashRef && document.getElementById('payMethod').value === 'EcoCash') {
        let tx = window.ecoCashTransactions.find(t => t.ref === window.stagedEcoCashRef);
        if (tx) {
            tx.status = 'claimed';
            tx.claimedBy = student.id; 
            tx.claimedDate = new Date().toISOString().split('T')[0];
        }
        window.stagedEcoCashRef = null;
        if (typeof window.saveEcoCashTransactions === 'function') window.saveEcoCashTransactions();
    }
    
    const checkDiscountInput = document.getElementById('payDiscountUsd');
    const discountAmount = checkDiscountInput && checkDiscountInput.value ? parseFloat(checkDiscountInput.value) : 0;
    
    const actualCashPaid = amount; 
    amount = actualCashPaid + discountAmount; 

    // 🎯 1. NEW EARLY DISCOUNT PREVIEW
    if (discountAmount > 0) {
        let expectedNewBal = currentBalance - amount;
        let discountMsg = `⚠️ DISCOUNT PREVIEW ⚠️\n\n`;
        discountMsg += `Current Balance Owed: $${currentBalance.toFixed(2)}\n`;
        discountMsg += `------------------------\n`;
        discountMsg += `Cash Paid Today: $${actualCashPaid.toFixed(2)}\n`;
        discountMsg += `Discount/Waiver Applied: $${discountAmount.toFixed(2)}\n`;
        discountMsg += `Total Value Cleared: $${amount.toFixed(2)}\n`;
        discountMsg += `------------------------\n`;
        
        if (expectedNewBal < 0) {
            discountMsg += `👉 NEW BALANCE: $0.00 (+ $${Math.abs(expectedNewBal).toFixed(2)} Overpayment Credit)\n\n`;
        } else {
            discountMsg += `👉 NEW BALANCE STILL OWED: $${expectedNewBal.toFixed(2)}\n\n`;
        }
        
        discountMsg += `Click OK to confirm and process this transaction.`;

        if (!confirm(discountMsg)) return; 
    }

   if (amount > currentBalance) {
        // Calculate the credits clearly
        let previousCredit = currentBalance < 0 ? Math.abs(currentBalance) : 0;
        let newCreditAdded = currentBalance > 0 ? (amount - currentBalance) : amount;
        let totalCredit = previousCredit + newCreditAdded;
        
        let msg = `⚠️ ADVANCE PAYMENT DETECTED ⚠️\n\n`;
        
        if (previousCredit > 0) {
            msg += `This student ALREADY has a previous credit/overpayment of: $${previousCredit.toFixed(2)}\n`;
            msg += `Current extra overpayment being added today: $${newCreditAdded.toFixed(2)}\n\n`;
            msg += `👉 TOTAL COMBINED OVERPAYMENT will be: $${totalCredit.toFixed(2)}\n\n`;
        } else {
            msg += `This student only owes $${currentBalance.toFixed(2)}, but is paying/clearing $${amount.toFixed(2)}.\n\n`;
            msg += `👉 This will leave a NEW ADVANCE CREDIT of: $${totalCredit.toFixed(2)} on their account.\n\n`;
        }
        
        msg += `Proceed to bank this credit for future bills?`;
        
        const confirmAdvance = confirm(msg);
        if (!confirmAdvance) return; 
    }

    const method = methodEl ? methodEl.value : 'Cash';
    const wantsWhatsapp = wantsWhatsappEl ? wantsWhatsappEl.checked : false;
    const wantsPrint = wantsPrintEl ? wantsPrintEl.checked : false; 

    // 🎯 2. WHATSAPP TAB OPENS HERE
    let waWindow = null;
    if (wantsWhatsapp) {
        waWindow = window.open('about:blank', '_blank');
        if (waWindow) {
            waWindow.document.write('<html><body><h3 style="font-family:sans-serif; text-align:center; margin-top:20vh;">Preparing WhatsApp receipt... Please wait.</h3></body></html>');
        }
    }

    if (!student.ledger) student.ledger = [];
    const originalLedger = JSON.parse(JSON.stringify(student.ledger));
    const processedBy = window.currentUser?.user || window.currentUser?.username || window.currentUser?.name || 'Admin';
    const originalBalance = student.balanceOwing;

    const paymentDate = new Date().toISOString().split('T')[0];
    let receiptNo = "RCPT-" + Date.now().toString().slice(-6);

   // ==========================================
    // 🧠 UPGRADED DISTRIBUTION ALGORITHM 
    // ==========================================
    let breakdownArr = [];
    let remainingAmount = amount; 
    
    let itemTotals = {};
    let unallocatedPaymentPool = 0; 
    const cleanName = (name) => String(name || '')
        .replace('Enrollment: ', '')
        .replace('Event/Trip: ', '')
        .replace('Payment for ', '')
        .replace('WAIVED: ', '')
        .replace(' (Admin Selected)', '')
        .replace(' (System Auto)', '')
        .trim();
    const getAllocationPriority = description => {
        const normalized = cleanName(description).toLowerCase();
        if (normalized.includes('transport') || normalized.includes('bus')) return 0;
        if (normalized.includes('admission')) return 1;
        if (normalized.includes('tuition') || normalized.includes('term')) return 2;
        return 3;
    };

    // PASS 1: Tally all Active Charges
    student.ledger.forEach(l => {
        if (l.status === 'VOID' || l.status === 'VOIDED') return;
        if (l.type === 'charge' || l.type === 'fee') {
            let amt = parseFloat(l.amount) || 0;
            let cName = (l.description || l.desc || l.notes || l.item || l.category || 'General Charge').trim();
            if (!itemTotals[cName]) itemTotals[cName] = { billed: 0, paid: 0 };
            itemTotals[cName].billed += amt;
        }
    });

    // PASS 2: Match Previous Payments & Breakdowns
    student.ledger.forEach(l => {
        if (l.status === 'VOID' || l.status === 'VOIDED') return;
        if (['payment', 'waiver', 'discount', 'credit', 'overpayment'].includes(l.type)) {
            let paymentTotalAmt = parseFloat(l.amount) || 0;
            let breakdownsToProcess = (l.breakdown && l.breakdown.length > 0) ? l.breakdown : [{ amt: paymentTotalAmt, desc: l.description }];

            breakdownsToProcess.forEach(b => {
                let bAmt = parseFloat(b.amt) || parseFloat(b.amount) || 0;
                let pName = cleanName(b.description || b.desc || b.notes || 'Unallocated');
                let matchedKey = null;
                
                // Prefer an exact charge name; only use a partial match if it is unambiguous.
                const normalizedPaymentName = pName.toLowerCase();
                const chargeNames = Object.keys(itemTotals);
                matchedKey = chargeNames.find(cName => cleanName(cName).toLowerCase() === normalizedPaymentName) || null;
                if (!matchedKey) {
                    const partialMatches = chargeNames.filter(cName => {
                        const normalizedChargeName = cleanName(cName).toLowerCase();
                        return normalizedChargeName.includes(normalizedPaymentName) || normalizedPaymentName.includes(normalizedChargeName);
                    });
                    if (partialMatches.length === 1) matchedKey = partialMatches[0];
                }
                
                // B. Fuzzy Keyword Fallback
                if (!matchedKey) {
                    for (let cName in itemTotals) {
                        let lowerC = cName.toLowerCase(), lowerP = pName.toLowerCase();
                        if (lowerP.includes('tuition') && lowerC.includes('tuition')) { matchedKey = cName; break; }
                        if (lowerP.includes('transport') && lowerC.includes('transport')) { matchedKey = cName; break; }
                        if ((lowerP.includes('shop') || lowerP.includes('uniform')) && (lowerC.includes('shop') || lowerC.includes('uniform'))) { matchedKey = cName; break; }
                    }
                }

                // C. Apply historical payment to the debt
                if (matchedKey) {
                    itemTotals[matchedKey].paid += bAmt; 
                } else {
                    unallocatedPaymentPool += bAmt;
                }
            });
        }
    });

    // PASS 2.5: Sweep trapped excess payments into the unallocated pool
    for (let cName in itemTotals) {
        if (itemTotals[cName].paid > itemTotals[cName].billed) {
            let excess = itemTotals[cName].paid - itemTotals[cName].billed;
            unallocatedPaymentPool += excess;
            itemTotals[cName].paid = itemTotals[cName].billed; // Cap it to prevent phantom debts
        }
    }
    // PASS 3: Waterfall historical unallocated pool over any remaining debts
    if (unallocatedPaymentPool > 0) {
        const orderedHistoricalCharges = Object.keys(itemTotals).sort((a, b) => getAllocationPriority(a) - getAllocationPriority(b));
        for (const item of orderedHistoricalCharges) {
            let amountOwed = itemTotals[item].billed - itemTotals[item].paid;
            if (amountOwed > 0) {
                let alloc = Math.min(amountOwed, unallocatedPaymentPool);
                itemTotals[item].paid += alloc;
                unallocatedPaymentPool -= alloc;
            }
        }
    }

    // PASS 4: Generate the EXACT owed list for the new payment
    let owed = {};
    for (let desc in itemTotals) {
        let amtOwed = itemTotals[desc].billed - itemTotals[desc].paid;
        if (amtOwed > 0.01) owed[desc] = amtOwed;
    }

    // Honor quick-button selections in the order the admin selected them.
    const breakdownList = document.getElementById('payBreakdownList');
    if (breakdownList && breakdownList.children.length > 0) {
        const rows = breakdownList.children;
        for (let i = 0; i < rows.length && remainingAmount > 0; i++) {
            if (rows[i].dataset.quickFee !== 'true') continue;

            const descInput = rows[i].querySelector('.p-desc');
            const amtInput = rows[i].querySelector('.p-amt');
            if (!descInput || !amtInput) continue;

            const selectedDesc = cleanName(descInput.value);
            const requestedAmt = parseFloat(amtInput.value) || 0;
            const normalizedDesc = selectedDesc.toLowerCase();
            if (!normalizedDesc || requestedAmt <= 0) continue;
            let actualKey = Object.keys(owed).find(key => cleanName(key).toLowerCase() === normalizedDesc);

            if (!actualKey) {
                const partialMatches = Object.keys(owed).filter(key => {
                    const normalizedKey = cleanName(key).toLowerCase();
                    return normalizedKey.includes(normalizedDesc) || normalizedDesc.includes(normalizedKey);
                });
                if (partialMatches.length === 1) actualKey = partialMatches[0];
            }

            const amountOwed = actualKey ? Math.max(0, owed[actualKey]) : 0;
            const allocation = Math.min(remainingAmount, requestedAmt, amountOwed);
            if (allocation <= 0) continue;

            breakdownArr.push({ desc: `${actualKey} (Admin Selected)`, amt: allocation, cleanDesc: actualKey });
            remainingAmount -= allocation;
            owed[actualKey] -= allocation;
        }

        // Keep support for any non-quick manual breakdown rows.
        for(let i=0; i < rows.length; i++) {
            let descInput = rows[i].querySelector('.p-desc');
            let amtInput = rows[i].querySelector('.p-amt');

            if (descInput && amtInput && rows[i].dataset.quickFee !== 'true' && remainingAmount > 0) {
                let dVal = descInput.value.trim();
                let requestedAmt = parseFloat(amtInput.value) || 0;

                let actualKey = Object.keys(owed).find(k => k.toLowerCase().includes(dVal.toLowerCase()) || dVal.toLowerCase().includes(k.toLowerCase())) || dVal;
                let actuallyOwed = owed[actualKey] !== undefined ? owed[actualKey] : 0;
                let maxPayable = Math.min(requestedAmt, actuallyOwed);

                if (maxPayable > 0) {
                    let alloc = Math.min(remainingAmount, maxPayable);
                    breakdownArr.push({ desc: `${actualKey} (Admin Selected)`, amt: alloc, cleanDesc: actualKey });
                    remainingAmount -= alloc;
                    if (owed[actualKey]) {
                        owed[actualKey] -= alloc;
                    }
                }
            }
        }
    }

    function autoAllocate(keyMatchStr) {
        let keys = Object.keys(owed).filter(k => k.toLowerCase().includes(keyMatchStr) && owed[k] > 0.01);
        for (let k of keys) {
            if (remainingAmount <= 0) break;
            let alloc = Math.min(remainingAmount, owed[k]);
            breakdownArr.push({ desc: `${k} (System Auto)`, amt: alloc, cleanDesc: k });
            remainingAmount -= alloc;
            owed[k] -= alloc;
        }
    }

    if (remainingAmount > 0) autoAllocate('transport');
    if (remainingAmount > 0) autoAllocate('bus');
    if (remainingAmount > 0) autoAllocate('admission');
    if (remainingAmount > 0) autoAllocate('tuition');
    if (remainingAmount > 0) autoAllocate('term');

    const remainingPriorityTerms = ['fee', 'food', 'meal', 'stationery', 'textbook'];
    remainingPriorityTerms.forEach(term => {
        if (remainingAmount > 0) autoAllocate(term);
    });
    if (remainingAmount > 0) autoAllocate('event');
    if (remainingAmount > 0) autoAllocate('trip');

    // The General Sweep (pays chronological leftovers)
    for (let desc in owed) {
        if (desc.toLowerCase().includes('event') || desc.toLowerCase().includes('trip')) continue; 
        if (owed[desc] > 0.01 && remainingAmount > 0) {
            let alloc = Math.min(remainingAmount, owed[desc]);
            breakdownArr.push({ desc: `${desc} (System Auto)`, amt: alloc, cleanDesc: desc });
            remainingAmount -= alloc;
            owed[desc] -= alloc; 
        }
    }

    if (remainingAmount > 0.01) {
        let leftoverDesc = 'Account Credit / Overpayment (System Auto)';
        breakdownArr.push({ desc: leftoverDesc, amt: remainingAmount, cleanDesc: leftoverDesc });
    }
    if (breakdownArr.length === 0) {
        breakdownArr.push({ desc: 'General Payment', amt: amount, cleanDesc: 'General Payment' });
    }

    // ==========================================
    // SPLIT THE MASTER BREAKDOWN
    // ==========================================
    let discountBreakdown = [];
    let cashBreakdown = [];
    let dPool = discountAmount;

    breakdownArr.forEach(b => {
        if (dPool > 0) {
            let take = Math.min(b.amt, dPool);
            discountBreakdown.push({ desc: b.desc, amt: take, cleanDesc: b.cleanDesc });
            dPool -= take;
            
            let cashLeft = b.amt - take;
            if (cashLeft > 0) {
                cashBreakdown.push({ desc: b.desc, amt: cashLeft, cleanDesc: b.cleanDesc });
            }
        } else {
            cashBreakdown.push({ ...b });
        }
    });

    const paymentReason = cashBreakdown.map(b => b.desc).join(' & ') || 'General Payment';
    const discountReason = discountBreakdown.map(b => b.desc).join(' & ') || 'System Discount';

    let overpayCashAmount = 0;
    let overpayZigAmount = 0;
    let tuitionCashAmount = actualCashPaid;
    let tuitionZigAmount = paidZig;

    let finalCashBreakdown = [];
    let finalOverpayBreakdown = [];

    cashBreakdown.forEach(b => {
        if (b.cleanDesc.includes('Account Credit') || b.cleanDesc.includes('Overpayment')) {
            overpayCashAmount += b.amt;
            finalOverpayBreakdown.push(b);
        } else {
            finalCashBreakdown.push(b);
        }
    });

    if (overpayCashAmount > 0 && actualCashPaid > 0) {
        let zigRatio = paidZig / actualCashPaid;
        overpayZigAmount = overpayCashAmount * zigRatio;
        tuitionZigAmount = paidZig - overpayZigAmount;
        tuitionCashAmount = actualCashPaid - overpayCashAmount;
    }

    // ==========================================
    // 💾 SAVE PAYMENT & DISCOUNT RECORDS 
    // ==========================================
    const sharedId = Date.now().toString();

    if (tuitionCashAmount > 0 || overpayCashAmount === 0) {
        student.ledger.push({
            id: sharedId,
            student_id: student.id,        
            date: paymentDate,
            type: 'payment',
            amount: parseFloat(tuitionCashAmount.toFixed(2)), 
            zig: parseFloat(tuitionZigAmount.toFixed(2)), 
            method: method,
            desc: finalCashBreakdown.map(b => b.desc).join(' & ') || 'General Payment',
            receiptNo: receiptNo,          
            receipt_no: receiptNo,         
            breakdown: finalCashBreakdown,
            processed_by: cashierName
        });
    }

    if (overpayCashAmount > 0) {
        student.ledger.push({
            id: "OVP-" + sharedId,
            student_id: student.id,        
            date: paymentDate,
            type: 'overpayment',
            amount: parseFloat(overpayCashAmount.toFixed(2)), 
            zig: parseFloat(overpayZigAmount.toFixed(2)), 
            method: method,
            desc: 'Account Credit / Overpayment',
            receiptNo: receiptNo,          
            receipt_no: receiptNo,         
            breakdown: finalOverpayBreakdown,
            processed_by: cashierName
        });
    }

    if (discountAmount > 0) {
        student.ledger.push({
            id: "DISC-" + sharedId,
            student_id: student.id,
            date: paymentDate,
            type: 'discount',
            amount: parseFloat(discountAmount.toFixed(2)),
            method: 'System Discount',
            desc: "Discount Applied: " + discountReason, 
            receiptNo: receiptNo,
            receipt_no: receiptNo,
            breakdown: discountBreakdown,
            processed_by: cashierName
        });
    }

    const cloudPaymentRecord = {
        id: parseInt(sharedId.slice(-9)), 
        student_id: student.id,
        date: paymentDate,
        amount: parseFloat(actualCashPaid.toFixed(2)), 
        zig: parseFloat(paidZig.toFixed(2)), 
        method: method,
        receipt_no: receiptNo,
        notes: paymentReason,                
        category: 'Fees',
        status: 'PAID',
        served_by: cashierName,
        processed_by: cashierName
    };

    // ==========================================
    // ☁️ SUPABASE INSERTS & EXPENSE LOGGING (RPC)
    // ==========================================
    const cloudBreakdownRecords = breakdownArr.map(b => ({
        description: b.desc,
        amount: parseFloat(b.amt.toFixed(2))
    }));

    const ledgerInserts = [];

    if (tuitionCashAmount > 0 || overpayCashAmount === 0) {
        ledgerInserts.push({
            date: paymentDate,
            type: 'payment',
            description: finalCashBreakdown.map(b => b.desc).join(' & ') || 'General Payment',
            amount: parseFloat(tuitionCashAmount.toFixed(2)),
            zig: parseFloat(tuitionZigAmount.toFixed(2)),
            breakdown: finalCashBreakdown,
            processed_by: cashierName
        });
    }

    if (overpayCashAmount > 0) {
        ledgerInserts.push({
            date: paymentDate, 
            type: 'overpayment',
            description: 'Account Credit / Overpayment',
            amount: parseFloat(overpayCashAmount.toFixed(2)),
            zig: parseFloat(overpayZigAmount.toFixed(2)),
            breakdown: finalOverpayBreakdown,
            processed_by: cashierName
        });
    }

    if (discountAmount > 0) {
        ledgerInserts.push({
            date: paymentDate, 
            type: 'discount',
            description: `Discount Applied: ${discountReason}`,
            amount: parseFloat(discountAmount.toFixed(2)),
            zig: 0,
            breakdown: discountBreakdown,
            processed_by: cashierName
        });
    }

    try {
        const { data: generatedReceiptNo, error } = await window.supabase.rpc('process_student_payment', {
            p_student_id: student.id,
            p_amount: parseFloat(actualCashPaid.toFixed(2)),
            p_zig: parseFloat(paidZig.toFixed(2)),
            p_method: method,
            p_cashier: cashierName,
            p_notes: paymentReason,
            p_breakdowns: cloudBreakdownRecords,
            p_ledger_entries: ledgerInserts
        });

        if (error) throw error;

        receiptNo = generatedReceiptNo;

        const { error: cashierArchiveError } = await window.supabaseClient
            .from('payments')
            .update({ processed_by: cashierName, served_by: cashierName })
            .eq('receipt_no', receiptNo);
        if (cashierArchiveError) {
            console.error(`Payment ${receiptNo} was saved, but its cashier name could not be stored in the payment archive:`, cashierArchiveError);
            alert(`Payment ${receiptNo} was saved, but the cashier name could not be copied to its payment archive. The receipt will use the ledger/audit record when available.`);
        }

        student.ledger.forEach(entry => {
            if (entry.id && entry.id.includes(sharedId)) {
                entry.receiptNo = receiptNo;
                entry.receipt_no = receiptNo;
            }
        });

        if (typeof window.logActivity === 'function') {
            window.logActivity("Processed Payment", `Receipt: ${receiptNo} | Amount: $${actualCashPaid.toFixed(2)} | Student: ${student.name}`);
        }

    } catch (err) {
        console.error("Supabase Save Error:", err.message);
        student.ledger = originalLedger;
        student.balanceOwing = originalBalance;
        student.balance_owing = originalBalance;
        return alert("Transaction failed. No local payment was kept. Error: " + err.message);
    }

    let receiptDataVerified = false;
    try {
        const { data: latestLedger, error } = await window.supabaseClient
            .from('student_ledger')
            .select('*')
            .eq('student_id', student.id);
        if (error) throw error;

        const receiptKey = String(receiptNo || '').toUpperCase();
        const savedReceiptEntries = (latestLedger || []).filter(entry =>
            String(entry.receipt_no || entry.receiptNo || '').toUpperCase() === receiptKey &&
            !['VOID', 'VOIDED', 'REVERSAL'].includes(String(entry.status || '').toUpperCase())
        );
        if (!receiptKey || savedReceiptEntries.length === 0) {
            throw new Error('The saved receipt entries were not returned by the cloud.');
        }

        const savedCash = savedReceiptEntries
            .filter(entry => ['payment', 'overpayment', 'credit'].includes(String(entry.type || '').toLowerCase()))
            .reduce((total, entry) => total + (parseFloat(entry.amount) || 0), 0);
        const savedDiscount = savedReceiptEntries
            .filter(entry => String(entry.type || '').toLowerCase() === 'discount')
            .reduce((total, entry) => total + (parseFloat(entry.amount) || 0), 0);
        const savedBreakdown = savedReceiptEntries.flatMap(entry =>
            Array.isArray(entry.breakdown) ? entry.breakdown : []
        );
        const savedBreakdownTotal = savedBreakdown.reduce((total, item) =>
            total + (parseFloat(item.amt || item.amount) || 0), 0
        );
        const expectedValueCleared = actualCashPaid + discountAmount;

        if (
            Math.abs(savedCash - actualCashPaid) > 0.01 ||
            Math.abs(savedDiscount - discountAmount) > 0.01 ||
            savedBreakdown.length === 0 ||
            Math.abs(savedBreakdownTotal - expectedValueCleared) > 0.01
        ) {
            throw new Error('The saved cash, discount, or itemized allocation does not match the transaction.');
        }

        student.ledger = latestLedger || [];
        breakdownArr.splice(0, breakdownArr.length, ...savedBreakdown.map(item => ({
            desc: item.desc || item.description || 'Payment Allocation',
            amt: parseFloat(item.amt || item.amount) || 0,
            cleanDesc: item.cleanDesc || item.desc || item.description || 'Payment Allocation'
        })));
        receiptDataVerified = true;
    } catch (err) {
        console.error("Payment was saved, but its receipt could not be verified against the cloud ledger:", err);
    }

    // ==========================================
    // 💸 LOCAL EXPENSE LOGGING
    // ==========================================
    if (discountAmount > 0) {
        const discountExpense = {
            id: 'EXP-DISC-' + Date.now(),
            date: paymentDate,
            desc: `System Discount Issued to ${student.name}`, 
            amount: parseFloat(discountAmount.toFixed(2)),
            payment_method: 'Discount Allocation' 
        };

        if (!window.expenses) window.expenses = [];
        window.expenses.push(discountExpense);
        if (typeof window.saveExpenses === 'function') window.saveExpenses();
    }

  // ==========================================
    // 🖥️ LOCAL UI UPDATES & REFRESHES
    // ==========================================
    const newBalance = typeof window.calculateStudentBalance === 'function'
        ? window.calculateStudentBalance(student)
        : currentBalance - amount;
    student.balanceOwing = newBalance;
    student.balance_owing = newBalance;
    window.changedStudentIds = [String(student.id)];

    const modal = document.getElementById('whatsappPaymentModal');
    if (modal) modal.style.display = 'none';

    if (typeof window.saveData === 'function') window.saveData(); 

    try {
        if (typeof window.filterDirectory === 'function') window.filterDirectory();
        if (typeof window.updateDashboard === 'function') window.updateDashboard();
        if (typeof window.renderPendingReferences === 'function') window.renderPendingReferences();
        if (typeof window.renderExpenses === 'function') window.renderExpenses();
        if (typeof window.calculateReconciliation === 'function') window.calculateReconciliation();
        if (typeof window.calculateVaultStats === 'function') window.calculateVaultStats();
    } catch (error) {
        console.error("Payment processed, but a UI refresh trigger failed:", error);
    }

    if (!receiptDataVerified) {
        const fieldsToClear = ['payUsd', 'payZig', 'payId', 'financeEcoCashRef', 'payDiscountUsd'];
        fieldsToClear.forEach(id => {
            const field = document.getElementById(id);
            if (field) field.value = '';
        });
        const breakdownList = document.getElementById('payBreakdownList');
        if (breakdownList) breakdownList.innerHTML = '';
        if (typeof window.updatePaymentLiveTotals === 'function') window.updatePaymentLiveTotals();
        if (typeof window.previewStudentBalance === 'function') window.previewStudentBalance();
        return alert(`Payment was saved as receipt ${receiptNo}, but the saved itemized figures could not be verified. No receipt was printed or sent. Do not process the payment again; sync the account and reprint this receipt.`);
    }

   // ==========================================
    // 🖨️ GENERATE UNIFIED RECEIPTS (PRINT & WHATSAPP)
    // ==========================================
    const termCycle = document.getElementById('payCycle') ? document.getElementById('payCycle').value : 'Current Term';
    const studentPhone = student.phone || student.cell || 'N/A';
    const studentGrade = student.grade || student.class || 'N/A';
    
    const hadPreviousCredit = currentBalance < 0;
    const hasTotalCredit = newBalance < 0;
    
    const displayPrevBalance = Math.abs(currentBalance).toFixed(2);
    const displayNewBalance = Math.abs(newBalance).toFixed(2);

    const waPrevBalance = hadPreviousCredit 
        ? `*Previous Overpayment:* $${displayPrevBalance}`
        : `*Previous Balance:* $${displayPrevBalance}`;

    const waTotalBalance = hasTotalCredit 
        ? `*TOTAL COMBINED OVERPAYMENT:* $${displayNewBalance}` 
        : `*Amount Still Owed:* $${displayNewBalance}`;
    
    let waStandardText = "";
    let waEventText = "";
    let waShopText = "";
    
    let htmlStandardRows = "";
    let htmlEventRows = "";
    let htmlShopRows = "";

    breakdownArr.forEach(b => {
        let stillOwed = owed[b.cleanDesc] || 0;
        let shortText = b.desc.includes('Account Credit') ? `[Banked for Future]` : (stillOwed > 0.01 ? `[Short: $${stillOwed.toFixed(2)}]` : `[Cleared]`);
        let descLower = (b.desc || "").toLowerCase();
        let isEvt = descLower.includes('event') || descLower.includes('trip');
        let isShp = descLower.includes('shop') || descLower.includes('uniform');

        let waLine = `▪️ ${b.desc}: $${b.amt.toFixed(2)} ${shortText}\n`;
        let rowHtml = `
        <tr>
            <td style="padding: 4px 0; border-bottom: 1px dashed #000;">
                <strong>${b.desc}</strong><br>
                <small style="color:#555;">${shortText}</small>
            </td>
            <td style="text-align: right; border-bottom: 1px dashed #000; vertical-align: top; padding: 4px 0; font-size: 14px;">
                <strong>$${b.amt.toFixed(2)}</strong>
            </td>
        </tr>`;

        if (isEvt) { 
            htmlEventRows += rowHtml; waEventText += waLine;
        } else if (isShp) { 
            htmlShopRows += rowHtml; waShopText += waLine;
        } else { 
            htmlStandardRows += rowHtml; waStandardText += waLine;
        }
    });

    let waBreakdownText = "";
    if (waStandardText !== "") waBreakdownText += `*Standard Tuition & Fees:*\n${waStandardText}\n`;
    if (waEventText !== "") waBreakdownText += `*Events & Trips:*\n${waEventText}\n`;
    if (waShopText !== "") waBreakdownText += `*Uniforms & Shop Matters:*\n${waShopText}\n`;

    const receiptText = `*${window.settings?.schoolName || 'HAVEN ONLINE'} - Official Receipt*

*Receipt No:* ${receiptNo}
*Date:* ${paymentDate}
*Term:* ${termCycle}
------------------------
*Student:* ${student.name}
*Student ID:* ${student.id}
*Grade/Class:* ${studentGrade}
------------------------
${waBreakdownText}------------------------
${waPrevBalance}
*Cash Received Today:* $${actualCashPaid.toFixed(2)}
${discountAmount > 0 ? `*Discount Applied:* -$${discountAmount.toFixed(2)}\n` : ''}------------------------
${waTotalBalance}

*Method:* ${method}
*Served By:* ${cashierName}
Thank you!`;

    // EXECUTE WHATSAPP 
    if (wantsWhatsapp) {
        const phone = student.phone || student.cell;
        if (phone && phone.trim() !== "") {
            let cleanPhone = phone.toString().replace(/[^0-9+]/g, '');
            if (cleanPhone.startsWith('0')) cleanPhone = '263' + cleanPhone.substring(1);
            const waLink = `https://wa.me/${cleanPhone}?text=${encodeURIComponent(receiptText)}`;
            
            if (waWindow) {
                waWindow.location.href = waLink;
            } else {
                window.open(waLink, '_blank');
            }
        } else {
            if (waWindow) waWindow.close(); 
            alert(`⚠️ Cannot send WhatsApp because no phone number is saved for ${student.name}.`);
        }
    } else if (waWindow) {
        waWindow.close();
    }

    // EXECUTE PRINT SECOND
    if (wantsPrint) {
        let printHTML = `
        <html>
        <head>
            <title>Receipt ${receiptNo}</title>
            <style>
                body { font-family: 'Courier New', Courier, monospace; color: #000 !important; font-weight: bold; max-width: 300px; margin: 0 auto; padding: 10px; font-size: 13px; }
                * { color: #000 !important; font-weight: bold !important; }
                .center { text-align: center; }
                table { width: 100%; border-collapse: collapse; font-size: 13px; margin-bottom: 5px; }
                .divider { border-top: 1px dashed #000; margin: 10px 0; }
                .details-box { margin-bottom: 8px; }
                .section-title { font-weight: bold; font-size: 13px; margin-top: 8px; text-transform: uppercase; border-bottom: 1px solid #000; padding-bottom: 2px; }
            </style>
        </head>
        <body>
            <div class="center">
                <h2 style="margin: 0 0 5px 0; font-size: 18px;"><strong>${window.settings?.schoolName || 'HAVEN ONLINE'}</strong></h2>
                <div><strong>Official Receipt</strong></div>
                <div>Receipt: <strong>${receiptNo}</strong></div>
                <div>Date: <strong>${paymentDate}</strong></div>
                <div>Term: <strong>${termCycle}</strong></div>
            </div>
            
            <div class="divider"></div>

            <div class="details-box">
                <div><strong>Student ID:</strong> ${student.id}</div>
                <div><strong>Student:</strong> ${student.name}</div>
                <div><strong>Grade/Class:</strong> ${studentGrade}</div>
                <div><strong>Contact:</strong> ${studentPhone}</div>
            </div>
            
            <div class="divider"></div>

            ${htmlStandardRows !== '' ? `<div class="section-title">Standard Tuition & Fees</div><table>${htmlStandardRows}</table>` : ''}
            ${htmlEventRows !== '' ? `<div class="section-title">Events & Trips</div><table>${htmlEventRows}</table>` : ''}
            ${htmlShopRows !== '' ? `<div class="section-title">Uniforms & Shop Matters</div><table>${htmlShopRows}</table>` : ''}

            <div class="divider"></div>

            <table style="font-weight: bold; font-size: 14px;">
                <tr>
                    <td>${hadPreviousCredit ? 'Previous Overpayment:' : 'Previous Balance:'}</td>
                    <td align="right"><strong>$${displayPrevBalance}</strong></td>
                </tr>
                <tr>
                    <td>Cash Received Today:</td>
                    <td align="right"><strong>$${actualCashPaid.toFixed(2)}</strong></td>
                </tr>
                ${discountAmount > 0 ? `
                <tr>
                    <td>Discount Applied:</td>
                    <td align="right"><strong>-$${discountAmount.toFixed(2)}</strong></td>
                </tr>` : ''}
                <tr style="font-size: 15px;">
                    <td style="padding-top: 5px;"><strong>${hasTotalCredit ? 'TOTAL COMBINED OVERPAYMENT:' : 'Amount Still Owed:'}</strong></td>
                    <td align="right" style="padding-top: 5px;"><strong>$${displayNewBalance}</strong></td>
                </tr>
            </table>

            <div class="divider"></div>
            
            <table>
                <tr>
                    <td><strong>Method:</strong></td>
                    <td align="right"><strong>${method}</strong></td>
                </tr>
            </table>
            
            <div class="divider"></div>
            
            <div class="center" style="font-size: 12px;">
                <div><strong>Served By: ${cashierName}</strong></div>
                <div>Thank you for your payment!</div>
            </div>

            <script>
                window.onload = function() { 
                    window.print(); 
                    setTimeout(() => { window.close(); }, 500); 
                };
            </script>
        </body>
        </html>`;
        const printWindow = window.open('', '_blank', 'width=400,height=600');
        if (printWindow) {
            printWindow.document.open();
            printWindow.document.write(printHTML); 
            printWindow.document.close();
        } else {
            alert("⚠️ Receipt popup was blocked! Please enable popups for this site.");
        }
    }

    // ==========================================
    // UI RESET & ALERTS
    // ==========================================
    const usdInput = document.getElementById('payUsd');
    const zigInput = document.getElementById('payZig');
    const studentIdInput = document.getElementById('payId');
    const ecoRefInput = document.getElementById('financeEcoCashRef');
    const breakdownListToClear = document.getElementById('payBreakdownList');
    const discountInputClean = document.getElementById('payDiscountUsd');

    if (usdInput) usdInput.value = '';
    if (zigInput) zigInput.value = '';
    if (studentIdInput) studentIdInput.value = ''; 
    if (ecoRefInput) ecoRefInput.value = ''; 
    if (discountInputClean) discountInputClean.value = '';
    if (breakdownListToClear) breakdownListToClear.innerHTML = '';

    if (typeof window.updatePaymentLiveTotals === 'function') window.updatePaymentLiveTotals();
    if (typeof window.previewStudentBalance === 'function') window.previewStudentBalance();

    setTimeout(() => {
        alert("✅ Payment Saved Successfully!");
    }, 500);
};

window.autoFillGeneralPayment = function() {
    // 1. Get the selected student
    const studentIdEl = document.getElementById('payId');
    if (!studentIdEl || !studentIdEl.value) return;

    let studentId = studentIdEl.value;
    if (studentId.includes('STU-')) {
        let match = studentId.match(/(STU-\d+)/);
        if (match) studentId = match[1];
    }

    const student = (window.students || []).find(s => String(s.id) === String(studentId));
    if (!student) return;

    // 2. Get the total balance the student owes
    let totalDue = parseFloat(student.balanceOwing) || 0;
    if (totalDue <= 0) return; // Nothing to discount if they owe $0

    // 3. Get the discount entered
    const discountInput = document.getElementById('payDiscountUsd');
    let discount = parseFloat(discountInput.value) || 0;

    // Safety: Prevent the discount from being larger than what they actually owe
    if (discount > totalDue) {
        discount = totalDue;
        discountInput.value = discount; 
    }

    // 4. Auto-adjust the USD payment box to exactly match the remaining balance
    const usdInput = document.getElementById('payUsd');
    if (usdInput) {
        let newTotal = totalDue - discount;
        usdInput.value = newTotal > 0 ? newTotal.toFixed(2) : '';
    }
    
    // 5. Instantly update the live preview balances on the screen (if applicable)
    if (typeof window.previewStudentBalance === 'function') {
        window.previewStudentBalance();
    }
};


// Function 1: Parent submits the reference from their portal
// ==========================================
// 💳 PARENT SUBMISSION PIPELINE (WITH STRICT BALANCE RULE)
// ==========================================

// Function 2: Admin views the Ledger
// 1. THE MERGED UI RENDERER (Based on the advanced Version 3)
window.renderPendingReferences = async function() {
    const tbody = document.getElementById('pendingReferencesTableBody');
    if (!tbody) return;

    // Show Loading State
    tbody.innerHTML = `<tr><td colspan="5" style="text-align:center; padding: 20px; color: #3498db;">🔄 Fetching Master Ledger Data...</td></tr>`;

    const filterDrop = document.getElementById('pppsFilter');
    const filterVal = filterDrop ? filterDrop.value : 'pending';

    let allRecords = [];
    let seenRefs = new Set(); 

    // Gather Local Pending Records (From Parent Portal Submissions)
    window.ecoCashTransactions = window.ecoCashTransactions || [];
    window.ecoCashTransactions.forEach(t => {
        if (t.studentId) {
            allRecords.push({
                date: t.date || new Date().toISOString().split('T')[0],
                ref: String(t.ref).toUpperCase(),
                studentId: t.studentId,
                studentName: t.studentName || "Unknown",
                grade: t.grade || "N/A",
                amount: parseFloat(t.amount) || 0,
                zigAmount: parseFloat(t.zigAmount) || 0, // 🎯 FIX: Explicitly grab the ZiG amount
                status: t.status === 'claimed' ? 'PAID' : 'PENDING'
            });
            seenRefs.add(String(t.ref).toUpperCase());
        }
    });

    // Gather Historical Cloud Records (From Master Payments Chamber)
    if (navigator.onLine && typeof supabaseClient !== 'undefined') {
        try {
            const { data, error } = await supabaseClient.from('payments').select('*').order('date', { ascending: false });

            if (data && !error) {
                data.forEach(p => {
                    const receipt = String(p.receipt_no || "").toUpperCase();
                    const method = String(p.method || "").toLowerCase();
                    const desc = String(p.notes || "").toLowerCase();
                    
                    const isDigital = method.includes('ecocash') || method.includes('bank') || desc.includes('ecocash') || receipt.startsWith('MP');
                    const isRefNumber = receipt !== "" && !receipt.startsWith('REC-');

                    if ((isDigital || isRefNumber) && !seenRefs.has(receipt)) {
                        let sName = "Unknown Student";
                        let sGrade = "N/A";
                        if (window.students) {
                            let st = window.students.find(s => String(s.id) === String(p.student_id));
                            if (st) {
                                sName = st.name;
                                sGrade = st.grade || st.class || "N/A";
                            }
                        }
                        
                        allRecords.push({
                            date: p.date,
                            ref: receipt,
                            studentId: p.student_id,
                            studentName: sName,
                            grade: sGrade,
                            amount: parseFloat(p.amount) || 0,
                            zigAmount: 0, // Historical DB pulls are already mapped to effective USD in payments table
                            status: p.status === 'VOID' ? 'VOID' : 'PAID'
                        });
                        seenRefs.add(receipt);
                    }
                });
            }
        } catch (err) {
            console.warn("Cloud fetch failed for PPPS ledger:", err);
        }
    }

    // Apply Filters (Today, Week, Month)
    const todayStr = new Date().toISOString().split('T')[0];
    const dToday = new Date(todayStr);

    let filtered = allRecords.filter(t => {
        if (filterVal === 'pending') return t.status === 'PENDING';
        if (filterVal === 'today') return t.date === todayStr;
        if (filterVal === 'week') {
            const diffTime = Math.abs(dToday - new Date(t.date));
            return Math.ceil(diffTime / (1000 * 60 * 60 * 24)) <= 7;
        }
        if (filterVal === 'month') return t.date.substring(0, 7) === todayStr.substring(0, 7); 
        return true; 
    });

    // Sort newest to top
    filtered.sort((a, b) => new Date(b.date) - new Date(a.date));

    // Render Table
    if (filtered.length === 0) {
        let msg = filterVal === 'pending' ? "No pending reference submissions. All caught up!" : "No records found for the selected time filter.";
        tbody.innerHTML = `<tr><td colspan="5" style="text-align:center; padding: 20px; color: #7f8c8d;">${msg}</td></tr>`;
        return;
    }

    let html = '';
    filtered.forEach(t => {
        const statusBadge = t.status === 'PENDING' 
            ? `<span style="background: #f39c12; color: white; padding: 3px 8px; border-radius: 12px; font-size: 11px;">Pending</span>`
            : (t.status === 'VOID' ? `<span style="background: #e74c3c; color: white; padding: 3px 8px; border-radius: 12px; font-size: 11px;">Voided</span>` : `<span style="background: #27ae60; color: white; padding: 3px 8px; border-radius: 12px; font-size: 11px;">Processed</span>`);
            
        const actionBtn = t.status === 'PENDING'
            ? `<button class="btn-standard btn-success" style="padding: 6px 12px; font-size: 12px; border-radius: 20px;" onclick="approvePendingReference('${t.ref}', this)">✅ Verify & Process</button>`
            : `<button class="btn-standard" style="padding: 6px 12px; font-size: 12px; border-radius: 20px; background: #95a5a6; color: white; cursor: not-allowed;" disabled>🔒 Locked in Cloud</button>`;

        // 🎯 FIX: Intelligently display whether it's ZiG or USD on the Admin Table!
        let displayAmount = t.zigAmount > 0 
            ? `<span style="color: #27ae60; font-weight: bold;">ZiG ${t.zigAmount.toFixed(2)}</span>` 
            : `<span style="color: #2c3e50; font-weight: bold;">$${t.amount.toFixed(2)}</span>`;

        html += `
            <tr style="border-bottom: 1px solid #ecf0f1;">
                <td style="padding: 10px;">${t.date}<br>${statusBadge}</td>
                <td style="padding: 10px; font-weight: bold; color: #2980b9;">${t.ref}</td>
                <td style="padding: 10px;">
                    <strong>${t.studentName}</strong><br>
                    <span style="font-size: 11px; color: #7f8c8d;">ID: ${t.studentId} | Class: ${t.grade}</span>
                </td>
                <td style="padding: 10px; text-align: right;">${displayAmount}</td>
                <td style="padding: 10px; text-align: center;">${actionBtn}</td>
            </tr>
        `;
    });
    tbody.innerHTML = html;
};

window.approvePendingReference = async function(refCode, btnElement) {
    // 1. Locate the pending EcoCash submission
    window.ecoCashTransactions = window.ecoCashTransactions || [];
    const tx = window.ecoCashTransactions.find(t => t.ref.toUpperCase() === refCode.toUpperCase());
    
    if (!tx) return alert("❌ Submission not found for reference: " + refCode);
    if (tx.status === 'claimed') return alert("⚠️ This reference has already been processed.");
    
    // 2. Locate the Student
    const student = window.students.find(s => String(s.id) === String(tx.studentId));
    if (!student) return alert(`❌ Linked Student ID (${tx.studentId}) not found in database.`);
    if (!student.ledger) student.ledger = [];
    const originalLedger = JSON.parse(JSON.stringify(student.ledger));

    const dateStr = new Date().toISOString().split('T')[0];
    const payId = 'PAY-' + tx.ref;
    const receiptNo = "REC-" + Math.floor(Math.random() * 900000 + 100000); 
    
    // 🎯 FIX: Extract ZiG properly and calculate effective USD for debt clearing
    const currentZigRate = parseFloat(document.getElementById('zigRate')?.value) || window.settings?.zigRate || 13.56;
    let rawUsd = parseFloat(tx.amount || 0);
    let rawZig = parseFloat(tx.zigAmount || 0);
    let effectiveUsd = rawZig > 0 ? (rawZig / currentZigRate) : rawUsd;

    if (effectiveUsd <= 0) return alert("❌ Cannot process a $0 amount.");

    const hasTargetEvent = Boolean(tx.targetEvent && tx.targetEvent.trim() !== "");
    const target = (tx.targetEvent || "").toLowerCase();
    
    const isShop = target.includes('shop') || target.includes('uniform');
    const isEvent = hasTargetEvent || target.includes('event') || target.includes('trip');

    let finalDesc = `Verified Online Payment [Ref: ${tx.ref}]`;
    let finalCategory = 'Tuition';
    let pendingEventCharge = null;
    let eventChargeSaved = false;

    // ==========================================
    // SCENARIO A: STANDARD TUITION (Mismatch Check)
    // ==========================================
    if (!isEvent && !isShop) {
        let totalOwed = 0;
        student.ledger.forEach(entry => {
            if (entry.status === 'VOID' || entry.status === 'VOIDED') return;
            const type = (entry.type || '').toLowerCase();
            if (type === 'charge' || type === 'fee') totalOwed += parseFloat(entry.amount) || 0;
            else if (type === 'payment' || type === 'discount' || type === 'waiver') totalOwed -= parseFloat(entry.amount) || 0;
        });

        // 🎯 FIX: Check mismatch against the calculated USD equivalent
        const debtDifference = Math.abs(totalOwed - effectiveUsd);
        
        if (debtDifference > 0.01) {
            alert(`⚠️ ATTENTION: TUITION AMOUNT MISMATCH\n\nStudent Owes: $${totalOwed.toFixed(2)}\nAmount Paid: $${effectiveUsd.toFixed(2)}\n\nBecause this is general tuition and the amounts do not match, it requires manual cashier allocation. Redirecting...`);
            
            const refInput = document.getElementById('financeEcoCashRef');
            if (refInput) {
                refInput.value = tx.ref;
                if (typeof window.autoFillFinanceEcoCash === 'function') window.autoFillFinanceEcoCash();
                const payTab = document.getElementById('nav-finance') || document.querySelector('[onclick*="finance"]');
                if (payTab) payTab.click();
            }
            return; 
        }
    }

    // ==========================================
    // SCENARIO B: EVENTS, TRIPS, AND SHOP
    // ==========================================
    if (isEvent) {
        finalDesc = `Event/Trip: ${tx.targetEvent}`;
        finalCategory = 'Events';
        
        const existingCharge = student.ledger.find(item => item.type === 'charge' && (item.desc === finalDesc || item.description === finalDesc) && item.status !== 'VOID');
        if (!existingCharge) {
            const chargeId = 'CHG-' + tx.ref;
            pendingEventCharge = {
                id: chargeId, date: dateStr, type: 'charge', amount: effectiveUsd, 
                desc: finalDesc, term: 'Auto', status: 'ACTIVE'
            };
        }
    } else if (isShop) {
        finalDesc = `Shop/Uniform Payment`;
        finalCategory = 'Shop';
    }

    // 4. Final Processing Confirmation (Shows ZiG dynamically)
    let displayPromptAmount = rawZig > 0 ? `ZiG ${rawZig.toFixed(2)}` : `$${effectiveUsd.toFixed(2)}`;
    if (!confirm(`✅ VERIFY & PROCESS\n\nRoute: ${finalCategory}\nItem: ${tx.targetEvent || 'General Fee'}\nAmount: ${displayPromptAmount}\n\nProceed to finalize and generate official receipt?`)) return;

    // 5. Create the Payment Object (🎯 Saves BOTH USD and ZiG to memory)
    const paymentObj = {
        id: payId,
        date: dateStr,
        type: 'payment',
        amount: effectiveUsd, // USD for debt tracking
        zig: rawZig,          // RAW ZiG for the Vault!
        desc: finalDesc,
        receiptNo: receiptNo,
        method: 'EcoCash', 
        term: 'Auto',
        breakdown: [{ desc: finalDesc, amt: effectiveUsd }],
        status: 'ACTIVE',
        processed_by: processedBy
    };
    student.ledger.push(paymentObj);

    // 6. 🚀 SYNC TO SUPABASE CLOUD (Vault & Master Ledger)
    const originalText = btnElement ? btnElement.innerText : 'Process';
    if (btnElement) btnElement.innerText = "⏳ Processing...";
    let referenceClaimed = false;
    let paymentLedgerSaved = false;
    let paymentRecordSaved = false;
    const paymentRecordId = Date.now();

    try {
        if (!navigator.onLine || !window.supabaseClient) {
            throw new Error('An active cloud connection is required to approve this payment.');
        }

        referenceClaimed = await window.claimPaymentReference(tx.ref, student.id, 'parent-reference');
        if (!referenceClaimed) {
            throw new Error(`Payment reference ${tx.ref} is already claimed. No payment was recorded.`);
        }

        if (pendingEventCharge) {
            const { error: chargeError } = await window.supabaseClient.from('student_ledger').insert([{
                id: pendingEventCharge.id, student_id: student.id, date: pendingEventCharge.date, type: 'charge',
                description: pendingEventCharge.desc, amount: pendingEventCharge.amount,
                status: pendingEventCharge.status, term: pendingEventCharge.term
            }]);
            if (chargeError) throw new Error('Event charge save failed: ' + chargeError.message);
            eventChargeSaved = true;
            student.ledger.push(pendingEventCharge);
        }

        const { error: ledgerErr } = await window.supabaseClient.from('student_ledger').insert([{
            id: payId, student_id: student.id, date: dateStr, type: 'payment',
            description: finalDesc, amount: effectiveUsd, zig: rawZig, receipt_no: receiptNo,
            method: 'EcoCash', status: 'ACTIVE', term: 'Auto',
            processed_by: processedBy,
            breakdown: [{ desc: finalDesc, amt: effectiveUsd }]
        }]);
        if (ledgerErr) throw new Error('Ledger save failed: ' + ledgerErr.message);
        paymentLedgerSaved = true;

        const { error: paymentErr } = await window.supabaseClient.from('payments').insert([{
            id: paymentRecordId, receipt_no: receiptNo, student_id: student.id,
            amount: effectiveUsd, date: dateStr, method: 'EcoCash',
            status: 'PAID', notes: `${finalDesc} [Ref: ${tx.ref}]`, category: finalCategory,
            processed_by: processedBy
        }]);
        if (paymentErr) throw new Error('Payment save failed: ' + paymentErr.message);
        paymentRecordSaved = true;

        // 7. Mark Submission as Claimed
        tx.status = 'claimed';
        tx.usedBy = student.id;
        if (typeof window.saveData === 'function') await window.saveData();

        // 8. 📱 TRIGGER WHATSAPP CONFIRMATION
        const rawPhone = student.phone || student.cell;
        if (rawPhone) {
            let phone = rawPhone.replace(/\D/g, ''); 
            if (phone.startsWith('0')) phone = '263' + phone.substring(1);
            
            let waMsg = `*${window.settings?.schoolName || 'HAVEN ONLINE'} - Payment Verified*\n\nGreat news! Your payment of *${displayPromptAmount}* (Ref: ${tx.ref}) for *${student.name}* has been verified.\n\n*Allocated To:* ${finalCategory}\n*Receipt No:* ${receiptNo}\n\nThank you!`;
            
            setTimeout(() => { window.open(`https://wa.me/${phone}?text=${encodeURIComponent(waMsg)}`, '_blank'); }, 500); 
        }

        alert(`🎉 Success! Payment processed directly into [${finalCategory}].\nLedger and Reconciliation Vault updated.`);
        
        // 9. Refresh UI & Print Receipt
        if (typeof window.renderPendingReferences === 'function') window.renderPendingReferences();
        if (typeof window.updateDashboard === 'function') window.updateDashboard();
        if (typeof window.calculateReconciliation === 'function') window.calculateReconciliation();
        
        if (typeof window.reprintReceipt === 'function') {
            window.reprintReceipt(receiptNo, student.id);
        }

    } catch (err) {
        console.error("Approval Sync Error:", err);
        const rollbackErrors = [];
        const rollbackOperations = [];
        if (paymentRecordSaved) {
            rollbackOperations.push(window.supabaseClient.from('payments').delete().eq('id', paymentRecordId));
        }
        if (paymentLedgerSaved) {
            rollbackOperations.push(window.supabaseClient.from('student_ledger').delete().eq('id', payId));
        }
        if (eventChargeSaved && pendingEventCharge) {
            rollbackOperations.push(window.supabaseClient.from('student_ledger').delete().eq('id', pendingEventCharge.id));
        }
        if (rollbackOperations.length > 0) {
            try {
                const rollbackResults = await Promise.all(rollbackOperations);
                rollbackResults.forEach(result => {
                    if (result.error) rollbackErrors.push(result.error.message);
                });
            } catch (rollbackError) {
                rollbackErrors.push(rollbackError.message || String(rollbackError));
            }
        }
        if (referenceClaimed) {
            console.error(`Payment reference ${tx.ref} remains claimed after an incomplete approval.`);
        }
        student.ledger = originalLedger;
        const recoveryMessage = referenceClaimed
            ? ' The reference remains reserved; verify cloud records before retrying or releasing it.'
            : '';
        const rollbackMessage = rollbackErrors.length ? ` Rollback needs review: ${rollbackErrors.join('; ')}.` : '';
        alert(`⚠️ Payment approval was not completed. No local payment was kept. ${err.message || 'Cloud sync failed.'}${recoveryMessage}${rollbackMessage}`);
        if (btnElement) btnElement.innerText = originalText;
    }
};

window.printFinancialReport = function() {
    let tBilled = 0, tPaid = 0, fullyPaidCount = 0, owingCount = 0;
    window.students.forEach(s => {
        let sBilled = 0, sPaid = 0;
        if(s.ledger && Array.isArray(s.ledger)) { 
            s.ledger.forEach(l => { 
                if(l.type === 'charge') sBilled += parseFloat(l.amount) || 0; 
                if(l.type === 'payment') sPaid += parseFloat(l.amount) || 0; 
            }); 
        }
        tBilled += sBilled; tPaid += sPaid;
        if (sBilled > 0) { 
            if (sBilled - sPaid <= 0) fullyPaidCount++; 
            else owingCount++; 
        }
    });
    const dateStr = new Date().toISOString().split('T')[0];
    let printHTML = `<html><head><title>Financial Summary</title><style>
        body { font-family: 'Segoe UI', Tahoma, sans-serif; padding: 30px; color: #2c3e50; } 
        h1 { text-align: center; text-transform: uppercase; border-bottom: 2px solid #2c3e50; padding-bottom: 10px; } 
        .box { border: 1px solid #bdc3c7; padding: 20px; margin-bottom: 20px; background: #f8f9fa; border-radius: 8px; } 
        h3 { margin-top: 0; color: #34495e; border-bottom: 1px dashed #bdc3c7; padding-bottom: 10px; }
    </style></head><body>
        <h1>${window.settings.schoolName || 'HAVEN ONLINE'} - Financial Report</h1>
        <p style="text-align: center; color: #7f8c8d;"><strong>Date Generated:</strong> ${dateStr}</p>
        <div class="box">
            <h3>Revenue Overview</h3>
            <p><strong>Total Income (Paid):</strong> $${tPaid.toFixed(2)}</p>
            <p><strong>Total Expected (Invoiced):</strong> $${tBilled.toFixed(2)}</p>
            <p style="color:#e74c3c; font-size: 18px;"><strong>Total Outstanding Arrears:</strong> $${(tBilled - tPaid > 0 ? tBilled - tPaid : 0).toFixed(2)}</p>
        </div>
        <div class="box">
            <h3>Account Status Overview</h3>
            <p><strong>Students Fully Paid:</strong> ${fullyPaidCount}</p>
            <p><strong>Students Owing:</strong> ${owingCount}</p>
            <p><strong>Total Enrolled:</strong> ${window.students.length}</p>
        </div>
    </body></html>`;
    const printWindow = window.open('', '_blank'); 
    printWindow.document.write(printHTML); 
    printWindow.document.close();
    setTimeout(() => { printWindow.print(); printWindow.close(); }, 500);
};

