// 13. BULK WHATSAPP FINANCE
// ==========================================

window.compileFinancialBatch = async function(type) {
    const classFilter = document.getElementById('waReminderClassFilter');
    const availableClasses = [...new Set((window.students || [])
        .map(student => String(student.grade || student.class || student.level || '').trim())
        .filter(Boolean))]
        .sort((a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' }));
    const previousClass = classFilter?.value || 'all';
    if (classFilter) {
        classFilter.replaceChildren(new Option('All Classes', 'all'));
        availableClasses.forEach(className => classFilter.add(new Option(className, className)));
        classFilter.value = availableClasses.includes(previousClass) ? previousClass : 'all';
    }
    const selectedClass = classFilter?.value || 'all';

    const messageFormat = document.getElementById('waReminderFormat')?.value || 'short';
    const isDetailed = messageFormat === 'detailed';
    const dateValue = date => [date.getFullYear(), String(date.getMonth() + 1).padStart(2, '0'), String(date.getDate()).padStart(2, '0')].join('-');
    const today = new Date();
    const shortStart = document.getElementById('waReminderStartDate')?.value || dateValue(new Date(today.getFullYear(), today.getMonth(), 1));
    const shortEnd = document.getElementById('waReminderEndDate')?.value || dateValue(new Date(today.getFullYear(), today.getMonth() + 1, 0));
    if (shortStart > shortEnd) return window.alert('Reminder start date must be on or before the end date.');

    const periodStart = new Date(`${shortStart}T00:00:00`);
    const periodLabel = shortStart.slice(0, 7) === shortEnd.slice(0, 7)
        ? periodStart.toLocaleDateString('en', { month: 'long', year: 'numeric' })
        : `${shortStart} to ${shortEnd}`;

    // ☁️ CLOUD MEMORY FIX: Fetch network-wide history from Supabase
    let waSentHistory = {};
    if (window.supabaseClient) {
        const { data, error } = await window.supabaseClient.from('wa_sent_logs').select('*');
        if (data) {
            data.forEach(log => {
                waSentHistory[log.student_id] = parseFloat(log.last_balance);
            });
        }
    }
    
    window.financeBatch = []; 
    
    window.students.forEach(s => {
        const studentClass = String(s.grade || s.class || s.level || 'N/A').trim();
        if (selectedClass !== 'all' && studentClass.toLowerCase() !== selectedClass.toLowerCase()) return;

        let tBilled = 0, tPaid = 0, historyText = "";
        let openingBalance = 0, periodBilled = 0, periodPaid = 0, periodOverpayment = 0;
        let terms = new Set();
        let lastDate = "";

        if(s.ledger && Array.isArray(s.ledger)) {
            s.ledger.forEach(l => {
                if (l.status === 'VOIDED' || l.status === 'voided' || l.status === 'VOID' || l.status === 'void') return;
                if (window.isCreditAllocationAdjustmentCharge?.(l) || window.isAdvanceCreditSettlementEntry?.(l)) return;

                let amount = parseFloat(l.amount) || 0;
                let dateStr = String(l.date || '').slice(0, 10) || 'N/A';
                let descStr = l.desc || l.description || 'Transaction';
                const isCharge = l.type === 'charge' || l.type === 'fee';
                const isCredit = ['payment', 'overpayment', 'credit', 'discount', 'waiver'].includes(l.type);
                const billedAmount = isCharge ? amount : 0;
                const paidAmount = isCredit ? amount : 0;

                tBilled += billedAmount;
                tPaid += paidAmount;

                if (dateStr === 'N/A' || dateStr < shortStart) {
                    openingBalance += billedAmount - paidAmount;
                } else if (dateStr <= shortEnd) {
                    periodBilled += billedAmount;
                    periodPaid += paidAmount;
                    if (l.type === 'overpayment') periodOverpayment += amount;
                }

                if (l.term) terms.add(l.term.toLowerCase());
                if (isDetailed) historyText += `▪️ ${dateStr}: ${descStr} - $${amount.toFixed(2)}\n`;
                if (isCredit && dateStr !== 'N/A') lastDate = dateStr;
            });
        }
        
        const bal = tBilled - tPaid;
        const owed = bal > 0 ? bal : 0;
        const credit = bal < 0 ? Math.abs(bal) : 0;
        const periodClosingBalance = openingBalance + periodBilled - periodPaid;
        // -------------------------------------

        if (type === 'owing' && (isDetailed ? owed <= 0 : periodClosingBalance <= 0.01)) return; 
        
        const rawPhone = s.phone || s.cell;
        if (!rawPhone || rawPhone.trim() === "") return; 

        const schoolName = window.settings?.schoolName || 'HAVEN ONLINE';
        let msg = `*${schoolName} - ${isDetailed ? 'FINANCIAL STATEMENT' : (periodClosingBalance > 0.01 ? 'PAYMENT REMINDER' : 'ACCOUNT UPDATE')}*\n`;
        msg += `*Student:* ${s.name || s.student_name || 'Student'}\n`;
        msg += `*Student ID:* ${s.id || s.student_id || 'N/A'}\n`;
        msg += `*Class:* ${s.grade || s.class || s.level || 'N/A'}\n`;

        if (isDetailed) {
            msg += `*Term:* ${Array.from(terms).join(', ') || 'Current'}\n`;
            msg += `------------------------\n*Total billed:* $${tBilled.toFixed(2)}\n*Total paid/credited:* $${tPaid.toFixed(2)}\n`;
            if (credit > 0.01) msg += `*ACCOUNT CREDIT:* $${credit.toFixed(2)}\n*BALANCE OWED:* $0.00\n`;
            else msg += `*BALANCE OWED:* $${owed.toFixed(2)}\n`;
            msg += `------------------------\n*Payment history:*\n${historyText || 'No ledger entries.'}\n`;
            msg += owed > 0.01
                ? `Please arrange payment when convenient. Contact the school if you have questions.`
                : `Thank you for your continued support.`;
        } else {
            msg += `*Period:* ${periodLabel}\n`;
            msg += `*Balance brought forward:* ${openingBalance < -0.01 ? `-$${Math.abs(openingBalance).toFixed(2)} credit` : `$${Math.max(0, openingBalance).toFixed(2)} owed`}\n`;
            msg += `*New charges:* $${periodBilled.toFixed(2)}\n`;
            msg += `*Payments/credits:* $${periodPaid.toFixed(2)}\n`;

            if (periodClosingBalance > 0.01) {
                msg += `*AMOUNT DUE:* $${periodClosingBalance.toFixed(2)}\n`;
                msg += periodOverpayment > 0.01
                    ? `Your overpayment of $${periodOverpayment.toFixed(2)} has been applied to the balance. The amount above remains due. Thank you.`
                    : `Please arrange payment when convenient. Thank you for supporting ${schoolName}.`;
            } else if (periodClosingBalance < -0.01) {
                msg += `*ACCOUNT CREDIT:* $${Math.abs(periodClosingBalance).toFixed(2)}\n`;
                msg += periodOverpayment > 0.01
                    ? `Thank you. Your payment exceeded this period's charges; the overpayment is carried forward as account credit.`
                    : `Your previous account credit has been carried forward to future fees. Thank you.`;
            } else {
                msg += `*BALANCE:* $0.00\n`;
                msg += periodOverpayment > 0.01
                    ? `Thank you. Your overpayment has been applied and the account is up to date.`
                    : `Your account is up to date for this period. Thank you.`;
            }
        }
        
        let phone = rawPhone.replace(/\D/g, ''); 
        if (phone.startsWith('0')) phone = '263' + phone.substring(1); 

        // ☁️ CLOUD MEMORY FIX: Check if ANY device already sent a message for this exact balance
        let alreadySent = false;
        if (waSentHistory[s.id] !== undefined && waSentHistory[s.id] === owed) {
            alreadySent = true;
        }

        window.financeBatch.push({ 
            id: s.id, 
            name: s.name, 
            grade: studentClass,
            phone: phone, 
            billed: tBilled,
            paid: tPaid,
            bal: owed, 
            credit: credit,
            terms: Array.from(terms).join(" "), 
            lastDate: lastDate,                 
            message: msg, 
            sent: alreadySent, 
            selected: false 
        });
    });
    
    document.getElementById('financeBatchControls').style.display = 'flex';
    window.renderFinanceBatch(); 
    alert(`Compiled ${window.financeBatch.length} students into the Queue!`);
};

window.renderFinanceBatch = function() {
    const queueDiv = document.getElementById('financeBatchQueue');
    const searchQ = (document.getElementById('waSearch').value || "").toLowerCase();
    
    if (window.financeBatch.length === 0) {
        queueDiv.innerHTML = "<em style='color: #7f8c8d; font-size: 13px;'>Queue is empty.</em>"; 
        document.getElementById('financeBatchControls').style.display = 'none';
        return;
    }

    // 1. Filter by Name OR Period (Term/Date)
    const filtered = window.financeBatch.filter(item => {
        return item.name.toLowerCase().includes(searchQ) || 
               String(item.id || '').toLowerCase().includes(searchQ) ||
               String(item.grade || '').toLowerCase().includes(searchQ) ||
               item.terms.includes(searchQ) ||
               item.lastDate.includes(searchQ);
    });

    if (filtered.length === 0) {
        queueDiv.innerHTML = "<em style='color: #7f8c8d; font-size: 13px;'>No matching records found.</em>";
        return;
    }

    // Updated Table with Checkboxes for Bulk Selection
    let html = `<table style="width:100%; font-size: 13px; border-collapse: collapse; text-align: left;">
        <thead>
            <tr style="border-bottom: 2px solid #bdc3c7;">
                <th style="padding: 10px 5px; width: 40px;">
                    <input type="checkbox" onchange="window.toggleAllWABatch(this)" title="Select All">
                </th>
                <th style="padding: 10px 5px;">Student</th>
                <th style="padding: 10px 5px;">Financials</th>
                <th style="padding: 10px 5px;">Status</th>
                <th style="padding: 10px 5px; text-align: right;">Action</th>
            </tr>
        </thead>
        <tbody>`;
    
    filtered.forEach((item) => {
        // Need to reference original array index to update the source truth data
        const originalIndex = window.financeBatch.indexOf(item);
        
        const statusColor = item.sent ? 'color: #27ae60; font-weight: bold;' : 'color: #7f8c8d;';
        
        // Display Credit in blue, Owing in red, zero balance in green
        let finHtml = `Bal: $${item.bal.toFixed(2)}`;
        if (item.credit > 0) finHtml = `<span style="color: #2980b9;">Credit: $${item.credit.toFixed(2)}</span>`;
        else if (item.bal > 0) finHtml = `<span style="color: #e74c3c;">Bal: $${item.bal.toFixed(2)}</span>`;
        else finHtml = `<span style="color: #27ae60;">Bal: $0.00</span>`;

        html += `
            <tr style="border-bottom: 1px solid #bdc3c7;">
                <td style="padding: 10px 5px;">
                    <input type="checkbox" class="wa-batch-chk" data-idx="${originalIndex}" 
                        ${item.selected ? 'checked' : ''} onchange="window.toggleWASelection(${originalIndex}, this)">
                </td>
                <td style="padding: 10px 5px;"><strong>${item.name}</strong><br><small>ID: ${item.id} · ${item.grade}</small><br><small>${item.phone}</small></td>
                <td style="padding: 10px 5px; font-weight: bold;">${finHtml}</td>
                <td style="padding: 10px 5px; ${statusColor}">${item.sent ? 'Sent ✔' : 'Pending'}</td>
                <td style="padding: 10px 5px; text-align: right;">
                    <button class="btn-standard btn-success" style="padding: 6px 12px; font-size: 11px;" 
                        onclick="window.sendBatchMessage(${originalIndex})">${item.sent ? 'Resend' : 'Send WA'}</button>
                </td>
            </tr>`;
    });
    html += `</tbody></table>`; 
    queueDiv.innerHTML = html;
};

// Checkbox helper functions
window.toggleAllWABatch = function(el) {
    const checkboxes = document.querySelectorAll('.wa-batch-chk');
    checkboxes.forEach(chk => {
        chk.checked = el.checked;
        const idx = chk.getAttribute('data-idx');
        window.financeBatch[idx].selected = el.checked;
    });
};

window.toggleWASelection = function(index, el) {
    window.financeBatch[index].selected = el.checked;
};

// 2. Send Multiple Contacts via Bulk
window.sendSelectedBatch = async function() {
    const selectedItems = window.financeBatch.map((item, idx) => ({...item, index: idx})).filter(i => i.selected);
    
    if(selectedItems.length === 0) {
        alert("Please select at least one contact using the checkboxes.");
        return;
    }

    if(!confirm(`You are about to send ${selectedItems.length} messages. \n\nIMPORTANT: Your browser must allow popups for this to work. Proceed?`)) return;

    for (let i = 0; i < selectedItems.length; i++) {
        const item = selectedItems[i];
        
        // Open WhatsApp Web/App
        window.open(`https://wa.me/${item.phone}?text=${encodeURIComponent(item.message)}`, '_blank');
        
        // Mark as sent and deselect
        window.financeBatch[item.index].sent = true;
        window.financeBatch[item.index].selected = false; 
        
        // Update UI progressively
        window.renderFinanceBatch();

        // Add a 1.5 second delay between openings to prevent the browser from blocking mass popups
        if (i < selectedItems.length - 1) {
            await new Promise(resolve => setTimeout(resolve, 1500));
        }
    }
};

window.sendBatchMessage = function(index) {
    const item = window.financeBatch[index];
    if (!item) return;

    // 1. Open WhatsApp draft tab
    window.open(`https://wa.me/${item.phone}?text=${encodeURIComponent(item.message)}`, '_blank');
    
    // 2. Update local batch state and re-render UI immediately
    window.financeBatch[index].sent = true; 
    window.renderFinanceBatch();

    // 3. Save sent status to Supabase cloud table for network-wide synchronization
    if (window.supabaseClient) {
        window.supabaseClient.from('wa_sent_logs').upsert({ 
            student_id: item.id, 
            last_balance: item.bal,
            sent_at: new Date().toISOString()
        }, { onConflict: 'student_id' })
        .then(({ error }) => {
            if (error) console.error("Failed to save WA sync status:", error);
        });
    }
};

window.clearFinancialBatch = function() {
    if (confirm("Clear the entire WhatsApp queue?")) { 
        window.financeBatch = []; 
        document.getElementById('waSearch').value = ""; // clear search
        window.renderFinanceBatch(); 
    }
};

