window.renderCustomClasses = function() {
    // FIX: Changed ID to customClassTableBody to prevent conflict with the tags function
    const tbody = document.getElementById('customClassTableBody');
    if (!tbody) {
        console.warn("Could not find tbody#customClassTableBody");
        return;
    }

    // 1. Safely wipe the table clean
    while (tbody.firstChild) {
        tbody.removeChild(tbody.firstChild);
    }

    window.officialClasses = window.officialClasses || [];

    if (window.officialClasses.length === 0) {
        const tr = document.createElement('tr');
        const td = document.createElement('td');
        td.colSpan = 3;
        td.style.textAlign = 'center';
        td.style.padding = '15px';
        td.style.color = '#7f8c8d';
        td.textContent = 'No official classes added yet.';
        tr.appendChild(td);
        tbody.appendChild(tr);
        return;
    }

    // 2. Build each row securely
    window.officialClasses.forEach((c, index) => {
        const cName = typeof c === 'string' ? c : (c.level || c.name);
        const rawLimit = typeof c === 'object' ? (c.capacity || c.limit || 0) : 0;
        const cLimit = rawLimit > 0 ? rawLimit : "No Limit";
        const colorTag = cLimit === "No Limit" ? "#7f8c8d" : "#2980b9";

        const tr = document.createElement('tr');
        tr.style.borderBottom = "1px solid #ecf0f1";

        // Column 1: Name
        const tdName = document.createElement('td');
        tdName.style.padding = "10px";
        tdName.innerHTML = `<strong>${cName}</strong>`;
        tr.appendChild(tdName);

        // Column 2: Limit
        const tdLimit = document.createElement('td');
        tdLimit.style.padding = "10px";
        tdLimit.style.textAlign = "center";
        tdLimit.style.color = colorTag;
        tdLimit.style.fontWeight = "bold";
        tdLimit.textContent = cLimit;
        tr.appendChild(tdLimit);

        // Column 3: Button
        const tdAction = document.createElement('td');
        tdAction.style.padding = "10px";
        tdAction.style.textAlign = "right";

        const btn = document.createElement('button');
        btn.className = "btn-standard btn-danger admin-edit-only";
        btn.style.padding = "6px 12px";
        btn.style.fontSize = "12px";
        btn.style.borderRadius = "4px";
        btn.style.cursor = "pointer";
        btn.innerHTML = "❌ Remove";
        
        btn.onclick = function() {
            if (typeof window.removeCustomClass === 'function') {
                window.removeCustomClass(index);
            }
        };

        tdAction.appendChild(btn);
        tr.appendChild(tdAction);

        // Lock the row into the table
        tbody.appendChild(tr);
    });
};

window.removeCustomClass = async function(index) {
    // 1. 3-Tier Security Check
    const role = window.currentUser?.role || "";
    if (!(role.includes('Level 2') || role.includes('Level 3') || role === 'Admin' || role === 'Chief Admin')) {
        return alert("❌ Access Denied: Only Admins can delete classes.");
    }

    // Must be online to ensure the database stays perfectly in sync with the screen
    if (!navigator.onLine) return alert("⚠️ You are offline. Please connect to the internet to delete classes.");

    // 2. Identify the exact class name, whether it's an old string or a new SQL object
    const classToRemove = window.officialClasses[index];
    const className = typeof classToRemove === 'string' ? classToRemove : (classToRemove.level || classToRemove.name);

    if (!confirm(`⚠️ Are you sure you want to completely remove the class: ${className}?`)) return;

    try {
        // 3. Remove from Supabase Cloud SQL Table FIRST
        const { error } = await supabaseClient.from('classes').delete().eq('level', className);
        if (error) throw error;
        console.log(`🗑️ Cloud sync: Removed ${className} from SQL.`);

        // 4. Remove Locally from Memory
        window.officialClasses.splice(index, 1);
        
        // 5. Instantly overwrite Local Storage so it doesn't resurrect on refresh
        localStorage.setItem('haven_classes', JSON.stringify(window.officialClasses));

        // 6. 🎯 THE FIX: Force a silent Master Settings backup update
        if (typeof window.saveOfficialClasses === 'function') {
            await window.saveOfficialClasses(true); // 'true' makes it silent!
        }

        // 7. Refresh ALL connected UIs in the system
        window.renderCustomClasses();
        if (typeof window.loadAdminClassRules === 'function') window.loadAdminClassRules();
        if (typeof window.updateAllClassDropdowns === 'function') window.updateAllClassDropdowns();
        if (typeof window.renderCustomClassTags === 'function') window.renderCustomClassTags();
        if (typeof window.updateOnlineEnrollmentDropdown === 'function') window.updateOnlineEnrollmentDropdown();

        console.log(`✅ Class ${className} completely wiped from the system.`);
    } catch (err) {
        console.error("Delete failed:", err);
        alert("Failed to delete class from the cloud. Please check your connection.");
    }
};

// ==========================================
// 💾 MASTER CLASS SAVE & SYNC ENGINE
// ==========================================
window.saveOfficialClasses = async function(isSilent = false) {
    // 1. 3-Tier Security Check
    const role = window.currentUser?.role || "";
    if (!(role.includes('Level 2') || role.includes('Level 3') || role === 'Admin' || role === 'Chief Admin')) {
        if (!isSilent) alert("❌ Access Denied: Only Admins can modify class master structures.");
        return;
    }

    if (!isSilent) console.log("💾 Processing Master Class Update...");

    // 2. Parse the Bulk Edit Table (ONLY if it exists and we aren't doing a silent background delete)
    const table = document.getElementById('adminClassTable');
    if (table && !isSilent) {
        let updatedClasses = [...(window.officialClasses || [])];
        
        for (let i = 1; i < table.rows.length; i++) {
            let row = table.rows[i];
            let levelInput = row.cells[0]?.querySelector('input');
            let capInput = row.cells[1]?.querySelector('input');
            let feeInput = row.cells[2]?.querySelector('input');

            if (levelInput && levelInput.value.trim() !== "") {
                let className = levelInput.value.trim();
                let newCap = capInput ? parseInt(capInput.value) || 30 : 30;
                let newFee = feeInput ? parseFloat(feeInput.value) || 0 : 0;

                // Find if it exists by checking both old and new naming conventions
                let existingIndex = updatedClasses.findIndex(c => (c.level || c.name) === className);
                
                if (existingIndex >= 0) {
                    updatedClasses[existingIndex].capacity = newCap;
                    updatedClasses[existingIndex].limit = newCap; // Hybrid support
                    updatedClasses[existingIndex].fee = newFee;
                } else {
                    updatedClasses.push({ 
                        level: className, name: className, 
                        capacity: newCap, limit: newCap, 
                        fee: newFee 
                    });
                }
            }
        }
        window.officialClasses = updatedClasses;
    }

    // 3. Local Memory & Settings Backup
    localStorage.setItem('haven_classes', JSON.stringify(window.officialClasses));
    
    window.settings = window.settings || {};
    window.settings.classes = window.officialClasses;
    localStorage.setItem('haven_settings', JSON.stringify(window.settings));

    if (!navigator.onLine) {
        if (typeof window.updateAllClassDropdowns === 'function') window.updateAllClassDropdowns();
        if (typeof window.renderCustomClassTags === 'function') window.renderCustomClassTags();
        if (!isSilent) alert("⚠️ Saved locally, but you are offline. Cloud sync paused.");
        return;
    }

    // 4. Dual Cloud Sync (SQL Table + Settings Blob)
    try {
        // A. Strip out UI data to prevent Supabase Schema errors (The PGRST204 fix)
        const pureSqlData = window.officialClasses.map(c => ({
            level: c.level || c.name,
            capacity: c.capacity || c.limit || 0,
            fee: c.fee || 0
        }));

        // B. Push strictly formatted data to SQL `classes` table
        const { error: sqlError } = await supabaseClient.from('classes').upsert(pureSqlData, { onConflict: 'level' });
        if (sqlError) throw sqlError;

        // C. Push the full UI object backup to `school_data` Settings Blob
        const { error: blobError } = await supabaseClient.from('school_data').upsert({ 
            id: 'master_settings', 
            settings: window.settings,
            last_updated: new Date().toISOString() 
        });
        if (blobError) throw blobError;
        
        // 5. Refresh System UI Elements
        if (typeof window.updateAllClassDropdowns === 'function') window.updateAllClassDropdowns();
        if (typeof window.renderCustomClassTags === 'function') window.renderCustomClassTags();
        if (typeof window.updateOnlineEnrollmentDropdown === 'function') window.updateOnlineEnrollmentDropdown();
        
        if (!isSilent) {
            console.log("✅ Classes updated successfully across all databases!");
            alert("✅ Master Classes synced to SQL and Cloud Backup successfully!");
        }
    } catch (error) {
        console.error("❌ Failed to save classes:", error);
        if (!isSilent) alert("⚠️ Saved locally, but encountered a cloud synchronization error.");
    }
};

// ==========================================
// 🏫 CLASS & ENROLLMENT LIMIT MANAGEMENT (MERGED HYBRID ENGINE)
// ==========================================

window.addCustomClass = async function() {
    // 1. 3-Tier Security Check
    const role = window.currentUser?.role || "";
    if (!(role.includes('Level 2') || role.includes('Level 3') || role === 'Admin' || role === 'Chief Admin')) {
        return alert("❌ Access Denied: Only Admins can add new classes.");
    }

    if (!navigator.onLine) return alert("⚠️ You are offline. Please connect to the internet to add new classes.");

    // 2. Read Inputs
    const nameInput = document.getElementById('newClassName');
    const limitInput = document.getElementById('newClassLimit'); 
    
    const className = nameInput.value.trim();
    const classLimit = parseInt(limitInput?.value) || 0; // 0 means no limit

    if (!className) return alert("Please enter a class name!");

    if (!window.officialClasses) window.officialClasses = [];

    // 3. Prevent duplicate class names
    const exists = window.officialClasses.some(c => {
        const existingName = typeof c === 'string' ? c : (c.level || c.name);
        return existingName.toLowerCase() === className.toLowerCase();
    });
    
    if (exists) return alert("⚠️ This class already exists in the system!");

    console.log(`🚀 Hybrid Sync: Adding custom class: ${className} with Capacity: ${classLimit}`);

    // 4. 🎯 THE FIX: Separate Cloud Data from Local UI Data
    
    // Data strictly for Supabase SQL Database (MUST match your table columns exactly)
    const cloudData = { 
        level: className,       
        capacity: classLimit,   
        fee: 0                  
    };

    // Data for local HTML UI rendering and local storage
    const localData = { 
        level: className,       
        capacity: classLimit,   
        fee: 0,                 
        name: className,        
        limit: classLimit       
    };

    try {
        // 5. Push ONLY the exact SQL columns to Supabase
        const { error } = await supabaseClient.from('classes').upsert(cloudData, { onConflict: 'level' });
        if (error) throw error;

        // 6. Clear Inputs & Update Local Memory with the Hybrid Object
        nameInput.value = '';
        if (limitInput) limitInput.value = '';

        window.officialClasses.push(localData);
        localStorage.setItem('haven_classes', JSON.stringify(window.officialClasses));
        
        // 7. Instant UI Refresh
        if (typeof window.loadAdminClassRules === 'function') window.loadAdminClassRules();
        if (typeof window.renderCustomClassTags === 'function') window.renderCustomClassTags();
        if (typeof window.updateAllClassDropdowns === 'function') window.updateAllClassDropdowns();
        window.renderCustomClasses();
        
        // ADD THIS LINE SO THE ONLINE FORM UPDATES INSTANTLY:
        if (typeof window.updateOnlineEnrollmentDropdown === 'function') window.updateOnlineEnrollmentDropdown();

        console.log("✅ Hybrid Save: Custom class and capacity limit are now permanent in SQL.");
    } catch (error) {
        console.error("❌ Hybrid Sync Failure:", error);
        alert("⚠️ Connection error. Class was not saved to the cloud.");
    }
};

