window.populateTransportDropdown = function() {
    const transportSelect = document.getElementById('regTransport');
    if (!transportSelect) return;

    // Reset dropdown to default
    transportSelect.innerHTML = '<option value="0">None ($0)</option>';

    if (window.settings) {
        const zones = ['A', 'B', 'C', 'D', 'E', 'F'];

        zones.forEach(zone => {
            let fullFare = 0;
            let rawOneWay = 0;

            // 1. Try the nested structure first (Preferred)
            if (window.settings.transportFares) {
                const t = window.settings.transportFares;
                fullFare = parseFloat(t[`zone${zone}`]) || 0;
                rawOneWay = parseFloat(t[`zone${zone}OneWay`]) || 0;
            } 
            // 2. Fallback to the flat structure (Console log version)
            else {
                const t = window.settings;
                fullFare = parseFloat(t[`transZone${zone}Full`]) || 0;
                rawOneWay = parseFloat(t[`transZone${zone}OneWay`]) || 0;
            }
            
            // Calculate halfway if rawOneWay from DB is 0 or missing
            const oneWayFare = rawOneWay > 0 ? rawOneWay : (fullFare / 2);

            // Append Full Route if > 0
            if (fullFare > 0) {
                const optFull = document.createElement('option');
                optFull.value = fullFare;
                optFull.setAttribute('data-mode', 'full');
                optFull.textContent = `Zone ${zone} - Full Route ($${fullFare.toFixed(2)})`;
                transportSelect.appendChild(optFull);
            }

            // Append One Way if > 0
            if (oneWayFare > 0) {
                const optOneWay = document.createElement('option');
                optOneWay.value = oneWayFare;
                optOneWay.setAttribute('data-mode', 'one_way');
                optOneWay.textContent = `Zone ${zone} - One Way ($${oneWayFare.toFixed(2)})`;
                transportSelect.appendChild(optOneWay);
            }
        });
    }
};

window.populateClassDropdowns = function() {
    const classes = (window.officialClasses || []).map(c => c.level || c.className || c.name).filter(Boolean);

    const fillDropdown = (id, defaultText) => {
        const select = document.getElementById(id);
        if (select) {
            const currentVal = select.value;
            select.innerHTML = `<option value="" disabled selected>${defaultText}</option>`;
            if (id === 'filterGrade') select.innerHTML = '<option value="ALL">All Grades</option>';

            classes.forEach(c => {
                const safe = String(c).trim();
                if (safe) select.innerHTML += `<option value="${safe}">${safe}</option>`;
            });

            if (classes.includes(currentVal) || (id === 'filterGrade' && currentVal === 'ALL')) {
                select.value = currentVal;
            }
        }
    };

    fillDropdown('regGrade', 'Select Grade/Class...');
    fillDropdown('filterGrade', 'All Grades');
    fillDropdown('setupFeeGrade', 'Select Grade...');
    fillDropdown('attendanceClass', '-- Select Class --');
    fillDropdown('deployClass', 'Select Class...');
};

