// 1. Auto-detects the current term based on the system clock
// 📅 1. MASTER DATE ENGINE (Hardcoded to 2026 Calendar)
window.getCurrentTerm = function() {
    const today = new Date();
    const year = today.getFullYear();
    const month = today.getMonth() + 1; // 1-12
    const date = today.getDate();

    // Create a simple MMDD format for easy date-range comparison
    const mmdd = month * 100 + date;

    // First Term: 13 Jan - 1 Apr (Holiday starts 2 Apr -> belongs to Term 2)
    if (mmdd >= 101 && mmdd <= 401) return `Term 1 ${year}`;
    
    // Second Term: 12 May - 6 Aug (Holiday starts 7 Aug -> belongs to Term 3)
    if (mmdd >= 402 && mmdd <= 806) return `Term 2 ${year}`;
    
    // Third Term: 8 Sep - 8 Dec (Holiday starts 9 Dec -> belongs to Term 1 of NEXT year)
    if (mmdd >= 807 && mmdd <= 1208) return `Term 3 ${year}`;
    if (mmdd >= 1209) return `Term 1 ${year + 1}`;
    
    return `Term 1 ${year}`; // Safe fallback
};

// ⚠️ 2. TERM VALIDATION HOOK (Attach this to your HTML dropdowns)
// Example HTML usage: <select id="payCycle" onchange="verifyTermSelection(this)">
window.verifyTermSelection = function(selectElement) {
    const currentSystemTerm = window.getCurrentTerm();
    
    // If they select a term that doesn't match the current calendar period, throw a warning
    if (selectElement.value && selectElement.value !== currentSystemTerm && selectElement.value !== "Once-Off" && selectElement.value !== "General") {
        alert(`⚠️ NOTICE: The term you selected (${selectElement.value}) is not the same as the current system time (${currentSystemTerm}).`);
    }
};

// 2. Saves Admin-defined exact calendar start/end dates to Supabase
window.saveCalendarSettings = async function() {
    // 1. 3-Tier Security Check
    const role = window.currentUser?.role || "";
    if (!(role.includes('Level 2') || role.includes('Level 3') || role === 'Admin' || role === 'Chief Admin')) {
        return alert("❌ Access Denied: Only Admins can modify calendar settings.");
    }

    console.log("💾 Syncing calendar dates to Cloud...");

    // 2. Extract values directly from the DOM inputs
    const term1Start = document.getElementById('calTerm1Start')?.value || "";
    const term1End = document.getElementById('calTerm1End')?.value || "";
    
    const term2Start = document.getElementById('calTerm2Start')?.value || "";
    const term2End = document.getElementById('calTerm2End')?.value || "";
    
    const term3Start = document.getElementById('calTerm3Start')?.value || "";
    const term3End = document.getElementById('calTerm3End')?.value || "";

    // 3. Ensure global settings object exists
    if (!window.settings) window.settings = {};
    if (!window.settings.calendar) window.settings.calendar = {};

    // 4. Update local memory object
    window.settings.calendar = {
        term1: { start: term1Start, end: term1End },
        term2: { start: term2Start, end: term2End },
        term3: { start: term3Start, end: term3End }
    };

    // 5. Save to Local Storage (Your Offline Safety Net)
    localStorage.setItem('haven_settings', JSON.stringify(window.settings));

    // 6. Network check before attempting Supabase push
    if (!navigator.onLine) {
        return alert("⚠️ Saved locally, but you are currently offline. Calendar dates will sync to the cloud when connection is restored.");
    }

    // 7. Push to Supabase Cloud
    try {
        const { error } = await window.supabaseClient.from('school_data').upsert({ 
            id: 'master_settings', 
            settings: window.settings,   
            last_updated: new Date().toISOString() 
        });

        if (error) throw error;

        alert("✅ Success! School calendar dates are now LIVE in the cloud.");

    } catch (error) {
        console.error("Cloud Error (Calendar):", error.message);
        alert("⚠️ Saved locally, but failed to reach the Cloud. Check your internet: " + error.message);
    }
};

window.saveSettings = async function() {
    // 3-Tier Check
    const role = window.currentUser?.role || "";
    if (!(role.includes('Level 2') || role.includes('Level 3') || role === 'Admin' || role === 'Chief Admin')) {
        return alert("❌ Access Denied: Only Admins can modify core school settings.");
    }

    console.log("💾 Syncing school profile and enrollment status to Cloud...");
    if (!window.settings) window.settings = {};

    // 1. Grab all text data from the screen
    const newName = document.getElementById('setSchoolName')?.value.trim() || "";
    const newAddress = document.getElementById('setAddress')?.value.trim() || ""; 
    const newPhone = document.getElementById('setPhone')?.value.trim() || ""; 
    const checkbox = document.getElementById('setEnrollmentOpen');

    // 2. Update the memory
    if (newName) window.settings.schoolName = newName;
    window.settings.address = newAddress;
    window.settings.phone = newPhone;
    window.settings.enrollmentOpen = checkbox ? checkbox.checked : false;

    // 🎯 THE FIX: CAPTURE TRANSPORT FARES BEFORE UPLOADING
    // (Ensure these IDs match the input IDs in your HTML settings tab)
    window.settings.transportFares = {
        zoneA: document.getElementById('setTransportA')?.value || 0,
        zoneAOneWay: document.getElementById('setTransportAOneWay')?.value || 0,
        zoneB: document.getElementById('setTransportB')?.value || 0,
        zoneBOneWay: document.getElementById('setTransportBOneWay')?.value || 0,
        zoneC: document.getElementById('setTransportC')?.value || 0,
        zoneCOneWay: document.getElementById('setTransportCOneWay')?.value || 0,
        zoneD: document.getElementById('setTransportD')?.value || 0,
        zoneDOneWay: document.getElementById('setTransportDOneWay')?.value || 0,
        zoneE: document.getElementById('setTransportE')?.value || 0,
        zoneEOneWay: document.getElementById('setTransportEOneWay')?.value || 0,
        zoneF: document.getElementById('setTransportF')?.value || 0,
        zoneFOneWay: document.getElementById('setTransportFOneWay')?.value || 0
    };

    // 🎯 THE FIX: STANDARDIZE LOGO NAMING 
    if (typeof window.base64Logo !== 'undefined' && window.base64Logo !== "") {
        try {
            const logoUrl = await window.uploadDataUrlToStorage(
                'school-assets',
                `logos/logo-${Date.now()}.png`,
                window.base64Logo
            );
            if (logoUrl) {
                window.settings.logoUrl = logoUrl;
                window.settings.schoolLogo = logoUrl;
                delete window.settings.logoBase64;
            }
        } catch (storageError) {
            console.warn("Logo Storage upload failed; retaining the previously selected logo:", storageError);
        }
    }

    // 4. Instant UI Feedback
    if (typeof window.applyEnrollmentVisibility === 'function') window.applyEnrollmentVisibility();
    if (typeof window.updateSchoolDisplay === 'function') window.updateSchoolDisplay(); 

    // 5. Save to Local Storage (Safety Net)
    localStorage.setItem('haven_settings', JSON.stringify(window.settings));

    // 6. Push to Supabase Cloud
    if (!navigator.onLine) {
        return alert("⚠️ Saved locally, but you are currently offline. Settings will sync to the cloud when connection is restored.");
    }

    try {
        // A. Update the main system settings using integer ID 1 to prevent the 406 Not Acceptable error
        const { error } = await supabaseClient.from('school_data').upsert({ 
            id: 'master_settings',
            settings: window.settings,   
            last_updated: new Date().toISOString() 
        });

        if (error) throw error;

        // B. Safely check and sync school name to the master key generator pool
        if (newName) {
            const { data: existingSchool, error: checkError } = await supabaseClient
                .from('schools')
                .select('school_name')
                .eq('school_name', newName)
                .maybeSingle(); // Gracefully handles 0 rows without throwing an error

            if (!existingSchool && !checkError) {
                await supabaseClient.from('schools').insert([
                    { id: Date.now(), school_name: newName }
                ]);
                console.log(`✅ School "${newName}" added to master key generator database.`);
            }
        }

        alert("✅ Global Fees & Transport Zones saved to the cloud successfully!");

        // C. Refresh transport dropdowns if active in the UI
        if (typeof populateTransportDropdown === 'function') {
            populateTransportDropdown();
        }

    } catch (error) {
        console.error("Cloud Error:", error.message || error);
        
        // Comprehensive error handling for network drops or oversized logos (413 Payload Too Large)
        const errMsg = error.message || String(error);
        if (errMsg.includes("payload too large") || errMsg.includes("413")) {
            alert("⚠️ Image Error: Your school logo is too large for the database. Please use a smaller photo.");
        } else {
            alert("⚠️ Saved locally, but failed to reach the Cloud. Check your internet: " + errMsg);
        }
    }
};

