window.loadFeeSetupForGrade = function() {
    const grade = document.getElementById('setupFeeGrade').value;
    const container = document.getElementById('dynamicFeeList');
    if(!container) return;
    container.innerHTML = ''; 
    const existingFees = window.feeStructures[grade] || [{name: 'Tuition Fee', amount: ''}];
    existingFees.forEach(fee => { window.addFeeRow(fee.name, fee.amount); });
};

window.addFeeRow = function(name = '', amount = '') {
    const feeList = document.getElementById('dynamicFeeList');
    if(!feeList) return;
    
    // 1. Create the main horizontal wrapper using the new CSS class
    const row = document.createElement('div');
    row.className = 'fee-row-horizontal'; 
    
    // 2. Create the Name Input (Keeping your original 'fee-name' class!)
    const nameInput = document.createElement('input');
    nameInput.type = 'text';
    nameInput.className = 'input-standard fee-name'; 
    nameInput.placeholder = 'Charge Name (e.g. Bus Fare)';
    nameInput.value = name;
    
    // 3. Create the Amount Input (Keeping your original 'fee-amount' class!)
    const amtInput = document.createElement('input');
    amtInput.type = 'number';
    amtInput.className = 'input-standard fee-amount'; 
    amtInput.placeholder = 'Amount ($)';
    amtInput.value = amount;
    
    // 4. Create the Delete Button (Adding Teacher View-Only restrictions)
    const delBtn = document.createElement('button');
    delBtn.className = 'btn-standard btn-danger admin-edit-only';
    delBtn.innerHTML = '❌';
    delBtn.onclick = function() {
        row.remove(); // Clean closure deletion! No random IDs needed.
    };
    
    // 5. Pack them all into the wrapper and push to the screen
    row.appendChild(nameInput);
    row.appendChild(amtInput);
    row.appendChild(delBtn);
    
    feeList.appendChild(row);
};

window.saveFeeStructure = async function() {
    // 1. Authorization Check
    const role = window.currentUser?.role || "";
    if (!(role.includes('Level 2') || role.includes('Level 3') || role === 'Admin' || role === 'Chief Admin')) {
        return alert("❌ Access Denied: Only Admins can modify fee structures.");
    }

    // 2. Gather Data from the UI
    const grade = document.getElementById('setupFeeGrade').value;
    const rows = document.getElementById('dynamicFeeList').children;
    const newFees = [];
    let hasValidFee = false;

    for (let i = 0; i < rows.length; i++) {
        const name = rows[i].querySelector('.fee-name').value.trim();
        const amount = parseFloat(rows[i].querySelector('.fee-amount').value) || 0;
        if (name && amount > 0) { 
            newFees.push({ name: name, amount: amount }); 
            hasValidFee = true; 
        }
    }
    
    if (!hasValidFee && rows.length > 0) {
        return alert("Please enter at least one valid Charge Name and Amount greater than 0.");
    }

    // 3. Update Local State (Array-Safe & Legacy Compatible)
    if (!window.feeStructures) window.feeStructures = []; // Safety initialization

    if (Array.isArray(window.feeStructures)) {
        const existingIndex = window.feeStructures.findIndex(f => f.id === grade || f.grade === grade);
        if (existingIndex >= 0) {
            window.feeStructures[existingIndex].fees = newFees; // Update existing
        } else {
            window.feeStructures.push({ id: grade, fees: newFees }); // Add new
        }
    } else {
        // Fallback just in case it is still running on the old object structure
        window.feeStructures[grade] = newFees;
    }

    // 4. Cache Locally
    localStorage.setItem('havenFeeStructures', JSON.stringify(window.feeStructures));

    // 5. Offline Handling & Early UI Refresh
    if (!navigator.onLine) {
        if (typeof window.renderFeeStructures === 'function') window.renderFeeStructures(); 
        return alert(`⚠️ Saved locally for ${grade}, but you are offline. It will sync when connection is restored.`);
    }

    // 6. Push to Cloud (Supabase)
    try {
        const { error } = await supabaseClient
            .from('fee_structures')
            .upsert({ id: grade, fees: newFees });
            
        if (error) throw error;
        console.log(`✅ Fee Structure for ${grade} blasted to the cloud!`);
    } catch (err) {
        console.error("Cloud Error:", err.message);
        alert("⚠️ Fees saved locally, but failed to reach the cloud.");
    }

    // 7. Final Instant UI Refresh
    if (typeof window.renderFeeStructures === 'function') window.renderFeeStructures(); 
    alert(`✅ Fee Structure saved successfully for ${grade}!`);
};

