// ==========================================

window.deleteFeeStructure = async function(grade) {
    // 1. Authorization Check
    const role = window.currentUser?.role || "";
    if (!(role.includes('Level 2') || role.includes('Level 3') || role === 'Admin' || role === 'Chief Admin')) {
        return alert("❌ Access Denied: Only Admins can delete fee structures.");
    }

    if (!navigator.onLine) return alert("⚠️ You are offline. Please connect to the internet to delete fee structures.");
    
    // Put quotes around the grade so we can see if there are accidental blank spaces!
    const confirmDelete = confirm(`Are you absolutely sure you want to delete the Fee Structure for: "${grade}"?`);
    if (!confirmDelete) return;

    // 2. Delete from Supabase FIRST (and use .select() to confirm it worked)
    try {
        const { data, error } = await supabaseClient
            .from('fee_structures')
            .delete()
            .eq('id', grade)
            .select(); // .select() forces Supabase to return the row it just deleted
            
        // If Supabase threw an error (like an RLS policy blocking you)
        if (error) {
            console.error("Database Delete Error:", error);
            return alert(`❌ Database refused to delete: ${error.message}`);
        }

        // If no error, but it didn't find the row to delete (Mismatched spaces!)
        if (!data || data.length === 0) {
            console.warn(`Attempted to delete "${grade}", but it wasn't found in the database.`);
            return alert(`⚠️ Could not find "${grade}" in the database. It might have hidden spaces or was already deleted.`);
        }

        console.log("✅ Successfully deleted from cloud:", data);

    } catch(e) { 
        console.error("Critical Cloud error:", e); 
        return alert("❌ An unexpected error occurred while contacting the database.");
    }

    // 3. ONLY if the cloud delete was successful, we clean up the local storage
    if (Array.isArray(window.feeStructures)) {
        window.feeStructures = window.feeStructures.filter(f => f.id !== grade && f.grade !== grade);
    } else {
        delete window.feeStructures[grade];
    }
    
    localStorage.setItem('havenFeeStructures', JSON.stringify(window.feeStructures));
    
    // 4. Refresh the UI
    window.renderFeeStructures();
};

window.runJanuaryBillingEngine = async function() {
    const today = new Date();
    const targetTerm = typeof window.getCurrentTerm === 'function' ? window.getCurrentTerm() : '';
    if (!window.requireLevel3BillingAccess()) return;
    if (today.getMonth() !== 0 || !/^Term 1\s+\d{4}$/.test(targetTerm)) {
        return window.alert('This process is available only in January during Term 1.');
    }
    if (!window.appDataReady) {
        return window.alert('Billing is blocked until verified student and ledger records have finished loading.');
    }

    const year = today.getFullYear();
    const dateStr = `${year}-01-${String(today.getDate()).padStart(2, '0')}`;
    const monthTag = `January ${year}`;
    const termTag = `Term 1 ${year}`;
    const batchId = `JAN-${year}-${Date.now().toString().slice(-6)}`;
    const money = value => Number.isFinite(Number(value)) ? Number(value) : 0;
    const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g, character => ({
        '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    })[character]);

    const normalizeClass = value => {
        const normalized = String(value || '').trim().replace(/\s+/g, ' ').toLowerCase();
        const baseClass = normalized.match(/^(ecd\s+[a-z]|grade\s+\d+|form\s+\d+|lower\s+6|upper\s+6)\b/);
        return baseClass ? baseClass[1].replace(/\s+/g, ' ') : normalized;
    };
    const classPromotions = {
        'ecd a': 'ECD B',
        'ecd b': 'Grade 1',
        'grade 1': 'Grade 2',
        'grade 2': 'Grade 3',
        'grade 3': 'Grade 4',
        'grade 4': 'Grade 5',
        'grade 5': 'Grade 6',
        'grade 6': 'Grade 7',
        'form 1': 'Form 2',
        'form 2': 'Form 3',
        'form 3': 'Form 4',
        'form 5': 'Form 6',
        'lower 6': 'Upper 6'
    };

    const getEnrollmentDate = student => {
        const recordedDate = student.enrollDate || student.enroll_date;
        if (recordedDate && !Number.isNaN(new Date(recordedDate).getTime())) {
            return new Date(recordedDate);
        }
        const firstCharge = (Array.isArray(student.ledger) ? student.ledger : [])
            .filter(entry => !['VOID', 'VOIDED'].includes(String(entry.status || '').toUpperCase()))
            .map(entry => entry.date)
            .filter(Boolean)
            .sort()[0];
        return firstCharge && !Number.isNaN(new Date(firstCharge).getTime()) ? new Date(firstCharge) : null;
    };

    const getPromotion = student => {
        const currentGrade = String(student.grade || '').trim();
        const key = normalizeClass(currentGrade);
        const enrollmentDate = getEnrollmentDate(student);
        if (!enrollmentDate) {
            return { grade: currentGrade, reason: 'Enrollment date unavailable; review class manually.' };
        }
        const enrollmentMonth = enrollmentDate.getMonth() + 1;
        const enrollmentDay = enrollmentDate.getDate();
        const isTermThree = (enrollmentMonth === 8 && enrollmentDay >= 7) ||
            (enrollmentMonth >= 9 && enrollmentMonth <= 12);
        if (isTermThree || enrollmentMonth === 1) {
            return { grade: currentGrade, reason: 'Late Term 3 / January enrolment; retain current class.' };
        }
        if (key === 'grade 7' || key === 'form 4') {
            return { grade: currentGrade, reason: 'Transfer placement required; retain current class.' };
        }
        const nextGrade = classPromotions[key];
        return nextGrade
            ? { grade: nextGrade, reason: `Progress to ${nextGrade}.` }
            : { grade: currentGrade, reason: 'No automatic progression rule; retain current class.' };
    };

    const getLedgerBalance = ledger => (Array.isArray(ledger) ? ledger : []).reduce((balance, entry) => {
        if (['VOID', 'VOIDED', 'REVERSAL'].includes(String(entry.status || '').toUpperCase())) return balance;
        const type = String(entry.type || '').toLowerCase();
        const amount = money(entry.amount);
        if (type === 'charge' || type === 'fee') return balance + amount;
        if (['payment', 'discount', 'waiver', 'credit', 'overpayment'].includes(type)) return balance - amount;
        return balance;
    }, 0);

    const feeStructures = window.feeStructures || {};
    const getGradeFees = student => {
        if (Array.isArray(feeStructures)) {
            const structure = feeStructures.find(item => (item.id || item.grade) === student.grade);
            const fees = structure ? (structure.fees || structure.items || []) : [];
            return Array.isArray(fees) ? fees : [];
        }
        const fees = feeStructures[student.grade];
        return Array.isArray(fees) ? fees : [];
    };

    const settings = window.settings || {};
    const termlyTuitionFallback = parseFloat(localStorage.getItem('setTermlyTuition')) || money(settings.termlyTuition) || 150;
    const foodCost = parseFloat(localStorage.getItem('setFoodFee')) || money(settings.foodFee) || 20;
    const stationeryECD = parseFloat(localStorage.getItem('setStatECD')) || money(settings.stationeryFeeECD) || 20;
    const stationeryGrades = parseFloat(localStorage.getItem('setStatGrades')) || money(settings.stationeryFeeGrades) || 20;
    const textbookCost = parseFloat(localStorage.getItem('setTextbookFee')) || money(settings.textbookFee) || 30;
    const termMonths = ['january', 'february', 'march', 'april'];
    const studentsToReview = [];

    const hasExistingCharge = (ledger, category, tag, frequency) => (Array.isArray(ledger) ? ledger : []).some(entry => {
        if (String(entry.status || '').toUpperCase() === 'VOID' || String(entry.status || '').toUpperCase() === 'VOIDED') return false;
        const description = String(entry.description || entry.desc || '').toLowerCase();
        const matchesCategory = category === 'tuition' ? description.includes('tuition') :
            category === 'transport' ? description.includes('transport') :
            category === 'food' ? description.includes('food') :
            category === 'stationery' ? description.includes('stationery') :
            description.includes('textbook');
        if (!matchesCategory) return false;
        if (frequency === 'once-off') return true;
        const entryTerm = String(entry.term || '').toLowerCase();
        const tagMatches = entryTerm === tag.toLowerCase() || description.includes(tag.toLowerCase());
        if (frequency === 'monthly') return tagMatches;
        if (frequency === 'termly') {
            return tagMatches || termMonths.some(month => description.includes(month) || entryTerm.includes(month));
        }
        return tagMatches || entryTerm.startsWith(tag.toLowerCase()) || description.includes(tag.toLowerCase()) ||
            String(entry.date || '').startsWith(tag);
    });

    const activeStudents = (window.students || []).filter(student => {
        const status = String(student.enrollmentStatus || student.enrollment_status || student.status || '').toLowerCase();
        return status === 'active' || status === 'pending_payment';
    });

    activeStudents.forEach(student => {
        const ledger = Array.isArray(student.ledger) ? student.ledger : [];
        const billingPlan = String(student.billing_plan || student.billingPlan || 'termly').toLowerCase();
        const gradeFees = getGradeFees(student);
        const configuredTuition = gradeFees.reduce((total, fee) => {
            const name = String(fee.name || fee.desc || '').toLowerCase();
            return total + ((name.includes('tuition') || name.includes('term') || name === 'fee') ? money(fee.amount) : 0);
        }, 0);
        const baseTuition = configuredTuition || termlyTuitionFallback;
        const tuitionAmount = billingPlan === 'exempt' ? 0 :
            billingPlan === 'monthly' ? Number((baseTuition / 3).toFixed(2)) :
            billingPlan === 'yearly' ? baseTuition * 3 : baseTuition;
        const plannedCharges = [];
        const addCharge = (category, description, amount, tag, frequency) => {
            if (billingPlan === 'exempt' || amount <= 0 || hasExistingCharge(ledger, category, tag, frequency)) return;
            plannedCharges.push({
                id: `CHG-AUTO-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
                student_id: student.id,
                date: dateStr,
                type: 'charge',
                amount,
                category,
                description,
                term: tag,
                status: 'ACTIVE',
                batch_id: batchId
            });
        };

        if (billingPlan === 'monthly') {
            addCharge('tuition', `Tuition Fee - ${monthTag} (Monthly)`, tuitionAmount, monthTag, 'monthly');
        } else if (billingPlan === 'yearly') {
            addCharge('tuition', `Tuition Fee - ${year} (Yearly)`, tuitionAmount, String(year), 'yearly');
        } else if (billingPlan !== 'exempt') {
            addCharge('tuition', `Tuition Fee (${termTag})`, tuitionAmount, termTag, 'termly');
        }

        const transportAmount = getStudentTransportFare(student);
        if (transportAmount > 0) {
            addCharge('transport', `Transport Service - ${monthTag}`, transportAmount, monthTag, 'monthly');
        }

        const wantsFood = String(student.food_program ?? student.foodProgram) === 'true';
        if (wantsFood) {
            const foodBilledThisTerm = ledger.reduce((total, entry) => {
                if (String(entry.status || '').toUpperCase() === 'VOID' || String(entry.status || '').toUpperCase() === 'VOIDED') return total;
                const description = String(entry.description || entry.desc || '').toLowerCase();
                const entryTerm = String(entry.term || '').toLowerCase();
                const belongsToTerm = entryTerm.includes(termTag.toLowerCase()) || description.includes(termTag.toLowerCase()) ||
                    termMonths.some(month => entryTerm.includes(month) || description.includes(month));
                return String(entry.type || '').toLowerCase() === 'charge' && description.includes('food') && belongsToTerm
                    ? total + money(entry.amount)
                    : total;
            }, 0);
            if (foodCost - foodBilledThisTerm > 0) {
                addCharge('food', `Food Program - ${termTag}`, foodCost - foodBilledThisTerm, termTag, 'termly');
            }
        }

        const wantsStationery = String(student.stationery_pack ?? student.stationeryPack) === 'true';
        if (wantsStationery) {
            const gradeName = String(student.grade || '').toUpperCase();
            addCharge('stationery', `Stationery Pack - ${year}`, gradeName.includes('ECD') ? stationeryECD : stationeryGrades, String(year), 'yearly');
        }

        const wantsTextbooks = String(student.textbooks) === 'true';
        if (wantsTextbooks) {
            addCharge('textbooks', 'Textbook Fee (Once-Off)', textbookCost, 'Once-Off', 'once-off');
        }

        const totalCharges = plannedCharges.reduce((total, charge) => total + charge.amount, 0);
        const currentBalance = getLedgerBalance(ledger);
        const promotion = getPromotion(student);
        studentsToReview.push({
            id: student.id,
            name: student.name || 'Unnamed student',
            currentGrade: student.grade || 'Unassigned',
            nextGrade: promotion.grade,
            promotionReason: promotion.reason,
            totalCharges,
            newBalance: currentBalance + totalCharges,
            charges: plannedCharges
        });
    });

    if (studentsToReview.length === 0) {
        return window.alert('There are no active or pending-payment students to review.');
    }
    const getSelectedActions = () => studentsToReview.map((student, index) => {
        const row = document.querySelector(`[data-january-row-index="${index}"]`);
        const billSelected = row ? row.querySelector('.january-bill-checkbox').checked : true;
        const currentStudent = (window.students || []).find(item => String(item.id) === String(student.id));
        return {
            ...student,
            billSelected,
            progressionSelected: row ? row.querySelector('.january-progression-checkbox').checked : true,
            newBalance: billSelected ? student.newBalance : getLedgerBalance(currentStudent?.ledger)
        };
    });
    const buildGradeSummary = selectedStudents => {
        const gradeRows = new Map();
        selectedStudents.forEach(student => {
            const grade = student.currentGrade || 'Unassigned';
            if (!gradeRows.has(grade)) {
                gradeRows.set(grade, {
                    grade,
                    billingStudents: 0,
                    chargeCount: 0,
                    tuition: 0,
                    transport: 0,
                    food: 0,
                    stationery: 0,
                    textbooks: 0,
                    other: 0,
                    total: 0,
                    classMoves: 0
                });
            }
            const row = gradeRows.get(grade);
            if (student.billSelected && student.charges.length > 0) {
                row.billingStudents++;
            }
            if (student.billSelected) {
                student.charges.forEach(charge => {
                    const category = String(charge.category || '').toLowerCase();
                    const amount = money(charge.amount);
                    if (category === 'tuition') row.tuition += amount;
                    else if (category === 'transport') row.transport += amount;
                    else if (category === 'food') row.food += amount;
                    else if (category === 'stationery') row.stationery += amount;
                    else if (category === 'textbooks') row.textbooks += amount;
                    else row.other += amount;
                    row.total += amount;
                    row.chargeCount++;
                });
            }
            if (student.progressionSelected && student.currentGrade !== student.nextGrade) row.classMoves++;
        });
        return Array.from(gradeRows.values()).sort((a, b) => a.grade.localeCompare(b.grade, undefined, { numeric: true }));
    };
    const currency = amount => `$${money(amount).toFixed(2)}`;
    const totalPlanned = studentsToReview.reduce((sum, student) => sum + student.totalCharges, 0);
    const promotionCount = studentsToReview.filter(student => student.currentGrade !== student.nextGrade).length;
    const modalHtml = `
        <div id="januaryBillingPreviewModal" style="position:fixed; inset:0; z-index:10000; display:flex; align-items:center; justify-content:center; padding:18px; background:rgba(15,29,48,.68);">
            <div style="width:1400px; max-width:100%; max-height:94vh; overflow:hidden; display:flex; flex-direction:column; border-radius:14px; background:#fff; box-shadow:0 20px 60px rgba(0,0,0,.25);">
                <div style="padding:20px 24px; color:#fff; background:linear-gradient(120deg,#17365d,#2878a8);">
                    <div style="display:flex; justify-content:space-between; align-items:flex-start; gap:12px;">
                        <div><div style="font-size:11px; letter-spacing:1px; opacity:.8;">LEVEL 3 · PRE-DEPLOYMENT REVIEW · ${year}</div><h2 style="margin:5px 0; font-size:21px;">January Billing &amp; Class Progression Plan</h2><div style="font-size:12px; opacity:.9;">Review the planned actions and grade totals, adjust each option, and print before deployment.</div></div>
                        <button type="button" onclick="document.getElementById('januaryBillingPreviewModal').remove()" aria-label="Close preview" style="border:0; color:#fff; background:transparent; font-size:26px; cursor:pointer;">&times;</button>
                    </div>
                </div>
                <div style="display:flex; flex-wrap:wrap; gap:10px; padding:14px 20px; background:#f5f8fb; border-bottom:1px solid #e3eaf2;">
                    <div style="padding:10px 14px; border-radius:8px; background:#fff; border:1px solid #e3eaf2;"><small style="color:#718096;">Active students in plan</small><div style="font-weight:700; color:#20344d;">${studentsToReview.length}</div></div>
                    <div style="padding:10px 14px; border-radius:8px; background:#fff; border:1px solid #e3eaf2;"><small style="color:#718096;">Selected new charges</small><div id="januarySelectedTotal" style="font-weight:700; color:#20344d;">${currency(totalPlanned)}</div></div>
                    <div style="padding:10px 14px; border-radius:8px; background:#fff; border:1px solid #e3eaf2;"><small style="color:#718096;">Selected class moves</small><div id="januarySelectedMoves" style="font-weight:700; color:#20344d;">${promotionCount}</div></div>
                </div>
                <div style="overflow:auto; flex:1; padding:15px 20px;">
                    <h3 style="margin:2px 0 9px; color:#20344d; font-size:15px;">Selected actions by current grade</h3>
                    <div style="overflow:auto; margin-bottom:20px; border:1px solid #e3eaf2; border-radius:8px;">
                    <table style="width:100%; min-width:920px; border-collapse:collapse; font-size:11px;">
                        <thead style="background:#eef3f8; color:#34495e;">
                            <tr>
                                <th style="padding:9px; text-align:left;">Current grade</th><th style="padding:9px;">Students with new charges</th>
                                <th style="padding:9px; text-align:right;">Tuition</th><th style="padding:9px; text-align:right;">Transport</th>
                                <th style="padding:9px; text-align:right;">Food</th><th style="padding:9px; text-align:right;">Stationery</th>
                                <th style="padding:9px; text-align:right;">Textbooks</th><th style="padding:9px; text-align:right;">Other</th>
                                <th style="padding:9px; text-align:right;">Total charges</th><th style="padding:9px;">Class moves</th>
                            </tr>
                        </thead>
                        <tbody id="januaryGradeSummaryBody"></tbody>
                        <tfoot id="januaryGradeSummaryFoot"></tfoot>
                    </table>
                    </div>
                    <div style="display:flex; flex-wrap:wrap; justify-content:space-between; align-items:center; gap:10px; margin-bottom:9px;">
                        <h3 style="margin:2px 0; color:#20344d; font-size:15px;">Student-by-student deployment options</h3>
                        <label style="font-size:12px; color:#52677f;"><input id="januarySelectAll" type="checkbox" checked> Select all billing and class-move options</label>
                    </div>
                    <div style="overflow:auto; border:1px solid #e3eaf2; border-radius:8px;">
                    <table style="width:100%; min-width:1050px; border-collapse:collapse; font-size:12px;">
                        <thead style="position:sticky; top:0; z-index:1; background:#eef3f8; color:#34495e;">
                            <tr><th style="padding:10px;">Bill</th><th style="padding:10px;">Apply class move</th><th style="padding:10px; text-align:left;">Student</th><th style="padding:10px; text-align:left;">Class plan / reason</th><th style="padding:10px; text-align:left;">Charges that will be added</th><th style="padding:10px; text-align:right;">New charges</th><th style="padding:10px; text-align:right;">Projected balance</th></tr>
                        </thead>
                        <tbody>
                            ${studentsToReview.map((student, index) => `
                                <tr data-january-row-index="${index}" style="border-bottom:1px solid #edf1f5;">
                                    <td style="padding:10px 8px; text-align:center;"><input type="checkbox" class="january-bill-checkbox" checked aria-label="Bill ${escapeHtml(student.name)}"></td>
                                    <td style="padding:10px 8px; text-align:center;"><input type="checkbox" class="january-progression-checkbox" ${student.currentGrade !== student.nextGrade ? 'checked' : 'disabled'} aria-label="Apply class move for ${escapeHtml(student.name)}"></td>
                                    <td style="padding:10px 8px;"><strong>${escapeHtml(student.name)}</strong><br><small style="color:#8391a2;">${escapeHtml(student.id)}</small></td>
                                    <td style="padding:10px 8px;"><strong>${escapeHtml(student.currentGrade)}${student.currentGrade !== student.nextGrade ? ` → ${escapeHtml(student.nextGrade)}` : ''}</strong><br><small style="color:#718096;">${escapeHtml(student.promotionReason)}</small></td>
                                    <td style="padding:10px 8px; color:#53657a;">${student.charges.length ? student.charges.map(charge => escapeHtml(charge.description)).join('<br>') : '<span style="color:#8492a6;">No new charges (ledger already covered)</span>'}</td>
                                    <td style="padding:10px 8px; text-align:right; font-weight:700;">${currency(student.totalCharges)}</td>
                                    <td style="padding:10px 8px; text-align:right;"><span class="january-projected-balance">$${Math.abs(student.newBalance).toFixed(2)} ${student.newBalance < 0 ? 'credit' : 'due'}</span></td>
                                </tr>`).join('')}
                        </tbody>
                    </table>
                    </div>
                </div>
                <div style="display:flex; flex-wrap:wrap; align-items:center; justify-content:space-between; gap:12px; padding:15px 20px; border-top:1px solid #e3eaf2; background:#f8fafc;">
                    <small style="color:#718096;">This is a pre-deployment plan. Print and review the selected figures; database records change only after final confirmation.</small>
                    <div style="display:flex; gap:9px;">
                        <button type="button" onclick="document.getElementById('januaryBillingPreviewModal').remove()" class="btn-standard" style="background:#fff; color:#34495e; border:1px solid #ccd6e0;">Cancel</button>
                        <button type="button" id="printJanuaryBilling" class="btn-standard" style="background:#fff; color:#20344d; border:1px solid #ccd6e0;">Print preview</button>
                        <button type="button" id="confirmJanuaryBilling" class="btn-standard btn-success" style="padding:10px 16px;">Deploy selected actions</button>
                    </div>
                </div>
            </div>
        </div>`;

    document.body.insertAdjacentHTML('beforeend', modalHtml);
    const renderGradeSummary = () => {
        const selectedStudents = getSelectedActions();
        const rows = buildGradeSummary(selectedStudents);
        const totals = rows.reduce((summary, row) => {
            ['billingStudents', 'chargeCount', 'tuition', 'transport', 'food', 'stationery', 'textbooks', 'other', 'total', 'classMoves']
                .forEach(key => summary[key] += row[key]);
            return summary;
        }, { billingStudents:0, chargeCount:0, tuition:0, transport:0, food:0, stationery:0, textbooks:0, other:0, total:0, classMoves:0 });
        const cell = (value, right = true) => `<td style="padding:8px 9px; text-align:${right ? 'right' : 'left'}; border-bottom:1px solid #edf1f5;">${value}</td>`;
        document.getElementById('januaryGradeSummaryBody').innerHTML = rows.map(row => `
            <tr>${cell(escapeHtml(row.grade), false)}${cell(row.billingStudents)}${cell(currency(row.tuition))}${cell(currency(row.transport))}${cell(currency(row.food))}${cell(currency(row.stationery))}${cell(currency(row.textbooks))}${cell(currency(row.other))}${cell(`<strong>${currency(row.total)}</strong>`)}${cell(row.classMoves)}</tr>`).join('');
        document.getElementById('januaryGradeSummaryFoot').innerHTML = `
            <tr style="background:#f5f8fb; font-weight:700;">${cell('TOTAL', false)}${cell(totals.billingStudents)}${cell(currency(totals.tuition))}${cell(currency(totals.transport))}${cell(currency(totals.food))}${cell(currency(totals.stationery))}${cell(currency(totals.textbooks))}${cell(currency(totals.other))}${cell(currency(totals.total))}${cell(totals.classMoves)}</tr>`;
        document.getElementById('januarySelectedTotal').textContent = currency(totals.total);
        document.getElementById('januarySelectedMoves').textContent = String(totals.classMoves);
        document.getElementById('confirmJanuaryBilling').textContent =
            `Deploy ${totals.chargeCount} charges · ${totals.classMoves} class moves`;
        selectedStudents.forEach((student, index) => {
            const row = document.querySelector(`[data-january-row-index="${index}"]`);
            if (row) row.querySelector('.january-projected-balance').textContent =
                `${currency(Math.abs(student.newBalance))} ${student.newBalance < 0 ? 'credit' : 'due'}`;
        });
    };
    const selectAll = document.getElementById('januarySelectAll');
    selectAll.addEventListener('change', function() {
        document.querySelectorAll('.january-bill-checkbox').forEach(checkbox => checkbox.checked = this.checked);
        document.querySelectorAll('.january-progression-checkbox:not(:disabled)').forEach(checkbox => checkbox.checked = this.checked);
        renderGradeSummary();
    });
    document.querySelectorAll('.january-bill-checkbox, .january-progression-checkbox').forEach(checkbox => {
        checkbox.addEventListener('change', function() {
            const billOptions = Array.from(document.querySelectorAll('.january-bill-checkbox'));
            const progressionOptions = Array.from(document.querySelectorAll('.january-progression-checkbox:not(:disabled)'));
            selectAll.checked = billOptions.every(option => option.checked) && progressionOptions.every(option => option.checked);
            renderGradeSummary();
        });
    });
    renderGradeSummary();

    document.getElementById('printJanuaryBilling').addEventListener('click', function() {
        const selectedStudents = getSelectedActions();
        const gradeRows = buildGradeSummary(selectedStudents);
        const selectedCharges = selectedStudents.reduce((sum, student) => sum + (student.billSelected ? student.totalCharges : 0), 0);
        const selectedMoves = selectedStudents.filter(student => student.progressionSelected && student.currentGrade !== student.nextGrade).length;
        const gradeTotals = gradeRows.reduce((summary, row) => {
            ['billingStudents', 'tuition', 'transport', 'food', 'stationery', 'textbooks', 'other', 'total', 'classMoves']
                .forEach(key => summary[key] += row[key]);
            return summary;
        }, { billingStudents:0, tuition:0, transport:0, food:0, stationery:0, textbooks:0, other:0, total:0, classMoves:0 });
        const printWindow = window.open('', '_blank');
        if (!printWindow) return window.alert('The printable preview was blocked by the browser. Allow pop-ups for this site and try again.');
        const gradeTable = `${gradeRows.map(row => `<tr><td>${escapeHtml(row.grade)}</td><td>${row.billingStudents}</td><td>${currency(row.tuition)}</td><td>${currency(row.transport)}</td><td>${currency(row.food)}</td><td>${currency(row.stationery)}</td><td>${currency(row.textbooks)}</td><td>${currency(row.other)}</td><td><strong>${currency(row.total)}</strong></td><td>${row.classMoves}</td></tr>`).join('')}
            <tr><th>TOTAL</th><th>${gradeTotals.billingStudents}</th><th>${currency(gradeTotals.tuition)}</th><th>${currency(gradeTotals.transport)}</th><th>${currency(gradeTotals.food)}</th><th>${currency(gradeTotals.stationery)}</th><th>${currency(gradeTotals.textbooks)}</th><th>${currency(gradeTotals.other)}</th><th>${currency(gradeTotals.total)}</th><th>${gradeTotals.classMoves}</th></tr>`;
        const studentRows = selectedStudents.filter(student => student.billSelected || student.progressionSelected).map(student => `
            <tr><td>${escapeHtml(student.name)}<br><small>${escapeHtml(student.id)}</small></td>
            <td>${student.billSelected ? 'YES' : 'NO'}</td>
            <td>${student.progressionSelected && student.currentGrade !== student.nextGrade ? `${escapeHtml(student.currentGrade)} → ${escapeHtml(student.nextGrade)}` : 'No change'}</td>
            <td>${student.billSelected && student.charges.length ? student.charges.map(charge => `${escapeHtml(charge.description)} (${currency(charge.amount)})`).join('<br>') : 'No new charges'}</td>
            <td>${currency(student.billSelected ? student.totalCharges : 0)}</td><td>${currency(Math.abs(student.newBalance))} ${student.newBalance < 0 ? 'credit' : 'due'}</td></tr>`).join('');
        printWindow.document.open();
        printWindow.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>January Billing Preview ${year}</title><style>
            body{font:12px Arial,sans-serif;color:#20344d;margin:24px}h1{font-size:20px;margin:0 0 5px}h2{font-size:15px;margin:22px 0 8px}.meta{color:#52677f;margin:0 0 15px}
            table{width:100%;border-collapse:collapse;margin:8px 0 18px}th,td{border:1px solid #cbd5df;padding:6px;text-align:left;vertical-align:top}th{background:#eef3f8}td:nth-child(n+2){text-align:right}
            .summary{display:flex;gap:24px;padding:10px;background:#f5f8fb;border:1px solid #dce6f1}.note{margin-top:16px;font-size:11px;color:#52677f}
            @page{size:landscape;margin:12mm}@media print{button{display:none}}
        </style></head><body>
            <h1>January Billing &amp; Class Progression — Review Copy</h1>
            <p class="meta">Academic year ${year} · ${escapeHtml(termTag)} · Batch ${escapeHtml(batchId)} · Prepared ${escapeHtml(dateStr)}</p>
            <div class="summary"><strong>New charges: ${currency(selectedCharges)}</strong><strong>Class moves: ${selectedMoves}</strong><strong>Students with new charges: ${selectedStudents.filter(student => student.billSelected && student.charges.length > 0).length}</strong></div>
            <h2>Selected totals by current grade</h2><table><thead><tr><th>Grade</th><th>Students with new charges</th><th>Tuition</th><th>Transport</th><th>Food</th><th>Stationery</th><th>Textbooks</th><th>Other</th><th>Total charges</th><th>Class moves</th></tr></thead><tbody>${gradeTable}</tbody></table>
            <h2>Selected student actions</h2><table><thead><tr><th>Student</th><th>Bill</th><th>Class progression</th><th>Charges to add</th><th>New charges</th><th>Projected balance</th></tr></thead><tbody>${studentRows || '<tr><td colspan="6">No actions selected</td></tr>'}</tbody></table>
            <p class="note">Review copy only. Nothing is written to the student ledger or class records until a Level 3 user confirms deployment in the application.</p>
            <script>window.onload=function(){window.print();};</script></body></html>`);
        printWindow.document.close();
    });

    document.getElementById('confirmJanuaryBilling').onclick = async function() {
        const selectedStudents = getSelectedActions().filter(student => student.billSelected || student.progressionSelected);
        if (selectedStudents.length === 0) {
            return window.alert('Select at least one billing or class-progression action before deployment.');
        }

        if (!window.requireLevel3BillingAccess() || new Date().getMonth() !== 0 ||
            typeof window.getCurrentTerm !== 'function' || !/^Term 1\s+\d{4}$/.test(window.getCurrentTerm())) {
            return window.alert('Billing was not submitted. Confirm that it is still January in Term 1.');
        }
        if (!window.appDataReady || !window.supabaseClient) {
            return window.alert('Billing was not submitted. Verified cloud data or the database connection is no longer available.');
        }

        this.disabled = true;
        this.textContent = 'Saving selected records…';
        let writeAttempted = false;
        try {
            const selectedCharges = selectedStudents.flatMap(student => student.billSelected ? student.charges : [])
                .map(({ category, ...charge }) => charge);
            const studentUpdates = selectedStudents.map(student => ({
                id: student.id,
                ...(student.progressionSelected ? { grade: student.nextGrade } : {}),
                ...(student.billSelected ? { balance_owing: student.newBalance } : {})
            }));
            const chunkSize = 100;

            for (let index = 0; index < selectedCharges.length; index += chunkSize) {
                writeAttempted = true;
                const { error } = await window.supabaseClient
                    .from('student_ledger')
                    .insert(selectedCharges.slice(index, index + chunkSize));
                if (error) throw error;
            }
            for (let index = 0; index < studentUpdates.length; index += chunkSize) {
                writeAttempted = true;
                const { error } = await window.supabaseClient
                    .from('students')
                    .upsert(studentUpdates.slice(index, index + chunkSize), { onConflict: 'id' });
                if (error) throw error;
            }

            selectedStudents.forEach(reviewedStudent => {
                const student = (window.students || []).find(item => String(item.id) === String(reviewedStudent.id));
                if (!student) return;
                if (!Array.isArray(student.ledger)) student.ledger = [];
                if (reviewedStudent.billSelected) {
                    student.ledger.push(...reviewedStudent.charges);
                    student.balanceOwing = reviewedStudent.newBalance;
                    student.balance_owing = reviewedStudent.newBalance;
                }
                if (reviewedStudent.progressionSelected) student.grade = reviewedStudent.nextGrade;
            });
            localStorage.setItem('haven_students', JSON.stringify(window.students || []));
            document.getElementById('januaryBillingPreviewModal').remove();
            if (typeof window.filterDirectory === 'function') window.filterDirectory();
            if (typeof window.updateDashboard === 'function') window.updateDashboard();
            if (typeof window.calculateAdminFinanceStats === 'function') window.calculateAdminFinanceStats();

            const chargeCount = selectedStudents.reduce((total, student) => total + (student.billSelected ? student.charges.length : 0), 0);
            const classChanges = selectedStudents.filter(student => student.progressionSelected && student.currentGrade !== student.nextGrade).length;
            window.alert(`January billing complete.\n\nSelected students: ${selectedStudents.length}\nLedger charges added: ${chargeCount}\nClass changes: ${classChanges}\nBilling batch: ${batchId}`);
        } catch (error) {
            console.error('January billing could not be completed:', error);
            this.disabled = writeAttempted;
            this.textContent = writeAttempted ? 'Submission needs review' : 'Confirm selected students';
            const partialWriteWarning = writeAttempted
                ? '\n\nA database write may already have succeeded. Do not retry until you verify the student ledger and class records.'
                : '';
            window.alert(`January billing failed: ${error.message || 'Unknown database error.'}${partialWriteWarning}`);
        }
    };
};

// ==========================================
// ACADEMICS, REPORTS & ANALYTICS MODULE
// ==========================================

// --- 1. DATA ENTRY & CLOUD SYNC ---

window.addAcadSubjectRow = function(subject = '', mark = '', teacherComment = '') {
    const list = document.getElementById('acadSubjectsList');
    const row = document.createElement('div');
    row.className = 'acad-subject-row flex-row-stretch';
    row.style.gap = '10px';
    row.style.marginBottom = '10px';
    row.style.alignItems = 'center';
    
    row.innerHTML = `
        <input type="text" class="input-standard subj-name" placeholder="Subject (e.g. Math)" value="${subject}" style="flex: 2; margin-bottom: 0;">
        <input type="number" class="input-standard subj-mark" placeholder="Mark %" value="${mark}" style="flex: 1; margin-bottom: 0;">
        <input type="text" class="input-standard subj-comment" placeholder="Subject Teacher's Comment..." value="${teacherComment}" style="flex: 3; margin-bottom: 0;">
        <button class="btn-standard btn-danger" onclick="this.parentElement.remove()" style="padding: 8px; margin-bottom: 0;" title="Remove Subject">❌</button>
    `;
    list.appendChild(row);
};

window.loadStudentAcademics = function() {
    const rawInput = document.getElementById('acadStudentId').value.trim();
    const studentId = rawInput.split(' ')[0].toUpperCase(); 
    
    const historyBox = document.getElementById('acadHistoryBox');
    const currentTerm = document.getElementById('acadTerm').value;
    const currentYear = parseInt(document.getElementById('acadYear').value);

    if(!studentId) {
        historyBox.innerHTML = '<em style="color: #7f8c8d; font-size: 13px;">No student selected.</em>';
        return;
    }

    const reports = (window.academicReports || []).filter(r => r.student_id === studentId);
    
    reports.sort((a,b) => {
        if (a.academic_year !== b.academic_year) return a.academic_year - b.academic_year;
        return a.term.localeCompare(b.term);
    });

    if(reports.length === 0) {
        historyBox.innerHTML = `<em style="color: #7f8c8d; font-size: 13px;">No previous records for ${studentId}.</em>`;
        document.getElementById('acadSubjectsList').innerHTML = ''; 
        document.getElementById('acadComments').value = '';
        if(document.getElementById('acadStatus')) document.getElementById('acadStatus').value = 'Draft';
        addAcadSubjectRow();
        return;
    }

    historyBox.innerHTML = '';
    
    // Render History Safely
    [...reports].reverse().forEach((rep, index, arr) => {
        let avg = 0; 
        const subs = rep.subjects || []; // Safety fallback
        
        // Fix for NaN Math bug
        subs.forEach(s => avg += (parseFloat(s.mark) || 0)); 
        avg = subs.length > 0 ? (avg / subs.length) : 0;

        let statusBadgeColor = rep.status === 'Ready' ? 'background: #f39c12; color: #fff;' : 
                               rep.status === 'Published' ? 'background: #27ae60; color: #fff;' : 
                               'background: #e8f8f5; color: #27ae60;';

        let subjHtml = subs.map(s => `<li><strong>${s.subject}</strong>: ${s.mark}% <br><span style="font-size:11px; color:#7f8c8d;">- ${s.teacher || 'Teacher'}: "${s.comment || 'No comment'}"</span></li>`).join('');
        
        historyBox.innerHTML += `
            <div style="background: white; padding: 15px; border: 1px solid #bdc3c7; border-radius: 4px; margin-bottom: 10px;">
                <div style="display:flex; justify-content:space-between; align-items: center; border-bottom: 1px solid #ecf0f1; padding-bottom: 5px; margin-bottom: 5px;">
                    <div>
                        <strong style="color: #3498db; font-size: 15px;">${rep.term} ${rep.academic_year}</strong> 
                        <span style="font-size: 11px; padding: 3px 8px; border-radius: 12px; margin-left: 5px; ${statusBadgeColor}">${rep.status || 'Draft'}</span>
                    </div>
                    <div style="display:flex; gap: 5px;">
                        <button class="btn-standard btn-primary" onclick="printReportCard('${rep.id}')" style="padding: 6px 12px; font-size: 11px;">🖨️ Print</button>
                        <button class="btn-standard btn-success" onclick="sendReportWhatsApp('${rep.id}')" style="padding: 6px 12px; font-size: 11px;">💬 WA</button>
                    </div>
                </div>
                <div style="margin: 10px 0;">
                    <small style="color: #555;">Overall Average: <strong style="color: #2c3e50; font-size: 14px;">${avg.toFixed(1)}%</strong></small>
                </div>
                <ul style="margin: 5px 0; padding-left: 20px; font-size: 13px;">${subjHtml}</ul>
                <div style="font-size: 12px; color: #2c3e50; margin-top: 8px; background: #fdfefe; padding: 5px; border-left: 3px solid #f39c12;">
                    <strong>Class Teacher:</strong> ${rep.class_teacher_comment || '<em>Pending...</em>'}
                </div>
            </div>
        `;
    });

    // Collaborative Pre-fill
    const currentReport = reports.find(r => r.term === currentTerm && r.academic_year === currentYear);
    document.getElementById('acadSubjectsList').innerHTML = '';
    if(currentReport) {
        (currentReport.subjects || []).forEach(s => addAcadSubjectRow(s.subject, s.mark, s.comment));
        document.getElementById('acadComments').value = currentReport.class_teacher_comment || '';
        if(document.getElementById('acadStatus')) document.getElementById('acadStatus').value = currentReport.status || 'Draft';
    } else {
        document.getElementById('acadComments').value = '';
        if(document.getElementById('acadStatus')) document.getElementById('acadStatus').value = 'Draft';
        addAcadSubjectRow(); 
    }
};

window.saveAcademicReport = async function() {
    const rawInput = document.getElementById('acadStudentId').value.trim();
    const studentId = rawInput.split(' ')[0].toUpperCase();

    const term = document.getElementById('acadTerm').value;
    const year = parseInt(document.getElementById('acadYear').value) || new Date().getFullYear();
    const classComment = document.getElementById('acadComments').value.trim();
    
    const statusSelect = document.getElementById('acadStatus');
    const workflowStatus = statusSelect ? statusSelect.value : 'Draft';

    if(!studentId) return alert("Please select a student ID first.");

    const student = (window.students || []).find(s => s.id.toUpperCase() === studentId);
    const studentName = student ? student.name : "Unknown Student";
    const className = student ? student.grade || student.class : "Unknown Class";

    const subjectRows = document.querySelectorAll('.acad-subject-row');
    const subjects = [];
    
    subjectRows.forEach(row => {
        const name = row.querySelector('.subj-name').value.trim();
        const markRaw = row.querySelector('.subj-mark').value;
        const mark = markRaw === '' ? 0 : parseFloat(markRaw); // Fix NaN bug
        const comment = row.querySelector('.subj-comment').value.trim();
        if(name) {
            subjects.push({ subject: name, mark: mark, comment: comment, teacher: window.currentUser ? window.currentUser.name : "Teacher" });
        }
    });

    if(subjects.length === 0) return alert("Please add at least one subject.");

    const reportId = `REP-${studentId}-${term.replace(/\s+/g, '')}-${year}`;

    const reportRecord = {
        id: reportId,
        student_id: studentId, 
        student_name: studentName,
        class_name: className,
        term: term,
        academic_year: year,
        subjects: subjects, 
        class_teacher_comment: classComment,
        status: workflowStatus, 
        updated_at: new Date().toISOString()
    };

    // 🛠️ CRITICAL FIX: Save locally so data survives page refresh instantly
    if(!window.academicReports) window.academicReports = [];
    const existingIndex = window.academicReports.findIndex(r => r.id === reportId);
    if(existingIndex > -1) window.academicReports[existingIndex] = reportRecord; 
    else window.academicReports.push(reportRecord); 
    
    // Write to LocalStorage
    localStorage.setItem('haven_academic_reports', JSON.stringify(window.academicReports));

    // Offline check
    if (!navigator.onLine) {
        loadStudentAcademics();
        return alert(`✅ Saved locally for ${studentName}!\nStatus: ${workflowStatus}\nWill sync to cloud when you are back online.`);
    }

    try {
        const { error } = await supabaseClient.from('academic_reports').upsert(reportRecord);
        if (error) throw error;

        alert(`✅ Academic Data Saved to Cloud for ${studentName}!\nStatus: ${workflowStatus}`);
        loadStudentAcademics(); 
    } catch (e) {
        console.error("Academics Error:", e);
        alert("⚠️ Saved locally, but failed to reach cloud: " + e.message);
    }
};

