window.getSubjectGrade = function(mark, studentGrade) {
    const isUpperPrimary = ["Grade 4", "Grade 5", "Grade 6", "Grade 7"].includes(studentGrade);
    if (isUpperPrimary) {
        if (mark >= 75) return "Units 1-2 (Grade A)";
        if (mark >= 65) return "Units 3-4 (Grade B)";
        if (mark >= 50) return "Unit 5 (Grade C)";
        if (mark >= 40) return "Unit 6 (Grade D)";
        return "Units 7-9 (Fail)";
    } else {
        if (mark >= 75) return "A (Distinction)";
        if (mark >= 65) return "B (Merit)";
        if (mark >= 50) return "C (Credit)";
        if (mark >= 40) return "D (Satisfactory)";
        if (mark >= 30) return "E (Pass)";
        return "U (Fail)";
    }
};

window.getStudentArrears = function(student) {
    if (!student) return 0;
    return parseFloat(student.balanceOwing) || 0;
};

window.buildAcademicWaMsg = function(student, rep, arrears) {
    let totalMarks = 0; let subjectText = "";
    rep.subjects.forEach(s => {
        totalMarks += parseFloat(s.mark);
        let gradeStr = window.getSubjectGrade(s.mark, student.grade || student.class);
        subjectText += `▪️ ${s.subject}: ${s.mark}% - ${gradeStr}\n`;
    });
    let avg = rep.subjects.length > 0 ? (totalMarks / rep.subjects.length).toFixed(1) : 0;
    let arrearsText = arrears > 0 ? `*⚠️ Arrears Due:* $${arrears.toFixed(2)}` : `*✅ Fees Status:* Fully Paid ($0 Owed)`;

    return `*${window.settings?.schoolName || 'HAVEN ONLINE'} - OFFICIAL REPORT CARD*\n\n*Student:* ${student.name} (${student.grade || student.class})\n*Term:* ${rep.term} ${rep.academic_year}\n------------------------\n*MARKS:*\n${subjectText}\n*Overall Average:* ${avg}%\n------------------------\n*TEACHER'S REMARKS:*\n${rep.class_teacher_comment || 'No comments provided.'}\n------------------------\n*FINANCIAL STATUS:*\n${arrearsText}\n\nThank you!`;
};

