window.generateSchoolAnalytics = function() {
    const container = document.getElementById('schoolAnalyticsDashboard');
    if (!container) return;
    
    const term = document.getElementById('analyticsTerm').value;
    const year = parseInt(document.getElementById('analyticsYear').value);
    
    const reports = (window.academicReports || []).filter(r => r.term === term && r.academic_year === year);
    
    if(reports.length === 0) {
        container.innerHTML = `<em style="color:#7f8c8d;">No academic data available for ${term} ${year} to analyze.</em>`;
        return;
    }

    let totalSchoolMarks = 0;
    let totalSubjectsCount = 0;
    let subjectTally = {}; // To store averages per subject
    
    reports.forEach(rep => {
        rep.subjects.forEach(s => {
            let mark = parseFloat(s.mark);
            totalSchoolMarks += mark;
            totalSubjectsCount++;
            
            if(!subjectTally[s.subject]) subjectTally[s.subject] = { total: 0, count: 0 };
            subjectTally[s.subject].total += mark;
            subjectTally[s.subject].count++;
        });
    });

    const schoolAverage = (totalSchoolMarks / totalSubjectsCount).toFixed(1);

    // Build Native HTML Bar Charts
    let subjectBarsHtml = '';
    for (const [subj, data] of Object.entries(subjectTally)) {
        let subjAvg = (data.total / data.count).toFixed(1);
        // Color coding based on performance
        let barColor = subjAvg >= 75 ? '#27ae60' : (subjAvg >= 50 ? '#3498db' : '#e74c3c');
        
        subjectBarsHtml += `
            <div style="margin-bottom: 10px;">
                <div style="display: flex; justify-content: space-between; font-size: 13px; margin-bottom: 3px;">
                    <strong>${subj}</strong>
                    <span>${subjAvg}%</span>
                </div>
                <div style="background: #ecf0f1; border-radius: 4px; width: 100%; height: 20px; overflow: hidden;">
                    <div style="background: ${barColor}; width: ${subjAvg}%; height: 100%; transition: width 0.5s;"></div>
                </div>
            </div>
        `;
    }

    container.innerHTML = `
        <div style="background: #2c3e50; color: white; padding: 20px; border-radius: 8px; text-align: center; margin-bottom: 20px;">
            <h4 style="margin: 0; color: #bdc3c7;">WHOLE SCHOOL AVERAGE</h4>
            <h1 style="margin: 5px 0 0 0; font-size: 36px; color: #2ecc71;">${schoolAverage}%</h1>
            <small>${term} ${year} | Based on ${reports.length} report cards</small>
        </div>
        <h4 style="border-bottom: 2px solid #ecf0f1; padding-bottom: 5px; color: #2c3e50;">Subject Performance Analysis</h4>
        ${subjectBarsHtml}
    `;
};
// ==========================================
// 23. INVENTORY & SHOP ENGINE
// ==========================================
/**
 * Calculates flawless, true inventory totals for a specific date range.
 * @param {number} absoluteInitial - The exact quantity when the item was first created in the database.
 * @param {Array} stockAddedLogs - Array of objects: { date: 'YYYY-MM-DD', qty: number }
 * @param {Array} salesLogs - Array of objects: { date: 'YYYY-MM-DD', qty: number }
 * @param {string} startDate - Format 'YYYY-MM-DD' (Optional)
 * @param {string} endDate - Format 'YYYY-MM-DD' (Optional)
 */
window.calculateTrueStockTotals = function(absoluteInitial, stockAddedLogs = [], salesLogs = [], startDate = null, endDate = null) {
    
    let totals = {
        openingStock: absoluteInitial || 0,
        addedDuringPeriod: 0,
        soldDuringPeriod: 0,
        closingStock: 0 // The true remaining
    };

    // 1. Calculate Opening Stock (If a startDate is provided, adjust the initial to that morning)
    if (startDate) {
        let addedBefore = stockAddedLogs
            .filter(log => log.date.split('T')[0] < startDate)
            .reduce((sum, log) => sum + parseInt(log.qty || 0), 0);
            
        let soldBefore = salesLogs
            .filter(log => log.date.split('T')[0] < startDate)
            .reduce((sum, log) => sum + parseInt(log.qty || 0), 0);

        totals.openingStock = totals.openingStock + addedBefore - soldBefore;
    }

    // 2. Calculate Inflows and Outflows strictly WITHIN the date range
    stockAddedLogs.forEach(log => {
        const logDate = log.date.split('T')[0];
        if ((!startDate || logDate >= startDate) && (!endDate || logDate <= endDate)) {
            totals.addedDuringPeriod += parseInt(log.qty || 0);
        }
    });

    salesLogs.forEach(log => {
        const logDate = log.date.split('T')[0];
        if ((!startDate || logDate >= startDate) && (!endDate || logDate <= endDate)) {
            totals.soldDuringPeriod += parseInt(log.qty || 0);
        }
    });

    // 3. The Flawless Final Math
    totals.closingStock = totals.openingStock + totals.addedDuringPeriod - totals.soldDuringPeriod;

    return totals;
};
window.getShopInventoryList = function() {
    if (Array.isArray(window.inventory) && window.inventory.length > 0) return window.inventory;
    if (Array.isArray(window.shopInventory) && window.shopInventory.length > 0) return window.shopInventory;
    if (Array.isArray(window.inventory)) return window.inventory;
    if (Array.isArray(window.shopInventory)) return window.shopInventory;
    return [];
};

window.renderInventory = function() {
    const list = document.getElementById('shopInventoryList');
    if (!list) return;
    
    list.innerHTML = '';
    
    const currentInventory = window.getShopInventoryList();
    const lowStockAlert = document.getElementById('shopLowStockAlerts');
    const lowStockItems = [];
    
    // 🎯 FIX 1: Look in ALL possible memory arrays where the shop data might be hiding
    const rawSalesData = [
        ...(window.transactions || []),
        ...(window.payments || []),
        ...(window.pre_enrollment_receipts || []),
        ...(window.preEnrollments || []), 
        ...(window.student_ledger || []),
        ...(window.studentLedger || [])
    ];
    const salesByReceipt = new Map();
    const salesData = [];
    rawSalesData.forEach(sale => {
        const receipt = sale.receipt_no || sale.receiptNo;
        if (!receipt) {
            salesData.push(sale);
            return;
        }

        const receiptKey = String(receipt).toLowerCase();
        const existing = salesByReceipt.get(receiptKey);
        if (existing) {
            salesByReceipt.set(receiptKey, {
                ...sale,
                ...existing,
                cartdetails: existing.cartdetails || sale.cartdetails || sale.cart_details,
                description: existing.description || existing.notes || sale.description || sale.notes,
                qty: existing.qty || sale.qty,
                costprice: existing.costprice || sale.costprice
            });
        } else {
            salesByReceipt.set(receiptKey, sale);
        }
    });
    salesData.push(...salesByReceipt.values());
    
    if (currentInventory.length === 0) {
        list.innerHTML = '<tr><td colspan="5" style="text-align: center; padding: 15px; color: #7f8c8d;">No items in inventory.</td></tr>';
        return;
    }

    // 1. Get Date Filters. Force empty strings to become proper `null`
    let startDate = document.getElementById('shopStartDate')?.value || null;
    let endDate = document.getElementById('shopEndDate')?.value || null;
    const periodSelect = document.getElementById('shopReportPeriod')?.value;

    if (periodSelect === 'all') {
        startDate = null;
        endDate = null;
    }

    const isLevel3 = window.currentUser && window.currentUser.role === 'Level 3';

    let grandTotalSold = 0;
    let grandTotalRevenue = 0;
    let grandTotalCost = 0;

    currentInventory.forEach(item => {
        const price = parseFloat(item.price) || 0;
        const cost = parseFloat(item.costprice) || parseFloat(item.cost) || 0; 
        const realTimeQty = parseInt(item.qty) || 0; 
        const configuredThreshold = parseInt(item.low_stock_threshold, 10);
        const lowStockThreshold = Number.isFinite(configuredThreshold) ? configuredThreshold : 5;
        const isLowStock = realTimeQty <= lowStockThreshold;
        if (isLowStock) lowStockItems.push({ name: item.name, qty: realTimeQty });
        
        let soldDuringPeriod = 0;
        let soldAfterPeriod = 0;

        const currentItemId = String(item.id || '').trim();
        const itemNameLower = String(item.name || '').toLowerCase().trim();

        salesData.forEach(sale => {
            if (sale.status === 'VOID' || sale.status === 'VOIDED') return;
            if (sale.pre_student_id && !sale.cartdetails && !hasPreEnrollmentUniformCharge(sale)) return;
            
            // 🎯 FIX 2: Check for created_at if date is missing (fixes pre-enrollment data)
            const rawDate = sale.date || sale.created_at || sale.payment_date || '';
            const saleDate = String(rawDate).split('T')[0];
            
            // If there's still no valid date string, skip it to prevent math errors
            if (!saleDate || saleDate === 'undefined') return;

            let qtyInThisSale = 0;
            
            let searchDesc = String(sale.description || sale.notes || sale.desc || '').toLowerCase();
            
            // Prevent double counting if the ledger logged BOTH a charge and a payment
            if (sale.type === 'payment' && searchDesc.includes('shop payment')) return;

            // ========================================================
            // METHOD 1: Text search matching new ledger format
            // ========================================================
            if (searchDesc.includes(itemNameLower)) {
                let regex = new RegExp(`(\\d+)x\\s+${itemNameLower.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`, 'i');
                let match = searchDesc.match(regex);
                
                qtyInThisSale = match ? parseInt(match[1]) : (searchDesc.split(itemNameLower).length - 1);
                if (qtyInThisSale <= 0) qtyInThisSale = 1;
            } 
            // ========================================================
            // METHOD 2: Fallback for older data using cartdetails
            // ========================================================
            else if (sale.cartdetails) {
                let cart = [];
                if (typeof sale.cartdetails === 'string') {
                    try { cart = JSON.parse(sale.cartdetails); } catch(e){}
                } else if (Array.isArray(sale.cartdetails)) {
                    cart = sale.cartdetails;
                } else {
                    cart = [sale.cartdetails]; 
                }

                cart.forEach(cartItem => {
                    const cartItemNameLower = String(cartItem.name || '').toLowerCase().trim();
                    if (cartItem.id === item.id || cartItemNameLower.includes(itemNameLower) || itemNameLower.includes(cartItemNameLower)) {
                        qtyInThisSale += parseInt(cartItem.cartQty || cartItem.qty || 1);
                    }
                });
            }

            // ========================================================
            // ASSIGN TO TIMELINE IF FOUND
            // ========================================================
            if (qtyInThisSale > 0) {
                if (endDate && saleDate > endDate) {
                    soldAfterPeriod += qtyInThisSale;
                } 
                else if ((!startDate || saleDate >= startDate) && (!endDate || saleDate <= endDate)) {
                    soldDuringPeriod += qtyInThisSale;
                }
            }
        });

        // 🕰️ TIME MACHINE MATH
        const closingStock = realTimeQty + soldAfterPeriod;
        const openingStock = closingStock + soldDuringPeriod;

        grandTotalSold += soldDuringPeriod;
        grandTotalRevenue += (soldDuringPeriod * price);
        grandTotalCost += (soldDuringPeriod * cost);

        const qtyBg = closingStock > 5 ? '#e8f8f5' : '#fadbd8';
        const qtyColor = closingStock > 5 ? '#27ae60' : '#c0392b';

        let adminButtonsHTML = '';
        if (isLevel3) {
            adminButtonsHTML = `
                <button class="btn-standard btn-warning" style="padding: 6px 10px; font-size: 11px;" onclick="editShopItem('${item.id}')" title="Edit Item Details">
                    ✏️ Edit
                </button>
                <button class="btn-standard btn-danger admin-only" style="padding: 6px 10px; font-size: 11px; background: #c0392b; color: white;" onclick="deleteShopItem('${item.id}')" title="Delete Item">
                    🗑️ Del
                </button>
            `;
        }
        
        const row = `
            <tr style="border-bottom: 1px solid #ecf0f1;">
                <td style="padding: 12px 8px;">
                    <strong style="color: #2c3e50;">${item.name}</strong><br>
                    ${item.description ? `<small style="color: #7f8c8d;">${item.description}</small><br>` : ''}
                    <small style="color: #7f8c8d;">Cost: $${cost.toFixed(2)} | Price: $${price.toFixed(2)}</small><br>
                    ${isLowStock ? `<small style="color:#c0392b; font-weight:bold;">LOW STOCK: ${realTimeQty} left (alert at ${lowStockThreshold})</small>` : `<small style="color:#7f8c8d;">Alert at ${lowStockThreshold}</small>`}
                </td>
                
                <td style="padding: 12px 8px; text-align: center; font-weight: bold; color: #34495e; background: #f8f9fa;">
                    ${openingStock}
                </td>
                <td style="padding: 12px 8px; text-align: center; font-weight: bold; color: #e67e22; background: #fff8e8;">
                    ${soldDuringPeriod}
                </td>
                <td style="padding: 12px 8px; text-align: center;">
                    <span style="padding: 3px 8px; border-radius: 4px; background: ${qtyBg}; color: ${qtyColor}; font-weight: bold;">
                        ${closingStock}
                    </span>
                </td>

                <td style="padding: 12px 8px; text-align: right; display: flex; justify-content: flex-end; gap: 5px; align-items: center; flex-wrap: wrap;">
                    <button class="btn-standard btn-success" style="padding: 6px 10px; font-size: 11px;" onclick="addToCart('${item.id}')" ${realTimeQty <= 0 ? 'disabled' : ''} title="Add to Cart">
                        🛒 Add
                    </button>
                    <button class="btn-standard btn-dark" style="padding: 6px 10px; font-size: 11px;" onclick="window.viewItemHistory('${item.id}')" title="View Sales History & Stock Audit">
                        🔍 Inspect
                    </button>
                    ${adminButtonsHTML}
                </td>
            </tr>
        `;
        list.insertAdjacentHTML('beforeend', row);
    });

    if (lowStockAlert) {
        lowStockAlert.style.display = lowStockItems.length ? 'block' : 'none';
        lowStockAlert.innerHTML = lowStockItems.length
            ? `<div style="padding:9px 12px; border:1px solid #e74c3c; background:#fff5f4; color:#a93226; border-radius:4px; font-size:12px;"><strong>Low stock:</strong> ${lowStockItems.map(item => `${item.name} (${item.qty} left)`).join(', ')}</div>`
            : '';
    }

    // Update Analytics Panel Dashboard to match the true mathematical totals
    if (document.getElementById('shopGoodsSold')) document.getElementById('shopGoodsSold').innerText = grandTotalSold;
    if (document.getElementById('shopTotalRevenue')) document.getElementById('shopTotalRevenue').innerText = `$${grandTotalRevenue.toFixed(2)}`;
    if (document.getElementById('shopTotalCosts')) document.getElementById('shopTotalCosts').innerText = `$${grandTotalCost.toFixed(2)}`;
    if (document.getElementById('shopNetProfit')) document.getElementById('shopNetProfit').innerText = `$${(grandTotalRevenue - grandTotalCost).toFixed(2)}`;
    if (document.getElementById('shopGoodsProfit')) document.getElementById('shopGoodsProfit').innerText = `$${(grandTotalRevenue - grandTotalCost).toFixed(2)}`;
    
    // Total Stock Units / Value ignore filters (always show present total reality of the warehouse)
    if (document.getElementById('shopStockUnits')) {
        let totalStockLeft = currentInventory.reduce((sum, item) => sum + (parseInt(item.qty) || 0), 0);
        document.getElementById('shopStockUnits').innerText = totalStockLeft;
    }
    if (document.getElementById('shopStockValue')) {
         let totalVal = currentInventory.reduce((sum, item) => sum + ((parseInt(item.qty) || 0) * (parseFloat(item.costprice || item.cost) || 0)), 0);
         document.getElementById('shopStockValue').innerText = `$${totalVal.toFixed(2)}`;
    }

    if (typeof window.applyPermissions === 'function') window.applyPermissions();
};


// Helper function to keep things clean
resetShopForm
window.deleteInventory = async function(id) {
    // 3-Tier Check
    const role = window.currentUser?.role || "";
    if (!(role.includes('Level 2') || role.includes('Level 3') || role === 'Admin' || role === 'Chief Admin')) {
        return alert("❌ Access Denied: Only Admins can delete inventory items.");
    }

    if (!navigator.onLine) return alert("⚠️ You are offline. Please connect to the internet to delete inventory items.");
    if (!confirm("Are you sure you want to completely delete this inventory item?")) return;

    window.inventory = window.inventory.filter(i => i.id !== id);
    localStorage.setItem('haven_inventory', JSON.stringify(window.inventory)); 
    
    try {
        const { error } = await supabaseClient.from('inventory').delete().eq('id', id);
        if (error) throw error;
        console.log("✅ Item successfully vaporized from the cloud!");
    } catch (err) {
        console.error("Cloud Delete Error:", err.message);
        alert("⚠️ Deleted locally, but failed to delete from cloud.");
    }
    window.renderInventory();
};

window.deleteShopItem = window.deleteInventory;
window.deleteInventoryItem = window.deleteInventory;

window.addToCart = function(id) {
    const invList = window.getShopInventoryList();
    const item = invList.find(i => i.id === id);
    if(!item || item.qty <= 0) return alert("This item is currently out of stock!");

    const existing = window.shopCart.find(c => c.id === id);
    if(existing) {
        if(existing.cartQty >= item.qty) return alert("You cannot sell more than the available stock!");
        existing.cartQty++;
    } else {
        window.shopCart.push({ ...item, cartQty: 1 });
    }
    window.renderCart();
};

// 🎯 Professional POS-style type-ahead: type a few letters, see matching products with price/stock, click to add
window.filterShopProductSearch = function() {
    const input = document.getElementById('shopProductSearch');
    const resultsBox = document.getElementById('shopProductSearchResults');
    if (!input || !resultsBox) return;

    const query = input.value.trim().toLowerCase();
    if (!query) {
        resultsBox.style.display = 'none';
        resultsBox.innerHTML = '';
        return;
    }

    const items = window.getShopInventoryList();
    const matches = items.filter(i => (i.name || '').toLowerCase().includes(query)).slice(0, 10);

    if (matches.length === 0) {
        resultsBox.innerHTML = '<div style="padding:10px; font-size:12px; color:#7f8c8d;">No matching products found.</div>';
        resultsBox.style.display = 'block';
        return;
    }

    resultsBox.innerHTML = matches.map(item => {
        const qty = parseInt(item.qty) || 0;
        const outOfStock = qty <= 0;
        return `
            <div onclick="${outOfStock ? '' : `window.addToCartFromSearch('${item.id}')`}" style="padding:8px 10px; border-bottom:1px solid #ecf0f1; cursor:${outOfStock ? 'not-allowed' : 'pointer'}; display:flex; justify-content:space-between; align-items:center; ${outOfStock ? 'opacity:0.5;' : ''}" onmouseover="this.style.background='#f4f6f7'" onmouseout="this.style.background='white'">
                <span><strong>${item.name}</strong></span>
                <span style="font-size:11px; text-align:right;">
                    <span style="color:#2980b9; font-weight:bold;">$${(parseFloat(item.price) || 0).toFixed(2)}</span>
                    &nbsp;|&nbsp;
                    <span style="color:${qty > 5 ? '#27ae60' : '#c0392b'};">${outOfStock ? 'Out of stock' : qty + ' in stock'}</span>
                </span>
            </div>
        `;
    }).join('');
    resultsBox.style.display = 'block';
};

// 🎯 Add-to-cart from the type-ahead search result, then reset the search box for the next item
window.addToCartFromSearch = function(id) {
    window.addToCart(id);
    const input = document.getElementById('shopProductSearch');
    const resultsBox = document.getElementById('shopProductSearchResults');
    if (input) { input.value = ''; input.focus(); }
    if (resultsBox) { resultsBox.style.display = 'none'; resultsBox.innerHTML = ''; }
};

// Close the search results dropdown when clicking elsewhere on the page
document.addEventListener('click', function(e) {
    const input = document.getElementById('shopProductSearch');
    const resultsBox = document.getElementById('shopProductSearchResults');
    if (!input || !resultsBox) return;
    if (e.target !== input && !resultsBox.contains(e.target)) {
        resultsBox.style.display = 'none';
    }
});

window.removeFromCart = function(id) {
    window.shopCart = window.shopCart.filter(c => c.id !== id);
    window.renderCart();
};

window.renderCart = function() {
    const tbody = document.getElementById('shopCartList');
    const emptyMsg = document.getElementById('shopCartEmpty');
    const totalSpan = document.getElementById('shopCartTotal');
    if(!tbody) return;

    tbody.innerHTML = '';
    let total = 0;

    if(window.shopCart.length === 0) {
        emptyMsg.style.display = 'block'; totalSpan.innerText = '$0.00';
        document.getElementById('shopPayUsd').value = ''; return;
    }

    emptyMsg.style.display = 'none';
    window.shopCart.forEach(cartItem => {
        const lineTotal = parseFloat(cartItem.price) * parseInt(cartItem.cartQty);
        total += lineTotal;
        tbody.innerHTML += `
            <tr style="border-bottom: 1px dashed #bdc3c7;">
                <td style="padding: 10px 0; font-weight:bold; color:#2c3e50;">${cartItem.name}</td>
                <td style="padding: 10px 0; text-align:center;">${cartItem.cartQty}</td>
                <td style="padding: 10px 0; text-align:right;">$${lineTotal.toFixed(2)}</td>
                <td style="padding: 10px 0; text-align:right;">
                    <button class="btn-standard btn-danger" onclick="removeFromCart('${cartItem.id}')" style="padding: 4px 8px; font-size:10px; margin:0;">❌</button>
                </td>
            </tr>
        `;
    });
    
    totalSpan.innerText = '$' + total.toFixed(2);
    document.getElementById('shopPayUsd').value = total.toFixed(2); 
};
// ==========================================
// 24. ULTIMATE SHOP SALE & PROFIT ENGINE (FINAL)
// ==========================================
// -----------------------------------------
// 1. UPDATED PROCESS SALE (Walk-in & Discount Popups)
// -----------------------------------------
window.processShopSale = async function() {
    const cart = window.shopCart || [];
    if (cart.length === 0) return alert("🛒 Your cart is empty!");

    let studentId = document.getElementById('shopStudentId').value.trim();
    if (studentId.includes('STU-')) {
        let match = studentId.match(/(STU-\d+)/);
        if (match) studentId = match[1];
    }
           
    const isWalkIn = (studentId === ""); 
    let student = null;
    let creditAvailable = 0;
    let creditApplied = 0;

    const usdField = document.getElementById('shopPayUsd');
    const zigField = document.getElementById('shopPayZig');
    const ecoRefField = document.getElementById('shopEcoRef'); 
    const discountField = document.getElementById('shopDiscount');
    const rateField = document.getElementById('zigRate');
    const waiverModeField = document.getElementById('shopWaiverMode');

    let paidUsd = parseFloat(usdField.value) || 0; 
    let paidZig = parseFloat(zigField.value) || 0;
    let ecoRef = ecoRefField ? ecoRefField.value.trim().toUpperCase() : "";
    const discount = parseFloat(discountField?.value) || 0;
    const isWaiver = !!(waiverModeField && waiverModeField.checked && discount > 0);
    const enteredZigRate = parseFloat(rateField?.value);
    const zigRate = Number.isFinite(enteredZigRate) && enteredZigRate > 0 ? enteredZigRate : 13.56;
    
    const cashierName = window.currentUser?.user || window.currentUser?.username || window.currentUser?.name;
    if (!cashierName) return alert("Please log in again before processing a shop sale.");
    if (!navigator.onLine || !window.supabaseClient) {
        return alert("⚠️ Connect to the cloud before processing a uniform sale so stock quantities can be verified.");
    }
    if (!Number.isFinite(paidUsd) || !Number.isFinite(paidZig) || paidUsd < 0 || paidZig < 0) {
        return alert("Enter valid non-negative payment amounts.");
    }

    if (ecoRef) {
        if (!window.ecoCashTransactions) window.ecoCashTransactions = [];
        if(window.ecoCashTransactions.some(t => t.ref.toUpperCase() === ecoRef)) {
            return alert("❌ This EcoCash Reference Number already exists in the Database.");
        }
    }

    let totalDue = 0;
    let totalCost = 0;
    let purchasedItemsText = cart.map(c => `${parseInt(c.cartQty) || 1}x ${c.name}`).join(', ');
    const requestedQuantities = new Map();
    cart.forEach(item => {
        const itemId = String(item.id);
        requestedQuantities.set(itemId, (requestedQuantities.get(itemId) || 0) + (parseInt(item.cartQty, 10) || 1));
    });

    const { data: inventoryRows, error: inventoryFetchError } = await window.supabaseClient
        .from('inventory')
        .select('*')
        .in('id', Array.from(requestedQuantities.keys()));
    if (inventoryFetchError) return alert(`⚠️ Could not verify current stock: ${inventoryFetchError.message}`);
    const inventoryById = new Map((inventoryRows || []).map(item => [String(item.id), item]));

    // Use a standard for...of loop so 'return' actually aborts the transaction
    for (const item of cart) {
        const countToBuy = parseInt(item.cartQty) || 1; 
        totalDue += (parseFloat(item.price) * countToBuy);

        const invItem = inventoryById.get(String(item.id));
        const itemCost = invItem && invItem.costprice ? parseFloat(invItem.costprice) : 0;
        totalCost += (itemCost * countToBuy);

        if (!invItem) {
            return alert(`❌ Inventory item ${item.name} was not found in the cloud. Refresh inventory and try again.`);
        }
    }

    for (const [itemId, quantityToBuy] of requestedQuantities) {
        const invItem = inventoryById.get(itemId);
        const availableQty = invItem ? (parseInt(invItem.qty, 10) || 0) : 0;
        if (!invItem || availableQty < quantityToBuy) {
            return alert(`❌ Insufficient stock for ${invItem?.name || itemId}. (Available: ${availableQty}, Trying to buy: ${quantityToBuy})\n\nRefresh inventory and try again.`);
        }
    }

    const inventoryUpdates = Array.from(requestedQuantities, ([itemId, quantity]) => {
        const item = inventoryById.get(itemId);
        return { ...item, qty: (parseInt(item.qty, 10) || 0) - quantity };
    });

    const finalDueAfterDiscount = totalDue - discount;
    if (discount < 0 || discount > totalDue) return alert("Discount must be between $0.00 and the cart total.");
    const zigEquivalentInUsd = paidZig / zigRate;
    
    const actualCashReceived = parseFloat((paidUsd + zigEquivalentInUsd).toFixed(2));
    let totalProvidedUsd = actualCashReceived; 

    if (!isWalkIn) {
        student = (window.students || []).find(s => String(s.id) === String(studentId));
        if (!student) return alert("Student ID was not found. Leave the field blank to process this as a walk-in sale.");
        if (student && student.ledger) {
            let billed = 0, paid = 0;
            student.ledger.forEach(l => {
                if (l.status === 'VOID' || l.status === 'VOIDED') return;
                
                if (l.type === 'charge' || l.type === 'fee') { 
                    billed += (parseFloat(l.amount) || 0);
                } else if (['payment', 'discount', 'waiver', 'credit', 'overpayment'].includes(l.type)) {
                    paid += (parseFloat(l.amount) || 0);
                }
            });
            
            let balance = billed - paid;
            if (balance < -0.01) {
                creditAvailable = Math.abs(balance);
            }
        }
    }

    if (isWalkIn && Math.round(totalProvidedUsd * 100) !== Math.round(finalDueAfterDiscount * 100)) {
        return alert(`Walk-in sales must be paid in full with no student credit or change.\n\nAmount due: $${finalDueAfterDiscount.toFixed(2)}\nAmount paid: $${totalProvidedUsd.toFixed(2)}`);
    }

    let confirmationMessage = isWalkIn ? "⚠️ NOTICE: This is a WALK-IN sale (No student linked).\n\n" : "";

    if (creditAvailable > 0 && totalProvidedUsd < finalDueAfterDiscount) {
        let amountNeeded = finalDueAfterDiscount - totalProvidedUsd;
        const useCredit = confirm(`💰 ADVANCE CREDIT FOUND!\n\n${student.name} has a pre-paid credit balance of $${creditAvailable.toFixed(2)}.\n\nThe cart still needs $${amountNeeded.toFixed(2)}. Do you want to use their credit to pay for this?`);

        if (useCredit) {
            creditApplied = Math.min(creditAvailable, amountNeeded);
            totalProvidedUsd += creditApplied; 
            confirmationMessage += `🛡️ CREDIT APPLIED: $${creditApplied.toFixed(2)} deducted from their overpayment balance.\n\n`;
        }
    }

    if (!isWalkIn && totalProvidedUsd < finalDueAfterDiscount) {
        let debtAmount = finalDueAfterDiscount - totalProvidedUsd;
        confirmationMessage += `📝 CREDIT SALE (STUDENT DEBT):\n   - Paying Now: $${(totalProvidedUsd - creditApplied).toFixed(2)}\n   - Applied Credit: $${creditApplied.toFixed(2)}\n   - The remaining $${debtAmount.toFixed(2)} will be added to their main school fee account as debt.\n\n`;
    }

    if (discount > 0) {
        confirmationMessage += isWaiver
            ? `🎁 WAIVER CALCULATION:\n   - Original Cart: $${totalDue.toFixed(2)}\n   - Waived: -$${discount.toFixed(2)}\n   - Final Due: $${finalDueAfterDiscount.toFixed(2)}\n\n`
            : `💰 DISCOUNT CALCULATION:\n   - Original Cart: $${totalDue.toFixed(2)}\n   - Discount: -$${discount.toFixed(2)}\n   - Final Due: $${finalDueAfterDiscount.toFixed(2)}\n\n`;
    }

    let change = 0;
    if (totalProvidedUsd > finalDueAfterDiscount) {
        change = totalProvidedUsd - finalDueAfterDiscount;
        if (isWalkIn) {
            confirmationMessage += `💵 OVERPAYMENT (WALK-IN):\n   - Hand back change: $${change.toFixed(2)}\n\n`;
        } else {
            confirmationMessage += `💵 OVERPAYMENT (STUDENT):\n   - $${change.toFixed(2)} will be left as credit on the student's account.\n\n`;
        }
    }

    confirmationMessage += "Do you want to proceed and finalize this sale?";
    const proceed = window.confirm(confirmationMessage);
    if (!proceed) return;

    const receiptNum = 'RCPT-' + Math.floor(100000 + Math.random() * 900000);
    const saleDate = new Date().toISOString().split('T')[0];

    let paymentMethodString = "Credit";
    let paymentMethodDetails = ""; 
    
    if (creditApplied > 0 && paidUsd === 0 && paidZig === 0) {
        paymentMethodString = "Overpayment/Account Credit";
        paymentMethodDetails = `Paid fully using student overpayment balance of $${creditApplied.toFixed(2)}`;
    } else if (ecoRef) {
        paymentMethodString = `EcoCash (${ecoRef})`;
        if (creditApplied > 0) paymentMethodDetails = `$${creditApplied.toFixed(2)} from overpayment + $${paidUsd.toFixed(2)} EcoCash`;
    } else if (paidUsd > 0 && paidZig > 0) {
        paymentMethodString = 'Split Payment (USD + ZiG)';
        if (creditApplied > 0) paymentMethodDetails = `$${creditApplied.toFixed(2)} overpayment + $${paidUsd.toFixed(2)} USD + $${paidZig.toFixed(2)} ZiG`;
    } else if (paidUsd > 0) {
        paymentMethodString = 'Cash USD';
        if (creditApplied > 0) paymentMethodDetails = `$${creditApplied.toFixed(2)} overpayment + $${paidUsd.toFixed(2)} cash`;
    } else if (paidZig > 0) {
        paymentMethodString = 'ZiG Cash';
        if (creditApplied > 0) paymentMethodDetails = `$${creditApplied.toFixed(2)} overpayment + $${paidZig.toFixed(2)} ZiG`;
    }

    const saleRecord = {
        id: "SALE-" + Date.now().toString(),
        student_id: studentId || "WALK-IN",  
        type: "Shop Sale",                   
        date: saleDate,
        category: 'Shop',
        description: `Sale to ${studentId || "Walk-in"}: ${purchasedItemsText}`, 
        item: purchasedItemsText,
        qty: cart.reduce((sum, i) => sum + (parseInt(i.cartQty || 1)), 0),
        amount: parseFloat(finalDueAfterDiscount.toFixed(2)),
        total: parseFloat(actualCashReceived.toFixed(2)), 
        costprice: parseFloat(totalCost.toFixed(2)),
        usdpaid: paidUsd,
        zigpaid: paidZig,
        receipt_no: receiptNum,              
        student_name: student?.name || studentId || "Walk-in", 
        paymentmethod: paymentMethodString,  
        payment_details: paymentMethodDetails || paymentMethodString, 
        status: 'ACTIVE',
        reconciled: false,
        cartdetails: JSON.parse(JSON.stringify(cart)), // ✅ FIXED: Deep copy prevents array corruption
        discount: discount,
        is_credit_backed: creditApplied > 0,
        credit_applied_amount: creditApplied, 
        processed_by: cashierName
    };

    let ledgerEntries = [];
    let cloudPaymentRecord = null; 
    
    const exactChargeDesc = `Shop Purchase: ${purchasedItemsText}`;

    if (studentId) {
        ledgerEntries.push({
            id: "CHG-" + receiptNum,
            student_id: studentId,
            date: saleDate,
            type: "charge",
            description: exactChargeDesc, 
            term: 'Once-Off',
            amount: parseFloat(totalDue.toFixed(2)),
            status: 'ACTIVE',
            processed_by: cashierName
        });

        if (discount > 0) {
            ledgerEntries.push({
                id: "DISC-" + receiptNum,
                student_id: studentId,
                date: saleDate,
                type: isWaiver ? "waiver" : "discount",
                description: isWaiver ? `Shop Waiver: ${purchasedItemsText}` : `Shop Discount: ${purchasedItemsText}`,
                amount: parseFloat(discount.toFixed(2)),
                method: isWaiver ? "System Exemption (Shop)" : "System Discount (Shop)",
                status: 'ACTIVE',
                processed_by: cashierName
            });
        }

        if (actualCashReceived > 0 || creditApplied > 0) {
            let breakdownItems = [{"desc": exactChargeDesc, "amt": actualCashReceived, "cleanDesc": exactChargeDesc}];
            
            ledgerEntries.push({
                id: "PAY-" + receiptNum,
                student_id: studentId,
                date: saleDate,
                type: "payment",
                description: `Shop Payment: ${purchasedItemsText}`,
                amount: parseFloat(actualCashReceived.toFixed(2)),
                zig: parseFloat(paidZig.toFixed(2)),
                method: paymentMethodString + " (Shop)", 
                receipt_no: receiptNum,
                status: 'ACTIVE',
                breakdown: breakdownItems,
                payment_notes: paymentMethodDetails || paymentMethodString, 
                credit_used: creditApplied, 
                processed_by: cashierName
            });
        }
    }

    if (actualCashReceived > 0 || creditApplied > 0) {
        cloudPaymentRecord = {
            id: Math.floor(Date.now() / 1000), 
            student_id: studentId || "WALK-IN",
            date: saleDate,
            amount: parseFloat(actualCashReceived.toFixed(2)), 
            zig: parseFloat(paidZig.toFixed(2)), 
            method: paymentMethodString, 
            receipt_no: receiptNum,
            notes: exactChargeDesc, 
            category: 'Shop',
            status: 'PAID',
            processed_by: cashierName
        };
    }

    let transactionSaved = false;
    let ledgerSaved = false;
    let paymentSaved = false;
    let referenceClaimed = false;
    const inventoryUpdatesApplied = [];
    
    try {
        if (!navigator.onLine || !window.supabaseClient) {
            throw new Error("You are offline or the cloud client is unavailable. No sale was recorded.");
        }

        if (ecoRef) {
            referenceClaimed = await window.claimPaymentReference(ecoRef, studentId, 'shop-sale');
            if (!referenceClaimed) {
                throw new Error(`Payment reference ${ecoRef} is already claimed. No sale was recorded.`);
            }
        }

        for (const updatedItem of inventoryUpdates) {
            const previousQty = parseInt(inventoryById.get(String(updatedItem.id)).qty, 10) || 0;
            const { data: changedRows, error: stockError } = await window.supabaseClient
                .from('inventory')
                .update({ qty: updatedItem.qty })
                .eq('id', updatedItem.id)
                .eq('qty', previousQty)
                .select('id');
            if (stockError) throw new Error(`Could not update remaining stock for ${updatedItem.name}: ${stockError.message}`);
            if (!changedRows || changedRows.length === 0) {
                throw new Error(`Stock for ${updatedItem.name} changed during checkout. Refresh inventory and try again.`);
            }
            inventoryUpdatesApplied.push({ id: updatedItem.id, previousQty, updatedQty: updatedItem.qty });
        }

        try {
            const { error: txError } = await window.supabaseClient.from('transactions').insert([saleRecord]);
            if (txError) throw txError;
            transactionSaved = true;
        } catch (e) {
            throw new Error(`Sale record save failed: ${e.message}`);
        }

        if (studentId) {
            const { error: ledgerError } = await window.supabaseClient.from('student_ledger').insert(ledgerEntries);
            if (ledgerError) throw new Error('Ledger save failed: ' + ledgerError.message);
            ledgerSaved = true;
        }

        if (cloudPaymentRecord) {
            const { error: paymentError } = await window.supabaseClient.from('payments').insert([cloudPaymentRecord]);
            if (paymentError) throw new Error('Payment save failed: ' + paymentError.message);
            paymentSaved = true;
        }

        if (!window.transactions) window.transactions = [];
        window.transactions.push(saleRecord);
        localStorage.setItem('havenTransactions', JSON.stringify(window.transactions));

        const updateInventoryCache = inventory => {
            if (!Array.isArray(inventory)) return;
            inventoryUpdates.forEach(updatedItem => {
                const cachedItem = inventory.find(item => String(item.id) === String(updatedItem.id));
                if (cachedItem) Object.assign(cachedItem, updatedItem);
            });
        };
        updateInventoryCache(window.inventory);
        updateInventoryCache(window.shopInventory);
        if (Array.isArray(window.inventory)) {
            localStorage.setItem('haven_inventory', JSON.stringify(window.inventory));
            localStorage.setItem('havenInventory', JSON.stringify(window.inventory));
        }
        if (Array.isArray(window.shopInventory)) localStorage.setItem('havenShopInventory', JSON.stringify(window.shopInventory));

        if (ecoRef && actualCashReceived > 0) {
            window.ecoCashTransactions.push({
                date: saleDate,
                ref: ecoRef,
                studentId,
                amount: paidUsd,
                zigAmount: paidZig,
                status: 'claimed',
                claimedBy: cashierName,
                source: 'shop-sale'
            });
            if (typeof window.saveEcoCashTransactions === 'function') window.saveEcoCashTransactions();
        }

        if (student) {
            if (!student.ledger) student.ledger = [];
            student.ledger.push(...ledgerEntries);
            if (typeof window.calculateStudentBalance === 'function') {
                student.balanceOwing = window.calculateStudentBalance(student);
                student.balance_owing = student.balanceOwing;
            }
        }

        usdField.value = '';
        zigField.value = '';
        if(ecoRefField) ecoRefField.value = '';
        if(discountField) discountField.value = '';
        if (document.getElementById('shopWaiverMode')) document.getElementById('shopWaiverMode').checked = false;
        document.getElementById('shopStudentId').value = '';
        window.shopCart = [];
        if (typeof window.renderCart === 'function') window.renderCart(); 
        if (typeof window.renderInventory === 'function') window.renderInventory();

        let missedWhatsapp = false;
        if (!isWalkIn && student) {
            const phone = (student.phone || student.cell || "").toString();
            
            if (phone.trim() !== "") {
                const wantsWhatsapp = confirm(`Do you want to send a WhatsApp receipt to ${student.name} at ${phone}?`);
                
                if (wantsWhatsapp) {
                    let cleanPhone = phone.replace(/[^0-9+]/g, '');
                    if (cleanPhone.startsWith('0')) cleanPhone = '263' + cleanPhone.substring(1); 
                    
                    const waText = `*${window.settings?.schoolName || 'HAVEN ONLINE'} - Shop Receipt*\n\n*Receipt No:* ${receiptNum}\n*Date:* ${saleDate}\n*Student:* ${student.name}\n*Student ID:* ${student.id}\n------------------------\n*Items Purchased:*\n${purchasedItemsText}\n------------------------\n*Total Due:* $${finalDueAfterDiscount.toFixed(2)}\n${creditApplied > 0 ? `💳 *Credit Applied:* $${creditApplied.toFixed(2)}\n` : ''}*Cash/Digital Paid:* $${actualCashReceived.toFixed(2)}\n*Payment Method:* ${paymentMethodString}\n${paymentMethodDetails ? `*Payment Details:* ${paymentMethodDetails}` : ''}\n------------------------\n*Served By:* ${cashierName}\nThank you!`;
                    
                    const waLink = `https://wa.me/${cleanPhone}?text=${encodeURIComponent(waText)}`;
                    window.open(waLink, '_blank');
                }
            } else {
                missedWhatsapp = true;
            }
        }

        try {
            if (typeof window.printShopReceipt === 'function') window.printShopReceipt(saleRecord);
        } catch (printError) {
            console.warn("Receipt generation failed (likely popup blocker):", printError);
        }

        const remainingStockText = inventoryUpdates.map(item => `${item.name}: ${item.qty} left`).join('\n');
        setTimeout(() => {
            if (missedWhatsapp && !isWalkIn) {
                alert(`✅ Sale Logged Successfully!\nReceipt: ${receiptNum}\n\nRemaining stock:\n${remainingStockText}\n\n⚠️ Could not send WhatsApp: No phone number saved for ${student.name}.`);
            } else {
                alert(`✅ Sale Logged Successfully!\nReceipt: ${receiptNum}\n\nRemaining stock:\n${remainingStockText}`);
            }
        }, 500);

    } catch (error) {
        console.error("Shop Sale Error:", error);
        const rollbackIssues = [];
        try {
            const rollbacks = [];
            for (const stockChange of inventoryUpdatesApplied) {
                rollbacks.push(window.supabaseClient.from('inventory')
                    .update({ qty: stockChange.previousQty })
                    .eq('id', stockChange.id)
                    .eq('qty', stockChange.updatedQty)
                    .select('id'));
            }
            if (paymentSaved) rollbacks.push(window.supabaseClient.from('payments').delete().eq('receipt_no', receiptNum));
            if (ledgerSaved) rollbacks.push(window.supabaseClient.from('student_ledger').delete().in('id', ledgerEntries.map(entry => entry.id)));
            if (transactionSaved) rollbacks.push(window.supabaseClient.from('transactions').delete().eq('id', saleRecord.id));
            const rollbackResults = await Promise.all(rollbacks);
            rollbackResults.forEach((result, index) => {
                if (result.error) rollbackIssues.push(result.error.message);
                else if (index < inventoryUpdatesApplied.length && (!result.data || result.data.length === 0)) {
                    rollbackIssues.push(`Inventory item ${inventoryUpdatesApplied[index].id} changed before rollback and needs review.`);
                }
            });
        } catch (rollbackError) {
            console.error("Shop sale rollback failed:", rollbackError);
            rollbackIssues.push(rollbackError.message);
        }
        if (referenceClaimed) rollbackIssues.push(`Payment reference ${ecoRef} remains claimed. Verify the cloud records before releasing or retrying it.`);
        if (transactionSaved && Array.isArray(window.transactions)) {
            window.transactions = window.transactions.filter(transaction => String(transaction.id) !== String(saleRecord.id));
            try { localStorage.setItem('havenTransactions', JSON.stringify(window.transactions)); }
            catch (storageError) { rollbackIssues.push(`Local transaction cache could not be restored: ${storageError.message}`); }
        }
        if (student && ledgerSaved && Array.isArray(student.ledger)) {
            const ledgerEntryIds = new Set(ledgerEntries.map(entry => String(entry.id)));
            student.ledger = student.ledger.filter(entry => !ledgerEntryIds.has(String(entry.id)));
            if (typeof window.calculateStudentBalance === 'function') {
                student.balanceOwing = window.calculateStudentBalance(student);
                student.balance_owing = student.balanceOwing;
            }
        }
        if (inventoryUpdatesApplied.length > 0) {
            const restoreInventoryCache = inventory => {
                if (!Array.isArray(inventory)) return;
                inventoryUpdatesApplied.forEach(change => {
                    const original = inventoryById.get(String(change.id));
                    const cached = inventory.find(item => String(item.id) === String(change.id));
                    if (original && cached) Object.assign(cached, original);
                });
            };
            restoreInventoryCache(window.inventory);
            restoreInventoryCache(window.shopInventory);
            try {
                if (Array.isArray(window.inventory)) {
                    localStorage.setItem('haven_inventory', JSON.stringify(window.inventory));
                    localStorage.setItem('havenInventory', JSON.stringify(window.inventory));
                }
                if (Array.isArray(window.shopInventory)) localStorage.setItem('havenShopInventory', JSON.stringify(window.shopInventory));
            } catch (storageError) {
                rollbackIssues.push(`Local inventory cache could not be restored: ${storageError.message}`);
            }
        }
        if (rollbackIssues.length > 0) error.message += ` Rollback needs review: ${rollbackIssues.join('; ')}`;
        alert("⚠️ Shop sale was not completed. Error: " + error.message);
    }
};

window.autoFillShopPayment = function() {
    const cart = window.shopCart || [];
    let totalDue = 0;
    
    // 1. Calculate the raw cart total
    cart.forEach(item => {
        const countToBuy = parseInt(item.cartQty) || 1; 
        totalDue += (parseFloat(item.price) * countToBuy);
    });

    // 2. Grab the discount entered
    const discountInput = document.getElementById('shopDiscount');
    let discount = parseFloat(discountInput.value) || 0;

    // Safety: Prevent the discount from being larger than the actual cart total
    if (discount > totalDue) {
        discount = totalDue;
        discountInput.value = discount; 
    }

    // 3. Auto-adjust the USD payment box to exactly match the new total
    const usdInput = document.getElementById('shopPayUsd');
    if (usdInput) {
        let newTotal = totalDue - discount;
        // Only update if it's greater than 0, otherwise set to empty or 0
        usdInput.value = newTotal > 0 ? newTotal.toFixed(2) : '';
    }
};
