    // 2. Safely clear values IF they exist in the HTML
    if (idEl) idEl.value = '';
    
    if (nameEl) {
        nameEl.value = '';
        delete nameEl.dataset.editingId; // CRITICAL: This takes the form out of "Edit Mode"
    }
    
    if (priceEl) priceEl.value = '';
    if (costEl) costEl.value = '';
    if (qtyEl) qtyEl.value = '';
