// Update your addShopItem logic to check if we are updating an item
const originalAddShopItem = window.addShopItem; 
window.addShopItem = async function() {
    // 🛡️ Only Level 3 may create/edit stock items — Level 2 can sell but not adjust inventory
    const role = window.currentUser?.role || "";
    if (!(role.includes('Level 3') || role === 'Chief Admin')) {
        return alert("⛔ Access Denied: Only Level 3 users can add or edit shop stock.");
    }

    // 1. Safely grab HTML Elements
    const nameEl = document.getElementById('shopItemName');
    const priceEl = document.getElementById('shopItemPrice');
    const costEl = document.getElementById('shopItemCost');
    const qtyEl = document.getElementById('shopItemQty');
    const descriptionEl = document.getElementById('shopItemDescription');
    const lowStockEl = document.getElementById('shopItemLowStock');

    if (!nameEl || !nameEl.value.trim()) return alert("⚠️ Please enter an item name.");

    // 2. Extract Values
    const name = nameEl.value.trim();
    const price = parseFloat(priceEl?.value) || 0;
    const costPrice = parseFloat(costEl?.value) || 0;
    const qty = parseInt(qtyEl?.value) || 0;
    const description = descriptionEl?.value.trim() || '';
    const configuredLowStock = parseInt(lowStockEl?.value, 10);
    const lowStockThreshold = Number.isFinite(configuredLowStock) ? Math.max(0, configuredLowStock) : 5;
    
    const editId = nameEl.dataset.editingId;
    const invList = window.getShopInventoryList();
    const client = window.supabaseClient || window.supabase; // Safely grab Supabase client
    
    // ==========================================
    // SCENARIO A: WE ARE EDITING AN EXISTING ITEM
    // ==========================================
    if (editId) {
        const item = invList.find(i => String(i.id) === String(editId));
        if (!item) return alert("Item not found. Refresh inventory and try again.");

        const updatedItem = {
            ...item,
            name,
            description,
            price,
            costprice: costPrice,
            qty,
            low_stock_threshold: lowStockThreshold
        };

        try {
            if (client && navigator.onLine) {
                const { error } = await client.from('inventory').upsert([updatedItem], { onConflict: 'id' });
                if (error) throw error;
            }
            Object.assign(item, updatedItem);
            window.inventory = invList;
            window.shopInventory = invList;
            localStorage.setItem('haven_inventory', JSON.stringify(invList));
            localStorage.setItem('havenShopInventory', JSON.stringify(invList));
            if (typeof window.renderInventory === 'function') window.renderInventory();
            alert(client && navigator.onLine ? "✅ Item updated successfully!" : "✅ Item updated locally. Sync when online.");
            if (typeof resetShopForm === 'function') resetShopForm();
            return;
        } catch (error) {
            console.error("Edit Item Error:", error);
            return alert("⚠️ Failed to update item: " + error.message);
        }
    }
    
    // ==========================================
    // SCENARIO B: WE ARE ADDING A NEW ITEM
    // ==========================================
    const newItem = {
        id: "INV-" + Date.now().toString(),
        name: name,
        description: description,
        price: price,
        costprice: costPrice,
        qty: qty,
        low_stock_threshold: lowStockThreshold
        // 🎯 FIX: 'category: Shop' has been completely removed to match your database schema
    };

    try {
        // A. Push to Supabase
        if (client) {
            const { error } = await client.from('inventory').insert([newItem]);
            if (error) throw error;
        }
        
        // B. Update local memory
        invList.push(newItem);
        window.inventory = invList;
        window.shopInventory = invList;
        localStorage.setItem('haven_inventory', JSON.stringify(invList));
        
        // C. AUTOMATIC EXPENSE DEDUCTION (For new stock only)
        const totalStockCost = costPrice * qty;
        if (totalStockCost > 0) {
            const invExpense = {
                id: 'EXP-INV-' + Date.now(),
                date: new Date().toISOString().split('T')[0],
                description: `Stock Purchase: ${qty}x ${name}`, 
                amount: totalStockCost,
                payment_method: 'Cash'
            };
            
            if (!window.expenses) window.expenses = [];
            window.expenses.push(invExpense);
            
            if (typeof window.saveExpenses === 'function') window.saveExpenses();
            if (typeof window.calculateReconciliation === 'function') window.calculateReconciliation();
        }

        // D. Update UI
        if (typeof window.renderInventory === 'function') window.renderInventory();
        alert("✅ Item Added Successfully!");
        if (typeof resetShopForm === 'function') resetShopForm(); 
        
    } catch (error) {
        console.error("Add Item Error:", error);
        
        // Offline Fallback Handling
        if (!navigator.onLine) {
            if (typeof window.renderInventory === 'function') window.renderInventory();
            if (typeof resetShopForm === 'function') resetShopForm();
            alert("⚠️ Saved locally. The item will sync to the cloud when connection is restored.");
        } else {
            alert("⚠️ Failed to add item: " + error.message);
        }
    }
};

