window.createNewUser = async function() { 
    // Developer God Mode and Chief Admin accounts can create staff accounts.
    const normalizedRole = window.getNormalizedRole(window.currentUser?.role);
    if (!(normalizedRole === 'Level 3' || normalizedRole === 'God Mode')) {
        return alert("❌ Access Denied: Only Chief Admins and God Mode can create staff accounts.");
    }

    const nameInput = document.getElementById('newUserName').value.trim();
    const passInput = document.getElementById('newUserPass').value.trim();
    const roleInput = document.getElementById('newUserRole').value;
    const emailInput = document.getElementById('newUserEmail')?.value.trim().toLowerCase() || '';

    if (!nameInput || !passInput) return alert("Please enter both a name and a password.");
    if (roleInput === 'Level 3' && !emailInput) {
        return alert("A verified email address is required for a Level 3 Chief Admin account.");
    }
    if (emailInput && !emailInput.includes('@')) {
        return alert("Please enter a valid email address.");
    }

    const userExists = window.users.some(u => {
        const existingName = u.name || u.user || u.username || ""; 
        return existingName.toLowerCase() === nameInput.toLowerCase();
    });

    if (userExists) return alert("A user with this name already exists!");

    // Generate the unique ID
    const newId = 'USR-' + Date.now();

    // 1. Local User Object (Keeping legacy keys like 'user' and 'pass' for your frontend)
    const newUser = {
        id: newId,
        name: nameInput,
        user: nameInput,     
        username: nameInput, 
        pass: passInput,     
        password: passInput,
        role: roleInput,
        email: emailInput
    };

    window.users.push(newUser);
    
    if (!navigator.onLine) {
        document.getElementById('newUserName').value = '';
        document.getElementById('newUserPass').value = '';
        if (document.getElementById('newUserEmail')) document.getElementById('newUserEmail').value = '';
        window.renderStaffList();
        return alert("⚠️ Saved locally, but you are offline. The user account will sync to the cloud later.");
    }

    try {
        // 2. Database Payload (Mapped EXACTLY to your SQL Schema columns)
        const dbPayload = {
            id: newId,
            name: nameInput,
            username: nameInput,
            password_hash: passInput, // Matches your schema
            role: roleInput,
            data: newUser // Saves the full legacy object in your JSONB column
        };

        const { error } = await supabaseClient.from('users').upsert([dbPayload]);
            
        if (error) throw error;

        document.getElementById('newUserName').value = '';
        document.getElementById('newUserPass').value = '';
        if (document.getElementById('newUserEmail')) document.getElementById('newUserEmail').value = '';
        
        alert("✅ Staff account created & saved to the cloud!");
        window.renderStaffList();

    } catch (err) {
        console.error("Error saving staff:", err);
        alert("⚠️ Failed to save to cloud. Check connection.");
    }
};
