window.renderStaffList = function() {
    const list = document.getElementById('staffList'); 
    if(!list) return;
    list.innerHTML = ''; 

    const staffData = (window.staff && window.staff.length > 0) ? window.staff : (window.users || []);

    if(staffData.length === 0) {
        list.innerHTML = '<div style="padding:20px; text-align:center; color:#7f8c8d; border:1px dashed #bdc3c7; border-radius:4px;">No staff members found.</div>';
        return;
    }

    staffData.forEach((s) => {
        // 1. Skip completely null/empty records
        if (!s) return; 

        // 2. Safely grab variables (Fallback to "Unknown")
        const staffName = s.name || s.user || s.username || "Unknown Staff Member";
        const staffRole = s.role || "Staff";
        
        // 3. THE MAGIC FIX: Grab the ID, and forcefully convert it to a String. 
        // This makes it physically impossible for .replace() to return "undefined".
        const rawId = s.user || s.username || s.id || "MISSING_ID"; 
        const safeStaffId = String(rawId).replace(/'/g, "\\'"); 
        
        const staffPass = s.pass || s.password || "No password set";

        // 4. Draw the UI
        list.innerHTML += `
            <div style="background: #f8f9fa; padding: 12px; border: 1px solid #bdc3c7; border-radius: 4px; margin-bottom: 8px; display: flex; justify-content: space-between; align-items: center;">
                <div>
                    <strong style="color: #2c3e50; font-size: 15px;">👤 ${staffName}</strong><br>
                    <span style="color: #7f8c8d; font-size: 12px; font-weight: bold;">Role: ${staffRole}</span><br>
                    <span style="color: #e74c3c; font-size: 12px; font-weight: bold;">Pass: ${staffPass}</span>
                </div>
                <button class="btn-standard btn-danger admin-only" onclick="deleteStaff('${safeStaffId}')" style="padding: 6px 12px; font-size: 11px; margin: 0;">🗑️ Delete</button>
            </div>
        `;
    });
};


