window.switchSettingsTab = function(tabName) {
    const tabs = ['setTabFees', 'setTabStaff', 'setTabSchool'];
    const btns = ['btnTabFees', 'btnTabStaff', 'btnTabSchool'];
    const colors = { fees: '#2980b9', staff: '#8e44ad', school: '#27ae60' };

    tabs.forEach(t => { if(document.getElementById(t)) document.getElementById(t).style.display = 'none'; });
    btns.forEach(b => { if(document.getElementById(b)) document.getElementById(b).style.background = '#95a5a6'; });

    if (tabName === 'fees') {
        if(document.getElementById('setTabFees')) document.getElementById('setTabFees').style.display = 'block';
        if(document.getElementById('btnTabFees')) document.getElementById('btnTabFees').style.background = colors.fees;
        if (typeof window.renderFeeStructures === 'function') window.renderFeeStructures();
    } else if (tabName === 'staff') {
        if(document.getElementById('setTabStaff')) document.getElementById('setTabStaff').style.display = 'block';
        if(document.getElementById('btnTabStaff')) document.getElementById('btnTabStaff').style.background = colors.staff;
        window.renderStaffList();
    } else if (tabName === 'school') {
        if(document.getElementById('setTabSchool')) document.getElementById('setTabSchool').style.display = 'block';
        if(document.getElementById('btnTabSchool')) document.getElementById('btnTabSchool').style.background = colors.school;
    }
};

window.openSetTab = function(tabId) {
    const normalizedRole = window.getNormalizedRole(window.currentUser && window.currentUser.role);
    if (normalizedRole === 'Level 2' && ['setTabFees', 'setTabStaff', 'setTabSchool'].includes(tabId)) {
        tabId = 'setTabAnnounce';
    }

    // 1. Hide all settings content panels
    document.querySelectorAll('.settings-content').forEach(el => {
        el.classList.remove('active');
        el.style.display = 'none'; 
    });

    // 2. Elegantly handle the active button highlight
    document.querySelectorAll('.tab-btn').forEach(btn => {
        btn.classList.remove('active');
        if (btn.getAttribute('onclick') && btn.getAttribute('onclick').includes(tabId)) {
            btn.classList.add('active');
        }
    });

    // 3. Show the selected panel with your original error handling
    const targetPanel = document.getElementById(tabId);
    if (targetPanel) {
        targetPanel.classList.add('active');
        targetPanel.style.display = 'block';
    } else {
        console.error(`❌ UI Error: Tab "${tabId}" not found in HTML.`);
        return;
    }

    // 4. CRITICAL: Trigger the specific data renders so the tabs aren't blank
    if (tabId === 'setTabSchool') {
        if (typeof window.updateSchoolDisplay === 'function') window.updateSchoolDisplay();
        if (typeof window.renderCustomClasses === 'function') window.renderCustomClasses(); // 🛠️ THE FIX
    } else if (tabId === 'setTabStaff' && typeof window.renderStaffList === 'function') {
        window.renderStaffList();
    } else if (tabId === 'setTabAnnounce' && typeof window.renderAnnouncements === 'function') {
        window.renderAnnouncements();
    } else if (tabId === 'setTabFees' && typeof window.renderFeeStructures === 'function') {
        window.renderFeeStructures();
    }
};

window.customPrompt = function(message, callback) {
    const modal = document.getElementById('securePromptModal');
    const input = document.getElementById('securePromptInput');
    
    if(document.getElementById('securePromptMessage')) document.getElementById('securePromptMessage').innerText = message;
    if(input) input.value = ''; 
    if(modal) modal.style.display = 'flex';
    if(input) input.focus();
    
    if(document.getElementById('securePromptSubmit')) {
        document.getElementById('securePromptSubmit').onclick = function() {
            modal.style.display = 'none';
            callback(input.value.trim());
        };
    }

    if(input) {
        input.onkeydown = function(e) {
            if (e.key === "Enter") document.getElementById('securePromptSubmit').click();
        };
    }
};

window.secureDelete = function(actionName, callback) {
    // 3-Tier Security Architecture Update
    // Replaced generic password check with strict Level 3 Verification
    const role = window.currentUser?.role || "";
    const isChiefAdmin = role.includes('Level 3') || role === 'Chief Admin';

    if (!isChiefAdmin) {
        alert("❌ CRITICAL ACTION DENIED: Only Level 3 (Chief Admins) have clearance for System Wipe actions.");
        return;
    }

    let pass = prompt(`SECURITY LOCK (Level 3 Required):\nEnter Password to completely wipe ${actionName}:`);
    if (pass === null) return; // User clicked cancel
    pass = pass.trim(); 

    const isCurrentAdminMatch = (window.currentUser.password === pass || window.currentUser.pass === pass);
    const isEmergencyOverride = (pass === "havenwipe");

    if (isCurrentAdminMatch || isEmergencyOverride) {
        callback(); 
    } else {
        alert("❌ Incorrect Admin Password. WIPE CANCELLED.");
    }
};

