                    if (phone.startsWith('0')) phone = '263' + phone.slice(1);
                    const receiptMessage = `${schoolName} payment receipt\nStudent: ${student.name}\nStudent ID: ${student.id}\nClass: ${student.grade || student.class || 'N/A'}\nReceipt: ${receiptNo}\nDate: ${date || 'N/A'}\nCash Received: $${(parseFloat(amount) || 0).toFixed(2)}\n${discountAmount > 0 ? `Discount Applied: $${discountAmount.toFixed(2)}\n` : ''}${waiverAmount > 0 ? `Waiver Applied: $${waiverAmount.toFixed(2)}\n` : ''}Total Value Cleared: $${((parseFloat(amount) || 0) + discountAmount + waiverAmount).toFixed(2)}\nMethod: ${method}\nProcessed By: ${processedBy}\n${breakdown.map(item => `${item.desc || item.description || 'Item'}: $${(parseFloat(item.amt || item.amount) || 0).toFixed(2)}`).join('\n')}`;
