window.dispatchSavedReceipt = async function(receiptNo, studentId) {
    const receiptKey = String(receiptNo || '').toUpperCase();
    const transaction = [...(window.__receiptTransactions || []), ...(window.transactions || [])].find(record =>
        String(record.receipt_no || record.receiptNo || record.receipt_number || '').toUpperCase() === receiptKey
    );
    const receiptType = transaction ? window.getReceiptTypeInfo(transaction).type : '';

    if (transaction && ['shop', 'uniform'].includes(receiptType) && typeof window.printShopReceipt === 'function') {
        const processedBy = await window.getArchivedReceiptProcessorName(receiptNo, transaction);
        window.printShopReceipt({ ...transaction, processed_by: processedBy });
        return;
    }

    window.reprintReceipt(receiptNo, studentId);
};

window.openReceiptLog = async function() {
    const tbody = document.getElementById('receiptLogTableBody');
    if(!tbody) return;

    const modal = document.getElementById('receiptLogModal');
    if (modal) modal.style.display = 'flex';
    if (window.__receiptLogLoadInProgress) return;

    tbody.innerHTML = '<tr><td colspan="7" style="text-align:center; padding: 25px;">Fetching records...</td></tr>';
    window.__receiptLogLoadInProgress = true;
    const requestId = (window.__receiptLogRequestId || 0) + 1;
    window.__receiptLogRequestId = requestId;
    let allReceipts = [];
    let receiptSet = new Set();
    let cloudTransactions = [];

    // 1. Gather Fees from Cloud
    try {
        if (!window.supabaseClient) throw new Error('Cloud database is not connected.');
        const [ledgerResult, transactionResult, paymentResult] = await Promise.all([
            window.supabaseClient.from('student_ledger')
                .select('*, students(name, id, balance_owing, grade)')
                .in('type', ['payment', 'discount', 'waiver', 'overpayment'])
                .order('date', { ascending: false })
                .limit(2500),
            window.supabaseClient.from('transactions').select('*').limit(2500),
            window.supabaseClient.from('payments').select('receipt_no,processed_by,served_by').limit(2500)
        ]);
        if (ledgerResult.error) throw ledgerResult.error;
        if (transactionResult.error) throw transactionResult.error;
        if (paymentResult.error) throw paymentResult.error;
        const ledgerRows = ledgerResult.data || [];
        cloudTransactions = transactionResult.data || [];
        const paymentsByReceipt = new Map((paymentResult.data || []).map(payment => [
            String(payment.receipt_no || payment.receiptNo || '').toUpperCase(),
            payment
        ]));
        const receiptTransactions = [...cloudTransactions, ...(window.transactions || [])];
        window.__receiptTransactions = receiptTransactions;
        const transactionByReceipt = new Map();
        receiptTransactions.forEach(transaction => {
            const transactionReceipt = String(transaction.receipt_no || transaction.receiptNo || transaction.receipt_number || '').toUpperCase();
            if (transactionReceipt && !transactionByReceipt.has(transactionReceipt)) transactionByReceipt.set(transactionReceipt, transaction);
        });

                let groupedReceipts = {};
                
                ledgerRows.forEach(l => {
                    const rNo = String(l.receipt_no || l.receiptNo || '').toUpperCase();
                    if (!rNo) return;
                    
                    if (!groupedReceipts[rNo]) {
                        groupedReceipts[rNo] = { ...l, totalAmount: 0, discountAmount: 0, receiptEntries: [] };
                    }
                    const ledgerType = String(l.type || '').toLowerCase();
                    if (ledgerType === 'discount') groupedReceipts[rNo].discountAmount += Math.abs(parseFloat(l.amount) || 0);
                    else if (ledgerType === 'waiver') groupedReceipts[rNo].waiverAmount = (groupedReceipts[rNo].waiverAmount || 0) + Math.abs(parseFloat(l.amount) || 0);
                    else groupedReceipts[rNo].totalAmount += parseFloat(l.amount) || 0;
                    groupedReceipts[rNo].receiptEntries.push(l);
                    if (!groupedReceipts[rNo].date) groupedReceipts[rNo].date = l.date || l.created_at || l.timestamp || '';
                });

                for (const l of Object.values(groupedReceipts)) {
                    const rNo = l.receipt_no || l.receiptNo || l.id;
                    const isVoid = l.receiptEntries.every(entry => ['VOID', 'VOIDED'].includes(String(entry.status || '').toUpperCase()));
                    const matchingSale = transactionByReceipt.get(String(rNo).toUpperCase());
                    const matchingPayment = paymentsByReceipt.get(String(rNo).toUpperCase());
                    
                    const studentData = Array.isArray(l.students) ? l.students[0] : l.students;
                    const studentBalance = studentData ? parseFloat(studentData.balance_owing || 0) : 0;
                    const studentGrade = studentData ? (studentData.grade || '') : '';
                    
                    let statusHTML = '';
                    if (isVoid) {
                        statusHTML = '<span style="color: #c0392b; font-weight: bold; background: #fadbd8; padding: 3px 8px; border-radius: 4px; font-size: 11px;">VOIDED</span>';
                    } else {
                        statusHTML = `<span style="color: #27ae60; font-weight: bold; font-size: 12px;">Processed</span><br>
                                      <span style="font-size: 10px; color: ${studentBalance > 0 ? '#f39c12' : '#27ae60'};">
                                        Acc Bal: $${studentBalance.toFixed(2)}
                                      </span>`;
                    }

                    const studentName = studentData ? `${studentData.name} (${studentData.id})` : `Student (${l.student_id})`;
                    
                    const receiptType = window.getReceiptTypeInfo({
                        ...(matchingSale || {}),
                        ...l,
                        receipt_no: rNo,
                        category: matchingSale?.category || l.category,
                        cartdetails: matchingSale?.cartdetails || l.cartdetails,
                        description: `${l.receiptEntries.map(entry => entry.description || entry.desc || '').join(' ')} ${matchingSale?.description || ''}`,
                        breakdown: l.receiptEntries.flatMap(entry => Array.isArray(entry.breakdown) ? entry.breakdown : [])
                    });

                    allReceipts.push({ 
                        no: rNo, 
                        date: l.date || l.created_at || l.timestamp || '', 
                        name: studentName, 
                        studentId: l.student_id,
                        grade: studentGrade, 
                        amt: l.totalAmount, 
                        type: receiptType.type, 
                        typeLabel: receiptType.label,
                        status: statusHTML,
                        isVoid: isVoid,
                        description: `${l.receiptEntries.map(entry => entry.description || entry.desc || '').filter(Boolean).join(' / ')} ${matchingSale?.description || ''}`.trim() || 'General Payment',
                        cashier: window.getReceiptProcessorName(...l.receiptEntries, matchingPayment, matchingSale),
                        discountAmount: l.discountAmount,
                        waiverAmount: l.waiverAmount || 0
                    });
                    receiptSet.add(rNo.toUpperCase());
                }

    // 2. Gather Shop & Uniform Sales
    const transactionRows = [...cloudTransactions, ...(window.transactions || [])];
    const transactionIds = new Set();
    const globalTxns = transactionRows.filter(transaction => {
        const key = String(transaction.id || transaction.receipt_no || transaction.receiptNo || transaction.receipt_number || '');
        if (!key || transactionIds.has(key)) return false;
        transactionIds.add(key);
        return true;
    });
    for (const t of globalTxns) {
        const rNum = t.receipt_no || t.receiptNo || t.receipt_number;
        if (rNum && !receiptSet.has(rNum.toUpperCase())) {
            const receiptType = window.getReceiptTypeInfo(t);
            const isVoid = (t.status === 'VOID' || t.status === 'VOIDED');
            
            let statusHTML = isVoid 
                ? '<span style="color: #c0392b; font-weight: bold; background: #fadbd8; padding: 3px 8px; border-radius: 4px; font-size: 11px;">VOIDED</span>'
                : '<span style="color: #27ae60; font-weight: bold; font-size: 12px;">Processed</span>';
            
            const studentRecord = (window.students || []).find(student => String(student.id) === String(t.student_id));
            allReceipts.push({ 
                no: rNum, 
                date: t.date || t.created_at || '', // 🎯 Apply fallback here too
                name: studentRecord?.name || t.student_name || t.description || "Walk-in Customer", 
                studentId: t.student_id || 'walk-in',
                grade: t.student_class || t.grade || studentRecord?.grade || '',
                amt: parseFloat(t.amount || t.total) || 0, 
                type: receiptType.type, 
                typeLabel: receiptType.label,
                status: statusHTML,
                isVoid: isVoid,
                description: t.description || 'Shop Sale',
                cashier: window.getReceiptProcessorName(t)
            });
            receiptSet.add(rNum.toUpperCase());
        }
    }

    if (requestId !== window.__receiptLogRequestId) return;
    window.__receiptLogCache = allReceipts;
    window.__receiptLogLoadInProgress = false;
    window.renderReceiptLog();
    } catch (error) {
        console.error("Could not load receipt log:", error);
        window.__receiptLogLoadInProgress = false;
        if (requestId === window.__receiptLogRequestId) {
            tbody.innerHTML = `<tr><td colspan="7" style="text-align:center; padding:25px; color:#c0392b;">Could not load receipts: ${String(error.message || error).replace(/[<>&"]/g, char => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;' })[char])}</td></tr>`;
        }
    }
};

window.renderReceiptLog = function() {
    const tbody = document.getElementById('receiptLogTableBody');
    if (!tbody) return;
    const allReceipts = window.__receiptLogCache || [];
    const fSearch = document.getElementById('receiptSearchText')?.value.toLowerCase().trim() || '';
    const fType = document.getElementById('receiptFilterType')?.value || 'all';
    const fStart = document.getElementById('receiptStartDate')?.value || '';
    const fEnd = document.getElementById('receiptEndDate')?.value || '';

    // 3. Apply Multi-layered Filters & Text Search
    let filteredReceipts = allReceipts.filter(r => {
        let matchSearch = true;
        if (fSearch !== '') {
            const compiledString = `${r.no} ${r.name} ${r.studentId} ${r.grade} ${r.description}`.toLowerCase();
            if (!compiledString.includes(fSearch)) matchSearch = false;
        }

        let matchType = false;
        if (fType === 'all') matchType = true;
        else if (fType === 'fees' && r.type === 'fees') matchType = true;
        else if (fType === 'shop' && (r.type === 'shop' || r.type === 'uniform')) matchType = true;
        else if (fType === 'event' && r.type === 'event') matchType = true; 
        
        const cleanRecordDate = r.date instanceof Date
            ? [r.date.getFullYear(), String(r.date.getMonth() + 1).padStart(2, '0'), String(r.date.getDate()).padStart(2, '0')].join('-')
            : String(r.date || '').slice(0, 10);

        let matchStart = (!fStart) || (cleanRecordDate >= fStart);
        let matchEnd = (!fEnd) || (cleanRecordDate <= fEnd);
        
        return matchSearch && matchType && matchStart && matchEnd;
    });    
    filteredReceipts.sort((a, b) => {
        const dateCompare = String(b.date || '').slice(0, 10).localeCompare(String(a.date || '').slice(0, 10));
        return dateCompare || String(b.no).localeCompare(String(a.no));
    });
    
    const pageSize = 50;
    const pageCount = Math.max(1, Math.ceil(filteredReceipts.length / pageSize));
    window.__receiptLogPage = Math.min(Math.max(1, window.__receiptLogPage || 1), pageCount);
    const pageStart = (window.__receiptLogPage - 1) * pageSize;
    const pageReceipts = filteredReceipts.slice(pageStart, pageStart + pageSize);

    // 4. Render Table
    if(filteredReceipts.length === 0) {
        tbody.innerHTML = '<tr><td colspan="7" style="text-align:center; padding: 25px; color: #7f8c8d;">No receipts found matching your search.</td></tr>';
    } else {
        let tableHTML = '';
        
        pageReceipts.forEach(r => {
            const amtColor = r.isVoid ? '#95a5a6' : ((r.type.includes('shop') || r.type === 'uniform') ? '#d35400' : (r.type === 'event' ? '#8e44ad' : '#27ae60')); 
            const rowBg = r.isVoid ? '#fdf2f2' : '#fff';
            const strikeText = r.isVoid ? 'text-decoration: line-through; opacity: 0.7;' : '';
            
            let badgeStyle = '';
            if (r.type === 'fees') badgeStyle = 'background: #e0f2fe; color: #0284c7; border: 1px solid #38bdf8;';
            if (r.type === 'event') badgeStyle = 'background: #ede9fe; color: #7c3aed; border: 1px solid #8b5cf6;';
            if (r.type.includes('shop') || r.type === 'uniform') badgeStyle = 'background: #fef3c7; color: #d97706; border: 1px solid #f59e0b;';

            const actionButtons = r.isVoid 
                ? `<span style="font-size: 11px; color: #7f8c8d; font-style: italic;">Locked</span>`
                : `<div style="display: flex; gap: 5px; justify-content: center;">
                       <button onclick="window.dispatchSavedReceipt(JSON.parse(decodeURIComponent('${encodeURIComponent(JSON.stringify(r.no))}')), JSON.parse(decodeURIComponent('${encodeURIComponent(JSON.stringify(r.studentId))}')))" 
                               style="background: #3498db; color: white; border: none; padding: 5px 8px; border-radius: 3px; cursor: pointer; font-size: 11px; font-weight: bold;">
                           👁️ View
                       </button>
                       <button onclick="processVoid(JSON.parse(decodeURIComponent('${encodeURIComponent(JSON.stringify(r.no))}')), JSON.parse(decodeURIComponent('${encodeURIComponent(JSON.stringify(r.studentId))}')), ${r.amt}, '${r.type}')" 
                               style="background: #e74c3c; color: white; border: none; padding: 5px 8px; border-radius: 3px; cursor: pointer; font-size: 11px; font-weight: bold;">
                           Void
                       </button>
                   </div>`;

            const displayGrade = r.grade ? `<br><span style="font-size:10px; color:#7f8c8d;">Class: ${r.grade}</span>` : '';

            tableHTML += `
                <tr style="border-bottom: 1px solid #ecf0f1; background: ${rowBg};">
                    <td style="padding: 10px; ${strikeText}"><strong>${r.no}</strong></td>
                    <td style="padding: 10px; color: #555; ${strikeText}">
                            ${r.date ? String(r.date).substring(0, 10) : 'Unknown Date'}<br>
                            <span style="font-size: 10px; color: #95a5a6; font-weight: bold;">👤 ${r.cashier}</span>
                        </td>
                    <td style="padding: 10px; font-size: 11px;">
                        <span style="padding: 2px 6px; border-radius: 4px; font-weight: bold; font-size: 9px; ${badgeStyle} ${strikeText}">${r.typeLabel}</span><br>
                        <small style="color:#666; display: block; margin-top: 4px; line-height: 1.2;">${r.description.length > 50 ? r.description.substring(0, 50) + '...' : r.description}</small>
                    </td>
                    <td style="padding: 10px; ${strikeText}">${r.name} ${displayGrade}</td>
                    <td style="padding: 10px; font-weight: bold; color: ${amtColor}; text-align: right; ${strikeText}">$${(parseFloat(r.amt) || 0).toFixed(2)}${r.discountAmount > 0 ? `<br><small style="font-weight:normal;color:#7c3aed;">Discount: $${r.discountAmount.toFixed(2)}</small>` : ''}${r.waiverAmount > 0 ? `<br><small style="font-weight:normal;color:#7c3aed;">Waiver: $${r.waiverAmount.toFixed(2)}</small>` : ''}</td>
                    <td style="padding: 10px; text-align: center;">${r.status}</td>
                    <td style="padding: 10px; text-align: center;">${actionButtons}</td>
                </tr>`;
        });
        
        tbody.innerHTML = tableHTML;
    }
    
    const pagination = document.getElementById('receiptLogPagination');
    if (pagination) {
        pagination.innerHTML = filteredReceipts.length > pageSize
            ? `<div style="display:flex; justify-content:space-between; align-items:center; gap:10px; padding:10px 2px;">
                   <span style="font-size:12px; color:#555;">Showing ${pageStart + 1}-${Math.min(pageStart + pageSize, filteredReceipts.length)} of ${filteredReceipts.length} receipts</span>
                   <div style="display:flex; gap:6px;">
                       <button class="btn-standard btn-primary" ${window.__receiptLogPage <= 1 ? 'disabled' : ''} onclick="window.setReceiptLogPage(${window.__receiptLogPage - 1})">Previous</button>
                       <span style="align-self:center; font-size:12px;">Page ${window.__receiptLogPage} of ${pageCount}</span>
                       <button class="btn-standard btn-primary" ${window.__receiptLogPage >= pageCount ? 'disabled' : ''} onclick="window.setReceiptLogPage(${window.__receiptLogPage + 1})">Next</button>
                   </div>
               </div>`
            : `<div style="padding:8px 2px; font-size:12px; color:#555;">${filteredReceipts.length} receipt${filteredReceipts.length === 1 ? '' : 's'}</div>`;
    }
};

window.setReceiptLogPage = function(page) {
    window.__receiptLogPage = Math.max(1, parseInt(page, 10) || 1);
    window.renderReceiptLog();
};
// 3. ADD THIS TO YOUR JAVASCRIPT
window.globalVoidedData = [];

window.openVoidedLog = async function() {
    const modal = document.getElementById('voidedLogModal');
    const tbody = document.getElementById('voidedTableBody');
    if (!modal || !tbody) return;

    modal.style.display = 'flex';
    tbody.innerHTML = '<tr><td colspan="8" style="text-align:center; padding: 25px;">Fetching voided records...</td></tr>';

    try {
        const [voidResult, transactionResult] = await Promise.all([
            window.supabaseClient.from('voided_transactions').select('*').order('voided_date', { ascending: false }),
            window.supabaseClient.from('transactions').select('*').limit(2500)
        ]);

        if (voidResult.error) throw voidResult.error;
        if (!transactionResult.error && transactionResult.data) {
            window.__receiptTransactions = transactionResult.data;
        }

        window.globalVoidedData = voidResult.data || [];
        window.renderVoidedTable();
    } catch (err) {
        console.error("Error fetching voided transactions:", err);
        tbody.innerHTML = '<tr><td colspan="8" style="text-align:center; color: red; padding: 25px;">Failed to load data.</td></tr>';
    }
};

window.renderVoidedTable = function() {
    const tbody = document.getElementById('voidedTableBody');
    const typeFilter = document.getElementById('voidTypeFilter').value;
    const startDate = document.getElementById('voidStartFilter').value;
    const endDate = document.getElementById('voidEndFilter').value;

    const getVoidedReceiptType = row => {
        const receiptNo = String(row.receipt_no || '').toUpperCase();
        const matchingSale = [...(window.__receiptTransactions || []), ...(window.transactions || [])].find(transaction =>
            String(transaction.receipt_no || transaction.receiptNo || transaction.receipt_number || '').toUpperCase() === receiptNo
        );
        const student = (window.students || []).find(record => String(record.id) === String(row.customer_id));
        const ledgerEntries = (student?.ledger || []).filter(entry =>
            String(entry.receipt_no || entry.receiptNo || '').toUpperCase() === receiptNo
        );
        return window.getReceiptTypeInfo({
            ...(matchingSale || {}),
            receipt_no: receiptNo,
            category: matchingSale?.category,
            cartdetails: matchingSale?.cartdetails,
            description: `${matchingSale?.description || ''} ${ledgerEntries.map(entry => entry.description || entry.desc || '').join(' ')} ${row.reason || ''}`,
            breakdown: ledgerEntries.flatMap(entry => Array.isArray(entry.breakdown) ? entry.breakdown : [])
        });
    };

    let filteredData = window.globalVoidedData.filter(row => {
        const rowType = getVoidedReceiptType(row).type;
        if (typeFilter !== 'all' && rowType !== typeFilter) return false;

        // Apply Date Filter (comparing YYYY-MM-DD)
        const vDate = row.voided_date ? row.voided_date.split('T')[0] : '';
        if (startDate && vDate < startDate) return false;
        if (endDate && vDate > endDate) return false;

        return true;
    });

    if (filteredData.length === 0) {
        tbody.innerHTML = '<tr><td colspan="8" style="text-align:center; padding: 25px; color: #7f8c8d;">No voided transactions found for these filters.</td></tr>';
        return;
    }

    // Fast string building rendering
    let html = '';
    filteredData.forEach(row => {
        const dateStr = new Date(row.voided_date).toLocaleString('en-GB', { dateStyle: 'medium', timeStyle: 'short' });
        const rNo = String(row.receipt_no).toUpperCase();
        const receiptType = getVoidedReceiptType(row);
        const typeColor = receiptType.type === 'event' ? '#7c3aed' : receiptType.type === 'shop' ? '#d97706' : '#0284c7';
        const typeBackground = receiptType.type === 'event' ? '#ede9fe' : receiptType.type === 'shop' ? '#fef3c7' : '#e0f2fe';
        const badge = `<span style="background:${typeBackground}; color:${typeColor}; padding:2px 6px; border-radius:4px; font-size:10px;">${receiptType.label}</span>`;

        // 👇 NEW: Look up the student's name from your global data 👇
        let customerDisplay = row.customer_id;
        try {
            const allStudents = window.students || (JSON.parse(localStorage.getItem('haven_data')) || {}).students || [];
            const foundStudent = allStudents.find(s => String(s.id) === String(row.customer_id));
            if (foundStudent && foundStudent.name) {
                // Formats it neatly with ID on top, Name on bottom in a lighter color
                customerDisplay = `${row.customer_id}<br><span style="font-size: 11px; color: #7f8c8d; font-weight: normal;">${foundStudent.name}</span>`;
            }
        } catch (e) {
            console.warn("Could not lookup student name for voided log", e);
        }

        html += `
            <tr style="border-bottom: 1px solid #ecf0f1; background: #fff;">
                <td style="padding: 10px; color: #555;">${dateStr}</td>
                <td style="padding: 10px; font-weight: bold;">${rNo}</td>
                <td style="padding: 10px; color: #2980b9; font-weight: bold;">${customerDisplay}</td>
                <td style="padding: 10px;">${badge}</td>
                <td style="padding: 10px; text-align: right; font-weight: bold; color: #c0392b;">$${parseFloat(row.amount).toFixed(2)}</td>
                <td style="padding: 10px;">${row.voided_by_admin}</td>
                <td style="padding: 10px; color: #7f8c8d; font-style: italic;">${row.reason}</td>
                <td style="padding: 10px; text-align: center;">
                    <span style="background: #e8f8f5; color: #27ae60; padding: 4px 8px; border-radius: 4px; font-size: 11px; font-weight: bold;">✅ Success</span>
                </td>
            </tr>
        `;
    });

    tbody.innerHTML = html;
};
// ==========================================
// BULLETPROOF VOID & REVERSAL PROCESSOR
// ==========================================
window.processVoid = async function(receiptNo, studentId, uiAmount, type) {
    if (window.__voidInProgress || window.__voidPromptInProgress) {
        return alert("A receipt void is already in progress. Please wait for it to finish.");
    }

    // 1. STRICT SECURITY & AUTHORIZATION 
    if (!window.currentUser) return alert("⛔ Access Denied: You must be logged in.");

    const role = window.currentUser.role || "";
    if (!(role.includes('Level 3') || role === 'Chief Admin')) {
        return alert("⛔ Access Denied: Only Level 3 (Chief Admins) have clearance to void transactions.");
    }
    window.__voidPromptInProgress = true;

    // 2. AUDIT PROMPTS & CONFIRMATION
    const adminName = window.currentUser.name || window.currentUser.user || window.currentUser.username || 'Unknown Admin';
    const reason = prompt(`⚠️ VOID RECEIPT: Please enter the reason for voiding Receipt ${receiptNo}:`);
    
    if (!reason || reason.trim() === "") {
        window.__voidPromptInProgress = false;
        return alert("Void cancelled. A valid reason is required for the audit trail.");
    }

    let ledgerBeforeVoid = null;
    let ledgerRowsForReceipt = [];
    let balanceBeforeVoid = null;
    let expectedBalanceAfterVoid = null;
    const isStudentReceipt = studentId && studentId !== 'walk-in' && studentId !== 'WALK-IN';
    if (!window.supabaseClient) {
        window.__voidPromptInProgress = false;
        return alert("Database connection is missing. The receipt was not voided.");
    }
    if (isStudentReceipt) {
        let data;
        try {
            const result = await window.supabaseClient
                .from('student_ledger')
                .select('id,receipt_no,status,type,amount')
                .eq('student_id', studentId);
            if (result.error) throw result.error;
            data = result.data;
        } catch (error) {
            window.__voidPromptInProgress = false;
            return alert(`Could not verify the student ledger before voiding: ${error.message || error}`);
        }

        ledgerBeforeVoid = data || [];
        const receiptKey = String(receiptNo || '').toLowerCase();
        ledgerRowsForReceipt = ledgerBeforeVoid.filter(entry =>
            String(entry.receipt_no || entry.receiptNo || '').toLowerCase() === receiptKey ||
            String(entry.id || '').toLowerCase().includes(receiptKey)
        );
        const activeReceiptRows = ledgerRowsForReceipt.filter(entry =>
            !['VOID', 'VOIDED', 'REVERSAL'].includes(String(entry.status || '').toUpperCase())
        );

        if (activeReceiptRows.length === 0 && (type === 'fees' || type === 'event')) {
            window.__voidPromptInProgress = false;
            return alert(`No active student-ledger entries were found for ${receiptNo}. The tuition/event reversal was stopped to avoid changing the wrong balance.`);
        }

        balanceBeforeVoid = window.calculateStudentBalance({ ledger: ledgerBeforeVoid });
        expectedBalanceAfterVoid = window.calculateStudentBalance({
            ledger: ledgerBeforeVoid.filter(entry => !ledgerRowsForReceipt.includes(entry))
        });
    }

    const balancePreview = balanceBeforeVoid === null
        ? ''
        : `\n\nStudent balance before: $${balanceBeforeVoid.toFixed(2)}\nExpected balance after reversal: $${expectedBalanceAfterVoid.toFixed(2)}`;
    const confirmVoid = confirm(`FINAL WARNING: Voiding Receipt ${receiptNo}.${balancePreview}\n\nThis will revert the transaction, restock inventory, and update the student ledger. Proceed?`);
    if (!confirmVoid) {
        window.__voidPromptInProgress = false;
        return;
    }

    window.__voidInProgress = true;
    window.__voidPromptInProgress = false;
    const previousCursor = document.body.style.cursor;
    document.body.style.cursor = 'wait';
    try {
        if (!window.supabaseClient) throw new Error("Database connection is missing.");

        let trueAmount = parseFloat(uiAmount) || 0;
        let ecoRefToRelease = null;

        // ==========================================
        // 3. INVENTORY RESTOCK & TRANSACTION VOID (SHOP/UNIFORMS)
        // ==========================================
        let { data: txData, error: txFetchErr } = await window.supabaseClient
            .from('transactions')
            .select('id,status,paymentmethod,cartdetails')
            .eq('receipt_no', receiptNo);

        if (!txFetchErr && (!txData || txData.length === 0)) {
            const receiptKey = String(receiptNo || '').trim().toUpperCase();
            const cachedSale = [
                ...(window.__receiptTransactions || []),
                ...(window.transactions || [])
            ].find(transaction =>
                String(transaction.receipt_no || transaction.receiptNo || transaction.receipt_number || '')
                    .trim()
                    .toUpperCase() === receiptKey
            );

            if (cachedSale?.id) {
                const cachedSaleResult = await window.supabaseClient
                    .from('transactions')
                    .select('id,status,paymentmethod,cartdetails')
                    .eq('id', cachedSale.id);
                if (cachedSaleResult.error) throw cachedSaleResult.error;
                txData = cachedSaleResult.data;
            }
        }

        if (!txFetchErr && (!txData || txData.length === 0)) {
            const legacyTransactionResult = await window.supabaseClient
                .from('transactions')
                .select('id,status,paymentmethod,cartdetails')
                .eq('receipt_number', receiptNo);
            if (!legacyTransactionResult.error) txData = legacyTransactionResult.data;
        }

        if (txFetchErr) throw txFetchErr;
        if (txData && txData.length > 0) {
            const sale = txData[0];
            if (['VOID', 'VOIDED'].includes(String(sale.status || '').toUpperCase())) {
                return alert(`Receipt ${receiptNo} is already voided. Inventory was not changed again.`);
            }
            
            if (sale.paymentmethod && sale.paymentmethod.includes('EcoCash')) {
                const match = sale.paymentmethod.match(/\(([^)]+)\)/);
                if (match) ecoRefToRelease = match[1];
            }

            if (!sale.cartdetails) throw new Error('This shop receipt has no item-level sale details; it cannot be safely restocked.');
            let cart = typeof sale.cartdetails === 'string' ? JSON.parse(sale.cartdetails) : sale.cartdetails;
            if (!Array.isArray(cart)) cart = cart ? [cart] : [];
            if (cart.length === 0) throw new Error('This shop receipt has no item quantities to restock.');

            const restoreQuantities = new Map();
            cart.forEach(item => {
                const itemId = item.id || item.item_id || item.inventory_id;
                const quantity = parseInt(item.cartQty || item.qty || item.quantity || item.count, 10) || 0;
                if (!itemId || quantity <= 0) throw new Error('A sold item is missing its inventory ID or quantity. Inventory was not changed.');
                restoreQuantities.set(String(itemId), (restoreQuantities.get(String(itemId)) || 0) + quantity);
            });

            const inventoryIds = Array.from(restoreQuantities.keys());
            const { data: cloudInventory, error: inventoryFetchError } = await window.supabaseClient
                .from('inventory')
                .select('*')
                .in('id', inventoryIds);
            if (inventoryFetchError) throw inventoryFetchError;

            const inventoryById = new Map((cloudInventory || []).map(item => [String(item.id), item]));
            const restoreRows = inventoryIds.map(itemId => {
                const inventoryItem = inventoryById.get(itemId);
                if (!inventoryItem) throw new Error(`Inventory item ${itemId} was not found. Sale remains active and no stock was changed.`);
                const previousQty = parseInt(inventoryItem.qty, 10) || 0;
                return { ...inventoryItem, qty: previousQty + restoreQuantities.get(itemId) };
            });

            const { error: restockError } = await window.supabaseClient
                .from('inventory')
                .upsert(restoreRows, { onConflict: 'id' });
            if (restockError) throw restockError;

            const { data: voidedSale, error: saleVoidError } = await window.supabaseClient
                .from('transactions')
                .update({ status: 'VOID', notes: `Voided by ${adminName} - ${reason.trim()}` })
                .eq('id', sale.id)
                .select('id');
            if (saleVoidError || !voidedSale || voidedSale.length === 0) {
                const rollbackRows = restoreRows.map(item => ({
                    ...item,
                    qty: (parseInt(item.qty, 10) || 0) - restoreQuantities.get(String(item.id))
                }));
                const { error: rollbackError } = await window.supabaseClient
                    .from('inventory')
                    .upsert(rollbackRows, { onConflict: 'id' });
                if (rollbackError) throw new Error(`Sale void failed (${saleVoidError?.message || 'sale not updated'}) and inventory rollback failed (${rollbackError.message}).`);
                if (saleVoidError) throw saleVoidError;
                throw new Error('Sale was not marked void; restored inventory quantities were rolled back.');
            }

            const syncLocalInventory = inventory => {
                restoreRows.forEach(restoredItem => {
                    const localItem = inventory.find(item => String(item.id) === String(restoredItem.id));
                    if (localItem) Object.assign(localItem, restoredItem);
                    else inventory.push({ ...restoredItem });
                });
            };
            window.inventory = Array.isArray(window.inventory) ? window.inventory : [];
            window.shopInventory = Array.isArray(window.shopInventory) ? window.shopInventory : [];
            syncLocalInventory(window.inventory);
            syncLocalInventory(window.shopInventory);
            localStorage.setItem('havenInventory', JSON.stringify(window.inventory));
            localStorage.setItem('haven_inventory', JSON.stringify(window.inventory));
            localStorage.setItem('havenShopInventory', JSON.stringify(window.shopInventory));

            if (window.transactions) {
                window.transactions.forEach(t => {
                    if ((t.receipt_no || t.receiptNo || t.receipt_number) === receiptNo) t.status = 'VOID';
                });
            }
        } else if (type === 'shop' || type === 'uniform') {
            throw new Error('The shop sale record was not found, so inventory quantities could not be restored.');
        }

        // ==========================================
        // 4. PAYMENTS TABLE VOID (FEES/EVENTS)
        // ==========================================
        const { data: payData, error: payDataErr } = await window.supabaseClient
            .from('payments')
            .select('*')
            .eq('receipt_no', receiptNo);
        
        if (payDataErr) throw payDataErr;
        if (payData && payData.length > 0) {
            trueAmount = payData.reduce((total, row) => total + (parseFloat(row.amount) || 0), 0);
            
            if (!ecoRefToRelease && payData[0].method && payData[0].method.includes('EcoCash')) {
                const match = payData[0].method.match(/\(([^)]+)\)/);
                if (match) ecoRefToRelease = match[1];
            }

            const { error: paymentsVoidError } = await window.supabaseClient.from('payments')
                .update({ status: 'VOID', notes: `Voided by ${adminName} - ${reason.trim()}` })
                .eq('receipt_no', receiptNo);
            if (paymentsVoidError) throw paymentsVoidError;

            const { error: eventHistoryVoidError } = await window.supabaseClient.from('event_history')
                .update({ status: 'VOID' })
                .eq('receipt_no', receiptNo);
            if (eventHistoryVoidError && !String(eventHistoryVoidError.message || '').includes('does not exist')) throw eventHistoryVoidError;
        }

        // ==========================================
        // 5. RELEASE ECOCASH (IF APPLICABLE)
        // ==========================================
        if (ecoRefToRelease && typeof window.releasePaymentReference === 'function') {
            await window.releasePaymentReference(ecoRefToRelease);
        }

        // ==========================================
        // 6. UNIVERSAL LEDGER REVERSAL & BALANCE UPDATE
        // ==========================================
        const ledgerEntryIds = [...new Set(ledgerRowsForReceipt.map(entry => entry.id).filter(Boolean))];
        if (isStudentReceipt && ledgerEntryIds.length === 0 && (type === 'fees' || type === 'event')) {
            throw new Error(`No ledger entries could be safely identified for ${receiptNo}; the student balance was not changed.`);
        }
        let ledgerVoidQuery = window.supabaseClient.from('student_ledger')
            .update({ status: 'VOID', voided_at: new Date().toISOString() });
        if (isStudentReceipt && ledgerEntryIds.length > 0) {
            ledgerVoidQuery = ledgerVoidQuery.eq('student_id', studentId).in('id', ledgerEntryIds);
        } else if (!isStudentReceipt) {
            ledgerVoidQuery = ledgerVoidQuery.eq('receipt_no', receiptNo);
        }
        if (!isStudentReceipt || ledgerEntryIds.length > 0) {
            const { error: ledgErr } = await ledgerVoidQuery;
            if (ledgErr) throw ledgErr;
        }

        const { error: voidAuditError } = await window.supabaseClient.from('voided_transactions').insert([{
            receipt_no: receiptNo, amount: trueAmount, customer_id: studentId, voided_by_admin: adminName, reason: reason.trim()
        }]);
        if (voidAuditError) throw voidAuditError;

        // DB-First Balance Recalculation
        if (studentId && studentId !== 'walk-in' && studentId !== 'WALK-IN') {
            const { data: currentLedger, error: ledgerFetchErr } = await window.supabaseClient
                .from('student_ledger')
                .select('id,receipt_no,status,type,amount')
                .eq('student_id', studentId);

            if (ledgerFetchErr) throw ledgerFetchErr;

            const recalculatedBalance = window.calculateStudentBalance({ ledger: currentLedger || [] });
            const stillActiveReceiptRows = (currentLedger || []).filter(entry =>
                (
                    String(entry.receipt_no || entry.receiptNo || '').toLowerCase() === String(receiptNo || '').toLowerCase() ||
                    String(entry.id || '').toLowerCase().includes(String(receiptNo || '').toLowerCase())
                ) &&
                !['VOID', 'VOIDED', 'REVERSAL'].includes(String(entry.status || '').toUpperCase())
            );
            if (stillActiveReceiptRows.length > 0) {
                throw new Error(`The ledger still contains active entries for ${receiptNo}; the reversal could not be verified.`);
            }

            const { error: balanceUpdateError } = await window.supabaseClient
                .from('students')
                .update({ balance_owing: recalculatedBalance })
                .eq('id', studentId);
            if (balanceUpdateError) throw balanceUpdateError;

            if (window.students) {
                const target = window.students.find(s => String(s.id) === String(studentId));
                if (target) {
                    target.balance_owing = recalculatedBalance;
                    target.balanceOwing = recalculatedBalance;
                    
                    if (target.ledger) {
                        target.ledger.forEach(l => {
                            if (l.receipt_no === receiptNo || l.receiptNo === receiptNo || (l.id && l.id.includes(receiptNo))) {
                                l.status = 'VOID';
                                l.voided_at = new Date().toISOString();
                            }
                        });
                    }
                }
            }
        }

        // ==========================================
        // 7. UI REFRESH & FEEDBACK
        // ==========================================
        const verifiedBalance = isStudentReceipt && window.students
            ? window.students.find(student => String(student.id) === String(studentId))?.balanceOwing
            : null;
        const balanceMessage = Number.isFinite(verifiedBalance)
            ? `\nVerified student balance after reversal: $${verifiedBalance.toFixed(2)}.`
            : '';
        alert(`✅ Receipt ${receiptNo} has been reversed and the student ledger update was verified.${balanceMessage}\nInventory has been restocked where applicable.`);

        const activeSection = document.querySelector('.main-content .section.active');
        if (activeSection?.id === 'dashboard' && typeof window.updateDashboard === 'function') {
            window.updateDashboard();
        }
        if (activeSection?.id === 'enrollment' && typeof window.filterDirectory === 'function') {
            window.filterDirectory();
        }
        if (activeSection?.id === 'shop' && txData && txData.length > 0 && typeof window.renderInventory === 'function') {
            window.renderInventory();
        }
        if (studentId && studentId !== 'walk-in' && studentId !== 'WALK-IN' &&
            document.getElementById('currentLedgerStudentId')?.value === String(studentId) &&
            typeof window.viewLedger === 'function') {
            window.viewLedger(studentId);
        }

        const receiptLogModal = document.getElementById('receiptLogModal');
        if (receiptLogModal && getComputedStyle(receiptLogModal).display !== 'none' &&
            typeof window.openReceiptLog === 'function') {
            window.openReceiptLog().catch(refreshError => console.error("Receipt log refresh failed after void:", refreshError));
        }
        const activeFinanceTab = document.querySelector('#finance .fin-tab-content.active');
        if (activeFinanceTab?.id === 'finTabRecon' && typeof window.calculateReconciliation === 'function') {
            window.calculateReconciliation().catch(refreshError => console.error("Reconciliation refresh failed after void:", refreshError));
        }

    } catch (err) {
        console.error("Void Failed:", err);
        alert("Failed to perfectly void receipt. " + (err.message || "Check console for details."));
    } finally {
        window.__voidInProgress = false;
        window.__voidPromptInProgress = false;
        document.body.style.cursor = previousCursor;
    }
};



// Function to fetch and display all voided receipts in a modal or console log
window.viewVoidedReceipts = async function() {
    try {
        if (typeof window.supabaseClient === 'undefined') {
            throw new Error("Supabase client is not initialized.");
        }

        const { data, error } = await window.supabaseClient
            .from('voided_transactions')
            .select('*')
            .order('voided_date', { ascending: false });

        if (error) throw error;

        console.table(data);
        alert(`Found ${data.length} voided receipt(s). Check your browser console for details.`);
        return data;
    } catch (err) {
        console.error("Error fetching voided receipts:", err);
        alert("Could not load voided receipts: " + err.message);
    }
};

