window.openRosterModal = function() {
    const gradeSelect = document.getElementById('rosterGrade');
    if(!gradeSelect) return;
    
    gradeSelect.innerHTML = '<option value="ALL">All Classes</option>';
    
    if (window.officialClasses) {
        window.officialClasses.sort((a,b) => a.level.localeCompare(b.level)).forEach(c => {
            gradeSelect.innerHTML += `<option value="${c.level}">${c.level}</option>`;
        });
    } else {
        const uniqueGrades = [...new Set(window.students.map(s => s.grade))].filter(g => g);
        uniqueGrades.sort().forEach(g => {
            gradeSelect.innerHTML += `<option value="${g}">${g}</option>`;
        });
    }
    
    document.getElementById('rosterPrintArea').style.display = 'none';
    document.getElementById('btnPrintRoster').style.display = 'none';
    document.getElementById('rosterModal').style.display = 'flex';
};

window.generateRoster = function() {
    const selGrade = document.getElementById('rosterGrade').value;
    const selYear = document.getElementById('rosterYear').value;
    
    let filtered = window.students.filter(s => {
        let mGrade = (selGrade === 'ALL') || (s.grade === selGrade);
        let mYear = true;
        if(selYear !== 'ALL' && s.enrollDate) {
            mYear = s.enrollDate.startsWith(selYear); 
        }
        return mGrade && mYear;
    });
    
    let boys = 0, girls = 0;
    
    filtered.forEach(s => {
        if(s.gender && s.gender.toLowerCase() === 'male') boys++;
        else if(s.gender && s.gender.toLowerCase() === 'female') girls++;
        
        // 🎯 THE FIX: Bulletproof Ledger & Cache Checking
        if (s.ledger && Array.isArray(s.ledger) && s.ledger.length > 0) {
            let tBilled = 0, tPaid = 0;
            s.ledger.forEach(l => {
                let lType = (l.type || '').toLowerCase().trim();
                if (l.status === 'VOID' || l.status === 'VOIDED') return;
                
                if (lType === 'charge' || lType === 'fee') {
                    tBilled += parseFloat(l.amount) || 0;
                } 
                else if (['payment', 'discount', 'waiver', 'credit', 'overpayment', 'refund'].includes(lType)) {
                    tPaid += parseFloat(l.amount) || 0;
                }
            });
            s.tempBal = tBilled - tPaid; 
        } else {
            // If ledger isn't loaded in memory, trust the database's master balance record
            s.tempBal = parseFloat(s.balanceOwing !== undefined ? s.balanceOwing : s.balance_owing) || 0;
        }
    });
    
    document.getElementById('rosterTitle').innerText = `${selGrade === 'ALL' ? 'Whole School' : selGrade} - Class of ${selYear === 'ALL' ? 'All Years' : selYear}`;
    document.getElementById('rosterStats').innerHTML = `Total Students: <span style="color:#2c3e50; font-weight:bold;">${filtered.length}</span> | Boys: <span style="color:#2980b9; font-weight:bold;">${boys}</span> | Girls: <span style="color:#8e44ad; font-weight:bold;">${girls}</span>`;
    
    const tbody = document.getElementById('rosterTableBody');
    tbody.innerHTML = '';
    
    if(filtered.length === 0) {
        tbody.innerHTML = '<tr><td colspan="4" style="text-align:center; padding:25px; color:#7f8c8d;">No students found for this class/year.</td></tr>';
    } else {
        filtered.sort((a, b) => a.name.localeCompare(b.name)).forEach(s => {
            // Setup default cleared state
            let balColor = '#27ae60';
            let balText = '$0.00';
            let statusBadge = `<span style="background:#d5f5e3; color:#27ae60; padding:4px 8px; border-radius:4px; font-size:11px; font-weight:bold;">Cleared</span>`;

            // Adjust if owing money
            if (s.tempBal > 0.01) {
                balColor = '#e74c3c';
                balText = `$${s.tempBal.toFixed(2)}`;
                statusBadge = `<span style="background:#fadbd8; color:#c0392b; padding:4px 8px; border-radius:4px; font-size:11px; font-weight:bold;">Owing</span>`;
            } 
            // Adjust if student has Advance Credit (Overpayment)
            else if (s.tempBal < -0.01) {
                balColor = '#8e44ad';
                balText = `+$${Math.abs(s.tempBal).toFixed(2)}`;
                statusBadge = `<span style="background:#f4ecf7; color:#8e44ad; padding:4px 8px; border-radius:4px; font-size:11px; font-weight:bold;">Credit</span>`;
            }
                
            tbody.innerHTML += `
                <tr style="border-bottom: 1px solid #ecf0f1; background: #fff;">
                    <td style="padding: 10px;"><strong>${s.name}</strong><br><small style="color:#7f8c8d;">${s.id}</small></td>
                    <td style="padding: 10px; color: #555;">${s.gender || '-'}</td>
                    <td style="padding: 10px; text-align: right; color: ${balColor}; font-weight: bold;">${balText}</td>
                    <td style="padding: 10px; text-align: center;">${statusBadge}</td>
                </tr>
            `;
        });
    }
    
    document.getElementById('rosterPrintArea').style.display = 'block';
    document.getElementById('btnPrintRoster').style.display = 'block';
    
    window.lastRosterHTML = document.getElementById('rosterPrintArea').innerHTML;
};

