window.currentParentStudent = null;
window.currentParentBalance = 0;

window.loginAsParent = async function() {
    if (!navigator.onLine) return alert("⚠️ You are offline. Please connect to the internet to log into the Parent Portal.");

    const inputField = document.getElementById('parentStudentId');
    const phoneField = document.getElementById('parentPhone'); 
    
    const inputId = inputField ? inputField.value.trim().toUpperCase() : '';
    const inputPhone = phoneField ? phoneField.value.trim().replace(/\s/g, '') : '';
    
    if(!inputId) return alert("Please enter a Student ID.");
    if(!inputPhone) return alert("Please enter the registered phone number."); 
    
    const loginModal = document.getElementById('parentLoginModal');
    if (loginModal) loginModal.style.display = 'none';
    
    try {
        const { data: stuData, error: stuErr } = await supabaseClient.from('students').select('*').eq('id', inputId);
        
        if (stuErr || !stuData || stuData.length === 0) {
            const localStudent = window.students ? window.students.find(s => s.id.toUpperCase() === inputId) : null;
            if (!localStudent) {
                if (loginModal) loginModal.style.display = 'flex'; 
                return alert(`❌ Login Failed: Student ID "${inputId}" was not found.`);
            }
            window.currentParentStudent = localStudent;
        } else {
            window.currentParentStudent = stuData[0]; 
        }

        const savedPhone = (window.currentParentStudent.phone || window.currentParentStudent.cell || "").toString().trim().replace(/\s/g, '');
        
        if (savedPhone === "" || savedPhone !== inputPhone) {
            if (loginModal) loginModal.style.display = 'flex'; 
            console.error(`Security Block: Parent typed ${inputPhone}, but system requires ${savedPhone}`);
            return alert("🔒 Access Denied: The phone number does not match the registered parent for this student. Please contact the school.");
        }

        if (!window.currentParentStudent.ledger) window.currentParentStudent.ledger = [];
        if (typeof window.recordVisit === 'function') {
            window.recordVisit(
                window.currentParentStudent.name || window.currentParentStudent.student_name || `Student ${window.currentParentStudent.id}`,
                'Parent',
                'Parent Login',
                `Parent portal login - Student ID ${window.currentParentStudent.id}`
            );
        }

        let cloudSettingsData = null;
        const { data: schoolData, error: sdErr } = await supabaseClient.from('school_data').select('*').eq('id', 'master_settings').maybeSingle();
        if (!sdErr && schoolData && schoolData.settings) cloudSettingsData = schoolData.settings;
        if (cloudSettingsData && window.settings) Object.assign(window.settings, cloudSettingsData);
        
        let tBilled = 0, tPaid = 0;
        window.currentParentStudent.ledger.forEach(l => {
            if(l.type === 'charge') tBilled += parseFloat(l.amount) || 0;
            if(l.type === 'payment') tPaid += parseFloat(l.amount) || 0;
        });
        window.currentParentBalance = tBilled - tPaid;
        
        const safeSchoolName = (window.settings && window.settings.schoolName) ? window.settings.schoolName : "HAVEN ONLINE";
        if (document.getElementById('pdSchoolName')) document.getElementById('pdSchoolName').innerText = safeSchoolName;
        if (document.getElementById('pdStudentName')) document.getElementById('pdStudentName').innerText = window.currentParentStudent.name;
        
        if (document.getElementById('pdStudentId')) {
            const maskedId = "STU-***" + window.currentParentStudent.id.slice(-2);
            document.getElementById('pdStudentId').innerText = maskedId;
        }
        
        if (document.getElementById('pdGrade')) document.getElementById('pdGrade').innerText = window.currentParentStudent.grade || "N/A";
        
        const welcomeBox = document.getElementById('pdWelcomeMessage');
        const balDisplay = document.getElementById('pdBalance');
        
        if (balDisplay && welcomeBox) {
            balDisplay.innerText = "$" + window.currentParentBalance.toFixed(2);
            if (window.currentParentBalance > 0) {
                balDisplay.style.color = "#e74c3c"; 
                welcomeBox.style.background = "#fadbd8";
                welcomeBox.style.color = "#c0392b";
                welcomeBox.style.border = "1px solid #e74c3c";
                welcomeBox.innerHTML = `<strong>👋 Welcome to the Parent Portal!</strong><br>Please note that <b>${window.currentParentStudent.name}</b> currently has an outstanding balance. Kindly review the ledger below.`;
                
                if (document.getElementById('paynowSection')) document.getElementById('paynowSection').style.display = 'block';
                if (document.getElementById('clearedSection')) document.getElementById('clearedSection').style.display = 'none';
            } else {
                balDisplay.style.color = "#27ae60"; 
                welcomeBox.style.background = "#d5f5e3";
                welcomeBox.style.color = "#27ae60";
                welcomeBox.style.border = "1px solid #2ecc71";
                welcomeBox.innerHTML = `<strong>🎉 Welcome back!</strong><br><b>${window.currentParentStudent.name}</b> is fully paid up and cleared. Thank you for your continued support!`;
                
                if (document.getElementById('paynowSection')) document.getElementById('paynowSection').style.display = 'none';
                if (document.getElementById('clearedSection')) document.getElementById('clearedSection').style.display = 'block';
            }
        }
        
        if (document.getElementById('hubSchoolName')) document.getElementById('hubSchoolName').innerText = safeSchoolName;
        if (document.getElementById('parentHubDashboard')) document.getElementById('parentHubDashboard').style.display = 'flex'; 
        
        if (inputField) inputField.value = ''; 
        if (phoneField) phoneField.value = '';

    } catch (err) {
        console.error("Critical error in Parent Login:", err);
        alert("⚠️ Something went wrong trying to load the student profile. Please try again.");
    }
};

window.processPaynowPayment = async function() {
    if (!navigator.onLine) return alert("⚠️ You are offline. Online payments require an active internet connection.");
    if (!window.currentParentStudent || window.currentParentBalance <= 0) {
        return alert("No outstanding balance to pay.");
    }

    try {
        const btn = document.getElementById('btnProcessPayment');
        const originalText = btn.innerText;
        btn.innerText = "Processing...";
        btn.disabled = true;

        const response = await fetch('/.netlify/functions/pay', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ 
                amount: window.currentParentBalance, 
                studentId: window.currentParentStudent.id,
                studentName: window.currentParentStudent.name
            })
        });

        if (!response.ok) throw new Error(`Server error: ${response.status} (Make sure you are on Netlify!)`);

        const data = await response.json();

        if (data.success && data.redirectUrl) {
            window.location.href = data.redirectUrl;
        } else {
            alert("Payment initiation failed: " + (data.error || "Unknown error"));
            btn.innerText = originalText;
            btn.disabled = false;
        }

    } catch (err) {
        console.error("Paynow System Error:", err);
        alert("⚠️ The online payment gateway is currently unreachable. Please try again later or contact the school office.");
        
        const btn = document.getElementById('btnProcessPayment');
        if(btn) {
            btn.innerText = "💳 Pay Fees Online";
            btn.disabled = false;
        }
    }
};

// ==========================================
// 32. SYNC ENGINE, RADAR & OFFLINE QUEUE
// ==========================================

window.refreshCoreDataFromCloud = async function() {
    if (!navigator.onLine) throw new Error('Offline');
    if (!window.supabaseClient) throw new Error('Cloud database is unavailable.');

    const tables = ['students', 'student_ledger', 'payments'];
    const cacheTimes = JSON.parse(localStorage.getItem('haven_core_sync_times') || '{}');
    const nextCacheTimes = { ...cacheTimes };

    const fetchCoreTable = async table => {
        const candidates = table === 'payments'
            ? ['created_at', 'updated_at', 'last_updated']
            : ['updated_at', 'created_at', 'last_updated'];

        for (const timestampColumn of candidates) {
            const since = cacheTimes[table];
            if (!since) break;
            const result = await window.supabaseClient
                .from(table)
                .select('*')
                .gte(timestampColumn, since)
                .order(timestampColumn, { ascending: true })
                .limit(5000);
            if (!result.error) {
                const latest = (result.data || []).reduce((latestValue, row) => {
                    const value = row[timestampColumn];
                    return value && String(value) > String(latestValue || '') ? value : latestValue;
                }, since);
                nextCacheTimes[table] = latest;
                return { data: result.data || [], incremental: true };
            }
        }

        const data = await window.fetchCompleteCloudTable(table);
        nextCacheTimes[table] = new Date().toISOString();
        return { data, incremental: false };
    };

    const results = await Promise.all(tables.map(fetchCoreTable));
    const [studentResult, ledgerResult, paymentResult] = results;
    const studentData = studentResult.incremental
        ? (() => {
            const map = new Map((window.students || []).map(student => [String(student.id), student]));
            studentResult.data.forEach(record => map.set(String(record.id), {
                ...map.get(String(record.id)),
                id: record.id,
                name: record.name,
                grade: record.grade,
                gender: record.gender || '',
                address: record.address || '',
                phone: record.phone || record.cell || '',
                dob: record.dob || '',
                enrollDate: record.enroll_date || record.enrollDate || '',
                paymentDeadline: record.payment_deadline || record.paymentDeadline || '',
                billingPlan: record.billing_plan || record.billingPlan || 'termly',
                balanceOwing: parseFloat(record.balance_owing || record.feesowed || 0),
                transportTier: parseFloat(record.transport_tier) || 0,
                transportMode: record.transport_mode || 'full',
                driver: record.driver || '',
                foodProgram: record.food_program === true || String(record.food_program) === 'true',
                stationeryPack: record.stationery_pack === true || String(record.stationery_pack) === 'true',
                textbooks: record.textbooks === true || String(record.textbooks) === 'true',
                enrollmentStatus: record.status || record.enrollment_status || 'active'
            }));
            return Array.from(map.values());
        })()
        : studentResult.data.map(record => ({
            id: record.id,
            name: record.name,
            grade: record.grade,
            gender: record.gender || '',
            address: record.address || '',
            phone: record.phone || record.cell || '',
            dob: record.dob || '',
            enrollDate: record.enroll_date || record.enrollDate || '',
            paymentDeadline: record.payment_deadline || record.paymentDeadline || '',
            billingPlan: record.billing_plan || record.billingPlan || 'termly',
            balanceOwing: parseFloat(record.balance_owing || record.feesowed || 0),
            transportTier: parseFloat(record.transport_tier) || 0,
            transportMode: record.transport_mode || 'full',
            driver: record.driver || '',
            foodProgram: record.food_program === true || String(record.food_program) === 'true',
            stationeryPack: record.stationery_pack === true || String(record.stationery_pack) === 'true',
            textbooks: record.textbooks === true || String(record.textbooks) === 'true',
            enrollmentStatus: record.status || record.enrollment_status || 'active'
        }));

    const ledgerRows = ledgerResult.incremental
        ? (() => {
            const map = new Map((window.__coreLedgerCache || []).map(row => [String(row.id), row]));
            ledgerResult.data.forEach(row => map.set(String(row.id), row));
            return Array.from(map.values());
        })()
        : ledgerResult.data;

    const ledgersByStudent = new Map();
    ledgerRows.forEach(entry => {
        const studentKey = String(entry.student_id || '');
        if (!ledgersByStudent.has(studentKey)) ledgersByStudent.set(studentKey, []);
        ledgersByStudent.get(studentKey).push(entry);
    });
    window.students = studentData.map(student => ({
        ...student,
        ledger: ledgersByStudent.get(String(student.id)) || student.ledger || []
    }));
    window.__coreLedgerCache = ledgerRows;
    window.payments = paymentResult.incremental
        ? [...(window.payments || []), ...paymentResult.data].filter((row, index, rows) =>
            rows.findIndex(item => String(item.id) === String(row.id)) === index)
        : paymentResult.data;

    localStorage.setItem('haven_core_sync_times', JSON.stringify(nextCacheTimes));
    localStorage.setItem('haven_cached_student_ledger', JSON.stringify(ledgerRows));
    localStorage.setItem('haven_cached_payments', JSON.stringify(window.payments));
    localStorage.setItem('haven_cached_students', JSON.stringify(window.students.map(student => ({
        id: student.id, name: student.name, grade: student.grade, gender: student.gender,
        address: student.address, phone: student.phone, dob: student.dob, enrollDate: student.enrollDate,
        paymentDeadline: student.paymentDeadline, billingPlan: student.billingPlan,
        balanceOwing: student.balanceOwing, transportTier: student.transportTier,
        transportMode: student.transportMode, driver: student.driver,
        foodProgram: student.foodProgram, stationeryPack: student.stationeryPack,
        textbooks: student.textbooks, enrollmentStatus: student.enrollmentStatus
    }))));
    window.appDataReady = true;
};

window.syncWithCloud = async function() {
    if (window.syncInProgress) return;
    if (typeof window.updateSchoolDisplay === 'function') window.updateSchoolDisplay();

    const dashTotal = document.getElementById('dashTotalStudents');
    if(dashTotal) dashTotal.innerText = window.students.length;
    console.log("Manual cloud refresh triggered...");
    const syncBtnBox = document.getElementById('mainSyncBtn');
    const syncText = document.getElementById('refreshText'); 

    if (!navigator.onLine) return alert("⚠️ You are offline. Cannot sync with the cloud right now.");

    window.syncInProgress = true;
    if (syncBtnBox) syncBtnBox.disabled = true;
    if (syncText) syncText.innerText = "Checking updates...";

    try {
        await window.refreshCoreDataFromCloud();

        if (typeof window.updateStudentTable === 'function') window.updateStudentTable();
        if (typeof window.updateDashboard === 'function') window.updateDashboard();
        if (typeof window.refreshLedgerView === 'function') window.refreshLedgerView();
        if (typeof window.calculateDailyActivityStats === 'function') window.calculateDailyActivityStats();
        if (typeof window.calculateVaultStats === 'function') window.calculateVaultStats();
        
        if (syncBtnBox && syncText) {
            syncBtnBox.style.backgroundColor = "#27ae60"; 
            syncText.innerText = "Refresh Complete"; 
            setTimeout(() => {
                syncBtnBox.style.backgroundColor = "#3498db"; 
                syncText.innerText = "Refresh Cloud"; 
            }, 3000);
        }
        console.log("✅ System Updated with latest Cloud Data!");

        // Secondary sections update independently so they cannot delay core data or payments.
        Promise.resolve().then(async () => {
            const refreshTasks = [
                window.loadPreStudents,
                window.calculateReconciliation,
                window.populateEventHistory,
                window.renderEcoCashTable,
                window.renderInventory,
                window.renderExpenses
            ].filter(task => typeof task === 'function');
            await Promise.allSettled(refreshTasks.map(task => task()));
        });

    } catch (err) {
        console.error("Sync crashed:", err);
        alert("⚠️ Sync failed. Check your internet connection.");
        if (syncBtnBox) syncBtnBox.style.backgroundColor = "#3498db";
        if (syncText) syncText.innerText = "Refresh Cloud";
    } finally {
        window.syncInProgress = false;
        if (syncBtnBox) syncBtnBox.disabled = false;
    }
};

