window.addToSyncQueue = function(tableName, dataPayload) {
    let queue = JSON.parse(localStorage.getItem('havenOfflineQueue') || '[]');
    queue.push({ table: tableName, data: dataPayload, time: new Date().toISOString() });
    localStorage.setItem('havenOfflineQueue', JSON.stringify(queue));
    console.log(`📦 Saved to Waiting Room. Items in queue: ${queue.length}`);
};

window.processSyncQueue = async function() {
    let queue = JSON.parse(localStorage.getItem('havenOfflineQueue') || '[]');
    if (queue.length === 0) return; 

    console.log(`🚀 Network found! Shooting ${queue.length} queued items to the cloud...`);
    let remainingQueue = [];

    for (let item of queue) {
        const { error } = await supabaseClient.from(item.table).upsert(item.data);
        if (error) {
            console.error("⚠️ Cloud save failed for item, keeping in queue:", error);
            remainingQueue.push(item); 
        }
    }

    localStorage.setItem('havenOfflineQueue', JSON.stringify(remainingQueue));
    if (remainingQueue.length === 0 && queue.length > 0) {
        console.log("✅ Connection Restored: All offline changes have been automatically synced to the cloud!");
    }
};

