window.isDateInPeriod = function(dateString, period, customStart = null, customEnd = null) {
    if (!dateString || period === 'all') return true;

    const targetDate = new Date(dateString);
    const today = new Date();

    targetDate.setHours(0, 0, 0, 0);
    const todayStart = new Date(today.getFullYear(), today.getMonth(), today.getDate());

    if (period === 'daily' || period === 'today') {
        return targetDate.getTime() === todayStart.getTime();
    } 
    else if (period === 'weekly' || period === 'week') {
        const sevenDaysAgo = new Date(todayStart);
        sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
        return targetDate >= sevenDaysAgo && targetDate <= todayStart;
    } 
    else if (period === 'monthly' || period === 'month') {
        return targetDate.getMonth() === today.getMonth() && targetDate.getFullYear() === today.getFullYear();
    } 
    else if (period === 'yearly' || period === 'year') {
        return targetDate.getFullYear() === today.getFullYear();
    } 
    else if (period === 'termly') {
        const currentMonth = today.getMonth();
        const targetMonth = targetDate.getMonth();
        const currentTerm = Math.floor(currentMonth / 4);
        const targetTerm = Math.floor(targetMonth / 4);
        return currentTerm === targetTerm && targetDate.getFullYear() === today.getFullYear();
    }
    else if (period === 'custom') {
        if (!customStart && !customEnd) return true; 

        let isAfterStart = true;
        let isBeforeEnd = true;

        if (customStart) {
            const start = new Date(customStart);
            start.setHours(0, 0, 0, 0);
            isAfterStart = targetDate >= start;
        }
        if (customEnd) {
            const end = new Date(customEnd);
            end.setHours(23, 59, 59, 999); 
            isBeforeEnd = targetDate <= end;
        }
        return isAfterStart && isBeforeEnd;
    }
    return true; 
};

