window.saveShopItem = async function() {
    const idField = document.getElementById('shopItemId').value;
    const name = document.getElementById('shopItemName').value.trim();
    const price = parseFloat(document.getElementById('shopItemPrice').value) || 0;
    const qty = parseInt(document.getElementById('shopItemQty').value) || 0;
    const costprice = parseFloat(document.getElementById('shopItemCost').value) || 0;

    if (!name) return alert("Item name is required!");

    const itemData = {
        id: idField || 'INV-' + Date.now(),
        name: name,
        price: price,
        qty: qty,
        costprice: costprice 
    };

    if (!window.inventory) window.inventory = [];
    
    // Check if we are updating an existing item or adding a new one
    if (idField) {
        const index = window.inventory.findIndex(i => i.id === idField);
        if (index !== -1) window.inventory[index] = { ...window.inventory[index], ...itemData };
    } else {
        window.inventory.push(itemData);
    }

    try {
        const { error } = await window.supabase.from('inventory').upsert(itemData);
        if (error) throw error;
        alert(idField ? "✅ Item updated successfully!" : "✅ Item added to inventory!");
    } catch (err) {
        console.error("Inventory Save Error:", err);
        alert("⚠️ Saved locally, but failed to reach the Cloud: " + err.message);
    }

    if (typeof window.renderInventory === 'function') window.renderInventory();
    resetShopForm();
};



window.deleteShopItem = async function(id) {
    // 🛑 THE FIX: Check the .role string
    if (!window.currentUser || window.currentUser.role !== 'Level 3') {
        return alert("⛔ Access Denied: Only Level 3 users can delete shop items.");
    }

    if(!confirm("Are you sure you want to completely delete this item from inventory?")) return;
    
    window.inventory = (window.inventory || []).filter(i => i.id !== id);
    
    try {
        await window.supabase.from('inventory').delete().eq('id', id);
    } catch(e) {
        console.error("Delete Error:", e);
    }
    
    if (typeof window.renderInventory === 'function') window.renderInventory();
};


window.editShopItem = function(itemId) {
    // 🛑 THE FIX: Check the .role string
    if (!window.currentUser || window.currentUser.role !== 'Level 3') {
        return alert("⛔ Access Denied: Only Level 3 users can edit shop items.");
    }

    const invList = window.getShopInventoryList();
    const item = invList.find(i => String(i.id) === String(itemId));
    
    if (!item) {
        return alert("Item not found!");
    }

    const nameEl = document.getElementById('shopItemName');
    const priceEl = document.getElementById('shopItemPrice');
    const costEl = document.getElementById('shopItemCost');
    const qtyEl = document.getElementById('shopItemQty');
    const descriptionEl = document.getElementById('shopItemDescription');
    const lowStockEl = document.getElementById('shopItemLowStock');
    const addBtn = document.getElementById('addStockBtn');
    const cancelBtn = document.getElementById('cancelEditBtn');

    if (nameEl) {
        nameEl.value = item.name || '';
        nameEl.dataset.editingId = itemId; 
    }
    if (priceEl) priceEl.value = item.price || 0;
    if (costEl) costEl.value = item.costprice || item.cost || 0;
    if (qtyEl) qtyEl.value = item.qty || 0;
    if (descriptionEl) descriptionEl.value = item.description || '';
    if (lowStockEl) lowStockEl.value = item.low_stock_threshold ?? 5;

    if (addBtn) {
        addBtn.innerHTML = "💾 Update Item";
        addBtn.classList.remove('btn-warning');
        addBtn.classList.add('btn-primary');
    }
    if (cancelBtn) {
        cancelBtn.style.display = 'block';
    }
};



window.calculateShopBalance = async function() {
    if (!window.supabaseClient) return alert("⚠️ Database connection required for live shop calculation.");
    
    let shopRevenue = 0;
    let shopCosts = 0;
    let goodsSold = 0;

    const periodDropdown = document.getElementById('shopReportPeriod');
    // Default to 'all' if the dropdown doesn't exist yet
    let period = periodDropdown ? periodDropdown.value : 'all'; 

    let customStart = null, customEnd = null;
    if (period === 'custom') {
        customStart = document.getElementById('shopStartDate') ? document.getElementById('shopStartDate').value : null;
        customEnd = document.getElementById('shopEndDate') ? document.getElementById('shopEndDate').value : null;
    }

    const reportTableBody = document.getElementById('shopReportTableBody');
    if (reportTableBody) reportTableBody.innerHTML = ''; 

    // 🗓️ BULLETPROOF DATE HANDLER (Fixes timezone drift)
    const now = new Date();
    const todayStr = now.toLocaleDateString('en-CA'); // Forces exact YYYY-MM-DD
    const thisMonthStr = todayStr.substring(0, 7); 
    
    const startOfWeek = new Date(now);
    startOfWeek.setDate(now.getDate() - now.getDay());
    const weekStartStr = startOfWeek.toLocaleDateString('en-CA');

    // 🛑 BASELINE DATE: Locks default tracking to 2026-09-21 onwards as requested
    const BASELINE_DATE = '2026-09-21';

    let dateStartStr = todayStr;
    let dateEndStr = todayStr;

    if (period === 'all') {
        dateStartStr = BASELINE_DATE;
        dateEndStr = '2099-12-31'; // Safe infinite future date
    } else if (period === 'month') {
        dateStartStr = `${thisMonthStr}-01`;
        dateEndStr = `${thisMonthStr}-31`;
    } else if (period === 'week') {
        dateStartStr = weekStartStr;
        dateEndStr = todayStr;
    } else if (period === 'custom') {
        if (!customStart || !customEnd) {
            // If they picked custom but haven't selected dates, fallback safely to baseline
            dateStartStr = BASELINE_DATE;
            dateEndStr = '2099-12-31';
        } else {
            dateStartStr = customStart;
            dateEndStr = customEnd;
        }
    } else if (period === 'today') {
        dateStartStr = todayStr;
        dateEndStr = todayStr;
    }

    // Timestamp formatting required for pre_enrollment_receipts
    const startOfDay = `${dateStartStr}T00:00:00.000Z`;
    const endOfDay = `${dateEndStr}T23:59:59.999Z`;

    document.body.style.cursor = 'wait'; // Show loading state

    try {
        // 1. Fetch Live True Inventory
        const { data: invData, error: invErr } = await window.supabaseClient
            .from('inventory')
            .select('*');
        
        if (invErr) throw new Error("Inventory fetch error: " + invErr.message);
        const inventoryList = invData || [];

        // 2. Fetch Today's Shop Payments (Standard Students)
        const { data: paymentsData, error: payErr } = await window.supabaseClient
            .from('payments')
            .select('*')
            .eq('category', 'Shop')
            .gte('date', dateStartStr)
            .lte('date', dateEndStr)
            .neq('status', 'VOID')
            .neq('status', 'VOIDED');

        // 3. Fetch Today's Pre-Enrollment Receipts (Next Year Students)
        const { data: preData, error: preErr } = await window.supabaseClient
            .from('pre_enrollment_receipts')
            .select('*')
            .eq('category', 'Uniforms')
            .gte('created_at', startOfDay)
            .lte('created_at', endOfDay)
            .neq('status', 'VOID')
            .neq('status', 'VOIDED');

        if (payErr) console.warn("Payments fetch error:", payErr);
        if (preErr) console.warn("Pre-enrollment fetch error:", preErr);

        // Merge standard payments and pre-enrollment receipts into one array
        const allShopData = [
            ...(paymentsData || []),
            ...(preData || [])
        ];

        // Deduplicate records to ensure no double-counting
        const processedReceipts = new Set();
        let finalDeduplicatedData = [];

        // Sort oldest to newest for chronological table display
        allShopData.sort((a, b) => {
            let da = a.date || (a.created_at || '').split('T')[0];
            let db = b.date || (b.created_at || '').split('T')[0];
            return new Date(da) - new Date(db);
        });

        allShopData.forEach(p => {
            let receiptCheck = p.receipt_no || p.id;
            if (processedReceipts.has(receiptCheck)) return;
            
            finalDeduplicatedData.push({
                id: p.id,
                date: p.date || (p.created_at ? p.created_at.split('T')[0] : null),
                receipt_no: p.receipt_no,
                student_id: p.student_id || p.pre_student_id,
                student_name: p.student_name || p.student_id || p.pre_student_id,
                amount: p.amount,
                description: p.notes || p.description || 'Shop Purchase',
                breakdown: p.breakdown || null,
                qty: p.qty || 0,
                costprice: p.costprice || p.cost || 0
            });
            
            processedReceipts.add(receiptCheck);
        });

        // 4. CALCULATE TOTALS WITH PRECISE INVENTORY COST MATCHING
        finalDeduplicatedData.forEach(t => {
            const cleanNum = (val) => parseFloat(String(val).replace(/[^0-9.-]+/g, "")) || 0;

            let saleAmount = cleanNum(t.amount);
            let qty = parseInt(t.qty) || 0;
            let costPrice = cleanNum(t.costprice) || 0;

            let rawDescription = t.description || 'Shop Item';
            let itemsBought = rawDescription;
            if (rawDescription.includes("Sale to ")) {
                let parts = rawDescription.split(": ");
                itemsBought = parts[1] || rawDescription;        
            }

            // If structured qty or cost is missing, parse text safely for multiple or single items
            if (qty === 0 || costPrice === 0) {
                qty = 0;
                costPrice = 0;
                let searchDesc = (rawDescription + " " + (typeof t.breakdown === 'string' ? t.breakdown : JSON.stringify(t.breakdown || ''))).toLowerCase();
                
                let foundMatch = false;

                // Sort inventory items by name length (longest first) to prevent partial word overlaps
                let sortedInventory = [...inventoryList].sort((a, b) => (b.name || '').length - (a.name || '').length);

                for (let invItem of sortedInventory) {
                    if (!invItem.name) continue; 
                    let itemNameLower = String(invItem.name).toLowerCase().trim();
                    if (searchDesc.includes(itemNameLower)) {
                        let regex = new RegExp(`(\\d+)x\\s+${itemNameLower.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`, 'i');
                        let match = searchDesc.match(regex);
                        
                        // If exact count like "1x dress" isn't matched, count occurrences or default to 1
                        let q = match ? parseInt(match[1]) : (searchDesc.split(itemNameLower).length - 1);
                        if (q <= 0) q = 1;
                        
                        qty += q;
                        costPrice += (parseFloat(invItem.costprice) || parseFloat(invItem.cost) || 0) * q;
                        
                        foundMatch = true;
                        
                        // Temporarily replace found item name in search string so it isn't matched twice accidentally
                        searchDesc = searchDesc.replace(new RegExp(itemNameLower, 'g'), '');
                    }
                }

                // Fallback if text couldn't match any known inventory item name
                if (!foundMatch) {
                    qty = 1;
                    costPrice = saleAmount * 0.5; // Safe fallback cost ratio
                }
            }

            const itemProfit = saleAmount - costPrice;

            shopRevenue += saleAmount;
            shopCosts += costPrice;
            goodsSold += qty;

            if (reportTableBody) {
                let niceDate = t.date ? String(t.date).split(' ')[0].split('T')[0] : 'Unknown';
                
                // 🎯 FIX: Cross-reference the ID to fetch the real student name
                let realName = t.student_name;
                if ((!realName || realName === t.student_id) && t.student_id) {
                    const foundStudent = (window.students || []).find(s => s.id === t.student_id);
                    if (foundStudent) realName = foundStudent.name;
                }
                
                // 🎯 Format nicely as: Name (ID)
                let customerDisplay = "Walk-in";
                if (realName && t.student_id && realName !== t.student_id) {
                    customerDisplay = `${realName}<br><small style="color: #7f8c8d;">${t.student_id}</small>`;
                } else if (realName) {
                    customerDisplay = realName;
                } else if (t.student_id) {
                    customerDisplay = t.student_id;
                }

                const row = `
                <tr style="border-bottom: 1px solid #ecf0f1; background: #fff;">
                    <td style="padding: 10px;">${niceDate}</td>
                    <td style="padding: 10px; font-weight: bold; color: #8e44ad;">${customerDisplay}</td> 
                    <td style="padding: 10px; color: #555;">${itemsBought}</td> 
                    <td style="padding: 10px; text-align: center;">${qty}</td>
                    <td style="padding: 10px; color: #c0392b; text-align: right;">$${costPrice.toFixed(2)}</td>
                    <td style="padding: 10px; color: #2980b9; text-align: right;">$${saleAmount.toFixed(2)}</td>
                    <td style="padding: 10px; font-weight: bold; text-align: right; color: ${itemProfit >= 0 ? '#27ae60' : '#c0392b'};">
                        $${itemProfit.toFixed(2)}
                    </td>
                </tr>`;
                reportTableBody.insertAdjacentHTML('beforeend', row);
            }
        });

        // 5. Update UI Dashboard Boxes
        const netProfit = shopRevenue - shopCosts;
        
        // Calculate Total Items Left in Stock from your Inventory table data
        const stockUnits = inventoryList.reduce((total, item) => {
            let q = parseInt(item.qty) || 0;
            return q > 0 ? total + q : total;
        }, 0);
        
        // Calculate Value of Goods Left based on true Cost Price
        const stockValue = inventoryList.reduce((total, item) => {
            let trueCost = parseFloat(item.costprice) || parseFloat(item.cost) || 0;
            let q = parseInt(item.qty) || 0;
            return q > 0 ? total + (q * trueCost) : total;
        }, 0);
        
        const revBox = document.getElementById('shopTotalRevenue');
        const costBox = document.getElementById('shopTotalCosts');
        const profitBox = document.getElementById('shopNetProfit');
        const stockUnitsBox = document.getElementById('shopStockUnits');
        const goodsSoldBox = document.getElementById('shopGoodsSold');
        const goodsProfitBox = document.getElementById('shopGoodsProfit');
        const stockValueBox = document.getElementById('shopStockValue');

        if (revBox) revBox.innerText = `$${shopRevenue.toFixed(2)}`;
        if (costBox) costBox.innerText = `$${shopCosts.toFixed(2)}`;
        if (profitBox) profitBox.innerText = `$${netProfit.toFixed(2)}`;
        if (goodsSoldBox) goodsSoldBox.innerText = goodsSold.toLocaleString();
        if (goodsProfitBox) goodsProfitBox.innerText = `$${netProfit.toFixed(2)}`;
        
        if (stockUnitsBox) stockUnitsBox.innerText = stockUnits.toLocaleString();
        if (stockValueBox) stockValueBox.innerText = `$${stockValue.toFixed(2)}`;

    } catch (error) {
        console.error("Calculate Shop Balance Error:", error);
        alert("❌ Failed to calculate shop balance: " + error.message);
    } finally {
        document.body.style.cursor = 'default';
    }
};

window.viewItemHistory = function(itemId) {
    const item = (window.inventory || window.shopInventory || []).find(i => i.id === itemId);
    if (!item) return alert("Item not found");

    // 🎯 FIX 1: Look in ALL possible memory arrays so Inspect sees the exact same data as the Dashboard
    const salesData = [
        ...(window.payments || []),
        ...(window.pre_enrollment_receipts || []),
        ...(window.preEnrollments || []), 
        ...(window.transactions || []),
        ...(window.student_ledger || []),
        ...(window.studentLedger || [])
    ];
    const transactionReceiptKeys = new Set((window.transactions || [])
        .map(transaction => String(transaction.receipt_no || transaction.receiptNo || '').trim().toLowerCase())
        .filter(Boolean));
    
    let startDate = document.getElementById('shopStartDate')?.value || null;
    let endDate = document.getElementById('shopEndDate')?.value || null;
    const periodSelect = document.getElementById('shopReportPeriod')?.value;
    
    if (periodSelect === 'all') { 
        startDate = null; 
        endDate = null; 
    }

    const price = parseFloat(item.price) || 0;
    const cost = parseFloat(item.costprice) || parseFloat(item.cost) || 0; 
    const realTimeQty = parseInt(item.qty) || 0;

    let soldDuringPeriod = 0;
    let soldAfterPeriod = 0;
    let historyRows = [];

    const currentItemId = String(item.id || '').trim();
    const itemNameLower = String(item.name || '').toLowerCase().trim();

    salesData.forEach(sale => {
        if (sale.status === 'VOID' || sale.status === 'VOIDED') return;
        const saleReceiptKey = String(sale.receipt_no || sale.receiptNo || '').trim().toLowerCase();
        if (sale.type !== 'Shop Sale' && saleReceiptKey && transactionReceiptKeys.has(saleReceiptKey) &&
            (sale.pre_student_id || String(sale.category || '').toLowerCase() === 'shop')) return;
        if (sale.pre_student_id && !hasPreEnrollmentUniformCharge(sale)) return;
        
        // 🎯 FIX 2: Check for created_at if date is missing (crucial for pre-enrollment receipts)
        const rawDate = sale.date || sale.created_at || sale.payment_date || '';
        const saleDate = String(rawDate).split('T')[0];
        
        if (!saleDate || saleDate === 'undefined') return;

        let qtyInThisSale = 0;
        let searchDesc = String(sale.description || sale.notes || sale.desc || '').toLowerCase();

        // 🎯 FIX 3: Prevent double-counting the charge AND the payment from the ledger
        if (sale.type === 'payment' && searchDesc.includes('shop payment')) return;

        // ========================================================
        // METHOD 1: Text search matching new ledger format
        // ========================================================
        if (searchDesc.includes(itemNameLower)) {
            let regex = new RegExp(`(\\d+)x\\s+${itemNameLower.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`, 'i');
            let match = searchDesc.match(regex);
            
            qtyInThisSale = match ? parseInt(match[1]) : (searchDesc.split(itemNameLower).length - 1);
            if (qtyInThisSale <= 0) qtyInThisSale = 1;
        } 
        // ========================================================
        // METHOD 2: Fallback for older data using cartdetails
        // ========================================================
        else if (sale.cartdetails) {
            let cart = [];
            if (typeof sale.cartdetails === 'string') {
                try { cart = JSON.parse(sale.cartdetails); } catch(e){}
            } else if (Array.isArray(sale.cartdetails)) {
                cart = sale.cartdetails;
            } else {
                cart = [sale.cartdetails]; 
            }

            cart.forEach(cartItem => {
                const cartItemNameLower = String(cartItem.name || '').toLowerCase().trim();
                if (cartItem.id === item.id || cartItemNameLower.includes(itemNameLower) || itemNameLower.includes(cartItemNameLower)) {
                    qtyInThisSale += parseInt(cartItem.cartQty || cartItem.qty || 1);
                }
            });
        }

        // ========================================================
        // RECORD THE SALE IF QUANTITY FOUND
        // ========================================================
        if (qtyInThisSale > 0) {
            const amtPaid = qtyInThisSale * price; 

            if (endDate && saleDate > endDate) {
                soldAfterPeriod += qtyInThisSale;
            } 
            else if ((!startDate || saleDate >= startDate) && (!endDate || saleDate <= endDate)) {
                soldDuringPeriod += qtyInThisSale;
                
                // Extract receipt number safely
                const receiptNum = sale.receipt_no || (sale.id ? String(sale.id).replace('CHG-', '') : '-');

                historyRows.push({
                    date: saleDate,
                    customer: sale.student_name || sale.student_id || 'Walk-in',
                    qty: qtyInThisSale,
                    total: amtPaid,
                    receipt: receiptNum
                });
            }
        }
    });

    // 🕰️ TIME MACHINE MATH (Same as render function)
    const closingStock = realTimeQty + soldAfterPeriod;
    const openingStock = closingStock + soldDuringPeriod;

    document.getElementById('inspectItemTitle').innerText = `🔍 Audit: ${item.name}`;
    document.getElementById('inspectInitialQty').innerText = openingStock;
    document.getElementById('inspectInitialCost').innerText = `Cost: $${(openingStock * cost).toFixed(2)}`;
    
    document.getElementById('inspectSoldQty').innerText = soldDuringPeriod;
    document.getElementById('inspectRevenue').innerText = `Sales: $${(soldDuringPeriod * price).toFixed(2)}`;
    
    document.getElementById('inspectCurrentQty').innerText = closingStock;
    document.getElementById('inspectStockValue').innerText = `Value: $${(closingStock * cost).toFixed(2)}`;

    const tbody = document.getElementById('inspectHistoryTableBody');
    if (historyRows.length === 0) {
        tbody.innerHTML = '<tr><td colspan="4" style="text-align: center; padding: 15px; color: #95a5a6;">No sales found for this item in the selected period.</td></tr>';
    } else {
        historyRows.sort((a,b) => new Date(b.date) - new Date(a.date));
        tbody.innerHTML = historyRows.map(r => `
            <tr style="border-bottom: 1px solid #ecf0f1;">
                <td style="padding: 8px;">${r.date}</td>
                <td style="padding: 8px;">${r.customer} <br><small style="color:#7f8c8d;">${r.receipt}</small></td>
                <td style="padding: 8px; text-align: center; font-weight: bold;">${r.qty}</td>
                <td style="padding: 8px; text-align: right; color: #27ae60; font-weight: bold;">$${r.total.toFixed(2)}</td>
            </tr>
        `).join('');
    }

    document.getElementById('itemInspectorModal').style.display = 'flex';
};



// ==========================================
// 📁 BULK CSV ENROLLMENT ENGINE (PRODUCTION SAFE)
// ==========================================
window.handleCSVUpload = async function(event) {
    const file = event.target.files[0];
    if (!file) return;

    const reader = new FileReader();

    reader.onload = async (e) => {
        const text = e.target.result;
        
        // Parse the CSV text into rows
        const rows = text.split('\n').filter(row => row.trim() !== ''); 
        if (rows.length < 2) {
            return alert("⚠️ The CSV file appears to be empty or missing headers.");
        }
        
        // Extract headers from the first row and clean them up
        const headers = rows[0].split(',').map(h => h.trim().toLowerCase());

        const newEnrollments = [];

        // Loop through the data rows (starting at index 1 to skip headers)
        for (let i = 1; i < rows.length; i++) {
            const currentRow = rows[i].split(',').map(val => val.trim());
            
            // Skip malformed rows
            if (currentRow.length !== headers.length) continue; 

            let studentRecord = {};
            
            // Dynamically map the CSV data to the exact header names
            headers.forEach((header, index) => {
                studentRecord[header] = currentRow[index];
            });

            // Enforce schema safety rules for the 'students' table
            studentRecord.id = studentRecord.id || ("STU-" + Math.floor(1000 + Math.random() * 9000));
            studentRecord.enrollment_status = studentRecord.enrollment_status || 'active'; 
            studentRecord.enroll_date = studentRecord.enroll_date || new Date().toISOString().split('T')[0];
            studentRecord.balance_owing = parseFloat(studentRecord.balance_owing || studentRecord.balance || 0);

            newEnrollments.push(studentRecord);
        }

        if (newEnrollments.length === 0) {
            return alert("❌ No valid student rows found in CSV. Check column headers and formatting.");
        }

        try {
            // 🛡️ Use supabaseClient (matches the rest of your app architecture)
            if (typeof supabaseClient === 'undefined') {
                throw new Error("Supabase client is not initialized.");
            }

            const { data, error } = await supabaseClient
                .from('students')
                .insert(newEnrollments)
                .select();

            if (error) throw error;

            console.log(`Successfully enrolled ${newEnrollments.length} students at once!`, data);
            
            // Update local memory cache instantly so UI reflects changes without a full page reload
            window.students = window.students || [];
            window.students = window.students.concat(data);
            
            if (typeof window.renderDirectory === 'function') window.renderDirectory();
            if (typeof window.updateDashboard === 'function') window.updateDashboard();

            alert(`✅ Bulk enrollment complete! Successfully added ${newEnrollments.length} students.`);

        } catch (err) {
            console.error("Database error during bulk upload:", err);
            alert("❌ Upload failed: " + (err.message || "Check the console for details."));
        } finally {
            // Clear input file cache so the same file can be re-uploaded if needed
            event.target.value = ''; 
        }
    };

    reader.readAsText(file);
};

// Auto-attach the listener to your input element if it exists on the page
document.getElementById('csvUploader')?.addEventListener('change', window.handleCSVUpload);

