window.deleteAnnouncement = async function(id) {
    // 1. Role Authorization Check
    const role = window.currentUser?.role || "";
    if (!(role.includes('Level 2') || role.includes('Level 3') || role === 'Admin' || role === 'Chief Admin')) {
        return alert("❌ Access Denied: Only Admins can delete school-wide announcements.");
    }

    if(confirm("Delete this announcement?")) {
        try {
            // 2. Delete directly from Supabase
            const { error } = await window.supabaseClient
                .from('announcements')
                .delete()
                .eq('id', id);

            if (error) throw error;

            // 3. Force a fresh pull from the database
            if (typeof window.renderAdminAnnouncements === 'function') {
                window.renderAdminAnnouncements();
            }
        } catch (err) {
            console.error("Delete Error:", err);
            alert("⚠️ Failed to delete announcement from the database.");
        }
    }
};

window.postAnnouncement = async function() {
    // 1. Role Authorization Check
    const role = window.currentUser?.role || "";
    if (!(role.includes('Level 2') || role.includes('Level 3') || role === 'Admin' || role === 'Chief Admin')) {
        return alert("❌ Access Denied: Only Admins can post school-wide announcements.");
    }

    // 2. Extract Data from DOM
    const title = document.getElementById('announceTitle').value.trim();
    const date = document.getElementById('announceDate').value;
    const type = document.getElementById('announceType').value;
    const desc = document.getElementById('announceDesc').value.trim();

    // 🎯 Safely read cost for Trips/Events
    const amount = parseFloat(document.getElementById('announceAmount')?.value) || 0; 

    // 3. Validation
    if(!title || !date || !desc) {
        return alert("⚠️ Please fill out the Title, Date, and Details.");
    }

    // 4. Construct the Data Object for Supabase
    const newEvent = {
        id: 'EVT-' + Date.now(),
        title: title,
        date: date,
        type: type,
        desc: desc, 
        amount: amount, 
        posted: new Date().toISOString()
    };

    try {
        // 5. Save directly to the Cloud (Supabase)
        const { error } = await window.supabaseClient
            .from('announcements')
            .insert([newEvent]);

        if (error) throw error;

        // 6. Reset Form Fields
        document.getElementById('announceTitle').value = '';
        document.getElementById('announceDesc').value = '';
        if (document.getElementById('announceAmount')) document.getElementById('announceAmount').value = '';

        // 7. Refresh the UI in the background (Without switching screens!)
        if (typeof window.renderAdminAnnouncements === 'function') {
            window.renderAdminAnnouncements(); // Updates your admin list visually
        }
        
        // This safely updates the parent list in the background so it's ready for them, 
        // without physically dragging you to their screen.
        if (typeof window.renderAnnouncements === 'function') {
            window.renderAnnouncements(); 
        }

        alert("✅ Announcement Published to Parent Portal!");

    } catch (err) {
        console.error("Post Error:", err);
        alert("⚠️ Failed to publish announcement to the database.");
    }
};

window.renderAdminAnnouncements = async function() {
    const list = document.getElementById('adminAnnouncementList');
    if (!list) return;
    
    // Clear the list while loading
    list.innerHTML = '<em style="color:#7f8c8d;">Loading announcements...</em>';

    try {
        // 1. Fetch fresh data directly from the Supabase cloud
        const { data, error } = await window.supabaseClient
            .from('announcements')
            .select('*')
            .order('posted', { ascending: false });

        if (error) throw error;

        // 2. Handle Empty State (No announcements in the database yet)
        if (!data || data.length === 0) {
            list.innerHTML = '<em style="color:#7f8c8d;">No active announcements.</em>';
            return;
        }

        // 3. Loop through the cloud data and apply your beautiful custom UI
        let html = '';
        data.forEach(a => {
            html += `
                <div style="background: #f8f9fa; border: 1px solid #bdc3c7; padding: 15px; border-radius: 5px; margin-bottom: 10px;">
                    <div style="display:flex; justify-content:space-between; align-items:flex-start;">
                        <div>
                            <strong style="color:#2980b9; font-size:16px;">${a.title}</strong>
                            <div style="font-size:12px; color:#e67e22; font-weight:bold; margin-top:3px;">${a.type} | Date: ${a.date}</div>
                        </div>
                        <button class="btn-standard btn-danger admin-only" onclick="deleteAnnouncement('${a.id}')" style="padding:6px 12px; font-size:11px;">🗑️ Del</button>
                    </div>
                    <p style="font-size:13px; color:#555; margin-top:8px;">${a.desc}</p>
                </div>
            `;
        });

        // 4. Inject the HTML into the screen
        list.innerHTML = html;

    } catch (err) {
        console.error("Failed to render announcements:", err);
        list.innerHTML = '<em style="color:#c0392b;">Error loading announcements. Please refresh.</em>';
    }
};
