// 39. UNIFIED PREVIEW STUDENT BALANCE FUNCTION
// ==========================================
window.previewStudentBalance = async function() {
    const searchInput = document.getElementById('payId');
    const previewBox = document.getElementById('paymentBalancePreview');
    const quickFeesContainer = document.getElementById('quickFeesContainer');
    const quickFeesButtons = document.getElementById('quickFeesButtons');
    const breakdownList = document.getElementById('payBreakdownList');

    const rateInput = document.getElementById('zigRate');
    const waiveSelect = document.getElementById('waiveFeeSelect'); 

    if (!searchInput || !previewBox) return;

    const rawInput = searchInput.value.trim();
    if (rawInput === "") {
        previewBox.style.display = 'none';
        if (quickFeesContainer) quickFeesContainer.style.display = 'none';
        if (waiveSelect) waiveSelect.innerHTML = '<option value="">Select fee to waive...</option>';
        if (breakdownList) breakdownList.innerHTML = '';
        return;
    }

    // 1. INTELLIGENTLY EXTRACT ID OR NAME
    let searchTerm = rawInput;
    let searchColumn = 'name'; 

    if (rawInput.includes('(') && rawInput.includes(')')) {
        searchTerm = rawInput.split('(')[1].split(')')[0].trim();
        searchColumn = 'id';
    } 
    else if (rawInput.toUpperCase().startsWith('STU-')) {
        searchColumn = 'id'; 
    }

    const rate = rateInput ? (parseFloat(rateInput.value) || 1) : 1;

    if (searchColumn === 'id') {
        searchTerm = searchTerm.split(' ')[0];
    }

    // 2. FETCH REAL-TIME DATA
    const { data: students, error } = await window.supabase
        .from('students')
        .select(`*, student_ledger (*)`)
        .eq(searchColumn, searchTerm) 
        .limit(1);

    const student = (students && students.length > 0) ? students[0] : null;

    if (student) {
        student.ledger = student.student_ledger || [];
    }

    if (error || !student) { 
        previewBox.style.display = 'none'; 
        if (quickFeesContainer) quickFeesContainer.style.display = 'none';
        if (waiveSelect) waiveSelect.innerHTML = '<option value="">Select fee to waive...</option>';
        return; 
    }

    // ==========================================
    // 3. THE MATH ENGINE (Upgraded to match viewLedger)
    // ==========================================
    let tBilled = 0, tPaid = 0;
    let itemTotals = {};
    let unallocatedPaymentPool = 0; 
    
    // Exactly matches viewLedger's text cleaner
    const cleanName = (name) => name.replace('Enrollment: ', '').replace('Event/Trip: ', '').replace('Payment for ', '').replace('WAIVED: ', '').replace(' (Admin Selected)', '').replace(' (System Auto)', '').trim();

    if (student.ledger && Array.isArray(student.ledger)) {
        const chronologicalLedger = [...student.ledger].sort((a, b) => new Date(a.date) - new Date(b.date));

        // PASS 1: Tally all Active Charges
        chronologicalLedger.forEach(l => {
            if (l.status === 'VOID' || l.status === 'VOIDED') return; 
            if (l.type === 'charge' || l.type === 'fee') {
                let amt = parseFloat(l.amount) || 0;
                tBilled += amt;
                let cName = (l.description || l.desc || l.notes || l.item || l.category || 'General Charge').trim();
                
                if (!itemTotals[cName]) itemTotals[cName] = { billed: 0, paid: 0 };
                itemTotals[cName].billed += amt;
            }
        });

        // PASS 2: Match Payments & Handle Breakdowns Smartly
        chronologicalLedger.forEach(l => {
            if (l.status === 'VOID' || l.status === 'VOIDED') return; 

            if (['payment', 'waiver', 'discount', 'credit', 'overpayment'].includes(l.type)) {
                let paymentTotalAmt = parseFloat(l.amount) || 0;
                tPaid += paymentTotalAmt;

                let breakdownsToProcess = [];
                if (l.breakdown && l.breakdown.length > 0) {
                    breakdownsToProcess = l.breakdown;
                } else {
                    // Treat whole payment as one unallocated chunk
                    breakdownsToProcess = [{ amt: paymentTotalAmt, desc: l.description }];
                }

                breakdownsToProcess.forEach(b => {
                    let bAmt = parseFloat(b.amt) || parseFloat(b.amount) || 0;
                    let safeDesc = (b.description || b.desc || b.notes || b.item || 'Unallocated');
                    let pName = cleanName(safeDesc);

                    let matchedKey = null;
                    
                    // A. Try exact or partial string match
                    for (let cName in itemTotals) {
                        if (cName.toLowerCase().includes(pName.toLowerCase()) || pName.toLowerCase().includes(cName.toLowerCase())) {
                            matchedKey = cName;
                            break;
                        }
                    }
                    
                    // B. Fuzzy Keyword Fallback (Saves orphaned payments when plans change)
                    if (!matchedKey) {
                        for (let cName in itemTotals) {
                            let lowerC = cName.toLowerCase();
                            let lowerP = pName.toLowerCase();
                            if (lowerP.includes('tuition') && lowerC.includes('tuition')) { matchedKey = cName; break; }
                            if (lowerP.includes('transport') && lowerC.includes('transport')) { matchedKey = cName; break; }
                            if ((lowerP.includes('shop') || lowerP.includes('uniform')) && (lowerC.includes('shop') || lowerC.includes('uniform'))) { matchedKey = cName; break; }
                        }
                    }

                    // C. Apply Payment (Cap at amount owed, send overage to Waterfall)
                    if (matchedKey) {
                        let amountOwed = itemTotals[matchedKey].billed - itemTotals[matchedKey].paid;
                        if (amountOwed > 0) {
                            if (bAmt <= amountOwed) {
                                itemTotals[matchedKey].paid += bAmt;
                            } else {
                                itemTotals[matchedKey].paid += amountOwed; // Pay it off exactly
                                unallocatedPaymentPool += (bAmt - amountOwed); // Keep the change!
                            }
                        } else {
                            unallocatedPaymentPool += bAmt; // Debt already cleared, send to waterfall
                        }
                    } else {
                        unallocatedPaymentPool += bAmt; // No match found, send to waterfall
                    }
                });
            }
        });

        // PASS 3: Waterfall unallocated pool exactly like viewLedger
        if (unallocatedPaymentPool > 0) {
            const getAllocationPriority = description => {
                const normalized = cleanName(description).toLowerCase();
                if (normalized.includes('transport') || normalized.includes('bus')) return 0;
                if (normalized.includes('admission')) return 1;
                if (normalized.includes('tuition') || normalized.includes('term')) return 2;
                return 3;
            };
            const waterfallOrder = Object.keys(itemTotals).sort(
                (a, b) => getAllocationPriority(a) - getAllocationPriority(b)
            );
            for (const item of waterfallOrder) {
                let amountOwed = itemTotals[item].billed - itemTotals[item].paid;
                if (amountOwed > 0) {
                    if (unallocatedPaymentPool >= amountOwed) {
                        itemTotals[item].paid += amountOwed;
                        unallocatedPaymentPool -= amountOwed;
                    } else {
                        itemTotals[item].paid += unallocatedPaymentPool;
                        unallocatedPaymentPool = 0;
                        break; 
                    }
                }
            }
            if (unallocatedPaymentPool > 0) {
                itemTotals["Overpayment / Credit"] = { billed: 0, paid: unallocatedPaymentPool };
            }
        }
    }

    // ==========================================
    // 4. UI RENDER: TABLES & QUICK BUTTONS
    // ==========================================
    const bal = tBilled - tPaid;
    const color = bal > 0 ? '#e74c3c' : (bal < 0 ? '#8e44ad' : '#27ae60');
    const zigBalance = (bal > 0) ? (bal * rate).toFixed(2) : "0.00";

    const statusText = bal > 0 
        ? `$${bal.toFixed(2)} USD Owed <span style="font-size:12px; color:#f39c12;">(≈ ${zigBalance} ZiG)</span>` 
        : (bal < 0 ? `+$${Math.abs(bal).toFixed(2)} Credit` : `Cleared ($0)`);

    let tableRows = '';
    let hasCredit = false;
    let waiveOptionsHTML = '<option value="">Select outstanding fee to waive...</option>';

    if (quickFeesButtons) quickFeesButtons.innerHTML = ''; 
    let hasOwedFees = false;
    let owedCount = 0;

    for (let item in itemTotals) {
        let ib = itemTotals[item].billed;
        let ip = itemTotals[item].paid;
        let iOwe = ib - ip;

        if (iOwe > 0.01) {
            let iColor = 'color:#e74c3c;';
            let iStatus = `$${iOwe.toFixed(2)} Left`;

            tableRows += `
                <tr>
                    <td style="padding:6px 0; border-bottom:1px dashed #bdc3c7;"><strong>${item}</strong></td>
                    <td style="text-align:right; border-bottom:1px dashed #bdc3c7;">$${ib.toFixed(2)}</td>
                    <td style="text-align:right; border-bottom:1px dashed #bdc3c7; color:#27ae60;">$${ip.toFixed(2)}</td>
                    <td style="text-align:right; font-weight:bold; border-bottom:1px dashed #bdc3c7; ${iColor}">${iStatus}</td>
                </tr>
            `;

            if (item !== "Overpayment / Credit") {
                waiveOptionsHTML += `<option value="${item}|${iOwe}">${item} ($${iOwe.toFixed(2)} owed)</option>`;

                hasOwedFees = true;
                owedCount++;

                let btn = document.createElement('button');
                btn.className = 'btn-quick-fee';
                btn.type = 'button';
                btn.innerHTML = `➕ ${item} <strong>($${iOwe.toFixed(2)})</strong>`;

                btn.onclick = function() {
                    if(typeof window.addFeeToBreakdown === 'function') {
                        window.addFeeToBreakdown(item, iOwe);
                    }
                };
                if (quickFeesButtons) quickFeesButtons.appendChild(btn);
            }
        } else if (iOwe < -0.01) {
            hasCredit = true; 
        }
    }

    if (owedCount > 1 && quickFeesButtons) {
        let totalOwed = bal > 0 ? bal : 0;
        let payAllBtn = document.createElement('button');
        payAllBtn.type = 'button';
        payAllBtn.style.cssText = "margin: 3px; padding: 5px 10px; background: #2ecc71; color: white; border: none; border-radius: 4px; cursor: pointer; font-weight: bold;";
        payAllBtn.innerHTML = `Pay All ($${totalOwed.toFixed(2)})`;
        payAllBtn.onclick = function() {
            let usdInput = document.getElementById('payUsd');
            if(usdInput) usdInput.value = totalOwed.toFixed(2);
            if(typeof window.updatePaymentLiveTotals === 'function') window.updatePaymentLiveTotals();
        };
        quickFeesButtons.appendChild(payAllBtn);
    }

    if (waiveSelect) waiveSelect.innerHTML = waiveOptionsHTML;
    if (quickFeesContainer) quickFeesContainer.style.display = hasOwedFees ? 'block' : 'none';
    if (tableRows === '') tableRows = '<tr><td colspan="4" style="text-align:center; padding:15px; color:#27ae60; font-weight:bold;">Account Cleared! All charges have been fully settled.</td></tr>';

    // 5. BUILD TRANSACTION HISTORY TABLE
    let historyRows = '';
    if (student.ledger && Array.isArray(student.ledger)) {
        const sortedLedger = [...student.ledger].sort((a, b) => new Date(b.date) - new Date(a.date));

        sortedLedger.forEach(entry => {
            const isVoid = entry.status === 'VOID' || entry.status === 'VOIDED';
            // 🛡️ Special highlighting for overpayments
            const isOverpayment = entry.type === 'overpayment';
            const rowStyle = isOverpayment ? 'background-color:#e8f4f8; border-left: 4px solid #2980b9;' : '';

            let billedAmt = entry.type === 'charge' ? `$${parseFloat(entry.amount).toFixed(2)}` : '-';
            let paidAmt = (entry.type === 'payment' || entry.type === 'waiver' || entry.type === 'credit' || entry.type === 'overpayment') ? `$${parseFloat(entry.amount).toFixed(2)}` : '-';

            let strikeStyle = isVoid ? 'text-decoration: line-through; opacity: 0.5; background: #fdf2f2;' : '';
            if (isVoid) {
                if (entry.type === 'charge') billedAmt += ' (VOID)';
                else paidAmt += ' (VOID)';
            }

            let breakdownHTML = '';
            if (entry.type === 'payment' && entry.breakdown && entry.breakdown.length > 0) {
                breakdownHTML = '<ul style="margin: 5px 0 0 15px; padding: 0; font-size: 11px; color: #1e8449; list-style-type: square;">';
                entry.breakdown.forEach(b => {
                    const safeBDesc = b.description || b.desc || b.notes || b.item || 'Unallocated';
                    let cleanDesc = safeBDesc.replace(' (System Auto)', '').replace(' (Admin Selected)', '');
                    breakdownHTML += `<li>${cleanDesc}: <strong>$${parseFloat(b.amt).toFixed(2)}</strong></li>`;
                });
                breakdownHTML += '</ul>';
            }

            let receiptBadge = entry.receiptNo ? `<br><span style="font-size: 10px; background: #ecf0f1; padding: 2px 5px; border-radius: 3px;">Ref: ${entry.receiptNo}</span>` : '';
            let safeDescription = entry.description || entry.desc || entry.notes || entry.item || entry.category || 'Transaction';
            let overpayLabel = isOverpayment ? ' 💰 OVERPAYMENT' : '';

            if (entry.type === 'payment' && safeDescription.includes('&')) {
                safeDescription = 'Combined Payment Breakdown:';
            }

            let termLabel = entry.term || 'General';
            let paidColor = isOverpayment ? '#2980b9' : '#27ae60';

            historyRows += `
                <tr style="${strikeStyle}${rowStyle}">
                    <td style="padding:6px; border-bottom:1px dashed #bdc3c7;">${entry.date}${overpayLabel}</td>
                    <td style="padding:6px; border-bottom:1px dashed #bdc3c7;">${termLabel}</td>
                    <td style="padding:6px; border-bottom:1px dashed #bdc3c7;">
                        <strong>${safeDescription}</strong> ${receiptBadge}
                        ${breakdownHTML}
                    </td>
                    <td style="text-align:right; font-weight:bold; border-bottom:1px dashed #bdc3c7; color:#e74c3c;">${billedAmt}</td>
                    <td style="text-align:right; font-weight:bold; border-bottom:1px dashed #bdc3c7; color:${paidColor};">${paidAmt}</td>
                </tr>
            `;
        });
    }
    if (historyRows === '') historyRows = '<tr><td colspan="5" style="text-align:center; padding:10px; color:#7f8c8d;">No transactions recorded.</td></tr>';

    let creditNotice = hasCredit ? `<div style="background:#f4ecf7; color:#8e44ad; padding:8px; text-align:center; margin-bottom:10px; border-radius:4px; font-weight:bold; font-size:12px; border: 1px solid #8e44ad;">This student has an overpayment/credit on their account!</div>` : '';

    // 6. INJECT HTML TO DOM
    previewBox.innerHTML = `
        ${creditNotice}
        <div style="display:flex; justify-content:space-between; margin-bottom:15px; align-items:center;">
            <strong style="font-size: 15px; color:#2c3e50;">👤 ${student.name} (${student.grade || 'N/A'})</strong>
            <strong style="color:${color}; font-size: 15px; background:#fff; padding:4px 8px; border-radius:4px; border:2px solid ${color};">Overall: ${statusText}</strong>
        </div>

        <div style="display: flex; gap: 15px; background: #f8f9fa; padding: 15px; border-radius: 6px; border: 1px solid #bdc3c7; margin-bottom: 20px;">
            <div style="flex: 1; text-align: center;">
                <span style="font-size: 12px; color: #7f8c8d; text-transform: uppercase; font-weight: bold;">Total Billed</span><br>
                <strong style="font-size: 18px; color: #2c3e50;">$${tBilled.toFixed(2)}</strong>
            </div>
            <div style="flex: 1; text-align: center; border-left: 1px solid #ecf0f1; border-right: 1px solid #ecf0f1;">
                <span style="font-size: 12px; color: #7f8c8d; text-transform: uppercase; font-weight: bold;">Total Paid</span><br>
                <strong style="font-size: 18px; color: #27ae60;">$${tPaid.toFixed(2)}</strong>
            </div>
            <div style="flex: 1; text-align: center;">
                <span style="font-size: 12px; color: #7f8c8d; text-transform: uppercase; font-weight: bold;">Total Owed</span><br>
                <strong style="font-size: 18px; color: ${color};">$${(tBilled - tPaid).toFixed(2)}</strong>
            </div>
        </div>

        <strong style="font-size:12px; color:#34495e; text-transform:uppercase;">Unpaid Fee Summary</strong>
        <table style="width:100%; font-size:12px; border-collapse: collapse; margin-bottom: 20px;">
            <tr style="background:#ecf0f1; color:#2c3e50;">
                <th style="text-align:left; padding:6px; border-bottom: 1px solid #bdc3c7;">Charge Name</th>
                <th style="text-align:right; padding:6px; border-bottom: 1px solid #bdc3c7;">Billed</th>
                <th style="text-align:right; padding:6px; border-bottom: 1px solid #bdc3c7;">Paid</th>
                <th style="text-align:right; padding:6px; border-bottom: 1px solid #bdc3c7;">Status</th>
            </tr>
            ${tableRows}
        </table>

        <strong style="font-size:12px; color:#34495e; text-transform:uppercase;">Transaction History & Ledger</strong>
        <div style="max-height: 250px; overflow-y: auto;">
            <table style="width:100%; font-size:12px; border-collapse: collapse; margin-bottom: 5px;">
                <tr style="background:#ecf0f1; color:#2c3e50;">
                    <th style="text-align:left; padding:6px; border-bottom: 1px solid #bdc3c7;">Date</th>
                    <th style="text-align:left; padding:6px; border-bottom: 1px solid #bdc3c7;">Period/Term</th>
                    <th style="text-align:left; padding:6px; border-bottom: 1px solid #bdc3c7;">Description</th>
                    <th style="text-align:right; padding:6px; border-bottom: 1px solid #bdc3c7;">Billed</th>
                    <th style="text-align:right; padding:6px; border-bottom: 1px solid #bdc3c7;">Paid</th>
                </tr>
                ${historyRows}
            </table>
        </div>
    `;
    previewBox.style.display = 'block';
};
