window.addFeeToBreakdown = function(desc, amount) {
    const list = document.getElementById('payBreakdownList');
    if (!list) return;

    // Prevent adding the exact same fee twice to the UI
    const existingRows = list.querySelectorAll('.p-desc');
    for (let i = 0; i < existingRows.length; i++) {
        if (existingRows[i].value === desc) {
            alert(`"${desc}" is already in your selected list.`);
            return;
        }
    }

    const row = document.createElement('div');
    row.style.cssText = "display: flex; gap: 10px; align-items: center; margin-bottom: 8px;";
    row.dataset.quickFee = 'true';
    
    // 🛠️ THE FIX: Added strict height, padding, and flex alignment!
    row.innerHTML = `
        <input type="text" class="input-standard p-desc" value="${desc}" readonly style="flex: 2; height: 36px; padding: 0 10px; font-size: 13px; background: #fdfdfd; border: 1px solid #bdc3c7; border-radius: 4px; box-sizing: border-box;">
        <input type="number" class="input-standard p-amt" value="${amount.toFixed(2)}" step="0.01" style="flex: 1; height: 36px; padding: 0 10px; text-align: right; font-size: 13px; font-weight: bold; color: #2c3e50; border: 1px solid #bdc3c7; border-radius: 4px; box-sizing: border-box;" oninput="if(typeof window.calcTotalPay === 'function') window.calcTotalPay();">
        <button type="button" onclick="this.parentElement.remove(); if(typeof window.calcTotalPay === 'function') window.calcTotalPay();" style="background: #e74c3c; color: white; border: none; border-radius: 4px; width: 36px; height: 36px; cursor: pointer; display: flex; align-items: center; justify-content: center; font-size: 14px;" title="Remove this item">✖</button>
    `;

    list.appendChild(row);
    
    // Auto-calculate the total
    if(typeof window.calcTotalPay === 'function') window.calcTotalPay();
};

window.applyFeeWaiver = function() {
    // 1. Security Check (Only Admins can grant exemptions to existing ledgers)
    const role = window.currentUser?.role || "";
    if (role && !(role.includes('Level 2') || role.includes('Level 3') || role === 'Admin' || role === 'Chief Admin')) {
        return alert("❌ Access Denied: Only Admins can grant fee exemptions.");
    }

    const searchInput = document.getElementById('payId');
    const waiveSelect = document.getElementById('waiveFeeSelect');
    
    if (!searchInput || !waiveSelect || !waiveSelect.value) {
        return alert("Please select a specific fee to waive from the dropdown.");
    }

    // 2. Get the active student
    const rawInput = searchInput.value.trim();
    const id = rawInput.split(' ')[0].toUpperCase(); 
    const student = window.students.find(s => s.id && s.id.toUpperCase() === id);
    
    if (!student) return alert("Student not found.");
    const processedBy = window.currentUser?.user || window.currentUser?.username || window.currentUser?.name || 'Admin';

    // 3. Extract the fee details from the dropdown value (Format: "Fee Name|Amount")
    const selectedData = waiveSelect.value.split('|');
    const feeName = selectedData[0];
    const feeAmount = parseFloat(selectedData[1]) || 0;

    if (!feeName || feeAmount <= 0) {
        return alert("Error reading fee data. Amount must be greater than $0.00.");
    }

    if (!confirm(`Are you sure you want to exempt ${student.name} from the ${feeName} fee ($${feeAmount.toFixed(2)})?\n\nThis will instantly reverse the charge and credit their account balance.`)) {
        return;
    }

    if (!student.ledger) student.ledger = [];
    
    const dateStr = new Date().toISOString().split('T')[0];
    const receiptNo = "WAIVE-" + Math.floor(Math.random() * 900000 + 100000);
    const waiverTransactionId = "WV-" + Date.now();

    // 4. Add the waiver as a credit adjustment (Separated from cash payments)
    const waiverRecord = {
        id: waiverTransactionId,
        date: dateStr,
        desc: `Exemption / Waiver: ${feeName}`,
        amount: feeAmount,
        type: 'waiver', // 🎯 FIXED: Changed from 'payment' so cash-flow reports don't treat waivers as collected cash
        method: 'System Exemption',
        receiptNo: receiptNo,
        receipt_no: receiptNo,
        processed_by: processedBy
    };

    student.ledger.push(waiverRecord);

    // Also sync to Supabase relational `student_ledger` table if online
    if (typeof window.supabaseClient !== 'undefined' && navigator.onLine) {
        window.supabaseClient.from('student_ledger').insert({
            id: waiverTransactionId,
            student_id: student.id,
            date: dateStr,
            type: 'waiver',
            amount: feeAmount,
            description: `Exemption / Waiver: ${feeName}`,
            receipt_no: receiptNo,
            processed_by: processedBy,
            term: typeof window.getCurrentTerm === 'function' ? window.getCurrentTerm() : 'Current Term'
        }).then(({ error }) => {
            if (error) console.warn("Cloud Sync Warning (Waiver):", error.message);
        });
    }

    // 5. Strict Balance Recalculation (Accounts for both 'payment' and 'waiver' types as reducers of balance)
    if (typeof window.calculateStudentBalance === 'function') {
        student.balanceOwing = window.calculateStudentBalance(student);
    } else {
        let nBilled = 0, nCredited = 0;
        student.ledger.forEach(l => { 
            const isVoid = l.status === 'VOID' || l.status === 'VOIDED';
            if (isVoid) return;

            if (l.type === 'payment' || l.type === 'waiver' || l.type === 'credit') {
                nCredited += (parseFloat(l.amount || l.amt) || 0); 
            }
            if (l.type === 'charge') {
                nBilled += (parseFloat(l.amount || l.amt) || 0); 
            }
        });
        student.balanceOwing = parseFloat((nBilled - nCredited).toFixed(2));
    }
    student.balance_owing = student.balanceOwing; // Keep snake_case synced for DB upsert

    // 6. Save and Sync Global Data
    if (typeof window.saveData === 'function') window.saveData();
    if (typeof window.filterDirectory === 'function') window.filterDirectory();
    if (typeof window.updateDashboard === 'function') window.updateDashboard();

    // 🧹 Wipe input fields and force a refresh of the payment form totals
    if (document.getElementById('payUsd')) document.getElementById('payUsd').value = '';
    if (document.getElementById('payZig')) document.getElementById('payZig').value = '';
    if (typeof window.updatePaymentLiveTotals === 'function') window.updatePaymentLiveTotals();

    // 7. Refresh the UI preview panel & populate fee dropdown options again
    if (typeof window.previewStudentBalance === 'function') {
        window.previewStudentBalance();
    }
    
    waiveSelect.value = ""; // Reset waiver dropdown selection

    alert(`✅ Exemption Applied Successfully!\n$${feeAmount.toFixed(2)} has been credited back for ${feeName}. Account balance updated.`);
};
