window.saveZigRate = async function() {
    // 3-Tier Check
    const role = window.currentUser?.role || "";
    if (!(role.includes('Level 2') || role.includes('Level 3') || role === 'Admin' || role === 'Chief Admin')) {
        return alert("❌ Access Denied: Only Admins can update the global exchange rate.");
    }

    const newRate = parseFloat(document.getElementById('zigRate').value);
    if (!newRate || newRate <= 0) return alert("Please enter a valid rate.");

    if (!window.settings) window.settings = {};
    window.settings.zigRate = newRate;

    if (!navigator.onLine) {
        localStorage.setItem('haven_settings', JSON.stringify(window.settings));
        return alert("⚠️ Saved locally, but you are offline. The exchange rate will sync when connection is restored.");
    }

    try {
        const { error } = await supabaseClient
            .from('school_data')
            .upsert({ id: 'master_settings', settings: window.settings, last_updated: new Date().toISOString() });

        if (error) throw error;
        alert("✅ Exchange rate saved to cloud!");
    } catch (err) {
        console.error("Rate save error:", err);
        alert("⚠️ Failed to save rate to cloud. Check internet connection.");
    }
};


