window.isCreditAllocationAdjustmentCharge = function(item) {
    const type = String(item?.type || '').toLowerCase();
    const description = String(item?.description || item?.desc || '').toLowerCase();

    return type === 'charge' && description.includes('credit allocation (reversal)');
};

window.isAdvanceCreditSettlementEntry = function(item) {
    const type = String(item?.type || '').toLowerCase();
    const description = String(item?.description || item?.desc || '').toLowerCase();
    const method = String(item?.method || '').toLowerCase();

    return type === 'payment' && (item.is_credit_backed === true || method.includes('advance credit') || description.includes('paid via advance credit'));
};

window.calculateStudentBalance = function(student) {
    if (!student || !student.ledger) return 0;
    
    let totalCharges = 0;
    let totalCredits = 0; // Includes payments, waivers, credits, AND overpayments
    
    student.ledger.forEach(item => {
        // SKIP VOIDED TRANSACTIONS
        if (['VOID', 'VOIDED', 'REVERSAL'].includes(String(item.status || '').toUpperCase())) {
            return;
        }
        let amt = parseFloat(item.amount) || 0;
        const type = String(item.type || '').toLowerCase();
        if (type === 'charge' || type === 'fee') {
            totalCharges += amt;
        } else if (['payment', 'waiver', 'discount', 'credit', 'overpayment'].includes(type)) {
            // 🛑 FIX: Include overpayments in credit calculation so they reduce outstanding balance
            totalCredits += amt;
        }
    });
    
    // Strict subtraction with floating-point safety
    return parseFloat((totalCharges - totalCredits).toFixed(2));
};

window.openPaymentModal = function(studentId) {
    let student = window.students.find(s => String(s.id) === String(studentId));
    if (!student) return alert("Could not find student ID: " + studentId); 

    const modal = document.getElementById('whatsappPaymentModal');
    if (!modal) return alert("Error: The new whatsappPaymentModal HTML is missing!");

    // Fill the basic details using the new wa_ IDs
    const nameEl = document.getElementById('wa_payStudentName');
    const idEl = document.getElementById('wa_payStudentId');
    if (nameEl) nameEl.innerText = student.name;
    if (idEl) idEl.value = student.id;
    
    // Clear the typing boxes from the last person
    const amtInput = document.getElementById('wa_payAmountInput');
    const descInput = document.getElementById('wa_payDescription');
    if (amtInput) amtInput.value = ''; 
    if (descInput) descInput.value = '';

    // Calculate and display balance
    const currentBalance = window.calculateStudentBalance(student);
    const balDisplay = document.getElementById('wa_payAmountDue');
    if (balDisplay) {
        balDisplay.innerText = `$${currentBalance.toFixed(2)}`;
        balDisplay.style.color = currentBalance > 0 ? '#e74c3c' : '#27ae60';
    }

    // Generate Transaction History
    const historyBox = document.getElementById('wa_payHistoryBox');
    if (historyBox) {
        let historyHTML = '<strong style="color:#2c3e50;">Recent Payments:</strong><br>';
        const ledger = student.ledger || [];
        const payments = ledger.filter(l => l.type === 'payment').slice(-4); 
        
        if (payments.length === 0) {
            historyHTML += '<em style="color:#7f8c8d;">No previous payments found.</em>';
        } else {
            payments.forEach(p => {
                historyHTML += `<span style="color:#27ae60;">+ $${parseFloat(p.amount).toFixed(2)}</span> <span style="color:#95a5a6; font-size:11px;">on ${p.date} (${p.method})</span><br>`;
            });
        }
        historyBox.innerHTML = historyHTML;
    }

    modal.style.display = 'flex';
};



