window.updateEnrollmentFeePreview = function() {
    const gradeSelect = document.getElementById('enrollGrade');
    const planSelect = document.getElementById('enrollBillingPlan'); 
    
    // Using the ID from the HTML you shared earlier
    const previewBox = document.getElementById('masterEnrollFeePreview');

    if (!gradeSelect || !planSelect || !previewBox) return;

    const selectedGrade = gradeSelect.value;
    const selectedPlan = planSelect.value; 

    // 1. Calculate Base Tuition from your SQL-backed structures
    let totalAmount = 0; 
    const currentFees = window.feeStructures[selectedGrade];
    
    if (currentFees && Array.isArray(currentFees)) {
        currentFees.forEach(fee => {
            totalAmount += parseFloat(fee.amount) || 0;
        });

        if (selectedPlan === 'monthly') {
            totalAmount = totalAmount / 3; 
        }
    } else {
        previewBox.value = "⚠️ Fee not set in Settings";
        return; // Stop the function here if there are no fees setup
    }

    // ==========================================
    // 2. The Initial Payment Subtraction 
    // ==========================================
    const paymentInput = document.getElementById('regOnlinePayment');
    let paymentAmount = 0;

    if (paymentInput && paymentInput.value) {
        paymentAmount = parseFloat(paymentInput.value) || 0;
    }
    
    // Subtract the payment from the total amount
    let finalBalance = totalAmount - paymentAmount;

    // Optional: Prevent the preview from showing a negative number if they overpay
    if (finalBalance < 0) {
        finalBalance = 0; 
    }

    // 3. Update the screen
    previewBox.value = '$' + finalBalance.toFixed(2);
};



