window.applyEnrollmentWaiver = function() {
    const waiveSelect = document.getElementById('enrollWaiveFeeSelect');
    
    if (!waiveSelect || !waiveSelect.value) {
        alert("Please select a fee from the dropdown to waive first.");
        return;
    }

    const feeName = waiveSelect.value;
    
    // Ensure the waived array exists in memory
    window.waivedEnrollmentFees = window.waivedEnrollmentFees || [];
    
    // Check if it's already waived
    if (!window.waivedEnrollmentFees.includes(feeName)) {
        // Push the fee to the waived list
        window.waivedEnrollmentFees.push(feeName);
        
        // Recalculate instantly to update the UI totals
        if (typeof window.previewEnrollmentFees === 'function') {
            window.previewEnrollmentFees();
        }
        
        // Notify the user
        alert(`🛑 ${feeName} has been exempted.\nIt will NOT be charged to the student's ledger or starting invoice.`);
        
        // 🧹 Reset the dropdown so it doesn't look like it's still selected
        waiveSelect.value = ""; 
    } else {
        alert(`⚠️ This fee (${feeName}) is already waived.`);
    }
};

