window.printPhysicalReceipt = function(studentName, date, amount, method, reason, receiptNo, newBalance, studentObj = null) {
    const schoolName = (window.settings && window.settings.schoolName) ? window.settings.schoolName : "HAVEN ONLINE";
    const logoUrl = (window.settings && window.settings.logoUrl) ? window.settings.logoUrl : "";
    const schoolAddress = (window.settings && window.settings.address) ? window.settings.address : "";
    const schoolPhone = (window.settings && window.settings.phone) ? window.settings.phone : "";

    const printWindow = window.open('', '_blank', 'width=400,height=600');
    
    let logoHtml = "";
    if (logoUrl) {
        logoHtml = `<img src="${logoUrl}" style="max-height: 80px; margin-bottom: 10px; display: block; margin-left: auto; margin-right: auto;">`;
    }

    // 🎯 MATCH VIEW LEDGER: Format itemized breakdown if available
    let breakdownHtml = "";
    if (reason && reason.includes('|')) {
        // If reason contains multi-item separation like "Tuition: $150 | Food: $60"
        const items = reason.split('|');
        breakdownHtml = `<div style="margin: 10px 0; border-top: 1px dashed #000; border-bottom: 1px dashed #000; padding: 5px 0;">
            <div style="font-size: 12px; font-weight: bold; margin-bottom: 4px;">PAYMENT BREAKDOWN:</div>`;
        items.forEach(item => {
            breakdownHtml += `<div style="font-size: 12px; display: flex; justify-content: space-between; margin-bottom: 3px;"><span>• ${item.trim()}</span></div>`;
        });
        breakdownHtml += `</div>`;
    } else {
        breakdownHtml = `<div class="row"><span>For:</span> <span>${reason}</span></div>`;
    }

    // 🎯 MATCH VIEW LEDGER: Calculate Global Financial State if student object is accessible
    let globalSummaryHtml = "";
    if (studentObj && studentObj.ledger && Array.isArray(studentObj.ledger)) {
        let tBilled = 0, tPaid = 0;
        studentObj.ledger.forEach(l => {
            if (l.status === 'VOID' || l.status === 'VOIDED') return;
            let amt = parseFloat(l.amount || l.amt || 0);
            if (l.type === 'charge') {
                tBilled += amt;
            } else if (l.type === 'payment' || l.type === 'waiver' || l.type === 'discount') {
                if (l.breakdown && l.breakdown.length > 0) {
                    l.breakdown.forEach(b => tPaid += parseFloat(b.amt || 0));
                } else {
                    tPaid += amt;
                }
            }
        });
        let globalOwed = tBilled - tPaid;

        globalSummaryHtml = `
            <div style="margin-top: 15px; border-top: 1px dashed #000; padding-top: 10px; font-size: 12px;">
                <div style="text-align: center; font-weight: bold; margin-bottom: 5px;">--- ACCOUNT SUMMARY ---</div>
                <div class="row" style="font-size: 12px; margin-bottom: 4px;"><span>Total Billed:</span> <span>$${tBilled.toFixed(2)}</span></div>
                <div class="row" style="font-size: 12px; margin-bottom: 4px;"><span>Total Paid:</span> <span>-$${tPaid.toFixed(2)}</span></div>
                <div class="row" style="font-size: 14px; font-weight: bold; color: ${globalOwed > 0 ? '#c0392b' : '#27ae60'}; margin-top: 6px;">
                    <span>Overall Balance Due:</span> <span>$${(globalOwed > 0 ? globalOwed : 0).toFixed(2)}</span>
                </div>
            </div>
        `;
    }

    const html = `
        <html>
        <head>
            <title>Receipt - ${receiptNo}</title>
            <style>
                body { font-family: 'Courier New', Courier, monospace; padding: 20px; color: #000; max-width: 350px; margin: 0 auto; line-height: 1.2; }
                .header { text-align: center; margin-bottom: 15px; border-bottom: 1px dashed #000; padding-bottom: 10px; }
                .school-name { font-size: 20px; font-weight: bold; text-transform: uppercase; margin-bottom: 5px; }
                .school-info { font-size: 12px; margin-bottom: 2px; }
                .row { display: flex; justify-content: space-between; margin-bottom: 8px; font-size: 14px; }
                .total { font-weight: bold; font-size: 16px; margin-top: 15px; border-top: 1px dashed #000; padding-top: 15px; }
                .footer { text-align: center; margin-top: 30px; font-size: 11px; border-top: 1px dashed #000; padding-top: 10px; }
            </style>
        </head>
        <body>
            <div class="header">
                ${logoHtml}
                <div class="school-name">${schoolName}</div>
                <div class="school-info">${schoolAddress}</div>
                <div class="school-info">${schoolPhone}</div>
                <div style="margin-top: 10px; font-weight: bold;">OFFICIAL RECEIPT</div>
            </div>

            <div class="row"><span>Receipt No:</span> <span>${receiptNo}</span></div>
            <div class="row"><span>Date:</span> <span>${date}</span></div>
            <br>
            <div class="row"><span>Student:</span> <span><b>${studentName}</b></span></div>
            
            <div class="row"><span>Method:</span> <span>${method}</span></div>
            
            ${breakdownHtml}
            
            <div class="total row"><span>AMOUNT PAID:</span> <span>$${parseFloat(amount).toFixed(2)}</span></div>
            <div class="row" style="margin-top: 10px;"><span>Transaction Bal:</span> <span>$${parseFloat(newBalance).toFixed(2)}</span></div>
            
            ${globalSummaryHtml}
            
            <div class="footer">
                Thank you for your payment!<br>
                <em>System by Haven Games</em>
            </div>
            
            <script>
                window.onload = function() { 
                    window.print(); 
                    setTimeout(() => { window.close(); }, 1000); 
                }
            </script>
        </body>
        </html>
    `; 
    
    printWindow.document.write(html);
    printWindow.document.close();
};

// ==========================================
// 46. AI FORM SCANNER LOGIC (SECURE NETLIFY ROUTE)
// ==========================================

window.processAIForm = async function(event) {
    if (!navigator.onLine) return alert("⚠️ You are offline. The AI form scanner requires an active internet connection.");

    const file = event.target.files[0];
    if (!file) return;

    const statusText = document.getElementById('aiLoadingStatus');
    if (statusText) {
        statusText.style.display = 'block';
        statusText.innerHTML = '<span class="spinner">⏳</span> AI is reading the form securely...';
    }

    try {
        // 1. Convert image to Base64
        const base64Data = await new Promise((resolve) => {
            const reader = new FileReader();
            reader.onloadend = () => resolve(reader.result.split(',')[1]);
            reader.readAsDataURL(file);
        });

        // 2. Send securely to Netlify Function (Hiding the API Key)
        const response = await fetch('/.netlify/functions/scanForm', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ 
                image: base64Data,
                mimeType: file.type
            })
        });

        if (!response.ok) throw new Error("Server error during AI scan.");
        
        const data = await response.json();

        if (data.error) throw new Error(data.error);

        // 3. Fill specific HTML IDs
        if (data.fullName) document.getElementById('regName').value = data.fullName;
        
        if (data.phone) {
            const phoneInput = document.getElementById('regPhone') || document.getElementById('phone');
            if (phoneInput) phoneInput.value = data.phone;
        }
        
        if (data.address) {
            const addressInput = document.getElementById('regAddress') || document.getElementById('address');
            if (addressInput) addressInput.value = data.address;
        }
        
        if (data.dob) {
            const dobInput = document.getElementById('regDob') || document.getElementById('dob') || document.getElementById('stDob');
            if (dobInput) dobInput.value = data.dob;
        }
        
        // Handle the Grade Dropdown safely
        if (data.grade && document.getElementById('regGrade')) {
            const gradeDropdown = document.getElementById('regGrade');
            const match = Array.from(gradeDropdown.options).find(opt => 
                opt.value.toLowerCase().includes(data.grade.toLowerCase())
            );
            if (match) gradeDropdown.value = match.value;
        }
        
        alert("✅ AI Scan successful!");

    } catch (error) {
        console.error("AI Error:", error);
        alert("❌ AI failed to read the form. Please enter manually.");
    } finally {
        if (statusText) statusText.style.display = 'none';
    }
};

// ==========================================
// 47. ONLINE ENROLLMENT ENGINE
