window.fileToBase64 = (file) => new Promise((resolve, reject) => {
    if (!file) { resolve(null); return; }
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result);
    reader.onerror = error => reject(error);
});

window.uploadFileToStorage = async function(bucket, path, file, contentType) {
    if (!window.supabaseClient || !file) return null;
    const { error } = await window.supabaseClient.storage
        .from(bucket)
        .upload(path, file, { cacheControl: '3600', upsert: true, contentType });
    if (error) throw error;
    if (bucket === 'application-documents') return `${bucket}/${path}`;
    const { data } = window.supabaseClient.storage.from(bucket).getPublicUrl(path);
    return data?.publicUrl || null;
};

window.uploadDataUrlToStorage = async function(bucket, path, dataUrl) {
    if (!dataUrl || !dataUrl.startsWith('data:')) return null;
    const response = await fetch(dataUrl);
    const blob = await response.blob();
    return window.uploadFileToStorage(bucket, path, blob, blob.type);
};

window.submitOnlineApplication = async function(event) {
    event.preventDefault(); 
    
    if (!navigator.onLine) return alert("⚠️ You are offline. Please connect to the internet to submit your application.");

    const submitBtn = document.getElementById('btnSubmitApp');
    const loadingText = document.getElementById('appLoadingText');
    
    if (submitBtn) submitBtn.style.display = 'none';
    if (loadingText) loadingText.style.display = 'block';
    
    try {
        const birthCertFile = document.getElementById('fileBirthCert')?.files[0];
        const resultsFile = document.getElementById('fileResults')?.files[0];
        const parentIdFile = document.getElementById('fileParentId')?.files[0];
        
        if (birthCertFile && birthCertFile.size > 2500000) throw new Error("Birth Certificate is too large. Max size is 2.5MB.");
        if (parentIdFile && parentIdFile.size > 2500000) throw new Error("Parent ID is too large. Max size is 2.5MB.");

        const appData = {
            dob: document.getElementById('appDob')?.value || '',
            gender: document.getElementById('appGender')?.value || '',
            guardianName: document.getElementById('appGuardianName')?.value || '',
            guardianPhone: document.getElementById('appGuardianPhone')?.value || '',
            guardianEmail: document.getElementById('appGuardianEmail')?.value || '',
            address: document.getElementById('appAddress')?.value || '',
            documents: {
                birthCert: null,
                results: null,
                parentId: null
            },
            submittedAt: new Date().toISOString()
        };

        const studentName = document.getElementById('appStudentName')?.value.trim() || 'Unknown';
        const level = document.getElementById('appLevel')?.value || 'N/A';
        const uniqueAppId = "APP-" + Date.now().toString().slice(-6); 

        const documentUploads = [
            ['birthCert', birthCertFile],
            ['results', resultsFile],
            ['parentId', parentIdFile]
        ];
        for (const [field, file] of documentUploads) {
            if (!file) continue;
            const safeName = file.name.replace(/[^a-z0-9._-]/gi, '_');
            appData.documents[field] = await window.uploadFileToStorage(
                'application-documents',
                `${uniqueAppId}/${field}-${Date.now()}-${safeName}`,
                file,
                file.type
            );
        }

        const { error } = await supabaseClient
            .from('pending_applications')
            .insert([{
                id: uniqueAppId,
                student_name: studentName,
                level: level,
                application_data: appData,
                status: 'pending'
            }]);

        if (error) throw error;

        const modal = document.getElementById('publicEnrollmentModal');
        if (modal) modal.style.display = 'none';
        
        alert(`✅ Application Submitted Successfully!\n\nYour reference number is ${uniqueAppId}. The school administration will review the documents and contact you on ${appData.guardianPhone}.`);
        
        const form = document.getElementById('onlineEnrollForm');
        if (form) form.reset();

    } catch (error) {
        console.error("Application Submission Error:", error);
        alert("⚠️ Failed to submit application: " + error.message);
    } finally {
        if (submitBtn) submitBtn.style.display = 'block';
        if (loadingText) loadingText.style.display = 'none';
    }
};

