window.reviewSingleApplication = function(encodedApp) {
    const app = JSON.parse(decodeURIComponent(encodedApp));
    
    const confirmMessage = `STUDENT DETAILS:
Name: ${app.student_name}
Class: ${app.level}

Would you like to APPROVE this student and assign their fees?`;

    if (confirm(confirmMessage)) {
        let admissionFee = prompt(`Enter the one-time ADMISSION FEE for ${app.student_name}:\n(Leave as 0 if none)`, "20");
        if (admissionFee === null) return; 

        let tuitionFee = prompt(`Enter the TERM TUITION FEE for ${app.level}:\n(Leave as 0 if none)`, "150");
        if (tuitionFee === null) return; 

        window.approveApplication(app, parseFloat(admissionFee) || 0, parseFloat(tuitionFee) || 0);
    }
};

window.viewDocument = function(base64String) {
    if (typeof base64String === 'string' && base64String.startsWith('application-documents/')) {
        const relativePath = base64String.slice('application-documents/'.length);
        window.supabaseClient.storage
            .from('application-documents')
            .createSignedUrl(relativePath, 3600)
            .then(({ data, error }) => {
                if (error) throw error;
                if (data?.signedUrl) window.open(data.signedUrl, '_blank');
            })
            .catch(error => alert(`Could not open document: ${error.message || error}`));
        return;
    }
    const win = window.open();
    if (win) {
        win.document.write(`<iframe src="${base64String}" frameborder="0" style="border:0; top:0px; left:0px; bottom:0px; right:0px; width:100%; height:100%;" allowfullscreen></iframe>`);
    } else {
        alert("⚠️ Please allow pop-ups for this site to view documents.");
    }
};

