// ✅ MASTER APPLICATION APPROVAL ENGINE (SCHEMA SAFE)
// ==========================================
window.approveApplication = async function(app, admissionFee, tuitionFee) {
    // 1. 3-Tier Security Check
    const role = window.currentUser?.role || "";
    if (!(role.includes('Level 2') || role.includes('Level 3') || role === 'Admin' || role === 'Chief Admin')) {
        return alert("❌ Access Denied: Only Admins can approve applications into the official ledger.");
    }

    if (!navigator.onLine) return alert("⚠️ You must be online to approve applications and send WhatsApp notifications.");

    // 2. Setup IDs and Fees
    const data = app.application_data || {};
    // New Line (Matches your offline students perfectly)
const studentId = "STU-" + Math.floor(1000 + Math.random() * 9000);

    let timeInput = prompt(`⏳ How many HOURS does the parent have to pay?`, "24");
    if (timeInput === null) return; 
    
    const deadlineHours = parseInt(timeInput) || 24;
    const deadlineDate = new Date();
    deadlineDate.setHours(deadlineDate.getHours() + deadlineHours); 

    let startingBalance = admissionFee + tuitionFee;
    const todayDate = new Date().toISOString().split('T')[0];

    let initialLedger = [
        { id: "FEE-A-" + Date.now(), date: todayDate, type: "charge", desc: "Admission Fee", amount: admissionFee },
        { id: "FEE-T-" + Date.now(), date: todayDate, type: "charge", desc: "Tuition Fee", amount: tuitionFee }
    ];

    // 3. 🎯 THE FIX: Split Cloud Data from Local UI Data

    // A. STRICT CLOUD DATA (Only columns that actually exist in your Supabase 'students' table)
    const cloudStudent = {
        id: studentId,
        name: app.student_name || app.studentName || data.studentName,
        grade: app.level,
        gender: data.gender || '',
        phone: data.guardianPhone || '',
        dob: data.dob || '',         
        address: data.address || '', 
        balance_owing: startingBalance,       // SQL strictly wants this
        enrollment_status: 'pending_payment',
        application_ref: app.id,              // The new column
        // 👇 NEW DB SCHEMA FIELDS INJECTED HERE 👇
        transport_tier: 0,
        food_program: false,
        stationery_pack: false
        // 👆 ------------------------------ 👆
    };

    // B. RICH LOCAL DATA (Contains all the extra UI labels like 'balance', 'class', 'status')
    const localStudent = {
        ...cloudStudent,                      // Copies everything from above, plus:
        class: app.level,                     // UI uses this
        balance: startingBalance,             // Parent Portal uses this
        status: 'active',                     // System filters use this
        email: data.guardianEmail || '',
        guardianName: data.guardianName || '',
        enrollDate: todayDate,
        applicationRef: app.id,               // CamelCase version just in case
        // 👇 NEW LOCAL UI FIELDS INJECTED HERE 👇
        transportTier: 0,
        foodProgram: false,
        stationeryPack: false
        // 👆 ------------------------------ 👆
    };

    try {
        
        // 4. Push STRICT data to Supabase Cloud
        const { error: stuErr } = await supabaseClient.from('students').insert([cloudStudent]);
        if (stuErr) throw stuErr;

        // ✅ NEW: Push initial ledger charges to your relational table
        await supabaseClient.from('student_ledger').insert(initialLedger.map(l => ({
            id: l.id,
            student_id: studentId,
            date: l.date,
            type: l.type,
            description: l.desc,
            amount: l.amount,
            status: 'ACTIVE'
        })));

        // 5. Remove from Waiting List
        await supabaseClient.from('pending_applications').update({ status: 'approved' }).eq('id', app.id);

        // 6. Push RICH data into Local Memory so the UI works instantly without refreshing
        window.students = window.students || [];
        window.students.push(localStudent);

        // 5. Remove from Waiting List
        await supabaseClient.from('pending_applications').update({ status: 'approved' }).eq('id', app.id);

        // 6. Push RICH data into Local Memory so the UI works instantly without refreshing
        window.students = window.students || [];
        window.students.push(localStudent);

        // 7. 🟢 WHATSAPP NOTIFICATION LOGIC
        const nicelyFormattedDeadline = deadlineDate.toLocaleString('en-GB', { weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute:'2-digit' });
        const schoolName = window.settings?.schoolName || "HAVEN ONLINE";
        const parentPhone = window.formatWhatsAppPhone(data.guardianPhone || '');
        
        const msg = `*CONGRATULATIONS!* 🎉\n\nYour application for *${cloudStudent.name}* at ${schoolName} has been *APPROVED*.\n\n*Student ID:* ${studentId}\n*Amount Due:* $${startingBalance.toFixed(2)}\n*Payment Deadline:* ${nicelyFormattedDeadline}\n\nYou can now log in to the Parent Portal using your new Student ID or your original Application Reference (*${app.id}*) to submit your payment.`;
        
        const waLink = `https://wa.me/${parentPhone}?text=${encodeURIComponent(msg)}`;

        alert(`✅ Enrollment Approved!\n\nID: ${studentId}\nOpening WhatsApp for notification...`);
        
        window.open(waLink, '_blank'); 

        // 8. Refresh UI
        if (typeof window.openPendingApplications === 'function') window.openPendingApplications();
        if (typeof window.renderTable === 'function') window.renderTable(); // Update student directory

    } catch (error) {
        console.error("Approval Error:", error);
        alert("⚠️ Error: " + error.message);
    }
};

// ==========================================
// 50. ECOCASH VERIFICATION ENGINE
// ==========================================

// ==========================================
// 💰 SECURE ECO-CASH VERIFICATION & LEDGER ENGINE
// ==========================================

window.verifyEcoCashPayment = async function() {
    // 1. Security Check
    const role = window.currentUser?.role || "";
    if (!(role.includes('Level 2') || role.includes('Level 3') || role === 'Admin' || role === 'Chief Admin')) {
        return alert("❌ Access Denied: Only Admins can officially verify EcoCash settlements.");
    }

    if (!navigator.onLine) return alert("⚠️ You must be online to verify EcoCash payments and update the cloud ledger.");

    // 2. Identify Student
    const studentId = prompt("Enter Student ID (e.g., STU-1234):");
    if (!studentId) return;

    const student = window.students.find(s => String(s.id).toUpperCase() === studentId.toUpperCase());
    if (!student) return alert("❌ Student not found in the system.");

    const ecoRef = prompt(`Enter EcoCash Reference Code from your school phone:`);
    if (!ecoRef) return;

    // 3. 🎯 THE FIX: Strict Admission Fee Verification
    // Find exactly what they were charged for Admission so we can enforce it
    const admissionCharge = (student.ledger || []).find(l => l.desc === "Admission Fee");
    const requiredAmount = admissionCharge ? parseFloat(admissionCharge.amount) : 50; 

    const amountPaid = prompt(`💰 VERIFYING ADMISSION PAYMENT\n\nStrict Requirement: The admission fee must be exactly $${requiredAmount}.\n\nEnter amount paid via EcoCash ($):`);
    if (!amountPaid || isNaN(parseFloat(amountPaid))) return;

    const paidNum = parseFloat(amountPaid);
    
    // Enforce the strict amount (no more, no less)
    if (paidNum !== requiredAmount) {
        return alert(`❌ Verification Rejected.\n\nThe admission fee must be EXACTLY $${requiredAmount}. Partial payments or over-payments for admission are strictly not allowed.`);
    }

    // 4. 🎯 THE FIX: Actually update the Ledger and Balance!
    const todayDate = new Date().toISOString().split('T')[0];
    const paymentRecord = {
        id: "PAY-ECO-" + Date.now(),
        date: todayDate,
        type: "payment",
        desc: "EcoCash Payment (Ref: " + ecoRef + ")",
        amount: paidNum
    };

    student.ledger = student.ledger || [];
    student.ledger.push(paymentRecord); // Inject the payment

    // Recalculate their exact balance
    let newBalance = 0;
    student.ledger.forEach(entry => {
        if (entry.type === 'charge') newBalance += parseFloat(entry.amount);
        if (entry.type === 'payment') newBalance -= parseFloat(entry.amount);
    });

    student.balance = newBalance;
    student.enrollment_status = 'active_secured';

    // 5. Lookup the fee structure for their specific class
    const classObj = (window.officialClasses || []).find(c => (c.level || c.name) === (student.class || student.grade)) || {};
    const termFee = classObj.fee || 0;

    try {
        // 6. Push strictly formatted data to Supabase
        const cloudUpdate = {
            ledger: student.ledger,
            balance_owing: newBalance,          // Safe Cloud Label
            enrollment_status: 'active_secured' // Upgrades them from pending
        };

        const { error } = await supabaseClient.from('students').update(cloudUpdate).eq('id', student.id);
        if (error) throw error;

        // 7. 🟢 UPGRADED WHATSAPP NOTIFICATION LOGIC
        const parentPhone = window.formatWhatsAppPhone(student.phone || student.guardianPhone || '');
        const sName = student.name || student.student_name || "the student";
        
        const welcomeMsg = `*ADMISSION SECURED!* ✅\n\nThank you. We have successfully verified your EcoCash payment of $${paidNum} (Ref: ${ecoRef}) for *${sName}*.\n\n*Current Fee Structure (${student.class || student.grade}):*\n- Admission Fee: Paid ($${paidNum})\n- Term Tuition Fee: $${termFee}\n*Outstanding Balance:* $${newBalance.toFixed(2)}\n\n*Next Steps:*\n1. Visit the office for Uniform Fitting.\n2. Pick up the Staff Introduction packet.\n3. Orientation begins next Monday at 08:00 AM.\n\nWelcome to the Haven family!`;
        
        const waLink = `https://wa.me/${parentPhone}?text=${encodeURIComponent(welcomeMsg)}`;

        alert(`✅ Payment Verified!\n\nLedger Updated: -$${paidNum}\nNew Balance: $${newBalance}\n\nOpening WhatsApp Receipt...`);
        
        window.open(waLink, '_blank');

        if (typeof window.renderDirectory === 'function') window.renderDirectory();

    } catch (err) {
        console.error("Verification Error:", err);
        alert("⚠️ Failed to verify in cloud. Please check your internet connection.");
    }
};

