window.printShopReceipt = function(saleData) {
    const isWalkIn = (!saleData.student_id || saleData.student_id === "WALK-IN" || saleData.student_id === "");
    const safeSettings = window.settings || {};
    const schoolName = safeSettings.schoolName || 'HAVEN GAMES & ONLINE';

    let itemsHTML = '';
    let subtotal = 0;

    // 1. Build Cart Items (with V1's detailed mapping & safety fallback)
    if (saleData.cartdetails && saleData.cartdetails.length > 0) {
        itemsHTML = saleData.cartdetails.map(item => {
            let unitPrice = parseFloat(item.price) || 0;
            let qty = parseInt(item.cartQty || item.qty || 1);
            let itemTotal = unitPrice * qty;
            subtotal += itemTotal;
            return `
                <tr>
                    <td style="padding: 3px 0;">${qty}x ${item.name}<br><small style="color:#555;">@ $${unitPrice.toFixed(2)} ea</small></td>
                    <td style="text-align: right; vertical-align: top; padding: 3px 0;">$${itemTotal.toFixed(2)}</td>
                </tr>`;
        }).join('');
    } else {
        // Fallback if cart is empty but sale exists
        itemsHTML = `<tr><td style="padding: 3px 0;">${saleData.item || "Shop Items"}</td><td style="text-align: right;">$${(parseFloat(saleData.amount) || 0).toFixed(2)}</td></tr>`;
        subtotal = parseFloat(saleData.amount) || 0;
    }

    // 2. Multi-currency Payment Details (Merged V1 & V2)
    const discount = parseFloat(saleData.discount) || 0;
    const paidUsd = parseFloat(saleData.usdpaid) || 0;
    const paidZig = parseFloat(saleData.zigpaid) || 0;
    const finalDue = parseFloat(saleData.amount) || (subtotal - discount);
    const totalPaidAmount = parseFloat(saleData.total) || finalDue; // From V2

   // 3. Student Account State Calculator (Corrected to use Master Balance)
    let studentSummaryHtml = "";
    if (!isWalkIn) {
        const student = (window.students || []).find(s => String(s.id) === String(saleData.student_id));
        if (student) {
            
            // 🎯 THE FIX: Use the system's exact master balance calculator, NOT a manual loop
            let finalBalance = 0;
            if (typeof window.calculateStudentBalance === 'function') {
                finalBalance = window.calculateStudentBalance(student);
            } else {
                finalBalance = parseFloat(student.balanceOwing || student.balance_owing || 0);
            }

            let balanceText = "";
            if (finalBalance > 0.01) {
                balanceText = `TOTAL ARREARS: $${finalBalance.toFixed(2)}`;
            } else if (finalBalance < -0.01) {
                balanceText = `ACCOUNT CREDIT: $${Math.abs(finalBalance).toFixed(2)}`;
            } else {
                balanceText = `ACCOUNT BAL: $0.00`;
            }

            studentSummaryHtml = `
                <div class="divider"></div>
                <div style="text-align: center; font-weight: bold; margin-bottom: 5px;">--- ACCOUNT STATE ---</div>
                <div><strong>Name:</strong> ${student.name}</div>
                <div><strong>ID:</strong> ${student.id}</div>
                <div style="margin-top: 5px; font-size: 14px; font-weight: bold;">${balanceText}</div>
            `;
        }
    }

    // 4. Build Final HTML Layout (Merged 80mm Thermal Style + Signature Block)
    const receiptHTML = `
        <html>
        <head>
            <title>Receipt - ${saleData.receipt_no}</title>
            <style>
                * { color: #000 !important; background: #fff !important; -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; filter: none !important; opacity: 1 !important; }
                body { font-family: 'Courier New', Courier, monospace; font-weight: 900; color: #000; max-width: 300px; margin: 0 auto; padding: 10px; font-size: 14px; line-height: 1.35; }
                .center { text-align: center; }
                table { width: 100%; border-collapse: collapse; font-size: 14px; font-weight: 900; margin-bottom: 5px; }
                .divider { border-top: 3px dashed #000; margin: 10px 0; }
                /* V2 Signature Block Styles appended to V1 Thermal Styles */
                .signature-block { margin-top: 20px; text-align: left; }
                .sig-line { border-bottom: 2px solid #000; width: 180px; display: inline-block; margin-bottom: 5px; margin-top: 25px; }
                @media print { body { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; } }
            </style>
        </head>
        <body>
            <div class="center">
                <h2 style="margin: 0 0 5px 0; font-size: 18px;">${schoolName}</h2>
                <div>Uniform & POS Shop</div>
                <div style="font-weight: 900; font-size: 16px; margin: 5px 0; color: #000 !important; text-transform: uppercase;"><strong>Receipt: ${saleData.receipt_no}</strong></div>
                <div>Date: ${saleData.date}</div>
                <div>Student: ${saleData.student_name || saleData.student_id || "Walk-in"}</div>
            </div>
            
            <div class="divider"></div>
            
            <table>
                <tr style="font-weight:bold;"><td>Item</td><td align="right">Total</td></tr>
                ${itemsHTML}
            </table>
            
            <div class="divider"></div>
            
            <table style="font-weight: bold;">
                <tr>
                    <td>Subtotal:</td>
                    <td align="right">$${subtotal.toFixed(2)}</td>
                </tr>
                ${discount > 0 ? `
                <tr>
                    <td>Discount:</td>
                    <td align="right">-$${discount.toFixed(2)}</td>
                </tr>` : ''}
                <tr style="font-size: 15px;">
                    <td style="padding-top: 5px;">TOTAL DUE:</td>
                    <td align="right" style="padding-top: 5px;">$${finalDue.toFixed(2)}</td>
                </tr>
            </table>

            <div class="divider"></div>
            
            <table>
                <tr>
                    <td>Paid USD:</td>
                    <td align="right">$${paidUsd.toFixed(2)}</td>
                </tr>
                <tr>
                    <td>Paid ZiG:</td>
                    <td align="right">${paidZig.toFixed(2)}</td>
                </tr>
                <tr style="font-size: 14px; font-weight: bold;">
                    <td style="padding-top: 5px;">TOTAL PAID:</td>
                    <td align="right" style="padding-top: 5px;">$${totalPaidAmount.toFixed(2)}</td>
                </tr>
                <tr>
                    <td>Method:</td>
                    <td align="right">${saleData.paymentmethod || 'Mixed'}</td>
                </tr>
                ${saleData.credit_applied_amount > 0 ? `
                <tr style="font-weight: 900;">
                    <td>Credit Used:</td>
                    <td align="right">$${saleData.credit_applied_amount.toFixed(2)}</td>
                </tr>
                <tr style="font-size: 11px; font-weight: 900;">
                    <td colspan="2">Paid from overpayment balance</td>
                </tr>` : ''}
                ${saleData.payment_details ? `
                <tr style="font-size: 12px; font-weight: 900; border-top: 1px solid #000; padding-top: 3px;">
                    <td colspan="2"><strong>Details:</strong><br>${saleData.payment_details}</td>
                </tr>` : ''}
            </table>

            ${studentSummaryHtml}

            <!-- V2 Signature Block Integrated into V1 Layout -->
            <div class="divider"></div>
            <div class="signature-block">
                <div><strong>Processed By:</strong> ${window.getReceiptProcessorName(saleData)}</div>
                <div class="sig-line"></div>
                <div style="font-size: 11px; font-weight: 900;">Cashier Signature</div>
            </div>

            <div class="divider"></div>
            <div class="center" style="font-size:11px;">
                Thank you! No Refund Without Receipt.
            </div>
            
            <!-- V1 Safe Browser Print Script -->
            <script>
                window.onload = function() { 
                    window.print(); 
                    setTimeout(() => { window.close(); }, 500); 
                };
            </script>
        </body>
        </html>
    `;

    // 5. Open and Print
    const printWindow = window.open('', '_blank', 'width=400,height=600');
    if (!printWindow) return alert('Please allow pop-ups to print this saved shop receipt.');
    printWindow.document.open();
    printWindow.document.write(receiptHTML);
    printWindow.document.close();
};

