window.showSettingsTab = function(tabId) {
    console.log(`📂 Switching to Settings Tab: ${tabId}`);

    // 🛡️ Level 2 may only view Fee Structures and Announcements in Settings (Danger Zone/wipe stays chief-admin-only regardless)
    const normalizedRole = window.getNormalizedRole(window.currentUser && window.currentUser.role);
    if (normalizedRole === 'Level 2' && !tabId.toLowerCase().includes('announce') && !tabId.toLowerCase().includes('fee')) {
        tabId = 'setTabFees';
    }

    // 1. HIDE EVERYTHING FIRST (Both Modern and Legacy styles)
    document.querySelectorAll('.settings-content').forEach(c => {
        c.style.display = 'none';
        c.classList.remove('active');
    });
    
    const allPossiblePanels = [
        'setTabSchool', 'setTabFees', 'setTabStaff', 'setTabAnnounce', 
        'schoolIdentity', 'feeStructure', 'staffManagement', 'announcementsTab', 'announcement'
    ];
    allPossiblePanels.forEach(id => {
        const el = document.getElementById(id);
        if (el) {
            el.style.display = 'none';
            el.classList.remove('active');
        }
    });

    // 2. CLEAR BUTTON STATES
    document.querySelectorAll('.settings-nav button, .tab-btn').forEach(b => {
        b.classList.remove('active');
        b.style.background = ''; // Clear inline colors
    });

    // 3. SMART RESOLVER: Figure out which of the 4 tabs they want
    let targetId = tabId;
    let colorHex = '#95a5a6';

    if (tabId.toLowerCase().includes('school') || tabId.toLowerCase().includes('identity')) {
        targetId = document.getElementById('schoolIdentity') ? 'schoolIdentity' : 'setTabSchool';
        colorHex = '#27ae60';
        if (typeof window.updateSchoolDisplay === 'function') window.updateSchoolDisplay();
        
        // 🛠️ THE FIX: Force the class tables to draw themselves every time you open this tab!
        if (typeof window.renderCustomClasses === 'function') window.renderCustomClasses();
        if (typeof window.loadAdminClassRules === 'function') window.loadAdminClassRules();
        
    } else if (tabId.toLowerCase().includes('fee')) {
        targetId = document.getElementById('feeStructure') ? 'feeStructure' : 'setTabFees';
        colorHex = '#2980b9';
        if (typeof window.renderFeeStructures === 'function') window.renderFeeStructures();
        
    } else if (tabId.toLowerCase().includes('staff') || tabId.toLowerCase().includes('manage')) {
        targetId = document.getElementById('staffManagement') ? 'staffManagement' : 'setTabStaff';
        colorHex = '#8e44ad';
        if (typeof window.renderStaffList === 'function') window.renderStaffList();
        
    } else if (tabId.toLowerCase().includes('announce')) {
        targetId = document.getElementById('announcementsTab') ? 'announcementsTab' : (document.getElementById('announcement') ? 'announcement' : 'setTabAnnounce');
        colorHex = '#f39c12';
        if (typeof window.renderAnnouncements === 'function') window.renderAnnouncements();
    }

    // 4. SHOW THE CORRECT PANEL
    const targetPanel = document.getElementById(targetId);
    if (targetPanel) {
        targetPanel.style.display = 'block';
        targetPanel.classList.add('active');
        console.log(`✅ Successfully opened: ${targetId}`);
    } else {
        console.error(`❌ UI Error: Could not find HTML panel for "${tabId}". Check your index.html IDs.`);
    }

    // 5. HIGHLIGHT THE CORRECT BUTTON
    const clickedBtn = Array.from(document.querySelectorAll('.settings-nav button, .tab-btn')).find(btn => 
        (btn.getAttribute('onclick') && btn.getAttribute('onclick').includes(tabId))
    );
    
    if (clickedBtn) {
        clickedBtn.classList.add('active');
        // If your HTML relies on legacy inline colors, apply them:
        if (!clickedBtn.classList.contains('active')) {
            clickedBtn.style.background = colorHex;
        }
    }
};

