window.renderAnnouncements = async function() {
    const list = document.getElementById('parentAnnouncementList');
    if (!list) return;

    // Show loading text while fetching from the cloud
    list.innerHTML = '<em style="color:#7f8c8d;">Loading announcements...</em>';

    try {
        // 1. Fetch fresh data directly from the Supabase cloud
        const { data, error } = await window.supabaseClient
            .from('announcements')
            .select('*')
            .order('posted', { ascending: false });

        if (error) throw error;

        // 2. Handle Empty State
        if (!data || data.length === 0) {
            list.innerHTML = '<div style="text-align:center; padding:20px; color:#7f8c8d; background:#f9f9f9; border-radius:5px;">No active announcements at this time.</div>';
            return;
        }

        // 3. Loop through the cloud data (Parent UI - NO DELETE BUTTONS)
        let html = '';
        data.forEach(a => {
            html += `
                <div style="background: #ffffff; border: 1px solid #e0e6ed; padding: 15px; border-radius: 8px; margin-bottom: 15px; box-shadow: 0 2px 5px rgba(0,0,0,0.02); border-left: 4px solid #3498db;">
                    <strong style="color:#2c3e50; font-size:16px; display:block; margin-bottom:4px;">${a.title}</strong>
                    <div style="font-size:12px; color:#e67e22; font-weight:bold; margin-bottom:8px;">${a.type} | Date: ${a.date}</div>
                    <p style="font-size:14px; color:#555; margin:0; line-height:1.5;">${a.desc}</p>
                </div>
            `;
        });

        // 4. Inject the HTML into the Parent Screen
        list.innerHTML = html;

    } catch (err) {
        console.error("Failed to render parent announcements:", err);
        list.innerHTML = '<em style="color:#c0392b;">Error loading announcements. Please close and reopen.</em>';
    }
};

