window.loadGlobalSettings = async function() {
    // 1. Attempt to fetch fresh relational data from the cloud
    if (navigator.onLine && typeof window.supabaseClient !== 'undefined') {
        try {
            const { data, error } = await window.supabaseClient
                .from('global_settings')
                .select('*')
                .eq('id', 'master_settings')
                .single();

            if (error) {
                if (error.code === 'PGRST116') {
                    console.warn("No master_settings row found in database yet. Using local/defaults.");
                } else {
                    throw error;
                }
            }

            if (data) {
                window.settings = window.settings || {};

                // 2. Map SQL snake_case to JS camelCase
                window.settings.foodFee = parseFloat(data.food_fee) || 0;
                window.settings.stationeryFeeECD = parseFloat(data.stationery_fee_ecd) || 0;
                window.settings.stationeryFeeGrades = parseFloat(data.stationery_fee_grades) || 0;
                window.settings.textbookFee = parseFloat(data.textbook_fee_grade) || 0;
                window.settings.admissionFeeECD = parseFloat(data.admission_fee_ecd) || 0;
                window.settings.admissionFeeGrades = parseFloat(data.admission_fee_grades) || 0;

                // 3. Nest the transport fares perfectly for your UI logic
                window.settings.transportFares = {
                    zoneA: parseFloat(data.trans_zone_a_full) || 0,
                    zoneAOneWay: parseFloat(data.trans_zone_a_one_way) || 0,
                    zoneB: parseFloat(data.trans_zone_b_full) || 0,
                    zoneBOneWay: parseFloat(data.trans_zone_b_one_way) || 0,
                    zoneC: parseFloat(data.trans_zone_c_full) || 0,
                    zoneCOneWay: parseFloat(data.trans_zone_c_one_way) || 0,
                    zoneD: parseFloat(data.trans_zone_d_full) || 0,
                    zoneDOneWay: parseFloat(data.trans_zone_d_one_way) || 0,
                    zoneE: parseFloat(data.trans_zone_e_full) || 0,
                    zoneEOneWay: parseFloat(data.trans_zone_e_one_way) || 0,
                    zoneF: parseFloat(data.trans_zone_f_full) || 0,
                    zoneFOneWay: parseFloat(data.trans_zone_f_one_way) || 0
                };

                console.log("✅ Global settings successfully synced and built from cloud.");
                
                // 4. Save to local storage for offline use
                localStorage.setItem('haven_settings', JSON.stringify(window.settings));
                
                // 5. Trigger UI updates
                if (typeof window.populateAllSettingsUI === 'function') window.populateAllSettingsUI();
                if (typeof window.populateSettingsUI === 'function') window.populateSettingsUI();
                
                // BUG FIX #1: Tell the Enrollment Dropdown to build itself!
                if (typeof window.populateTransportDropdown === 'function') window.populateTransportDropdown();
                
                // Optional: Trigger enrollment preview if a grade is already selected
                if (document.getElementById('regGrade')?.value && typeof window.previewEnrollmentFees === 'function') {
                    window.previewEnrollmentFees();
                }
                
                return; // Exit function successfully
            }
        } catch (error) {
            console.warn("⚠️ Cloud fetch failed. Checking local storage fallback...", error.message);
        }
    }

    // 6. Offline / Fallback mode: Load from localStorage if the cloud fails
    const localSettings = localStorage.getItem('haven_settings');
    if (localSettings) {
        window.settings = JSON.parse(localSettings);
        console.log("📂 Global settings loaded from local storage (Offline Mode).");
        
        if (typeof window.populateAllSettingsUI === 'function') window.populateAllSettingsUI();
        if (typeof window.populateSettingsUI === 'function') window.populateSettingsUI();
        
        // BUG FIX #1 (Offline mode): Tell the Enrollment Dropdown to build itself
        if (typeof window.populateTransportDropdown === 'function') window.populateTransportDropdown();
    } else {
        window.settings = {}; 
    }
};

window.populateSettingsUI = function() {
    if (!window.settings) return;

    // 🛡️ Helper function to safely fill inputs even if HTML IDs differ
    const setVal = (value, id1, id2, id3) => {
        const el = document.getElementById(id1) || document.getElementById(id2) || document.getElementById(id3);
        if (el) el.value = value > 0 ? value : ''; // Leave blank if 0 for cleaner UI
    };

    // Fill Standard Fees
    setVal(window.settings.foodFee, 'tblFoodFee', 'foodFee', 'setFoodFee');
    setVal(window.settings.stationeryFeeECD, 'tblStatECD', 'statECD', 'stationeryECD');
    setVal(window.settings.stationeryFeeGrades, 'tblStatGrades', 'statGrades', 'stationeryGrades');
    setVal(window.settings.textbookFee, 'tblTextbook', 'textbookFee', 'textbook');
    setVal(window.settings.admissionFeeECD, 'tblAdmECD', 'admissionFeeECD', 'admECD');
    setVal(window.settings.admissionFeeGrades, 'tblAdmGrades', 'admissionFeeGrades', 'admGrades');
    
    // Fill Calendar (Unchanged)
    if (window.settings.calendar) {
        if (document.getElementById('calTerm1Start')) document.getElementById('calTerm1Start').value = window.settings.calendar.term1.start || '';
        if (document.getElementById('calTerm1End')) document.getElementById('calTerm1End').value = window.settings.calendar.term1.end || '';
        if (document.getElementById('calTerm2Start')) document.getElementById('calTerm2Start').value = window.settings.calendar.term2.start || '';
        if (document.getElementById('calTerm2End')) document.getElementById('calTerm2End').value = window.settings.calendar.term2.end || '';
        if (document.getElementById('calTerm3Start')) document.getElementById('calTerm3Start').value = window.settings.calendar.term3.start || '';
        if (document.getElementById('calTerm3End')) document.getElementById('calTerm3End').value = window.settings.calendar.term3.end || '';
    }
    
    // BUG FIX #2 & #3: Fill Transport Fares using the safe IDs and include One-Way
    if (window.settings.transportFares) {
        const t = window.settings.transportFares;
        
        setVal(t.zoneA, 'tblTransA', 'zoneA', 'transA');
        setVal(t.zoneAOneWay, 'tblTransAOneWay', 'zoneAOneWay', 'transAOneWay');
        
        setVal(t.zoneB, 'tblTransB', 'zoneB', 'transB');
        setVal(t.zoneBOneWay, 'tblTransBOneWay', 'zoneBOneWay', 'transBOneWay');
        
        setVal(t.zoneC, 'tblTransC', 'zoneC', 'transC');
        setVal(t.zoneCOneWay, 'tblTransCOneWay', 'zoneCOneWay', 'transCOneWay');
        
        setVal(t.zoneD, 'tblTransD', 'zoneD', 'transD');
        setVal(t.zoneDOneWay, 'tblTransDOneWay', 'zoneDOneWay', 'transDOneWay');
        
        setVal(t.zoneE, 'tblTransE', 'zoneE', 'transE');
        setVal(t.zoneEOneWay, 'tblTransEOneWay', 'zoneEOneWay', 'transEOneWay');
        
        setVal(t.zoneF, 'tblTransF', 'zoneF', 'transF');
        setVal(t.zoneFOneWay, 'tblTransFOneWay', 'zoneFOneWay', 'transFOneWay');
    }
};

// ==========================================
// 2. MAIN INITIALIZATION FUNCTION
// ==========================================

const cloudFetchQueue = [];
let activeCloudFetches = 0;
const MAX_CONCURRENT_CLOUD_FETCHES = 4;

function withCloudFetchSlot(request) {
    return new Promise((resolve, reject) => {
        cloudFetchQueue.push({ request, resolve, reject });

        const startQueuedFetches = () => {
            while (activeCloudFetches < MAX_CONCURRENT_CLOUD_FETCHES && cloudFetchQueue.length > 0) {
                const queuedFetch = cloudFetchQueue.shift();
                activeCloudFetches++;
                Promise.resolve()
                    .then(queuedFetch.request)
                    .then(queuedFetch.resolve, queuedFetch.reject)
                    .finally(() => {
                        activeCloudFetches--;
                        startQueuedFetches();
                    });
            }
        };

        startQueuedFetches();
    });
}

window.fetchCompleteCloudTable = async function(tableName, pageSize = 1000, orderColumn = 'id') {
    const startedAt = performance.now();
    if (!window.supabaseClient) throw new Error('Supabase client is not connected.');
    if (!Number.isInteger(pageSize) || pageSize < 1) throw new Error('Cloud page size must be a positive integer.');

    const firstPage = await withCloudFetchSlot(() => window.supabaseClient
        .from(tableName)
        .select('*', { count: 'exact' })
        .order(orderColumn, { ascending: true })
        .range(0, pageSize - 1));

    if (firstPage.error) throw firstPage.error;
    if (firstPage.count === null || firstPage.count === undefined) {
        throw new Error(`Could not verify the total row count for ${tableName}.`);
    }

    const expectedCount = firstPage.count;
    const rows = firstPage.data || [];
    if (rows.length !== Math.min(pageSize, expectedCount)) throw new Error(`${tableName} changed while it was downloading.`);
    const getRowKey = row => {
        const value = row[orderColumn];
        return value === null || value === undefined || String(value).trim() === ''
            ? JSON.stringify(row)
            : String(value);
    };
    const downloadedKeys = new Set(rows.map(getRowKey));
    if (downloadedKeys.size !== rows.length) {
        throw new Error(`The ${tableName} download contains missing or repeated page keys.`);
    }

    const pageCount = Math.ceil(expectedCount / pageSize);
    const concurrentPages = 3;
    for (let firstPageIndex = 1; firstPageIndex < pageCount; firstPageIndex += concurrentPages) {
        const pageIndexes = Array.from(
            { length: Math.min(concurrentPages, pageCount - firstPageIndex) },
            (_, index) => firstPageIndex + index
        );
        const pages = await Promise.all(pageIndexes.map(async pageIndex => {
            const offset = pageIndex * pageSize;
            const { data, error } = await withCloudFetchSlot(() => window.supabaseClient
                .from(tableName)
                .select('*')
                .order(orderColumn, { ascending: true })
                .range(offset, offset + pageSize - 1));

            if (error) throw error;
            const expectedPageLength = Math.min(pageSize, expectedCount - offset);
            if (!data || data.length !== expectedPageLength) {
                throw new Error(`The ${tableName} download ended before all rows arrived. Please retry.`);
            }
            return data;
        }));

        for (const page of pages) {
            for (const row of page) {
                const key = getRowKey(row);
                if (downloadedKeys.has(key)) throw new Error(`The ${tableName} download repeated or missed records. Please retry.`);
                downloadedKeys.add(key);
            }
            rows.push(...page);
        }
    }

    const verification = await withCloudFetchSlot(() => window.supabaseClient
        .from(tableName)
        .select(orderColumn, { count: 'exact', head: true }));

    if (verification.error) throw verification.error;
    if (verification.count !== expectedCount || rows.length !== expectedCount || downloadedKeys.size !== expectedCount) {
        throw new Error(`The ${tableName} download is incomplete. Please retry.`);
    }

    const elapsedSeconds = ((performance.now() - startedAt) / 1000).toFixed(1);
    console.info(`[Cloud startup] ${tableName}: verified ${rows.length} rows in ${elapsedSeconds}s`);
    const startupProgress = window.startupLoadProgress;
    if (startupProgress && startupProgress.active &&
        startupProgress.generation === window.appInitializationGeneration) {
        startupProgress.completed = Math.min(startupProgress.total, startupProgress.completed + 1);
        const percentage = 20 + Math.round((startupProgress.completed / startupProgress.total) * 60);
        window.updateLoadingStatus(
            `Verified ${startupProgress.completed} of ${startupProgress.total} school data sets...`,
            percentage
        );
    }

    return rows;
};

window.logActivity = async function(action, details = "") {
    if (!window.currentUser || !window.supabaseClient) return;
    
    const auditData = {
        user: window.currentUser.username || window.currentUser.user || "Unknown",
        role: window.currentUser.role || "Unknown",
        action_type: action,
        details: details,
        created_at: new Date().toISOString()
    };

    try {
        const { error } = await window.supabaseClient.from('audit_logs').insert([auditData]);
        if (error) {
            const detail = [error.message, error.details, error.hint].filter(Boolean).join(' | ');
            console.warn("Audit Log Failed:", detail || error);
        }
    } catch (e) {
        console.warn("Audit Log Failed:", e);
    }
};

window.recordVisit = async function(user, role, activity, viewed) {
    const deviceType = /Mobi|Android|iPhone|iPad|iPod|Windows Phone/i.test(navigator.userAgent)
        ? 'Mobile'
        : 'Desktop';
    const cleanViewed = String(viewed || '').trim();
    const signature = [
        String(user || 'Unknown').trim(),
        String(role || 'Unknown').trim(),
        String(activity || 'Page View').trim(),
        cleanViewed
    ].join('|');

    window.visitRecordSignatures = window.visitRecordSignatures || new Map();
    const nowMs = Date.now();
    const previousMs = window.visitRecordSignatures.get(signature);
    if (previousMs && nowMs - previousMs < 3000) return;
    window.visitRecordSignatures.set(signature, nowMs);

    const record = {
        user: String(user || 'Unknown'),
        role: String(role || 'Unknown'),
        action_type: String(activity || 'Page View'),
        details: cleanViewed
            ? `${deviceType} - ${cleanViewed}`
            : `${deviceType} - System visit`,
        created_at: new Date().toISOString()
    };

    try {
        const localRecords = JSON.parse(localStorage.getItem('haven_visit_logs') || '[]');
        localRecords.unshift(record);
        localStorage.setItem('haven_visit_logs', JSON.stringify(localRecords.slice(0, 5000)));
    } catch (e) {
        console.warn('Could not cache visit record:', e);
    }

    if (window.supabaseClient) {
        try {
            await window.supabaseClient.from('audit_logs').insert([record]);
        } catch (e) {
            console.warn('Could not save visit record to cloud:', e);
        }
    }
};

window.loadVisitLog = async function() {
    const tbody = document.getElementById('visitLogTableBody');
    if (tbody) tbody.innerHTML = '<tr><td colspan="5" style="padding:20px;text-align:center;color:#64748b;">Loading records...</td></tr>';

    let cloudRecords = [];
    if (window.supabaseClient) {
        try {
            const { data, error } = await window.supabaseClient
                .from('audit_logs')
                .select('user,role,action_type,details,created_at')
                .or('action_type.eq.System Visit,action_type.eq.Parent Login,action_type.eq.Page View,action_type.eq.Parent Page View')
                .order('created_at', { ascending: false })
                .limit(1000);
            if (!error && Array.isArray(data)) cloudRecords = data;
        } catch (e) {
            console.warn('Could not load cloud visit records:', e);
        }
    }

    let localRecords = [];
    try {
        localRecords = JSON.parse(localStorage.getItem('haven_visit_logs') || '[]');
    } catch (_) {}

    const merged = [...cloudRecords];
    localRecords.forEach(record => {
        const duplicate = merged.some(item =>
            item.created_at === record.created_at &&
            item.user === record.user &&
            item.action_type === record.action_type
        );
        if (!duplicate) merged.push(record);
    });
    const seenVisits = new Set();
    window.visitLogRecords = merged
        .filter(record => ['System Visit', 'Parent Login', 'Page View', 'Parent Page View'].includes(record.action_type))
        .filter(record => {
            const time = new Date(record.created_at).getTime();
            const timeBucket = Number.isFinite(time) ? Math.floor(time / 3000) : 'unknown';
            const key = [
                String(record.user || '').trim(),
                String(record.role || '').trim(),
                String(record.action_type || '').trim(),
                String(record.details || '').replace(/^(Mobile|Desktop)\s+-\s+/i, '').trim(),
                timeBucket
            ].join('|');
            if (seenVisits.has(key)) return false;
            seenVisits.add(key);
            return true;
        })
        .sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
    window.renderVisitLog();
};

window.renderVisitLog = function() {
    const records = window.visitLogRecords || [];
    const search = (document.getElementById('visitLogSearch')?.value || '').trim().toLowerCase();
    const role = document.getElementById('visitLogRole')?.value || '';
    const date = document.getElementById('visitLogDate')?.value || '';

    const filtered = records.filter(record => {
        const recordRole = record.role || '';
        const roleMatches = !role ||
            (role === 'Parent' ? recordRole === 'Parent' : recordRole === role);
        const haystack = [record.user, record.role, record.action_type, record.details].join(' ').toLowerCase();
        const searchMatches = !search || haystack.includes(search);
        const dateMatches = !date || String(record.created_at || '').startsWith(date);
        return roleMatches && searchMatches && dateMatches;
    });

    const visitRecords = records.filter(record =>
        record.action_type === 'System Visit' || record.action_type === 'Parent Login'
    );
    document.getElementById('visitLogParentVisits').textContent =
        visitRecords.filter(record => record.role === 'Parent').length;
    document.getElementById('visitLogAdminVisits').textContent =
        visitRecords.filter(record => record.role && record.role !== 'Parent').length;
    document.getElementById('visitLogPageViews').textContent =
        records.filter(record => record.action_type === 'Page View' || record.action_type === 'Parent Page View').length;

    const tbody = document.getElementById('visitLogTableBody');
    if (!tbody) return;
    if (!filtered.length) {
        tbody.innerHTML = '<tr><td colspan="5" style="padding:20px;text-align:center;color:#64748b;">No visit records found.</td></tr>';
        return;
    }

    const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g, char => ({
        '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    })[char]);

    tbody.innerHTML = filtered.map(record => {
        const dateText = record.created_at
            ? new Date(record.created_at).toLocaleString()
            : 'Unknown';
        return `<tr>
            <td style="padding:10px;border-bottom:1px solid #e2e8f0;">${escapeHtml(dateText)}</td>
            <td style="padding:10px;border-bottom:1px solid #e2e8f0;font-weight:bold;">${escapeHtml(record.user)}</td>
            <td style="padding:10px;border-bottom:1px solid #e2e8f0;">${escapeHtml(record.role)}</td>
            <td style="padding:10px;border-bottom:1px solid #e2e8f0;">${escapeHtml(record.action_type)}</td>
            <td style="padding:10px;border-bottom:1px solid #e2e8f0;">${escapeHtml(record.details)}</td>
        </tr>`;
    }).join('');
};

window.initializeApp = async function() {
    window.appInitializationGeneration = (window.appInitializationGeneration || 0) + 1;
    const initializationGeneration = window.appInitializationGeneration;
    const initializationStartedAt = performance.now();
    console.log("🚀 Haven Cloud Sync: Starting Full System Initialization...");
    window.appDataReady = false;
    window.startupLoadProgress = null;
    window.__hasCachedCore = false;
    if (typeof window.setAppDataInteractivity === 'function') window.setAppDataInteractivity(false);

    // Open immediately from verified local core records while fresh cloud data refreshes.
    try {
        const cachedStudents = JSON.parse(localStorage.getItem('haven_cached_students') || '[]');
        if (Array.isArray(cachedStudents) && cachedStudents.length > 0) {
            let cachedPayments = [];
            let cachedLedger = [];
            try {
                const storedLedger = JSON.parse(localStorage.getItem('haven_cached_student_ledger') || '[]');
                const storedPayments = JSON.parse(localStorage.getItem('haven_cached_payments') || '[]');
                cachedLedger = Array.isArray(storedLedger) ? storedLedger : [];
                cachedPayments = Array.isArray(storedPayments) ? storedPayments : [];
            } catch (_) {}
            const ledgersByStudent = new Map();
            cachedLedger.forEach(entry => {
                const studentKey = String(entry.student_id || '');
                if (!ledgersByStudent.has(studentKey)) ledgersByStudent.set(studentKey, []);
                ledgersByStudent.get(studentKey).push(entry);
            });
            window.students = cachedStudents.map(record => ({
                ...record,
                ledger: ledgersByStudent.get(String(record.id)) || record.ledger || []
            }));
            window.payments = cachedPayments;
            window.__coreLedgerCache = cachedLedger;
            window.__hasCachedCore = true;
            window.appDataReady = true;
            if (typeof window.setAppDataInteractivity === 'function') window.setAppDataInteractivity(true);
            if (typeof window.updateLoadingStatus === 'function') {
                window.updateLoadingStatus('Core cached records ready. Verifying current cloud records...', 35);
            }
        }
    } catch (cacheError) {
        console.warn('Could not restore core cache:', cacheError);
    }
    
    try {
        window.updateLoadingStatus("Connecting to cloud database...", 5);
        if (!navigator.onLine) throw new Error('An active internet connection is required to verify all data.');

        // 0. PURGE STALE CACHES
        // Force the system to rely ONLY on fresh cloud data for financials
        window.transactions = [];
        localStorage.removeItem('havenTransactions');
        localStorage.removeItem('haven_payments');
        if (typeof window.supabaseClient === 'undefined') {
            throw new Error("Supabase Client not connected.");
        }

        // 🌟 STEP 1: WAKE SYSTEM & FETCH SETTINGS 🌟
        if (typeof window.updateLoadingStatus === 'function') window.updateLoadingStatus("Fetching Identity & Settings...", 20);
        
        // Instant local storage fallback so UI never flashes empty
        try {
            const localSettings = localStorage.getItem('haven_settings');
            if (localSettings) window.settings = JSON.parse(localSettings);
        } catch (e) { console.warn("Local settings parse error:", e); }

        try {
    // 1. Fetch the data from global_settings
    let { data: cloudRow, error: newErr } = await Promise.race([
        window.supabaseClient
        .from('global_settings')
        .select('*')
        .eq('id', 'master_settings') 
        .maybeSingle(),
        new Promise((_, reject) => setTimeout(() => reject(new Error('Settings connection timed out')), 12000))
    ]);

    if (initializationGeneration !== window.appInitializationGeneration) return;

    // 2. Map the flat database columns directly to window.settings
    if (cloudRow) {
        window.settings = {
            ...window.settings,
            foodFee: cloudRow.food_fee,
            stationeryFeeECD: cloudRow.stationery_fee_ecd,
            admissionFeeGrades: cloudRow.admission_fee_grades,
            stationeryFeeGrades: cloudRow.stationery_fee_grades,
            textbookFeeGrade: cloudRow.textbook_fee_grade,
            admissionFeeECD: cloudRow.admission_fee_ecd,
            transZoneAFull: cloudRow.trans_zone_a_full,
            transZoneAOneWay: cloudRow.trans_zone_a_one_way,
            transZoneBFull: cloudRow.trans_zone_b_full,
            transZoneBOneWay: cloudRow.trans_zone_b_one_way,
            transZoneCFull: cloudRow.trans_zone_c_full,
            transZoneCOneWay: cloudRow.trans_zone_c_one_way,
            transZoneDFull: cloudRow.trans_zone_d_full,
            transZoneDOneWay: cloudRow.trans_zone_d_one_way,
            transZoneEFull: cloudRow.trans_zone_e_full,
            transZoneEOneWay: cloudRow.trans_zone_e_one_way,
            transZoneFFull: cloudRow.trans_zone_f_full,
            transZoneFOneWay: cloudRow.trans_zone_f_one_way
        };
    }

    if (newErr) throw newErr;
    if (typeof window.updateHeartbeatUI === 'function') window.updateHeartbeatUI('ONLINE');

    // 4. Extract any legacy JSON properties, sync to localStorage, and update UI
    if (cloudRow) {
        const extracted = cloudRow.settings?.settings || cloudRow.settings || cloudRow.data || {};
        window.settings = { ...window.settings, ...extracted };
        window.staff = extracted.staff || window.staff || [];
        window.announcements = extracted.announcements || window.announcements || [];
        if (!window.settings.schoolName && extracted.schoolName) window.settings.schoolName = extracted.schoolName;
        
        localStorage.setItem('haven_settings', JSON.stringify(window.settings));
        console.log("☁️ Global settings loaded from cloud successfully!");
        
        if (typeof window.populateAllSettingsUI === 'function') window.populateAllSettingsUI();
        if (typeof window.populateSettingsUI === 'function') window.populateSettingsUI();
    } else {
        console.log("No cloud settings found. Using local/default settings.");
    }

} catch (err) { 
    console.error("Could not verify master settings from cloud:", err);
    if (typeof window.updateHeartbeatUI === 'function') {
        window.updateHeartbeatUI(navigator.onLine ? 'RETRYING' : 'OFFLINE');
    }
}

        if (!window.settings) window.settings = {};
        if (!window.settings.schoolName) window.settings.schoolName = "Gudlance Preparatory";
        
        const enrollToggle = document.getElementById('indepOnlineEnrollToggle');
        if (enrollToggle) enrollToggle.checked = !!window.settings.enrollmentOpen;
        const pubEnrollBtn = document.getElementById('btnApplyOnlinePublic');
        if (pubEnrollBtn) pubEnrollBtn.style.display = window.settings.enrollmentOpen ? 'block' : 'none';

        // Independent datasets are fetched together; the shared cloud queue caps network concurrency.
        const cachedLoginUsers = Array.isArray(window.loginCloudUsers) ? window.loginCloudUsers : null;
        window.loginCloudUsers = null;
        const fetchTable = async (table, globalVar, storageKey) => {
            const data = await window.fetchCompleteCloudTable(table);
            if (initializationGeneration !== window.appInitializationGeneration) return;
            const normalizedData = data.map(row => row.data ? row.data : row);
            window[globalVar] = normalizedData;
            if (storageKey) localStorage.setItem(storageKey, JSON.stringify(window[globalVar]));
            return normalizedData;
        };
        const fetchGroup = async requests => {
            const results = await Promise.allSettled(requests);
            const failure = results.find(result => result.status === 'rejected');
            if (failure) throw failure.reason;
            return results.map(result => result.value);
        };

        window.startupLoadProgress = {
            active: true,
            completed: cachedLoginUsers ? 1 : 0,
            total: 11,
            generation: initializationGeneration
        };
        if (typeof window.updateLoadingStatus === 'function') {
            window.updateLoadingStatus('Loading students, ledger, and payments...', 20);
        }

        const isPhone = /Mobi|Android|iPhone|iPad|iPod|Windows Phone/i.test(navigator.userAgent);
        let studentData, ledgerData, paymentData;

        if (isPhone) {
            const fetchPhoneCore = async (tableName, orderColumn = 'id') => {
                const { data, error } = await window.supabaseClient
                    .from(tableName)
                    .select('*')
                    .order(orderColumn, { ascending: false })
                    .range(0, 1999);
                if (error) throw error;
                return data || [];
            };

            try {
                [studentData, ledgerData, paymentData] = await Promise.race([
                    Promise.all([
                        fetchPhoneCore('students', 'id'),
                        fetchPhoneCore('student_ledger', 'date'),
                        fetchPhoneCore('payments', 'created_at')
                    ]),
                    new Promise((_, reject) => setTimeout(
                        () => reject(new Error('Phone core cloud connection timed out')),
                        18000
                    ))
                ]);
            } catch (phoneCoreError) {
                console.warn('Phone cloud core refresh failed; retaining usable cached records:', phoneCoreError);
                studentData = window.students.map(student => ({
                    id: student.id,
                    name: student.name,
                    grade: student.grade,
                    gender: student.gender,
                    address: student.address,
                    phone: student.phone,
                    dob: student.dob,
                    enroll_date: student.enrollDate,
                    payment_deadline: student.paymentDeadline,
                    billing_plan: student.billingPlan,
                    balance_owing: student.balanceOwing,
                    transport_tier: student.transportTier,
                    transport_mode: student.transportMode,
                    driver: student.driver,
                    food_program: student.foodProgram,
                    stationery_pack: student.stationeryPack,
                    textbooks: student.textbooks,
                    status: student.enrollmentStatus
                }));
                ledgerData = window.__coreLedgerCache || [];
                paymentData = window.payments || [];
            }
        } else {
            [studentData, ledgerData, paymentData] = await fetchGroup([
                window.fetchCompleteCloudTable('students'),
                window.fetchCompleteCloudTable('student_ledger'),
                fetchTable('payments', 'payments', 'haven_payments')
            ]);
        }
        if (initializationGeneration !== window.appInitializationGeneration) return;

        if (isPhone && window.__hasCachedCore) {
            const cachedById = new Map((window.students || []).map(student => [String(student.id), student]));
            studentData.forEach(record => {
                const existing = cachedById.get(String(record.id));
                cachedById.set(String(record.id), { ...existing, ...record });
            });
            studentData = Array.from(cachedById.values());

            const ledgerById = new Map((window.__coreLedgerCache || []).map(entry => [String(entry.id), entry]));
            ledgerData.forEach(entry => ledgerById.set(String(entry.id), entry));
            ledgerData = Array.from(ledgerById.values());

            const paymentById = new Map((window.payments || []).map(entry => [String(entry.id), entry]));
            paymentData.forEach(entry => paymentById.set(String(entry.id), entry));
            paymentData = Array.from(paymentById.values());
        }

        // Make student, ledger, and payment data available before loading other sections.
        const ledgersByStudent = new Map();
        ledgerData.forEach(entry => {
            const studentKey = String(entry.student_id || '');
            if (!ledgersByStudent.has(studentKey)) ledgersByStudent.set(studentKey, []);
            ledgersByStudent.get(studentKey).push(entry);
        });
        window.students = studentData.map(record => ({
                id: record.id,
                name: record.name,
                grade: record.grade,
                gender: record.gender || '',
                address: record.address || '',
                phone: record.phone || record.cell || '', 
                dob: record.dob || '',
                enrollDate: record.enroll_date || record.enrollDate || '',
                paymentDeadline: record.payment_deadline || record.paymentDeadline || '',
                billingPlan: record.billing_plan || record.billingPlan || 'termly',
                balanceOwing: parseFloat(record.balance_owing || record.feesowed || 0),
                
                transportTier: parseFloat(record.transport_tier) || 0,
                transportMode: record.transport_mode || 'full',
                driver: record.driver || '', // 👇 FIX: MAP THE DRIVER TO MEMORY 👇
                
                foodProgram: record.food_program === true || String(record.food_program) === 'true',
                stationeryPack: record.stationery_pack === true || String(record.stationery_pack) === 'true',
                textbooks: record.textbooks === true || String(record.textbooks) === 'true',

                ledger: ledgersByStudent.get(String(record.id)) || [],
                enrollmentStatus: record.status || record.enrollment_status || 'active'
            }));
        window.payments = paymentData;
        try {
            const existingCoreTimes = JSON.parse(localStorage.getItem('haven_core_sync_times') || '{}');
            const now = new Date().toISOString();
            localStorage.setItem('haven_core_sync_times', JSON.stringify({
                ...existingCoreTimes,
                students: now,
                student_ledger: now,
                payments: now
            }));
        } catch (_) {}
        if (initializationGeneration !== window.appInitializationGeneration) return;
        console.log("Data securely loaded! Total students:", window.students.length, "ledger rows:", ledgerData.length);
        // Core data is already stored in memory. Avoid writing large datasets to the
        // 5 MB localStorage quota; this cache must never block cloud startup.
        try {
            const compactStudents = window.students.map(student => ({
                id: student.id,
                name: student.name,
                grade: student.grade,
                gender: student.gender,
                address: student.address,
                phone: student.phone,
                dob: student.dob,
                enrollDate: student.enrollDate,
                paymentDeadline: student.paymentDeadline,
                billingPlan: student.billingPlan,
                balanceOwing: student.balanceOwing,
                transportTier: student.transportTier,
                transportMode: student.transportMode,
                driver: student.driver,
                foodProgram: student.foodProgram,
                stationeryPack: student.stationeryPack,
                textbooks: student.textbooks,
                enrollmentStatus: student.enrollmentStatus
            }));
            localStorage.setItem('haven_cached_students', JSON.stringify(compactStudents));
            localStorage.setItem('haven_cached_student_ledger', JSON.stringify(ledgerData));
            localStorage.setItem('haven_cached_payments', JSON.stringify(paymentData));
            window.__coreLedgerCache = ledgerData;
        } catch (cacheError) {
            try {
                localStorage.removeItem('haven_cached_students');
                localStorage.removeItem('haven_cached_student_ledger');
                localStorage.removeItem('haven_cached_payments');
            } catch (_) {}
            console.warn('Core cache unavailable; continuing with cloud data in memory:', cacheError);
        }

        // Core data is complete: unlock the app without waiting for secondary datasets.
        window.appDataReady = true;
        if (typeof window.setAppDataInteractivity === 'function') window.setAppDataInteractivity(true);
        if (typeof window.updateLoadingStatus === 'function') {
            window.updateLoadingStatus('Students, ledger, and payments ready. Loading remaining sections...', 50);
        }

        if (typeof updateSchoolDisplay === 'function') updateSchoolDisplay();
        if (typeof renderFeeStructures === 'function') renderFeeStructures();
        if (typeof updateStudentTable === 'function') updateStudentTable();
        if (typeof updateDashboard === 'function') updateDashboard();
        if (typeof filterDirectory === 'function') filterDirectory();
        if (typeof populateStudentDatalist === 'function') populateStudentDatalist();
        if (typeof window.refreshLedgerView === 'function') window.refreshLedgerView();

        window.appDataReady = true;
        if (typeof window.setAppDataInteractivity === 'function') window.setAppDataInteractivity(true);
        const pendingNavigation = window.pendingAppNavigation;
        window.pendingAppNavigation = null;
        if (pendingNavigation) window.navTo(pendingNavigation);
        if (typeof window.updateLoadingStatus === 'function') {
            window.updateLoadingStatus('Core records ready. Loading remaining sections...', 50);
        }

        const backgroundLoad = (async () => {
            const attendanceCutoff = new Date();
            attendanceCutoff.setFullYear(attendanceCutoff.getFullYear() - 1);
            const attendanceCutoffValue = attendanceCutoff.toISOString().slice(0, 10);
            const fetchRecentAttendance = async () => {
                const { data, error } = await window.supabaseClient
                    .from('attendance')
                    .select('id,date,class,recordedBy,records')
                    .gte('date', attendanceCutoffValue)
                    .order('date', { ascending: false })
                    .limit(5000);
                if (error) throw error;
                return data || [];
            };
            const fetchRecentTransactions = async () => {
                const { data, error } = await window.supabaseClient
                    .from('transactions')
                    .select('id,date,receipt_no,status,student_id,amount,type,category,paymentmethod,cartdetails,processed_by')
                    .gte('date', attendanceCutoffValue)
                    .order('date', { ascending: false })
                    .limit(5000);
                if (error) throw error;
                const rows = data || [];
                window.transactions = rows;
                localStorage.setItem('havenTransactions', JSON.stringify(rows));
                return rows;
            };
            const [clsData, feeData, , , , , reportData, teacherData, allocationData, attendanceData, cloudUserData] = await fetchGroup([
                window.fetchCompleteCloudTable('classes', 1000, 'level'),
                window.fetchCompleteCloudTable('fee_structures'),
                fetchRecentTransactions(),
                fetchTable('inventory', 'inventory', 'haven_inventory'),
                fetchTable('expenses', 'expenses', 'haven_expenses'),
                fetchTable('payroll_history', 'payrollHistory', 'haven_payroll_history'),
                fetchTable('academic_reports', 'academicReports', 'haven_academic_reports'),
                window.fetchCompleteCloudTable('teachers'),
                window.fetchCompleteCloudTable('allocations'),
                fetchRecentAttendance(),
                cachedLoginUsers || window.fetchCompleteCloudTable('users')
            ]);
            if (initializationGeneration !== window.appInitializationGeneration) return;
            window.officialClasses = clsData.map(c => ({
                ...c,
                name: c.name || c.level || c.className || 'Unnamed Class',
                limit: c.limit || c.capacity || 30
            }));
            localStorage.setItem('haven_classes', JSON.stringify(window.officialClasses));
            const feeObj = {};
            feeData.forEach(row => { feeObj[row.id || row.level || row.grade] = row.data || row.fees || []; });
            window.feeStructures = feeObj;
            localStorage.setItem('havenFeeStructures', JSON.stringify(window.feeStructures));
            window.academicReports = reportData.map(row => row.data || row);
            window.teachers = teacherData.map(row => row.data || row);
            window.allocations = allocationData.map(row => row.data || row);
            window.attendanceData = attendanceData.map(row => row.data || row);
            localStorage.setItem('havenAttendance', JSON.stringify(window.attendanceData));
            window.users = cloudUserData.length > 0 ? cloudUserData.map(row => row.data || row) : [];

            if (typeof renderFeeStructures === 'function') renderFeeStructures();
            if (typeof renderStaffList === 'function') renderStaffList();
            if (typeof renderAnnouncements === 'function') renderAnnouncements();
            if (typeof updateDashboard === 'function') updateDashboard();
            if (typeof renderInventory === 'function') renderInventory();
            if (typeof renderExpenses === 'function') renderExpenses();
            if (typeof updateAllClassDropdowns === 'function') updateAllClassDropdowns();
            if (typeof renderCustomClasses === 'function') renderCustomClasses();
            if (typeof renderStaffDirectory === 'function') renderStaffDirectory();
            if (typeof updateTeacherDropdowns === 'function') updateTeacherDropdowns();
            if (typeof renderAllocationsTable === 'function') renderAllocationsTable();
            if (typeof renderPayrollHistory === 'function') renderPayrollHistory();
            if (typeof initAttendanceTab === 'function') initAttendanceTab();
            if (typeof calculateReconciliation === 'function') calculateReconciliation();
            if (typeof window.populateEventHistory === 'function') window.populateEventHistory();
            if (typeof window.renderEcoCashTable === 'function') window.renderEcoCashTable();
            if (typeof window.renderSettingsSummary === 'function') window.renderSettingsSummary(window.settings);

            if (window.settings && window.settings.zigRate) {
                const rateInput = document.getElementById('zigRate');
                if (rateInput) rateInput.value = window.settings.zigRate;
            }

            console.log("🌟 All school data loaded.");
            window.startupLoadProgress.active = false;
            if (typeof window.updateLoadingStatus === 'function') window.updateLoadingStatus("System Ready!", 100);
            if (typeof window.fetchAndRenderEventHistoryTable === 'function') {
                window.fetchAndRenderEventHistoryTable();
            }
        })();

        backgroundLoad.catch(backgroundError => {
            if (initializationGeneration !== window.appInitializationGeneration) return;
            window.startupLoadProgress.active = false;
            console.error('Background section data could not be loaded:', backgroundError);
            if (typeof window.updateLoadingStatus === 'function') {
                window.updateLoadingStatus(
                    `Core records are ready, but background data failed to load: ${backgroundError.message || backgroundError}`,
                    40,
                    true
                );
            }
        });

        console.info(`[Startup] Core data available in ${((performance.now() - initializationStartedAt) / 1000).toFixed(1)}s`);

        // Session Heartbeat
        if (window.currentUser && window.currentUser.sessionId) {
            if (typeof window.startSessionHeartbeat === 'function') window.startSessionHeartbeat();
        }

    } catch (error) {
        if (initializationGeneration !== window.appInitializationGeneration) return;
        if (window.startupLoadProgress) window.startupLoadProgress.active = false;

        if (window.__hasCachedCore && window.currentUser) {
            window.appDataReady = true;
            if (typeof window.setAppDataInteractivity === 'function') {
                window.setAppDataInteractivity(true);
            }
            const overlay = document.getElementById('systemLoadingScreen');
            if (overlay) overlay.style.display = 'none';
            if (typeof window.updateLoadingStatus === 'function') {
                window.updateLoadingStatus(
                    'Using saved records because the cloud refresh is slow. Updates will retry in the background.',
                    80,
                    true
                );
            }
            console.warn('Startup cloud refresh could not finish; cached core records remain usable:', error);
            return;
        }

        window.appDataReady = false;
        if (typeof window.setAppDataInteractivity === 'function') window.setAppDataInteractivity(false);
        window.showCloudLoadFailure(error);
        
        const offlineBanner = document.getElementById('offlineBanner');
        if (offlineBanner) offlineBanner.style.display = 'block';
        throw error;
    }
    
};

// ==========================================
// 3. ROLE-BASED ACCESS CONTROL (RBAC)
// ==========================================
window.applyPermissions = function() {
    if (!window.currentUser) return;
    const role = window.currentUser.role;
    const adminOnlyElements = document.querySelectorAll('.admin-only');

    if (role === 'Admin' || role.includes('Level 2') || role.includes('Level 3') || role === 'Chief Admin') {
        // Admins see everything
        adminOnlyElements.forEach(el => el.style.display = '');
    } else if (role === 'Finance' || role.includes('Level 1')) {
        // Finance/Teachers see limited views, hide pure admin/wipe settings
        adminOnlyElements.forEach(el => el.style.display = 'none');
    }
};

// ==========================================
// 5. GLOBAL UNDO ENGINE (NEW FEATURE)
// ==========================================


window.undoLastFormAction = function() {
    if (window.formHistoryStack.length === 0) return alert("Nothing to undo!");
    
    const lastAction = window.formHistoryStack.pop();
    const state = lastAction.state;
    
    // Restore exact values based on HTML IDs
    for (const [id, value] of Object.entries(state)) {
        const el = document.getElementById(id);
        if (el) {
            if (el.type === 'checkbox' || el.type === 'radio') {
                el.checked = value;
            } else {
                el.value = value;
            }
        }
    }
    
    alert("↩️ Form restored to previous state!");
    
    // Hide button if history is empty
    if (window.formHistoryStack.length === 0) {
        document.getElementById('globalUndoBtn').style.display = 'none';
    }
};
// Make sure the memory bank exists
if (!window.formHistoryStack) window.formHistoryStack = [];

window.restoreLastFormState = function() {
    if (window.formHistoryStack.length === 0) return;

    // Grab the most recent snapshot from the top of the stack
    const lastState = window.formHistoryStack.pop();

    // Hide the Undo button if the memory bank is now empty
    if (window.formHistoryStack.length === 0) {
        document.getElementById('globalUndoBtn').style.display = 'none';
    }

    // Loop through the saved snapshot and put the values back into the form
    for (let inputId in lastState.state) {
        const inputElement = document.getElementById(inputId);
        if (inputElement) {
            inputElement.value = lastState.state[inputId];
        }
    }
    
    alert("↩️ Form data restored!");
};

// ==========================================
// 6. TEACHER REGISTRATION & DEPLOYMENT
// ==========================================

window.registerTeacher = async function() {
    const name = document.getElementById('regTeacherName').value.trim();
    const empId = document.getElementById('regTeacherId').value.trim();
    const subjectsRaw = document.getElementById('regTeacherSubjects').value.trim();

    if (!name || !empId) return alert("Please enter both the Teacher Name and Employee ID.");

    // Save state before clearing (Undo Engine hook)
    window.saveFormStateToHistory('regTeacherForm', {
        'regTeacherName': name,
        'regTeacherId': empId,
        'regTeacherSubjects': subjectsRaw
    });

    const subjectArray = subjectsRaw.split(',').map(s => s.trim()).filter(s => s !== "");

    const newTeacher = {
        id: empId,
        name: name,
        subjects: subjectArray,
        assignedClass: "Unassigned",
        assignedSubject: "N/A"
    };

    if (!window.teachers) window.teachers = [];
    window.teachers.push(newTeacher);

    // 1. Save Locally
    localStorage.setItem('haven_teachers', JSON.stringify(window.teachers));

    // 2. Clear UI
    document.getElementById('regTeacherName').value = '';
    document.getElementById('regTeacherId').value = '';
    document.getElementById('regTeacherSubjects').value = '';

   // 3. Sync to Cloud safely
    if (navigator.onLine && typeof supabaseClient !== 'undefined') {
        try {
            // Ask Supabase to save, and extract the 'error' if it fails
            const { data, error } = await supabaseClient
                .from('teachers')
                .upsert(newTeacher);

            if (error) {
                // If Supabase complains (like a 404 missing table error)
                console.warn("Supabase Warning:", error.message);
                alert("⚠️ Saved locally. Cloud sync failed because the database table is not set up yet.");
            } else {
                console.log("✅ Teacher saved to cloud.");
            }
        } catch (e) {
            console.warn("Network error during cloud save. Saved locally.");
        }
    }

    window.renderAllocationsTable();
    alert(`✅ ${name} has been successfully registered!`);
};

window.deployTeacherAILegacyV1 = async function() {
    if (!window.teachers || window.teachers.length === 0) return alert("No teachers to assign!");
    if (!window.officialClasses || window.officialClasses.length === 0) return alert("No formal classes setup!");

    let unassignedClasses = [...window.officialClasses.map(c => c.level)];
    let matchCount = 0;

    // Algorithmic Auto-Assign based on subject tags and availability
    window.teachers.forEach(teacher => {
        if (teacher.assignedClass === "Unassigned" && unassignedClasses.length > 0) {
            teacher.assignedClass = unassignedClasses.shift(); // Grab next available class
            teacher.assignedSubject = teacher.subjects.length > 0 ? teacher.subjects[0] : "General";
            matchCount++;
            if (navigator.onLine && typeof supabaseClient !== 'undefined') {
                try {
                    supabaseClient.from('teachers').upsert(teacher);
                } catch(e) {}
            }
        }
    });

    window.renderAllocationsTable();
    alert(`🤖 Auto-Deployment Complete!\nSuccessfully matched ${matchCount} teachers to classes.`);
};

window.removeTeacher = async function(id) {
    if (!confirm("Are you sure you want to remove this teacher?")) return;
    window.teachers = window.teachers.filter(t => t.id !== id);
    if (navigator.onLine && typeof supabaseClient !== 'undefined') {
        try {
            await supabaseClient.from('teachers').delete().eq('id', id);
        } catch(e) {}
    }
    window.renderAllocationsTable();
};
// ==========================================
// 7. HYBRID ATTENDANCE REGISTER
// ==========================================


window.toggleAbsenceReason = function(checkbox) {
    const reasonSelect = checkbox.closest('tr').querySelector('.att-reason');
    reasonSelect.style.display = checkbox.checked ? 'none' : 'block';
};

window.saveAttendance = async function() {
    const classSelect = document.getElementById('attClassSelect').value;
    const dateInput = document.getElementById('attDate').value;
    const rows = document.querySelectorAll('.att-row');

    let records = [];
    let absentees = [];

    rows.forEach(row => {
        const id = row.getAttribute('data-id');
        const name = row.getAttribute('data-name');
        const isPresent = row.querySelector('.att-status').checked;
        const reason = isPresent ? "" : row.querySelector('.att-reason').value;

        records.push({ id, name, status: isPresent ? 'Present' : 'Absent', reason });
        if (!isPresent) absentees.push(id);
    });

    const logEntry = {
        id: `ATT-${classSelect.replace(/\s+/g, '-')}-${dateInput}`,
        date: dateInput,
        class: classSelect,
        recordedBy: window.currentUser ? window.currentUser.name : 'Staff',
        records: records
    };

    // Upsert into memory
    const existingIndex = window.attendanceLogs.findIndex(l => l.id === logEntry.id);
    if (existingIndex >= 0) {
        window.attendanceLogs[existingIndex] = logEntry;
    } else {
        window.attendanceLogs.push(logEntry);
    }

  // Cloud Sync
if (navigator.onLine && typeof supabaseClient !== 'undefined') {
    try {
        await supabaseClient.from('attendance').upsert(logEntry); // <-- Updated to 'attendance'
        alert("✅ Register Saved to Cloud!");
        } catch (e) {
            console.warn("Sync Error:", e);
            alert("⚠️ Saved locally, cloud sync failed. Ensure table is configured.");
        }
    } else {
        alert("⚠️ Saved offline.");
    }

    // 🔴 WILDCARD FEATURE: Check for 3 Consecutive Absences
    window.checkConsecutiveAbsences(absentees, classSelect, dateInput);
};

window.checkConsecutiveAbsences = function(currentAbsentees, className, currentDate) {
    if (currentAbsentees.length === 0) return;

    // Get all logs for this class, sorted by date descending
    const classLogs = window.attendanceLogs
        .filter(l => l.class === className && l.date <= currentDate)
        .sort((a, b) => new Date(b.date) - new Date(a.date));

    if (classLogs.length < 3) return; // Not enough history

    currentAbsentees.forEach(studentId => {
        let absentCount = 0;
        
        // Check the last 3 registers
        for (let i = 0; i < 3; i++) {
            const log = classLogs[i];
            const record = log.records.find(r => r.id === studentId);
            if (record && record.status === 'Absent') {
                absentCount++;
            } else {
                break; // Sequence broken
            }
        }

        if (absentCount === 3) {
            const student = window.students.find(s => s.id === studentId);
            if (student && student.phone) {
                // Trigger Warning Generation
                const phone = student.phone.replace(/\D/g, '');
                const formattedPhone = phone.startsWith('0') ? '263' + phone.substring(1) : phone;
                
                const msg = `*ATTENDANCE WARNING* ⚠️\n\nDear Parent/Guardian,\n\nPlease note that *${student.name}* has been marked ABSENT for 3 consecutive days. \n\nPlease contact the school office urgently to update us on their situation.`;
                
                if(confirm(`⚠️ WARNING TRIGGERED!\n\n${student.name} has missed 3 consecutive days. Open WhatsApp to notify parent?`)) {
                    window.open(`https://wa.me/${formattedPhone}?text=${encodeURIComponent(msg)}`, '_blank');
                }
            }
        }
    });
};


