// 8. PAYROLL & SALARIES ENGINE
// ==========================================



// 🎯 Resolve a payroll record's staff name/title/centre robustly (handles legacy IDs that no longer
// match the current staff registry) instead of falling back to a raw ID/number.
window.resolvePayrollStaffInfo = function(record) {
    const teacherId = record.teacher_id;

    // 1. Denormalized name saved at the time of payment (most reliable for current-session records)
    if (record.teacher_name) {
        return { name: record.teacher_name, title: record.teacher_title || 'Staff', centre: record.teacher_centre || 'N/A' };
    }

    // 2. Cached staff pool built by updatePayrollDropdown (current registry)
    const cached = (window.__payrollStaffCache || {})[teacherId];
    if (cached) {
        return { name: cached.name.split(' (')[0], title: cached.staffType, centre: cached.centres.length ? cached.centres.join(', ') : 'N/A' };
    }

    // 3. Deep search across every raw staff source for a loose ID/username match
    const pools = [window.staffRegistry, window.staffAccounts, window.users, window.teachers, window.staff];
    for (const pool of pools) {
        if (!Array.isArray(pool)) continue;
        const match = pool.find(s => String(s.id) === String(teacherId) || String(s.user) === String(teacherId) || String(s.username) === String(teacherId));
        if (match) {
            const name = (match.name || match.username || match.user || '') + (match.surname ? ' ' + match.surname : '');
            const centres = (match.centre_assignments && match.centre_assignments.length) ? match.centre_assignments : (match.centre ? [match.centre] : []);
            return { name: name.trim() || `Unknown Staff (${teacherId})`, title: match.staff_type || match.type || match.role || 'Staff', centre: centres.length ? centres.join(', ') : 'N/A' };
        }
    }

    // 4. Truly not found (e.g. deleted staff with no denormalized name) — label clearly instead of a bare ID
    return { name: `Former/Unknown Staff (${teacherId})`, title: 'Unknown', centre: 'N/A' };
};

window.renderPayrollHistory = function() {
    // 1. Populate Dropdown (delegates to the richer, centre/title/salary-aware populator)
    if (typeof window.updatePayrollDropdown === 'function') window.updatePayrollDropdown();

    // 2. Render the filtered/summarized views
    if (typeof window.filterPayrollHistoryList === 'function') window.filterPayrollHistoryList();
    if (typeof window.renderPayrollSummaryTable === 'function') window.renderPayrollSummaryTable();
    if (typeof window.renderPayrollTotals === 'function') window.renderPayrollTotals();
};

// 🎯 Filterable, checkbox-selectable payroll history list (search by name/title/centre/date range)
window.filterPayrollHistoryList = function() {
    const list = document.getElementById('payrollHistoryList');
    if (!list) return;

    const history = window.payrollHistory || [];
    if (history.length === 0) {
        list.innerHTML = '<em style="color:#7f8c8d;">No payroll records processed yet.</em>';
        if (typeof window.updatePayrollHistorySelectionTotal === 'function') window.updatePayrollHistorySelectionTotal();
        return;
    }

    const search = (document.getElementById('payHistorySearch')?.value || '').toLowerCase().trim();
    const titleFilter = document.getElementById('payHistoryTitleFilter')?.value || '';
    const centreFilter = document.getElementById('payHistoryCentreFilter')?.value || '';
    const startDate = document.getElementById('payHistoryStartDate')?.value || '';
    const endDate = document.getElementById('payHistoryEndDate')?.value || '';

    const enriched = history.map(record => ({ record, info: window.resolvePayrollStaffInfo(record) }));

    const filtered = enriched.filter(({ record, info }) => {
        if (search && !info.name.toLowerCase().includes(search)) return false;
        if (titleFilter && info.title !== titleFilter) return false;
        if (centreFilter && !info.centre.split(', ').includes(centreFilter)) return false;
        if (startDate && record.payment_date < startDate) return false;
        if (endDate && record.payment_date > endDate) return false;
        return true;
    }).sort((a, b) => new Date(b.record.payment_date) - new Date(a.record.payment_date));

    if (filtered.length === 0) {
        list.innerHTML = '<em style="color:#7f8c8d;">No payroll records match the selected filters.</em>';
        if (typeof window.updatePayrollHistorySelectionTotal === 'function') window.updatePayrollHistorySelectionTotal();
        return;
    }

    list.innerHTML = filtered.map(({ record, info }) => {
        const amount = parseFloat(record.amount || 0);
        return `
            <div style="background: white; border-left: 5px solid #27ae60; padding: 10px; margin-bottom: 8px; border-radius: 4px; box-shadow: 0 1px 2px rgba(0,0,0,0.05); font-size: 13px;">
                <div style="display:flex; justify-content:space-between; align-items:flex-start; margin-bottom: 5px; gap: 8px;">
                    <label style="display:flex; align-items:flex-start; gap: 6px; cursor:pointer;">
                        <input type="checkbox" class="payHistoryRowCheck" value="${record.id}" data-amount="${amount}" onchange="window.updatePayrollHistorySelectionTotal()" style="margin-top: 3px;">
                        <strong style="color: #2c3e50;">👤 ${info.name}</strong>
                    </label>
                    <strong style="color: #27ae60; white-space: nowrap;">$${amount.toFixed(2)}</strong>
                </div>
                <div style="color: #7f8c8d; font-size: 11px; padding-left: 22px;">
                    ${info.title} ${info.centre !== 'N/A' ? `| ${info.centre}` : ''} | Period: ${record.payroll_period} | Date Paid: ${record.payment_date}
                </div>
            </div>
        `;
    }).join('');

    if (typeof window.updatePayrollHistorySelectionTotal === 'function') window.updatePayrollHistorySelectionTotal();
};

// 🎯 Shows the sum of checked rows, or the sum of all currently-displayed/filtered rows if none are checked
window.updatePayrollHistorySelectionTotal = function() {
    const totalEl = document.getElementById('payHistoryDisplayedTotal');
    if (!totalEl) return;

    const checkboxes = Array.from(document.querySelectorAll('.payHistoryRowCheck'));
    const checked = checkboxes.filter(cb => cb.checked);
    const source = checked.length > 0 ? checked : checkboxes;
    const sum = source.reduce((s, cb) => s + (parseFloat(cb.dataset.amount) || 0), 0);

    totalEl.innerText = `$${sum.toFixed(2)} ${checked.length > 0 ? `(${checked.length} selected)` : `(${checkboxes.length} displayed)`}`;
};

// 🎯 Aggregate payroll history per staff member: title, centre, periods paid, first/last paid, total spent
window.renderPayrollSummaryTable = function() {
    const tbody = document.getElementById('payrollSummaryBody');
    if (!tbody) return;

    const history = window.payrollHistory || [];

    if (history.length === 0) {
        tbody.innerHTML = '<tr><td colspan="7" style="text-align:center; padding:10px; color:#7f8c8d;">No payroll records processed yet.</td></tr>';
        return;
    }

    const groups = {};
    history.forEach(record => {
        const id = record.teacher_id;
        if (!groups[id]) groups[id] = [];
        groups[id].push(record);
    });

    const rows = Object.entries(groups).map(([id, records]) => {
        const sorted = [...records].sort((a, b) => new Date(a.payment_date) - new Date(b.payment_date));
        const info = window.resolvePayrollStaffInfo(records[0]);
        const total = records.reduce((sum, r) => sum + (parseFloat(r.amount) || 0), 0);

        return { name: info.name, title: info.title, centre: info.centre, count: records.length, first: sorted[0].payment_date, last: sorted[sorted.length - 1].payment_date, total };
    }).sort((a, b) => b.total - a.total);

    tbody.innerHTML = rows.map(r => `
        <tr style="border-bottom: 1px solid #ecf0f1;">
            <td style="padding: 6px;"><strong>${r.name}</strong></td>
            <td style="padding: 6px;">${r.title}</td>
            <td style="padding: 6px;">${r.centre}</td>
            <td style="padding: 6px; text-align: center;">${r.count}</td>
            <td style="padding: 6px;">${r.first}</td>
            <td style="padding: 6px;">${r.last}</td>
            <td style="padding: 6px; text-align: right; font-weight: bold; color: #27ae60;">$${r.total.toFixed(2)}</td>
        </tr>
    `).join('');
};

// 🎯 Mini accounts summary: total salaries paid out & total staff loans still outstanding
window.renderPayrollTotals = function() {
    const salariesEl = document.getElementById('payTotalSalariesPaid');
    const loansEl = document.getElementById('payTotalOutstandingLoans');
    if (!salariesEl && !loansEl) return;

    if (salariesEl) {
        const totalSalaries = (window.payrollHistory || []).reduce((sum, r) => sum + (parseFloat(r.amount) || 0), 0);
        salariesEl.innerText = `$${totalSalaries.toFixed(2)}`;
    }
    
    if (loansEl) {
        let totalLoans = 0;
        let countedIds = new Set(); // Prevents double-counting if an employee is in both arrays

        // 1. Check users array (Primary authoritative source for loans)
        if (window.users && Array.isArray(window.users)) {
            window.users.forEach(u => {
                let bal = parseFloat(u.loanBalance) || 0;
                
                // Extract from JSON data if it's nested
                if (u.data) {
                    let uData = typeof u.data === 'string' ? JSON.parse(u.data) : u.data;
                    bal = parseFloat(uData.loanBalance) || bal;
                }
                
                if (bal > 0) {
                    totalLoans += bal;
                    countedIds.add(u.id || u.username);
                }
            });
        }

        // 2. Check staffAccounts array (Fallback for older records)
        if (window.staffAccounts && Array.isArray(window.staffAccounts)) {
            window.staffAccounts.forEach(s => {
                const id = s.id || s.username;
                if (!countedIds.has(id)) {
                    totalLoans += (parseFloat(s.loanBalance) || 0);
                    countedIds.add(id);
                }
            });
        }

        loansEl.innerText = `$${totalLoans.toFixed(2)}`;
    }
};
window.deleteSelectedPayrollRecords = async function() {
    // 1. Role Authorization
    const role = window.currentUser?.role || "";
    if (!(role.includes('Level 3') || role === 'Admin' || role === 'Chief Admin')) {
        return alert("❌ Access Denied: Only Admins can delete payroll records.");
    }

    if (!navigator.onLine || typeof window.supabaseClient === 'undefined') {
        return alert("⚠️ You must be online and connected to the cloud to delete records.");
    }

    // 2. Gather selected records
    const checkboxes = document.querySelectorAll('.payHistoryRowCheck:checked');
    if (checkboxes.length === 0) {
        return alert("⚠️ Please check the box next to at least one payroll record to delete.");
    }

    const idsToDelete = Array.from(checkboxes).map(cb => cb.value);

    // 3. Confirm deletion
    if (!confirm(`⚠️ Are you sure you want to PERMANENTLY delete ${idsToDelete.length} payroll record(s)?\n\nThis will remove them from the cloud database and cannot be undone.`)) {
        return;
    }

    try {
        document.body.style.cursor = 'wait';

        // 4. Delete from Supabase Cloud
        const { error } = await window.supabaseClient
            .from('payroll_history')
            .delete()
            .in('id', idsToDelete);

        if (error) throw error;

        // 5. Delete from Local Memory
        if (window.payrollHistory) {
            window.payrollHistory = window.payrollHistory.filter(r => !idsToDelete.includes(r.id));
        }

        // 6. Refresh UI
        window.filterPayrollHistoryList();
        if (typeof window.renderPayrollTotals === 'function') window.renderPayrollTotals();
        
        alert(`✅ Successfully deleted ${idsToDelete.length} payroll record(s).`);

    } catch (error) {
        console.error("Error deleting payroll records:", error);
        alert("❌ Failed to delete records: " + error.message);
    } finally {
        document.body.style.cursor = 'default';
    }
};

// ==========================================
// 1. PAYROLL DROPDOWN HANDLER (Merged & Kept Detailed Version)
// ==========================================
window.handlePayrollStaffSelect = function() {
    const empId = document.getElementById('payEmpSelect').value;
    const loanDisplay = document.getElementById('payOutstandingLoan');
    const interestDisplay = document.getElementById('payLoanInterest');
    const basicDisplay = document.getElementById('payBasic');
    const infoPanel = document.getElementById('payStaffInfoPanel');

    // If they select "-- Select Staff Member --" (blank), reset everything to 0
    if (!empId) {
        if (loanDisplay) loanDisplay.value = "0";
        if (interestDisplay) interestDisplay.value = "0";
        if (infoPanel) infoPanel.style.display = 'none';
        if (typeof window.calcNetSalary === 'function') window.calcNetSalary();
        return;
    }

    // Grab cached details from the new registry to help us search
    const cached = (window.__payrollStaffCache || {})[empId] || {};
    const staffName = cached.name ? cached.name.split(' (')[0] : '';
    const staffUsername = cached.username || '';

    // 1. SMART SEARCH: Find the employee in the users table (where loans are saved)
    let emp = null;
    if (window.users) {
        emp = window.users.find(u => 
            u.id === empId || 
            u.username === empId ||
            (staffUsername && u.username === staffUsername) ||
            (staffName && u.name === staffName) ||
            (u.data && (u.data.id === empId || u.data.username === staffUsername || u.data.name === staffName))
        );
    }
    
    // Fallback if not found in users
    if (!emp && window.staffAccounts) {
        emp = window.staffAccounts.find(s => s.id === empId || s.username === empId);
    }

    // 2. Extract their loan data safely
    let balance = 0;
    let rate = 0;
    
    if (emp) {
        balance = parseFloat(emp.loanBalance) || 0;
        
        // Data is often nested inside the 'data' JSON object
        if (emp.data) {
            let empData = typeof emp.data === 'string' ? JSON.parse(emp.data) : emp.data;
            balance = parseFloat(empData.loanBalance) || balance;
            rate = parseFloat(empData.loanInterestRate) || rate;
        }
    }

    // 3. Inject the numbers into the visual text boxes
    if (loanDisplay) loanDisplay.value = balance.toFixed(2);
    if (interestDisplay && rate > 0) interestDisplay.value = rate;

    // 4. Auto-populate the allocated salary & show a staff details panel
    if (cached.name) {
        if (basicDisplay && cached.salary > 0) basicDisplay.value = cached.salary.toFixed(2);
        
        if (infoPanel) {
            infoPanel.style.display = 'block';
            infoPanel.innerHTML = `
                <strong>${staffName}</strong><br>
                Title: <strong>${cached.staffType || 'N/A'}</strong> &nbsp;|&nbsp;
                Centre(s): <strong>${(cached.centres && cached.centres.length) ? cached.centres.join(', ') : 'N/A'}</strong><br>
                Allocated Salary: <strong>$${(cached.salary || 0).toFixed(2)}</strong> &nbsp;|&nbsp;
                Loan Balance: <strong>$${balance.toFixed(2)}</strong>
                ${cached.phone ? ` &nbsp;|&nbsp; Phone: <strong>${cached.phone}</strong>` : ''}
            `;
        }
    } else if (infoPanel) {
        infoPanel.style.display = 'none';
    }

    // 5. Force the math engine to recalculate with the new loan amounts
    if (typeof window.calcNetSalary === 'function') window.calcNetSalary();
};

window.deleteUnifiedStaffMember = async function(staffId) {
    // 1. Ask for confirmation before deleting
    if (!confirm('⚠️ Are you sure you want to permanently delete this staff member?\n\nThis action cannot be undone.')) {
        return;
    }

    // 2. Remove the staff member from the local registry array
    if (window.staffRegistry) {
        window.staffRegistry = window.staffRegistry.filter(s => s.id !== staffId);
    }

    // 3. Update localStorage so it reflects the deletion immediately
    localStorage.setItem('havenStaffRegistry', JSON.stringify(window.staffRegistry));

    // 4. Delete from Supabase Database
    if (navigator.onLine && window.supabaseClient && window.supabaseReady) {
        try {
            console.log(`Attempting to delete staff ID: ${staffId} from cloud...`);
            
            const { error } = await window.supabaseClient
                .from('staff_registry')
                .delete()
                .eq('id', staffId); // Target the specific staff ID
            
            if (error) {
                console.error('❌ Cloud deletion error:', error);
                alert(`⚠️ Staff removed locally, but failed to delete from the cloud database.\nError: ${error.message}`);
            } else {
                console.log('✅ Staff successfully deleted from cloud database.');
                alert('✅ Staff member completely deleted.');
            }
        } catch (e) {
            console.error('Cloud delete exception:', e);
            alert('⚠️ Staff removed locally, but a network issue prevented cloud deletion.');
        }
    } else {
        alert('✅ Staff removed locally. Cloud database will not be updated until you are online.');
    }

    // 5. Refresh the UI to remove the row from the table
    window.renderUnifiedStaffDirectory();
    
    // 6. Update the payroll dropdown if it exists so they can't be paid anymore
    if (typeof window.updatePayrollDropdown === 'function') {
        window.updatePayrollDropdown();
    }
};


// ==========================================
// 2. ISSUE STAFF LOAN (Upgraded with Top-Up Authorization)
// ==========================================
window.issueStaffLoan = async function() {
    // 1. Role Authorization Check
    const role = window.currentUser?.role || "";
    if (!(role.includes('Level 2') || role.includes('Level 3') || role === 'Admin' || role === 'Chief Admin')) {
        return alert("❌ Access Denied: Only Admins can issue staff loans.");
    }

    if (!navigator.onLine) {
        return alert("⚠️ You must be online to issue and sync loans to the cloud database.");
    }

    // 2. Gather Inputs
    const selectEl = document.getElementById('loanEmpSelect');
    const empId = selectEl.value;
    const loanAmount = parseFloat(document.getElementById('loanAmountInput').value) || 0;
    const interestRate = parseFloat(document.getElementById('loanRateInput').value) || 0;
    const reason = document.getElementById('loanReasonInput').value.trim() || 'Staff Loan Disbursement';

    if (!empId) return alert("⚠️ Please select a staff member.");
    if (loanAmount <= 0) return alert("⚠️ Please enter a valid loan amount greater than zero.");

    const empName = selectEl.options[selectEl.selectedIndex].text.split(' (')[0];

    try {
        let userRecord = null;
        let actualDbId = null;

        // 3. Smart Fallback Lookup 
        const { data: userMatches, error: fetchError } = await supabaseClient
            .from('users')
            .select('id, username, name, data')
            .or(`id.eq.${empId},username.eq.${empId}`);

        if (userMatches && userMatches.length > 0) {
            userRecord = userMatches[0];
            actualDbId = userRecord.id;
        } else {
            const { data: allUsers, error: allErr } = await supabaseClient
                .from('users')
                .select('id, username, name, data');

            if (!allErr && allUsers) {
                const found = allUsers.find(u => 
                    u.id === empId || 
                    u.username === empId || 
                    u.name === empName || 
                    (u.data && (u.data.id === empId || u.data.username === empId || u.data.name === empName))
                );
                if (found) {
                    userRecord = found;
                    actualDbId = found.id;
                }
            }
        }

        if (!userRecord || !actualDbId) {
            return alert(`❌ Employee record not found in the database for ID: ${empId}`);
        }

        // 4. Parse existing JSON data to check for existing loans
        let currentData = userRecord.data || {};
        if (typeof currentData === 'string') {
            try { currentData = JSON.parse(currentData); } catch(e) { currentData = {}; }
        }

        let currentLoanBalance = parseFloat(currentData.loanBalance) || 0;
        let newLoanBalance = currentLoanBalance + loanAmount;
        
        // 🎯 5. TOP-UP AUTHORIZATION CHECK
        let confirmMsg = "";
        if (currentLoanBalance > 0) {
            confirmMsg = `⚠️ AUTHORIZATION REQUIRED (LOAN TOP-UP)\n\nEmployee: ${empName}\nCURRENT DEBT: $${currentLoanBalance.toFixed(2)}\n\nThey are requesting an additional: $${loanAmount.toFixed(2)}\nNEW TOTAL DEBT WILL BE: $${newLoanBalance.toFixed(2)}\n\nDo you authorize this loan top-up?`;
        } else {
            confirmMsg = `🏦 Confirm Loan Issuance:\n\nEmployee: ${empName}\nAmount: $${loanAmount.toFixed(2)}\nInterest Rate: ${interestRate}%\nReason: ${reason}\n\nClick OK to process.`;
        }

        const confirmIssue = confirm(confirmMsg);
        if (!confirmIssue) return; // Stop if admin cancels the prompt

        // Proceed with updating the database
        currentData.loanBalance = newLoanBalance;
        currentData.loanInterestRate = interestRate;

        // 6. Update the 'users' table in Supabase
        const { error: updateError } = await supabaseClient
            .from('users')
            .update({ data: currentData })
            .eq('id', actualDbId);

        if (updateError) throw updateError;

        // 7. Update Local Memory States
        if (window.users) {
            let u = window.users.find(u => u.id === actualDbId || u.username === empId || u.id === empId);
            if (u) {
                u.data = currentData;
                u.loanBalance = newLoanBalance;
            }
        }
        if (window.staffAccounts) {
            let s = window.staffAccounts.find(s => s.id === actualDbId || s.username === empId || s.id === empId);
            if (s) s.loanBalance = newLoanBalance;
        }

        // 8. Log loan disbursement as an expense record for the Vault
        const loanExpenseRecord = {
            id: 'EXP-LOAN-' + Date.now(),
            date: new Date().toISOString().split('T')[0],
            description: `Staff Loan Advanced: ${empName} - ${reason}`,
            amount: loanAmount,
            payment_method: 'Cash / Bank Advance'
        };
        await supabaseClient.from('expenses').insert([loanExpenseRecord]);
        
        if (!window.expenses) window.expenses = [];
        window.expenses.push(loanExpenseRecord);
        if (typeof window.saveExpenses === 'function') window.saveExpenses();

        // 9. Reset Form, Refresh UI, and Print
        // Capture data for the slip BEFORE clearing the form
        const loanSlipData = {
            name: empName,
            id: empId,
            amount: loanAmount,
            rate: interestRate,
            reason: reason,
            newBalance: newLoanBalance,
            date: new Date().toISOString().split('T')[0],
            admin: window.currentUser?.name || window.currentUser?.username || "Admin"
        };

        // Clear the form
        document.getElementById('loanAmountInput').value = '';
        document.getElementById('loanRateInput').value = '0';
        document.getElementById('loanReasonInput').value = '';
        selectEl.value = '';
        
        // Hide the red warning text if it was showing
        if (document.getElementById('loanExistingBalanceDisplay')) {
            document.getElementById('loanExistingBalanceDisplay').style.display = 'none';
        }

        if (typeof window.updatePayrollDropdown === 'function') {
            window.updatePayrollDropdown();
        }

        // Ask the user if they want to print the loan slip
        const wantToPrint = confirm(`✅ Loan Successfully Issued!\n\n$${loanAmount.toFixed(2)} has been added to ${empName}'s account.\nNew Total Loan Balance Owed: $${newLoanBalance.toFixed(2)}\n\nWould you like to print the loan disbursement slip now?`);
        
        if (wantToPrint) {
            window.printLoanSlip(loanSlipData);
        }

    } catch (err) {
        console.error("Loan Issuance Error:", err);
        alert("⚠️ Failed to process loan: " + (err.message || "Check console for details."));
    }
};

// 1. Function to filter the dropdown list
window.filterLoanStaffDropdown = function() {
    const searchFilter = document.getElementById('loanEmpSearch').value.toLowerCase().trim();
    const selectEl = document.getElementById('loanEmpSelect');
    
    if (!selectEl) return;

    Array.from(selectEl.options).forEach(opt => {
        if (!opt.value) return; // Always keep the "-- Select --" placeholder visible
        
        const name = opt.textContent.toLowerCase();
        if (name.includes(searchFilter)) {
            opt.hidden = false;
            opt.style.display = "";
        } else {
            opt.hidden = true;
            opt.style.display = "none";
        }
    });
};

// 2. Function to display the existing balance when a user is selected
window.showEmployeeLoanBalance = function() {
    const selectEl = document.getElementById('loanEmpSelect');
    const displayEl = document.getElementById('loanExistingBalanceDisplay');
    const empId = selectEl.value;

    if (!empId) {
        displayEl.style.display = 'none';
        return;
    }

    let currentBalance = 0;
    let foundUser = null;

    // Search existing local arrays to find the user's data
    if (window.users) {
        foundUser = window.users.find(u => u.id === empId || u.username === empId);
    }
    if (!foundUser && window.staffAccounts) {
        foundUser = window.staffAccounts.find(s => s.id === empId || s.username === empId);
    }

    if (foundUser) {
        // Safely extract the loan balance from their data object
        let userData = foundUser.data || {};
        if (typeof userData === 'string') {
            try { userData = JSON.parse(userData); } catch(e) { userData = {}; }
        }
        
        currentBalance = parseFloat(userData.loanBalance) || parseFloat(foundUser.loanBalance) || 0;
    }

    // Display it if they have a debt
    if (currentBalance > 0) {
        displayEl.textContent = `⚠️ Current Debt: $${currentBalance.toFixed(2)}`;
        displayEl.style.display = 'block';
    } else {
        displayEl.style.display = 'none'; // Hide if balance is 0
    }
};
