// MANUAL SYNC FUNCTION FOR STAFF DATA
// ============================================

window.syncStaffToCloud = async function() {
    if (!navigator.onLine) {
        return alert('❌ You are offline. Cannot sync to cloud.');
    }
    
    if (!window.supabaseClient || !window.supabaseReady) {
        return alert('⚠️ Supabase not ready yet. Please try again in a moment.');
    }
    
    if (!window.staffRegistry || window.staffRegistry.length === 0) {
        return alert('⚠️ No staff data to sync.');
    }
    
    const button = document.querySelector('[onclick="window.syncStaffToCloud()"]');
    if (button) button.disabled = true;
    
    try {
        console.log(`Syncing ${window.staffRegistry.length} staff members to cloud...`);
        
        // Upsert all staff to maintain local changes
        const { data, error } = await window.supabaseClient
            .from('staff_registry')
            .upsert(window.staffRegistry, { onConflict: 'id' })
            .select();
        
        if (error) {
            console.error('❌ Sync error:', error);
            alert(`❌ Sync failed: ${error.message}\n\nData remains saved locally.`);
        } else {
            console.log('✅ Staff data synced to cloud:', data?.length || 0, 'records');
            alert(`✅ Success! Synced ${data?.length || window.staffRegistry.length} staff members to cloud.`);
        }
    } catch (e) {
        console.error('❌ Sync exception:', e);
        alert(`❌ Sync error: ${e.message}\n\nPlease check your connection.`);
    } finally {
        if (button) button.disabled = false;
    }
};

