window.renderUnifiedStaffDirectory = function() {
    const tbody = document.getElementById('unifiedStaffDirBody');
    if (!tbody) return;
    
    // Get filters from HTML
    const typeFilter = document.getElementById('staffDirTypeFilter')?.value || '';
    const centreFilter = document.getElementById('staffDirCentreFilter')?.value || '';
    const searchFilter = (document.getElementById('staffDirSearchBox')?.value || '').toLowerCase();
    
    // 1. STRICTLY use the unified registry. NO legacy fallbacks.
    let allStaff = window.staffRegistry || [];
    
    // Fallback to local storage only if memory is completely empty (e.g., hard refresh offline)
    if (allStaff.length === 0) {
        const cached = localStorage.getItem('havenStaffRegistry');
        if (cached) allStaff = JSON.parse(cached);
    }
    
    // Apply HTML filters
    let filtered = allStaff.filter(staff => {
        // Type
        const sType = staff.staff_type || staff.type || '';
        if (typeFilter && sType !== typeFilter) return false;
        
        // Centre
        if (centreFilter) {
            const centres = staff.centre_assignments || [staff.centre] || [];
            if (!centres.includes(centreFilter) && !centres.some(c => c.includes(centreFilter))) return false;
        }
        
        // Search
        if (searchFilter) {
            const name = (staff.name || '').toLowerCase();
            const surname = (staff.surname || '').toLowerCase();
            const id = (staff.id || '').toLowerCase();
            const phone = (staff.phone || '').toLowerCase();
            if (!name.includes(searchFilter) && !surname.includes(searchFilter) && !id.includes(searchFilter) && !phone.includes(searchFilter)) {
                return false;
            }
        }
        return true;
    });
    
    // Update HTML Summary Stats
    const teachers = allStaff.filter(s => ['Teacher', 'Primary', 'Secondary'].includes(s.staff_type || s.type)).length;
    const drivers = allStaff.filter(s => s.staff_type === 'Driver').length;
    const auxiliary = allStaff.filter(s => s.staff_type === 'Auxiliary').length;
    
    if(document.getElementById('staffDirTotal')) document.getElementById('staffDirTotal').textContent = allStaff.length;
    if(document.getElementById('staffDirTeachers')) document.getElementById('staffDirTeachers').textContent = teachers;
    if(document.getElementById('staffDirDrivers')) document.getElementById('staffDirDrivers').textContent = drivers;
    if(document.getElementById('staffDirAuxiliary')) document.getElementById('staffDirAuxiliary').textContent = auxiliary;
    
    // Clear table and render
    tbody.innerHTML = '';
    
    if (filtered.length === 0) {
        tbody.innerHTML = '<tr><td colspan="7" style="text-align:center; padding: 20px; color:#7f8c8d;">No staff found matching filters.</td></tr>';
        return;
    }
    
    filtered.forEach(staff => {
        const tr = document.createElement('tr');
        let staffType = staff.staff_type || staff.type || 'Unknown';
        let typeEmoji = staffType === 'Driver' ? '🚗' : (staffType === 'Auxiliary' ? '🔧' : '👨‍🏫');
        
        // Ensure centres parse correctly if saved as arrays/strings
        let parsedCentres = [];
        try { 
            parsedCentres = Array.isArray(staff.centre_assignments) ? staff.centre_assignments : JSON.parse(staff.centre_assignments); 
        } catch(e) { 
            parsedCentres = [staff.centre_assignments || staff.centre || 'N/A']; 
        }
        
        // Extract qualifications based on type
        let details = staff.phone ? `📱 ${staff.phone}` : 'No phone';
        let qualifications = '';
        
        if (['Teacher', 'Primary', 'Secondary'].includes(staffType)) {
            qualifications = staff.qualified_grades || staff.qualified_subjects || 'N/A';
        } else if (staffType === 'Driver') {
            details += `<br><small style="color:#7f8c8d;">${staff.vehicle_type || 'Vehicle'} (${staff.vehicle_registration || 'No Reg'})</small>`;
            qualifications = (staff.routes || []).join(', ') || 'No routes';
        } else if (staffType === 'Auxiliary') {
            details += `<br><small style="color:#7f8c8d;">${staff.department || 'General'}</small>`;
            qualifications = staff.job_description || 'N/A';
        }
        
        const salary = staff.salary ? `$${parseFloat(staff.salary).toFixed(2)}` : 'N/A';
        const payMethod = staff.payment_method ? staff.payment_method.substring(0, 3) : 'N/A';
        
        tr.innerHTML = `
            <td><strong>${staff.name || 'N/A'}</strong> ${staff.surname || ''}</td>
            <td><span style="font-size:18px;">${typeEmoji}</span><br><small>${staffType}</small></td>
            <td><small style="background:#ecf0f1; padding:3px 6px; border-radius:3px; font-weight:bold;">${parsedCentres.join(', ')}</small></td>
            <td style="font-size:11px;">${details}</td>
            <td><small>${qualifications}</small></td>
            <td><small style="color:#2c3e50; font-weight:bold;">${salary}<br><span style="color:#7f8c8d;">${payMethod}</span></small></td>
            <td style="text-align: right;">
                <button class="btn-standard btn-secondary" style="padding: 4px 8px; font-size: 11px;" onclick="editUnifiedStaffMember('${staff.id}')">✏️ Edit</button>
                <button class="btn-standard btn-danger admin-edit-only" style="padding: 4px 8px; font-size: 11px; margin-top: 4px;" onclick="deleteUnifiedStaffMember('${staff.id}')">🗑️ Delete</button>
            </td>
        `;
        tbody.appendChild(tr);
    });
};

