window.editUnifiedStaffMember = function(staffId) {
    // Find the staff member
    let staff = null;
    if (window.staffRegistry) {
        staff = window.staffRegistry.find(s => s.id === staffId);
    }
    
    if (!staff) {
        return alert('❌ Staff member not found.');
    }

    // Store current ID and type
    document.getElementById('staffEditId').value = staffId;
    document.getElementById('staffEditType').value = staff.staff_type;

    // Load common fields
    document.getElementById('staffEditName').value = staff.name || '';
    document.getElementById('staffEditSurname').value = staff.surname || '';
    document.getElementById('staffEditPhone').value = staff.phone || '';
    
    // Set staff type selector (THIS IS KEY - allows changing type!)
    document.getElementById('staffEditTypeSelector').value = staff.staff_type;

    // Load centres
    const centres = staff.centre_assignments || [];
    document.querySelectorAll('.staffEditCentre').forEach(cb => {
        cb.checked = centres.includes(cb.value);
    });

    // Load payroll
    document.getElementById('staffEditSalary').value = staff.salary || 0;
    document.getElementById('staffEditPaymentMethod').value = staff.payment_method || 'Cash';
    document.getElementById('staffEditBankAccount').value = staff.bank_account || '';

    // Hide all type-specific sections first
    document.getElementById('staffEditTeacherSection').style.display = 'none';
    document.getElementById('staffEditDriverSection').style.display = 'none';
    document.getElementById('staffEditAuxiliarySection').style.display = 'none';

    // Load type-specific data based on CURRENT type
    if (staff.staff_type === 'Teacher') {
        document.getElementById('staffEditTitle').textContent = `✏️ Edit Teacher: ${staff.name}`;
        document.getElementById('staffEditTeacherSection').style.display = 'block';
        
        document.getElementById('staffEditTeacherType').value = staff.teacher_type || '';
        document.getElementById('staffEditTeacherGrades').value = staff.qualified_grades || '';
        document.getElementById('staffEditTeacherSubjects').value = staff.qualified_subjects || '';
        document.getElementById('staffEditTeacherForms').value = staff.qualified_forms || '';
        
        // Show teacher type qualifications
        if (staff.teacher_type === 'Primary') {
            document.getElementById('staffEditPrimaryQuals').style.display = 'block';
            document.getElementById('staffEditSecondaryQuals').style.display = 'none';
        } else if (staff.teacher_type === 'Secondary') {
            document.getElementById('staffEditPrimaryQuals').style.display = 'none';
            document.getElementById('staffEditSecondaryQuals').style.display = 'block';
        }
        
        // Load class dropdown
        loadEditClassDropdown();
        document.getElementById('staffEditDeploySubject').value = staff.assigned_subject || '';

    } else if (staff.staff_type === 'Driver') {
        document.getElementById('staffEditTitle').textContent = `✏️ Edit Driver: ${staff.name}`;
        document.getElementById('staffEditDriverSection').style.display = 'block';
        
        document.getElementById('staffEditVehicleType').value = staff.vehicle_type || '';
        document.getElementById('staffEditVehicleReg').value = staff.vehicle_registration || '';
        document.getElementById('staffEditLicenseNum').value = staff.license_number || '';
        document.getElementById('staffEditLicenseExp').value = staff.license_expiry || '';
        
        // Load routes
        const routes = staff.routes || [];
        document.querySelectorAll('.staffEditRoute').forEach(cb => {
            cb.checked = routes.includes(cb.value);
        });

    } else if (staff.staff_type === 'Auxiliary') {
        document.getElementById('staffEditTitle').textContent = `✏️ Edit Auxiliary: ${staff.name}`;
        document.getElementById('staffEditAuxiliarySection').style.display = 'block';
        
        document.getElementById('staffEditJobDesc').value = staff.job_description || '';
        document.getElementById('staffEditDepartment').value = staff.department || '';
    }

    // Open modal
    document.getElementById('staffEditModal').style.display = 'flex';
};

// Handle staff type change in edit form
window.handleStaffTypeChange = function() {
    const newType = document.getElementById('staffEditTypeSelector').value;
    
    // Hide all sections
    document.getElementById('staffEditTeacherSection').style.display = 'none';
    document.getElementById('staffEditDriverSection').style.display = 'none';
    document.getElementById('staffEditAuxiliarySection').style.display = 'none';
    
    // Show relevant section based on selected type
    if (newType === 'Teacher') {
        document.getElementById('staffEditTeacherSection').style.display = 'block';
        document.getElementById('staffEditTitle').textContent = '✏️ Edit Teacher';
        // Load class dropdown when switching to teacher
        loadEditClassDropdown();
    } else if (newType === 'Driver') {
        document.getElementById('staffEditDriverSection').style.display = 'block';
        document.getElementById('staffEditTitle').textContent = '✏️ Edit Driver';
    } else if (newType === 'Auxiliary') {
        document.getElementById('staffEditAuxiliarySection').style.display = 'block';
        document.getElementById('staffEditTitle').textContent = '✏️ Edit Auxiliary Staff';
    }
};

