// Connect both your HTML buttons to this single, robust sync function
window.migrateOldStaffToUnifiedRegistry = async function() { await window.syncStaffToCloud(true); };

window.syncStaffToCloud = async function(isMigration = false) {
    if (!navigator.onLine || !window.supabaseClient) {
        return alert("⚠️ You must be online to sync with the database.");
    }

    try {
        const btn = document.querySelector('button[onclick="window.syncStaffToCloud()"]');
        if (btn) btn.innerHTML = "⏳ Syncing...";

        // 1. Fetch the absolute truth strictly from the staff_registry table
        const { data, error } = await window.supabaseClient
            .from('staff_registry')
            .select('*')
            .order('date_added', { ascending: false });
        
        if (error) throw error;

        if (data) {
            // 2. Overwrite local arrays with the cloud truth
            window.staffRegistry = data;
            localStorage.setItem('havenStaffRegistry', JSON.stringify(data));
            
            // 3. Update the UI instantly
            window.renderUnifiedStaffDirectory();
            
            if (isMigration) {
                alert(`✅ Upgrade Complete! Fetched ${data.length} staff records from the new unified database.`);
            } else {
                console.log(`Cloud sync successful: ${data.length} records loaded.`);
            }
        }
    } catch (e) {
        console.error("❌ Database sync error:", e);
        alert(`⚠️ Failed to sync with cloud: ${e.message}`);
    } finally {
        const btn = document.querySelector('button[onclick="window.syncStaffToCloud()"]');
        if (btn) btn.innerHTML = "☁️ Sync Cloud";
    }
};

