window.updatePayrollDropdown = function() {
    // 1. Target BOTH dropdowns
    const paySelect = document.getElementById('payEmpSelect');
    const loanSelect = document.getElementById('loanEmpSelect');
    
    // Save current selections so they don't reset if refreshed mid-action
    const currentPayVal = paySelect ? paySelect.value : '';
    const currentLoanVal = loanSelect ? loanSelect.value : '';
    
    // Reset options
    if (paySelect) paySelect.innerHTML = '<option value="">-- Select Staff Member --</option>';
    if (loanSelect) loanSelect.innerHTML = '<option value="">-- Select Staff Member --</option>';
    
    // 2. Gather staff from multiple sources with priority to unified registry
    let allStaff = [];
    
    // Priority 1: Unified registry (NEW system)
    if (window.staffRegistry && window.staffRegistry.length > 0) {
        allStaff.push(...window.staffRegistry);
    }
    
    // Priority 2: Old systems (for backward compatibility)
    if (window.staffAccounts) allStaff.push(...window.staffAccounts.filter(s => !allStaff.some(a => a.id === s.id)));
    if (window.users) allStaff.push(...window.users.filter(u => !allStaff.some(a => a.id === u.id)));
    if (window.teachers) allStaff.push(...window.teachers.filter(t => !allStaff.some(a => a.id === t.id)));
    
    // 3. Deduplicate and format staff list
    let uniqueStaff = {};
    allStaff.forEach(s => {
        let name = s.name || s.username || s.user;
        let id = s.id || s.user;
        let staffType = s.staff_type || s.type || 'Staff';
        
        if (name && id && !uniqueStaff[id]) {
            // Check for loan balances
            let loanBal = parseFloat(s.loanBalance || s.data?.loanBalance) || 0;
            let salary = parseFloat(s.salary || s.data?.salary) || 0;
            let centres = (s.centre_assignments && s.centre_assignments.length) ? s.centre_assignments : (s.centre ? [s.centre] : []);
            
            // Format display name to include type
            let displayName = name;
            if (s.surname) displayName += ' ' + s.surname;
            displayName += ` (${staffType})`;
            
            uniqueStaff[id] = { 
                id: id, 
                name: displayName, 
                loanBalance: loanBal,
                staffType: staffType,
                salary: salary,
                centres: centres,
                phone: s.phone || ''
            };
        }
    });
    
    // 🎯 Cache the full staff list so search/filter/select handlers don't need to re-derive it
    window.__payrollStaffCache = uniqueStaff;

    // 4. Populate BOTH dropdown elements with formatted data
    Object.values(uniqueStaff).forEach(s => {
        const centreAttr = s.centres.join(',');
        const optionHtml = `<option value="${s.id}" data-loan="${s.loanBalance}" data-type="${s.staffType}" data-salary="${s.salary}" data-centre="${centreAttr}">${s.name}</option>`;
        if (paySelect) paySelect.innerHTML += optionHtml;
        if (loanSelect) loanSelect.innerHTML += optionHtml;
    });
    
    // Restore selections
    if (currentPayVal && paySelect) paySelect.value = currentPayVal;
    if (currentLoanVal && loanSelect) loanSelect.value = currentLoanVal;

    // 5. Populate the Centre & Job Title filter dropdowns from the same staff pool
    const centreFilterEl = document.getElementById('payCentreFilter');
    const titleFilterEl = document.getElementById('payTitleFilter');
    if (centreFilterEl) {
        const currentCentreVal = centreFilterEl.value;
        const allCentres = new Set();
        Object.values(uniqueStaff).forEach(s => s.centres.forEach(c => c && allCentres.add(c)));
        centreFilterEl.innerHTML = '<option value="">All Centres</option>' +
            [...allCentres].sort().map(c => `<option value="${c}">${c}</option>`).join('');
        centreFilterEl.value = currentCentreVal;
    }
    if (titleFilterEl) {
        const currentTitleVal = titleFilterEl.value;
        const allTitles = new Set(Object.values(uniqueStaff).map(s => s.staffType).filter(Boolean));
        titleFilterEl.innerHTML = '<option value="">All Job Titles</option>' +
            [...allTitles].sort().map(t => `<option value="${t}">${t}</option>`).join('');
        titleFilterEl.value = currentTitleVal;
    }

    // 6. Populate the Payroll History filter dropdowns with the same Centre/Title pools
    const historyCentreEl = document.getElementById('payHistoryCentreFilter');
    const historyTitleEl = document.getElementById('payHistoryTitleFilter');
    if (historyCentreEl && centreFilterEl) {
        const currentVal = historyCentreEl.value;
        historyCentreEl.innerHTML = centreFilterEl.innerHTML.replace('All Centres', 'All Centres');
        historyCentreEl.value = currentVal;
    }
    if (historyTitleEl && titleFilterEl) {
        const currentVal = historyTitleEl.value;
        historyTitleEl.innerHTML = titleFilterEl.innerHTML;
        historyTitleEl.value = currentVal;
    }
};

// 🎯 Search & filter the staff picker by name, centre (G1/G2/...) and job title
window.filterPayrollStaffDropdown = function() {
    const paySelect = document.getElementById('payEmpSelect');
    if (!paySelect) return;

    const search = (document.getElementById('payStaffSearch')?.value || '').toLowerCase().trim();
    const centre = document.getElementById('payCentreFilter')?.value || '';
    const title = document.getElementById('payTitleFilter')?.value || '';

    Array.from(paySelect.options).forEach(opt => {
        if (!opt.value) return; // Always keep the placeholder option visible
        const name = opt.textContent.toLowerCase();
        const optCentres = (opt.dataset.centre || '').split(',');
        const optTitle = opt.dataset.type || '';

        const matchesSearch = !search || name.includes(search);
        const matchesCentre = !centre || optCentres.includes(centre);
        const matchesTitle = !title || optTitle === title;

        opt.hidden = !(matchesSearch && matchesCentre && matchesTitle);
    });
};

