// 3. The Real-Time Salary & Loan Math Engine
window.calcNetSalary = function() {
    const basic = parseFloat(document.getElementById('payBasic').value) || 0;
    const allow = parseFloat(document.getElementById('payAllowances').value) || 0;
    const bonus = parseFloat(document.getElementById('payBonus').value) || 0;
    const arrears = parseFloat(document.getElementById('payArrears').value) || 0;
    
    const tax = parseFloat(document.getElementById('payTax').value) || 0;
    const med = parseFloat(document.getElementById('payMedical').value) || 0;
    
    const outstandingLoan = parseFloat(document.getElementById('payOutstandingLoan').value) || 0;
    const interestRate = parseFloat(document.getElementById('payLoanInterest').value) || 0;
    const loanRepayment = parseFloat(document.getElementById('payLoan').value) || 0;
    
    // Calculate how much of their repayment goes to the bank (interest) vs paying off their debt
    const interestAmount = outstandingLoan * (interestRate / 100);
    let principalDeduction = loanRepayment - interestAmount;
    if (principalDeduction < 0) principalDeduction = 0; // Prevent weird math if they pay less than interest owed

    const gross = basic + allow + bonus + arrears;
    const deduct = tax + med + loanRepayment;
    const net = gross - deduct;
    
    // Update the visual math helper for the Admin
    const helper = document.getElementById('loanMathHelper');
    if (loanRepayment > 0 && outstandingLoan > 0) {
        helper.innerHTML = `Interest: <strong>$${interestAmount.toFixed(2)}</strong> | Principal Paid: <strong>$${principalDeduction.toFixed(2)}</strong> | Remaining Debt: <strong>$${Math.max(0, outstandingLoan - principalDeduction).toFixed(2)}</strong>`;
    } else {
        helper.innerHTML = '';
    }
    
    const netDisplay = document.getElementById('payNetTotal');
    if (netDisplay) {
        netDisplay.innerText = "$" + net.toFixed(2);
        netDisplay.style.color = net < 0 ? "#e74c3c" : "#27ae60";
    }
    return net;
};
window.submitPayrollExpense = async function() {
    // 1. Role & Connectivity Checks
    const role = window.currentUser?.role || "";
    if (!(role.includes('Level 2') || role.includes('Level 3') || role === 'Admin' || role === 'Chief Admin')) {
        return alert("❌ Access Denied: Only Admins and Finance Officers can process payroll.");
    }

    if (!navigator.onLine) {
        return alert("⚠️ You must be online to authorize payroll and update the cloud ledger.");
    }

    // 2. DOM Elements & Basic Validation
    const empSelect = document.getElementById('payEmpSelect');
    const pStart = document.getElementById('payPeriodStart').value;
    const pEnd = document.getElementById('payPeriodEnd').value;
    
    if (!empSelect.value || !pStart || !pEnd) {
        return alert("Please select an employee and define the pay period dates.");
    }
    if (pStart > pEnd) {
        return alert("The pay-period start date cannot be after the end date.");
    }

    const netPay = window.calcNetSalary();
    if (netPay <= 0) {
        return alert("Net pay must be greater than zero to process payroll.");
    }

    const empId = empSelect.value;
    const empName = empSelect.options[empSelect.selectedIndex].text.split(' (')[0];
    const paymentDate = new Date().toISOString().split('T')[0];

    // 🎯 3. Loan Math Calculation
    const outstandingLoan = parseFloat(document.getElementById('payOutstandingLoan').value) || 0;
    const interestRate = parseFloat(document.getElementById('payLoanInterest').value) || 0;
    const loanRepayment = parseFloat(document.getElementById('payLoan').value) || 0;
    
    const interestAmount = outstandingLoan * (interestRate / 100);
    let principalDeduction = loanRepayment - interestAmount;
    if (principalDeduction < 0) principalDeduction = 0;
    if (loanRepayment > outstandingLoan + interestAmount) {
        return alert(`Loan repayment cannot exceed the outstanding balance plus interest ($${(outstandingLoan + interestAmount).toFixed(2)}).`);
    }
    
    const newLoanBalance = Math.max(0, outstandingLoan - principalDeduction);

    // 4. Map to SQL Table Columns
    const payrollRecord = {
        id: 'PAY-' + Date.now(),
        teacher_id: empId,            
        amount: netPay,                         
        payment_date: paymentDate,              
        payroll_period: `${pStart} to ${pEnd}`, 
        payment_method: 'Bank Transfer',        
        status: 'Paid',
        notes: loanRepayment > 0 ? `Includes $${loanRepayment.toFixed(2)} loan deduction ($${interestAmount.toFixed(2)} interest)` : ''
    };

    try {
        const { data: existingPayroll, error: duplicateError } = await supabaseClient
            .from('payroll_history')
            .select('id')
            .eq('teacher_id', empId)
            .eq('payroll_period', payrollRecord.payroll_period)
            .limit(1);
        if (duplicateError) throw duplicateError;
        if (existingPayroll && existingPayroll.length > 0) {
            return alert(`Payroll has already been processed for ${empName} for this period.`);
        }

        let userDataBeforeLoanUpdate = null;
        let userDataAfterLoanUpdate = null;
        let userIdForLoan = null;

        if (loanRepayment > 0) {
            const { data: userRecord, error: userError } = await supabaseClient
                .from('users')
                .select('id, data')
                .or(`id.eq.${empId},username.eq.${empId}`)
                .maybeSingle();
            if (userError) throw userError;
            if (!userRecord) throw new Error('The selected employee has no user account to receive the loan repayment.');

            userIdForLoan = userRecord.id;
            userDataBeforeLoanUpdate = typeof userRecord.data === 'string' ? JSON.parse(userRecord.data) : (userRecord.data || {});
            userDataAfterLoanUpdate = { ...userDataBeforeLoanUpdate, loanBalance: newLoanBalance };
            const { error: loanError } = await supabaseClient
                .from('users')
                .update({ data: userDataAfterLoanUpdate })
                .eq('id', userIdForLoan);
            if (loanError) throw loanError;
        }

        // Payroll remains private in payroll_history; the Vault reads it as a Chief-Admin-only outflow.
        const { error: payrollError } = await supabaseClient.from('payroll_history').insert([payrollRecord]);
        if (payrollError) {
            if (userIdForLoan) {
                await supabaseClient.from('users').update({ data: userDataBeforeLoanUpdate }).eq('id', userIdForLoan);
            }
            throw payrollError;
        }

        // 7. Keep the local loan display synchronized only after both writes succeed.
        if (loanRepayment > 0) {
            
            // Update local memory so the dropdown updates instantly
            if (window.users) {
                let u = window.users.find(u => u.id === empId);
                if (u) u.loanBalance = newLoanBalance;
            }
            if (window.staffAccounts) {
                let s = window.staffAccounts.find(s => s.id === empId);
                if (s) s.loanBalance = newLoanBalance;
            }
        }

        // 8. Update Local Memory arrays
        if (!window.payrollHistory) window.payrollHistory = [];
        if (!window.expenses) window.expenses = [];
        // 🎯 Keep a denormalized name/title/centre locally so the history table never has to guess later
        const staffInfo = (window.__payrollStaffCache || {})[empId];
        window.payrollHistory.push({
            ...payrollRecord,
            teacher_name: empName,
            teacher_title: staffInfo ? staffInfo.staffType : undefined,
            teacher_centre: staffInfo && staffInfo.centres.length ? staffInfo.centres.join(', ') : undefined
        });
   
        
       // ... (Your existing Step 9 system updates remain here)
        if (typeof window.calculateReconciliation === 'function') window.calculateReconciliation();
        if (typeof window.renderPayrollHistory === 'function') window.renderPayrollHistory();
        window.updatePayrollDropdown(); 

        // --- NEW PRINT LOGIC ---
        // Prepare the data for the payslip
        const payslipData = {
            name: empName,
            id: empId,
            period: `${pStart} to ${pEnd}`,
            date: paymentDate,
            netPay: netPay,
            loanRepayment: loanRepayment,
            interestAmount: interestAmount,
            newLoanBalance: newLoanBalance,
            title: staffInfo ? staffInfo.staffType : 'Staff Member',
            centre: staffInfo && staffInfo.centres.length ? staffInfo.centres.join(', ') : 'N/A'
        };

        // Ask the user if they want to print before clearing the form
        const wantToPrint = confirm(`✅ Payroll Processed!\n\n${empName}'s salary of $${netPay.toFixed(2)} has been recorded.\n${loanRepayment > 0 ? `New Loan Balance: $${newLoanBalance.toFixed(2)}\n\n` : '\n'}Would you like to print the payslip now?`);
        
        if (wantToPrint) {
            window.printPayslip(payslipData);
        }

        // 10. Clear Form (moved to after the print prompt)
        document.querySelectorAll('.pay-earn, .pay-deduct').forEach(el => el.value = "0");
        document.getElementById('payOutstandingLoan').value = "0";
        document.getElementById('payLoanInterest').value = "0";
        empSelect.value = "";
        window.calcNetSalary();

    } catch (e) {
        console.error("Payroll Error:", e);
        alert("⚠️ Failed to securely save payroll to the cloud: " + (e.message || "Check console for details."));
    }
};
