// ==========================================
window.renderFeeStructures = function() {
    const tbody = document.getElementById('savedFeesTableBody');
    if (!tbody) return;
    tbody.innerHTML = ''; // Clear the table

    // 1. THE AGGRESSIVE SANITIZER (From render 6373)
    // We must ensure the data is ALWAYS a clean array so the delete function doesn't crash.
    let rawData = window.feeStructures || [];
    let safeArray = [];

    if (Array.isArray(rawData)) {
        safeArray = rawData;
    } else if (rawData && typeof rawData === 'object') {
        // Convert object to array safely
        safeArray = Object.keys(rawData).map(key => {
            return { id: key, fees: rawData[key] };
        });
    }

    // CRITICAL: Save the fixed array back to the global variable
    window.feeStructures = safeArray;

    // 2. EMPTY STATE
    if (safeArray.length === 0) {
        tbody.innerHTML = '<tr><td colspan="4" style="text-align: center; color: #7f8c8d; padding: 20px;">No fee structures saved yet.</td></tr>';
        return;
    }

    // 3. RENDER UI WITH HORIZONTAL TABS (From the Update)
    safeArray.forEach((feeStruct) => {
        const gradeName = feeStruct.id || feeStruct.grade || "Unknown Class";
        
        // Handle different data structures safely
        let charges = [];
        if (Array.isArray(feeStruct.fees)) charges = feeStruct.fees;
        else if (Array.isArray(feeStruct.items)) charges = feeStruct.items;
        else if (Array.isArray(feeStruct)) charges = feeStruct;

        let total = 0;

        const tr = document.createElement('tr');

        // Column 1: Grade/Class Name
        const tdGrade = document.createElement('td');
        tdGrade.innerHTML = `<strong style="color: #2c3e50; font-size: 14px;">${gradeName}</strong>`;

        // Column 2: The Horizontal Badges (Tabs)
        const tdItems = document.createElement('td');
        const badgeContainer = document.createElement('div');
        badgeContainer.style.display = 'flex';
        badgeContainer.style.flexWrap = 'wrap';
        badgeContainer.style.gap = '8px';

        if (charges.length > 0) {
            charges.forEach(charge => {
                const name = charge.name || charge.desc || "Item";
                const amt = parseFloat(charge.amount || charge.fee) || 0;
                total += amt;

                // Create the small horizontal tab/badge
                const badge = document.createElement('span');
                badge.style.background = '#e8f4f8';
                badge.style.border = '1px solid #3498db';
                badge.style.color = '#2980b9';
                badge.style.padding = '4px 10px';
                badge.style.borderRadius = '15px'; // Pill shape
                badge.style.fontSize = '11px';
                badge.style.fontWeight = 'bold';
                badge.innerHTML = `${name}: $${amt.toFixed(2)}`;
                
                badgeContainer.appendChild(badge);
            });
        } else {
            badgeContainer.innerHTML = `<span style="color:#7f8c8d; font-size:12px; font-style:italic;">Base fee only</span>`;
        }
        tdItems.appendChild(badgeContainer);

        // Column 3: Total Base Fee
        const tdTotal = document.createElement('td');
        tdTotal.style.textAlign = 'right';
        tdTotal.style.whiteSpace = 'nowrap'; // Prevents total from wrapping
        tdTotal.innerHTML = `<strong style="color: #d35400; font-size: 16px;">$${total.toFixed(2)}</strong>`;

        // Column 4: Action Button (Fixed Overlap)
        const tdAction = document.createElement('td');
        tdAction.style.textAlign = 'center';
        tdAction.style.whiteSpace = 'nowrap'; // Prevents button from squishing

        const delBtn = document.createElement('button');
        delBtn.className = 'btn-standard btn-danger admin-edit-only'; 
        delBtn.style.padding = '6px 12px';
        delBtn.style.fontSize = '12px';
        delBtn.innerHTML = '🗑️ Delete';
        delBtn.onclick = async function() {
            if(confirm(`Delete fee structure for ${gradeName}?`)) {
                
                // 1. Remove Locally
                window.feeStructures = window.feeStructures.filter(f => (f.id || f.grade) !== gradeName);
                localStorage.setItem('havenFeeStructures', JSON.stringify(window.feeStructures));
                window.renderFeeStructures(); // Refresh UI instantly

                // 2. Remove from Cloud (Supabase)
                if (navigator.onLine && typeof supabaseClient !== 'undefined') {
                    try {
                        await supabaseClient.from('fee_structures').delete().eq('id', gradeName);
                        console.log(`✅ Deleted ${gradeName} fees from cloud.`);
                    } catch (e) {
                        console.error("Cloud delete failed:", e);
                    }
                }
            }
        };

        tdAction.appendChild(delBtn);

        // Pack the row and push to table
        tr.appendChild(tdGrade);
        tr.appendChild(tdItems);
        tr.appendChild(tdTotal);
        tr.appendChild(tdAction);

        tbody.appendChild(tr);
    });
};

