// 🧠 UPGRADED: Now accepts the ID of the specific button you want to show
window.saveFormStateToHistory = function(formId, inputValuesObject, undoBtnId) {
    if (!window.formHistoryStack) window.formHistoryStack = [];
    
    window.formHistoryStack.push({
        formId: formId,
        state: inputValuesObject,
        timestamp: Date.now(),
        undoBtnId: undoBtnId // Remembers which specific button to hide later
    });
    
    // Keep memory clean
    if (window.formHistoryStack.length > 10) window.formHistoryStack.shift();
    
    // Show the SMART local undo button right next to where they clicked
    if (undoBtnId) {
        const btn = document.getElementById(undoBtnId);
        if (btn) btn.style.display = 'block'; 
    }
};

// 🧠 UPGRADED: Automatically hides the specific button after you click it
window.restoreLastFormState = function() {
    if (!window.formHistoryStack || window.formHistoryStack.length === 0) return;

    const lastState = window.formHistoryStack.pop();

    // Loop through the saved snapshot and put the values back
    for (let inputId in lastState.state) {
        const inputElement = document.getElementById(inputId);
        if (inputElement) {
            inputElement.value = lastState.state[inputId];
        }
    }
    
    // Hide the local Undo button again
    if (lastState.undoBtnId) {
        const btn = document.getElementById(lastState.undoBtnId);
        if (btn) btn.style.display = 'none';
    }

    // Refresh UI logic specific to Enrollment
    if (typeof window.previewEnrollmentFees === 'function') {
        window.previewEnrollmentFees();
    }
};

