window.registerStaff = async function() {
    // 1. Security Check
    const userRole = window.currentUser?.role || "";
    if (!(userRole.includes('Level 2') || userRole.includes('Level 3') || userRole === 'Chief Admin')) {
        return alert("❌ Access Denied: Only Admins can register new staff.");
    }

    // 2. Gather Basic Info
    const name = document.getElementById('staffName').value.trim();
    const username = document.getElementById('staffUsername').value.trim();
    const pass = document.getElementById('staffPassword').value;
    const role = document.getElementById('staffRole').value;
    const type = document.getElementById('staffType').value;

    if (!name || !username || !pass) return alert("Please fill in Name, Username, and Password.");

    // 3. Strict Duplicate Name/Username Check
    const nameLower = name.toLowerCase();
    const usernameLower = username.toLowerCase();

    const existsInUsers = (window.users || []).some(u => {
        const existingName = (u.name || u.user || u.username || "").toLowerCase();
        const existingUsername = (u.username || u.user || "").toLowerCase();
        return existingName === nameLower || existingName === usernameLower || existingUsername === usernameLower;
    });

    const existsInStaff = (window.staffAccounts || []).some(s => 
        (s.username || "").toLowerCase() === usernameLower || 
        (s.name || "").toLowerCase() === nameLower
    );

    if (existsInUsers || existsInStaff) {
        return alert("❌ A user with this Name or Username already exists! Please choose a different one.");
    }

    // 4. Gather Dynamic Capabilities
    let capabilities = { grades: "", subjects: "", forms: "" };
    let subjectArray = []; 
    
    if (type === "Primary") {
        capabilities.grades = document.getElementById('capableGrades').value.trim();
        if (!capabilities.grades) return alert("Please enter the qualified grades for this Primary teacher.");
        subjectArray = ["Class Teacher"];
    } else if (type === "Secondary") {
        capabilities.subjects = document.getElementById('capableSubjects').value.trim();
        capabilities.forms = document.getElementById('capableForms').value.trim();
        if (!capabilities.subjects || !capabilities.forms) return alert("Please enter the subjects and forms for this High School teacher.");
        subjectArray = capabilities.subjects.split(',').map(s => s.trim()).filter(s => s !== "");
    }

    const uniqueId = "USR-" + Date.now();

    // 5. Construct the Universal Data Object
    const newStaff = {
        id: uniqueId,
        name: name,
        user: username,         
        username: username,
        pass: pass,             
        password: pass, 
        role: role,
        type: type,
        capabilities: capabilities
    };

    // 6. Save Locally
    if (!window.staffAccounts) window.staffAccounts = [];
    window.staffAccounts.push(newStaff);
    localStorage.setItem('havenStaffAccounts', JSON.stringify(window.staffAccounts));

    if (!window.users) window.users = [];
    window.users.push(newStaff);

    // 7. Save to Cloud (Supabase)
    if (!navigator.onLine) {
        clearFormAndRefresh();
        return alert("⚠️ Saved locally, but you are offline. The user account will sync to the cloud later.");
    }

    if (typeof supabaseClient !== 'undefined') {
        try {
            // A. Save Login to 'users' table 
            const userUpdates = [{ 
                id: username, 
                data: newStaff 
            }];
            
            const { error: userError } = await supabaseClient.from('users').upsert(userUpdates);
            if (userError) throw userError;

            // B. Build Academic Profile for the 'teachers' table (FIXED SECTION)
            if (type === "Primary" || type === "Secondary") {
                const newTeacherProfile = {
                    id: username, 
                    name: name,
                    // Convert array to a comma-separated string so the DB 'text' column accepts it
                    subjects: subjectArray.join(', '), 
                    // Lowercase names matching your SQL schema exactly
                    assignedclass: "Unassigned",
                    assignedsubject: "N/A"
                };

                const { error: teacherError } = await supabaseClient.from('teachers').upsert([newTeacherProfile]);
                if (teacherError) {
                    console.warn("Could not save to teachers table:", teacherError);
                    alert("⚠️ Saved user, but failed to create teacher profile in DB.");
                } else {
                    if (!window.teachers) window.teachers = [];
                    window.teachers.push(newTeacherProfile);
                }
            }

            console.log("✅ Staff successfully saved to all relevant cloud tables.");
            alert(`✅ ${name} successfully registered as ${role}! Saved to cloud.`);
            clearFormAndRefresh();

        } catch (err) {
            console.error("Cloud save failed:", err);
            alert("⚠️ Saved locally, but failed to sync to cloud. Check connection.");
        }
    }

    // Helper function to handle UI cleanup
    function clearFormAndRefresh() {
        document.getElementById('staffName').value = '';
        document.getElementById('staffUsername').value = '';
        document.getElementById('staffPassword').value = '';
        
        if(document.getElementById('capableGrades')) document.getElementById('capableGrades').value = '';
        if(document.getElementById('capableSubjects')) document.getElementById('capableSubjects').value = '';
        if(document.getElementById('capableForms')) document.getElementById('capableForms').value = '';
        
        if (typeof window.renderStaffDirectory === 'function') window.renderStaffDirectory();
        if (typeof window.renderStaffList === 'function') window.renderStaffList();
        if (typeof window.updateTeacherDropdowns === 'function') window.updateTeacherDropdowns();
        if (typeof window.renderAllocationsTable === 'function') window.renderAllocationsTable();
    }
};

