window.registerUnifiedStaff = async function() {
    // 1. SECURITY CHECK
    const userRole = window.currentUser?.role || "";
    if (!(userRole.includes('Level 2') || userRole.includes('Level 3') || userRole === 'Chief Admin')) {
        return alert("❌ Access Denied: Only Admins (Level 2+) can register staff.");
    }

    // 2. GATHER BASIC INFO
    const staffType = document.getElementById('unifiedStaffType').value.trim();
    const name = document.getElementById('unifiedName').value.trim();
    const surname = document.getElementById('unifiedSurname').value.trim();
    const phone = document.getElementById('unifiedPhone').value.trim();
    const centres = Array.from(document.getElementById('unifiedCentre').selectedOptions).map(o => o.value);
    
    // Validation
    if (!staffType) return alert("❌ Please select a Staff Type (Teacher, Driver, or Auxiliary).");
    if (!name) return alert("❌ Please enter staff name.");
    if (centres.length === 0) return alert("❌ Please select at least one centre.");

    // 3. HANDLE LOGIN ACCESS
    let username = '';
    let password = '';
    let role = 'Level 1';
    const hasLogin = document.getElementById('unifiedHasLogin').checked;
    
    if (hasLogin) {
        username = document.getElementById('unifiedUsername').value.trim();
        password = document.getElementById('unifiedPassword').value;
        role = document.getElementById('unifiedRole').value;
        
        if (!username || !password) return alert("❌ If granting login, please provide Username and Password.");
        
        // Check for duplicate username
        const usernameLower = username.toLowerCase();
        const existingUser = (window.users || []).some(u => (u.username || '').toLowerCase() === usernameLower);
        if (existingUser) return alert("❌ Username already exists! Please choose another.");
    }

    // 4. GATHER PAYROLL INFO
    const salary = parseFloat(document.getElementById('unifiedSalary').value) || 0;
    const paymentMethod = document.getElementById('unifiedPaymentMethod').value;
    const bankAccount = document.getElementById('unifiedBankAccount').value.trim();

    // 5. CREATE BASE STAFF OBJECT
    const uniqueId = "STF-" + Date.now();
    const newStaff = {
        id: uniqueId,
        name: name,
        surname: surname,
        phone: phone,
        staff_type: staffType,
        centre_assignments: centres,
        has_login: hasLogin,
        username: username || null,
        password: password || null,
        role: hasLogin ? role : null,
        salary: salary,
        payment_method: paymentMethod,
        bank_account: bankAccount,
        date_added: new Date().toISOString(),
        added_by: window.currentUser?.name || 'System'
    };

    // 6. ADD TYPE-SPECIFIC FIELDS
    if (staffType === 'Teacher') {
        const teacherType = document.getElementById('unifiedTeacherType').value;
        const grades = document.getElementById('unifiedTeacherGrades').value.trim();
        const subjects = document.getElementById('unifiedTeacherSubjects').value.trim();
        const forms = document.getElementById('unifiedTeacherForms').value.trim();
        
        if (teacherType === 'Primary' && !grades) {
            return alert("❌ Please enter qualified grades for this Primary teacher.");
        }
        if (teacherType === 'Secondary' && (!subjects || !forms)) {
            return alert("❌ Please enter subjects and forms for this Secondary teacher.");
        }
        
        newStaff.teacher_type = teacherType;
        newStaff.qualified_grades = grades;
        newStaff.qualified_subjects = subjects;
        newStaff.qualified_forms = forms;
        
    } else if (staffType === 'Driver') {
        const vehicleType = document.getElementById('unifiedVehicleType').value.trim();
        const vehicleReg = document.getElementById('unifiedVehicleReg').value.trim();
        const licenseNum = document.getElementById('unifiedLicenseNum').value.trim();
        const licenseExp = document.getElementById('unifiedLicenseExp').value;
        const routes = Array.from(document.querySelectorAll('.driverRoute:checked')).map(cb => cb.value);
        
        if (!vehicleType || !vehicleReg) {
            return alert("❌ Please enter vehicle type and registration for driver.");
        }
        
        newStaff.vehicle_type = vehicleType;
        newStaff.vehicle_registration = vehicleReg;
        newStaff.license_number = licenseNum;
        newStaff.license_expiry = licenseExp;
        newStaff.routes = routes;
        
    } else if (staffType === 'Auxiliary') {
        const jobDesc = document.getElementById('unifiedJobDesc').value;
        const department = document.getElementById('unifiedDepartment').value.trim();
        
        if (!jobDesc) return alert("❌ Please select a job description for this auxiliary staff.");
        
        newStaff.job_description = jobDesc;
        newStaff.department = department;
    }

    // 7. SAVE LOCALLY
    if (!window.staffRegistry) window.staffRegistry = [];
    window.staffRegistry.push(newStaff);
    localStorage.setItem('havenStaffRegistry', JSON.stringify(window.staffRegistry));

    // Also add to users array if has login
    if (hasLogin) {
        if (!window.users) window.users = [];
        window.users.push({
            id: username,
            name: name,
            user: username,
            username: username,
            pass: password,
            password: password,
            role: role
        });
        localStorage.setItem('havenUsers', JSON.stringify(window.users));
    }

    // 8. SAVE TO CLOUD (if online)
    if (!navigator.onLine) {
        alert("⚠️ Saved locally. The staff member will sync to cloud when you're online.");
        clearUnifiedForm();
        return;
    }

    try {
        if (!window.supabaseClient || !window.supabaseReady) {
            console.warn('Supabase not ready');
            alert("⚠️ Saved locally. Cloud sync not available.");
            clearUnifiedForm();
            return;
        }

        // Try to insert into Supabase (requires staff_registry table to exist)
        let cloudSaved = false;
        try {
            console.log('Attempting to save staff to cloud:', { id: uniqueId, name: name, type: staffType });
            
            const { data, error: dbError } = await window.supabaseClient
                .from('staff_registry')
                .insert([newStaff])
                .select();
            
            if (dbError) {
                console.error('❌ Staff insert error:', dbError);
                
                // If table doesn't exist (PGRST116, 42P01) or schema mismatch, that's OK
                if (dbError.code === 'PGRST116' || dbError.code === '42P01' || 
                    dbError.message?.includes('relation') || dbError.message?.includes('does not exist')) {
                    console.warn("⚠️ staff_registry table not yet configured - will use local only");
                } else {
                    console.warn("Could not save to staff_registry table:", dbError.message);
                }
            } else {
                cloudSaved = true;
                console.log('✅ Staff saved to cloud:', data);
            }
        } catch (e) {
            console.error("staff_registry insert exception:", e.message);
        }

        // If has login, also save to users table
        if (hasLogin) {
            try {
                console.log('Attempting to save user to cloud:', { username: username });
                
                const { data, error: userError } = await window.supabaseClient.from('users')
                    .upsert([{
                        id: username,
                        name: name,
                        username: username,
                        password: password,
                        role: role,
                        staff_id: uniqueId
                    }])
                    .select();
                
                if (userError) {
                    console.error('❌ User insert error:', userError.message);
                } else {
                    console.log('✅ User saved to cloud:', data);
                }
            } catch (e) {
                console.error("Users table insert exception:", e.message);
            }
        }

        // ... (Keep all your existing Cloud Save logic here) ...

        const syncNote = cloudSaved ? "" : " (Local storage only - cloud table pending)";
        alert(`✅ ${name} successfully registered as ${staffType}!${syncNote}`);
        
        clearUnifiedForm();
        
        // 🚀 NEW: Instantly refresh the directory on screen to show the new staff member
        window.renderUnifiedStaffDirectory();

    } catch (err) {
        console.error("Cloud save error:", err);
        alert("⚠️ Saved locally. Check your connection and try syncing manually.");
        clearUnifiedForm();
        window.renderUnifiedStaffDirectory();
    }
};

