window.initAttendanceTab = function() {
    const dateInput = document.getElementById('attendanceDate');
    if (dateInput) dateInput.valueAsDate = new Date(); // Defaults to today
    
    const classSelect = document.getElementById('attendanceClass');
    if (!classSelect) return;
    
    classSelect.innerHTML = '<option value="">-- Choose Class --</option>';
    
    const classes = window.officialClasses || [];
    const role = window.currentUser?.role || "";
    const teacherName = window.currentUser?.user || window.currentUser?.name || "";

    // SECURITY CHECK: If the user is a Teacher (Level 1), filter their classes
    if (role.includes('Level 1') || role === 'Teacher') {
        // Find classes where this specific teacher is assigned
        const myAllocations = (window.allocations || []).filter(a => (a.teachername || a.teacher_name || a.teacherName || a.teacher) === teacherName);

        if (myAllocations.length === 0) {
            classSelect.innerHTML = '<option value="" disabled>⚠️ You have no assigned classes.</option>';
            return;
        }

        // Populate only their assigned classes
        myAllocations.forEach(alloc => {
            const className = alloc.classname || alloc.class_name || alloc.className || alloc.class;
            classSelect.innerHTML += `<option value="${className}">${className} (${alloc.subject || 'Class Teacher'})</option>`;
        });

    } else {
        // Admins (Level 2/Level 3) can see and manage all classes
        classes.forEach(c => {
            classSelect.innerHTML += `<option value="${c.level || c.className}">${c.level || c.className}</option>`;
        });
    }
};

