// 2. LOAD: Runs on App Start to fetch the saved fee
async function loadApplicationData() {
    try {
        // Fetch global configurations from Supabase
        const { data: settingsData, error } = await window.supabase
            .from('settings')
            .select('*')
            .single();

        if (error) throw error;

        if (settingsData) {
            // Map DB snake_case to JS camelCase
            window.settings = {
                admissionFee: parseFloat(settingsData.admission_fee) || 0
            };
            
            // Populate the UI input box
            const feeInput = document.getElementById('setAdmissionFee');
            if (feeInput) {
                feeInput.value = window.settings.admissionFee;
            }
        }
    } catch (err) {
        console.warn("Retrying from local storage fallback...");
        const local = localStorage.getItem('school_settings');
        if (local) {
            window.settings = JSON.parse(local);
            const feeInput = document.getElementById('setAdmissionFee');
            if (feeInput) feeInput.value = window.settings.admissionFee;
        }
    }
}
