window.autoFillEcoCash = function() {
    const refInput = document.getElementById('regEcoCashRef');
    const paymentInput = document.getElementById('regOnlinePayment');
    
    if (!refInput || !paymentInput) return;

    // Grab what the clerk typed and clean it up
    const typedRef = refInput.value.trim().toUpperCase();
    
    if (typedRef === "") {
        alert("Please enter a Reference Number first.");
        return;
    }

    // Safety fallback just in case the pool hasn't loaded
    window.ecoCashTransactions = window.ecoCashTransactions || [];

    // 1. Search the unallocated pool
    const foundTransaction = window.ecoCashTransactions.find(t => t.ref === typedRef);

    // 2. Run the Security Checks
    if (!foundTransaction) {
        alert(`❌ Reference ${typedRef} not found. Please check with Accounting.`);
        paymentInput.value = ''; // Clear the box to prevent mistakes
        // Trigger update to reset preview
        paymentInput.dispatchEvent(new Event('input')); 
        return;
    }

    if (foundTransaction.status === 'claimed') {
        alert(`⚠️ FRAUD ALERT: Reference ${typedRef} was already used by ${foundTransaction.usedBy}!`);
        paymentInput.value = ''; 
        paymentInput.dispatchEvent(new Event('input')); 
        return;
    }

    // 3. SUCCESS! Auto-Fill the Money
    paymentInput.value = foundTransaction.amount;
    
    // ==========================================
    // 🔥 THE MAGIC LINK
    // ==========================================
    // Because Javascript just bypassed the keyboard and forced a number into the box,
    // the browser doesn't know it changed. We have to artificially trigger the 'input' 
    // event so your `$0.00` Master Preview Box recalculates instantly!
    paymentInput.dispatchEvent(new Event('input'));
    
    // Give the clerk a nice success message
    alert(`✅ Success! $${foundTransaction.amount.toFixed(2)} verified and auto-filled.`);
};
// Render the table
window.renderEcoCashTable = function() {
    const tbody = document.getElementById('ecoCashTableBody');
    if (!tbody) return;
    
    tbody.innerHTML = ''; 
    
    // Reverse the array so newest is at the top
    const reversedTransactions = [...(window.ecoCashTransactions || [])].reverse();

    reversedTransactions.forEach(t => {
        let statusBadge = t.status === 'claimed' 
            ? `<span style="background:#e74c3c; color:white; padding:3px 8px; border-radius:12px; font-size:12px;">Claimed by ${t.usedBy}</span>`
            : `<span style="background:#f1c40f; color:#333; padding:3px 8px; border-radius:12px; font-size:12px;">Unclaimed</span>`;

        tbody.innerHTML += `
            <tr style="border-bottom: 1px solid #eee;">
                <td style="padding: 10px 5px;">${t.date}</td>
                <td style="padding: 10px 5px; font-weight: bold; color: #2980b9;">${t.ref}</td>
                <td style="padding: 10px 5px; color: #27ae60; font-weight: bold;">$${t.amount.toFixed(2)}</td>
                <td style="padding: 10px 5px;">${statusBadge}</td>
            </tr>
        `;
    });
};

