window.autoFillFinanceEcoCash = function() {
    const refInput = document.getElementById('financeEcoCashRef');
    const usdInput = document.getElementById('payUsd');
    const zigInput = document.getElementById('payZig'); // Grab ZiG input
    const methodSelect = document.getElementById('payMethod');
    const studentSelect = document.getElementById('payId');
    
    if (!refInput) return;

    const typedRef = refInput.value.trim().toUpperCase();
    
    if (typedRef === "") {
        return alert("⚠️ Please enter an EcoCash Reference Number first.");
    }

    // Search the global pool
    const ecoPool = window.ecoCashTransactions || [];
    const tx = ecoPool.find(t => t.ref.toUpperCase() === typedRef);

    // 1. SECURITY CHECKS (From Version 1)
    if (!tx) {
        alert(`❌ Reference ${typedRef} not found in the system. Check with Admin.`);
        if (usdInput) { usdInput.value = ''; usdInput.dispatchEvent(new Event('input')); }
        if (zigInput) { zigInput.value = ''; zigInput.dispatchEvent(new Event('input')); }
        return;
    }

    if (tx.status === 'claimed') {
        alert(`⚠️ FRAUD ALERT: Reference ${typedRef} was already used by Student ID: ${tx.claimedBy || tx.studentId || 'Unknown'} on ${tx.claimedDate || 'a previous date'}!`);
        if (usdInput) { usdInput.value = ''; usdInput.dispatchEvent(new Event('input')); }
        if (zigInput) { zigInput.value = ''; zigInput.dispatchEvent(new Event('input')); }
        return;
    }

    // 2. AUTO-SELECT STUDENT (From Version 2)
    if (tx.studentId && studentSelect) {
        studentSelect.value = tx.studentId;
        // Trigger UI update for the student balance
        if (typeof previewStudentBalance === 'function') previewStudentBalance();
    }

    // 3. FLIP PAYMENT METHOD
    if (methodSelect) {
        methodSelect.value = 'EcoCash';
    }

    // 4. AUTO-FILL MONEY (Handling both ZiG and USD)
    if (tx.currency === 'ZIG' || tx.currency === 'ZiG' || tx.zigAmount > 0) {
        if (zigInput) {
            zigInput.value = tx.zigAmount || tx.amount;
            zigInput.dispatchEvent(new Event('input')); // Force UI to recognize typing
        }
        if (usdInput) usdInput.value = '';
    } else {
        if (usdInput) {
            usdInput.value = tx.amount;
            usdInput.dispatchEvent(new Event('input')); // Force UI to recognize typing
        }
        if (zigInput) zigInput.value = '';
    }

    // 5. TRIGGER CALCULATORS
    if (typeof updatePaymentLiveTotals === 'function') updatePaymentLiveTotals();

    // 6. STAGE FOR CHECKOUT (Do NOT mark as claimed yet!)
    // We store the reference globally so your processPayment() function knows to mark it claimed *only* after success.
    window.stagedEcoCashRef = tx.ref; 

    alert(`✅ Success! Reference ${typedRef} verified.\nAmount: ${tx.currency === 'ZIG' ? 'ZiG' : '$'}${tx.amount}\n\nThe details are loaded. You may now process the payment.`);
};

