// 1. Initialize the Class Dropdown for the Heatmap
window.initHeatmapDropdowns = function() {
    const heatmapSelect = document.getElementById('heatmapClass');
    const dailySelect = document.getElementById('attendanceClass'); // Your existing daily register dropdown
    
    if (!heatmapSelect) return;

    // Set default dates if they aren't set yet
    if (!document.getElementById('heatmapEnd').value) {
        const today = new Date();
        const lastWeek = new Date();
        lastWeek.setDate(today.getDate() - 7);
        document.getElementById('heatmapEnd').valueAsDate = today;
        document.getElementById('heatmapStart').valueAsDate = lastWeek;
    }

    heatmapSelect.innerHTML = '<option value="" disabled selected>-- Choose Class --</option>';

    let classesLoaded = false;

    // STRATEGY 1: Clone the options from the daily attendance dropdown (Safest method)
    if (dailySelect && dailySelect.options && dailySelect.options.length > 0) {
        Array.from(dailySelect.options).forEach(opt => {
            // Ignore placeholder or disabled options
            if (opt.value && !opt.disabled && opt.value.trim() !== "") {
                heatmapSelect.innerHTML += `<option value="${opt.value}">${opt.text}</option>`;
                classesLoaded = true;
            }
        });
    } 
    // STRATEGY 2: Fallback to your global arrays if the dropdown isn't built yet
    if (!classesLoaded) {
        const classes = window.classes || window.officialClasses || [];
        classes.forEach(c => {
            const className = typeof c === 'string' ? c : (c.level || c.className || c.name);
            if (className) {
                heatmapSelect.innerHTML += `<option value="${className}">${className}</option>`;
                classesLoaded = true;
            }
        });
    }

    // IF STILL EMPTY: The database is probably still fetching. Try again in 1.5 seconds.
    if (!classesLoaded) {
        setTimeout(window.initHeatmapDropdowns, 1500);
    }
};

