// 2. The Core Rendering Engine
window.renderAttendanceHeatmap = function() {
    const className = document.getElementById('heatmapClass').value;
    const startDate = document.getElementById('heatmapStart').value;
    const endDate = document.getElementById('heatmapEnd').value;
    const highlight = document.getElementById('heatmapHighlight').value;
    const container = document.getElementById('heatmapTableContainer');

    if (!className || !startDate || !endDate) return;

    // Pull from whatever global array your app uses
    const allData = window.attendanceLogs || window.attendanceData || [];

    // Check if the global array is still completely empty (meaning DB hasn't loaded yet)
    if (allData.length === 0) {
        container.innerHTML = `<div style="padding: 40px; text-align: center; color: #3498db;">
            <h3 style="margin-bottom: 10px;">⏳ Syncing with Database...</h3>
            <p>Please wait a few seconds while Haven downloads the attendance history.</p>
        </div>`;
        
        // Auto-retry the render in 2 seconds
        setTimeout(window.renderAttendanceHeatmap, 2000);
        return; 
    }

    // A. Filter Logs with safe string trimming
    const logs = allData.filter(l => {
        // Force both to be strings and trim spaces to ensure a perfect match
        const logClass = String(l.className || l.class || "").trim();
        const targetClass = String(className).trim();
        
        // YYYY-MM-DD string comparison works perfectly natively
        return logClass === targetClass && l.date >= startDate && l.date <= endDate;
    }).sort((a, b) => new Date(a.date) - new Date(b.date));

    if (logs.length === 0) {
        container.innerHTML = `<div style="padding: 30px; text-align: center; color: #e74c3c; font-weight: bold;">
            No registers found for <strong>${className}</strong> between ${startDate} and ${endDate}. 
            <br><span style="font-size:12px; color:#7f8c8d;">(Make sure your system has downloaded these dates from the database)</span>
        </div>`;
        return;
    }

    // B. Get unique dates (Use Set to prevent duplicate columns)
    const dates = [...new Set(logs.map(l => l.date))];

    // C. Get all students belonging to this class safely
    const classStudents = (window.students || []).filter(s => {
        const studentClass = String(s.grade || s.class || "").trim();
        return studentClass === String(className).trim();
    }).sort((a,b) => a.name.localeCompare(b.name));

    // D. Build the Table Header
    let html = `<table style="width: 100%; border-collapse: collapse; font-size: 12px; text-align: center; white-space: nowrap;">
                    <thead style="background: #2c3e50; color: white; position: sticky; top: 0; z-index: 10;">
                        <tr>
                            <th style="padding: 10px; text-align: left; position: sticky; left: 0; background: #34495e; z-index: 11;">Student Name</th>`;
    
    dates.forEach(d => {
        const shortDate = new Date(d).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
        html += `<th style="padding: 10px; border-left: 1px solid #7f8c8d;">${shortDate}</th>`;
    });

    html += `           <th style="padding: 10px; border-left: 2px solid #fff; background: #27ae60;">Total (P)</th>
                        <th style="padding: 10px; background: #e74c3c;">Total (A)</th>
                        <th style="padding: 10px; background: #f39c12;">Total (L)</th>
                    </tr>
                </thead>
                <tbody style="background: #fff;">`;

    // E. Loop through Students and populate rows
    classStudents.forEach(student => {
        let presentCount = 0;
        let absentCount = 0;
        let lateCount = 0;
        let rowDataHtml = '';

        dates.forEach(d => {
            const log = logs.find(l => l.date === d);
            let status = 'N/A';

            if (log && log.records) {
                try {
                    // CRITICAL FIX: Parse the database string into a real JavaScript array
                    const recordArray = typeof log.records === 'string' ? JSON.parse(log.records) : log.records;
                    const record = recordArray.find(r => r.id === student.id);
                    if (record) status = record.status;
                } catch(e) {
                    console.error("Failed to parse stringified records from database:", e);
                }
            }
            
            let cellBg = '#f8f9fa';
            let cellText = '<span style="color:#bdc3c7">-</span>';

            if (status === 'Present') { cellBg = '#d5f5e3'; cellText = '<strong style="color:#27ae60;">P</strong>'; presentCount++; }
            else if (status === 'Absent') { cellBg = '#fadbd8'; cellText = '<strong style="color:#c0392b;">A</strong>'; absentCount++; }
            else if (status === 'Late') { cellBg = '#fcf3cf'; cellText = '<strong style="color:#d68910;">L</strong>'; lateCount++; }

            rowDataHtml += `<td style="padding: 8px; border: 1px solid #ecf0f1; background: ${cellBg};">${cellText}</td>`;
        });

        // F. Evaluate the Award / Behavior Highlight Rules
        let rowStyle = "border-bottom: 1px solid #ecf0f1;";
        let isMatch = true;

        if (highlight === 'perfect') {
            if (absentCount === 0 && lateCount === 0 && presentCount > 0) rowStyle = "background: #e8f8f5; border: 2px solid #27ae60;";
            else isMatch = false; // Hide if not perfect
        } else if (highlight === 'absent') {
            if (absentCount > 0) rowStyle = "background: #fdedf0; border: 2px solid #e74c3c;";
            else isMatch = false;
        } else if (highlight === 'late') {
            if (lateCount > 0) rowStyle = "background: #fef9e7; border: 2px solid #f39c12;";
            else isMatch = false;
        }

        // Only draw the row if they match the filter (or if filter is 'none')
        if (highlight === 'none' || isMatch) {
            html += `<tr style="${rowStyle}">
                        <td style="padding: 10px; text-align: left; border-right: 1px solid #ecf0f1; position: sticky; left: 0; background: ${rowStyle.includes('background') ? rowStyle.split('background:')[1].split(';')[0] : '#fff'}; z-index: 5;">
                            <strong>${student.name}</strong>
                        </td>
                        ${rowDataHtml}
                        <td style="padding: 10px; border-left: 2px solid #bdc3c7; font-weight: bold; color: #27ae60;">${presentCount}</td>
                        <td style="padding: 10px; border-left: 1px solid #bdc3c7; font-weight: bold; color: #e74c3c;">${absentCount}</td>
                        <td style="padding: 10px; border-left: 1px solid #bdc3c7; font-weight: bold; color: #f39c12;">${lateCount}</td>
                    </tr>`;
        }
    });

    html += `</tbody></table>`;
    container.innerHTML = html;
};

