window.routeToCentralPayment = function(studentId) {
    // 1. Navigate to the Finance tab
    window.navTo('finance');
    
    // 2. Locate the central payment search box
    const payInput = document.getElementById('payId');
    if (payInput) {
        // Auto-fill the ID
        payInput.value = studentId;
        
        // 3. Force the system to recognize the input and fetch the balances
        payInput.dispatchEvent(new Event('input'));
        if (typeof window.previewStudentBalance === 'function') {
            window.previewStudentBalance();
        }
    }
};


// ==========================================
// 42. ENROLLMENT FEE PREVIEW ENGINE (MERGED ULTIMATE)
// ==========================================

window.previewEnrollmentFees = function() {
    // 1. DATABASE SECURITY CHECK
    if (!window.settings || Object.keys(window.settings).length === 0) {
        console.warn("Database settings missing. Triggering UI report.");
        alert("⚠️ WARNING: Global fee structures have not been loaded from the database. Please ensure you are connected to the network or navigate to Global Settings to configure fees.");
        return; 
    }

    // 2. UI ELEMENT SETUP
    const gradeBox = document.getElementById('regGrade') || document.getElementById('grade');
    const planSelect = document.getElementById('regBillingPlan'); 
    const orangeBox = document.getElementById('masterEnrollFeePreview') || document.getElementById('enrollFeePreview') || document.getElementById('invoiceTotalAmount');
    const greyBox = document.getElementById('regFeePreview') || document.getElementById('invoicePreviewContainer');
    const admissionCheckbox = document.getElementById('regChargeAdmission');
    const waiveSelect = document.getElementById('enrollWaiveFeeSelect'); 
    const paymentInput = document.getElementById('regInitialPayment');

    if (!gradeBox || !orangeBox) {
        console.warn("Missing gradeBox or orangeBox in HTML. Preview halted.");
        return;
    }

    // 3. GRADE VALIDATION & WAIVER RESET
    const selectedGrade = gradeBox.value;
    const currentGrade = selectedGrade ? selectedGrade.toUpperCase() : "";
    const selectedPlan = planSelect ? planSelect.value : 'termly'; 

    window.waivedEnrollmentFees = window.waivedEnrollmentFees || [];
    if (window.currentEnrollmentGrade !== selectedGrade) {
        window.waivedEnrollmentFees = []; 
        window.currentEnrollmentGrade = selectedGrade;
    }

    if (!selectedGrade) {
        if (orangeBox.tagName === 'INPUT') orangeBox.value = '$0.00';
        else orangeBox.innerText = '$0.00';
        
        if (greyBox) {
            greyBox.innerHTML = 'Select a grade to see auto-charges.';
            greyBox.style.color = '#7f8c8d';
        }
        if (waiveSelect) waiveSelect.innerHTML = '<option value="">Select fee to waive...</option>';
        return;
    }

    // 4. FETCH BASE TUITION FROM MEMORY (CRITICAL FIX: Integrated JSON parsing)
    let gradeFees = [];
    if (Array.isArray(window.feeStructures)) {
        const struct = window.feeStructures.find(f => (f.id === selectedGrade || f.grade === selectedGrade));
        let rawFees = struct ? (struct.fees || struct.items || struct) : [];
        try {
            // Safely parse if the database returns a stringified JSON array
            gradeFees = typeof rawFees === 'string' ? JSON.parse(rawFees) : (Array.isArray(rawFees) ? rawFees : []);
        } catch (e) {
            console.warn("Could not parse fee structure array:", e);
            gradeFees = [];
        }
    } else if (window.feeStructures && window.feeStructures[selectedGrade]) {
        let rawFees = window.feeStructures[selectedGrade];
        try {
            gradeFees = typeof rawFees === 'string' ? JSON.parse(rawFees) : rawFees;
        } catch (e) {
            gradeFees = [];
        }
    }

    // 5. INITIALIZE MATH & TEXT LOGIC
    let total = 0;
    let textLines = [];
    let dropdownHTML = '<option value="">Select fee to waive...</option>';
    let admissionAlreadyIncluded = false;
    const applyAdmission = admissionCheckbox ? admissionCheckbox.checked : true;

    const addServiceToPreview = (name, amount) => {
        const isWaived = window.waivedEnrollmentFees.includes(name);
        
        if (amount > 0 && !isWaived) {
            total += amount; 
            textLines.push(`<div style="display:flex; justify-content:space-between; color:#34495e; padding: 3px 0; border-bottom: 1px dashed #ccc;"><span>${name}:</span> <strong>$${amount.toFixed(2)}</strong></div>`);
            dropdownHTML += `<option value="${name}">${name} ($${amount.toFixed(2)})</option>`;
        } else if (isWaived) {
            textLines.push(`<div style="display:flex; justify-content:space-between; color:#e74c3c; text-decoration: line-through; padding: 3px 0; border-bottom: 1px dashed #ccc;"><span>${name}:</span> <strong>Waived ($0.00)</strong></div>`);
        }
    };

    // 6. PROCESS GRADE FEES (Tuition with Monthly Split & Exempt Logic)
    if (selectedPlan === 'exempt') {
        textLines.push(`<div style="display:flex; justify-content:space-between; color:#27ae60; padding: 3px 0; border-bottom: 1px dashed #ccc;"><span><b>Fully Exempt Student</b>:</span> <strong>$0.00</strong></div>`);
        admissionAlreadyIncluded = true; 
    } else if (gradeFees && gradeFees.length > 0) {
        gradeFees.forEach(f => {
            let feeName = f.desc || f.name || 'Fee';
            let feeAmount = parseFloat(f.amount) || 0;
            
            const isAdmissionFee = feeName.toLowerCase().includes('admission') || feeName.toLowerCase().includes('enroll') || feeName.toLowerCase().includes('registration');

            if (selectedPlan === 'monthly' && !isAdmissionFee) {
                feeAmount = feeAmount / 3; 
                feeName += " (Monthly Split)";
            }
            
            if (isAdmissionFee) {
                admissionAlreadyIncluded = true;
                if (applyAdmission) addServiceToPreview(feeName, feeAmount);
            } else {
                addServiceToPreview(feeName, feeAmount);
            }
        });
    }
    
    console.log("Fees for this Grade:", gradeFees);
    console.log("Did Section 6 block Section 7?:", admissionAlreadyIncluded);

    // 7. DYNAMIC ADMISSION FALLBACK (ECD vs GRADES)
    if (!admissionAlreadyIncluded && applyAdmission && selectedPlan !== 'exempt') {
        let admFee = 0;
        let admName = "";

        const feeAdmECD = parseFloat(window.settings?.admissionFeeECD) || parseFloat(document.getElementById('tblAdmECD')?.value) || 0;
        const feeAdmGrades = parseFloat(window.settings?.admissionFeeGrades) || parseFloat(document.getElementById('tblAdmGrades')?.value) || 0;

        if (currentGrade.includes("ECD") || currentGrade.includes("TODDLER")) {
            admFee = feeAdmECD;
            admName = "Admission Fee (ECD)";
        } else {
            admFee = feeAdmGrades;
            admName = "Admission Fee (Grades)";
        }

        if (admFee > 0) {
            if (window.waivedEnrollmentFees.includes("Global Admission") && !window.waivedEnrollmentFees.includes(admName)) {
                window.waivedEnrollmentFees.push(admName);
            }
            addServiceToPreview(admName, admFee);
        }
    }

    // 8. ADDITIONAL SERVICES (Using Bulletproof Fallbacks)
    const transVal = parseFloat(document.getElementById('regTransport')?.value) || 0;
    
    const feeFood = parseFloat(window.settings?.foodFee) || parseFloat(document.getElementById('tblFoodFee')?.value) || 0;
    const foodVal = document.getElementById('regFood')?.value === 'true' ? feeFood : 0; 
    
    let statVal = 0;
    if (document.getElementById('regStationery')?.value === 'true') {
        const feeStatECD = parseFloat(window.settings?.stationeryFeeECD) || parseFloat(document.getElementById('tblStatECD')?.value) || 0;
        const feeStatGrades = parseFloat(window.settings?.stationeryFeeGrades) || parseFloat(document.getElementById('tblStatGrades')?.value) || 0;

        if (currentGrade.includes("ECD") || currentGrade.includes("TODDLER")) {
            statVal = feeStatECD;
        } else {
            statVal = feeStatGrades;
        }
    }

    // ✅ THE FIX: Changed textbookFee to textbookFeeGrade
    const feeTextbook = parseFloat(window.settings?.textbookFeeGrade) || parseFloat(document.getElementById('tblTextbook')?.value) || 0;
    const textbookVal = document.getElementById('regTextbooks')?.value === 'true' ? feeTextbook : 0;

    addServiceToPreview('Transport Service', transVal);
    addServiceToPreview('Food Program', foodVal);
    addServiceToPreview('Stationery Pack', statVal);
    addServiceToPreview('Textbooks', textbookVal);
    // 9. CALCULATE INITIAL PAYMENT DEDUCTIONS
    const paymentAmount = paymentInput ? (parseFloat(paymentInput.value) || 0) : 0;
    let finalBalance = total - paymentAmount;
    if (finalBalance < 0) finalBalance = 0;

    // 10. RENDER FINAL HTML OUTPUT
    if (orangeBox.tagName === 'INPUT') {
        orangeBox.value = `$${total.toFixed(2)}`;
    } else {
        orangeBox.innerText = `$${total.toFixed(2)}`;
    }

    if (greyBox) {
        greyBox.style.color = '#7f8c8d'; 

        if (total > 0 || textLines.length > 0) {
            let summaryHTML = textLines.join('') + `<hr style="margin:8px 0; border-top:1px dashed #bdc3c7;">`;
            
            if (paymentAmount > 0) {
                summaryHTML += `<div style="display:flex; justify-content:space-between; font-weight:bold; color:#2c3e50; font-size: 0.95em;"><span>Subtotal:</span> <span>$${total.toFixed(2)}</span></div>`;
                summaryHTML += `<div style="display:flex; justify-content:space-between; color:#27ae60; font-size: 0.95em; border-bottom: 1px solid #bdc3c7; padding-bottom: 3px;"><span>Initial Payment:</span> <span>-$${paymentAmount.toFixed(2)}</span></div>`;
            }

            summaryHTML += `<div style="display:flex; justify-content:space-between; font-weight:bold; font-size: 1.1em; color:#2c3e50; margin-top: 5px;"><span>FINAL INVOICE BALANCE:</span> <span>$${finalBalance.toFixed(2)}</span></div>`;
            
            greyBox.innerHTML = summaryHTML;
        } else {
            greyBox.innerHTML = 'No fees to charge (or all fees waived).';
            greyBox.style.color = '#e74c3c'; 
        }
    }

    // 11. POPULATE WAIVER DROPDOWN & PLACEHOLDERS
    if (waiveSelect) {
        waiveSelect.innerHTML = dropdownHTML;
    }
    
    if (paymentInput && paymentInput.value === '') {
        paymentInput.placeholder = "e.g. " + total.toFixed(2);
    }
};
window.clearEnrollmentForm = function() {
    // 1. Reset text and number inputs
    const inputsToClear = [
        'regName', 'name', 'regInitialPayment', 'regTransport', 'regGrade', 'grade'
    ];
    inputsToClear.forEach(id => {
        const el = document.getElementById(id);
        if (el) el.value = '';
    });

    // 2. Reset Dropdowns to default states
    const planSelect = document.getElementById('regBillingPlan');
    if (planSelect) planSelect.value = 'termly';

    const addonsToReset = ['regFood', 'regStationery', 'regTextbooks'];
    addonsToReset.forEach(id => {
        const el = document.getElementById(id);
        if (el) el.value = 'false';
    });

    // 3. Reset Checkboxes
    const admissionCheckbox = document.getElementById('regChargeAdmission');
    if (admissionCheckbox) admissionCheckbox.checked = true; // Usually on by default

    // 4. Clear the internal Memory/State
    window.waivedEnrollmentFees = [];
    window.currentEnrollmentGrade = "";

    // 5. Trigger the preview function to instantly calculate and show $0.00
    if (typeof window.previewEnrollmentFees === 'function') {
        window.previewEnrollmentFees();
    }
};
