// 2. Main Ledger Generator (Tabbed Version)
window.viewLedger = function(id) {
    const s = window.students.find(st => String(st.id) === String(id));
    if (!s) return alert("Student not found!");
    
    let billingTag = s.billing_plan === 'monthly' ? ' | 🗓️ MONTHLY PAYER' : ' | 📅 TERMLY PAYER';
    if (s.billing_plan === 'exempt') billingTag = ' | 🛡️ EXEMPT';

    if (document.getElementById('currentLedgerStudentId')) document.getElementById('currentLedgerStudentId').value = id;
    if (document.getElementById('modalStudentName')) document.getElementById('modalStudentName').innerText = `${s.name} ${s.billing_plan === 'monthly' ? '🗓️' : ''}`;
    if (document.getElementById('modalStudentIdText')) document.getElementById('modalStudentIdText').innerText = `ID: ${s.id} | Class: ${s.grade || 'N/A'}${billingTag}`;
    const startDate = document.getElementById('ledgerStartDate')?.value || "1900-01-01";
    const endDate = document.getElementById('ledgerEndDate')?.value || "2100-01-01";

    let tBilledStandard = 0, tPaidStandard = 0;
    let tBilledEvent = 0, tPaidEvent = 0;
    let tBilledShop = 0, tPaidShop = 0; 
    let totalUnpaidTab2 = 0;
    
    let htmlStandard = `
        <h4 style="margin: 10px 0; color: #2c3e50;">Standard Tuition & Fees</h4>
        <table style="width:100%; border-collapse:collapse; text-align:left; font-size:13px; margin-bottom: 20px;">
            <thead style="background:#2c3e50; color:white; position:sticky; top:0; z-index:1;">
                <tr>
                    <th style="padding:10px;">Date</th>
                    <th style="padding:10px;">Period</th>
                    <th style="padding:10px;">Description</th>
                    <th style="padding:10px; text-align:right;">Billed ($)</th>
                    <th style="padding:10px; text-align:right;">Paid ($)</th>
                    <th style="padding:10px; text-align:right;">Running Bal ($)</th>
                </tr>
            </thead><tbody>`;

    let htmlEvents = `
        <h4 style="margin: 10px 0; color: #8e44ad;">Events & Trips</h4>
        <table style="width:100%; border-collapse:collapse; text-align:left; font-size:13px; margin-bottom: 20px;">
            <thead style="background:#8e44ad; color:white; position:sticky; top:0; z-index:1;">
                <tr>
                    <th style="padding:10px;">Date</th>
                    <th style="padding:10px;">Period</th>
                    <th style="padding:10px;">Description</th>
                    <th style="padding:10px; text-align:right;">Billed ($)</th>
                    <th style="padding:10px; text-align:right;">Paid ($)</th>
                    <th style="padding:10px; text-align:right;">Running Bal ($)</th>
                </tr>
            </thead><tbody>`;
            
    let htmlShop = `
        <h4 style="margin: 10px 0; color: #d35400;">Uniforms & Shop Matters</h4>
        <table style="width:100%; border-collapse:collapse; text-align:left; font-size:13px; margin-bottom: 20px;">
            <thead style="background:#d35400; color:white; position:sticky; top:0; z-index:1;">
                <tr>
                    <th style="padding:10px;">Date</th>
                    <th style="padding:10px;">Description</th>
                    <th style="padding:10px; text-align:right;">Billed ($)</th>
                    <th style="padding:10px; text-align:right;">Paid/Disc ($)</th>
                    <th style="padding:10px; text-align:right;">Running Bal ($)</th>
                </tr>
            </thead><tbody>`;
    
    let htmlCharges = `<table style="width:100%; border-collapse:collapse; text-align:left; font-size:13px;">
                        <thead style="background:#e74c3c; color:white; position:sticky; top:0; z-index:1;">
                            <tr>
                                <th style="padding:10px;">Charge Description</th>
                                <th style="padding:10px;">Category</th>
                                <th style="padding:10px; text-align:right;">Billed ($)</th>
                                <th style="padding:10px; text-align:right;">Paid ($)</th>
                                <th style="padding:10px; text-align:right;">Left to Pay ($)</th>
                                <th style="padding:10px; text-align:center;">Reverse</th>
                            </tr>
                        </thead><tbody>`;
                        
    let htmlPayments = `<table style="width:100%; border-collapse:collapse; text-align:left; font-size:13px;">
                        <thead style="background:#27ae60; color:white; position:sticky; top:0; z-index:1;">
                            <tr>
                                <th style="padding:10px;">Date</th>
                                <th style="padding:10px;">Receipt & Breakdown</th>
                                <th style="padding:10px; text-align:right;">Amount Paid</th>
                                <th style="padding:10px; text-align:center;">Action</th>
                            </tr>
                        </thead><tbody>`;

    if (s.ledger && Array.isArray(s.ledger)) {
        const chronologicalLedger = [...s.ledger].sort((a, b) => new Date(a.date) - new Date(b.date));

        // TAB 3 (RECEIPTS) - ENHANCED OVERPAYMENT DISPLAY
        chronologicalLedger.forEach(item => {
            const isVoid = item.status === 'VOID' || item.status === 'VOIDED';
            if (!isVoid && (item.type === 'payment' || item.type === 'waiver' || item.type === 'discount' || item.type === 'overpayment')) {
                const method = item.method || 'System';
                const safeDesc = item.description || item.desc || item.notes || item.item || 'General Transaction';
                const receiptBadge = (item.receiptNo || item.receipt_no) ? `<br><small style="color:#6c757d; font-size: 10px;">Ref: ${item.receiptNo || item.receipt_no}</small>` : '';
                
                // 🛡️ Special highlighting for overpayments
                const isOverpayment = item.type === 'overpayment';
                const rowStyle = isOverpayment ? 'background-color:#e8f4f8; border-left: 4px solid #2980b9;' : 'border-bottom:1px solid #dee2e6;';
                const amountColor = isOverpayment ? '#2980b9' : '#27ae60';

                let receiptDescDisplay = `<strong>${safeDesc}</strong> <span style="font-size:10px; color:#555;">(${method})</span>`;
                if (item.breakdown && Array.isArray(item.breakdown) && item.breakdown.length > 0) {
                    receiptDescDisplay = `<strong>Payment Details</strong> <span style="font-size:10px; color:#555;">(${method})</span>`;
                    receiptDescDisplay += `<ul style="margin: 6px 0 0 15px; padding: 0; font-size: 11.5px; line-height: 1.5; color: #1e8449;">`;
                    item.breakdown.forEach(b => {
                        receiptDescDisplay += `<li>${b.desc || b.description}: <strong>$${(parseFloat(b.amt) || 0).toFixed(2)}</strong></li>`;
                    });
                    receiptDescDisplay += `</ul>`;
                }

                let rNo = item.receiptNo || item.receipt_no;
                let actionBtn = rNo ? `<button class="btn-standard btn-success" style="padding:4px 10px; font-size:11px;" onclick="reprintReceipt('${rNo}', '${s.id}')">🖨️ View</button>` : '-';
                let typeLabel = isOverpayment ? '💰 OVERPAYMENT' : '';
                
                htmlPayments += `<tr style="${rowStyle}">
                    <td style="padding:10px; vertical-align:top;">${item.date} ${typeLabel}</td>
                    <td style="padding:10px; vertical-align:top;">${receiptDescDisplay}${receiptBadge}</td>
                    <td style="padding:10px; text-align:right; font-weight:bold; color:${amountColor}; vertical-align:top;">$${(parseFloat(item.amount) || 0).toFixed(2)}</td>
                    <td style="padding:10px; text-align:center; vertical-align:top;">${actionBtn}</td>
                </tr>`;
            }
        });

        let statementLines = [];
        let unallocatedPaymentPool = 0;
        
        const cleanName = (name) => name.replace('Enrollment: ', '').replace('Event/Trip: ', '').replace('Payment for ', '').replace('WAIVED: ', '').replace(' (Admin Selected)', '').replace(' (System Auto)', '').trim();

        // STEP 1: Build Rows from Charges
        chronologicalLedger.forEach(item => {
            if (item.status === 'VOID' || item.status === 'VOIDED') return;
            if (item.type !== 'charge') return;
            if (window.isCreditAllocationAdjustmentCharge(item)) return;

            let amt = parseFloat(item.amount) || 0;
            let safeDesc = item.description || item.desc || item.notes || item.item || item.category || 'General Transaction';
            let rNo = item.receiptNo || item.receipt_no || '';
            
            const isEvent = safeDesc.toLowerCase().includes('event') || safeDesc.toLowerCase().includes('trip') || rNo.startsWith('EVT') || (item.id && String(item.id).includes('EVT'));
            const isShop = safeDesc.toLowerCase().includes('shop') || safeDesc.toLowerCase().includes('uniform') || rNo.startsWith('RCPT') || (item.id && String(item.id).includes('RCPT'));
            const category = isShop ? 'Shop' : (isEvent ? 'Event' : 'Standard');
            let matchedName = cleanName(safeDesc);

            let existing = statementLines.find(l => l.cleanName === matchedName && l.cat === category);
            if(existing) {
                existing.billed += amt;
                if (item.id) existing.chargeIds.push(String(item.id));
            } else {
                statementLines.push({
                    date: item.date,
                    term: item.term || '-',
                    desc: safeDesc,
                    cleanName: matchedName,
                    billed: amt,
                    paid: 0,
                    cat: category,
                    chargeIds: item.id ? [String(item.id)] : []
                });
            }
        });

        // STEP 2: Distribute Payments (Upgraded with previewStudentBalance engine)
        chronologicalLedger.forEach(item => {
            if (item.status === 'VOID' || item.status === 'VOIDED') return;
            if (['payment', 'waiver', 'discount', 'overpayment', 'credit'].includes(item.type)) {
                let safeDesc = item.description || item.desc || item.notes || item.item || item.category || 'General Transaction';

                const receiptNo = String(item.receipt_no || item.receiptNo || '');
                const linkedChargeId = String(item.linked_charge_id || '');
                const paymentChargeId = String(item.id || '').startsWith('PAY-')
                    ? String(item.id).replace(/^PAY-/, 'CHG-')
                    : '';
                const receiptChargeIds = [
                    linkedChargeId,
                    paymentChargeId,
                    receiptNo ? `CHG-${receiptNo}` : '',
                    receiptNo.startsWith('EVT-') ? `CHG-EVT-${receiptNo}` : ''
                ].filter(Boolean);
                const receiptTarget = receiptChargeIds.length
                    ? statementLines.find(line => line.chargeIds.some(chargeId => receiptChargeIds.includes(chargeId)))
                    : null;

                const breakdownsToProcess = Array.isArray(item.breakdown) && item.breakdown.length > 0
                    ? item.breakdown
                    : [{ amt: item.amount, desc: safeDesc }];

                const applyStatementPayment = (target, amount, isCreditAllocation = false) => {
                    if (!target) {
                        if (!isCreditAllocation) unallocatedPaymentPool += amount;
                        return;
                    }

                    const available = Math.max(0, target.billed - target.paid);
                    const applied = Math.min(amount, available);
                    target.paid += applied;
                    if (isCreditAllocation) {
                        unallocatedPaymentPool = Math.max(0, unallocatedPaymentPool - applied);
                    } else {
                        unallocatedPaymentPool += amount - applied;
                    }
                };

                const isAdvanceCredit = window.isAdvanceCreditSettlementEntry(item);
                const creditUsed = Math.max(0, parseFloat(item.credit_used) || 0);
                if (isAdvanceCredit) {
                    applyStatementPayment(receiptTarget, parseFloat(item.amount) || 0, true);
                    return;
                }
                if (creditUsed > 0) applyStatementPayment(receiptTarget, creditUsed, true);

                breakdownsToProcess.forEach(b => {
                    let bName = cleanName(b.desc || b.description || '');
                    let bAmt = parseFloat(b.amt) || parseFloat(b.amount) || 0;

                    if (bAmt <= 0) return;

                    let target = receiptTarget;

                    // Receipt-linked POS/event entries must not be matched to a similarly named charge.
                    if (!target) {
                        target = statementLines.find(l => l.cleanName.toLowerCase() === bName.toLowerCase());
                    }

                    // Keep generic descriptions unallocated instead of assigning them to the first uniform/event.
                    if (!target) {
                        const lowerB = bName.toLowerCase();
                        const isGenericBreakdown = !lowerB ||
                            lowerB === 'shop purchase' ||
                            lowerB === 'uniform purchase' ||
                            lowerB === 'covered by advance credit' ||
                            lowerB.includes('account credit') ||
                            lowerB.includes('overpayment');

                        if (!isGenericBreakdown) {
                            target = statementLines.find(l =>
                                l.cleanName.toLowerCase().includes(lowerB) || lowerB.includes(l.cleanName.toLowerCase())
                            );
                        }
                    }

                    applyStatementPayment(target, bAmt, isAdvanceCredit);
                });
            }
        });

        // STEP 3: Apply overpayments/unallocated payments across all debts in priority order
        if (unallocatedPaymentPool > 0) {
            const categoriesToClear = ['Standard', 'Shop', 'Event']; 
            
            for (let cat of categoriesToClear) {
                for (let line of statementLines) {
                    if (line.cat !== cat) continue; 
                    
                    let owe = line.billed - line.paid;
                    
                    if (owe > 0) {
                        if (unallocatedPaymentPool >= owe) {
                            line.paid += owe;
                            unallocatedPaymentPool -= owe;
                        } else {
                            line.paid += unallocatedPaymentPool;
                            unallocatedPaymentPool = 0;
                            break;
                        }
                    }
                }
                if (unallocatedPaymentPool <= 0) break; 
            }

            if (unallocatedPaymentPool > 0) {
                statementLines.push({
                    date: new Date().toISOString().split('T')[0],
                    term: '-',
                    desc: 'Unallocated Account Credit / Overpayment',
                    cleanName: 'Credit',
                    billed: 0,
                    paid: unallocatedPaymentPool,
                    cat: 'Standard'
                });
            }
        }

        // RENDER TAB 1 & 2 
        let hasUnpaid = false;
        let runBalStandard = 0, runBalEvent = 0, runBalShop = 0; 
        let visibleBilledStandard = 0, visiblePaidStandard = 0;
        let visibleBilledEvent = 0, visiblePaidEvent = 0;

        statementLines.forEach(line => {
            let rowOwe = line.billed - line.paid;

            if (line.cat === 'Event') {
                tBilledEvent += line.billed;
                tPaidEvent += line.paid;
            } else if (line.cat === 'Shop') {
                tBilledShop += line.billed;
                tPaidShop += line.paid;
            } else {
                tBilledStandard += line.billed;
                tPaidStandard += line.paid;
            }

            if (rowOwe > 0.01) {
                hasUnpaid = true;
                totalUnpaidTab2 += rowOwe;
            }

            if (line.billed > 0.01) {
                const badgeClass = line.cat === 'Event' ? '#8e44ad' : (line.cat === 'Shop' ? '#d35400' : '#2980b9');
                const voidButtons = line.chargeIds.map(chargeId => {
                    const rawCharge = (s.ledger || []).find(entry => String(entry.id) === String(chargeId));
                    if (!rawCharge || ['VOID', 'VOIDED'].includes(String(rawCharge.status || '').toUpperCase())) return '';
                    return `<button onclick="window.voidLedgerCharge('${s.id}', '${chargeId}', this)" title="Reverse this charge" style="background-color:#e74c3c; color:white; border:none; padding:3px 8px; border-radius:3px; cursor:pointer; font-size:11px; margin:2px;">Reverse</button>`;
                }).join('');
                const balanceColor = rowOwe > 0.01 ? '#c0392b' : '#27ae60';
                htmlCharges += `<tr style="border-bottom:1px solid #dee2e6;">
                    <td style="padding:10px; vertical-align:top;"><strong>${line.desc}</strong></td>
                    <td style="padding:10px; vertical-align:top;"><span style="background:${badgeClass}; color:white; padding:2px 6px; border-radius:3px; font-size:10px;">${line.cat}</span></td>
                    <td style="padding:10px; text-align:right; vertical-align:top;">$${line.billed.toFixed(2)}</td>
                    <td style="padding:10px; text-align:right; color:#27ae60; vertical-align:top;">$${line.paid.toFixed(2)}</td>
                    <td style="padding:10px; text-align:right; font-weight:bold; color:${balanceColor}; vertical-align:top;">$${Math.max(0, rowOwe).toFixed(2)}</td>
                    <td style="padding:10px; text-align:center; vertical-align:top;">${voidButtons || '-'}</td>
                </tr>`;
            }

            if (line.date >= startDate && line.date <= endDate) {
                let termStr = `<span style="background:#e9ecef; color:#495057; font-size:11px; padding:2px 6px; border-radius:4px; font-weight:500;">${line.term}</span>`;
                let billedStr = line.billed > 0 ? `$${line.billed.toFixed(2)}` : '-';
                let paidStr = line.paid > 0 ? `-$${line.paid.toFixed(2)}` : '-';
                
                if (line.cat === 'Standard') {
                    visibleBilledStandard += line.billed;
                    visiblePaidStandard += line.paid;
                    runBalStandard += rowOwe;
                    let balColor = runBalStandard > 0 ? '#c0392b' : '#27ae60';
                    
                    htmlStandard += `<tr style="border-bottom:1px solid #dee2e6;">
                        <td style="padding:10px; vertical-align:top;">${line.date}</td>
                        <td style="padding:10px; vertical-align:top;">${termStr}</td>
                        <td style="padding:10px; vertical-align:top;"><strong>${line.desc}</strong></td>
                        <td style="padding:10px; text-align:right; color:#c0392b; font-weight:bold;">${billedStr}</td>
                        <td style="padding:10px; text-align:right; color:#27ae60; font-weight:bold;">${paidStr}</td>
                        <td style="padding:10px; text-align:right; color:${balColor}; font-weight:bold;">$${runBalStandard.toFixed(2)}</td>
                    </tr>`;
                } else if (line.cat === 'Event') {
                    visibleBilledEvent += line.billed;
                    visiblePaidEvent += line.paid;
                    runBalEvent += rowOwe;
                    let balColor = runBalEvent > 0 ? '#c0392b' : '#27ae60';
                    
                    htmlEvents += `<tr style="border-bottom:1px solid #dee2e6;">
                        <td style="padding:10px; vertical-align:top;">${line.date}</td>
                        <td style="padding:10px; vertical-align:top;">${termStr}</td>
                        <td style="padding:10px; vertical-align:top;"><strong>${line.desc}</strong></td>
                        <td style="padding:10px; text-align:right; color:#c0392b; font-weight:bold;">${billedStr}</td>
                        <td style="padding:10px; text-align:right; color:#27ae60; font-weight:bold;">${paidStr}</td>
                        <td style="padding:10px; text-align:right; color:${balColor}; font-weight:bold;">$${runBalEvent.toFixed(2)}</td>
                    </tr>`;
                } else if (line.cat === 'Shop') {
                    runBalShop += rowOwe;
                    let balColor = runBalShop > 0 ? '#c0392b' : '#27ae60';
                    
                    htmlShop += `<tr style="border-bottom:1px solid #dee2e6;">
                        <td style="padding:10px; vertical-align:top;">${line.date}</td>
                        <td style="padding:10px; vertical-align:top;"><strong>${line.desc}</strong></td>
                        <td style="padding:10px; text-align:right; color:#c0392b; font-weight:bold;">${billedStr}</td>
                        <td style="padding:10px; text-align:right; color:#27ae60; font-weight:bold;">${paidStr}</td>
                        <td style="padding:10px; text-align:right; color:${balColor}; font-weight:bold;">$${runBalShop.toFixed(2)}</td>
                    </tr>`;
                }
            }
        });

        if (!hasUnpaid) {
            htmlCharges += `<tr><td colspan="6" style="text-align:center; padding:15px; color:#27ae60; font-weight:bold;">Account cleared. Active charges remain listed above and can be reversed by an authorized administrator.</td></tr>`;
        }
    }

    const overallStandardBal = tBilledStandard - tPaidStandard;
    const overallEventBal = tBilledEvent - tPaidEvent;
    const visiblePaidTotal = tPaidStandard + tPaidEvent + tPaidShop; 
    const overallShopBal = tBilledShop - tPaidShop;

    htmlShop += `</tbody>
        <tfoot style="background:#fef9e7; border-top: 2px solid #d35400; font-weight:bold;">
            <tr>
                <td colspan="2" style="padding:10px; text-align:right; color:#d35400;">SHOP TOTALS:</td>
                <td style="padding:10px; text-align:right; color:#c0392b;">$${tBilledShop.toFixed(2)}</td>
                <td style="padding:10px; text-align:right; color:#27ae60;">-$${tPaidShop.toFixed(2)}</td>
                <td style="padding:10px; text-align:right; color:${overallShopBal > 0 ? '#c0392b' : '#27ae60'};">$${overallShopBal.toFixed(2)}</td>
            </tr>
        </tfoot></table>`;

    htmlStandard += `</tbody>
        <tfoot style="background:#ecf0f1; border-top: 2px solid #2c3e50; font-weight:bold;">
            <tr>
                <td colspan="3" style="padding:10px; text-align:right; color:#2c3e50;">STANDARD TOTALS:</td>
                <td style="padding:10px; text-align:right; color:#c0392b;">$${tBilledStandard.toFixed(2)}</td>
                <td style="padding:10px; text-align:right; color:#27ae60;">-$${tPaidStandard.toFixed(2)}</td>
                <td style="padding:10px; text-align:right; color:${overallStandardBal > 0 ? '#c0392b' : '#27ae60'};">$${overallStandardBal.toFixed(2)}</td>
            </tr>
        </tfoot></table>`;

    htmlEvents += `</tbody>
        <tfoot style="background:#f4ebf7; border-top: 2px solid #8e44ad; font-weight:bold;">
            <tr>
                <td colspan="3" style="padding:10px; text-align:right; color:#8e44ad;">EVENT TOTALS:</td>
                <td style="padding:10px; text-align:right; color:#c0392b;">$${tBilledEvent.toFixed(2)}</td>
                <td style="padding:10px; text-align:right; color:#27ae60;">-$${tPaidEvent.toFixed(2)}</td>
                <td style="padding:10px; text-align:right; color:${overallEventBal > 0 ? '#c0392b' : '#27ae60'};">$${overallEventBal.toFixed(2)}</td>
            </tr>
        </tfoot></table>`;

    htmlCharges += `</tbody>
        <tfoot style="background:#fdf2f2; border-top: 2px solid #e74c3c; font-weight:bold;">
            <tr><td colspan="5" style="padding:10px; text-align:right;">TOTAL COMBINED ARREARS:</td><td style="padding:10px; text-align:right; color:#c0392b;">$${totalUnpaidTab2.toFixed(2)}</td></tr>
        </tfoot></table>`;

    htmlPayments += `</tbody>
         <tfoot style="background:#f4fff8; border-top: 2px solid #27ae60; font-weight:bold;">
            <tr><td colspan="2" style="padding:10px; text-align:right;">TOTAL ALL PAYMENTS:</td><td style="padding:10px; text-align:right; color:#27ae60;">$${visiblePaidTotal.toFixed(2)}</td><td></td></tr>
         </tfoot></table>`;

    if (document.getElementById('ledgerAll')) document.getElementById('ledgerAll').innerHTML = htmlStandard + htmlEvents + htmlShop;
    if (document.getElementById('ledgerCharges')) document.getElementById('ledgerCharges').innerHTML = htmlCharges;
    if (document.getElementById('ledgerPayments')) document.getElementById('ledgerPayments').innerHTML = htmlPayments;

    const totalGlobalBilled = tBilledStandard + tBilledEvent + tBilledShop;
    const totalGlobalPaid = tPaidStandard + tPaidEvent + tPaidShop;
    const finalGlobalOwed = totalGlobalBilled - totalGlobalPaid;
    
    if (document.getElementById('modalTotalBilled')) document.getElementById('modalTotalBilled').innerText = totalGlobalBilled.toFixed(2);
    if (document.getElementById('modalTotalPaid')) document.getElementById('modalTotalPaid').innerText = totalGlobalPaid.toFixed(2);
    
    const balEl = document.getElementById('modalTotalOwed');
    if (balEl) {
        if (finalGlobalOwed < -0.01) {
            balEl.innerText = `ADVANCE CREDIT: $${Math.abs(finalGlobalOwed).toFixed(2)}`;
            balEl.style.color = '#2980b9'; 
            balEl.style.backgroundColor = '#e8f4f8';
            balEl.style.padding = '4px 8px';
            balEl.style.borderRadius = '4px';
        } else if (Math.abs(finalGlobalOwed) <= 0.01) {
            balEl.innerText = `CLEARED: $0.00`;
            balEl.style.color = '#27ae60'; 
            balEl.style.backgroundColor = 'transparent';
        } else {
            balEl.innerText = `TOTAL OWED: $${finalGlobalOwed.toFixed(2)}`;
            balEl.style.color = '#e74c3c'; 
            balEl.style.backgroundColor = 'transparent';
        }
    }

    const modal = document.getElementById('ledgerModal') || document.getElementById('studentLedgerModal');
    if (modal) modal.style.display = 'flex';
};

window.reprintReceipt = async function(receiptNo, studentId) {
    if (!navigator.onLine || !window.supabaseClient) {
        return alert("Connect to the cloud before reprinting a saved receipt so its figures can be verified.");
    }

    const student = window.students.find(s => String(s.id) === String(studentId));
    if (!student || !student.ledger) return alert("Student data could not be located.");

    const { data: latestLedger, error: ledgerError } = await window.supabaseClient
        .from('student_ledger')
        .select('*')
        .eq('student_id', studentId);
    if (ledgerError) return alert(`Could not refresh the student ledger for this receipt: ${ledgerError.message}`);
    student.ledger = latestLedger || [];
    const latestBalance = window.calculateStudentBalance(student);
    student.balanceOwing = latestBalance;
    student.balance_owing = latestBalance;
    
    // 1. FILTER to get ALL ledger entries tied to this exact receipt number
    const receiptKey = String(receiptNo || '').toUpperCase();
    const receiptEntries = student.ledger.filter(l =>
        String(l.receiptNo || l.receipt_no || '').toUpperCase() === receiptKey &&
        ['payment', 'waiver', 'discount', 'overpayment'].includes(String(l.type || '').toLowerCase()) &&
        !['VOID', 'VOIDED', 'REVERSAL'].includes(String(l.status || '').toUpperCase())
    );
    
    if (!receiptEntries || receiptEntries.length === 0) return alert("Receipt transaction not found in this ledger!");

    const { data: paymentRows, error: paymentError } = await window.supabaseClient
        .from('payments')
        .select('*')
        .eq('receipt_no', receiptNo)
        .limit(1);
    if (paymentError) console.warn(`Could not load saved payment details for receipt ${receiptNo}:`, paymentError);

    // 2. AGGREGATE the split rows (Tuition + Overpayment + Discount) back into one Master Total
    let amountUsd = 0;
    let amountZig = 0;
    let discountUsd = 0;
    let waiverUsd = 0;
    let combinedBreakdown = [];
    let methods = new Set();
    let dateStr = receiptEntries[0].date || new Date().toISOString().split('T')[0];
    
    receiptEntries.forEach(entry => {
        const entryAmount = parseFloat(entry.amount || 0);
        const entryType = String(entry.type || '').toLowerCase();
        if (entryType === 'discount') {
            discountUsd += Math.abs(entryAmount);
        } else if (entryType === 'waiver') {
            waiverUsd += Math.abs(entryAmount);
        } else {
            amountUsd += entryAmount;
            amountZig += parseFloat(entry.zig || 0);
        }
        if (entry.method && !entry.method.includes('Discount')) methods.add(entry.method);
        
        // Merge the breakdowns so the receipt shows every allocated item
        if (entry.breakdown && Array.isArray(entry.breakdown) && entry.breakdown.length > 0) {
            combinedBreakdown = combinedBreakdown.concat(entry.breakdown);
        } else if (entryType !== 'discount') {
            combinedBreakdown.push({ 
                desc: entry.description || entry.desc || 'General Payment', 
                amt: entryAmount 
            });
        }
    });

    const method = Array.from(methods).join(', ') || "Cash";

    // 3. RECONSTRUCT a single combined payment object for the print generators
    const payment = {
        receipt_no: receiptNo,
        receiptNo: receiptNo,
        date: dateStr,
        amount: amountUsd,
        zig: amountZig,
        method: method,
        breakdown: combinedBreakdown,
        discountAmount: discountUsd,
        waiverAmount: waiverUsd,
        processed_by: await window.getArchivedReceiptProcessorName(
            receiptNo,
            ...receiptEntries,
            paymentRows && paymentRows[0]
        ),
        type: 'payment'
    };

    // Calculate overall balance (what is NOT paid)
    const currentBalance = typeof window.calculateStudentBalance === 'function' 
        ? window.calculateStudentBalance(student) 
        : (parseFloat(student.balanceOwing) || 0);
    const getLedgerTimestamp = entry => {
        const timestampValue = entry.created_at || entry.timestamp ||
            (/\dT\d/.test(String(entry.date || '')) ? entry.date : '');
        return Date.parse(timestampValue || '');
    };
    const receiptTimestamp = Math.max(...receiptEntries.map(getLedgerTimestamp).filter(Number.isFinite));
    const receiptDateKey = String(dateStr).slice(0, 10);
    let historicalBalance = null;

    if (Number.isFinite(receiptTimestamp)) {
        let reconstructedBalance = 0;
        let hasReliableHistory = true;
        const applyLedgerEntry = entry => {
            const amount = parseFloat(entry.amount || 0) || 0;
            if (entry.type === 'charge' || entry.type === 'fee') reconstructedBalance += amount;
            else if (['payment', 'discount', 'waiver', 'credit', 'overpayment'].includes(entry.type)) reconstructedBalance -= amount;
        };

        student.ledger.forEach(entry => {
            if (['VOID', 'VOIDED', 'REVERSAL'].includes(String(entry.status || '').toUpperCase())) return;

            const entryTime = getLedgerTimestamp(entry);
            const isReceiptEntry = receiptEntries.includes(entry);
            if (Number.isFinite(entryTime)) {
                if (entryTime <= receiptTimestamp) applyLedgerEntry(entry);
                return;
            }

            const entryDateKey = String(entry.date || '').slice(0, 10);
            if (isReceiptEntry || entryDateKey < receiptDateKey) {
                applyLedgerEntry(entry);
            } else if (entryDateKey === receiptDateKey && !isReceiptEntry) {
                hasReliableHistory = false;
            }
        });

        if (hasReliableHistory) historicalBalance = parseFloat(reconstructedBalance.toFixed(2));
    }
    
    // ========================================================
    // 4. GENERATE THE ACTION MENU OVERLAY
    // ========================================================
    const overlay = document.createElement('div');
    overlay.style.cssText = 'position:fixed; top:0; left:0; width:100%; height:100%; background:rgba(0,0,0,0.6); z-index:999999; display:flex; align-items:center; justify-content:center; backdrop-filter: blur(3px);';
    
    const dialog = document.createElement('div');
    dialog.style.cssText = 'background:#fff; padding:30px; border-radius:12px; width:90%; max-width:400px; text-align:center; box-shadow:0 10px 30px rgba(0,0,0,0.3); font-family: system-ui, -apple-system, sans-serif;';
    
    dialog.innerHTML = `
        <h3 style="margin:0 0 10px 0; color:#2c3e50;">Receipt Options</h3>
        <p style="font-size:13px; color:#7f8c8d; margin-bottom:20px; line-height:1.5;">
            Receipt <strong>${receiptNo}</strong> for <strong>${student.name}</strong><br>
            Cash Received: <strong style="color:#27ae60;">$${amountUsd.toFixed(2)}</strong>
            ${discountUsd > 0 ? `<br>Discount Applied: <strong>-$${discountUsd.toFixed(2)}</strong>` : ''}
            ${waiverUsd > 0 ? `<br>Waiver Applied: <strong>-$${waiverUsd.toFixed(2)}</strong>` : ''}
            <br>Total Value Cleared: <strong>$${(amountUsd + discountUsd + waiverUsd).toFixed(2)}</strong>
            ${historicalBalance !== null ? `<br>Balance after receipt: <strong>$${historicalBalance.toFixed(2)}</strong>` : ''}
            <br>Current balance today: <strong>$${currentBalance.toFixed(2)}</strong>
            ${amountZig > 0 ? ` <em>(+ ZiG ${amountZig.toFixed(2)})</em>` : ''}
        </p>
        <div style="display:flex; flex-direction:column; gap:12px;">
            <button id="btnReceiptPrint" style="padding:14px; border:none; border-radius:8px; background:#2980b9; color:#fff; font-size:14px; font-weight:bold; cursor:pointer; display:flex; justify-content:center; align-items:center; gap:8px; transition: background 0.2s;">
                🖨️ Print High-Class Receipt
            </button>
            <button id="btnReceiptWA" style="padding:14px; border:none; border-radius:8px; background:#27ae60; color:#fff; font-size:14px; font-weight:bold; cursor:pointer; display:flex; justify-content:center; align-items:center; gap:8px; transition: background 0.2s;">
                💬 Send via WhatsApp
            </button>
            <button id="btnReceiptCancel" style="padding:12px; border:1px solid #bdc3c7; border-radius:8px; background:#f8f9fa; color:#34495e; font-size:14px; cursor:pointer; font-weight:bold;">
                ❌ Do Nothing / Close
            </button>
        </div>
    `;
    
    overlay.appendChild(dialog);
    document.body.appendChild(overlay);

    // ========================================================
    // 5. BUTTON EVENT LISTENERS
    // ========================================================
    document.getElementById('btnReceiptCancel').onclick = () => document.body.removeChild(overlay);
    
    document.getElementById('btnReceiptPrint').onclick = () => {
        document.body.removeChild(overlay);
        generateHighClassPrint(student, payment, amountUsd, amountZig, method, dateStr, currentBalance, receiptNo, historicalBalance);
    };
    
    document.getElementById('btnReceiptWA').onclick = () => {
        document.body.removeChild(overlay);
        generateWhatsAppReceipt(student, payment, amountUsd, amountZig, method, dateStr, currentBalance, receiptNo, historicalBalance);
    };
};

// ========================================================
// 3. HIGH-CLASS PHYSICAL PRINT GENERATOR
// ========================================================
function generateHighClassPrint(student, payment, amountUsd, amountZig, method, dateStr, currentBalance, receiptNo, historicalBalance = null) {
    
    // Build the itemized breakdown logic
    let breakdownHtml = '';
    if (payment.breakdown && Array.isArray(payment.breakdown) && payment.breakdown.length > 0) {
        payment.breakdown.forEach(b => {
            breakdownHtml += `
                <tr>
                    <td style="padding: 10px 0; border-bottom: 1px dashed #eee;">${b.desc || b.description}</td>
                    <td style="padding: 10px 0; border-bottom: 1px dashed #eee; text-align: right; font-weight:bold;">$${parseFloat(b.amt).toFixed(2)}</td>
                </tr>`;
        });
    } else {
        breakdownHtml = `
            <tr>
                <td style="padding: 10px 0; border-bottom: 1px dashed #eee;">${payment.description || payment.desc || 'General Payment'}</td>
                <td style="padding: 10px 0; border-bottom: 1px dashed #eee; text-align: right; font-weight:bold;">$${amountUsd.toFixed(2)}</td>
            </tr>`;
    }

    const discountAmount = parseFloat(payment.discountAmount) || 0;
    const waiverAmount = parseFloat(payment.waiverAmount) || 0;
    if (discountAmount > 0) {
        breakdownHtml += `
            <tr>
                <td style="padding: 10px 0; border-bottom: 1px dashed #eee;">Discount Applied</td>
                <td style="padding: 10px 0; border-bottom: 1px dashed #eee; text-align: right; font-weight:bold;">-$${discountAmount.toFixed(2)}</td>
            </tr>`;
    }
    if (waiverAmount > 0) {
        breakdownHtml += `
            <tr>
                <td style="padding: 10px 0; border-bottom: 1px dashed #eee;">Waiver Applied</td>
                <td style="padding: 10px 0; border-bottom: 1px dashed #eee; text-align: right; font-weight:bold;">-$${waiverAmount.toFixed(2)}</td>
            </tr>`;
    }

    const zigLine = amountZig > 0 ? `<div style="display:flex; justify-content:space-between; margin-bottom:8px; font-size:14px;"><strong>Paid in ZiG:</strong> <span style="font-weight:bold; color:#d35400;">ZiG ${amountZig.toFixed(2)}</span></div>` : '';
    const usdLine = `<div style="display:flex; justify-content:space-between; margin-bottom:8px; font-size:14px;"><strong>Cash Received in USD:</strong> <span style="font-weight:bold; color:#27ae60;">$${amountUsd.toFixed(2)}</span></div>`;
    const discountLine = discountAmount > 0
        ? `<div style="display:flex; justify-content:space-between; margin-bottom:8px; font-size:14px;"><strong>Discount Applied:</strong> <span>$${discountAmount.toFixed(2)}</span></div>`
        : '';
    const waiverLine = waiverAmount > 0
        ? `<div style="display:flex; justify-content:space-between; margin-bottom:8px; font-size:14px;"><strong>Waiver Applied:</strong> <span>$${waiverAmount.toFixed(2)}</span></div>`
        : '';
    const totalClearedLine = `<div style="display:flex; justify-content:space-between; margin-bottom:8px; font-size:14px;"><strong>Total Value Cleared:</strong> <span>$${(amountUsd + discountAmount + waiverAmount).toFixed(2)}</span></div>`;

    const html = `
    <html>
    <head>
        <title>Receipt - ${receiptNo}</title>
        <style>
            body { font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif; margin: 0; padding: 20px; color: #2c3e50; }
            .receipt-container { max-width: 400px; margin: 0 auto; border: 1px solid #ecf0f1; padding: 30px; border-radius: 12px; box-shadow: 0 4px 15px rgba(0,0,0,0.05); }
            .header { text-align: center; margin-bottom: 25px; border-bottom: 2px solid #2c3e50; padding-bottom: 15px; }
            .header h1 { margin: 0; font-size: 22px; color: #2c3e50; text-transform: uppercase; letter-spacing: 1.5px; }
            .header h2 { margin: 5px 0 0; font-size: 15px; color: #7f8c8d; font-weight: normal; }
            .info-row { display: flex; justify-content: space-between; font-size: 13px; margin-bottom: 8px; }
            .info-row span { font-weight: bold; }
            .section-title { font-size: 11px; color: #7f8c8d; text-transform: uppercase; letter-spacing: 1px; margin: 25px 0 10px; border-bottom: 1px solid #bdc3c7; padding-bottom: 4px; }
            table { width: 100%; border-collapse: collapse; font-size: 13px; margin-bottom: 20px; }
            .totals { margin-top: 15px; background: #f8f9fa; padding: 15px; border-radius: 8px; border: 1px solid #eee; }
            .arrears { margin-top: 20px; text-align: center; padding: 12px; background: ${currentBalance > 0.01 ? '#fdedf0' : '#e8f8f5'}; color: ${currentBalance > 0.01 ? '#c0392b' : '#27ae60'}; border-radius: 8px; font-size: 14px; border: 1px solid ${currentBalance > 0.01 ? '#e74c3c' : '#27ae60'}; }
            .arrears strong { display: block; font-size: 18px; margin-top: 5px; }
            .footer { text-align: center; margin-top: 30px; font-size: 11px; color: #95a5a6; line-height: 1.5; }
            @media print {
                @page { size: 80mm auto; margin: 0; }
                * { color: #000 !important; background-color: #fff !important; border-color: #000 !important; text-shadow: none !important; box-shadow: none !important; -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; }
                body { width: 80mm; max-width: 80mm; margin: 0; padding: 4mm; color: #000 !important; }
                .receipt-container { width: 100%; max-width: 100%; margin: 0; padding: 2mm; border: 0; border-radius: 0; }
            }
        </style>
    </head>
    <body>
        <div class="receipt-container">
            <div class="header">
                <h1>OFFICIAL RECEIPT</h1>
                <h2>Gudlance Preparatory School</h2>
            </div>
            
            <div class="info-row"><strong>Receipt No:</strong> <span>${receiptNo}</span></div>
            <div class="info-row"><strong>Date:</strong> <span>${dateStr}</span></div>
            <div class="info-row"><strong>Student:</strong> <span>${student.name}</span></div>
            <div class="info-row"><strong>Class:</strong> <span>${student.grade || 'N/A'}</span></div>
            <div class="info-row"><strong>Method:</strong> <span style="text-transform:uppercase;">${method}</span></div>
            <div class="info-row"><strong>Processed By:</strong> <span>${payment.processed_by || 'Not recorded'}</span></div>

            <div class="section-title">Itemized Breakdown</div>
            <table>
                <tbody>
                    ${breakdownHtml}
                </tbody>
            </table>

            <div class="totals">
                ${usdLine}
                ${zigLine}
                ${discountLine}
                ${waiverLine}
                ${totalClearedLine}
            </div>

            <div class="arrears">
                ${historicalBalance !== null ? `Balance After This Receipt:<strong>$${historicalBalance.toFixed(2)}</strong>` : ''}
                Current Account Balance Today:
                <strong>$${parseFloat(currentBalance).toFixed(2)}</strong>
                ${historicalBalance !== null && historicalBalance <= 0.01 ? '<span style="font-size:12px; color:#27ae60;"><br>Account Fully Cleared at Transaction</span>' : ''}
            </div>

            <div class="footer">
                Thank you for your payment!<br>
                <em>System Generated on ${new Date().toLocaleString()}</em>
            </div>
        </div>
        <script>
            // Auto-trigger print dialog, then close the hidden window when done
            window.onload = function() { 
                window.print(); 
                setTimeout(() => window.close(), 500); 
            }
        </script>
    </body>
    </html>
    `;

    const printWin = window.open('', '_blank', 'width=500,height=800');
    printWin.document.write(html);
    printWin.document.close();
}

// ========================================================
// 4. WHATSAPP GENERATOR
// ========================================================
function generateWhatsAppReceipt(student, payment, amountUsd, amountZig, method, dateStr, currentBalance, receiptNo, historicalBalance = null) {
    let text = `🏫 *GUDLANCE PREPARATORY SCHOOL*\n🧾 *OFFICIAL RECEIPT*\n------------------------\n`;
    text += `👤 *Student:* ${student.name}\n`;
    text += `🔢 *Receipt #:* ${receiptNo}\n`;
    text += `📅 *Date:* ${dateStr}\n`;
    text += `------------------------\n`;
    text += `✅ *CASH RECEIVED:*\n`;
    text += `💵 USD: *$${amountUsd.toFixed(2)}*\n`;
    if (amountZig > 0) text += `🇿🇼 ZiG: *${amountZig.toFixed(2)}*\n`;
    const discountAmount = parseFloat(payment.discountAmount) || 0;
    const waiverAmount = parseFloat(payment.waiverAmount) || 0;
    if (discountAmount > 0) text += `🎟️ Discount Applied: *$${discountAmount.toFixed(2)}*\n`;
    if (waiverAmount > 0) text += `🎟️ Waiver Applied: *$${waiverAmount.toFixed(2)}*\n`;
    text += `💰 *Total Value Cleared: $${(amountUsd + discountAmount + waiverAmount).toFixed(2)}*\n`;
    text += `💳 Method: ${method}\n\n`;
    text += `👤 Processed By: ${payment.processed_by || 'Not recorded'}\n\n`;
    
    text += `📝 *PAYMENT BREAKDOWN:*\n`;
    if (payment.breakdown && Array.isArray(payment.breakdown) && payment.breakdown.length > 0) {
        payment.breakdown.forEach(b => {
            text += `▪️ ${b.desc || b.description}: $${parseFloat(b.amt).toFixed(2)}\n`;
        });
    } else {
        text += `▪️ ${payment.description || payment.desc || 'General Payment'}: $${amountUsd.toFixed(2)}\n`;
    }
    
    text += `\n------------------------\n`;
    if (historicalBalance !== null) {
        text += `📅 *BALANCE AFTER THIS RECEIPT:*\n`;
        text += `*$${historicalBalance.toFixed(2)}*\n`;
    }
    text += `⚠️ *CURRENT ACCOUNT BALANCE TODAY:*\n`;
    text += `*$${parseFloat(currentBalance).toFixed(2)}*\n`;
    if (currentBalance <= 0.01) {
        text += `✅ _Account Fully Cleared_\n`;
    }
    text += `------------------------\n`;
    text += `Thank you for your payment!`;

    const encodedText = encodeURIComponent(text);
    
    // Find parent phone number if available, otherwise open generic WhatsApp window
    let phone = student.phone || student.parent_phone || student.cell || '';
    phone = phone.replace(/\D/g, ''); // strip non-numeric spaces
    
    // Auto-format Zimbabwe numbers
    if (phone.startsWith('0')) phone = '263' + phone.substring(1); 
    
    let url = `https://wa.me/${phone}?text=${encodedText}`;
    
    // If no valid phone number is found, it will open WhatsApp Web/App and ask the Admin to select a contact
    if (!phone || phone.length < 8) {
        url = `https://wa.me/?text=${encodedText}`; 
    }

    window.open(url, '_blank');
}

// 3. WhatsApp Summary Engine (Clean version)
// ==========================================
// UNIFIED ROBUST WHATSAPP STATEMENT SENDER
// ==========================================
window.sendStudentStatementWA = function(customPayment = null, customBreakdown = null) {
    const id = document.getElementById('currentLedgerStudentId')?.value;
    const student = window.students.find(st => String(st.id) === String(id));
    if (!student) return alert("Student not found! Please open a student ledger first.");

    const rawPhone = student.phone || student.cell || student.guardianPhone || "";
    if (!rawPhone) return alert("No valid phone number or contact found for this student.");

    let phone = rawPhone.replace(/\D/g, '');
    if (phone.startsWith('0')) phone = '263' + phone.substring(1);

    const schoolName = window.settings?.schoolName || "HAVEN ONLINE";
    const term = typeof window.getCurrentTerm === 'function' ? window.getCurrentTerm() : 'Current Term';
    const statementChoice = window.prompt(
        "WhatsApp statement format:\n\n1 = Short monthly/date-range summary (recommended)\n2 = Full transaction history\n\nCancel to stop.",
        "1"
    );
    if (statementChoice === null) return;

    const normalizedChoice = statementChoice.trim().toLowerCase();
    if (!['1', '2', 'short', 'full'].includes(normalizedChoice)) {
        return window.alert("Please enter 1 for the short statement or 2 for the full statement.");
    }
    const isDetailed = normalizedChoice === '2' || normalizedChoice === 'full';

    const dateValue = date => [date.getFullYear(), String(date.getMonth() + 1).padStart(2, '0'), String(date.getDate()).padStart(2, '0')].join('-');
    const today = new Date();
    const monthStart = dateValue(new Date(today.getFullYear(), today.getMonth(), 1));
    const monthEnd = dateValue(new Date(today.getFullYear(), today.getMonth() + 1, 0));
    const selectedStart = document.getElementById('ledgerStartDate')?.value || '';
    const selectedEnd = document.getElementById('ledgerEndDate')?.value || '';
    const periodStart = selectedStart || monthStart;
    const periodEnd = selectedEnd || monthEnd;
    if (periodStart > periodEnd) return window.alert("The statement start date must be on or before the end date.");

    const periodStartDate = new Date(`${periodStart}T00:00:00`);
    const periodEndDate = new Date(`${periodEnd}T00:00:00`);
    const periodLabel = periodStart.slice(0, 7) === periodEnd.slice(0, 7)
        ? periodStartDate.toLocaleDateString('en', { month: 'long', year: 'numeric' })
        : `${periodStart} to ${periodEnd}`;

    // --- MATH ENGINE ---
    let statementLines = [];
    let unallocatedPaymentPool = 0; 
    const sortedLedger = student.ledger ? [...student.ledger].sort((a, b) => new Date(a.date) - new Date(b.date)) : [];

    const getLedgerImpact = entry => {
        if (entry.status === 'VOID' || entry.status === 'VOIDED') return { billed: 0, paid: 0, overpayment: 0 };
        if (window.isCreditAllocationAdjustmentCharge?.(entry) || window.isAdvanceCreditSettlementEntry?.(entry)) {
            return { billed: 0, paid: 0, overpayment: 0 };
        }

        const amount = parseFloat(entry.amount || entry.amt) || 0;
        if (entry.type === 'charge' || entry.type === 'fee') return { billed: amount, paid: 0, overpayment: 0 };
        if (['payment', 'waiver', 'discount', 'credit', 'overpayment'].includes(entry.type)) {
            return { billed: 0, paid: amount, overpayment: entry.type === 'overpayment' ? amount : 0 };
        }
        return { billed: 0, paid: 0, overpayment: 0 };
    };

    let openingBalance = 0;
    let periodBilled = 0;
    let periodPaid = 0;
    let periodOverpayment = 0;
    sortedLedger.forEach(entry => {
        const entryDate = String(entry.date || '').slice(0, 10);
        const impact = getLedgerImpact(entry);
        if (entryDate && entryDate < periodStart) {
            openingBalance += impact.billed - impact.paid;
        } else if (entryDate && entryDate >= periodStart && entryDate <= periodEnd) {
            periodBilled += impact.billed;
            periodPaid += impact.paid;
            periodOverpayment += impact.overpayment;
        }
    });
    const periodClosingBalance = openingBalance + periodBilled - periodPaid;
    
    const cleanName = (name) => name
        .replace('Enrollment: ', '').replace('Event/Trip: ', '')
        .replace('Payment for ', '').replace('WAIVED: ', '')
        .replace(' (Admin Selected)', '').replace(' (System Auto)', '').trim();
    // STEP 1: Build Rows from Charges
    sortedLedger.forEach(item => {
        if (item.status === 'VOID' || item.status === 'VOIDED') return;
        if (item.type !== 'charge') return;

        let amt = parseFloat(item.amount || item.amt) || 0;
        let safeDesc = item.description || item.desc || item.notes || item.item || item.category || 'General Transaction';
        let rNo = item.receiptNo || item.receipt_no || '';
        
        const isEvent = safeDesc.toLowerCase().includes('event') || safeDesc.toLowerCase().includes('trip') || rNo.startsWith('EVT') || (item.id && String(item.id).includes('EVT'));
        const isShop = safeDesc.toLowerCase().includes('shop') || safeDesc.toLowerCase().includes('uniform') || rNo.startsWith('RCPT') || (item.id && String(item.id).includes('RCPT'));
        const category = isShop ? 'Shop' : (isEvent ? 'Event' : 'Standard');
        
        let matchedName = cleanName(safeDesc);
        let existing = statementLines.find(l => l.cleanName === matchedName && l.cat === category);
        
        if (existing) existing.billed += amt;
        else statementLines.push({ date: item.date || 'N/A', term: item.term || '-', desc: safeDesc, cleanName: matchedName, billed: amt, paid: 0, cat: category });
    });

    // STEP 2: Distribute Payments
    sortedLedger.forEach(item => {
        if (item.status === 'VOID' || item.status === 'VOIDED') return;
        if (['payment', 'waiver', 'discount', 'overpayment', 'credit'].includes(item.type)) {
            let safeDesc = item.description || item.desc || item.notes || item.item || item.category || 'General Transaction';
            
            if (item.breakdown && item.breakdown.length > 0) {
                item.breakdown.forEach(b => {
                    let bName = cleanName(b.desc || b.description || '');
                    let bAmt = parseFloat(b.amt || b.amount) || 0;
                    let target = statementLines.find(l => l.cleanName.toLowerCase().includes(bName.toLowerCase()) || bName.toLowerCase().includes(l.cleanName.toLowerCase()));
                    if (target) target.paid += bAmt;
                    else unallocatedPaymentPool += bAmt;
                });
            } else {
                let pAmt = parseFloat(item.amount || item.amt) || 0;
                let pName = cleanName(safeDesc);
                let target = statementLines.find(l => l.cleanName.toLowerCase().includes(pName.toLowerCase()) || pName.toLowerCase().includes(l.cleanName.toLowerCase()));
                if (target) target.paid += pAmt;
                else unallocatedPaymentPool += pAmt;
            }
        }
    });

    // STEP 3: Apply Unallocated Payments (Waterfall)
    let finalOverpaymentBalance = 0;
    if (unallocatedPaymentPool > 0) {
        const categoriesToClear = ['Standard', 'Shop', 'Event']; 
        for (let cat of categoriesToClear) {
            for (let line of statementLines) {
                if (line.cat !== cat) continue; 
                let owe = line.billed - line.paid;
                if (owe > 0.01) {
                    if (unallocatedPaymentPool >= owe) { line.paid += owe; unallocatedPaymentPool -= owe; } 
                    else { line.paid += unallocatedPaymentPool; unallocatedPaymentPool = 0; break; }
                }
            }
            if (unallocatedPaymentPool <= 0) break; 
        }
        if (unallocatedPaymentPool > 0) {
            finalOverpaymentBalance = unallocatedPaymentPool;
            statementLines.push({ date: new Date().toISOString().split('T')[0], term: '-', desc: 'Unallocated Account Credit (Overpayment)', cleanName: 'Credit', billed: 0, paid: unallocatedPaymentPool, cat: 'Standard' });
        }
    }

    // --- WHATSAPP MESSAGE GENERATION ---
    let totalGlobalBilled = 0, totalGlobalPaid = 0;
    
    // 1. Calculate Totals (Always needed)
    statementLines.forEach(line => {
        totalGlobalBilled += line.billed;
        totalGlobalPaid += line.paid;
    });
    let balanceDue = totalGlobalBilled - totalGlobalPaid;

    // 2. Assemble Header & Summary
    let message = `*${schoolName.toUpperCase()} - ACCOUNT STATEMENT*\n`;
    message += `*Student:* ${student.name || student.student_name || 'Student'}\n`;
    message += `*Student ID:* ${student.id || student.student_id || id}\n`;
    message += `*Class:* ${student.grade || student.class || student.level || 'N/A'}\n`;
    if (isDetailed) message += `*Term:* ${term}\n`;
    else message += `*Period:* ${periodLabel}\n`;

    if (isDetailed && customPayment && customBreakdown) {
        message += `🟢 *RECENT TRANSACTION:* \n`;
        message += `Amount Paid: *$${parseFloat(customPayment).toFixed(2)}*\n`;
        message += `*Allocation Breakdown:*\n`;
        customBreakdown.forEach(b => { message += `   - ${b}\n`; });
        message += `\n───────────────────────\n`;
    }

    if (isDetailed) {
        message += `📋 *FINANCIAL SUMMARY:*\n`;
        message += `• Total Billed: *$${totalGlobalBilled.toFixed(2)}*\n`;
        message += `• Total Paid: *$${totalGlobalPaid.toFixed(2)}*\n`;
        message += `• *BALANCE DUE:* *_$${balanceDue > 0 ? balanceDue.toFixed(2) : '0.00'}_*\n`;
        if (finalOverpaymentBalance > 0.01) message += `• 💰 *AVAILABLE CREDIT: +$${finalOverpaymentBalance.toFixed(2)}*\n`;
    }

    // 3. Assemble Conditional Details (Short vs Long)
    if (isDetailed) {
        // --- LONG VERSION (Summaries + Ledger) ---
        const buildCategoryText = (categoryName, title) => {
            let catText = "";
            statementLines.filter(l => l.cat === categoryName).forEach(line => {
                let rowOwe = line.billed - line.paid;
                let oweStr = rowOwe > 0.01 ? `*_Bal: $${rowOwe.toFixed(2)}_*` : `~Bal: $0.00~`;
                catText += `▪️ *${line.desc}*\n   Billed: $${line.billed.toFixed(2)} | Paid: $${line.paid.toFixed(2)} | ${oweStr}\n`;
            });
            if (catText !== "") return `\n📘 *${title.toUpperCase()} SUMMARY*\n${catText}`;
            return "";
        };

        let itemizedLedgerStr = buildCategoryText('Standard', 'Standard Tuition & Fees');
        itemizedLedgerStr += buildCategoryText('Event', 'Events & Trips');
        itemizedLedgerStr += buildCategoryText('Shop', 'Uniforms & Shop Matters');

        let historyStr = "";
        sortedLedger.forEach(entry => {
            const isVoid = entry.status === 'VOID' || entry.status === 'VOIDED';
            const isOverpayment = entry.type === 'overpayment';

            let billedAmt = entry.type === 'charge' ? `$${parseFloat(entry.amount || entry.amt || 0).toFixed(2)}` : '-';
            let paidAmt = (['payment', 'waiver', 'credit', 'overpayment', 'discount'].includes(entry.type)) ? `$${parseFloat(entry.amount || entry.amt || 0).toFixed(2)}` : '-';

            if (isVoid) {
                if (entry.type === 'charge') billedAmt = `~${billedAmt}~ (VOID)`;
                else paidAmt = `~${paidAmt}~ (VOID)`;
            }

            let breakdownStr = '';
            if (entry.type === 'payment' && entry.breakdown && entry.breakdown.length > 0) {
                entry.breakdown.forEach(b => {
                    const safeBDesc = b.description || b.desc || b.notes || b.item || 'Unallocated';
                    let cleanDesc = safeBDesc.replace(' (System Auto)', '').replace(' (Admin Selected)', '');
                    breakdownStr += `\n   └ ${cleanDesc}: *$${parseFloat(b.amt || b.amount || 0).toFixed(2)}*`;
                });
            }

            let refStr = (entry.receiptNo || entry.receipt_no) ? ` [Ref: ${entry.receiptNo || entry.receipt_no}]` : '';
            let safeDescription = entry.description || entry.desc || entry.notes || entry.item || entry.category || 'Transaction';
            if (entry.type === 'payment' && safeDescription.includes('&')) safeDescription = 'Combined Payment Breakdown:';

            historyStr += `🗓️ *${entry.date || '-'}*${isOverpayment ? ' 💰 *OVERPAYMENT*' : ''}\n`;
            historyStr += `📝 ${safeDescription}${refStr}${breakdownStr}\n`;
            historyStr += `🔴 Billed: ${billedAmt} | 🟢 Paid: ${paidAmt}\n\n`;
        });

        message += `\n═══════════════════════\n`;
        message += `📊 *CATEGORY SUMMARIES:*`;
        message += itemizedLedgerStr ? itemizedLedgerStr : `\n_No summary available._\n`;

        message += `\n═══════════════════════\n`;
        message += `📜 *COMPLETE TRANSACTION HISTORY:*\n\n`;
        message += historyStr ? historyStr : `_No financial history found._\n`;

    } else {
        message += `*Balance brought forward:* ${openingBalance < -0.01 ? `-$${Math.abs(openingBalance).toFixed(2)} credit` : `$${Math.max(0, openingBalance).toFixed(2)} owed`}\n`;
        message += `*New charges:* $${periodBilled.toFixed(2)}\n`;
        message += `*Payments/credits:* $${periodPaid.toFixed(2)}\n`;

        if (periodClosingBalance > 0.01) {
            message += `*AMOUNT DUE:* $${periodClosingBalance.toFixed(2)}\n`;
            if (periodOverpayment > 0.01) {
                message += `Your overpayment of $${periodOverpayment.toFixed(2)} this period has been applied to the account balance. Thank you.\n`;
            } else {
                message += `Please arrange payment when convenient. Thank you for supporting ${schoolName}.\n`;
            }
        } else if (periodClosingBalance < -0.01) {
            message += `*ACCOUNT CREDIT:* $${Math.abs(periodClosingBalance).toFixed(2)}\n`;
            if (periodOverpayment > 0.01) {
                message += `Your payment exceeded this period's charges. The overpayment is safely carried forward as credit. Thank you.\n`;
            } else {
                message += `Your previous credit has been carried forward to future fees. Thank you.\n`;
            }
        } else {
            message += `*BALANCE:* $0.00\n`;
            message += `Your account is up to date for this period. Thank you.\n`;
        }
    }

    message += `═══════════════════════\n`;
    message += `_Thank you for partnering with ${schoolName}! Please contact administration for any queries._`;

    const whatsappUrl = `https://wa.me/${phone}?text=${encodeURIComponent(message)}`;
    window.open(whatsappUrl, '_blank');
};

// 4. Professional Print Layout (Restored and linked to the modal ID)
// ==========================================
// UPGRADED FORENSIC STATEMENT PRINTING ENGINE
// ==========================================
window.printStudentStatement = function() {
    const studentId = document.getElementById('currentLedgerStudentId')?.value;
    const student = window.students.find(s => String(s.id) === String(studentId));
    if (!student) return alert("Student not found!");

    if (!student.ledger || student.ledger.length === 0) {
        return alert("No financial history found for this student.");
    }

    const sortedLedger = [...student.ledger].sort((a, b) => new Date(a.date) - new Date(b.date));

    // --- MATH ENGINE ---
    let statementLines = [];
    let unallocatedPaymentPool = 0;
    let unallocatedDiscountPool = 0;
    
    const cleanName = (name) => name
        .replace('Enrollment: ', '').replace('Event/Trip: ', '')
        .replace('Payment for ', '').replace('WAIVED: ', '')
        .replace(' (Admin Selected)', '').replace(' (System Auto)', '').trim();
    const cleanAllocationName = (name) => cleanName(name)
        .replace(/^Discount Applied:\s*/i, '')
        .replace(/^Exemption\s*\/\s*Waiver:\s*/i, '')
        .replace(/^Shop (?:Discount|Waiver):\s*/i, 'Shop Purchase: ')
        .trim();

    // STEP 1: Build Rows from Charges
    sortedLedger.forEach(item => {
        if (item.status === 'VOID' || item.status === 'VOIDED') return;
        if (item.type !== 'charge') return;

        let amt = parseFloat(item.amount || item.amt) || 0;
        let safeDesc = item.description || item.desc || item.notes || item.item || item.category || 'General Transaction';
        let rNo = item.receiptNo || item.receipt_no || '';
        
        const isEvent = safeDesc.toLowerCase().includes('event') || safeDesc.toLowerCase().includes('trip') || rNo.startsWith('EVT') || (item.id && String(item.id).includes('EVT'));
        const isShop = safeDesc.toLowerCase().includes('shop') || safeDesc.toLowerCase().includes('uniform') || rNo.startsWith('RCPT') || (item.id && String(item.id).includes('RCPT'));
        const category = isShop ? 'Shop' : (isEvent ? 'Event' : 'Standard');
        
        let matchedName = cleanName(safeDesc);
        let existing = statementLines.find(l => l.cleanName === matchedName && l.cat === category);
        
        if (existing) {
            existing.billed += amt;
            if (item.id && !existing.chargeIds.includes(String(item.id))) existing.chargeIds.push(String(item.id));
        } else {
            statementLines.push({
                date: item.date || 'N/A', term: item.term || '-', desc: safeDesc,
                cleanName: matchedName, billed: amt, paid: 0, discount: 0, cat: category,
                chargeIds: item.id ? [String(item.id)] : []
            });
        }
    });

    // STEP 2: Distribute Payments
    sortedLedger.forEach(item => {
        if (item.status === 'VOID' || item.status === 'VOIDED') return;
        if (['payment', 'waiver', 'discount', 'overpayment', 'credit'].includes(item.type)) {
            const isDiscount = item.type === 'discount' || item.type === 'waiver';
            let safeDesc = item.description || item.desc || item.notes || item.item || item.category || 'General Transaction';
            const receiptNo = String(item.receipt_no || item.receiptNo || '');
            const paymentChargeId = String(item.id || '').startsWith('PAY-')
                ? String(item.id).replace(/^PAY-/, 'CHG-')
                : '';
            const receiptChargeIds = [
                item.linked_charge_id,
                paymentChargeId,
                receiptNo ? `CHG-${receiptNo}` : '',
                receiptNo.startsWith('EVT-') ? `CHG-EVT-${receiptNo}` : ''
            ].filter(Boolean).map(String);
            const receiptTarget = receiptChargeIds.length
                ? statementLines.find(line => line.chargeIds.some(chargeId => receiptChargeIds.includes(chargeId)))
                : null;
            
            if (item.breakdown && item.breakdown.length > 0) {
                item.breakdown.forEach(b => {
                    let bName = cleanAllocationName(b.desc || b.description || '');
                    let bAmt = parseFloat(b.amt || b.amount) || 0;
                    let target = receiptTarget || statementLines.find(l => l.cleanName.toLowerCase().includes(bName.toLowerCase()) || bName.toLowerCase().includes(l.cleanName.toLowerCase()));
                    if (target) target[isDiscount ? 'discount' : 'paid'] += bAmt;
                    else if (isDiscount) unallocatedDiscountPool += bAmt;
                    else unallocatedPaymentPool += bAmt;
                });
            } else {
                let pAmt = parseFloat(item.amount || item.amt) || 0;
                let pName = cleanAllocationName(safeDesc);
                let target = receiptTarget || statementLines.find(l => l.cleanName.toLowerCase().includes(pName.toLowerCase()) || pName.toLowerCase().includes(l.cleanName.toLowerCase()));
                if (target) target[isDiscount ? 'discount' : 'paid'] += pAmt;
                else if (isDiscount) unallocatedDiscountPool += pAmt;
                else unallocatedPaymentPool += pAmt;
            }
        }
    });

    // STEP 3: Apply Unallocated Payments (Waterfall)
    let finalOverpaymentBalance = 0;
    for (const allocationType of ['paid', 'discount']) {
        let pool = allocationType === 'paid' ? unallocatedPaymentPool : unallocatedDiscountPool;
        if (pool <= 0) continue;
        const categoriesToClear = ['Standard', 'Shop', 'Event'];
        for (let cat of categoriesToClear) {
            for (let line of statementLines) {
                if (line.cat !== cat) continue;
                let owe = line.billed - line.paid - line.discount;
                if (owe > 0.01) {
                    if (pool >= owe) {
                        line[allocationType] += owe;
                        pool -= owe;
                    } else {
                        line[allocationType] += pool;
                        pool = 0;
                        break;
                    }
                }
            }
            if (pool <= 0) break;
        }
        if (allocationType === 'paid' && pool > 0) {
            finalOverpaymentBalance = pool;
            statementLines.push({ date: new Date().toISOString().split('T')[0], term: '-', desc: 'Unallocated Account Credit (Overpayment)', cleanName: 'Credit', billed: 0, paid: pool, discount: 0, cat: 'Standard' });
        }
    }

    // --- HTML GENERATION ---
    let totalGlobalBilled = 0, totalGlobalPaid = 0;
    
    // Summary Category Tables function
    const buildCategoryTable = (categoryName, title, color) => {
        let rowsHtml = '';
        let catBilled = 0, catPaid = 0, catDiscount = 0;
        
        statementLines.filter(l => l.cat === categoryName).forEach(line => {
            let rowOwe = line.billed - line.paid - line.discount;
            catBilled += line.billed;
            catPaid += line.paid;
            catDiscount += line.discount;
            
            rowsHtml += `
                <tr style="border-bottom: 1px solid #bdc3c7;">
                    <td style="padding: 8px;">${line.date}</td>
                    <td style="padding: 8px;"><strong>${line.desc}</strong></td>
                    <td style="padding: 8px; text-align: right;">${line.billed > 0 ? '$'+line.billed.toFixed(2) : '-'}</td>
                    <td style="padding: 8px; text-align: right; color: #27ae60;">${line.paid > 0 ? '-$'+line.paid.toFixed(2) : '-'}</td>
                    <td style="padding: 8px; text-align: right; color: #8e44ad;">${line.discount > 0 ? '-$'+line.discount.toFixed(2) : '-'}</td>
                    <td style="padding: 8px; text-align: right; font-weight:bold; color: ${rowOwe > 0.01 ? '#c0392b' : '#27ae60'};">$${rowOwe.toFixed(2)}</td>
                </tr>`;
        });

        totalGlobalBilled += catBilled;
        totalGlobalPaid += catPaid;
        let catOwe = catBilled - catPaid - catDiscount;

        if (rowsHtml === '') return ''; // Hide empty categories

        return `
            <h4 style="color: ${color}; margin: 20px 0 5px 0; border-bottom: 2px solid ${color}; padding-bottom: 5px;">${title} Summary</h4>
            <table style="width: 100%; border-collapse: collapse; margin-bottom: 10px; font-size: 13px;">
                <thead>
                    <tr style="background: #f8f9fa;">
                        <th style="padding: 8px; text-align: left; border-bottom: 1px solid #bdc3c7;">Date</th>
                        <th style="padding: 8px; text-align: left; border-bottom: 1px solid #bdc3c7;">Description</th>
                        <th style="padding: 8px; text-align: right; border-bottom: 1px solid #bdc3c7;">Billed</th>
                        <th style="padding: 8px; text-align: right; border-bottom: 1px solid #bdc3c7;">Paid/Credit</th>
                        <th style="padding: 8px; text-align: right; border-bottom: 1px solid #bdc3c7;">Discount</th>
                        <th style="padding: 8px; text-align: right; border-bottom: 1px solid #bdc3c7;">Balance</th>
                    </tr>
                </thead>
                <tbody>${rowsHtml}</tbody>
                <tfoot>
                    <tr style="font-weight: bold; background: #ecf0f1;">
                        <td colspan="2" style="padding: 8px; text-align: right;">Category Totals:</td>
                        <td style="padding: 8px; text-align: right;">$${catBilled.toFixed(2)}</td>
                        <td style="padding: 8px; text-align: right; color: #27ae60;">-$${catPaid.toFixed(2)}</td>
                        <td style="padding: 8px; text-align: right; color: #8e44ad;">-$${catDiscount.toFixed(2)}</td>
                        <td style="padding: 8px; text-align: right; color: ${catOwe > 0.01 ? '#c0392b' : '#27ae60'};">$${catOwe.toFixed(2)}</td>
                    </tr>
                </tfoot>
            </table>
        `;
    };

    let tablesHtml = buildCategoryTable('Standard', 'Standard Tuition & Fees', '#2c3e50');
    tablesHtml += buildCategoryTable('Event', 'Events & Trips', '#8e44ad');
    tablesHtml += buildCategoryTable('Shop', 'Uniforms & Shop Matters', '#d35400');

    // NEW STEP: Build Complete Transaction History (Chronological Ledger with Advances)
    let historyRows = '';
    sortedLedger.forEach(entry => {
        const isVoid = entry.status === 'VOID' || entry.status === 'VOIDED';
        const isOverpayment = entry.type === 'overpayment';
        const rowStyle = isOverpayment ? 'background-color:#e8f4f8; border-left: 4px solid #2980b9;' : '';

        let billedAmt = entry.type === 'charge' ? `$${parseFloat(entry.amount || entry.amt || 0).toFixed(2)}` : '-';
        const entryAmount = parseFloat(entry.amount || entry.amt || 0);
        let paidAmt = ['payment', 'credit', 'overpayment'].includes(entry.type) ? `-$${entryAmount.toFixed(2)}` : '-';
        let discountAmt = ['waiver', 'discount'].includes(entry.type) ? `-$${entryAmount.toFixed(2)}` : '-';

        let strikeStyle = isVoid ? 'text-decoration: line-through; opacity: 0.5; background: #fdf2f2;' : '';
        if (isVoid) {
            if (entry.type === 'charge') billedAmt += ' (VOID)';
            else if (discountAmt !== '-') discountAmt += ' (VOID)';
            else paidAmt += ' (VOID)';
        }

        let breakdownHTML = '';
        if (entry.type === 'payment' && entry.breakdown && entry.breakdown.length > 0) {
            breakdownHTML = '<ul style="margin: 5px 0 0 15px; padding: 0; font-size: 11px; color: #1e8449; list-style-type: square;">';
            entry.breakdown.forEach(b => {
                const safeBDesc = b.description || b.desc || b.notes || b.item || 'Unallocated';
                let cleanDesc = safeBDesc.replace(' (System Auto)', '').replace(' (Admin Selected)', '');
                breakdownHTML += `<li>${cleanDesc}: <strong>$${parseFloat(b.amt || b.amount || 0).toFixed(2)}</strong></li>`;
            });
            breakdownHTML += '</ul>';
        }

        let receiptBadge = (entry.receiptNo || entry.receipt_no) ? `<br><span style="font-size: 10px; background: #ecf0f1; padding: 2px 5px; border-radius: 3px; color: #7f8c8d;">Ref: ${entry.receiptNo || entry.receipt_no}</span>` : '';
        let safeDescription = entry.description || entry.desc || entry.notes || entry.item || entry.category || 'Transaction';
        let overpayLabel = isOverpayment ? ' <br><span style="font-size:10px; font-weight:bold; color:#2980b9;">💰 OVERPAYMENT</span>' : '';
        const discountLabel = ['waiver', 'discount'].includes(entry.type)
            ? `<br><span style="font-size:10px; font-weight:bold; color:#8e44ad;">${entry.type === 'waiver' ? 'WAIVER' : 'DISCOUNT'}</span>`
            : '';

        if (entry.type === 'payment' && safeDescription.includes('&')) {
            safeDescription = 'Combined Payment Breakdown:';
        }

        let termLabel = entry.term || '-';
        let paidColor = isOverpayment ? '#2980b9' : '#27ae60';

        historyRows += `
            <tr style="${strikeStyle}${rowStyle}">
                <td style="padding:8px; border-bottom:1px dashed #bdc3c7; font-size:12px; vertical-align:top;">${entry.date || '-'}${overpayLabel}</td>
                <td style="padding:8px; border-bottom:1px dashed #bdc3c7; font-size:12px; vertical-align:top;">${termLabel}</td>
                <td style="padding:8px; border-bottom:1px dashed #bdc3c7; font-size:12px; vertical-align:top;">
                    <strong>${safeDescription}</strong> ${receiptBadge}${discountLabel}
                    ${breakdownHTML}
                </td>
                <td style="text-align:right; font-weight:bold; border-bottom:1px dashed #bdc3c7; color:#e74c3c; font-size:12px; vertical-align:top;">${billedAmt}</td>
                <td style="text-align:right; font-weight:bold; border-bottom:1px dashed #bdc3c7; color:${paidColor}; font-size:12px; vertical-align:top;">${paidAmt}</td>
                <td style="text-align:right; font-weight:bold; border-bottom:1px dashed #bdc3c7; color:#8e44ad; font-size:12px; vertical-align:top;">${discountAmt}</td>
                <td style="border-bottom:1px dashed #bdc3c7; font-size:12px; vertical-align:top;">${entry.processed_by || '-'}</td>
            </tr>
        `;
    });

    let fullLedgerHTML = `
        <div style="page-break-inside: avoid;">
            <h4 style="color: #34495e; margin: 40px 0 5px 0; border-bottom: 2px solid #34495e; padding-bottom: 5px;">Complete Transaction History (Ledger)</h4>
            <table style="width: 100%; border-collapse: collapse; margin-bottom: 20px;">
                <thead>
                    <tr style="background: #ecf0f1;">
                        <th style="padding: 8px; text-align: left; border-bottom: 1px solid #bdc3c7; font-size: 13px;">Date</th>
                        <th style="padding: 8px; text-align: left; border-bottom: 1px solid #bdc3c7; font-size: 13px;">Period</th>
                        <th style="padding: 8px; text-align: left; border-bottom: 1px solid #bdc3c7; font-size: 13px;">Description & Details</th>
                        <th style="padding: 8px; text-align: right; border-bottom: 1px solid #bdc3c7; font-size: 13px;">Billed</th>
                        <th style="padding: 8px; text-align: right; border-bottom: 1px solid #bdc3c7; font-size: 13px;">Paid/Credit</th>
                        <th style="padding: 8px; text-align: right; border-bottom: 1px solid #bdc3c7; font-size: 13px;">Discount</th>
                        <th style="padding: 8px; text-align: left; border-bottom: 1px solid #bdc3c7; font-size: 13px;">Admin</th>
                    </tr>
                </thead>
                <tbody>
                    ${historyRows || '<tr><td colspan="7" style="text-align:center; padding: 15px;">No transactions recorded.</td></tr>'}
                </tbody>
            </table>
        </div>
    `;

    const totalGlobalDiscount = statementLines.reduce((total, line) => total + line.discount, 0);
    const finalBalance = totalGlobalBilled - totalGlobalPaid - totalGlobalDiscount;
    const dateStr = new Date().toLocaleDateString();
    const safeSettings = window.settings || {};
    const schoolName = safeSettings.schoolName || 'HAVEN GAMES & ONLINE';
    const logoHTML = safeSettings.logoUrl ? `<img src="${safeSettings.logoUrl}" style="height:70px; display:block; margin: 0 auto 15px auto;">` : '';

    let printHTML = `
        <html><head><title>Statement of Account - ${student.name}</title>
        <style>
            body { font-family: 'Segoe UI', Tahoma, sans-serif; padding: 40px; color: #2c3e50; max-width: 800px; margin: 0 auto; }
            .header { text-align: center; border-bottom: 3px solid #2c3e50; padding-bottom: 20px; margin-bottom: 20px; }
            h1 { margin: 0 0 5px 0; font-size: 24px; text-transform: uppercase; }
            .student-info { display: flex; justify-content: space-between; background: #f8f9fa; padding: 15px; border: 1px solid #bdc3c7; border-radius: 6px; margin-bottom: 20px; font-size: 14px; }
            .summary-box { float: right; width: 300px; background: #fdfefe; border: 1px solid #bdc3c7; padding: 15px; border-radius: 6px; margin-top: 20px; margin-bottom: 30px;}
            .summary-row { display: flex; justify-content: space-between; margin-bottom: 10px; font-size: 14px; }
        </style>
        </head><body>
            <div class="header">
                ${logoHTML}
                <h1>${schoolName}</h1>
                <h3 style="margin: 0; color: #7f8c8d;">DETAILED STATEMENT OF ACCOUNT</h3>
            </div>

            <div class="student-info">
                <div>
                    <p style="margin: 0 0 5px 0;"><strong>Student Name:</strong> ${student.name}</p>
                    <p style="margin: 0 0 5px 0;"><strong>Student ID:</strong> ${student.id}</p>
                    <p style="margin: 0;"><strong>Grade / Class:</strong> ${student.grade || 'N/A'}</p>
                </div>
                <div style="text-align: right;">
                    <p style="margin: 0 0 5px 0;"><strong>Statement Date:</strong> ${dateStr}</p>
                    <p style="margin: 0;"><strong>Contact:</strong> ${student.phone || student.cell || 'N/A'}</p>
                </div>
            </div>

            ${tablesHtml || '<p style="text-align:center; padding:20px;">No financial history found.</p>'}

            <div class="summary-box">
                <div class="summary-row"><span>Total Billed:</span> <strong>$${totalGlobalBilled.toFixed(2)}</strong></div>
                <div class="summary-row"><span>Total Paid:</span> <strong style="color: #27ae60;">-$${totalGlobalPaid.toFixed(2)}</strong></div>
                <div class="summary-row"><span>Total Discount:</span> <strong style="color: #8e44ad;">-$${totalGlobalDiscount.toFixed(2)}</strong></div>
                <hr style="border: 0; border-top: 1px dashed #bdc3c7; margin: 10px 0;">
                <div class="summary-row" style="font-size: 18px; font-weight: bold; color: ${finalBalance > 0.01 ? '#c0392b' : '#27ae60'};">
                    <span>Balance Due:</span> <span>$${(finalBalance > 0 ? finalBalance : 0).toFixed(2)}</span>
                </div>
                ${finalOverpaymentBalance > 0.01 ? `<hr style="border: 0; border-top: 1px dashed #bdc3c7; margin: 10px 0;">
                <div class="summary-row" style="font-size: 16px; font-weight: bold; color: #2980b9; background: #e8f4f8; padding: 8px; border-radius: 4px; border: 1px solid #b3d4fc;">
                    <span>💰 Available Credit:</span> <span>+$${finalOverpaymentBalance.toFixed(2)}</span>
                </div>
                <p style="font-size: 12px; color: #7f8c8d; margin: 8px 0 0 0; font-style: italic;">This credit/overpayment can be used for future purchases or fees.</p>` : ''}
            </div>
            
            <div style="clear: both;"></div>

            <!-- THE NEW COMPLETE LEDGER INJECTION -->
            ${fullLedgerHTML}
            
            <div style="clear: both; padding-top: 30px; text-align: center; font-size: 12px; color: #7f8c8d;">
                <p>Please contact the administration office for any queries regarding this statement.</p>
                <p>Thank you for your continued support.</p>
            </div>
        </body></html>
    `;

    const printWindow = window.open('', '_blank');
    printWindow.document.write(printHTML);
    printWindow.document.close();
    setTimeout(() => { printWindow.print(); }, 800);
};
window.updatePaymentLiveTotals = function() {
    const usdInput = document.getElementById('payUsd');
    const zigInput = document.getElementById('payZig');
    const rateInput = document.getElementById('zigRate');
    const methodInput = document.getElementById('payMethod');
    const totalDiv = document.getElementById('livePaymentTotal');
    const searchInput = document.getElementById('payId');
    
    // Failsafe: Ensure critical UI elements exist before executing
    if (!usdInput || !zigInput || !rateInput || !totalDiv) return;

    const rate = parseFloat(rateInput.value) || 1;
    let usd = parseFloat(usdInput.value) || 0;
    let zig = parseFloat(zigInput.value) || 0;
    const method = methodInput ? methodInput.value : 'Cash';

    // Auto-calculate split payments if a student is selected
    if (method === 'Split Payment' && searchInput && searchInput.value) {
        
        // Find student robustly (handles formats like "STU-1001 - Name" seamlessly)
        const searchVal = searchInput.value.toUpperCase();
        const student = window.students ? window.students.find(s => searchVal.includes(s.id.toUpperCase())) : null;
        
        // Support both new SQL schema (balance_owing) and old UI state (balanceOwing)
        const debt = student ? parseFloat(student.balance_owing || student.balanceOwing || 0) : 0;
        
        // UX Protection: Only auto-fill ZiG if the user is actively typing in the USD box.
        // This allows the cashier to manually override the ZiG box without it snapping back.
        if (usd > 0 && debt > usd && document.activeElement === usdInput) {
            let remainingUSD = debt - usd;
            zigInput.value = (remainingUSD * rate).toFixed(2);
            
            // Re-read the newly auto-filled value so the total calculates correctly
            zig = parseFloat(zigInput.value); 
        }
    }

    // Display the live accurate total
    const totalUSD = usd + (zig / rate);
    totalDiv.innerHTML = `Total Received Equivalent: <span style="color:#27ae60; font-size: 18px; font-weight: bold;">$${totalUSD.toFixed(2)} USD</span>`;
};
window.generateAdvancedWhatsAppInvoice = function(student, transactionAmount, breakdownArray, parentPhone) {
    // 1. Get the School Name from your settings (Fallback if not set)
    const schoolName = window.settings?.schoolName || "School Administration";
    const date = new Date().toLocaleDateString();
    const time = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

    // 2. Build the Advanced Text Message
    let msg = `🏫 *${schoolName.toUpperCase()}*\n`;
    msg += `-----------------------------------\n`;
    msg += `🧾 *OFFICIAL PAYMENT RECEIPT*\n`;
    msg += `-----------------------------------\n\n`;

    msg += `*👤 STUDENT DETAILS*\n`;
    msg += `▪️ *Name:* ${student.name || student.student_name || "N/A"}\n`;
    msg += `▪️ *ID:* ${student.id || "N/A"}\n`;
    msg += `▪️ *Grade/Class:* ${student.grade || student.class || "N/A"}\n\n`;

    msg += `*💰 TRANSACTION SUMMARY*\n`;
    msg += `▪️ *Total Paid:* $${parseFloat(transactionAmount).toFixed(2)}\n`;
    msg += `▪️ *Date:* ${date} at ${time}\n\n`;

    msg += `*📊 ADVANCED BREAKDOWN*\n`;
    
    // Loop through whatever they paid for (e.g., Tuition, Uniforms, Arrears)
    if (breakdownArray && breakdownArray.length > 0) {
        breakdownArray.forEach(item => {
            msg += `- ${item.description}: $${parseFloat(item.amount).toFixed(2)}\n`;
        });
    } else {
        msg += `- Standard Payment Allocation: $${parseFloat(transactionAmount).toFixed(2)}\n`;
    }

    msg += `\n-----------------------------------\n`;
    // Calculate remaining balance if your system tracks it
    const remainingBalance = student.balanceOwing || window.currentParentBalance || 0;
    if (remainingBalance > 0) {
        msg += `*⚠️ Remaining Balance:* $${parseFloat(remainingBalance).toFixed(2)}\n`;
    } else {
        msg += `*✅ Account Status:* Fully Cleared\n`;
    }
    
    msg += `\n_Thank you for your payment!_\n_System generated receipt._`;

    // 3. Format the Phone Number (Remove spaces/pluses)
    let cleanPhone = "";
    if (parentPhone) {
        cleanPhone = String(parentPhone).replace(/\D/g, '');
        // Optional: Ensure it has country code if needed, e.g., prepending '263' for Zimbabwe if local
    }

    // 4. Encode for URL and attach to the button
    const encodedMessage = encodeURIComponent(msg);
    const waLink = cleanPhone ? `https://wa.me/${cleanPhone}?text=${encodedMessage}` : `https://wa.me/?text=${encodedMessage}`;
    
    const waBtn = document.getElementById('pppsWhatsAppBtn');
    if (waBtn) waBtn.href = waLink;
};
