window.logNewEcoCash = async function() {
    const refNumber = document.getElementById('newEcoRef').value.trim().toUpperCase();
    const studentId = document.getElementById('newEcoStudentId').value.trim();
    const usdAmount = parseFloat(document.getElementById('newEcoAmountUsd').value) || 0;
    const zigAmount = parseFloat(document.getElementById('newEcoAmountZig').value) || 0;
    const cashierName = window.currentUser?.user || window.currentUser?.username || window.currentUser?.name || 'Admin';
    
    if (!refNumber || !studentId || (usdAmount <= 0 && zigAmount <= 0)) {
        return alert("⚠️ Please provide Reference, Student ID, and at least one amount (USD or ZiG).");
    }

    const student = window.students.find(s => String(s.id) === String(studentId));
    if (!student) return alert(`❌ Student ID ${studentId} not found.`);
    if (!student.ledger) student.ledger = [];

    if (!window.ecoCashTransactions) window.ecoCashTransactions = [];
    if(window.ecoCashTransactions.some(t => t.ref.toUpperCase() === refNumber)) {
        return alert("❌ This Reference Number already exists in the Database.");
    }

    const rateEl = document.getElementById('zigRate');
    const zigRate = parseFloat(rateEl?.value) || 13.56;
    let totalClearedValue = usdAmount;
    if (zigAmount > 0) {
        totalClearedValue += (zigAmount / zigRate);
    }

    // ==========================================
    // 🧠 1. SMART WATERFALL 
    // ==========================================
    let charges = {};
    let paid = {};

    student.ledger.forEach(l => {
        if (l.status === 'VOID' || l.status === 'VOIDED') return;
        if (l.type === 'charge') {
            const safeDesc = (l.desc || l.description || 'General Charge').trim();
            charges[safeDesc] = (charges[safeDesc] || 0) + (parseFloat(l.amount) || 0);
        }
        if ((l.type === 'payment' || l.type === 'waiver' || l.type === 'discount') && l.breakdown) {
            l.breakdown.forEach(b => {
                let baseName = (b.desc || b.description || 'General Charge').replace(" (System Auto)", "").replace(" (Admin Confirmed)", "").trim();
                paid[baseName] = (paid[baseName] || 0) + (parseFloat(b.amt) || 0);
            });
        }
    });

    let owed = {};
    for (let desc in charges) {
        let amtOwed = charges[desc] - (paid[desc] || 0);
        if (amtOwed > 0.01) owed[desc] = amtOwed;
    }

    // ==========================================
    // 🧮 2. ALLOCATE TO ITEMS
    // ==========================================
    let remainingAmount = totalClearedValue;
    let breakdownArr = [];

    // A. PRIORITY PROMPT: SHOP & EVENTS
    for (let desc in owed) {
        let dLower = desc.toLowerCase();
        if ((dLower.includes('event') || dLower.includes('trip') || dLower.includes('shop') || dLower.includes('uniform')) && owed[desc] > 0.01 && remainingAmount > 0) {
            
            let possibleAlloc = Math.min(remainingAmount, owed[desc]);
            let wantsToPay = confirm(`🛒/🚌 SPECIAL ITEM DETECTED:\n\nThis student owes $${owed[desc].toFixed(2)} for:\n"${desc}"\n\nDo you want to allocate $${possibleAlloc.toFixed(2)} from this EcoCash payment towards this item?`);
            
            if (wantsToPay) {
                breakdownArr.push({ desc: `${desc} (Admin Confirmed)`, amt: possibleAlloc, cleanDesc: desc });
                remainingAmount -= possibleAlloc;
                owed[desc] -= possibleAlloc; 
            }
        }
    }

    // B. SYSTEM WATERFALL: STANDARD FEES
    for (let desc in owed) {
        let dLower = desc.toLowerCase();
        if (dLower.includes('event') || dLower.includes('trip') || dLower.includes('shop') || dLower.includes('uniform')) continue; 

        if (owed[desc] > 0.01 && remainingAmount > 0) {
            let alloc = Math.min(remainingAmount, owed[desc]);
            breakdownArr.push({ desc: `${desc} (System Auto)`, amt: alloc, cleanDesc: desc });
            remainingAmount -= alloc;
            owed[desc] -= alloc; 
        }
    }

    // C. LEFTOVER CREDIT
    if (remainingAmount > 0.01) {
        breakdownArr.push({ desc: 'Account Credit (Overpayment)', amt: remainingAmount, cleanDesc: 'Account Credit' });
    }
    if (breakdownArr.length === 0) {
        breakdownArr.push({ desc: 'EcoCash General Payment', amt: totalClearedValue, cleanDesc: 'General Payment' });
    }

    const paymentReason = breakdownArr.map(b => b.desc).join(' & ');
    const paymentDate = new Date().toISOString().split('T')[0];
    const receiptNo = "ECO-" + refNumber;
    const dbId = Date.now().toString();

    // 🎯 SMART CATEGORIZATION: Fixes the Vault reporting bug
    const reasonLower = paymentReason.toLowerCase();
    let mainCategory = 'Fees';
    if (reasonLower.includes('shop') || reasonLower.includes('uniform')) mainCategory = 'Shop';
    else if (reasonLower.includes('event') || reasonLower.includes('trip')) mainCategory = 'Events';

    // ==========================================
    // 💾 3. CREATE RECORDS (CLEANED FOR SUPABASE)
    // ==========================================
    
    // A. Local UI Record
    const localPaymentRecord = {
        id: "PAY-" + dbId,
        student_id: studentId,
        date: paymentDate,
        type: 'payment',
        amount: parseFloat(totalClearedValue.toFixed(2)), 
        zig: parseFloat(zigAmount.toFixed(2)), 
        method: 'EcoCash', 
        desc: paymentReason,
        description: paymentReason,
        receiptNo: receiptNo,
        receipt_no: receiptNo,
        breakdown: breakdownArr,
        processed_by: cashierName
    };

    // B. Strict Database Ledger Record
    const dbLedgerRecord = {
        id: "PAY-" + dbId,
        student_id: studentId,
        date: paymentDate,
        type: 'payment',
        amount: parseFloat(totalClearedValue.toFixed(2)), 
        zig: parseFloat(zigAmount.toFixed(2)), 
        method: 'EcoCash', 
        description: paymentReason,
        receipt_no: receiptNo,
        breakdown: breakdownArr,
        processed_by: cashierName
    };

    // C. Cloud Vault Record
    const cloudPaymentRecord = {
        id: parseInt(dbId) || Date.now(),
        student_id: studentId,
        date: paymentDate,
        amount: parseFloat(totalClearedValue.toFixed(2)), 
        zig: parseFloat(zigAmount.toFixed(2)), 
        method: 'EcoCash',
        receipt_no: receiptNo,
        notes: paymentReason,
        category: mainCategory,
        status: 'PAID',
        processed_by: cashierName
    };

    // D. Update Local UI State
    student.ledger.push(localPaymentRecord);
    student.balanceOwing = window.calculateStudentBalance ? window.calculateStudentBalance(student) : (student.balanceOwing - totalClearedValue);

    const newEcoTracker = {
        date: paymentDate,
        ref: refNumber,
        studentId: studentId,
        amount: usdAmount,
        zigAmount: zigAmount,
        status: 'claimed',
        claimedBy: window.currentUser?.name || 'Admin',
        source: 'walk-in-admin'
    };
    window.ecoCashTransactions.push(newEcoTracker);
    if (typeof window.saveEcoCashTransactions === 'function') window.saveEcoCashTransactions();

    // ==========================================
    // ☁️ 4. SYNC TO CLOUD & PRINT RECEIPT
    // ==========================================
    try {
        await Promise.all([
            window.supabase.from('payments').insert([cloudPaymentRecord]),
            window.supabase.from('student_ledger').insert([dbLedgerRecord])
        ]);

        if (typeof window.saveData === 'function') await window.saveData();

        if (typeof window.calculateReconciliation === 'function') window.calculateReconciliation();
        if (typeof window.calculateVaultStats === 'function') window.calculateVaultStats();
        if (typeof window.renderPendingReferences === 'function') window.renderPendingReferences();

        // Clear the form fields FIRST so they are ready for the next student
        document.getElementById('newEcoRef').value = '';
        document.getElementById('newEcoStudentId').value = '';
        document.getElementById('newEcoAmountUsd').value = '';
        document.getElementById('newEcoAmountZig').value = '';

        // 👇 THE FIX: Instantly trigger the beautiful Action Menu we built! 👇
        if (typeof window.reprintReceipt === 'function') {
            window.reprintReceipt(receiptNo, studentId);
        } else {
            alert(`✅ EcoCash Walk-in Logged!\nReceipt: ${receiptNo}\nAmount: $${totalClearedValue.toFixed(2)}`);
        }
        
    } catch (err) {
        console.error("Manual EcoCash Cloud Sync Error:", err);
        alert("⚠️ Saved locally, but cloud sync failed: " + (err.message || JSON.stringify(err)));
    }
};


