// THE UPGRADED VAULT CALCULATOR ENGINE
// ==========================================
window.showVaultBreakdown = function(categoryKey, title, formulaText = "") {
    if (!window.vaultBreakdowns) return alert("Vault data is still loading. Please wait.");
    
    let records = [];
    
    // 🎯 Dynamically build Net Cash / Net Online by combining inflows and outflows
    if (categoryKey === 'netCash') {
        records = [
            ...(window.vaultBreakdowns.tuitionCash || []).map(r => ({...r, type: 'Inflow (+)'})),
            ...(window.vaultBreakdowns.shopCash || []).map(r => ({...r, type: 'Inflow (+)'})),
            ...(window.vaultBreakdowns.eventCash || []).map(r => ({...r, type: 'Inflow (+)'})),
            ...(window.vaultBreakdowns.overpayCash || []).map(r => ({...r, type: 'Inflow (+)'})),
            ...(window.vaultBreakdowns.expensesCash || []).map(r => ({...r, amount: -Math.abs(r.amount), type: 'Outflow (-)'}))
        ];
    } else if (categoryKey === 'netOnline') {
        records = [
            ...(window.vaultBreakdowns.tuitionOnline || []).map(r => ({...r, type: 'Inflow (+)'})),
            ...(window.vaultBreakdowns.shopOnline || []).map(r => ({...r, type: 'Inflow (+)'})),
            ...(window.vaultBreakdowns.eventOnline || []).map(r => ({...r, type: 'Inflow (+)'})),
            ...(window.vaultBreakdowns.overpayOnline || []).map(r => ({...r, type: 'Inflow (+)'})),
            ...(window.vaultBreakdowns.expensesOnline || []).map(r => ({...r, amount: -Math.abs(r.amount), type: 'Outflow (-)'}))
        ];
    } else {
        records = window.vaultBreakdowns[categoryKey] || [];
    }

    if (records.length === 0) return alert(`No records found for ${title} in this date range.`);

    // Sort by largest absolute amount first
    records.sort((a, b) => Math.abs(b.amount) - Math.abs(a.amount));
    const totalAmount = records.reduce((sum, r) => sum + r.amount, 0);

    const isNetView = categoryKey === 'netCash' || categoryKey === 'netOnline';
    const supportsMethodFilter = categoryKey === 'netOnline' || categoryKey === 'expensesOnline';
    const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g, character => ({
        '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    })[character]);
    const getMethodGroup = method => {
        const normalized = String(method || '').trim().toLowerCase();
        if (!normalized || normalized === 'not specified' || normalized === 'n/a') return 'Not recorded';
        if (normalized.includes('ecocash')) return 'EcoCash';
        if (normalized.includes('innbucks')) return 'Innbucks';
        if (normalized.includes('online bank')) return 'Online Bank';
        if (normalized.includes('bank') || normalized.includes('transfer')) return 'Bank Transfer';
        if (normalized.includes('zipit')) return 'Zipit';
        if (normalized.includes('swipe') || normalized.includes('card')) return 'Card / Swipe';
        if (normalized.includes('online')) return 'Online (Other)';
        return 'Other';
    };
    const methodGroups = supportsMethodFilter
        ? Array.from(new Set(records.map(record => getMethodGroup(record.method)))).sort()
        : [];
    const methodFilterHtml = supportsMethodFilter ? `
        <div class="method-filter">
            <label for="vaultMethodFilter">Filter by payment method:</label>
            <select id="vaultMethodFilter" onchange="filterVaultMethod()">
                <option value="all">All methods</option>
                ${methodGroups.map(group => `<option value="${escapeHtml(group)}">${escapeHtml(group)}</option>`).join('')}
            </select>
            <span id="vaultBreakdownCount">${records.length} transaction(s)</span>
        </div>
    ` : '';

    let rowsHtml = records.map(r => {
        const methodGroup = getMethodGroup(r.method);
        return `
            <tr ${supportsMethodFilter ? `data-method-group="${escapeHtml(methodGroup)}" data-amount="${Number(r.amount) || 0}"` : ''} style="border-bottom: 1px solid #ddd; ${r.amount < 0 ? 'background-color: #fdf2f2;' : ''}">
                <td style="padding: 8px;">${escapeHtml(r.date || '-')}</td>
                <td style="padding: 8px; font-weight: bold;">${escapeHtml(r.desc || '-')}</td>
                <td style="padding: 8px; color: #555;">${escapeHtml(r.ref || '-')}</td>
                ${supportsMethodFilter ? `<td style="padding: 8px;">${escapeHtml(r.method || 'Not recorded')}</td>` : ''}
                ${isNetView ? `<td style="padding: 8px; font-size: 11px;">${escapeHtml(r.type || '')}</td>` : ''}
                <td style="padding: 8px; text-align: right; font-weight: bold; color: ${r.amount < 0 ? '#c0392b' : '#27ae60'};">
                    $${Number(r.amount || 0).toFixed(2)}
                </td>
            </tr>
        `;
    }).join('');

    const formulaHtml = formulaText 
        ? `<div style="background: #eef6ff; border-left: 4px solid #3498db; padding: 12px; margin-bottom: 20px; font-size: 13px; color: #2c3e50; border-radius: 4px;">
            <strong>💡 What is this calculation?</strong><br>${escapeHtml(formulaText)}
           </div>` 
        : '';

    const html = `
    <html>
    <head>
        <title>${escapeHtml(title)} Breakdown</title>
        <style>
            body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; padding: 20px; background: #f4f6f7; margin: 0; }
            .container { background: #fff; max-width: 650px; margin: 0 auto; padding: 20px; border-radius: 8px; box-shadow: 0 4px 10px rgba(0,0,0,0.1); }
            h2 { margin-top: 0; color: #2c3e50; border-bottom: 2px solid #3498db; padding-bottom: 10px; }
            table { width: 100%; border-collapse: collapse; font-size: 13px; margin-top: 20px; }
            th { text-align: left; background: #ecf0f1; padding: 10px 8px; color: #333; }
            .total-row { background: #e8f8f5; font-size: 16px; border-top: 2px solid #27ae60; }
            .method-filter { display:flex; flex-wrap:wrap; align-items:center; gap:8px; margin:12px 0; font-size:13px; }
            .method-filter select { padding:7px; min-width:180px; border:1px solid #bdc3c7; border-radius:4px; }
            .method-filter span { color:#7f8c8d; font-size:12px; }
            @media print { body { background: #fff; } .container { box-shadow: none; max-width: 100%; } button, .method-filter { display: none; } }
        </style>
    </head>
    <body>
        <div class="container">
            <h2>${escapeHtml(title)} Breakdown</h2>
            ${formulaHtml}
            ${methodFilterHtml}
            <button onclick="window.print()" style="margin-bottom: 15px; padding: 8px 15px; background: #2c3e50; color: #fff; border: none; border-radius: 4px; cursor: pointer;">🖨️ Print List</button>
            <table>
                <thead>
                    <tr>
                        <th>Date</th>
                        <th>Name / Description</th>
                        <th>ID / Reference</th>
                        ${supportsMethodFilter ? '<th>Payment Method</th>' : ''}
                        ${isNetView ? '<th>Flow</th>' : ''}
                        <th style="text-align: right;">Amount</th>
                    </tr>
                </thead>
                <tbody id="vaultBreakdownRows">
                    ${rowsHtml}
                    <tr class="total-row">
                        <td colspan="${(isNetView ? 4 : 3) + (supportsMethodFilter ? 1 : 0)}" style="padding: 12px 8px; font-weight: bold; text-align: right;">TOTAL MATH RESULT:</td>
                        <td id="vaultBreakdownFilteredTotal" style="padding: 12px 8px; font-weight: bold; text-align: right; color: ${totalAmount < 0 ? '#c0392b' : '#27ae60'};">$${totalAmount.toFixed(2)}</td>
                    </tr>
                </tbody>
            </table>
        </div>
        ${supportsMethodFilter ? `<script>
            function filterVaultMethod() {
                var selectedMethod = document.getElementById('vaultMethodFilter').value;
                var total = 0;
                var count = 0;
                document.querySelectorAll('#vaultBreakdownRows tr[data-method-group]').forEach(function(row) {
                    var visible = selectedMethod === 'all' || row.getAttribute('data-method-group') === selectedMethod;
                    row.style.display = visible ? '' : 'none';
                    if (visible) {
                        total += parseFloat(row.getAttribute('data-amount')) || 0;
                        count++;
                    }
                });
                document.getElementById('vaultBreakdownFilteredTotal').textContent = '$' + total.toFixed(2);
                document.getElementById('vaultBreakdownCount').textContent = count + ' transaction(s)';
            }
        </script>` : ''}
    </body>
    </html>
    `;

    const popup = window.open('', '_blank', 'width=700,height=750');
    if (popup) {
        popup.document.write(html);
        popup.document.close();
    } else {
        alert("Popup blocked! Please allow popups to view the breakdown.");
    }
};
window.calculateVaultStats = async function() {
    const rateInput = document.getElementById('zigRate');
    const rate = rateInput ? (parseFloat(rateInput.value) || 1) : 1;

    const startDateInput = document.getElementById('vaultStartDate');
    if (startDateInput && !startDateInput.value) {
        const now = new Date();
        startDateInput.value = [now.getFullYear(), String(now.getMonth() + 1).padStart(2, '0'), String(now.getDate()).padStart(2, '0')].join('-');
    }

    const startDate = document.getElementById('vaultStartDate')?.value;
    const endDate = document.getElementById('vaultEndDate')?.value;
    const classFilter = (document.getElementById('vaultClassFilter')?.value || "").toLowerCase().trim();
    const studentFilter = (document.getElementById('vaultStudentFilter')?.value || "").toLowerCase().trim();

    let studentsData = window.students || [];
    let vaultCashExpenses = 0, vaultOnlineExpenses = 0, vaultZigExpenses = 0, vaultPayrollExpenses = 0;
    const paymentArchiveByReceipt = new Map();

    // 🎯 INITIALIZE ALL BREAKDOWN TRACKERS
    window.vaultBreakdowns = {
        expected: [], collected: [], debt: [], overpayment: [],
        tuitionCash: [], tuitionOnline: [], shopCash: [], shopOnline: [],
        eventCash: [], eventOnline: [], overpayCash: [], overpayOnline: [], 
        expensesCash: [], expensesOnline: [], expensesZig: [],
        tuitionDiscount: [], shopDiscount: [], tuitionWaiver: [], shopWaiver: []
    };

    if (typeof window.supabaseClient !== 'undefined') {
        try {
            document.body.style.cursor = 'wait';
            let paymentsQuery = window.supabaseClient
                .from('payments')
                .select('receipt_no,created_at,processed_by,served_by');
            if (startDate) paymentsQuery = paymentsQuery.gte('date', startDate);
            if (endDate) paymentsQuery = paymentsQuery.lte('date', endDate);
            const [studentsResult, paymentsResult] = await Promise.all([
                window.supabaseClient.from('students').select(`*, student_ledger (*)`),
                paymentsQuery
            ]);
            if (studentsResult.error) throw studentsResult.error;
            if (paymentsResult.error) throw paymentsResult.error;
            if (studentsResult.data) studentsData = studentsResult.data;
            (paymentsResult.data || []).forEach(payment => {
                paymentArchiveByReceipt.set(String(payment.receipt_no || '').toUpperCase(), payment);
            });
        } catch(e) { console.error("Vault fetch error:", e); } 
        finally { document.body.style.cursor = 'default'; }
    }

    if (typeof window.supabaseClient !== 'undefined') {
        try {
            const { data: payrollRows, error: payrollError } = await window.supabaseClient.from('payroll_history').select('*');
            if (payrollError) throw payrollError;
            (payrollRows || []).forEach(record => {
                if (String(record.status || '').toLowerCase() === 'void') return;
                const payrollDate = String(record.payment_date || record.date || '').trim().split(' ')[0].split('T')[0];
                if (startDate && payrollDate < startDate) return;
                if (endDate && payrollDate > endDate) return;
                const amount = parseFloat(record.amount) || 0;
                if (amount <= 0) return;
                vaultPayrollExpenses += amount; 
            });
        } catch (payrollError) {}
    }

    if (typeof window.supabaseClient !== 'undefined') {
        try {
            const { data: expenseRows, error: expenseError } = await window.supabaseClient.from('expenses').select('*');
            if (expenseError) throw expenseError;
            (expenseRows || []).forEach(exp => {
                let expData = {};
                try { expData = typeof exp.data === 'string' ? JSON.parse(exp.data) : (exp.data || {}); } catch (parseError) {}
                if (exp.status === 'VOID' || exp.status === 'VOIDED') return;
                const expenseType = String(exp.type || expData.type || 'daily').toLowerCase();
                const isTransferType = expenseType.includes('transfer') || expenseType.includes('advance') || expenseType.includes('loan');
                const expenseDate = String(exp.date || expData.date || '').trim().split(' ')[0].split('T')[0];
                if (startDate && expenseDate < startDate) return;
                if (endDate && expenseDate > endDate) return;
                const amount = parseFloat(exp.amount || expData.amount || exp.total || 0) || 0;
                if (amount <= 0) return;
                const currency = String(exp.currency || expData.currency || 'USD').toUpperCase();
                const methodLabel = String(exp.payment_method || expData.payment_method || exp.method || expData.method || 'Cash').trim();
                const method = methodLabel.toLowerCase();
                const isOnline = method.includes('online') || method.includes('transfer') || method.includes('swipe') || method.includes('bank') || method.includes('ecocash') || method.includes('innbucks') || method.includes('zipit');
                if (method.includes('discount')) return; 
                
                const desc = String(exp.description || expData.description || '').toLowerCase();
                if (String(exp.id).includes('EXP-INV') || desc.includes('stock purchase')) return; 

                const breakObj = {
                    date: expenseDate,
                    desc: exp.description || expData.description || expData.desc || 'Expense',
                    ref: exp.id || expData.id || methodLabel,
                    method: methodLabel,
                    amount: amount
                };

                if (currency === 'ZIG') { vaultZigExpenses += amount; window.vaultBreakdowns.expensesZig.push(breakObj); }
                else if (isOnline) { vaultOnlineExpenses += amount; window.vaultBreakdowns.expensesOnline.push(breakObj); }
                else if (!isTransferType) { vaultCashExpenses += amount; window.vaultBreakdowns.expensesCash.push(breakObj); }  
            });
        } catch (expenseError) {}
    }

    let paymentDetails = [];
    let shopCashFromPos = 0, shopOnlineFromPos = 0;

    if (typeof window.supabaseClient !== 'undefined') {
        try {
            const { data: posRows, error: posError } = await window.supabaseClient.from('transactions').select('*');
            if (posError) throw posError;
            
            (posRows || []).forEach(sale => {
                if (sale.status === 'VOID' || sale.status === 'VOIDED' || sale.reconciled === true) return;
                const saleDate = String(sale.date || '').trim().split(' ')[0].split('T')[0];
                if (startDate && saleDate < startDate) return;
                if (endDate && saleDate > endDate) return;
                
                const methodLabel = String(sale.paymentmethod || sale.paymentMethod || sale.payment_method || sale.method || 'Cash').trim();
                const method = methodLabel.toLowerCase();
                let saleValue = parseFloat(sale.amount || 0);
                let cashReceived = parseFloat(sale.total || sale.usdpaid || sale.amount || 0); 
                
                const isOnline = method.includes('online') || method.includes('ecocash') || method.includes('innbucks') || method.includes('transfer') || method.includes('zipit') || method.includes('swipe');
                const isWalkIn = !sale.student_id || sale.student_id === 'WALK-IN';
                
                if (isWalkIn && cashReceived > 0) {
                    const breakObj = { date: saleDate, desc: 'POS Walk-in Sale', ref: sale.receipt_no || sale.id, method: methodLabel, amount: cashReceived };
                    if (isOnline) { shopOnlineFromPos += cashReceived; window.vaultBreakdowns.shopOnline.push(breakObj); }
                    else { shopCashFromPos += cashReceived; window.vaultBreakdowns.shopCash.push(breakObj); }
                }

                if (isWalkIn || cashReceived === 0) {
                    const occurredAt = window.getReceiptEventTimestamp(sale);
                    paymentDetails.push({
                        date: saleDate, studentId: sale.student_id || 'WALK-IN', studentName: sale.student_name || sale.student_id || 'Walk-in Customer',
                        grade: 'Shop POS', type: 'Shop Sale', description: sale.description || sale.item || 'Shop Purchase',
                        method: sale.paymentmethod || sale.method || 'Cash', receipt: sale.receipt_no || sale.id || '-', amount: saleValue,
                        occurredAt, time: window.formatReceiptEventTime(occurredAt),
                        processedBy: window.getReceiptProcessorName(sale)
                    });
                }
            });
        } catch (posError) {}
    }

    if (!studentsData || studentsData.length === 0) return;

    let globalBilled = 0, globalPaid = 0, activeStudentCount = 0;
    let globalTuitionDiscount = 0, globalShopDiscount = 0;
    let globalTuitionWaiver = 0, globalShopWaiver = 0;
    let globalDebt = 0, globalOverpayment = 0;

    let revenue = {
        tuition: { cash: 0, online: 0 }, overpay: { cash: 0, online: 0 },
        shop: { cash: 0, online: 0 }, events: { cash: 0, online: 0 }
    };
    let yields = { transport: 0, food: 0, stationery: 0, textbooks: 0 };
    let exceptionsLog = [];
    let unallocatedPayments = 0;

    const getIsoDate = (dStr) => {
        if (!dStr) return "";
        return String(dStr).trim().split(' ')[0].split('T')[0]; 
    };

    studentsData.forEach(student => {
        if (classFilter && !(student.grade || student.class || "").toLowerCase().includes(classFilter)) return;
        let stuIdStr = (student.id || "").toString().toLowerCase();
        let stuNameStr = (student.name || "").toLowerCase();
        if (studentFilter && !stuIdStr.includes(studentFilter) && !stuNameStr.includes(studentFilter)) return;

        let ledger = student.ledger || student.student_ledger || [];
        
        // Split ledgers - we need ALL time for debt, but strictly DATE FILTERED for everything else
        const filteredLedger = ledger.filter(l => {
            if (l.status === 'VOID' || l.status === 'VOIDED') return false; 
            let rowDate = getIsoDate(l.date);
            if (startDate && rowDate < startDate) return false;
            if (endDate && rowDate > endDate) return false;
            return true;
        });

        activeStudentCount++;
        
        // 🎯 1. CALCULATE SNAPSHOT DEBT (Ignores date filters, shows true real-time arrears)
        let studentTotalBilledAllTime = 0, studentTotalPaidAllTime = 0;
        ledger.forEach(l => {
            if (l.status === 'VOID' || l.status === 'VOIDED') return;
            let amt = parseFloat(l.amount) || 0;
            if (l.type === 'charge') studentTotalBilledAllTime += amt;
            else if (['payment', 'overpayment', 'credit', 'waiver'].includes(l.type)) studentTotalPaidAllTime += amt;
        });
        let studentBalance = studentTotalBilledAllTime - studentTotalPaidAllTime;
        if (studentBalance > 0) {
            globalDebt += studentBalance; 
            window.vaultBreakdowns.debt.push({ date: 'All-Time Snapshot', desc: student.name, ref: student.id, amount: studentBalance });
        }

        if (filteredLedger.length === 0) return; 

        // 🎯 2. PROCESS DATE FILTERED LEDGER
        const paymentReceipts = new Set(
            filteredLedger.filter(entry => (entry.type || '').toLowerCase() === 'payment' && (entry.receipt_no || entry.receiptNo))
            .map(entry => String(entry.receipt_no || entry.receiptNo).toLowerCase())
        );

        filteredLedger.forEach(l => {
            let rowUsd = parseFloat(l.amount) || 0;
            let rowType = (l.type || '').toLowerCase();
            let methodLabel = String(l.method || l.payment_method || 'Not specified').trim();
            let method = methodLabel.toLowerCase();
            let description = (l.description || l.desc || l.notes || '').toLowerCase();
            let isCreditBacked = String(l.is_credit_backed).toLowerCase() === 'true' || method.includes('advance credit') || description.includes('paid via advance credit');
            let isCreditReversal = description.includes('credit allocation (reversal)');
            let isOnline = method.includes('bank') || method.includes('online') || method.includes('transfer') || method.includes('swipe') || method.includes('ecocash') || method.includes('innbucks') || method.includes('zipit');
            let methodKey = isOnline ? 'online' : 'cash';

            // Tracking Expected Billed strictly within Dates
            if (rowType === 'charge') {
                if (isCreditReversal) return;
                globalBilled += rowUsd;
                window.vaultBreakdowns.expected.push({ date: getIsoDate(l.date), desc: `${student.name} (${description})`, ref: student.id, amount: rowUsd });
                return;
            }

            if ((rowType === 'payment' || rowType === 'overpayment')) {
                const receiptNo = String(l.receipt_no || l.receiptNo || l.receipt || '').toUpperCase();
                const archivedPayment = paymentArchiveByReceipt.get(receiptNo);
                const occurredAt = window.getReceiptEventTimestamp(archivedPayment) ??
                    window.getReceiptEventTimestamp(l);
                paymentDetails.push({
                    date: getIsoDate(l.date), studentId: student.id || '', studentName: student.name || '',
                    grade: student.grade || student.class || '', type: rowType === 'overpayment' ? 'Overpayment' : 'Payment',
                    description: description || 'General Payment', method: l.method || l.payment_method || 'Not specified',
                    receipt: l.receipt_no || l.receiptNo || l.receipt || '-', amount: rowUsd,
                    occurredAt, time: window.formatReceiptEventTime(occurredAt),
                    processedBy: window.getReceiptProcessorName(l, archivedPayment)
                });
            }

            if (['payment', 'waiver', 'discount', 'credit', 'overpayment'].includes(rowType)) {
                let isDiscount = rowType === 'discount' || rowType === 'waiver' || method.includes('discount') || method.includes('exemption') || description.includes('discount') || description.includes('waiver') || description.includes('exemption');
                if (isDiscount) {
                    let desc = description;
                    let isShop = desc.includes('shop') || desc.includes('uniform');
                    let isWaiver = rowType === 'waiver' || method.includes('exemption') || desc.includes('waiver') || desc.includes('exemption');
                    
                    const breakObj = { date: getIsoDate(l.date), desc: `${student.name} - ${desc}`, ref: student.id, amount: rowUsd };
                    if (isWaiver) {
                        if (isShop) { globalShopWaiver += rowUsd; window.vaultBreakdowns.shopWaiver.push(breakObj); }
                        else { globalTuitionWaiver += rowUsd; window.vaultBreakdowns.tuitionWaiver.push(breakObj); }
                    } else {
                        if (isShop) { globalShopDiscount += rowUsd; window.vaultBreakdowns.shopDiscount.push(breakObj); }
                        else { globalTuitionDiscount += rowUsd; window.vaultBreakdowns.tuitionDiscount.push(breakObj); }
                    }
                    
                    exceptionsLog.push({ date: getIsoDate(l.date), category: `${isShop ? 'Shop' : 'Tuition'} ${isWaiver ? 'Waiver' : 'Discount'}`, entity: student.name, desc: desc || (isWaiver ? 'System Waiver' : 'System Discount'), amount: rowUsd });
                    return; 
                }

                let breakdowns = l.breakdown && Array.isArray(l.breakdown) && l.breakdown.length > 0 ? l.breakdown : null;

                if (!breakdowns) {
                    breakdowns = [{ amt: rowUsd, desc: description || 'General Payment' }];
                    if (!isCreditBacked && description.includes('&')) {
                        unallocatedPayments += rowUsd;
                        exceptionsLog.push({ date: getIsoDate(l.date), category: 'Needs Allocation', entity: student.name, desc: description || 'Combined payment without breakdown', amount: rowUsd });
                    }
                }

                let totalBreakdownValue = breakdowns.reduce((sum, b) => sum + (parseFloat(b.amt) || parseFloat(b.amount) || 0), 0);

                breakdowns.forEach(b => {
                    let bVal = parseFloat(b.amt) || parseFloat(b.amount) || 0;
                    let ratio = totalBreakdownValue > 0 ? (bVal / totalBreakdownValue) : 0;
                    let allocatedUsd = rowUsd * ratio;
                    let cleanD = (b.desc || b.description || description || '').toLowerCase();

                    if (cleanD.includes('transport') || cleanD.includes('bus')) yields.transport += bVal;
                    if (cleanD.includes('food') || cleanD.includes('meal')) yields.food += bVal;
                    if (cleanD.includes('stationery')) yields.stationery += bVal;
                    if (cleanD.includes('textbook') || cleanD.includes('book')) yields.textbooks += bVal;

                    if (!isCreditBacked) {
                        const breakObj = {
                            date: getIsoDate(l.date),
                            desc: `${student.name} - ${cleanD}`,
                            ref: l.receipt_no || l.receiptNo,
                            method: methodLabel,
                            amount: allocatedUsd
                        };

                        if (cleanD.includes('unallocated payment')) {
                            // Skip
                        } else if (cleanD.includes('shop') || cleanD.includes('uniform') || cleanD.includes('tracksuit')) {
                            revenue.shop[methodKey] += allocatedUsd;
                            if(isOnline) window.vaultBreakdowns.shopOnline.push(breakObj); else window.vaultBreakdowns.shopCash.push(breakObj);
                        } else if (cleanD.includes('event') || cleanD.includes('trip')) {
                            revenue.events[methodKey] += allocatedUsd;
                            if(isOnline) window.vaultBreakdowns.eventOnline.push(breakObj); else window.vaultBreakdowns.eventCash.push(breakObj);
                        } else if (cleanD.includes('overpayment') || cleanD.includes('account credit') || rowType === 'overpayment') {
                            revenue.overpay[methodKey] += allocatedUsd;
                            if(isOnline) window.vaultBreakdowns.overpayOnline.push(breakObj); else window.vaultBreakdowns.overpayCash.push(breakObj);
                            window.vaultBreakdowns.overpayment.push(breakObj); 
                            if (ratio === 1) exceptionsLog.push({ date: getIsoDate(l.date), category: 'Overpayment Banked', entity: student.name, desc: cleanD, amount: allocatedUsd });
                        } else {
                            revenue.tuition[methodKey] += allocatedUsd;
                            if(isOnline) window.vaultBreakdowns.tuitionOnline.push(breakObj); else window.vaultBreakdowns.tuitionCash.push(breakObj);
                        }
                    }
                });

                if (isCreditBacked) return;
                
                // Track actual newly collected revenue within the date range
                globalPaid += rowUsd; 
                window.vaultBreakdowns.collected.push({ date: getIsoDate(l.date), desc: `${student.name} (${description})`, ref: l.receipt_no || student.id, amount: rowUsd });
            }
        });
    });

    revenue.shop.cash += shopCashFromPos;
    revenue.shop.online += shopOnlineFromPos;

    // DOM Updates
    if (document.getElementById('statTotalSt')) document.getElementById('statTotalSt').innerText = activeStudentCount;
    if (document.getElementById('statExpectedUsd')) document.getElementById('statExpectedUsd').innerText = globalBilled.toFixed(2);
    if (document.getElementById('statExpectedZig')) document.getElementById('statExpectedZig').innerText = (globalBilled * rate).toFixed(2);
    if (document.getElementById('statCollectedUsd')) document.getElementById('statCollectedUsd').innerText = globalPaid.toFixed(2);
    if (document.getElementById('statCollectedZig')) document.getElementById('statCollectedZig').innerText = (globalPaid * rate).toFixed(2);
    
    if (document.getElementById('statDebtUsd')) document.getElementById('statDebtUsd').innerText = globalDebt.toFixed(2);
    else if (document.getElementById('statLeftUsd')) document.getElementById('statLeftUsd').innerText = globalDebt.toFixed(2);
    
    if (document.getElementById('statForgivenTuition')) document.getElementById('statForgivenTuition').innerText = globalTuitionDiscount.toFixed(2);
    if (document.getElementById('statForgivenShop')) document.getElementById('statForgivenShop').innerText = globalShopDiscount.toFixed(2);
    if (document.getElementById('statWaivedTuition')) document.getElementById('statWaivedTuition').innerText = globalTuitionWaiver.toFixed(2);
    if (document.getElementById('statWaivedShop')) document.getElementById('statWaivedShop').innerText = globalShopWaiver.toFixed(2);
    
    const totalOverpaymentFromLog = exceptionsLog.filter(log => log.category.includes('Overpayment')).reduce((total, log) => total + log.amount, 0);
    globalOverpayment = totalOverpaymentFromLog; 
    
    if (document.getElementById('exceptionTuitionDiscountTotal')) document.getElementById('exceptionTuitionDiscountTotal').innerText = `$${globalTuitionDiscount.toFixed(2)}`;
    if (document.getElementById('exceptionShopDiscountTotal')) document.getElementById('exceptionShopDiscountTotal').innerText = `$${globalShopDiscount.toFixed(2)}`;
    if (document.getElementById('exceptionTuitionWaiverTotal')) document.getElementById('exceptionTuitionWaiverTotal').innerText = `$${globalTuitionWaiver.toFixed(2)}`;
    if (document.getElementById('exceptionShopWaiverTotal')) document.getElementById('exceptionShopWaiverTotal').innerText = `$${globalShopWaiver.toFixed(2)}`;
    if (document.getElementById('exceptionOverpaymentTotal')) document.getElementById('exceptionOverpaymentTotal').innerText = `$${totalOverpaymentFromLog.toFixed(2)}`;
    
    if (document.getElementById('statOverpayUsd')) document.getElementById('statOverpayUsd').innerText = globalOverpayment.toFixed(2);
    
    if (document.getElementById('vaultCashExpenses')) document.getElementById('vaultCashExpenses').innerText = `$${vaultCashExpenses.toFixed(2)}`;
    if (document.getElementById('vaultOnlineExpenses')) document.getElementById('vaultOnlineExpenses').innerText = `$${vaultOnlineExpenses.toFixed(2)}`;
    if (document.getElementById('vaultZigExpenses')) document.getElementById('vaultZigExpenses').innerText = `ZiG ${vaultZigExpenses.toFixed(2)}`;
    if (document.getElementById('vaultPayrollExpenses')) document.getElementById('vaultPayrollExpenses').innerText = `$${vaultPayrollExpenses.toFixed(2)}`;
    
    if (document.getElementById('vaultNetCash')) document.getElementById('vaultNetCash').innerText = `$${(revenue.tuition.cash + revenue.shop.cash + revenue.events.cash + revenue.overpay.cash - vaultCashExpenses).toFixed(2)}`;
    if (document.getElementById('vaultNetOnline')) document.getElementById('vaultNetOnline').innerHTML = `$${(revenue.tuition.online + revenue.shop.online + revenue.events.online + revenue.overpay.online - vaultOnlineExpenses).toFixed(2)} <br><span style="font-size: 11px; color: #e67e22; font-weight: normal;">(Includes $${revenue.overpay.online.toFixed(2)} online overpayments)</span>`;

    const fillRev = (id, val) => { if(document.getElementById(id)) document.getElementById(id).innerText = `$${val.toFixed(2)}`; };
    fillRev('vaultTuitionCash', revenue.tuition.cash); fillRev('vaultTuitionOnline', revenue.tuition.online);
    fillRev('vaultOverpayCash', revenue.overpay.cash); fillRev('vaultOverpayOnline', revenue.overpay.online);
    fillRev('vaultShopCash', revenue.shop.cash); fillRev('vaultShopOnline', revenue.shop.online);
    fillRev('vaultEventCash', revenue.events.cash); fillRev('vaultEventOnline', revenue.events.online);

    

    const totalYield = yields.transport + yields.food + yields.stationery + yields.textbooks;
    const yieldsContainer = document.getElementById('vaultYieldsContainer');
    if (yieldsContainer) {
        yieldsContainer.innerHTML = `
            <div style="background: #ffffff; border: 1px solid #e0e6ed; border-radius: 4px; padding: 10px; margin-bottom: 15px;">
                <h4 style="margin: 0 0 8px 0; font-size: 11px; color: #7f8c8d; text-transform: uppercase; border-bottom: 1px solid #eee; padding-bottom: 5px;">
                    📊 Specific Category Yields (Filtered by Date)
                </h4>
                <table style="width:100%; border-collapse: collapse; font-size: 12px; text-align: left;">
                    <tbody>
                        <tr style="border-bottom: 1px solid #f9f9f9;"><td style="padding: 6px 0; font-weight: 500; color:#2c3e50;">🚌 Transport</td><td style="text-align: right; color: #27ae60; font-weight: bold;">$${yields.transport.toFixed(2)}</td></tr>
                        <tr style="border-bottom: 1px solid #f9f9f9;"><td style="padding: 6px 0; font-weight: 500; color:#2c3e50;">🍽️ Food Program</td><td style="text-align: right; color: #27ae60; font-weight: bold;">$${yields.food.toFixed(2)}</td></tr>
                        <tr style="border-bottom: 1px solid #f9f9f9;"><td style="padding: 6px 0; font-weight: 500; color:#2c3e50;">✏️ Stationery</td><td style="text-align: right; color: #27ae60; font-weight: bold;">$${yields.stationery.toFixed(2)}</td></tr>
                        <tr style="border-bottom: 1px solid #f9f9f9;"><td style="padding: 6px 0; font-weight: 500; color:#2c3e50;">📚 Textbooks</td><td style="text-align: right; color: #27ae60; font-weight: bold;">$${yields.textbooks.toFixed(2)}</td></tr>
                    </tbody>
                    <tfoot style="border-top: 2px solid #ecf0f1;">
                        <tr><td style="padding: 8px 0; font-weight: bold; color: #2c3e50;">COMBINED YIELD</td><td style="text-align: right; color: #2c3e50; font-weight: bold;">$${totalYield.toFixed(2)}</td></tr>
                    </tfoot>
                </table>
            </div>
        `;
    }

    const paymentBody = document.getElementById('vaultPaymentDetailsBody');
    if (paymentBody) {
        const escapeCell = value => String(value ?? '')
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#39;');

        paymentDetails = paymentDetails.map(payment => {
            const methodStr = String(payment.method || '').toLowerCase();
            const descStr = String(payment.description || '').toLowerCase();
            
            const isAdvanceCredit = methodStr.includes('advance credit') || 
                                    methodStr.includes('overpayment') || 
                                    methodStr.includes('account credit') ||
                                    descStr.includes('advance credit') || 
                                    descStr.includes('overpayment');

            if (isAdvanceCredit) {
                return { ...payment, displayAmount: 0, originalAmount: payment.amount };
            }
            return { ...payment, displayAmount: payment.amount };
        });

        paymentDetails.sort((a, b) =>
            (a.occurredAt ?? Number.MAX_SAFE_INTEGER) - (b.occurredAt ?? Number.MAX_SAFE_INTEGER) ||
            String(a.receipt || '').localeCompare(String(b.receipt || ''))
        );

        if (paymentDetails.length === 0) {
            paymentBody.innerHTML = '<tr><td colspan="10" style="padding: 15px; text-align: center; color: #95a5a6;">No payments found for the selected date range.</td></tr>';
        } else {
            paymentBody.innerHTML = paymentDetails.map(payment => {
                
                let amountHtml = `$${parseFloat(payment.displayAmount).toFixed(2)}`;
                if (payment.displayAmount === 0 && payment.originalAmount > 0) {
                    amountHtml = `<span style="text-decoration: line-through; color: #95a5a6; font-size: 11px;">$${payment.originalAmount.toFixed(2)}</span><br><span style="color: #e67e22;">$0.00</span>`;
                }

                return `
                <tr style="border-bottom: 1px solid #f4f6f7;">
                    <td style="padding: 6px 4px;">${escapeCell(payment.date)}<br><small>${escapeCell(payment.time)}</small></td>
                    <td style="padding: 6px 4px; font-weight: bold; color: #2980b9;">${escapeCell(payment.studentId)}</td>
                    <td style="padding: 6px 4px;">${escapeCell(payment.studentName)}</td>
                    <td style="padding: 6px 4px;">${escapeCell(payment.grade)}</td>
                    <td style="padding: 6px 4px; color: ${payment.type === 'Overpayment' ? '#8e44ad' : '#27ae60'}; font-weight: bold;">${escapeCell(payment.type)}</td>
                    <td style="padding: 6px 4px;">${escapeCell(payment.description)}</td>
                    <td style="padding: 6px 4px;">${escapeCell(payment.method)}</td>
                    <td style="padding: 6px 4px;">${escapeCell(payment.receipt)}</td>
                    <td style="padding: 6px 4px;">${escapeCell(payment.processedBy)}</td>
                    <td style="padding: 6px 4px; text-align: right; font-weight: bold;">${amountHtml}</td>
                </tr>`;
            }).join('');
        }

        const paymentTotal = paymentDetails.reduce((total, payment) => total + (payment.displayAmount || 0), 0);
        const paymentTotalElement = document.getElementById('vaultPaymentDetailsTotal');
        if (paymentTotalElement) paymentTotalElement.innerText = `$${paymentTotal.toFixed(2)}`;
    }
        
    const tbody = document.getElementById('unifiedExceptionsTableBody');
    if (tbody) {
        tbody.innerHTML = '';
        if (exceptionsLog.length === 0) {
            tbody.innerHTML = '<tr><td colspan="5" style="text-align:center; padding: 15px; color: #95a5a6;">No waivers, discounts, or overpayments in this period.</td></tr>';
            if (document.getElementById('unifiedExceptionsTableFoot')) document.getElementById('unifiedExceptionsTableFoot').style.display = 'none';
        } else {
            exceptionsLog.sort((a, b) => new Date(b.date) - new Date(a.date));
            let totalLogValue = 0;
            exceptionsLog.forEach(log => {
                totalLogValue += log.amount;
                let colorClass = log.category.includes('Overpayment') ? '#8e44ad' : '#e67e22'; 
                tbody.innerHTML += `
                    <tr style="border-bottom: 1px solid #fdfefe;">
                        <td style="padding: 6px 4px; color: #7f8c8d;">${log.date}</td>
                        <td style="padding: 6px 4px; font-weight: bold; color: ${colorClass};">${log.category}</td>
                        <td style="padding: 6px 4px; color: #2c3e50;">${log.entity}</td>
                        <td style="padding: 6px 4px; color: #7f8c8d;">${log.desc}</td>
                        <td style="padding: 6px 4px; text-align: right; font-weight: bold; color: ${colorClass};">$${log.amount.toFixed(2)}</td>
                    </tr>`;
            });
            if (document.getElementById('unifiedExceptionsTableFoot')) document.getElementById('unifiedExceptionsTableFoot').style.display = 'table-row-group';
            if (document.getElementById('unifiedExceptionsTotal')) document.getElementById('unifiedExceptionsTotal').innerText = `$${totalLogValue.toFixed(2)}`;
        }
    }
};

// ==========================================
// Reconciliation Functions
// ==========================================





window.printReconReport = function() {
    window.calculateReconciliation(); 
    
    const periodText = document.getElementById('reconPeriod').options[document.getElementById('reconPeriod').selectedIndex].text;
    const dateStr = new Date().toLocaleDateString();
    const data = window.currentReconData || {}; 

    let logoHTML = window.settings.logoUrl ? `<img src="${window.settings.logoUrl}" style="height:60px; display:block; margin: 0 auto 10px auto;">` : '';

    let printHTML = `<html><head><title>Cash Flow Report</title><style>
        body { font-family: 'Segoe UI', Tahoma, sans-serif; padding: 30px; max-width: 700px; margin: 0 auto; color: #2c3e50;} 
        h1 { text-align: center; text-transform: uppercase; border-bottom: 2px solid #2c3e50; padding-bottom: 10px; margin-bottom: 5px; } 
        h3 { text-align: center; color: #7f8c8d; margin-top: 0; }
        .box { border: 1px solid #bdc3c7; padding: 20px; margin-top: 20px; background: #f8f9fa; font-size: 16px; border-radius: 8px; } 
        .row { display: flex; justify-content: space-between; margin-bottom: 10px; border-bottom: 1px dashed #bdc3c7; padding-bottom: 5px; }
        .sub-row { display: flex; justify-content: space-between; margin-bottom: 5px; font-size: 14px; color: #555; padding-left: 20px; }
        .zig-label { color: #27ae60; font-size: 13px; font-weight: normal; margin-left: 10px; border-left: 1px solid #ccc; padding-left: 10px; }
        .section-title { font-weight: bold; margin-top: 15px; margin-bottom: 5px; border-bottom: 2px solid #2980b9; display: inline-block; color: #2980b9; }
        .total { font-size: 18px; font-weight: bold; border-top: 2px solid #2c3e50; padding-top: 15px; margin-top: 15px; }
        .net { font-size: 20px; font-weight: bold; border-top: 3px double #2c3e50; padding-top: 15px; margin-top: 15px; color: #27ae60; }
        .highlight-drawer { background: #e8f4f8; padding: 15px; border-radius: 5px; margin-top: 15px; border-left: 4px solid #3498db; }
        .highlight-bank { background: #fdf5e6; padding: 15px; border-radius: 5px; margin-top: 10px; border-left: 4px solid #f39c12; }
    </style></head><body>
        ${logoHTML}
        <h1>${window.settings.schoolName || 'Haven Master System'}</h1>
        <h3>Official Cash Flow & Reconciliation</h3>
        <p><strong>Report Date:</strong> ${dateStr}</p>
        <p><strong>Period:</strong> ${periodText}</p>
        
        <div class="box">
            <div class="section-title">1. REVENUE (INFLOW)</div>
            
            <div class="row"><span>Tuition & Fees:</span> <strong>$${(data.tuitionCash + data.tuitionOnline).toFixed(2)}</strong></div>
            <div class="sub-row">
                <span>├─ Cash on Desk:</span> 
                <span>$${(data.tuitionCash).toFixed(2)} ${data.tuitionZigCash > 0 ? `<span class="zig-label">ZiG ${data.tuitionZigCash.toFixed(2)}</span>` : ''}</span>
            </div>
            <div class="sub-row">
                <span>└─ Online/EcoCash:</span> 
                <span>$${(data.tuitionOnline).toFixed(2)} ${data.tuitionZigOnline > 0 ? `<span class="zig-label">ZiG ${data.tuitionZigOnline.toFixed(2)}</span>` : ''}</span>
            </div>
            
            <div class="row" style="margin-top:10px;"><span>Uniforms & Shop:</span> <strong>$${(data.shopCash + data.shopOnline).toFixed(2)}</strong></div>
            <div class="sub-row">
                <span>├─ Cash on Desk:</span> 
                <span>$${(data.shopCash).toFixed(2)} ${data.shopZigCash > 0 ? `<span class="zig-label">ZiG ${data.shopZigCash.toFixed(2)}</span>` : ''}</span>
            </div>
            <div class="sub-row">
                <span>└─ Online/EcoCash:</span> 
                <span>$${(data.shopOnline).toFixed(2)} ${data.shopZigOnline > 0 ? `<span class="zig-label">ZiG ${data.shopZigOnline.toFixed(2)}</span>` : ''}</span>
            </div>

            <div class="total"><span>TOTAL GROSS REVENUE:</span> <span style="color:#2980b9;">$${(data.totalCashIn + data.totalOnlineIn).toFixed(2)}</span></div>

            <div class="section-title" style="margin-top: 25px;">2. EXPENSES (OUTFLOW)</div>
            <div class="row"><span>Total Expenses:</span> <strong>$${(data.totalExpenses).toFixed(2)}</strong></div>
            <div class="sub-row"><span>├─ Paid via Cash Drawer:</span> <span>$${(data.expCash).toFixed(2)}</span></div>
            <div class="sub-row"><span>└─ Paid via Bank/Online:</span> <span>$${(data.expOnline).toFixed(2)}</span></div>

            <div class="section-title" style="margin-top: 25px;">3. RECONCILIATION SUMMARY</div>
            
            <div class="highlight-drawer">
                <div class="row" style="border:none;"><span><strong>EXPECTED CASH IN DRAWER</strong>:</span> <span>$${data.netCashOnHand.toFixed(2)}</span></div>
                <div class="sub-row" style="font-size:12px; padding-left:0;">(Total Cash In: $${data.totalCashIn.toFixed(2)} - Cash Expenses: $${data.expCash.toFixed(2)})</div>
            </div>

            <div class="highlight-bank">
                <div class="row" style="border:none;"><span><strong>ONLINE / BANK TOTAL</strong>:</span> <span>$${data.netOnline.toFixed(2)}</span></div>
                <div class="sub-row" style="font-size:12px; padding-left:0;">(Total Online In: $${data.totalOnlineIn.toFixed(2)} - Online Expenses: $${data.expOnline.toFixed(2)})</div>
            </div>

            <div class="row net"><span>GRAND NET INCOME:</span> <span>$${data.grandTotalNet.toFixed(2)}</span></div>
            
            <div style="text-align: right; font-size: 14px; color: #7f8c8d; margin-top: 15px; border-top: 1px dashed #bdc3c7; padding-top: 10px;">
                Physical ZiG Cash: ${(data.totalZig || 0).toFixed(2)} ZiG<br>
                Online/EcoCash ZiG: ${(data.totalOnlineZig || 0).toFixed(2)} ZiG<br>
                <strong style="color:#2c3e50; font-size: 16px; display:inline-block; margin-top:4px;">Total ZiG Revenue: ${((data.totalZig || 0) + (data.totalOnlineZig || 0)).toFixed(2)} ZiG</strong>
            </div>
        </div>
        
        <div style="margin-top: 50px; display: flex; justify-content: space-between;">
            <div><p>Prepared By: ___________________</p></div>
            <div><p>Signed: ___________________</p></div>
        </div>
    </body></html>`;
    
    const printWindow = window.open('', '_blank'); 
    printWindow.document.write(printHTML); 
    printWindow.document.close();
    setTimeout(() => { printWindow.print(); printWindow.close(); }, 500);
};
//------New code Vault
      // NEW FUNCTION: Independent Quality Report logic operating inside the Admin Vault
window.runVaultQualityReport = async function() {
    // 🎯 1. Independent Date Pickers
    const sDate = document.getElementById('qrStartDate')?.value;
    const eDate = document.getElementById('qrEndDate')?.value;
    
    if (!sDate || !eDate) {
        return alert("⚠️ Please select both a Start Date and End Date for the report.");
    }

    try {
        const [ ledgerResult, expenseResult ] = await Promise.all([
            window.supabaseClient.from('student_ledger').select('*')
                .in('type', ['payment', 'overpayment'])
                .gte('date', sDate).lte('date', eDate),
            window.supabaseClient.from('expenses').select('*')
                .gte('date', sDate).lte('date', eDate)
        ]);

        if (ledgerResult.error) throw ledgerResult.error;
        if (expenseResult.error) throw expenseResult.error;

        let totalCash = 0;
        let totalCashZig = 0;
        let totalOnline = 0;
        let totalOverpayments = 0;
        let transactionsLocked = 0;

        // Process Revenue (Excluding Voided & Advance Credits)
        (ledgerResult.data || []).forEach(pay => {
            if (pay.status === 'VOID' || pay.status === 'VOIDED' || pay.is_credit_backed === true) return;
            
            const method = (pay.method || '').toLowerCase();
            const amt = parseFloat(pay.amount || 0);
            const amtZig = parseFloat(pay.zig || 0);
            const isOnline = method.includes('online') || method.includes('ecocash') || method.includes('transfer') || method.includes('zipit') || method.includes('swipe');
            
            if (isOnline) {
                totalOnline += amt;
            } else {
                totalCash += amt;
                totalCashZig += amtZig;
            }

            if (pay.type === 'overpayment') {
                totalOverpayments += amt;
            }
            transactionsLocked++;
        });

        // Process Expenses & Build HTML Log
        let expCash = 0;
        let expCashZig = 0;
        let expHTML = "";
        
        (expenseResult.data || []).forEach(exp => {
            let expData = {};
            try { expData = typeof exp.data === 'string' ? JSON.parse(exp.data) : (exp.data || {}); } catch(e) {}
            
            if (exp.status === 'VOID' || exp.status === 'VOIDED') return;
            
            const method = String(exp.payment_method || expData.payment_method || exp.method || expData.method || 'Cash').toLowerCase();
            const currency = String(exp.currency || expData.currency || 'USD').toUpperCase();
            const isOnlineExpense = method.includes('online') || method.includes('transfer') || method.includes('swipe') || method.includes('bank') || method.includes('ecocash') || method.includes('zipit');
            const amt = parseFloat(exp.amount || expData.amount || exp.total || 0);
            const desc = exp.description || expData.desc || 'Unnamed Expense';
            const date = exp.date || expData.date || 'N/A';
            
            // Deduct physical cash expenses from drawer expectation
            if (!isOnlineExpense && amt > 0) {
                if (currency === 'ZIG') {
                    expCashZig += amt;
                    expHTML += `
                        <div style="display:flex; justify-content:space-between; padding: 6px 0; border-bottom: 1px dashed #fadbd8;">
                            <span><strong>${date}</strong> - ${desc} (ZiG)</span>
                            <strong style="color:#c0392b;">-ZiG ${amt.toFixed(2)}</strong>
                        </div>`;
                } else {
                    expCash += amt;
                    expHTML += `
                        <div style="display:flex; justify-content:space-between; padding: 6px 0; border-bottom: 1px dashed #fadbd8;">
                            <span><strong>${date}</strong> - ${desc}</span>
                            <strong style="color:#c0392b;">-$${amt.toFixed(2)}</strong>
                        </div>`;
                }
                transactionsLocked++;
            }
        });

        const netExpectedCash = totalCash - expCash;
        const netExpectedZig = totalCashZig - expCashZig;

        // Update UI Elements
        document.getElementById('qrTotalCash').innerText = `$${totalCash.toFixed(2)}`;
        document.getElementById('qrTotalZig').innerText = `ZiG ${totalCashZig.toFixed(2)}`;
        document.getElementById('qrOvers').innerText = `$${totalOverpayments.toFixed(2)}`;
        document.getElementById('qrExpenses').innerText = `-$${expCash.toFixed(2)}`;
        
        document.getElementById('qrNetCash').innerText = `$${netExpectedCash.toFixed(2)}`;
        document.getElementById('qrNetZig').innerText = `ZiG ${netExpectedZig.toFixed(2)}`;
        
        const expList = document.getElementById('qrExpenseList');
        expList.innerHTML = expHTML || `<div style="color: #27ae60; font-weight: bold; text-align: center;">No cash expenses logged in this period.</div>`;

        // Store variables globally for saving & typing variance
        window.qrExpectedCash = netExpectedCash;
        window.qrExpectedZig = netExpectedZig;
        window.qrTransactionsCount = transactionsLocked;
        window.qrReportDateRange = sDate === eDate ? sDate : `${sDate} to ${eDate}`;

        // Reset actuals and trigger variance calc
        document.getElementById('qrActualCash').value = '';
        document.getElementById('qrActualZig').value = '';
        window.calcReportVariance();

    } catch (err) {
        console.error("Quality Report Error:", err);
        alert("Failed to load Quality Report: " + err.message);
    }
};

window.calcReportVariance = function() {
    const actualCash = parseFloat(document.getElementById('qrActualCash').value) || 0;
    const actualZig = parseFloat(document.getElementById('qrActualZig').value) || 0;
    
    const expectedCash = window.qrExpectedCash || 0;
    const expectedZig = window.qrExpectedZig || 0;

    const varCash = actualCash - expectedCash;
    const varZig = actualZig - expectedZig;

    const varCashEl = document.getElementById('qrVarCash');
    const varZigEl = document.getElementById('qrVarZig');

    // Color code outputs: Green for exact/over, Red for short
    varCashEl.innerText = (varCash >= 0 ? '+$' : '-$') + Math.abs(varCash).toFixed(2);
    varCashEl.style.color = varCash >= 0 ? (varCash === 0 ? '#27ae60' : '#8e44ad') : '#e74c3c';
    
    varZigEl.innerText = (varZig >= 0 ? '+ZiG ' : '-ZiG ') + Math.abs(varZig).toFixed(2);
    varZigEl.style.color = varZig >= 0 ? (varZig === 0 ? '#27ae60' : '#8e44ad') : '#e74c3c';
};

// 🎯 2. Save Reconciliation to DB
window.saveReconciliationAudit = async function() {
    const actualCashStr = document.getElementById('qrActualCash').value;
    if (actualCashStr === "") return alert("Please enter the Actual USD Cash counted in the drawer.");
    
    const expectedUsd = window.qrExpectedCash || 0;
    const actualUsd = parseFloat(actualCashStr) || 0;
    const varUsd = actualUsd - expectedUsd;
    
    const expectedZig = window.qrExpectedZig || 0;
    const actualZig = parseFloat(document.getElementById('qrActualZig').value) || 0;
    const varZig = actualZig - expectedZig;

    const cashierName = window.currentUser?.user || window.currentUser?.username || window.currentUser?.name || 'Unknown Admin';
    const reportDate = window.qrReportDateRange || new Date().toISOString().split('T')[0];

    const confirmMsg = `Save Reconciliation for ${cashierName}?\n\nDate: ${reportDate}\nExpected: $${expectedUsd.toFixed(2)}\nActual: $${actualUsd.toFixed(2)}\nVariance: $${varUsd.toFixed(2)}`;
    if (!confirm(confirmMsg)) return;

    const auditRecord = {
        date: new Date().toISOString(),
        user: cashierName,
        expected_usd: `$${expectedUsd.toFixed(2)}`,
        actual_usd: `${actualUsd}`,
        variance_usd: (varUsd >= 0 ? '+$' : '-$') + Math.abs(varUsd).toFixed(2),
        expected_zig: `ZiG ${expectedZig.toFixed(2)}`,
        actual_zig: `${actualZig}`,
        variance_zig: (varZig >= 0 ? '+ZiG ' : '-ZiG ') + Math.abs(varZig).toFixed(2),
        transactions_locked: window.qrTransactionsCount || 0,
        clean_expected_usd: expectedUsd,
        clean_actual_usd: actualUsd
    };

    try {
        const { error } = await window.supabaseClient.from('reconciliation_audits').insert([auditRecord]);
        if (error) throw error;
        
        alert("✅ Reconciliation Saved Successfully!");
        
        // Clear inputs and refresh history
        document.getElementById('qrActualCash').value = '';
        document.getElementById('qrActualZig').value = '';
        window.calcReportVariance();
        window.loadReconciliationHistory();
        
    } catch (err) {
        console.error("Failed to save audit:", err);
        alert("Failed to save reconciliation audit. " + err.message);
    }
};

// 🎯 3. History Fetcher with Filters & 4. "Investigate Short" Feature
window.loadReconciliationHistory = async function() {
    const sDate = document.getElementById('qrHistStartDate')?.value;
    const eDate = document.getElementById('qrHistEndDate')?.value;
    const cashierFilter = (document.getElementById('qrHistCashier')?.value || "").toLowerCase().trim();
    const varianceFilter = document.getElementById('qrHistVariance')?.value || "all";

    try {
        const { data, error } = await window.supabaseClient.from('reconciliation_audits')
            .select('*')
            .order('created_at', { ascending: false })
            .limit(100);

        if (error) throw error;

        const tbody = document.getElementById('qrHistoryTableBody');
        tbody.innerHTML = '';

        let recordsFound = 0;

        (data || []).forEach(row => {
            const rowDateRaw = row.date || row.created_at;
            const rowIsoDate = rowDateRaw.split('T')[0];
            const cashier = (row.user || 'Unknown').toLowerCase();
            
            // Apply Date Filters
            if (sDate && rowIsoDate < sDate) return;
            if (eDate && rowIsoDate > eDate) return;
            
            // 5. Apply Cashier Name Filter
            if (cashierFilter && !cashier.includes(cashierFilter)) return;

            // 6. Apply Variance Status Filter
            const varUsdVal = parseFloat(String(row.variance_usd).replace(/[^0-9.-]+/g,"")) || 0;
            if (varianceFilter === 'short' && varUsdVal >= 0) return;
            if (varianceFilter === 'over' && varUsdVal <= 0) return;
            if (varianceFilter === 'exact' && varUsdVal !== 0) return;

            recordsFound++;

            const isShort = varUsdVal < 0;
            const varColor = isShort ? '#e74c3c' : (varUsdVal > 0 ? '#8e44ad' : '#27ae60');
            
            // 🎯 Action Button: Let user draw the accounts for the day if there is a short (or anytime)
            const actionBtn = `<button onclick="window.viewReconciliationDay('${rowIsoDate}')" style="background:#f39c12; color:white; border:none; padding:4px 8px; font-size:10px; border-radius:3px; cursor:pointer;">${isShort ? 'Investigate Short' : 'View Day'}</button>`;

            tbody.innerHTML += `
                <tr style="border-bottom: 1px solid #ecf0f1;">
                    <td style="padding: 8px;">${rowIsoDate}</td>
                    <td style="padding: 8px; font-weight: bold; color: #34495e;">${row.user || 'Admin'}</td>
                    <td style="padding: 8px;">${row.expected_usd || '$0.00'}</td>
                    <td style="padding: 8px;">$${row.clean_actual_usd || row.actual_usd || '0.00'}</td>
                    <td style="padding: 8px; font-weight: bold; color: ${varColor};">${row.variance_usd || '$0.00'}</td>
                    <td style="padding: 8px; font-size: 11px;">${row.variance_zig || 'ZiG 0.00'}</td>
                    <td style="padding: 8px; text-align: right;">${actionBtn}</td>
                </tr>
            `;
        });

        if (recordsFound === 0) {
            tbody.innerHTML = `<tr><td colspan="7" style="text-align:center; padding: 15px; color:#e74c3c;">No audits found matching these filters.</td></tr>`;
        }

    } catch (err) {
        console.error("Failed to load history:", err);
    }
};

// Helper: Clicking "Investigate Short" sets the report dates to that day and runs it
window.viewReconciliationDay = function(dateStr) {
    if (!dateStr) return;
    document.getElementById('qrStartDate').value = dateStr;
    document.getElementById('qrEndDate').value = dateStr;
    window.runVaultQualityReport();
    
    // Optional: Scroll back to top to see the breakdown
    document.getElementById('qrStartDate').scrollIntoView({ behavior: 'smooth', block: 'center' });
};

