window.triggerUpgradeMode = function(message = "System upgrade in progress. Please leave the station to avoid data loss.") {
    // Prevent duplicate overlays if triggered multiple times
    if (document.getElementById('havenUpgradeOverlay')) return; 

    const overlay = document.createElement('div');
    overlay.id = 'havenUpgradeOverlay';
    // Max z-index to cover the login screen (which is 9000) and offline banners (10000)
    overlay.style.cssText = 'position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(44, 62, 80, 0.95); z-index: 9999999; display: flex; align-items: center; justify-content: center; font-family: "Segoe UI", Tahoma, sans-serif; backdrop-filter: blur(5px);';

    overlay.innerHTML = `
        <div style="background: white; padding: 40px; border-radius: 12px; box-shadow: 0 10px 30px rgba(0,0,0,0.5); max-width: 500px; width: 90%; text-align: center; border-top: 5px solid #f39c12;">
            <div style="font-size: 50px; margin-bottom: 10px;">⚙️</div>
            <h1 style="color: #f39c12; font-size: 28px; margin: 0 0 10px 0; text-transform: uppercase;">System Upgrade</h1>
            <p style="font-size: 16px; color: #34495e; margin-top: 0; font-weight: bold;">${message}</p>
            
            <div style="background: #fdfbf7; border: 1px dashed #f39c12; padding: 15px; border-radius: 6px; margin: 20px 0;">
                <p style="margin: 0; font-size: 14px; color: #e74c3c; font-weight: bold;">Action Required:</p>
                <p style="margin: 5px 0 0 0; font-size: 13px; color: #555;">Please do not attempt to log in or process data. Leave the station to prevent data corruption during the database update.</p>
            </div>
        </div>
    `;
    
    document.body.appendChild(overlay);
    
    // Safety protocol: Forcefully clear active session data from the frontend
    if (typeof window.logout === 'function') {
        window.logout();
    }
};

window.removeUpgradeMode = function() {
    const overlay = document.getElementById('havenUpgradeOverlay');
    if (overlay) overlay.remove();
};
