window.toggleSystemUpgrade = async function(isUpgrading) {
    try {
        console.log(`🛠️ Button clicked! Attempting to set upgrade mode to: ${isUpgrading}`);
        
        // Let the user know it's thinking
        const btnText = isUpgrading ? "Locking System..." : "Unlocking System...";
        console.log(btnText);

        // 1. Fetch current settings safely targeting only row ID 1
        const { data, error: fetchError } = await window.supabaseClient
            .from('school_data')
            .select('settings')
            .eq('id', 1) 
            .single();

        // Ignore the "No Rows Found" error (PGRST116) if the table is completely empty
        if (fetchError && fetchError.code !== 'PGRST116') {
            throw fetchError;
        }

        // 2. Modify the upgradeMode flag
        let currentSettings = (data && data.settings) ? data.settings : {};
        currentSettings.upgradeMode = isUpgrading;

        // 3. Push the update back to Supabase
        const { error: updateError } = await window.supabaseClient
            .from('school_data')
            .update({ settings: currentSettings })
            .eq('id', 1);

        if (updateError) throw updateError;

        console.log("✅ Database updated! Cloud radar will now trigger the overlay.");
        
        // 4. Force immediate UI feedback for God Mode
        if (isUpgrading) {
            alert("🚨 SYSTEM LOCKED: All other active stations are now blocked out.");
        } else {
            alert("✅ SYSTEM UNLOCKED: Teachers can now log back in.");
            // If the overlay accidentally appeared on your screen, force it to delete
            if (document.getElementById('havenUpgradeOverlay')) {
                document.getElementById('havenUpgradeOverlay').remove();
            }
        }

    } catch (error) {
        console.error("❌ Failed to toggle upgrade mode:", error);
        alert("Action Failed: Check your internet connection or Supabase permissions. Error: " + error.message);
    }
};
