window.setAppDataInteractivity = function(isReady) {
    const appContent = document.querySelector('.main-content');
    if (appContent) {
        if (isReady) {
            appContent.removeAttribute('inert');
            appContent.removeAttribute('aria-busy');
        } else {
            appContent.setAttribute('inert', '');
            appContent.setAttribute('aria-busy', 'true');
        }
    }
    const syncButton = document.getElementById('mainSyncBtn');
    if (syncButton) syncButton.disabled = !isReady;
};

window.updateLoadingStatus = function(message, progressPercent, keepVisible = false) {
    const overlay = document.getElementById('systemLoadingScreen');
    const textEl = document.getElementById('loadingStatusText');
    const barEl = document.getElementById('loadingProgressBar');
    const retryButton = document.getElementById('loadingRetryButton');
    const loginScreen = document.getElementById('loginScreen');
    const startupBanner = document.getElementById('startupSyncBanner');
    const startupMessage = document.getElementById('startupSyncMessage');
    const startupPercent = document.getElementById('startupSyncPercent');
    const startupProgress = document.getElementById('startupSyncProgress');
    const startupHint = document.getElementById('startupSyncHint');
    const startupRetryButton = document.getElementById('startupSyncRetryButton');
    if (window.loadingHideTimer) clearTimeout(window.loadingHideTimer);

    const signedIn = !!window.currentUser ||
        !!(loginScreen && (loginScreen.style.display === 'none' || getComputedStyle(loginScreen).display === 'none'));
    if (signedIn && startupBanner) {
        if (overlay) overlay.style.display = 'none';
        startupBanner.style.display = 'block';
        startupBanner.style.borderLeftColor = progressPercent >= 100 ? '#16834a' : '#2874a6';
        if (startupMessage) startupMessage.textContent = message;
        if (startupPercent) startupPercent.textContent = `${Math.max(0, Math.min(100, progressPercent))}%`;
        if (startupProgress) startupProgress.style.width = `${Math.max(0, Math.min(100, progressPercent))}%`;
        if (startupHint) {
            startupHint.textContent = progressPercent >= 100
                ? 'All school records have been downloaded and verified.'
                : 'Students, ledger, and payments are ready first. Other school data continues loading in the background.';
        }
        if (startupRetryButton) startupRetryButton.style.display = keepVisible && progressPercent < 100 ? 'flex' : 'none';
        if (progressPercent >= 100 && !keepVisible) {
            window.loadingHideTimer = setTimeout(() => {
                if (startupBanner) startupBanner.style.display = 'none';
            }, 800);
        }
        return;
    }

    if (startupBanner) startupBanner.style.display = 'none';
    
    // Ensure the overlay is visible
    if (overlay && overlay.style.display !== 'flex') {
        overlay.style.display = 'flex';
    }
    
    // Update the text and progress bar
    if (textEl) textEl.innerText = message;
    if (barEl) barEl.style.width = progressPercent + '%';
    if (retryButton && progressPercent < 100) retryButton.style.display = 'none';
    
    console.log(`[Sync] ${message} (${progressPercent}%)`);
    
    // Auto-hide the screen when it reaches 100%
    if (progressPercent >= 100 && !keepVisible) {
        if (textEl) textEl.innerText = "System Ready!";
        window.loadingHideTimer = setTimeout(() => {
            if (overlay) overlay.style.display = 'none';
        }, 800); // Wait just under a second so the user sees it finish
    }
};

window.showCloudLoadFailure = function(error) {
    console.error('Cloud data was not fully verified:', error);
    window.appDataReady = false;
    if (typeof window.setAppDataInteractivity === 'function') window.setAppDataInteractivity(false);
    window.updateLoadingStatus('Cloud data is incomplete. Check the connection and retry.', 5, true);
    const retryButton = document.getElementById('loadingRetryButton');
    if (retryButton) retryButton.style.display = 'inline-flex';
};

window.retryCloudInitialization = function() {
    const loginScreen = document.getElementById('loginScreen');
    if (loginScreen && loginScreen.style.display !== 'none') {
        return window.attemptLogin();
    }
    return window.initializeApp();
};
