// ==========================================
window.updateHeartbeatUI = function(status) {
    const pill = document.getElementById('dbConnectionPill');
    const text = document.getElementById('dbConnectionText');
    const dot = document.getElementById('dbConnectionDot');
    
    if (!pill || !text || !dot) return;
    pill.style.display = 'flex';

    if (status === 'ONLINE') {
        pill.style.background = '#27ae60'; // Secure Green
        text.innerText = "Cloud Connected";
        dot.style.animation = "pulsePing 3s infinite"; // Slow, calm pulse
    } else if (status === 'RETRYING') {
        pill.style.background = '#f39c12'; // Warning Orange
        text.innerText = "Reconnecting...";
        dot.style.animation = "pulsePing 1s infinite"; // Fast, anxious pulse
    } else if (status === 'OFFLINE') {
        pill.style.background = '#e74c3c'; // Danger Red
        text.innerText = "No Internet Connection";
        dot.style.animation = "none"; // Dead stop
    }
};

// Catch absolute internet drops (when the Wi-Fi completely disconnects)
window.addEventListener('online', () => window.updateHeartbeatUI('RETRYING'));
window.addEventListener('offline', () => window.updateHeartbeatUI('OFFLINE'));
window.updateHeartbeatUI(navigator.onLine ? 'RETRYING' : 'OFFLINE');
