window.renderAllocationsTable = function() {
    const tbody = document.getElementById('allocationsTableBody');
    if (!tbody) return;
    
    // Clear the table before drawing
    tbody.innerHTML = ''; 

    // Pull from the global allocations array
    const allocations = window.allocations || [];

    // If the roster is empty, show the default message
    if (allocations.length === 0) {
        tbody.innerHTML = '<tr><td colspan="5" style="text-align:center; padding: 20px; color:#7f8c8d;">No teachers deployed yet.</td></tr>';
        
        // Always run UI check even if empty
        if (typeof window.evaluateGodModeUI === 'function' && window.currentUser) {
            window.evaluateGodModeUI(window.currentUser);
        }
        return;
    }

    allocations.forEach((alloc, index) => {
        const tr = document.createElement('tr');
        tr.style.borderBottom = "1px solid #ecf0f1";
        tr.style.transition = "background 0.2s";

        // Support existing allocation rows while standardizing new rows on DB fields.
        const displayClass = alloc.classname || alloc.class_name || alloc.className || alloc.class || "Unknown Class";
        const displayTeacher = alloc.teachername || alloc.teacher_name || alloc.teacherName || alloc.teacher || "Unknown Teacher";
        const displayAdmin = alloc.assignedby || alloc.deployed_by || alloc.assignedBy || alloc.deployedBy || 'System';

        // 2. SMART SUBJECT CHECK & STYLING
        let displaySubject = alloc.subject && alloc.subject.trim() !== '' 
            ? `<span style="background: #e8f4f8; color: #2980b9; padding: 4px 8px; border-radius: 4px; font-weight: bold; font-size: 12px;">${alloc.subject}</span>` 
            : `<span style="color:#7f8c8d; font-style:italic;">🏫 Class Teacher</span>`;

        // 3. DRAW THE ROW
        tr.innerHTML = `
            <td style="padding: 12px;"><strong style="color: #2c3e50;">${displayClass}</strong></td>
            <td style="padding: 12px;">${displaySubject}</td>
            <td style="padding: 12px; font-weight: bold; color: #2c3e50;">👨‍🏫 ${displayTeacher}</td>
            <td style="padding: 12px;"><small style="color: #95a5a6;">${displayAdmin}</small></td>
            <td style="padding: 12px; text-align: right;">
                <button class="btn-standard btn-danger admin-edit-only" style="padding: 5px 10px; font-size: 12px;" onclick="removeAllocation(${index})">❌ Unassign</button>
            </td>
        `;
        tbody.appendChild(tr);
    });

    // 4. SECURITY CHECK: Hide 'Unassign' buttons for Level 1 Teachers
    if (typeof window.evaluateGodModeUI === 'function' && window.currentUser) {
        window.evaluateGodModeUI(window.currentUser);
    }
};

window.deployTeacherAI = async function() {
    // 1. Security Check
    const role = window.currentUser?.role || "";
    if (!(role.includes('Level 2') || role.includes('Level 3'))) {
        return alert("❌ Access Denied: Only Admins can run the AI Deployment.");
    }

    // 2. Gather Data
    const classes = window.officialClasses || [];
    const staff = window.staffAccounts || [];
    const teachers = staff.filter(s => s.type !== "None"); // Only look at teaching staff

    if (classes.length === 0) return alert("⚠️ You haven't created any Official Classes yet!");
    if (teachers.length === 0) return alert("⚠️ You need to register some teaching staff first.");

    if (!confirm("🤖 Do you want the AI to automatically assign Class/Form Teachers based on their logged qualifications?")) return;

    if (!window.allocations) window.allocations = [];
    let newAssignmentsCount = 0;
    const newAllocationsToSync = []; // Keep track of new ones for the cloud

    // 3. The AI Brain Engine
    classes.forEach(cls => {
        const className = cls.level;

        const isPrimary = className.toLowerCase().includes('grade') || className.toLowerCase().includes('ecd');
        const isSecondary = className.toLowerCase().includes('form');

        // Check if this class already has a "Class Teacher" assigned
        const existing = window.allocations.find(a => (a.classname || a.class_name || a.className) === className && a.subject === "Class Teacher");
        if (existing) return; 

        let matchedTeacher = null;

        if (isPrimary) {
            matchedTeacher = teachers.find(t => 
                t.type === "Primary" && 
                t.capabilities?.grades?.toLowerCase().includes(className.toLowerCase())
            );
        } else if (isSecondary) {
            matchedTeacher = teachers.find(t => 
                t.type === "Secondary" && 
                t.capabilities?.forms?.toLowerCase().includes(className.toLowerCase())
            );
        }

        // 4. Create the Match! (Fixed database column names)
        if (matchedTeacher) {
            const teacherName = matchedTeacher.name || matchedTeacher.username || matchedTeacher.user;
            const alreadyClassTeacher = window.allocations.some(a =>
                (a.teachername || a.teacher_name || a.teacherName) === teacherName &&
                a.subject === "Class Teacher"
            );
            if (alreadyClassTeacher) return;

            const newAlloc = {
                id: 'ALLOC-' + Date.now() + '-' + Math.random().toString(36).substring(2, 9),
                classname: className,
                subject: "Class Teacher",
                teachername: teacherName,
                assignedby: "AI System",
                timestamp: new Date().toISOString()
            };
            window.allocations.push(newAlloc);
            newAllocationsToSync.push(newAlloc);
            newAssignmentsCount++;
        }
    });

    // 5. Result Reporting
    if (newAssignmentsCount === 0) {
        return alert("🤖 AI Scan Complete: No new matches found. Check your staff qualifications to ensure they match your class names exactly.");
    }

    // 6. Save Locally
    localStorage.setItem('havenAllocations', JSON.stringify(window.allocations));

    // 7. Blast to Cloud (Supabase)
    if (navigator.onLine && typeof supabaseClient !== 'undefined' && newAllocationsToSync.length > 0) {
        try {
            const { error } = await supabaseClient.from('allocations').upsert(newAllocationsToSync);
            if (error) throw error;
            console.log(`✅ AI synced ${newAssignmentsCount} allocations to cloud.`);
        } catch (err) {
            console.error("Cloud AI sync failed:", err);
        }
    }

    // 8. Refresh UI
    if (typeof window.renderAllocationsTable === 'function') window.renderAllocationsTable();

    alert(`🤖 AI Deployment Complete! Successfully matched and assigned ${newAssignmentsCount} new Class Teachers.`);
};
