window.updateTeacherDropdowns = function() {
    const deployTeacherSelect = document.getElementById('deployTeacher');
    if (!deployTeacherSelect) return;

    deployTeacherSelect.innerHTML = '<option value="" disabled selected>Select a teacher...</option>';

    let allStaff = [];
    if (window.staffAccounts && window.staffAccounts.length > 0) allStaff = allStaff.concat(window.staffAccounts);
    if (window.teachers && window.teachers.length > 0) allStaff = allStaff.concat(window.teachers);
    if (window.staff && window.staff.length > 0) allStaff = allStaff.concat(window.staff);
    if (window.users && window.users.length > 0) allStaff = allStaff.concat(window.users);

    allStaff = allStaff.filter(staff => {
        if (!staff || staff.role === 'Student') return false;
        const type = staff.type || staff.teacherType || staff.role || '';
        return type === 'Primary' || type === 'Secondary' || Array.isArray(staff.subjects) || Boolean(staff.capabilities) || Boolean(staff.name);
    });

    if (allStaff.length === 0) {
        deployTeacherSelect.innerHTML = '<option value="" disabled selected>No teachers registered yet</option>';
        return;
    }

    const uniqueTeachers = [];
    const seenIds = new Set();

    allStaff.forEach(teacher => {
        const id = teacher.id || teacher.username || teacher.user || teacher.name;
        const name = teacher.name || teacher.fullName || teacher.user || teacher.username;
        if (name && !seenIds.has(String(id))) {
            seenIds.add(String(id));
            uniqueTeachers.push(teacher);
        }
    });

    uniqueTeachers.forEach(teacher => {
        const name = teacher.name || teacher.fullName || teacher.user || teacher.username;
        const type = teacher.type || teacher.teacherType || teacher.role || 'Staff';

        const option = document.createElement('option');
        option.value = name;
        option.dataset.teacherId = teacher.id || teacher.username || teacher.user;
        option.textContent = `👨‍🏫 ${name} (${type})`;
        deployTeacherSelect.appendChild(option);
    });
};
window.voidTransaction = async function(receiptNo, studentId) {
    // 1. Admin Verification
    const role = window.currentUser?.role || "";
    if (!role.includes('Level 3')) return alert("Access Denied: Only Chief Admins can void receipts.");

    const student = window.students.find(s => s.id === studentId);
    if (!student) return alert("Student not found.");

    // 2. Find target payment
    const payment = student.ledger.find(l => l.receiptNo === receiptNo || l.id === receiptNo);
    if (!payment) return alert("Receipt not found in ledger.");
    if (payment.status === 'VOID') return alert("Already voided.");

    // 3. Flag original as void
    payment.status = 'VOID';
    payment.desc = "[VOIDED] " + payment.desc;

    // 4. Create Reversal Audit Trail
    const reversal = {
        id: "REV-" + Date.now(),
        date: new Date().toISOString().split('T')[0],
        type: 'charge', // Opposite of payment to restore balance
        amount: payment.amount,
        desc: `Reversal Adjustment for ${receiptNo}`,
        status: 'VOID_AUDIT'
    };
    student.ledger.push(reversal);

    // 5. Cloud Sync Updates to global payments chamber
    if (typeof supabaseClient !== 'undefined') {
        await supabaseClient.from('payments').update({ status: 'VOID', notes: 'Voided by Admin' }).eq('receipt_no', receiptNo);
    }

    if (typeof window.saveData === 'function') window.saveData();
    alert(`Receipt ${receiptNo} successfully voided and audited.`);
};

