// 3. UPDATED PREVIEW FEES ENGINE (With Database Check)
// ==========================================
// UPGRADED SMART SERVICE BILLING ENGINE
// ==========================================
window.runSmartServiceBilling = async function() {
    if (!window.requireLevel3BillingAccess()) return;

    if (!window.appDataReady) {
        return window.alert('Smart Billing is blocked until student, ledger, payment, and billing data are verified.');
    }

    const mode = document.getElementById('smartBillingMode')?.value === 'execute' ? 'execute' : 'preview';
    const monthInput = document.getElementById('smartBillingMonth');
    const now = new Date();
    const currentMonthValue = monthInput?.value || `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    const [billingYear, billingMonth] = currentMonthValue.split('-').map(Number);
    if (!billingYear || !billingMonth || billingMonth < 1 || billingMonth > 12) {
        return window.alert('⚠️ Select a valid billing month before reviewing Smart Billing.');
    }
    if (monthInput && !monthInput.value) monthInput.value = currentMonthValue;

    const currentDate = new Date(billingYear, billingMonth - 1, 1);
    const currentMonthName = currentDate.toLocaleString('default', { month: 'long' });
    const currentYearNum = currentDate.getFullYear();
    const dateStr = `${currentYearNum}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const customTag = document.getElementById('smartBillingTag')?.value.trim() || '';
    const cycleValue = document.getElementById('smartBillingCycle')?.value || 'auto';
    const requestedCycle = ['monthly', 'termly', 'yearly'].includes(cycleValue) ? cycleValue : 'auto';
    const billingTag = customTag || `${currentMonthName} ${currentYearNum}`;
    
    let currentTermNum = (currentDate.getMonth() + 1 <= 4) ? 1 : (currentDate.getMonth() + 1 <= 8) ? 2 : 3;
    let termMonths = currentTermNum === 1 ? ['january', 'february', 'march', 'april'] : 
                     currentTermNum === 2 ? ['may', 'june', 'july', 'august'] : 
                     ['september', 'october', 'november', 'december'];
    
    const monthlyTag = billingTag;
    const termlyTag = customTag || `Term ${currentTermNum} ${currentYearNum}`;
    const yearlyTag = customTag || `${currentYearNum}`;

    // 🚩 Generate the unique Batch ID for this run
    const batchId = `BATCH-${currentMonthName.toUpperCase()}${currentYearNum}-${Date.now().toString().slice(-5)}`;

    const monthlyTuitionCost = parseFloat(window.localStorage.getItem('setMonthlyTuition')) || (window.settings && window.settings.monthlyTuition) || 50;
    const termlyTuitionCost = parseFloat(window.localStorage.getItem('setTermlyTuition')) || (window.settings && window.settings.termlyTuition) || 150; 
    const foodCost = parseFloat(window.localStorage.getItem('setFoodFee')) || (window.settings && window.settings.foodFee) || 20;
    const statECD = parseFloat(window.localStorage.getItem('setStatECD')) || (window.settings && window.settings.stationeryFeeECD) || 20;
    const statGrades = parseFloat(window.localStorage.getItem('setStatGrades')) || (window.settings && window.settings.stationeryFeeGrades) || 20;
    const textbookCost = parseFloat(window.localStorage.getItem('setTextbookFee')) || (window.settings && window.settings.textbookFee) || 30;

    let previewData = {
        categories: {
            Tuition: { billed: 0, coveredByCredit: 0, netOwed: 0 },
            Transport: { billed: 0, coveredByCredit: 0, netOwed: 0 },
            Food: { billed: 0, coveredByCredit: 0, netOwed: 0 },
            Stationery: { billed: 0, coveredByCredit: 0, netOwed: 0 },
            Textbooks: { billed: 0, coveredByCredit: 0, netOwed: 0 }
        },
        students: []
    };

    const getGradeTuition = (student, billingPlan) => {
        let gradeFees = [];
        if (Array.isArray(window.feeStructures)) {
            const structure = window.feeStructures.find(item => (item.id || item.grade) === student.grade);
            gradeFees = structure ? (structure.fees || structure.items || []) : [];
        }
        const termlyTuition = gradeFees.reduce((total, fee) => {
            const name = String(fee.name || fee.desc || '').toLowerCase();
            return total + ((name.includes('tuition') || name.includes('term') || name === 'fee') ? (parseFloat(fee.amount) || 0) : 0);
        }, 0);
        const configuredAmount = termlyTuition || termlyTuitionCost;
        if (billingPlan === 'monthly') return parseFloat((configuredAmount / 3).toFixed(2));
        if (billingPlan === 'yearly') return configuredAmount * 3;
        return configuredAmount;
    };

    (window.students || []).forEach(student => {
        const status = String(student.enrollmentStatus || student.enrollment_status || student.status || '').toLowerCase();
        if (status !== 'active' && status !== 'pending_payment') return; 

        const ledger = Array.isArray(student.ledger) ? student.ledger : [];
        const gradeName = (student.grade || "").toUpperCase();
        const studentPlan = (student.billing_plan || student.billingPlan || "termly").toLowerCase();
        const billingPlan = requestedCycle === 'auto' ? studentPlan : requestedCycle;

        let tBilled = 0, tPaid = 0;
        ledger.forEach(l => {
            if (l.status === 'VOID' || l.status === 'VOIDED') return;
            if (l.type === 'charge' || l.type === 'fee') tBilled += parseFloat(l.amount) || 0;
            if (['payment', 'waiver', 'discount', 'credit', 'overpayment'].includes(l.type)) tPaid += parseFloat(l.amount) || 0;
        });
        
        let trueBalance = tBilled - tPaid; 
        let availableCredit = trueBalance < 0 ? Math.abs(trueBalance) : 0;
        let studentBilledThisRun = 0;
        let creditUsedThisRun = 0;
        let studentNewChargesList = [];
        let studentTransactions = [];

        const applyServiceCharge = function(category, desc, amount, tag, frequency) {
            if (amount <= 0) return;

            const alreadyBilled = ledger.some(entry => {
                if (entry.status === 'VOID' || entry.status === 'VOIDED') return false;
                const entryDesc = (entry.description || entry.desc || '').toLowerCase();
                
                let isMatch = false;
                if (category === 'Tuition') isMatch = entryDesc.includes('tuition');
                if (category === 'Transport') isMatch = entryDesc.includes('transport');
                if (category === 'Food') isMatch = entryDesc.includes('food');
                if (category === 'Stationery') isMatch = entryDesc.includes('stationery');
                if (category === 'Textbooks') isMatch = entryDesc.includes('textbook');
                if (!isMatch) return false;

                const entryTerm = (entry.term || '').toLowerCase();
                const termMatches = entryTerm === tag.toLowerCase() || entryDesc.includes(tag.toLowerCase());

                if (frequency === 'monthly') return termMatches;
                if (frequency === 'termly') return termMatches || termMonths.some(m => entryDesc.includes(m) || entryTerm.includes(m));
                if (frequency === 'yearly') return termMatches || entry.date?.startsWith(tag);
                if (frequency === 'once-off') return true; 
                return false;
            });

            if (!alreadyBilled) {
                const transactionId = "CHG-AUTO-" + Date.now() + Math.random().toString(36).substr(2, 4);
                
                studentTransactions.push({
                    id: transactionId,
                    student_id: student.id,
                    date: dateStr,
                    type: 'charge',
                    amount: amount,
                    description: desc,
                    term: tag,
                    batch_id: batchId // 🚩 Attached the batch ID here
                });

                previewData.categories[category].billed += amount;
                studentBilledThisRun += amount;
                studentNewChargesList.push(desc);
            }
        };

        if (billingPlan === 'monthly') applyServiceCharge('Tuition', `Tuition Fee - ${monthlyTag} (Monthly)`, getGradeTuition(student, 'monthly'), monthlyTag, 'monthly');
        else if (billingPlan === 'yearly') applyServiceCharge('Tuition', `Tuition Fee - ${yearlyTag} (Yearly)`, getGradeTuition(student, 'yearly'), yearlyTag, 'yearly');
        else applyServiceCharge('Tuition', `Tuition Fee (${termlyTag})`, getGradeTuition(student, 'termly'), termlyTag, 'termly');

        const transportFare = getStudentTransportFare(student);
        if (transportFare > 0) applyServiceCharge('Transport', `Transport Service - ${monthlyTag}`, transportFare, monthlyTag, 'monthly');

        const wantsFood = String(student.food_program) === "true" || String(student.foodProgram) === "true";
        if (wantsFood) {
            let termFoodBilled = 0;
            ledger.forEach(entry => {
                if (entry.status === 'VOID' || entry.status === 'VOIDED') return;
                const entryDesc = (entry.description || entry.desc || '').toLowerCase();
                const entryTerm = (entry.term || '').toLowerCase();
                if (entry.type === 'charge' && (entryDesc.includes("food program") || entryDesc.includes("food"))) {
                    if (entryTerm.includes(termlyTag.toLowerCase()) || entryDesc.includes(termlyTag.toLowerCase()) || termMonths.some(m => entryTerm.includes(m) || entryDesc.includes(m))) {
                        termFoodBilled += parseFloat(entry.amount) || 0;
                    }
                }
            });
            const remainingFood = foodCost - termFoodBilled;
            if (remainingFood > 0) applyServiceCharge('Food', `Food Program - ${termlyTag}`, remainingFood, termlyTag, 'termly');
        }

        const wantsStat = String(student.stationery_pack) === "true";
        if (wantsStat) applyServiceCharge('Stationery', `Stationery Pack - ${yearlyTag}`, gradeName.includes("ECD") ? statECD : statGrades, yearlyTag, 'yearly');
        
        const wantsBooks = String(student.textbooks) === "true";
        if (wantsBooks) applyServiceCharge('Textbooks', `Textbook Fee (Once-Off)`, textbookCost, "Once-Off", 'once-off');

        const getServicePriority = transaction => {
            const description = transaction.description.toLowerCase();
            if (description.includes('transport') || description.includes('bus')) return 0;
            if (description.includes('tuition') || description.includes('term')) return 1;
            if (description.includes('food')) return 2;
            if (description.includes('stationery')) return 3;
            return 4;
        };
        studentTransactions.sort((a, b) => getServicePriority(a) - getServicePriority(b));
        studentTransactions.forEach(transaction => {
            const description = transaction.description.toLowerCase();
            const category = description.includes('transport') || description.includes('bus') ? 'Transport' :
                description.includes('tuition') || description.includes('term') ? 'Tuition' :
                description.includes('food') ? 'Food' :
                description.includes('stationery') ? 'Stationery' : 'Textbooks';
            const creditUsed = Math.min(transaction.amount, availableCredit);
            previewData.categories[category].coveredByCredit += creditUsed;
            creditUsedThisRun += creditUsed;
            availableCredit -= creditUsed;
        });

        if (studentBilledThisRun > 0) {
            let finalNewBalance = trueBalance + studentBilledThisRun;
            let phone = student.phone || student.guardian_phone || '';
            let waMsg = '';
            
            if (phone.length > 8) {
                waMsg = `Hello Parent of ${student.name}.\n\nThe automated billing cycle for ${monthlyTag} has run.\nCharges applied: ${studentNewChargesList.join(', ')}.\n\n`;
                if (trueBalance < 0) waMsg += `🟢 An existing overpayment of $${Math.abs(trueBalance).toFixed(2)} was used to cover these charges.\n`;
                waMsg += finalNewBalance <= 0 ? `✅ Your account is fully cleared.` : `🔴 Total outstanding balance is $${finalNewBalance.toFixed(2)}.`;
            }

            previewData.students.push({
                id: student.id,
                name: student.name,
                grossBilled: studentBilledThisRun,
                creditUsed: creditUsedThisRun,
                chargesList: studentNewChargesList,
                transactions: studentTransactions,
                newBalance: finalNewBalance,
                phone: phone,
                msg: encodeURIComponent(waMsg)
            });
        }
    });

    Object.values(previewData.categories).forEach(category => {
        category.netOwed = Math.max(0, category.billed - category.coveredByCredit);
    });

    if (previewData.students.length === 0) {
        return window.alert("✅ System Scan Complete.\n\nNo active subscriptions require billing right now.");
    }

    let totalGross = 0;
    let totalCredit = 0;
    let totalProjectedBalance = 0;
    for (let cat in previewData.categories) {
        totalGross += previewData.categories[cat].billed;
        totalCredit += previewData.categories[cat].coveredByCredit;
    }
    previewData.students.forEach(student => {
        totalProjectedBalance += student.newBalance;
    });
    const totalNetOwed = Math.max(0, totalGross - totalCredit);

    const modalHtml = `
        <div id="smartBillingPreviewModal" style="position:fixed; top:0; left:0; width:100%; height:100%; background:rgba(0,0,0,0.6); z-index:9999; display:flex; align-items:center; justify-content:center;">
            <div style="background:white; width: 1000px; max-width: 95%; max-height: 90vh; border-radius: 8px; box-shadow: 0 10px 25px rgba(0,0,0,0.2); overflow:hidden; display:flex; flex-direction:column; font-family: sans-serif;">
                <div style="background:#2c3e50; color:white; padding: 15px; display:flex; justify-content:space-between; align-items:center;">
                    <h3 style="margin:0; font-size:16px;">🤖 Smart Billing ${mode === 'preview' ? 'Simulation' : 'Execution Review'}</h3>
                    <span style="font-size:12px; background:${mode === 'preview' ? '#2980b9' : '#e67e22'}; padding:3px 6px; border-radius:4px;">${mode === 'preview' ? 'MOCK ONLY — NO LEDGER WRITES' : 'REAL RUN — CONFIRM TO WRITE'}</span>
                </div>
                
                <div style="padding: 15px; overflow-y:auto; flex:1;">
                    <p style="margin-top:0; font-size:13px;">Snapshot date: ${dateStr} (billing is simulated from day 1). Existing ledger credit is applied transport-first. ${mode === 'preview' ? 'This mock run cannot write to the database.' : 'Uncheck any student to skip them; database writes happen only after you confirm below.'}</p>
                    
                    <table style="width: 100%; border-collapse: collapse; font-size: 12px; margin-bottom: 20px;">
                        <thead style="background:#ecf0f1; position:sticky; top:0;">
                            <tr>
                                <th style="padding:8px; border-bottom:2px solid #bdc3c7;"><input type="checkbox" id="selectAllSkip" checked></th>
                                <th style="text-align:left; padding:8px; border-bottom:2px solid #bdc3c7;">Student</th>
                                <th style="text-align:left; padding:8px; border-bottom:2px solid #bdc3c7;">Charges Detected</th>
                                <th style="padding:8px; border-bottom:2px solid #bdc3c7;">Billed</th>
                                <th style="padding:8px; border-bottom:2px solid #bdc3c7;">Credit Used</th>
                                <th style="padding:8px; border-bottom:2px solid #bdc3c7;">Net New Due</th>
                                <th style="padding:8px; border-bottom:2px solid #bdc3c7;">Projected Balance</th>
                            </tr>
                        </thead>
                        <tbody>
                            ${previewData.students.map(s => `
                            <tr>
                                <td style="text-align:center; padding:8px; border-bottom:1px solid #eee;"><input type="checkbox" class="student-bill-cb" data-id="${s.id}" checked></td>
                                <td style="padding:8px; border-bottom:1px solid #eee;"><strong>${s.name}</strong><br><small style="color:#7f8c8d;">${s.id}</small></td>
                                <td style="padding:8px; border-bottom:1px solid #eee; color:#2980b9;">${s.chargesList.join(', ')}</td>
                                <td style="text-align:center; padding:8px; border-bottom:1px solid #eee; font-weight:bold;">$${s.grossBilled.toFixed(2)}</td>
                                <td style="text-align:center; padding:8px; border-bottom:1px solid #eee;">$${s.creditUsed.toFixed(2)}</td>
                                <td style="text-align:center; padding:8px; border-bottom:1px solid #eee; font-weight:bold;">$${Math.max(0, s.grossBilled - s.creditUsed).toFixed(2)}</td>
                                <td style="text-align:center; padding:8px; border-bottom:1px solid #eee; font-weight:bold;">$${Math.abs(s.newBalance).toFixed(2)} ${s.newBalance < 0 ? 'credit' : 'due'}</td>
                            </tr>`).join('')}
                        </tbody>
                    </table>
                </div>

                <div style="background:#ecf0f1; padding:15px; display:flex; justify-content:space-between; align-items:center; border-top:1px solid #bdc3c7;">
                    <div style="font-size:13px;">
                        <strong>Gross:</strong> $${totalGross.toFixed(2)} &nbsp;
                        <strong>Credit:</strong> $${totalCredit.toFixed(2)} &nbsp;
                        <strong>Net new due:</strong> $${totalNetOwed.toFixed(2)} &nbsp;
                        <strong>Projected account balance:</strong> $${Math.abs(totalProjectedBalance).toFixed(2)} ${totalProjectedBalance < 0 ? 'credit' : 'due'}
                    </div>
                    <div style="display:flex; gap:10px;">
                        <button onclick="document.getElementById('smartBillingPreviewModal').remove()" style="padding:8px 12px; border:1px solid #bdc3c7; background:white; cursor:pointer; font-weight:bold;">Cancel</button>
                        ${mode === 'execute' ? '<button id="commitBillingBtn" style="padding:8px 12px; border:none; background:#27ae60; color:white; border-radius:4px; cursor:pointer; font-weight:bold;">✅ Confirm Real Run on Checked</button>' : '<strong style="padding:8px 12px; color:#2980b9;">Mock only — no commit action</strong>'}
                    </div>
                </div>
            </div>
        </div>
    `;

    document.body.insertAdjacentHTML('beforeend', modalHtml);

    document.getElementById('selectAllSkip').addEventListener('change', function(e) {
        document.querySelectorAll('.student-bill-cb').forEach(cb => cb.checked = e.target.checked);
    });

    if (mode !== 'execute') return;

    document.getElementById('commitBillingBtn').onclick = async function() {
        if (!window.requireLevel3BillingAccess()) return;
        this.innerHTML = "⏳ Processing DB...";
        this.disabled = true;

        const checkedIds = Array.from(document.querySelectorAll('.student-bill-cb:checked')).map(cb => cb.dataset.id);
        if (checkedIds.length === 0) return document.getElementById('smartBillingPreviewModal').remove();

        let finalTransactions = [];
        let finalBalances = [];
        let finalQueue = [];

        previewData.students.forEach(s => {
            if (checkedIds.includes(s.id)) {
                finalTransactions.push(...s.transactions);
                finalBalances.push({ id: s.id, balance_owing: s.newBalance });
                if (s.msg) finalQueue.push({ name: s.name, phone: s.phone, msg: s.msg });
            }
        });

        // Safe DB Chunking Function
        const chunkArray = (arr, size) => Array.from({ length: Math.ceil(arr.length / size) }, (v, i) => arr.slice(i * size, i * size + size));

        try {
            if (!window.appDataReady || !window.currentUser) {
                throw new Error('Session or verified ledger data is no longer available. No billing records were written.');
            }
            if (!window.supabaseClient) throw new Error('Cloud database is unavailable. No billing records were written.');

            if (window.supabaseClient && finalTransactions.length > 0) {
                const transChunks = chunkArray(finalTransactions, 100);
                for (const chunk of transChunks) {
                    const { error } = await window.supabaseClient.from('student_ledger').insert(chunk);
                    if (error) throw error;
                }
            }

            if (window.supabaseClient && finalBalances.length > 0) {
                const balChunks = chunkArray(finalBalances, 100);
                for (const chunk of balChunks) {
                    const { error } = await window.supabaseClient.from('students').upsert(chunk, { onConflict: 'id' });
                    if (error) throw error;
                }
            }

            document.getElementById('smartBillingPreviewModal').remove();
            if (typeof window.initializeApp === 'function') window.initializeApp(); 
            
            if (finalQueue.length > 0) {
                let waLinks = finalQueue.map(q => 
                    `<div style="margin-bottom:8px; display:flex; justify-content:space-between; align-items:center; border-bottom:1px solid #eee; padding-bottom:5px;">
                        <span style="font-size:12px;">${q.name}</span>
                        <a href="whatsapp://send?phone=${q.phone}&text=${q.msg}" target="_blank" style="background:#25D366; color:white; padding:4px 8px; text-decoration:none; border-radius:4px; font-size:11px;">Send Alert</a>
                    </div>`
                ).join('');

                document.body.insertAdjacentHTML('beforeend', `
                    <div id="waQueueModal" style="position:fixed; top:0; left:0; width:100%; height:100%; background:rgba(0,0,0,0.6); z-index:9999; display:flex; align-items:center; justify-content:center;">
                        <div style="background:white; width: 450px; border-radius: 8px; padding: 20px;">
                            <h3 style="margin-top:0; color:#27ae60;">✅ DB Commit Successful</h3>
                            <p style="font-size:12px; color:#e74c3c; margin-bottom:10px;"><strong>Batch ID for Reversals:</strong> ${batchId}</p>
                            <h4 style="margin-bottom:10px;">📱 WhatsApp Queue (${finalQueue.length})</h4>
                            <div style="max-height:300px; overflow-y:auto; margin-bottom:15px; padding:10px; border:1px solid #ddd;">
                                ${waLinks}
                            </div>
                            <button onclick="document.getElementById('waQueueModal').remove()" style="width:100%; padding:10px; background:#34495e; color:white; border:none; cursor:pointer;">Finish</button>
                        </div>
                    </div>
                `);
            } else {
                window.alert(`✅ Smart Billing Complete!\nBatch ID: ${batchId}`);
            }
        } catch (error) {
            window.alert(`⚠️ DATABASE COMMIT FAILED.\nError: ${error.message}`);
            document.getElementById('smartBillingPreviewModal').remove();
            if (typeof window.initializeApp === 'function') window.initializeApp(); 
        }
    };
};

//--- NEW Safe Batch Reversal Engine
window.reverseSmartServiceBilling = async function() {
    if (!window.requireLevel3BillingAccess()) return;

    const batchId = window.prompt("⚠️ EMERGENCY BILLING REVERSAL ⚠️\n\nPlease enter the exact BATCH ID you wish to reverse (e.g., BATCH-OCTOBER2026-12345):");
    if (!batchId || batchId.trim() === "") return; 

    const cleanBatchId = batchId.trim();

    if (!window.supabaseClient) {
        return window.alert("❌ Database connection not found.");
    }

    try {
        const { data: charges, error: fetchError } = await window.supabaseClient
            .from('student_ledger')
            .select('*')
            .eq('batch_id', cleanBatchId)
            .neq('status', 'VOID');

        if (fetchError) throw fetchError;

        if (!charges || charges.length === 0) {
            return window.alert(`❌ No active charges found for Batch ID: ${cleanBatchId}\n\nIt may have already been reversed or the ID is incorrect.`);
        }

        let studentReversals = {};
        let totalReversed = 0;
        
        charges.forEach(charge => {
            const sid = charge.student_id;
            const amt = parseFloat(charge.amount) || 0;
            
            if (!studentReversals[sid]) studentReversals[sid] = 0;
            studentReversals[sid] += amt;
            totalReversed += amt;
        });

        const confirmReversal = window.confirm(`⚠️ CONFIRM REVERSAL\n\nFound ${charges.length} active charges tied to this batch, totaling $${totalReversed.toFixed(2)}.\n\nAre you sure you want to VOID these charges and restore the student balances?`);
        if (!confirmReversal) return;
        if (!window.requireLevel3BillingAccess()) return;

        // 1. Mark ledger entries as VOID (Using Batch ID is a safe short URL)
        const { error: voidError } = await window.supabaseClient
            .from('student_ledger')
            .update({ status: 'VOID', voided_at: new Date().toISOString() })
            .eq('batch_id', cleanBatchId);

        if (voidError) throw voidError;

        // 2. Fetch and restore student balances using safe chunking
        const studentIds = Object.keys(studentReversals);
        let students = [];
        
        const chunkArray = (arr, size) => Array.from({ length: Math.ceil(arr.length / size) }, (v, i) => arr.slice(i * size, i * size + size));
        const studentIdChunks = chunkArray(studentIds, 50);

        for (const chunk of studentIdChunks) {
            const { data: chunkData, error: stuErr } = await window.supabaseClient
                .from('students')
                .select('id, balance_owing')
                .in('id', chunk);
            if (stuErr) throw stuErr;
            students.push(...chunkData);
        }

        const balanceUpdates = students.map(student => ({
            id: student.id,
            balance_owing: (parseFloat(student.balance_owing) || 0) - (studentReversals[student.id] || 0)
        }));

        const balanceChunks = chunkArray(balanceUpdates, 100);
        for (const chunk of balanceChunks) {
            const { error: balError } = await window.supabaseClient.from('students').upsert(chunk, { onConflict: 'id' });
            if (balError) throw balError;
        }

        window.alert(`✅ Reversal Complete!\n\nSuccessfully voided $${totalReversed.toFixed(2)} across ${studentIds.length} student accounts. Vault and ledgers have been restored.`);
        if (typeof window.initializeApp === 'function') window.initializeApp(); 

    } catch (error) {
        console.error("Billing Reversal Error:", error);
        window.alert(`⚠️ NETWORK ERROR: The reversal failed to commit fully.\n\nError: ${error.message}`);
    }
};

