window.calculateProratedUpgrade = async function(studentId, oldTierCost, newTierCost) {
    if (newTierCost <= oldTierCost) {
        return alert("New tier must be more expensive to calculate an upgrade difference.");
    }

    const currentDate = new Date();
    const currentMonth = currentDate.getMonth();
    const currentYear = currentDate.getFullYear();
    
    // 1. Calculate days in the current month
    const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
    const currentDay = currentDate.getDate();
    const daysRemaining = daysInMonth - currentDay + 1; // +1 to include today

    // 2. Calculate the financial difference
    const monthlyDifference = newTierCost - oldTierCost;
    const dailyDifferenceRate = monthlyDifference / daysInMonth;
    const proratedCharge = (dailyDifferenceRate * daysRemaining).toFixed(2);

    if (confirm(`🔄 PRO-RATED UPGRADE CALCULATION\n\nDays remaining in month: ${daysRemaining}\nMonthly difference: $${monthlyDifference}\n\nApply a one-time charge of $${proratedCharge} to the student's ledger?`)) {
        
        const student = window.students.find(s => s.id === studentId);
        if (!student) return alert("Student not found.");

        const transactionId = "CHG-UPG-" + Date.now();
        const desc = `Transport Upgrade (Pro-rated for ${daysRemaining} days)`;
        const dateStr = currentDate.toISOString().split('T')[0];

        // 3. Update Local Ledger
        if (!student.ledger) student.ledger = [];
        student.ledger.push({
            id: transactionId,
            date: dateStr,
            type: 'charge',
            amount: parseFloat(proratedCharge),
            desc: desc,
            term: `${currentDate.toLocaleString('default', { month: 'long' })} ${currentYear}`
        });

        student.balanceOwing = (parseFloat(student.balanceOwing) || 0) + parseFloat(proratedCharge);
        student.transportTier = newTierCost; // Update to the new tier permanently

        // 4. Sync to Database
        try {
            if (typeof window.saveData === 'function') await window.saveData();
            
            if (typeof window.supabaseClient !== 'undefined') {
                await window.supabaseClient.from('transactions').insert([{
                    id: transactionId,
                    student_id: student.id,
                    date: dateStr,
                    type: 'charge',
                    amount: parseFloat(proratedCharge),
                    description: desc
                }]);
            }
            alert(`✅ Pro-rated charge of $${proratedCharge} applied successfully.`);
            if (typeof window.updateDashboard === 'function') window.updateDashboard();
        } catch (error) {
            console.error("Database sync failed:", error);
            alert("⚠️ Charge applied locally, but database sync failed.");
        }
    }
};
