window.updateSchoolDisplay = function() {
    try {
        if (!window.settings) {
            console.warn("⚠️ updateSchoolDisplay aborted: window.settings is empty.");
            return;
        }

        let activeSettings = window.settings;

        // 1. If it's a string (e.g. raw localStorage data), parse it
        if (typeof activeSettings === 'string') {
            activeSettings = JSON.parse(activeSettings);
            window.settings = activeSettings; // Fix it globally
        }

        // 2. If Supabase returned it wrapped in a parent object, unwrap it
        if (activeSettings.settings && activeSettings.settings.schoolName) {
            activeSettings = activeSettings.settings;
        }

        // 3. Extract the data safely
        const name = activeSettings.schoolName || "HAVEN ONLINE";
        const logo = activeSettings.logoUrl || activeSettings.logo || "";

        console.log("🏫 Applying School Name:", name);
        console.log("🖼️ Applying Logo:", logo ? "Success (Base64 found)" : "No Logo found");

        // 4. Update all Name elements
        const nameIDs = ['schoolDisplayName', 'displaySchoolName', 'schoolNameDisplay', 'headerSchoolName', 'displaySchoolNameHeader', 'hubSchoolName', 'pdSchoolName'];
        nameIDs.forEach(id => {
            document.querySelectorAll(`[id="${id}"]`).forEach(el => {
                el.innerText = name;
            });
        });

        // 5. Update all Logo elements
        const logoIDs = ['schoolLogoMain', 'schoolLogoDisplay', 'displaySchoolLogo', 'mainLogo'];
        logoIDs.forEach(id => {
            document.querySelectorAll(`[id="${id}"]`).forEach(img => {
                if (logo) {
                    img.src = logo;
                    img.style.display = 'block';
                } else {
                    img.style.display = 'none';
                }
            });
        });
        if (typeof window.renderSettingsSummary === 'function') {
            window.renderSettingsSummary(activeSettings);
        }

        // 6. Update Settings Inputs (Removes duplicate input-population code from the loader function)
        if (document.getElementById('setSchoolName')) {
            document.getElementById('setSchoolName').value = (name === "HAVEN ONLINE") ? "" : name;
        }
        if (document.getElementById('setAddress')) {
            document.getElementById('setAddress').value = activeSettings.address || "";
        }
        if (document.getElementById('setPhone')) {
            document.getElementById('setPhone').value = activeSettings.phone || "";
        }
        if (document.getElementById('setEnrollmentOpen')) {
            document.getElementById('setEnrollmentOpen').checked = !!activeSettings.enrollmentOpen;
        }

    } catch (error) {
        console.error("❌ CRASH in updateSchoolDisplay:", error);
    }
};


window.loadAndDisplaySettings = async function() {
    console.log("🔄 Loading school settings...");
    
    try {
        // 1. Attempt to fetch live data from Supabase Cloud first
        if (navigator.onLine && typeof supabaseClient !== 'undefined') {
            const { data, error } = await supabaseClient
                .from('school_data')
                .select('settings')
                .eq('id', 'master_settings') 
                .maybeSingle(); 

            if (error) {
                console.warn("Notice fetching settings:", error.message);
            }

            if (data && data.settings) {
                window.settings = typeof data.settings === 'string' ? JSON.parse(data.settings) : data.settings;
                localStorage.setItem('haven_settings', JSON.stringify(window.settings));
            }
        }

        // 2. Fallback to Local Storage if offline or cloud fetch returned empty
        if (!window.settings || Object.keys(window.settings).length === 0) {
            const localSaved = localStorage.getItem('haven_settings');
            if (localSaved) window.settings = JSON.parse(localSaved);
        }

        // 3. Trigger UI Updates
        if (window.settings) {
            if (typeof window.applyEnrollmentVisibility === 'function') window.applyEnrollmentVisibility();
            window.updateSchoolDisplay();
            console.log("✅ Settings loaded successfully into interface.");
        }
    } catch (err) {
        console.error("⚠️ Error loading settings:", err.message);
    }
};

// Auto-trigger the loading sequence when the page is fully loaded
document.addEventListener('DOMContentLoaded', () => {
    if (typeof window.loadAndDisplaySettings === 'function') {
        window.loadAndDisplaySettings();
    }
});

// Independent uniform store ledger. This data is stored in its own school_data
// row and never shares the shop inventory or financial transaction records.
window.enableInventorySelectSearch = function(select) {
    if (!select || select.multiple) return;
    let search = document.getElementById(`${select.id}Search`);
    if (!search) {
        const label = select.parentElement && select.parentElement.querySelector('label');
        const description = label ? label.textContent.trim().toLowerCase() : 'options';
        search = document.createElement('input');
        search.type = 'search';
        search.id = `${select.id}Search`;
        search.className = 'input-standard inventory-select-search';
        search.placeholder = `Type to filter ${description}`;
        search.setAttribute('aria-label', `Type to filter ${description}`);
        search.setAttribute('autocomplete', 'off');
        search.addEventListener('input', () => window.enableInventorySelectSearch(select));
        select.parentNode.insertBefore(search, select);
    }

    const query = search.value.trim().toLocaleLowerCase().split(/\s+/)
        .filter(term => term && !['the', 'a', 'an', 'of', 'for'].includes(term));
    Array.from(select.options).forEach(option => {
        const text = `${option.textContent} ${option.value}`.toLocaleLowerCase();
        option.hidden = Boolean(query.length && String(select.value) !== String(option.value) && !query.every(term => text.includes(term)));
    });
};

window.enableInventoryModuleSelectSearch = function(moduleId) {
    const module = document.getElementById(moduleId);
    if (!module) return;
    module.querySelectorAll('select').forEach(select => window.enableInventorySelectSearch(select));
};

window.storeInventory = [];
window.storeMovements = [];
window.storeReconciliations = [];
window.storeOrders = [];
window.storeDataLoaded = false;
window.storeCloudReady = false;
window.storeDataRevision = null;

const STORE_DATA_ROW_ID = 'uniform_store_inventory';
const STORE_LOCAL_KEY = 'haven_uniform_store_v1';

function storeActorName() {
    const user = window.currentUser || {};
    return String(user.name || user.user || user.username || 'Staff');
}

function canOperateUniformStore() {
    const role = window.getNormalizedRole(window.currentUser && window.currentUser.role);
    return ['Level 2', 'Level 3', 'God Mode'].includes(role);
}

function canReconcileUniformStore() {
    const role = window.getNormalizedRole(window.currentUser && window.currentUser.role);
    return role === 'Level 3';
}

function showStoreStatus(message, isError) {
    const status = document.getElementById('storeStatus');
    if (!status) return;
    status.textContent = message;
    status.style.display = 'block';
    status.style.color = isError ? '#922b21' : '#145a32';
    status.style.background = isError ? '#fdedec' : '#eafaf1';
    status.style.border = `1px solid ${isError ? '#e6b0aa' : '#abebc6'}`;
}

function escapeStoreHtml(value) {
    return String(value == null ? '' : value).replace(/[&<>"']/g, character => ({
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#39;'
    }[character]));
}

function storeItemLabel(item) {
    const description = String(item.description || '').trim();
    return `${item.category} / ${item.name}${description ? ` / ${description}` : ''} / Size ${item.size}`;
}

function storeOrderRemaining(order) {
    return Math.max(0, Number(order.quantityOrdered) - Number(order.quantityReceived || 0));
}

function updateStoreSelects() {
    const storeOptions = window.storeInventory
        .slice()
        .sort((a, b) => storeItemLabel(a).localeCompare(storeItemLabel(b)))
        .map(item => `<option value="${escapeStoreHtml(item.id)}">${escapeStoreHtml(storeItemLabel(item))} (${Number(item.quantity) || 0} available)</option>`)
        .join('');
    const issueSelect = document.getElementById('storeIssueItem');
    const reconSelect = document.getElementById('storeReconItem');
    if (issueSelect) issueSelect.innerHTML = `<option value="">Select store stock</option>${storeOptions}`;
    if (reconSelect) reconSelect.innerHTML = `<option value="">Select store stock</option>${storeOptions}`;
    const orderValue = document.getElementById('storeReceiveOrder')?.value || '';
    const openOrders = window.storeOrders.filter(order => storeOrderRemaining(order) > 0)
        .slice().sort((a, b) => String(a.orderDate).localeCompare(String(b.orderDate)));
    const receiveOrderSelect = document.getElementById('storeReceiveOrder');
    if (receiveOrderSelect) {
        receiveOrderSelect.innerHTML = `<option value="">Select an open order</option>${openOrders.map(order =>
            `<option value="${escapeStoreHtml(order.id)}">${escapeStoreHtml(storeItemLabel(order))} — ${storeOrderRemaining(order)} outstanding · ${escapeStoreHtml(order.supplier)}</option>`
        ).join('')}`;
        if (openOrders.some(order => String(order.id) === String(orderValue))) receiveOrderSelect.value = orderValue;
    }

    const shopItems = typeof window.getShopInventoryList === 'function'
        ? window.getShopInventoryList()
        : (Array.isArray(window.shopInventory) ? window.shopInventory : []);
    const shopOptions = shopItems
        .slice()
        .sort((a, b) => String(a.name || '').localeCompare(String(b.name || '')))
        .map(item => {
            const description = String(item.description || '').trim();
            const label = `${item.name || 'Unnamed item'}${description ? ` (${description})` : ''}`;
            return `<option value="${escapeStoreHtml(item.id)}">${escapeStoreHtml(label)} — ${Number(item.qty) || 0} in shop</option>`;
        })
        .join('');
    const shopSelect = document.getElementById('storeReconShopItem');
    if (shopSelect) shopSelect.innerHTML = `<option value="">Select shop stock</option>${shopOptions}`;
    window.enableInventoryModuleSelectSearch('stores');
}

window.renderStoreModule = function() {
    const inventoryRows = document.getElementById('storeInventoryRows');
    if (!inventoryRows) return;
    const today = new Date().toISOString().slice(0, 10);
    ['storeOrderDate', 'storeOrderReceiveDate'].forEach(id => {
        const input = document.getElementById(id);
        if (input && !input.value) input.value = today;
    });
    const reconciliationPanel = document.querySelector('#stores .store-chief-admin-only');
    if (reconciliationPanel) reconciliationPanel.style.display = canReconcileUniformStore() ? 'block' : 'none';

    const items = window.storeInventory.slice().sort((a, b) =>
        `${a.category} ${a.name} ${a.size}`.localeCompare(`${b.category} ${b.name} ${b.size}`)
    );
    const total = items.reduce((sum, item) => sum + (Number(item.quantity) || 0), 0);
    document.getElementById('storeUnitsTotal').textContent = String(total);
    inventoryRows.innerHTML = items.length
        ? items.map(item => `<tr style="border-bottom:1px solid #ecf0f1;">
            <td style="padding:9px;">${escapeStoreHtml(item.category)}</td>
            <td style="padding:9px;"><strong>${escapeStoreHtml(item.name)}</strong>${item.description ? `<br><small>${escapeStoreHtml(item.description)}</small>` : ''}</td>
            <td style="padding:9px;">${escapeStoreHtml(item.size)}</td>
            <td style="padding:9px; text-align:right; font-weight:bold;">${Number(item.quantity) || 0}</td>
            <td style="padding:9px; white-space:nowrap;">${canReconcileUniformStore()
                ? `<button type="button" class="btn-standard btn-primary inventory-row-action" data-item-id="${escapeStoreHtml(item.id)}" onclick="window.editStoreItem(this.dataset.itemId)">Edit</button>
                   ${Number(item.quantity) > 0 ? `<button type="button" class="btn-standard btn-dark inventory-row-action" data-item-id="${escapeStoreHtml(item.id)}" onclick="window.clearStoreItemStock(this.dataset.itemId)" style="margin-left:4px;">Clear stock</button>` : ''}
                   <button type="button" class="btn-standard btn-danger inventory-row-action" data-item-id="${escapeStoreHtml(item.id)}" onclick="window.deleteStoreItem(this.dataset.itemId)" style="margin-left:4px;">Delete</button>`
                : '<span style="color:#7f8c8d;">Restricted</span>'}</td>
        </tr>`).join('')
        : '<tr><td colspan="5" style="padding:12px; color:#7f8c8d;">No store stock recorded yet.</td></tr>';
    Array.from(inventoryRows.querySelectorAll('tr')).forEach(row => {
        row.dataset.searchText = `${row.textContent} size ${row.cells[2]?.textContent || ''}`.toLocaleLowerCase();
    });
    window.filterStoreInventory();

    const frequentItems = new Map();
    window.storeMovements.filter(movement => movement.type === 'ISSUED').forEach(movement => {
        const key = String(movement.itemId || '');
        if (key) frequentItems.set(key, (frequentItems.get(key) || 0) + 1);
    });
    const quickItems = window.storeInventory.slice().sort((a, b) =>
        (frequentItems.get(String(b.id)) || 0) - (frequentItems.get(String(a.id)) || 0) ||
        storeItemLabel(a).localeCompare(storeItemLabel(b))
    ).slice(0, 5);
    const quickContainer = document.getElementById('storeFrequentItems');
    if (quickContainer) quickContainer.innerHTML = quickItems.map(item =>
        `<button type="button" class="store-quick-button" data-item-id="${escapeStoreHtml(item.id)}" onclick="window.quickSelectStoreItem(this.dataset.itemId)" ${Number(item.quantity) <= 0 ? 'disabled' : ''}>${escapeStoreHtml(item.name)} · ${escapeStoreHtml(item.size)}</button>`
    ).join('');

    const orderRows = document.getElementById('storeOrderRows');
    if (orderRows) {
        const orderTerms = (document.getElementById('storeOrderSearch')?.value || '').trim().toLocaleLowerCase()
            .split(/\s+/).filter(term => term && !['the', 'a', 'an', 'of', 'for'].includes(term));
        const orders = window.storeOrders.filter(order => {
            const searchable = `${storeItemLabel(order)} ${order.supplier} ${order.details} ${order.orderDate}`.toLocaleLowerCase();
            return orderTerms.every(term => searchable.includes(term));
        }).slice().sort((a, b) => String(b.orderDate).localeCompare(String(a.orderDate)));
        orderRows.innerHTML = orders.length
            ? orders.map(order => {
                const remaining = storeOrderRemaining(order);
                return `<tr style="border-bottom:1px solid #ecf0f1;">
                    <td style="padding:8px;">${escapeStoreHtml(order.orderDate)}</td>
                    <td style="padding:8px;">${escapeStoreHtml(storeItemLabel(order))}</td>
                    <td style="padding:8px; text-align:right;">${Number(order.quantityOrdered) || 0}</td>
                    <td style="padding:8px; text-align:right;">${Number(order.quantityReceived) || 0}</td>
                    <td style="padding:8px; text-align:right; font-weight:bold; color:${remaining ? '#b45309' : '#15803d'};">${remaining}</td>
                    <td style="padding:8px;">${escapeStoreHtml(order.supplier)}${order.details ? `<br><small>${escapeStoreHtml(order.details)}</small>` : ''}</td>
                    <td style="padding:8px;">${remaining ? (Number(order.quantityReceived) > 0 ? 'PARTIAL' : 'OPEN') : 'RECEIVED'}</td>
                </tr>`;
            }).join('')
            : '<tr><td colspan="7" style="padding:12px; color:#7f8c8d;">No uniform orders recorded.</td></tr>';
    }

    const start = document.getElementById('storeActivityStart')?.value || '';
    const end = document.getElementById('storeActivityEnd')?.value || '';
    const query = (document.getElementById('storeActivitySearch')?.value || '').trim().toLowerCase();
    const filteredMovements = window.storeMovements.filter(movement => {
        const date = String(movement.date || '').slice(0, 10);
        const searchable = `${movement.category} ${movement.itemName} ${movement.description || ''} ${movement.size} ${movement.receiptNo} ${movement.recipientName} ${movement.supplier || ''} ${movement.actor} ${movement.note || ''}`.toLowerCase();
        return (!start || date >= start) && (!end || date <= end) && (!query || searchable.includes(query));
    }).sort((a, b) => String(b.date).localeCompare(String(a.date)));

    const movementRows = document.getElementById('storeActivityRows');
    movementRows.innerHTML = filteredMovements.length
        ? filteredMovements.map(movement => {
            const type = String(movement.type || 'RECEIVED').toUpperCase();
            const issue = type === 'ISSUED';
            const adjustment = type === 'ADJUSTMENT';
            const auditOnly = type === 'DETAILS_UPDATED' || type === 'ITEM_DELETED';
            const reference = issue
                ? `${movement.receiptNo} / ${movement.recipientName}`
                : (movement.note || 'Stock received');
            const quantity = Number(movement.quantity) || 0;
            const quantityText = auditOnly ? '—' : `${issue || quantity < 0 ? '' : '+'}${issue ? -Math.abs(quantity) : quantity}`;
            const movementColor = issue || (adjustment && quantity < 0) ? '#c0392b' : '#1e8449';
            return `<tr style="border-bottom:1px solid #ecf0f1;">
                <td style="padding:8px;">${escapeStoreHtml(new Date(movement.date).toLocaleString())}</td>
                <td style="padding:8px; color:${movementColor}; font-weight:bold;">${escapeStoreHtml(type.replace(/_/g, ' '))}</td>
                <td style="padding:8px;">${escapeStoreHtml(`${movement.category} / ${movement.itemName}${movement.description ? ` / ${movement.description}` : ''} / ${movement.size}`)}</td>
                <td style="padding:8px;">${escapeStoreHtml(reference)}</td>
                <td style="padding:8px; text-align:right; font-weight:bold; color:${movementColor};">${quantityText}</td>
                <td style="padding:8px;">${escapeStoreHtml(movement.actor)}</td>
            </tr>`;
        }).join('')
        : '<tr><td colspan="6" style="padding:12px; color:#7f8c8d;">No store activity matches these filters.</td></tr>';

    const reconciliationRows = document.getElementById('storeReconciliationRows');
    if (reconciliationRows) {
        const audits = window.storeReconciliations
            .filter(audit => (!start || String(audit.date).slice(0, 10) >= start) && (!end || String(audit.date).slice(0, 10) <= end))
            .sort((a, b) => String(b.date).localeCompare(String(a.date)));
        reconciliationRows.innerHTML = audits.length
            ? audits.map(audit => `<tr style="border-bottom:1px solid #ecf0f1;">
                <td style="padding:8px;">${escapeStoreHtml(new Date(audit.date).toLocaleString())}</td>
                <td style="padding:8px;">${escapeStoreHtml(audit.storeLabel)}</td>
                <td style="padding:8px;">${escapeStoreHtml(audit.shopLabel)}</td>
                <td style="padding:8px; text-align:right;">${Number(audit.storeQuantity) || 0}</td>
                <td style="padding:8px; text-align:right;">${Number(audit.shopQuantity) || 0}</td>
                <td style="padding:8px; text-align:right; font-weight:bold; color:${Number(audit.variance) === 0 ? '#1e8449' : '#c0392b'};">${Number(audit.variance) > 0 ? '+' : ''}${Number(audit.variance) || 0}</td>
                <td style="padding:8px;">${escapeStoreHtml(audit.actor)}</td>
            </tr>`).join('')
            : '<tr><td colspan="7" style="padding:12px; color:#7f8c8d;">No reconciliation records for this period.</td></tr>';
    }

    updateStoreSelects();
    if (window.storeReceiptMatch) updateStoreReceiptCollectionStatus();
};

window.filterStoreInventory = function() {
    const query = (document.getElementById('storeStockSearch')?.value || '').trim().toLocaleLowerCase()
        .split(/\s+/).filter(term => term && !['the', 'a', 'an', 'of', 'for'].includes(term));
    const rows = Array.from(document.querySelectorAll('#storeInventoryRows tr[data-search-text]'));
    let visible = 0;
    rows.forEach(row => {
        const matches = !query.length || query.every(term => row.dataset.searchText.includes(term));
        row.hidden = !matches;
        if (matches) visible++;
    });
    const body = document.getElementById('storeInventoryRows');
    if (!body) return;
    let emptyRow = body.querySelector('[data-no-store-match]');
    if (query && rows.length && visible === 0) {
        if (!emptyRow) {
            emptyRow = document.createElement('tr');
            emptyRow.dataset.noStoreMatch = 'true';
            emptyRow.innerHTML = '<td colspan="5" style="padding:12px; color:#7f8c8d;">No uniforms match this description or size.</td>';
            body.appendChild(emptyRow);
        }
        emptyRow.hidden = false;
    } else if (emptyRow) {
        emptyRow.hidden = true;
    }
};

window.quickSelectStoreItem = function(itemId) {
    const select = document.getElementById('storeIssueItem');
    if (!select || !window.storeInventory.some(item => String(item.id) === String(itemId) && Number(item.quantity) > 0)) {
        return showStoreStatus('That uniform is no longer available. Reload the stock list and select again.', true);
    }
    select.value = String(itemId);
    select.dispatchEvent(new Event('change', { bubbles: true }));
};

window.loadStoreData = async function() {
    if (!canOperateUniformStore()) {
        showStoreStatus('Access denied. Stock / Stores is available to admin staff only.', true);
        return;
    }
    if (window.storeDataLoading) return window.storeDataLoading;

    window.storeDataLoading = (async () => {
        window.storeCloudReady = false;
        const cached = localStorage.getItem(STORE_LOCAL_KEY);
        if (cached) {
            try {
                const localData = JSON.parse(cached);
                window.storeInventory = Array.isArray(localData.inventory) ? localData.inventory : [];
                window.storeMovements = Array.isArray(localData.movements) ? localData.movements : [];
                window.storeReconciliations = Array.isArray(localData.reconciliations) ? localData.reconciliations : [];
                window.storeOrders = Array.isArray(localData.orders) ? localData.orders : [];
                window.renderStoreModule();
            } catch (error) {
                console.error('Invalid local store cache:', error);
                showStoreStatus('The local store cache is unreadable. Cloud data will be loaded; do not make changes until loading succeeds.', true);
            }
        }

        if (!navigator.onLine || !window.supabaseClient) {
            window.storeDataLoaded = false;
            showStoreStatus('Cannot verify current store stock while offline. Reconnect and reopen this section before receiving or issuing uniforms.', true);
            return;
        }

        try {
            const { data, error } = await window.supabaseClient
                .from('school_data')
                .select('settings,last_updated')
                .eq('id', STORE_DATA_ROW_ID)
                .maybeSingle();
            if (error) throw error;

            const cloudData = data && data.settings ? data.settings : {};
            if (data && data.settings && typeof data.settings !== 'object') {
                throw new Error('The saved store record has an invalid format.');
            }
            window.storeInventory = Array.isArray(cloudData.inventory) ? cloudData.inventory : [];
            window.storeMovements = Array.isArray(cloudData.movements) ? cloudData.movements : [];
            window.storeReconciliations = Array.isArray(cloudData.reconciliations) ? cloudData.reconciliations : [];
            window.storeOrders = Array.isArray(cloudData.orders) ? cloudData.orders : [];
            window.storeDataRevision = data ? data.last_updated : null;
            window.storeDataLoaded = true;
            window.storeCloudReady = true;
            localStorage.setItem(STORE_LOCAL_KEY, JSON.stringify({
                inventory: window.storeInventory,
                movements: window.storeMovements,
                reconciliations: window.storeReconciliations,
                orders: window.storeOrders
            }));
            window.renderStoreModule();
            showStoreStatus(data
                ? 'Store stock verified from cloud.'
                : 'Store stock is verified and empty. Receive stock to begin the separate store ledger.', false);
        } catch (error) {
            window.storeDataLoaded = false;
            window.storeCloudReady = false;
            console.error('Store stock load failed:', error);
            showStoreStatus(`Could not verify store stock from cloud: ${error.message || 'Unknown database error'}. Changes are disabled to prevent using stale figures.`, true);
        }
    })();

    try {
        await window.storeDataLoading;
    } finally {
        window.storeDataLoading = null;
    }
};

async function saveStoreData() {
    if (!window.storeCloudReady || !navigator.onLine || !window.supabaseClient) {
        throw new Error('Current store stock is not verified online. Reopen Stock / Stores while connected before changing quantities.');
    }
    const now = new Date().toISOString();
    const payload = {
        id: STORE_DATA_ROW_ID,
        settings: {
            inventory: window.storeInventory,
            movements: window.storeMovements,
            reconciliations: window.storeReconciliations,
            orders: window.storeOrders
        },
        last_updated: now
    };

    let response;
    if (window.storeDataRevision) {
        let update = window.supabaseClient
            .from('school_data')
            .update({ settings: payload.settings, last_updated: now })
            .eq('id', STORE_DATA_ROW_ID)
            .eq('last_updated', window.storeDataRevision)
            .select('id');
        response = await update;
        if (response.error) throw response.error;
        if (!response.data || response.data.length !== 1) {
            window.storeCloudReady = false;
            throw new Error('Store stock changed in another session. Reload the section before trying again; no local change was saved.');
        }
    } else {
        response = await window.supabaseClient
            .from('school_data')
            .insert(payload)
            .select('id');
        if (response.error) {
            if (response.error.code === '23505') {
                window.storeCloudReady = false;
                throw new Error('Another session initialized the store ledger. Reload the section before trying again.');
            }
            throw response.error;
        }
        if (!response.data || response.data.length !== 1) {
            throw new Error('The database did not confirm the new store ledger.');
        }
    }

    window.storeDataRevision = now;
    localStorage.setItem(STORE_LOCAL_KEY, JSON.stringify({
        inventory: window.storeInventory,
        movements: window.storeMovements,
        reconciliations: window.storeReconciliations,
        orders: window.storeOrders
    }));
}

async function commitStoreChange(change) {
    const previous = JSON.stringify({
        inventory: window.storeInventory,
        movements: window.storeMovements,
        reconciliations: window.storeReconciliations,
        orders: window.storeOrders
    });
    change();
    try {
        await saveStoreData();
        window.renderStoreModule();
        showStoreStatus('Store record saved and confirmed by cloud.', false);
    } catch (error) {
        const restored = JSON.parse(previous);
        window.storeInventory = restored.inventory;
        window.storeMovements = restored.movements;
        window.storeReconciliations = restored.reconciliations;
        window.storeOrders = restored.orders || [];
        window.renderStoreModule();
        console.error('Store change was not saved:', error);
        showStoreStatus(`No store change was saved: ${error.message || 'Unknown database error'}`, true);
        throw error;
    }
}

function requireStoreWriteAccess() {
    if (!canOperateUniformStore()) {
        showStoreStatus('Access denied. Admin staff are required for store operations.', true);
        return false;
    }
    if (!window.storeDataLoaded || !window.storeCloudReady) {
        showStoreStatus('Store changes are disabled until current cloud stock has been verified.', true);
        return false;
    }
    return true;
}

window.editStoreItem = function(itemId) {
    if (!canReconcileUniformStore()) {
        return showStoreStatus('Access denied. Only the Chief Admin can edit store item details.', true);
    }
    if (!requireStoreWriteAccess()) return;
    const item = window.storeInventory.find(entry => String(entry.id) === String(itemId));
    if (!item) return showStoreStatus('Store item not found. Reload the section and try again.', true);

    document.getElementById('storeEditItemId').value = item.id;
    document.getElementById('storeEditCategory').value = item.category;
    document.getElementById('storeEditName').value = item.name;
    document.getElementById('storeEditDescription').value = item.description || '';
    document.getElementById('storeEditSize').value = item.size;
    document.getElementById('storeEditQuantity').value = item.quantity;
    document.getElementById('storeEditReason').value = '';
    document.getElementById('storeEditModal').style.display = 'flex';
};

window.closeStoreEditModal = function() {
    const modal = document.getElementById('storeEditModal');
    if (modal) modal.style.display = 'none';
};

window.saveStoreItemEdit = async function() {
    if (!canReconcileUniformStore()) {
        return showStoreStatus('Access denied. Only the Chief Admin can edit store item details.', true);
    }
    if (!requireStoreWriteAccess()) return;

    const itemId = document.getElementById('storeEditItemId').value;
    const category = document.getElementById('storeEditCategory').value.trim();
    const name = document.getElementById('storeEditName').value.trim();
    const description = document.getElementById('storeEditDescription').value.trim();
    const size = document.getElementById('storeEditSize').value.trim();
    const quantityInput = document.getElementById('storeEditQuantity').value.trim();
    const quantity = Number(quantityInput);
    const reason = document.getElementById('storeEditReason').value.trim();
    const item = window.storeInventory.find(entry => String(entry.id) === String(itemId));

    if (!item) return showStoreStatus('Store item not found. Reload the section before editing.', true);
    if (!Number.isSafeInteger(Number(item.quantity)) || Number(item.quantity) < 0) {
        return showStoreStatus('The current stock quantity is invalid. Reload the section and ask an administrator to verify it.', true);
    }
    if (!category || !name || !size) return showStoreStatus('Category, item, and size are required.', true);
    if (!quantityInput || !Number.isSafeInteger(quantity) || quantity < 0) return showStoreStatus('Available quantity must be a whole number zero or greater.', true);
    if (!reason) return showStoreStatus('Enter a reason so the item change is recorded in the audit history.', true);
    if (reason.length > 300) return showStoreStatus('The edit reason must be 300 characters or fewer.', true);

    const normalize = value => String(value).trim().toLocaleLowerCase();
    const duplicate = window.storeInventory.find(entry =>
        String(entry.id) !== String(itemId) &&
        normalize(entry.category) === normalize(category) &&
        normalize(entry.name) === normalize(name) &&
        normalize(entry.description || '') === normalize(description) &&
        normalize(entry.size) === normalize(size)
    );
    if (duplicate) return showStoreStatus('Another store record already uses this category, item, and size. Edit that record instead.', true);

    const previous = { category: item.category, name: item.name, description: item.description || '', size: item.size, quantity: Number(item.quantity) };
    const updated = { category, name, description, size, quantity };
    if (previous.category === category && previous.name === name && previous.description === description && previous.size === size && previous.quantity === quantity) {
        return showStoreStatus('No changes were made to this store item.', true);
    }
    const quantityDelta = quantity - previous.quantity;
    const detailChanges = `Category "${previous.category}" -> "${category}", item "${previous.name}" -> "${name}", description "${previous.description}" -> "${description}", size "${previous.size}" -> "${size}"`;
    const movement = {
        id: `STM-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        type: quantityDelta === 0 ? 'DETAILS_UPDATED' : 'ADJUSTMENT',
        itemId: item.id,
        category,
        itemName: name,
        description,
        size,
        quantity: quantityDelta,
        date: new Date().toISOString(),
        actor: storeActorName(),
        note: `${detailChanges}; quantity ${previous.quantity} -> ${quantity}. Reason: ${reason}`
    };

    try {
        await commitStoreChange(() => {
            Object.assign(item, updated);
            window.storeMovements.push(movement);
        });
        window.closeStoreEditModal();
    } catch (error) {
        console.error('Store item edit failed:', error);
    }
};

window.clearStoreItemStock = async function(itemId) {
    if (!canReconcileUniformStore()) {
        return showStoreStatus('Access denied. Only the Chief Admin can clear store stock.', true);
    }
    if (!requireStoreWriteAccess()) return;
    const item = window.storeInventory.find(entry => String(entry.id) === String(itemId));
    if (!item) return showStoreStatus('Store item not found. Reload the section and try again.', true);
    const quantity = Number(item.quantity);
    if (!Number.isSafeInteger(quantity) || quantity <= 0) {
        return showStoreStatus('This item has no valid stock to clear.', true);
    }
    const reason = window.prompt(`Why are you clearing ${quantity} units of ${storeItemLabel(item)}? The stock write-off will be recorded.`);
    if (reason === null) return;
    if (!reason.trim() || reason.trim().length > 300) return showStoreStatus('A clear-stock reason of 1–300 characters is required.', true);
    if (!window.confirm(`Clear ${quantity} units from active store stock? The movement history will be retained.`)) return;
    const movement = {
        id: `STM-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        type: 'ADJUSTMENT',
        itemId: item.id,
        category: item.category,
        itemName: item.name,
        description: item.description || '',
        size: item.size,
        quantity: -quantity,
        date: new Date().toISOString(),
        actor: storeActorName(),
        note: `Chief Admin cleared ${quantity} units from active store stock. Reason: ${reason.trim()}`
    };
    try {
        await commitStoreChange(() => {
            item.quantity = 0;
            window.storeMovements.push(movement);
        });
    } catch (error) {
        console.error('Store stock clear failed:', error);
    }
};

window.deleteStoreItem = async function(itemId) {
    if (!canReconcileUniformStore()) {
        return showStoreStatus('Access denied. Only the Chief Admin can delete store items.', true);
    }
    if (!requireStoreWriteAccess()) return;
    const item = window.storeInventory.find(entry => String(entry.id) === String(itemId));
    if (!item) return showStoreStatus('Store item not found. Reload the section and try again.', true);
    if (!Number.isSafeInteger(Number(item.quantity)) || Number(item.quantity) !== 0) {
        return showStoreStatus('This item still has stock. Adjust it to zero with a reason before deleting; stock cannot be silently discarded.', true);
    }

    const reason = window.prompt(`Why are you deleting ${storeItemLabel(item)}? This action will be recorded.`);
    if (reason === null) return;
    if (!reason.trim()) return showStoreStatus('A deletion reason is required.', true);
    if (reason.trim().length > 300) return showStoreStatus('The deletion reason must be 300 characters or fewer.', true);
    if (!window.confirm(`Delete ${storeItemLabel(item)} from active store stock? Its activity and reconciliation history will be retained.`)) return;

    const movement = {
        id: `STM-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        type: 'ITEM_DELETED',
        itemId: item.id,
        category: item.category,
        itemName: item.name,
        description: item.description || '',
        size: item.size,
        quantity: 0,
        date: new Date().toISOString(),
        actor: storeActorName(),
        note: `Item removed from active store stock. Reason: ${reason.trim()}`
    };
    try {
        await commitStoreChange(() => {
            window.storeInventory = window.storeInventory.filter(entry => String(entry.id) !== String(itemId));
            window.storeMovements.push(movement);
        });
    } catch (error) {
        console.error('Store item deletion failed:', error);
    }
};

function normalizeStoreReceiptKey(value) {
    return String(value || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
}

function normalizeStoreReceiptDigits(value) {
    return String(value || '').replace(/\D/g, '');
}

function getStoreReceiptMovements(match) {
    const receiptKey = normalizeStoreReceiptKey(match.receiptNo);
    const inputKey = normalizeStoreReceiptKey(match.inputValue);
    const exact = window.storeMovements.filter(movement => {
        const key = normalizeStoreReceiptKey(movement.receiptNo);
        return key === receiptKey || key === inputKey;
    });
    if (exact.length) return exact;

    const receiptDigits = normalizeStoreReceiptDigits(match.receiptNo);
    const inputDigits = normalizeStoreReceiptDigits(match.inputValue);
    const targetDigits = receiptDigits || inputDigits;
    if (!targetDigits) return [];
    const digitMatches = window.storeMovements.filter(movement =>
        normalizeStoreReceiptDigits(movement.receiptNo) === targetDigits &&
        (
            (match.studentId && String(movement.studentId || '') === String(match.studentId)) ||
            String(movement.recipientName || '').trim().toLowerCase() === String(match.studentName || '').trim().toLowerCase()
        )
    );
    const uniqueReceiptKeys = new Set(digitMatches.map(movement => normalizeStoreReceiptKey(movement.receiptNo)));
    return uniqueReceiptKeys.size === 1 ? digitMatches : [];
}

function renderStoreReceiptLookupStatus(message, color) {
    const status = document.getElementById('storeReceiptLookupStatus');
    const issueButton = document.getElementById('storeIssueBtn');
    if (status && message) {
        status.textContent = message;
        status.style.color = color || '#7f8c8d';
    }

    const match = window.storeReceiptMatch;
    if (issueButton) {
        issueButton.disabled = !match || match.inputKey !== normalizeStoreReceiptKey(document.getElementById('storeReceiptNo')?.value) || match.isCollected;
        issueButton.style.opacity = issueButton.disabled ? '0.55' : '1';
        issueButton.style.cursor = issueButton.disabled ? 'not-allowed' : 'pointer';
    }
}

function updateStoreReceiptCollectionStatus() {
    const match = window.storeReceiptMatch;
    if (!match) return;
    const priorIssues = getStoreReceiptMovements(match);
    const issuedQuantity = priorIssues.reduce((sum, movement) => sum + (Number(movement.quantity) || 0), 0);
    const expectedQuantity = Number(match.expectedQuantity) || 0;
    const studentDisplay = `${match.studentName}${match.studentId ? ` (${match.studentId})` : ''}`;
    match.issuedQuantity = issuedQuantity;
    match.isCollected = expectedQuantity > 0
        ? issuedQuantity >= expectedQuantity
        : priorIssues.length > 0;

    let message;
    let color;
    if (match.isCollected) {
        message = `COLLECTED — ${studentDisplay}; ${issuedQuantity} unit(s) issued.`;
        color = '#1e8449';
    } else if (issuedQuantity > 0) {
        message = `PARTIALLY COLLECTED — ${studentDisplay}; ${issuedQuantity}${expectedQuantity ? ` of ${expectedQuantity}` : ''} unit(s) issued.`;
        color = '#b9770e';
    } else {
        message = `VERIFIED — ${studentDisplay}; not yet collected.`;
        color = '#1e8449';
    }
    if (match.expectedQuantity > 0 && !match.isCollected) {
        message += ` ${Math.max(0, expectedQuantity - issuedQuantity)} unit(s) remain on the receipt.`;
    }
    renderStoreReceiptLookupStatus(message, color);
}

window.storeReceiptMatch = null;
window.storeReceiptLookupRequest = 0;
window.lookupStoreReceipt = async function(rawValue) {
    const requestId = ++window.storeReceiptLookupRequest;
    const inputValue = String(rawValue || '').trim();
    const inputKey = normalizeStoreReceiptKey(inputValue);
    const studentNameInput = document.getElementById('storeStudentName');
    const studentIdInput = document.getElementById('storeStudentId');
    window.storeReceiptMatch = null;
    if (studentNameInput) studentNameInput.value = '';
    if (studentIdInput) studentIdInput.value = '';
    if (!canOperateUniformStore()) {
        renderStoreReceiptLookupStatus('Access denied. Admin staff are required to look up store receipts.', '#922b21');
        return;
    }
    renderStoreReceiptLookupStatus('Searching receipts…', '#2874a6');

    if (inputKey.length < 3) {
        renderStoreReceiptLookupStatus('Enter at least 3 receipt characters to search.', '#7f8c8d');
        return;
    }
    if (!navigator.onLine || !window.supabaseClient) {
        renderStoreReceiptLookupStatus('Receipt lookup needs an active cloud connection. No issue can be recorded offline.', '#922b21');
        return;
    }

    try {
        await window.loadStoreData();
        if (requestId !== window.storeReceiptLookupRequest) return;
        if (!window.storeCloudReady) {
            renderStoreReceiptLookupStatus('Could not verify store collection history. Reopen Stock / Stores while online.', '#922b21');
            return;
        }

        const pattern = `%${Array.from(inputKey).join('%')}%`;
        const [transactionResult, paymentResult, preReceiptResult] = await Promise.all([
            window.supabaseClient.from('transactions').select('*').ilike('receipt_no', pattern).limit(1000),
            window.supabaseClient.from('payments').select('*').ilike('receipt_no', pattern).limit(1000),
            window.supabaseClient.from('pre_enrollment_receipts').select('*').ilike('receipt_no', pattern).limit(1000)
        ]);
        if (requestId !== window.storeReceiptLookupRequest) return;
        const failedLookup = [transactionResult, paymentResult, preReceiptResult].find(result => result.error);
        if (failedLookup) throw failedLookup.error;

        const records = [
            ...(transactionResult.data || []).map(record => ({ ...record, _receiptSource: 'transaction' })),
            ...(paymentResult.data || []).map(record => ({ ...record, _receiptSource: 'payment' })),
            ...(preReceiptResult.data || []).map(record => ({ ...record, _receiptSource: 'pre-enrollment' }))
        ];
        const receiptRecords = records.filter(record =>
            normalizeStoreReceiptKey(record.receipt_no || record.receiptNo || record.receipt_number) === inputKey ||
            (
                normalizeStoreReceiptDigits(inputValue) &&
                normalizeStoreReceiptDigits(record.receipt_no || record.receiptNo || record.receipt_number) === normalizeStoreReceiptDigits(inputValue)
            )
        );
        const viableRecords = receiptRecords.filter(record => {
            if (record._receiptSource === 'pre-enrollment' && !hasPreEnrollmentUniformCharge(record)) return false;
            const category = String(record.category || '').toLowerCase();
            const type = String(record.type || '').toLowerCase();
            const description = String(record.description || record.notes || record.item || '').toLowerCase();
            const hasCart = Boolean(record.cartdetails || record.cart_details);
            return category.includes('shop') || category.includes('uniform') ||
                type.includes('shop sale') || hasCart || description.includes('uniform purchase');
        });
        const activeRecords = viableRecords.filter(record =>
            !['VOID', 'VOIDED', 'PENDING', 'UNPAID', 'FAILED', 'CANCELLED', 'CANCELED'].includes(String(record.status || '').toUpperCase())
        );

        if (viableRecords.length && !activeRecords.length) {
            const hasVoided = viableRecords.some(record => ['VOID', 'VOIDED'].includes(String(record.status || '').toUpperCase()));
            renderStoreReceiptLookupStatus(
                hasVoided ? 'This receipt is voided. Uniforms cannot be issued against it.' : 'This receipt is not paid or is not in a valid state. Uniforms cannot be issued against it.',
                '#922b21'
            );
            return;
        }
        if (!activeRecords.length) {
            renderStoreReceiptLookupStatus('No matching Shop / Uniform receipt was found. Check the receipt number.', '#922b21');
            return;
        }

        const distinctReceiptKeys = new Set(activeRecords.map(record =>
            normalizeStoreReceiptKey(record.receipt_no || record.receiptNo || record.receipt_number)
        ));
        if (distinctReceiptKeys.size !== 1) {
            renderStoreReceiptLookupStatus('More than one receipt matches those digits. Enter the full receipt number to avoid selecting the wrong student.', '#922b21');
            return;
        }

        const receiptNo = String(activeRecords[0].receipt_no || activeRecords[0].receiptNo || activeRecords[0].receipt_number || '').trim();
        const studentIds = Array.from(new Set(activeRecords
            .map(record => String(record.student_id || record.pre_student_id || '').trim())
            .filter(id => id && !['WALK-IN', 'WALK IN', '0'].includes(id.toUpperCase()))
        ));
        if (studentIds.length > 1) {
            renderStoreReceiptLookupStatus('The receipt records point to different students. Ask an administrator to verify this receipt.', '#922b21');
            return;
        }
        const studentId = studentIds[0] || '';
        const nameCandidates = Array.from(new Set(activeRecords
            .map(record => String(record.student_name || record.name || '').trim())
            .filter(name => name && !['walk-in', 'walk in', 'unknown student'].includes(name.toLowerCase()))
        ));
        if (nameCandidates.length > 1) {
            renderStoreReceiptLookupStatus('The receipt records contain conflicting student names. Ask an administrator to verify the receipt.', '#922b21');
            return;
        }
        let studentName = nameCandidates[0] || '';
        const localStudent = studentId && (window.students || []).find(student => String(student.id) === studentId);
        const preStudent = studentId && (window.preStudents || []).find(student => String(student.id) === studentId);
        studentName = studentName || localStudent?.name || preStudent?.name || '';

        if (!studentName && studentId) {
            const isPreEnrollment = activeRecords.some(record => record.pre_student_id);
            const studentTable = isPreEnrollment ? 'pre_enrollments' : 'students';
            const { data: studentRecord, error } = await window.supabaseClient
                .from(studentTable)
                .select('id,name')
                .eq('id', studentId)
                .maybeSingle();
            if (requestId !== window.storeReceiptLookupRequest) return;
            if (error) throw error;
            studentName = String(studentRecord?.name || '').trim();
        }
        if (!studentName) {
            renderStoreReceiptLookupStatus('Receipt found, but its student name could not be verified. No issue can be recorded.', '#922b21');
            return;
        }

        let expectedQuantity = 0;
        for (const record of activeRecords) {
            expectedQuantity = Math.max(expectedQuantity, Number.parseInt(record.qty, 10) || 0);
            let cart = record.cartdetails || record.cart_details;
            if (typeof cart === 'string') {
                try {
                    cart = JSON.parse(cart);
                } catch (error) {
                    console.warn('Could not read receipt cart quantities:', error);
                    cart = [];
                }
            }
            if (!Array.isArray(cart)) continue;
            expectedQuantity = Math.max(expectedQuantity, cart.reduce((sum, item) =>
                sum + (Number.parseInt(item.cartQty || item.qty || item.quantity, 10) || 0), 0
            ));
        }

        window.storeReceiptMatch = {
            inputKey,
            inputValue,
            receiptNo,
            studentId,
            studentName,
            expectedQuantity
        };
        if (studentNameInput) studentNameInput.value = studentName;
        if (studentIdInput) studentIdInput.value = studentId;
        updateStoreReceiptCollectionStatus();
    } catch (error) {
        if (requestId !== window.storeReceiptLookupRequest) return;
        console.error('Receipt lookup failed:', error);
        renderStoreReceiptLookupStatus(`Receipt lookup failed: ${error.message || 'Cloud error'}. No issue can be recorded until it is verified.`, '#922b21');
    }
};

let storeReceiptLookupTimer = null;
const storeReceiptInput = document.getElementById('storeReceiptNo');
if (storeReceiptInput) {
    storeReceiptInput.addEventListener('input', () => {
        clearTimeout(storeReceiptLookupTimer);
        window.storeReceiptLookupRequest++;
        const inputValue = storeReceiptInput.value;
        window.storeReceiptMatch = null;
        document.getElementById('storeStudentName').value = '';
        document.getElementById('storeStudentId').value = '';
        renderStoreReceiptLookupStatus('Searching receipts…', '#2874a6');
        storeReceiptLookupTimer = setTimeout(() => window.lookupStoreReceipt(inputValue), 350);
    });
}
renderStoreReceiptLookupStatus('Receipt is checked as you type. Letter case, spaces, and hyphens do not matter.', '#7f8c8d');

window.receiveStoreStock = async function() {
    if (!requireStoreWriteAccess()) return;
    const category = document.getElementById('storeCategory').value.trim();
    const name = document.getElementById('storeItemName').value.trim();
    const description = document.getElementById('storeItemDescription').value.trim();
    const size = document.getElementById('storeItemSize').value.trim();
    const quantity = Number(document.getElementById('storeReceiveQty').value);
    const supplier = document.getElementById('storeReceiveSupplier').value.trim();
    if (!category || !name || !size) return showStoreStatus('Enter category, item, and size before receiving stock.', true);
    if (!Number.isSafeInteger(quantity) || quantity <= 0) return showStoreStatus('Quantity received must be a whole number greater than zero.', true);
    if (!supplier) return showStoreStatus('Enter the supplier name before receiving stock.', true);

    const normalized = value => String(value).trim().toLocaleLowerCase();
    const item = window.storeInventory.find(entry =>
        normalized(entry.category) === normalized(category) &&
        normalized(entry.name) === normalized(name) &&
        normalized(entry.description || '') === normalized(description) &&
        normalized(entry.size) === normalized(size)
    );
    if (item && !Number.isSafeInteger(Number(item.quantity) + quantity)) {
        return showStoreStatus('The resulting stock quantity is outside the supported range.', true);
    }
    const target = item || {
        id: `STORE-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        category,
        name,
        description,
        size,
        quantity: 0
    };
    const movement = {
        id: `STM-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        type: 'RECEIVED',
        itemId: target.id,
        category: target.category,
        itemName: target.name,
        description: target.description || '',
        size: target.size,
        quantity,
        date: new Date().toISOString(),
        actor: storeActorName(),
        supplier,
        note: `Stock received from ${supplier}`
    };
    try {
        await commitStoreChange(() => {
            if (!item) window.storeInventory.push(target);
            target.quantity = Number(target.quantity) + quantity;
            window.storeMovements.push(movement);
        });
        ['storeItemName', 'storeItemDescription', 'storeItemSize', 'storeReceiveQty', 'storeReceiveSupplier']
            .forEach(id => { document.getElementById(id).value = ''; });
    } catch (error) {
        console.error('Stock receipt was not completed:', error);
        showStoreStatus(`Stock receipt was not completed: ${error.message || 'Unknown database error'}`, true);
    }
};

window.createStoreOrder = async function() {
    if (!requireStoreWriteAccess()) return;
    const category = document.getElementById('storeOrderCategory').value.trim();
    const name = document.getElementById('storeOrderName').value.trim();
    const description = document.getElementById('storeOrderDescription').value.trim();
    const size = document.getElementById('storeOrderSize').value.trim();
    const quantity = Number(document.getElementById('storeOrderQuantity').value);
    const orderDate = document.getElementById('storeOrderDate').value;
    const supplier = document.getElementById('storeOrderSupplier').value.trim();
    const details = document.getElementById('storeOrderDetails').value.trim();
    const today = new Date().toISOString().slice(0, 10);
    if (!category || !name || !size) return showStoreStatus('Category, item, and size are required for an order.', true);
    if (!Number.isSafeInteger(quantity) || quantity <= 0) return showStoreStatus('Order quantity must be a whole number greater than zero.', true);
    if (!orderDate || Number.isNaN(Date.parse(`${orderDate}T00:00:00`))) return showStoreStatus('Select a valid order date.', true);
    if (orderDate > today) return showStoreStatus('Order date cannot be in the future.', true);
    if (!supplier) return showStoreStatus('Supplier name is required for an order.', true);
    const order = {
        id: `STO-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        category,
        name,
        description,
        size,
        quantityOrdered: quantity,
        quantityReceived: 0,
        orderDate,
        supplier,
        details,
        createdAt: new Date().toISOString(),
        createdBy: storeActorName()
    };
    try {
        await commitStoreChange(() => window.storeOrders.push(order));
        ['storeOrderCategory', 'storeOrderName', 'storeOrderDescription', 'storeOrderSize', 'storeOrderQuantity', 'storeOrderSupplier', 'storeOrderDetails']
            .forEach(id => { document.getElementById(id).value = ''; });
    } catch (error) {
        console.error('Uniform stock order was not saved:', error);
    }
};

window.receiveStoreOrder = async function() {
    if (!requireStoreWriteAccess()) return;
    const orderId = document.getElementById('storeReceiveOrder').value;
    const order = window.storeOrders.find(item => String(item.id) === String(orderId));
    const quantity = Number(document.getElementById('storeOrderReceiveQty').value);
    const supplier = document.getElementById('storeOrderReceiveSupplier').value.trim();
    const receivedDate = document.getElementById('storeOrderReceiveDate').value;
    if (!order) return showStoreStatus('Select an open uniform order before receiving stock.', true);
    const remaining = storeOrderRemaining(order);
    if (!Number.isSafeInteger(quantity) || quantity <= 0) return showStoreStatus('Received quantity must be a whole number greater than zero.', true);
    if (quantity > remaining) return showStoreStatus(`Only ${remaining} unit(s) remain outstanding on this order.`, true);
    if (!supplier) return showStoreStatus('Record the supplier name at receipt.', true);
    const today = new Date().toISOString().slice(0, 10);
    if (!receivedDate || Number.isNaN(Date.parse(`${receivedDate}T00:00:00`))) return showStoreStatus('Select a valid received date.', true);
    if (receivedDate > today) return showStoreStatus('Received date cannot be in the future.', true);

    const normalized = value => String(value || '').trim().toLocaleLowerCase();
    const item = window.storeInventory.find(entry =>
        normalized(entry.category) === normalized(order.category) &&
        normalized(entry.name) === normalized(order.name) &&
        normalized(entry.description) === normalized(order.description) &&
        normalized(entry.size) === normalized(order.size)
    );
    if (item && (!Number.isSafeInteger(Number(item.quantity)) || !Number.isSafeInteger(Number(item.quantity) + quantity))) {
        return showStoreStatus('The resulting stock quantity is outside the supported range.', true);
    }
    const target = item || {
        id: `STORE-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        category: order.category,
        name: order.name,
        description: order.description || '',
        size: order.size,
        quantity: 0
    };
    const receivedTotal = Number(order.quantityReceived || 0) + quantity;
    if (!Number.isSafeInteger(receivedTotal) || receivedTotal > Number(order.quantityOrdered)) {
        return showStoreStatus('The received quantity would exceed the valid order balance.', true);
    }
    const movement = {
        id: `STM-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        type: 'RECEIVED',
        orderId: order.id,
        itemId: target.id,
        category: target.category,
        itemName: target.name,
        description: target.description || '',
        size: target.size,
        quantity,
        date: new Date(`${receivedDate}T12:00:00`).toISOString(),
        actor: storeActorName(),
        supplier,
        note: `Order ${order.id}: ${quantity} received from ${supplier}; ${Number(order.quantityOrdered) - receivedTotal} outstanding`
    };
    try {
        await commitStoreChange(() => {
            if (!item) window.storeInventory.push(target);
            target.quantity = Number(target.quantity) + quantity;
            order.quantityReceived = receivedTotal;
            window.storeMovements.push(movement);
        });
        ['storeOrderReceiveQty', 'storeOrderReceiveSupplier'].forEach(id => { document.getElementById(id).value = ''; });
    } catch (error) {
        console.error('Uniform order receipt was not saved:', error);
    }
};

window.issueStoreUniform = async function() {
    if (!requireStoreWriteAccess()) return;
    const receiptNo = document.getElementById('storeReceiptNo').value.trim();
    const receiptMatch = window.storeReceiptMatch;
    if (!receiptMatch || receiptMatch.inputKey !== normalizeStoreReceiptKey(receiptNo)) {
        return showStoreStatus('Verify the receipt and student before issuing any uniform.', true);
    }
    if (receiptMatch.isCollected) {
        return showStoreStatus('This receipt is already fully collected. Check the activity log before proceeding.', true);
    }
    const recipientName = receiptMatch.studentName;
    const itemId = document.getElementById('storeIssueItem').value;
    const quantity = Number(document.getElementById('storeIssueQty').value);
    if (!receiptNo || !recipientName || !itemId) return showStoreStatus('Receipt number, recipient name, and a stock item are required.', true);
    if (!Number.isSafeInteger(quantity) || quantity <= 0) return showStoreStatus('Quantity issued must be a whole number greater than zero.', true);
    if (receiptMatch.expectedQuantity > 0 && quantity > receiptMatch.expectedQuantity - receiptMatch.issuedQuantity) {
        return showStoreStatus(`This receipt has only ${Math.max(0, receiptMatch.expectedQuantity - receiptMatch.issuedQuantity)} unit(s) remaining to collect.`, true);
    }

    const item = window.storeInventory.find(entry => String(entry.id) === String(itemId));
    if (!item) return showStoreStatus('The selected store item no longer exists. Reload the section and try again.', true);
    if (!Number.isSafeInteger(Number(item.quantity)) || Number(item.quantity) < 0) {
        return showStoreStatus('The selected store stock has an invalid quantity. Reload the section and ask an administrator to verify it.', true);
    }
    if (Number(item.quantity) < quantity) {
        return showStoreStatus(`Insufficient store stock for ${storeItemLabel(item)}. Available: ${Number(item.quantity) || 0}; requested: ${quantity}.`, true);
    }
    const movement = {
        id: `STM-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        type: 'ISSUED',
        itemId: item.id,
        category: item.category,
        itemName: item.name,
        description: item.description || '',
        size: item.size,
        quantity,
        receiptNo: receiptMatch.receiptNo,
        studentId: receiptMatch.studentId,
        recipientName,
        date: new Date().toISOString(),
        actor: storeActorName()
    };
    try {
        await commitStoreChange(() => {
            item.quantity = Number(item.quantity) - quantity;
            window.storeMovements.push(movement);
        });
        document.getElementById('storeIssueQty').value = '';
    } catch (error) {
        console.error('Uniform issue was not completed:', error);
        showStoreStatus(`Uniform issue was not completed: ${error.message || 'Unknown database error'}`, true);
    }
};

window.reconcileStoreAndShop = async function() {
    if (!canReconcileUniformStore()) {
        showStoreStatus('Access denied. Only the Chief Admin can reconcile shop and store stock.', true);
        return;
    }
    if (!requireStoreWriteAccess()) return;
    if (!navigator.onLine || !window.supabaseClient) {
        showStoreStatus('Reconciliation requires a live connection to verify current shop stock.', true);
        return;
    }
    const storeId = document.getElementById('storeReconItem').value;
    const shopId = document.getElementById('storeReconShopItem').value;
    if (!storeId || !shopId) return showStoreStatus('Select both the store size and the matching shop item.', true);

    try {
        const { data: currentShopInventory, error } = await window.supabaseClient.from('inventory').select('*');
        if (error) throw error;
        const storeItem = window.storeInventory.find(item => String(item.id) === String(storeId));
        const shopItem = (currentShopInventory || []).find(item => String(item.id) === String(shopId));
        if (!storeItem || !shopItem) throw new Error('A selected stock item is no longer available. Reload the section and select again.');

        const storeQuantity = Number(storeItem.quantity);
        const shopQuantity = Number(shopItem.qty);
        if (!Number.isSafeInteger(storeQuantity) || !Number.isSafeInteger(shopQuantity) || storeQuantity < 0 || shopQuantity < 0) {
            throw new Error('A selected stock record has an invalid quantity. Reconciliation was not saved.');
        }
        const audit = {
            id: `STR-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
            date: new Date().toISOString(),
            storeItemId: storeItem.id,
            storeLabel: storeItemLabel(storeItem),
            shopItemId: shopItem.id,
            shopLabel: String(shopItem.name || 'Unnamed item'),
            storeQuantity,
            shopQuantity,
            variance: storeQuantity - shopQuantity,
            actor: storeActorName()
        };
        await commitStoreChange(() => window.storeReconciliations.push(audit));
        const result = document.getElementById('storeReconciliationResult');
        result.textContent = audit.variance === 0
            ? `Tally confirmed: ${audit.storeLabel} and ${audit.shopLabel} both show ${storeQuantity} units. No stock or financial figures were changed.`
            : `Variance recorded: store ${storeQuantity}, shop ${shopQuantity}, difference ${audit.variance > 0 ? '+' : ''}${audit.variance} units. No stock or financial figures were changed.`;
        result.style.cssText = `padding:10px; border-radius:4px; background:${audit.variance === 0 ? '#eafaf1' : '#fdedec'}; color:${audit.variance === 0 ? '#145a32' : '#922b21'};`;
    } catch (error) {
        console.error('Store reconciliation failed:', error);
        showStoreStatus(`Reconciliation was not saved: ${error.message || 'Unknown database error'}`, true);
    }
};

