function groceryActorName() {
    const user = window.currentUser || {};
    return String(user.name || user.user || user.username || 'Staff');
}

function canOperateGroceries() {
    const role = window.getNormalizedRole(window.currentUser && window.currentUser.role);
    return ['Level 2', 'Level 3', 'God Mode'].includes(role);
}

function canManageGroceryProducts() {
    return window.getNormalizedRole(window.currentUser && window.currentUser.role) === 'Level 3';
}

function showGroceryStatus(message, isError, notificationTitle) {
    const status = document.getElementById('groceryStatus');
    const statusMessage = document.getElementById('groceryStatusMessage');
    const statusTitle = document.getElementById('groceryStatusTitle');
    const statusIcon = document.getElementById('groceryStatusIcon');
    if (!status || !statusMessage || !statusTitle || !statusIcon) return;
    const isPending = notificationTitle === 'Saving';
    const variant = isPending ? 'pending' : isError ? 'error' : 'success';
    status.className = `grocery-notification grocery-notification--${variant}`;
    statusTitle.textContent = notificationTitle || (isError ? 'Action required' : 'Completed');
    statusIcon.textContent = isPending ? '…' : isError ? '!' : '✓';
    statusMessage.textContent = message;
    status.setAttribute('role', isError ? 'alert' : 'status');
    status.setAttribute('aria-live', isError ? 'assertive' : 'polite');
    status.style.display = 'flex';
}

window.dismissGroceryStatus = function() {
    const status = document.getElementById('groceryStatus');
    if (status) status.style.display = 'none';
};

