window.showGroceryHelp = function(topic) {
    const guide = GROCERY_HELP_GUIDES[topic];
    if (!guide) return;
    document.getElementById('groceryHelpTitle').textContent = guide.title;
    document.getElementById('groceryHelpSummary').textContent = guide.summary;
    document.getElementById('groceryHelpExpected').textContent = guide.expected;
    const steps = document.getElementById('groceryHelpSteps');
    steps.replaceChildren(...guide.steps.map(step => {
        const item = document.createElement('li');
        item.textContent = step;
        return item;
    }));
    document.getElementById('groceryHelpModal').style.display = 'flex';
};

window.closeGroceryHelp = function() {
    const modal = document.getElementById('groceryHelpModal');
    if (modal) modal.style.display = 'none';
};

function escapeGroceryHtml(value) {
    return String(value == null ? '' : value).replace(/[&<>"']/g, character => ({
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#39;'
    }[character]));
}

function groceryMoney(value) {
    return `$${(Number(value) || 0).toFixed(2)}`;
}

function groceryUnitPrice(value) {
    const number = Number(value) || 0;
    let formatted = number.toFixed(8).replace(/0+$/, '');
    if (formatted.endsWith('.')) formatted += '00';
    else if (formatted.includes('.') && formatted.split('.')[1].length === 1) formatted += '0';
    return `$${formatted}`;
}

function groceryToday() {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
}

function groceryDateIsValid(value) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
    const parsed = new Date(`${value}T00:00:00Z`);
    return !Number.isNaN(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value;
}

function groceryDateTime(value) {
    return new Date(`${value}T12:00:00`).toISOString();
}

function groceryRound(value, places) {
    const scale = 10 ** places;
    return Math.round((Number(value) + Number.EPSILON) * scale) / scale;
}

function getFoodProgramStudentCount() {
    return (Array.isArray(window.students) ? window.students : []).filter(student => {
        const status = String(student.enrollmentStatus || student.enrollment_status || student.status || 'active').toLowerCase();
        const participates = student.foodProgram === true || student.food_program === true ||
            String(student.foodProgram ?? student.food_program ?? '').toLowerCase() === 'true';
        return participates && ['active', 'pending_payment'].includes(status);
    }).length;
}

function requireGroceryWriteAccess() {
    if (!canOperateGroceries()) {
        showGroceryStatus('Access denied. Admin staff are required for School groceries.', true);
        return false;
    }
    if (!window.groceryDataLoaded || !window.groceryCloudReady) {
        showGroceryStatus('Grocery changes are disabled until current cloud stock has been verified.', true);
        return false;
    }
    return true;
}

function groceryProductLabel(item) {
    return `${item.name} / ${item.category} / ${item.term} (${groceryPackSize(item)} ${item.unit} pack)`;
}

function groceryPackSize(item) {
    const packSize = Number(item && item.issuePackSize);
    return Number.isFinite(packSize) && packSize > 0 ? packSize : 1;
}

function groceryStockLabel(item) {
    const quantity = groceryRound(Number(item.quantity) || 0, 3);
    const packSize = groceryPackSize(item);
    const packs = Math.floor(quantity / packSize + 1e-9);
    const loose = groceryRound(quantity - packs * packSize, 3);
    const unit = String(item.unit || '');
    return `${packs} full pack${packs === 1 ? '' : 's'} × ${packSize} ${unit}${loose > 0 ? ` + ${loose} ${unit} loose` : ''} (${quantity} ${unit} total)`;
}

function updateGrocerySelects() {
    const productValue = document.getElementById('groceryIssueProduct')?.value || '';
    const analyticsValue = document.getElementById('groceryAnalyticsProduct')?.value || '';
    const reportValue = document.getElementById('groceryReportProduct')?.value || '';
    const items = window.groceryInventory.slice().sort((a, b) => groceryProductLabel(a).localeCompare(groceryProductLabel(b)));
    const options = items.map(item =>
        `<option value="${escapeGroceryHtml(item.id)}">${escapeGroceryHtml(groceryProductLabel(item))} — ${escapeGroceryHtml(groceryStockLabel(item))}</option>`
    ).join('');
    const reportItems = new Map(items.map(item => [String(item.id), item]));
    window.groceryMovements.forEach(movement => {
        const productId = String(movement.productId || '');
        if (!productId || reportItems.has(productId)) return;
        reportItems.set(productId, {
            id: productId,
            name: movement.productName || 'Deleted product',
            category: movement.category || 'Historical',
            unit: movement.unit || 'units',
            term: movement.term || 'Historical',
            issuePackSize: movement.issuePackSize || 1
        });
    });
    const reportOptions = [...reportItems.values()]
        .sort((a, b) => groceryProductLabel(a).localeCompare(groceryProductLabel(b)))
        .map(item =>
        `<option value="${escapeGroceryHtml(item.id)}">${escapeGroceryHtml(groceryProductLabel(item))}</option>`
    ).join('');
    const issueSelect = document.getElementById('groceryIssueProduct');
    if (issueSelect) {
        issueSelect.innerHTML = `<option value="">Select product</option>${options}`;
        if (items.some(item => String(item.id) === productValue)) issueSelect.value = productValue;
    }
    const analyticsSelect = document.getElementById('groceryAnalyticsProduct');
    if (analyticsSelect) {
        analyticsSelect.innerHTML = `<option value="">All products</option>${options}`;
        if (items.some(item => String(item.id) === analyticsValue)) analyticsSelect.value = analyticsValue;
    }
    const reportSelect = document.getElementById('groceryReportProduct');
    if (reportSelect) {
        reportSelect.innerHTML = `<option value="">All products</option>${reportOptions}`;
        if (items.some(item => String(item.id) === reportValue)) reportSelect.value = reportValue;
    }

    const typeSelect = document.getElementById('groceryHistoryType');
    if (typeSelect) {
        const selectedType = typeSelect.value;
        const categories = [...new Set(items.map(item => String(item.category || '').trim()).filter(Boolean))]
            .sort((a, b) => a.localeCompare(b));
        typeSelect.innerHTML = `<option value="">All types</option>${categories.map(category =>
            `<option value="${escapeGroceryHtml(category)}">${escapeGroceryHtml(category)}</option>`
        ).join('')}`;
        if (categories.includes(selectedType)) typeSelect.value = selectedType;
    }
}

function groceryPeriodFor(movement, grain) {
    const dateText = String(movement.date || '').slice(0, 10);
    if (!groceryDateIsValid(dateText)) return null;
    const date = new Date(`${dateText}T00:00:00Z`);
    const year = date.getUTCFullYear();
    if (grain === 'day') return { key: dateText, label: dateText, date: dateText };
    if (grain === 'week') {
        const thursday = new Date(date);
        thursday.setUTCDate(thursday.getUTCDate() - ((thursday.getUTCDay() + 6) % 7) + 3);
        const weekYear = thursday.getUTCFullYear();
        const firstThursday = new Date(Date.UTC(weekYear, 0, 4));
        firstThursday.setUTCDate(firstThursday.getUTCDate() - ((firstThursday.getUTCDay() + 6) % 7) + 3);
        const week = 1 + Math.round((thursday - firstThursday) / 604800000);
        const label = `${weekYear}-W${String(week).padStart(2, '0')}`;
        return { key: label, label, date: dateText };
    }
    if (grain === 'year') return { key: String(year), label: String(year), date: dateText };
    if (grain === 'term') {
        const term = String(movement.term || 'General');
        const label = `${year} ${term}`;
        return { key: label, label, date: dateText };
    }
    const label = dateText.slice(0, 7);
    return { key: label, label, date: dateText };
}

function aggregateGroceryIssues(movements, grain, productFilter, start, end) {
    const groups = new Map();
    movements.filter(movement => movement.type === 'ISSUED').forEach(movement => {
        const date = String(movement.date || '').slice(0, 10);
        if (!groceryDateIsValid(date) || (start && date < start) || (end && date > end)) return;
        if (productFilter && String(movement.productId) !== String(productFilter)) return;
        const period = groceryPeriodFor(movement, grain);
        if (!period) return;
        const groupKey = `${period.key}|${movement.productId}`;
        let group = groups.get(groupKey);
        if (!group) {
            group = {
                key: period.key,
                label: period.label,
                productId: String(movement.productId),
                productName: movement.productName || 'Deleted product',
                category: movement.category || '',
                unit: movement.unit || '',
                term: movement.term || '',
                quantity: 0,
                value: 0,
                startDate: date,
                endDate: date,
                studentsByDate: new Map()
            };
            groups.set(groupKey, group);
        }
        group.quantity += Number(movement.quantity) || 0;
        group.value += Number.isFinite(Number(movement.totalValue))
            ? Number(movement.totalValue)
            : (Number(movement.quantity) || 0) * (Number(movement.unitPrice) || 0);
        if (date < group.startDate) group.startDate = date;
        if (date > group.endDate) group.endDate = date;
        const studentCount = Number(movement.foodStudents) || 0;
        if (studentCount > 0) group.studentsByDate.set(date, studentCount);
    });
    return [...groups.values()].map(group => {
        const studentCounts = [...group.studentsByDate.values()];
        const foodStudents = studentCounts.length
            ? studentCounts.reduce((sum, count) => sum + count, 0) / studentCounts.length
            : 0;
        return {
            ...group,
            quantity: groceryRound(group.quantity, 3),
            value: groceryRound(group.value, 2),
            foodStudents,
            perStudent: foodStudents > 0 ? group.quantity / foodStudents : null
        };
    }).sort((a, b) => a.startDate.localeCompare(b.startDate) || a.productName.localeCompare(b.productName));
}

function getGroceryHistoricalBaseline(group, allGroups) {
    if (!(group.foodStudents > 0)) return null;
    const prior = allGroups.filter(item =>
        item.productId === group.productId &&
        item.startDate < group.startDate &&
        item.foodStudents > 0
    ).slice(-4);
    if (prior.length < 3) return null;
    const perStudent = prior.map(item => item.quantity / item.foodStudents);
    return perStudent.reduce((sum, value) => sum + value, 0) / perStudent.length;
}

function getGroceryDailyRates() {
    const daily = new Map();
    window.groceryMovements.filter(movement => movement.type === 'ISSUED').forEach(movement => {
        const date = String(movement.date || '').slice(0, 10);
        const students = Number(movement.foodStudents) || 0;
        if (!groceryDateIsValid(date) || students <= 0) return;
        let day = daily.get(date);
        if (!day) {
            day = { value: 0, students };
            daily.set(date, day);
        }
        day.value += Number.isFinite(Number(movement.totalValue))
            ? Number(movement.totalValue)
            : (Number(movement.quantity) || 0) * (Number(movement.unitPrice) || 0);
        day.students = students;
    });
    const rates = [...daily.values()].map(day => day.value / day.students).filter(Number.isFinite);
    return {
        dailyValuePerStudent: rates.length ? rates.reduce((sum, rate) => sum + rate, 0) / rates.length : 0,
        issueDays: rates.length
    };
}

window.renderGroceryAnalytics = function() {
    const tbody = document.getElementById('groceryAnalyticsRows');
    if (!tbody) return;
    const grain = document.getElementById('groceryAnalyticsGrain').value || 'month';
    const productFilter = document.getElementById('groceryAnalyticsProduct').value;
    const start = document.getElementById('groceryAnalyticsStart').value;
    const end = document.getElementById('groceryAnalyticsEnd').value;
    const allGroups = aggregateGroceryIssues(window.groceryMovements, grain, '', '', '');
    const visibleGroups = aggregateGroceryIssues(window.groceryMovements, grain, productFilter, start, end);
    const reviews = window.groceryReviews.slice().sort((a, b) => String(b.date).localeCompare(String(a.date)));
    const analysisMap = new Map();
    window.groceryCurrentAnalysisMap = analysisMap;

    const rows = visibleGroups.map((group, index) => {
        const baseline = getGroceryHistoricalBaseline(group, allGroups);
        const expected = baseline == null ? null : baseline * group.foodStudents;
        const variance = expected == null ? null : group.quantity - expected;
        const variancePercent = expected > 0 ? (variance / expected) * 100 : null;
        const status = expected == null ? 'Insufficient history'
            : group.quantity < expected * 0.8 ? 'LOW'
            : group.quantity > expected * 1.2 ? 'HIGH'
            : 'Within 20%';
        const review = reviews.find(entry => entry.periodKey === group.key && String(entry.productId) === group.productId);
        const key = `${group.key}|${group.productId}`;
        analysisMap.set(key, { ...group, expected, baseline, variance, variancePercent, status });
        const color = status === 'LOW' ? '#b9770e' : status === 'HIGH' ? '#c0392b' : '#1e8449';
        const comparison = expected == null
            ? 'Needs 3 prior periods'
            : `${status}${variancePercent == null ? '' : ` (${variancePercent > 0 ? '+' : ''}${groceryRound(variancePercent, 1)}%)`} (${variance > 0 ? '+' : ''}${groceryRound(variance, 2)} ${group.unit})`;
        const reviewText = review ? `Reviewed: ${review.reason}` : (status === 'LOW' || status === 'HIGH' ? 'Reason required' : '');
        return `<tr style="border-bottom:1px solid #ecf0f1;">
            <td style="padding:7px;">${escapeGroceryHtml(group.label)}</td>
            <td style="padding:7px;">${escapeGroceryHtml(group.productName)}</td>
            <td style="padding:7px; text-align:right;">${group.quantity} ${escapeGroceryHtml(group.unit)}</td>
            <td style="padding:7px; text-align:right;">${groceryMoney(group.value)}</td>
            <td style="padding:7px; text-align:right;">${group.foodStudents ? groceryRound(group.quantity / group.foodStudents, 3) : '—'}</td>
            <td style="padding:7px; color:${color};">${escapeGroceryHtml(comparison)}${reviewText ? `<br><small>${escapeGroceryHtml(reviewText)}</small>` : ''}
                <br><button type="button" class="btn-standard btn-dark" data-analysis-key="${escapeGroceryHtml(key)}" onclick="window.selectGroceryReview(this.dataset.analysisKey)" style="padding:3px 6px; font-size:10px;">Review / note</button></td>
        </tr>`;
    });
    tbody.innerHTML = rows.length
        ? rows.join('')
        : '<tr><td colspan="6" style="padding:10px; color:#7f8c8d;">No consumption history matches these filters.</td></tr>';

    const chartCanvas = document.getElementById('groceryConsumptionChart');
    if (chartCanvas && typeof Chart !== 'undefined') {
        if (window.groceryConsumptionChartInstance) window.groceryConsumptionChartInstance.destroy();
        const chartRows = productFilter ? visibleGroups.map(group => {
            const analysis = analysisMap.get(`${group.key}|${group.productId}`);
            return { label: group.label, actual: group.quantity, expected: analysis && analysis.expected != null ? analysis.expected : null };
        }) : visibleGroups.map(group => ({ label: group.label, actual: group.value, expected: null }));
        const labels = [...new Set(chartRows.map(row => row.label))];
        const actualByPeriod = new Map();
        const expectedByPeriod = new Map();
        chartRows.forEach(row => {
            actualByPeriod.set(row.label, (actualByPeriod.get(row.label) || 0) + row.actual);
            if (row.expected != null) expectedByPeriod.set(row.label, (expectedByPeriod.get(row.label) || 0) + row.expected);
        });
        window.groceryConsumptionChartInstance = new Chart(chartCanvas.getContext('2d'), {
            type: 'bar',
            data: {
                labels,
                datasets: [
                    { label: productFilter ? 'Issued quantity' : 'Issued value ($)', data: labels.map(label => groceryRound(actualByPeriod.get(label) || 0, 2)), backgroundColor: '#3498db' },
                    ...(productFilter ? [{ type: 'line', label: 'Historical expected quantity', data: labels.map(label => expectedByPeriod.has(label) ? groceryRound(expectedByPeriod.get(label), 2) : null), borderColor: '#e67e22', backgroundColor: '#e67e22', spanGaps: false }] : [])
                ]
            },
            options: { responsive: true, maintainAspectRatio: false, scales: { y: { beginAtZero: true } } }
        });
    }
    updateGroceryBudgetProjection();
};

function groceryReportQuantity(value) {
    return groceryRound(Number(value) || 0, 3).toLocaleString(undefined, { maximumFractionDigits: 3 });
}

function groceryReportTotalsByUnit(rows, field) {
    const totals = new Map();
    rows.forEach(row => {
        const unit = String(row.unit || 'units');
        totals.set(unit, (totals.get(unit) || 0) + (Number(row[field]) || 0));
    });
    return [...totals.entries()]
        .sort(([unitA], [unitB]) => unitA.localeCompare(unitB))
        .map(([unit, quantity]) => `${groceryReportQuantity(quantity)} ${unit}`)
        .join(' · ') || '0';
}

window.renderGroceryReport = function() {
    const tbody = document.getElementById('groceryReportRows');
    if (!tbody) return false;
    const start = document.getElementById('groceryReportStart').value;
    const end = document.getElementById('groceryReportEnd').value;
    const productFilter = document.getElementById('groceryReportProduct').value;
    if (start && !groceryDateIsValid(start)) {
        showGroceryStatus('Select a valid report start date.', true);
        return false;
    }
    if (end && !groceryDateIsValid(end)) {
        showGroceryStatus('Select a valid report end date.', true);
        return false;
    }
    if (start && end && start > end) {
        showGroceryStatus('The report start date must be on or before the end date.', true);
        return false;
    }

    const period = start || end
        ? `Date range: ${start || 'all earlier dates'} to ${end || 'all later dates'}`
        : 'Date range: all recorded dates';
    const selectedProduct = window.groceryInventory.find(item => String(item.id) === String(productFilter));
    document.getElementById('groceryReportPeriod').textContent =
        `${period} · Product: ${selectedProduct ? groceryProductLabel(selectedProduct) : 'All products'} · Generated: ${new Date().toLocaleString()}`;

    if (!window.groceryDataLoaded) {
        document.getElementById('groceryReportBought').textContent = '—';
        document.getElementById('groceryReportUsed').textContent = '—';
        document.getElementById('groceryReportStock').textContent = '—';
        document.getElementById('groceryReportCoverage').textContent = 'Unavailable';
        tbody.innerHTML = '<tr><td colspan="6" style="padding:10px; color:#7f8c8d;">Report requires current cloud-verified grocery data. Reopen School groceries while connected.</td></tr>';
        return false;
    }

    const inventoryById = new Map(window.groceryInventory.map(item => [String(item.id), item]));
    const reportRows = new Map();
    const getRow = (productId, unit, term, name, category) => {
        const key = JSON.stringify([productId, unit, term]);
        let row = reportRows.get(key);
        if (!row) {
            row = {
                productId,
                unit,
                term,
                name: name || 'Deleted product',
                category: category || '',
                bought: 0,
                used: 0,
                stock: 0,
                issueByDate: new Map()
            };
            reportRows.set(key, row);
        }
        return row;
    };

    window.groceryInventory.forEach(item => {
        const productId = String(item.id);
        if (productFilter && productId !== String(productFilter)) return;
        const unit = String(item.unit || 'units');
        const term = String(item.term || 'General');
        const row = getRow(productId, unit, term, item.name, item.category);
        row.stock = Number(item.quantity) || 0;
    });

    window.groceryMovements.forEach(movement => {
        if (!['RECEIVED', 'ISSUED'].includes(movement.type)) return;
        const date = String(movement.date || '').slice(0, 10);
        if (!groceryDateIsValid(date) || (start && date < start) || (end && date > end)) return;
        const productId = String(movement.productId || '');
        if (!productId || (productFilter && productId !== String(productFilter))) return;
        const item = inventoryById.get(productId);
        const unit = String(movement.unit || (item && item.unit) || 'units');
        const term = String(movement.term || 'General');
        const row = getRow(productId, unit, term,
            (item && item.name) || movement.productName,
            (item && item.category) || movement.category);
        const quantity = Number(movement.quantity);
        if (!Number.isFinite(quantity) || quantity <= 0) return;
        if (movement.type === 'RECEIVED') {
            row.bought += quantity;
        } else {
            row.used += quantity;
            row.issueByDate.set(date, (row.issueByDate.get(date) || 0) + quantity);
        }
    });

    const rows = [...reportRows.values()].map(row => {
        const issueDays = row.issueByDate.size;
        const averageUsed = issueDays ? row.used / issueDays : 0;
        return {
            ...row,
            bought: groceryRound(row.bought, 3),
            used: groceryRound(row.used, 3),
            stock: groceryRound(row.stock, 3),
            averageUsed: groceryRound(averageUsed, 3),
            coverage: averageUsed > 0 ? groceryRound(row.stock / averageUsed, 1) : null,
            issueDays
        };
    }).sort((a, b) =>
        a.name.localeCompare(b.name) || a.unit.localeCompare(b.unit) || a.term.localeCompare(b.term)
    );

    document.getElementById('groceryReportBought').textContent = groceryReportTotalsByUnit(rows, 'bought');
    document.getElementById('groceryReportUsed').textContent = groceryReportTotalsByUnit(rows, 'used');
    document.getElementById('groceryReportStock').textContent = groceryReportTotalsByUnit(rows, 'stock');
    const coverageCount = rows.filter(row => row.issueDays > 0).length;
    document.getElementById('groceryReportCoverage').textContent = coverageCount
        ? `${coverageCount} product${coverageCount === 1 ? '' : 's'} estimated below`
        : 'No issue history for this filter';

    tbody.innerHTML = rows.length
        ? rows.map(row => `<tr style="border-bottom:1px solid #ecf0f1;">
            <td style="padding:8px;"><strong>${escapeGroceryHtml(row.name)}</strong><small style="display:block;">${escapeGroceryHtml(row.category)} · ${escapeGroceryHtml(row.term)} · Base unit: ${escapeGroceryHtml(row.unit)}</small></td>
            <td style="padding:8px; text-align:right;">${groceryReportQuantity(row.bought)} ${escapeGroceryHtml(row.unit)}</td>
            <td style="padding:8px; text-align:right;">${groceryReportQuantity(row.used)} ${escapeGroceryHtml(row.unit)}</td>
            <td style="padding:8px; text-align:right;">${groceryReportQuantity(row.stock)} ${escapeGroceryHtml(row.unit)}</td>
            <td style="padding:8px; text-align:right;">${row.issueDays ? `${groceryReportQuantity(row.averageUsed)} ${escapeGroceryHtml(row.unit)}` : '—'}</td>
            <td style="padding:8px; text-align:right;">${row.coverage == null ? 'No usage history' : `${groceryReportQuantity(row.coverage)} issue days`}</td>
        </tr>`).join('')
        : '<tr><td colspan="6" style="padding:10px; color:#7f8c8d;">No grocery purchases, issues, or current stock match these filters.</td></tr>';
    return true;
};

window.printGroceryReport = function() {
    if (!window.groceryDataLoaded) {
        showGroceryStatus('Load current cloud-verified grocery data before printing this report.', true);
        return;
    }
    if (!window.renderGroceryReport()) return;
    const report = document.getElementById('groceryReport');
    const reportToggle = report.querySelector('.grocery-section-toggle');
    const reportWasCollapsed = report.classList.contains('grocery-section-collapsed');
    if (reportWasCollapsed) {
        report.classList.remove('grocery-section-collapsed');
        if (reportToggle) {
            reportToggle.textContent = 'Collapse';
            reportToggle.setAttribute('aria-expanded', 'true');
            reportToggle.setAttribute('aria-label', 'Collapse grocery purchase, usage and stock report');
            reportToggle.title = 'Collapse grocery purchase, usage and stock report';
        }
    }
    document.body.classList.add('grocery-report-printing');
    let printFinished = false;
    const finishPrint = () => {
        if (printFinished) return;
        printFinished = true;
        window.removeEventListener('afterprint', finishPrint);
        document.body.classList.remove('grocery-report-printing');
        if (reportWasCollapsed) {
            report.classList.add('grocery-section-collapsed');
            if (reportToggle) {
                reportToggle.textContent = 'Expand';
                reportToggle.setAttribute('aria-expanded', 'false');
                reportToggle.setAttribute('aria-label', 'Expand grocery purchase, usage and stock report');
                reportToggle.title = 'Expand grocery purchase, usage and stock report';
            }
        }
    };
    window.addEventListener('afterprint', finishPrint, { once: true });
    window.print();
    window.setTimeout(finishPrint, 1000);
};

window.selectGroceryReview = function(analysisKey) {
    const selection = window.groceryCurrentAnalysisMap.get(String(analysisKey));
    if (!selection) return showGroceryStatus('That consumption period is no longer available. Reapply the filters and try again.', true);
    window.groceryReviewSelection = selection;
    const panel = document.getElementById('groceryReviewPanel');
    panel.style.display = 'block';
    document.getElementById('groceryReviewTitle').textContent = `${selection.status} consumption review — ${selection.productName}, ${selection.label}`;
    document.getElementById('groceryReviewMetrics').textContent =
        `Issued ${selection.quantity} ${selection.unit}; ${selection.foodStudents ? groceryRound(selection.quantity / selection.foodStudents, 3) : 'no'} units per food-program student` +
        (selection.expected == null ? '; historical comparison is not yet available.' : `; historical expectation is about ${groceryRound(selection.expected, 3)} ${selection.unit}.`);
    const existing = window.groceryReviews.slice().reverse().find(entry =>
        entry.periodKey === selection.key && String(entry.productId) === selection.productId
    );
    document.getElementById('groceryReviewReason').value = existing ? existing.reason : '';
    document.getElementById('groceryReviewStatus').textContent = '';
};

window.saveGroceryReview = async function() {
    if (!requireGroceryWriteAccess()) return;
    const selection = window.groceryReviewSelection;
    const reason = document.getElementById('groceryReviewReason').value.trim();
    if (!selection) return showGroceryStatus('Select a consumption period before saving its review.', true);
    if (!reason) return showGroceryStatus('An explanation is required to save this consumption review.', true);
    if (reason.length > 300) return showGroceryStatus('The explanation must be 300 characters or fewer.', true);
    const review = {
        id: `GREV-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        periodKey: selection.key,
        periodLabel: selection.label,
        productId: selection.productId,
        productName: selection.productName,
        status: selection.status,
        actualQuantity: selection.quantity,
        expectedQuantity: selection.expected,
        reason,
        date: new Date().toISOString(),
        actor: groceryActorName()
    };
    try {
        await commitGroceryChange(
            () => window.groceryReviews.push(review),
            'Consumption review saved and synced. The explanation is attached to this period and product. Next: return to the analysis table to verify it.',
            'Check the connection and current grocery data, then retry saving the explanation.'
        );
        document.getElementById('groceryReviewStatus').textContent = 'Review saved.';
        window.renderGroceryAnalytics();
        window.selectGroceryReview(`${selection.key}|${selection.productId}`);
    } catch (error) {
        console.error('Grocery consumption review failed:', error);
    }
};

function updateGroceryBudgetProjection() {
    const count = getFoodProgramStudentCount();
    const daysInput = document.getElementById('groceryProjectionDays');
    const days = Number(daysInput?.value);
    const rate = getGroceryDailyRates();
    const enoughHistory = rate.issueDays >= 3;
    const budget = enoughHistory ? rate.dailyValuePerStudent * count * days : 0;
    document.getElementById('groceryProjectedBudget').textContent = groceryMoney(budget);
    document.getElementById('groceryProjectionBasis').textContent = enoughHistory
        ? `Estimate uses ${rate.issueDays} recorded issue day(s), ${groceryMoney(rate.dailyValuePerStudent)} average cost per food-program student per issue day, ${count} current student(s), and ${days || 0} projected service day(s). It is an estimate, not a financial entry.`
        : `A budget estimate will appear after 3 recorded issue days (${rate.issueDays} recorded so far).`;
}

function renderGroceryIssueCart() {
    const rows = document.getElementById('groceryIssueCartRows');
    const total = document.getElementById('groceryIssueCartTotal');
    if (!rows || !total) return;
    let totalValue = 0;
    rows.innerHTML = window.groceryIssueCart.length
        ? window.groceryIssueCart.map((line, index) => {
            const item = window.groceryInventory.find(entry => String(entry.id) === String(line.productId));
            if (!item) return `<tr><td colspan="4" style="padding:8px; color:#c0392b;">A listed product is no longer active. Remove it before submitting.</td></tr>`;
            const quantity = Number(line.quantity) || 0;
            const value = quantity * (Number(item.unitPrice) || 0);
            totalValue += value;
            return `<tr style="border-top:1px solid #ecf0f1;">
                <td style="padding:6px;">${escapeGroceryHtml(groceryProductLabel(item))}<br><small>${escapeGroceryHtml(groceryStockLabel(item))} available</small></td>
                <td style="padding:6px;"><input class="input-standard" aria-label="Issue quantity for ${escapeGroceryHtml(item.name)}" type="number" min="0.001" step="0.001" value="${quantity}" data-cart-index="${index}" onchange="window.updateGroceryIssueCartQuantity(Number(this.dataset.cartIndex), this.value)" style="max-width:130px;"> ${escapeGroceryHtml(item.unit)}</td>
                <td style="padding:6px; text-align:right;">${groceryMoney(value)}</td>
                <td style="padding:6px; text-align:right;"><button type="button" class="btn-standard btn-danger" data-cart-index="${index}" onclick="window.removeGroceryIssueItem(Number(this.dataset.cartIndex))" style="padding:4px 7px;">Remove</button></td>
            </tr>`;
        }).join('')
        : '<tr><td colspan="4" style="padding:8px; color:#7f8c8d;">No products added to this request.</td></tr>';
    total.textContent = groceryMoney(totalValue);
}

function renderGroceryFrequentButtons() {
    const container = document.getElementById('groceryFrequentButtons');
    if (!container) return;
    const counts = new Map();
    window.groceryMovements.filter(movement => movement.type === 'ISSUED').forEach(movement => {
        counts.set(String(movement.productId), (counts.get(String(movement.productId)) || 0) + 1);
    });
    const mostIssued = window.groceryInventory.map(item => ({
        item,
        count: counts.get(String(item.id)) || 0
    })).filter(entry => entry.count > 0 && Number(entry.item.quantity) > 0)
        .sort((a, b) => b.count - a.count || groceryProductLabel(a.item).localeCompare(groceryProductLabel(b.item)))
        .slice(0, 5);
    const tileColors = ['teal', 'blue', 'purple', 'orange', 'rose', 'green'];
    container.innerHTML = mostIssued.length
        ? mostIssued.map(({ item, count }, index) => {
            const packSize = groceryPackSize(item);
            const unit = escapeGroceryHtml(item.unit);
            const name = escapeGroceryHtml(item.name);
            return `<button type="button" class="grocery-quick-tile grocery-quick-tile--${tileColors[index % tileColors.length]}" data-product-id="${escapeGroceryHtml(item.id)}" onclick="window.quickAddGroceryProduct(this.dataset.productId)" aria-label="Add one pack of ${name} to the issue list">
                <span class="grocery-quick-tile-name">${name}</span>
                <span class="grocery-quick-tile-pack">1 pack · ${packSize} ${unit}</span>
                <span class="grocery-quick-tile-count">${count} issue${count === 1 ? '' : 's'}</span>
            </button>`;
        }).join('')
        : '<span style="color:#7f8c8d; font-size:12px;">Frequently issued products will appear after issue history is recorded.</span>';
}

function initializeGrocerySectionCollapses() {
    const palette = [
        { accent: '#b45309', tint: '#fff7ed' },
        { accent: '#0f766e', tint: '#ecfdf5' },
        { accent: '#1d4ed8', tint: '#eff6ff' },
        { accent: '#6d28d9', tint: '#f5f3ff' },
        { accent: '#be185d', tint: '#fdf2f8' },
        { accent: '#15803d', tint: '#f0fdf4' },
        { accent: '#c2410c', tint: '#fff7ed' }
    ];
    document.querySelectorAll('#groceries .card').forEach((card, index) => {
        if (card.dataset.groceryCollapseInitialized === 'true') return;
        const heading = card.querySelector('h2, h3, h4');
        const header = card.firstElementChild;
        const title = heading ? heading.textContent.trim().replace(/\s+/g, ' ') : '';
        if (!header || !heading || !header.contains(heading) || !title) return;
        const colors = palette[index % palette.length];
        card.style.setProperty('--grocery-section-accent', colors.accent);
        card.style.setProperty('--grocery-section-tint', colors.tint);

        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'btn-standard btn-dark grocery-section-toggle';
        button.textContent = 'Expand';
        button.setAttribute('aria-expanded', 'false');
        button.setAttribute('aria-label', `Expand ${title}`);
        button.title = `Expand ${title}`;
        button.addEventListener('click', () => {
            const expanded = button.getAttribute('aria-expanded') !== 'true';
            card.classList.toggle('grocery-section-collapsed', !expanded);
            button.textContent = expanded ? 'Collapse' : 'Expand';
            button.setAttribute('aria-expanded', String(expanded));
            button.setAttribute('aria-label', `${expanded ? 'Collapse' : 'Expand'} ${title}`);
            button.title = `${expanded ? 'Collapse' : 'Expand'} ${title}`;
        });

        header.classList.add('grocery-section-heading');
        header.appendChild(button);
        card.classList.add('grocery-section-collapsible', 'grocery-section-collapsed');
        card.dataset.groceryCollapseInitialized = 'true';
    });
}

function canCorrectGroceryReceipt(movement) {
    if (!movement || movement.type !== 'RECEIVED') return false;
    const index = window.groceryMovements.findIndex(entry => String(entry.id) === String(movement.id));
    if (index < 0) return false;
    return !window.groceryMovements.slice(index + 1).some(entry =>
        String(entry.productId) === String(movement.productId)
    );
}

function groceryPackSizeBeforeReceipt(movement) {
    const index = window.groceryMovements.findIndex(entry => String(entry.id) === String(movement.id));
    for (let position = index - 1; position >= 0; position -= 1) {
        const entry = window.groceryMovements[position];
        if (String(entry.productId) !== String(movement.productId) || entry.type === 'RECEIPT_VOIDED') continue;
        const packSize = Number(entry.issuePackSize);
        if (Number.isFinite(packSize) && packSize > 0) return packSize;
    }
    return 1;
}

function groceryReceiptTotal(movement) {
    const total = Number(movement.totalValue);
    if (Number.isFinite(total) && total >= 0) return groceryRound(total, 2);
    return groceryRound((Number(movement.quantity) || 0) * (Number(movement.unitPrice) || 0), 2);
}

window.renderGroceryModule = function() {
    const inventoryRows = document.getElementById('groceryInventoryRows');
    if (!inventoryRows) return;
    initializeGrocerySectionCollapses();
    const chiefAdmin = canManageGroceryProducts();
    const foodStudents = getFoodProgramStudentCount();
    document.getElementById('groceryFoodStudentCount').textContent = String(foodStudents);
    document.getElementById('groceryFoodCountHint').textContent =
        `${foodStudents} active / pending food-program student(s) will be attached to each issue for per-student analysis.`;

    const totalStockValue = window.groceryInventory.reduce((sum, item) =>
        sum + (Number(item.quantity) || 0) * (Number(item.unitPrice) || 0), 0);
    document.getElementById('groceryStockValue').textContent = groceryMoney(totalStockValue);
    inventoryRows.innerHTML = window.groceryInventory.length
        ? window.groceryInventory.slice().sort((a, b) => groceryProductLabel(a).localeCompare(groceryProductLabel(b))).map(item => {
            const productDays = window.groceryMovements.filter(movement => movement.type === 'ISSUED' && String(movement.productId) === String(item.id));
            const byDate = new Map();
            productDays.forEach(movement => {
                const date = String(movement.date || '').slice(0, 10);
                const students = Number(movement.foodStudents) || 0;
                if (!students) return;
                const entry = byDate.get(date) || { quantity: 0, students };
                entry.quantity += Number(movement.quantity) || 0;
                byDate.set(date, entry);
            });
            const rates = [...byDate.values()].map(day => day.quantity / day.students);
            const rate = rates.length ? rates.reduce((sum, value) => sum + value, 0) / rates.length : 0;
            const cover = rate > 0 && foodStudents > 0 ? groceryRound(Number(item.quantity) / (rate * foodStudents), 1) : null;
            return `<tr style="border-bottom:1px solid #ecf0f1;">
                <td style="padding:8px;"><strong>${escapeGroceryHtml(item.name)}</strong><br><small>${escapeGroceryHtml(item.category)} · ${escapeGroceryHtml(item.unit)} · ${groceryPackSize(item)} ${escapeGroceryHtml(item.unit)} per pack</small></td>
                <td style="padding:8px;">${escapeGroceryHtml(item.term)}</td>
                <td style="padding:8px; text-align:right; font-weight:bold;">${escapeGroceryHtml(groceryStockLabel(item))}<br><small>${cover == null ? 'History needed for cover' : `~${cover} issue days cover`}</small></td>
                <td style="padding:8px; text-align:right;">${groceryUnitPrice(item.unitPrice)}</td>
                <td style="padding:8px; text-align:right;">${groceryMoney((Number(item.quantity) || 0) * (Number(item.unitPrice) || 0))}</td>
                <td style="padding:8px; position:sticky; right:0; z-index:1; background:#fff; box-shadow:-4px 0 6px rgba(0,0,0,.06);">${chiefAdmin
                    ? `<div style="display:flex; flex-direction:column; gap:4px; min-width:100px;">
                           <button type="button" class="btn-standard btn-primary" data-product-id="${escapeGroceryHtml(item.id)}" onclick="window.editGroceryProduct(this.dataset.productId)" style="width:100%; box-sizing:border-box; padding:6px 8px; font-size:12px;">Edit</button>
                           ${Number(item.quantity) > 0
                                ? `<button type="button" class="btn-standard btn-dark" data-product-id="${escapeGroceryHtml(item.id)}" onclick="window.clearGroceryProductStock(this.dataset.productId)" style="width:100%; box-sizing:border-box; padding:6px 8px; font-size:12px;">Clear stock</button>`
                                : '<button type="button" class="btn-standard btn-dark" disabled title="This item already has zero stock." style="width:100%; box-sizing:border-box; padding:6px 8px; font-size:12px;">Clear stock</button>'}
                           <button type="button" class="btn-standard btn-danger" data-product-id="${escapeGroceryHtml(item.id)}" onclick="window.deleteGroceryProduct(this.dataset.productId)" style="width:100%; box-sizing:border-box; padding:6px 8px; font-size:12px;">Delete</button>
                       </div>`
                    : '—'}</td>
            </tr>`;
        }).join('')
        : '<tr><td colspan="6" style="padding:10px; color:#7f8c8d;">No grocery stock recorded yet.</td></tr>';

    updateGrocerySelects();
    window.updateGroceryIssueEstimate();
    renderGroceryIssueCart();
    renderGroceryFrequentButtons();
    const start = document.getElementById('groceryHistoryStart')?.value || '';
    const end = document.getElementById('groceryHistoryEnd')?.value || '';
    const category = document.getElementById('groceryHistoryType')?.value || '';
    const departmentSelect = document.getElementById('groceryHistoryDepartment');
    const selectedDepartment = departmentSelect?.value || '';
    if (departmentSelect) {
        const departments = [...new Set(window.groceryMovements.map(movement => String(movement.department || '').trim()).filter(Boolean))]
            .sort((a, b) => a.localeCompare(b));
        departmentSelect.innerHTML = `<option value="">All departments</option>${departments.map(department =>
            `<option value="${escapeGroceryHtml(department)}">${escapeGroceryHtml(department)}</option>`
        ).join('')}`;
        if (departments.includes(selectedDepartment)) departmentSelect.value = selectedDepartment;
    }
    const department = departmentSelect?.value || '';
    const query = (document.getElementById('groceryHistorySearch')?.value || '').trim().toLowerCase();
    const movements = window.groceryMovements.filter(movement => {
        const effectiveDate = movement.type === 'RECEIPT_VOIDED' ? movement.voidedAt || movement.date : movement.date;
        const date = String(effectiveDate || '').slice(0, 10);
        const searchable = `${movement.productName} ${movement.category} ${movement.takenBy} ${movement.purchasedBy} ${movement.receivedBy} ${movement.supplier} ${movement.paymentMethod} ${movement.receivedPacks} ${movement.pricePerPack} ${movement.department} ${movement.actor} ${movement.note || ''} ${movement.correctionReason || ''} ${movement.voidReason || ''}`.toLowerCase();
        return (!start || date >= start) && (!end || date <= end) &&
            (!category || String(movement.category) === category) &&
            (!department || String(movement.department || '') === department) &&
            (!query || searchable.includes(query));
    }).sort((a, b) => {
        const dateA = a.type === 'RECEIPT_VOIDED' ? a.voidedAt || a.date : a.date;
        const dateB = b.type === 'RECEIPT_VOIDED' ? b.voidedAt || b.date : b.date;
        return String(dateB).localeCompare(String(dateA));
    });
    const movementRows = document.getElementById('groceryMovementRows');
    movementRows.innerHTML = movements.length
        ? movements.map(movement => {
            const issued = movement.type === 'ISSUED';
            const received = ['RECEIVED', 'RECEIPT_EDITED', 'RECEIPT_VOIDED'].includes(movement.type);
            const reversed = movement.type === 'ISSUE_REVERSED';
            const voidedReceipt = movement.type === 'RECEIPT_VOIDED';
            const supersededReceipt = movement.type === 'RECEIPT_EDITED';
            const amount = groceryReceiptTotal(movement) * (voidedReceipt ? -1 : 1);
            const quantityText = ['PRODUCT_EDITED', 'PRODUCT_DELETED'].includes(movement.type)
                ? '—'
                : movement.type === 'PRODUCT_RESTORED'
                    ? '—'
                : supersededReceipt
                    ? 'Superseded'
                    : voidedReceipt
                        ? `-${Number(movement.quantity) || 0}`
                : movement.type === 'ADJUSTMENT'
                    ? `${Number(movement.quantity) > 0 ? '+' : ''}${Number(movement.quantity) || 0}`
                    : `${issued ? '-' : '+'}${Number(movement.quantity) || 0}`;
            const balanceText = movement.stockAfter == null ? '' : `<br><small>Balance after: ${Number(movement.stockAfter)} ${escapeGroceryHtml(movement.unit || '')}</small>`;
            const hasActiveMovementProduct = window.groceryInventory.some(item =>
                String(item.id) === String(movement.productId)
            );
            const canDeleteIssue = chiefAdmin && issued && hasActiveMovementProduct;
            const canManageReceipt = chiefAdmin && movement.type === 'RECEIVED';
            const movementIndex = window.groceryMovements.findIndex(entry => String(entry.id) === String(movement.id));
            const hasLaterProductMovement = movementIndex >= 0 && window.groceryMovements.slice(movementIndex + 1)
                .some(entry => String(entry.productId) === String(movement.productId));
            const canRestoreProduct = chiefAdmin && movement.type === 'PRODUCT_DELETED' &&
                !hasActiveMovementProduct && !hasLaterProductMovement;
            const receiptActions = canManageReceipt
                ? `<div style="display:flex; flex-direction:column; gap:4px; min-width:105px;">
                       <button type="button" class="btn-standard btn-primary" data-movement-id="${escapeGroceryHtml(movement.id)}" onclick="window.editGroceryReceipt(this.dataset.movementId)" style="padding:5px 8px; font-size:11px;">Edit details</button>
                       ${canCorrectGroceryReceipt(movement) && hasActiveMovementProduct
                            ? `<button type="button" class="btn-standard btn-danger" data-movement-id="${escapeGroceryHtml(movement.id)}" onclick="window.voidGroceryReceipt(this.dataset.movementId)" title="Void this receipt and retain its audit history" style="padding:5px 8px; font-size:11px;">Delete / void</button>`
                            : `<button type="button" class="btn-standard btn-danger" disabled title="${hasActiveMovementProduct ? 'Later stock activity prevents a safe stock reversal.' : 'The product is inactive, so the receipt cannot be returned to stock.'}" style="padding:5px 8px; font-size:11px;">Delete / void</button><small>${hasActiveMovementProduct ? 'Later stock activity — locked' : 'Product inactive — locked'}</small>`}
                   </div>`
                : '';
            const issueActions = chiefAdmin && issued
                ? canDeleteIssue
                    ? `<button type="button" class="btn-standard btn-danger" data-movement-id="${escapeGroceryHtml(movement.id)}" onclick="window.deleteGroceryIssueMovement(this.dataset.movementId)" style="padding:5px 8px; font-size:11px;">Delete issue</button>`
                    : `<button type="button" class="btn-standard btn-danger" disabled title="The product is inactive, so issue quantity cannot be safely returned." style="padding:5px 8px; font-size:11px;">Delete issue</button><small>Product inactive — locked</small>`
                : '';
            const restoreAction = canRestoreProduct
                ? `<button type="button" class="btn-standard btn-primary" data-movement-id="${escapeGroceryHtml(movement.id)}" onclick="window.restoreGroceryProduct(this.dataset.movementId)" style="padding:5px 8px; font-size:11px;">Restore item</button>`
                : '';
            const actorText = voidedReceipt
                ? `${movement.actor || ''} (voided by ${movement.voidedBy || 'Chief Admin'})`
                : supersededReceipt
                    ? `${movement.actor || ''} (corrected by ${movement.correctedBy || 'Chief Admin'})`
                    : received && movement.metadataEditedBy
                        ? `${movement.actor || ''} (details edited by ${movement.metadataEditedBy})`
                    : movement.actor || '';
            const receiptDetails = received
                ? [`Packs: ${movement.receivedPacks == null ? '' : `${movement.receivedPacks} × ${movement.issuePackSize} ${movement.unit} @ ${groceryMoney(movement.pricePerPack)} / pack`}`, `Supplier/payee: ${movement.supplier || '—'}`, `Received by: ${movement.receivedBy || '—'}`, `Payment: ${movement.paymentMethod || '—'}`, movement.note, movement.voidReason ? `Void reason: ${movement.voidReason}` : '', movement.correctionReason ? `Correction reason: ${movement.correctionReason}` : '']
                : [movement.department, movement.note];
            return `<tr style="border-bottom:1px solid #ecf0f1;">
                <td style="padding:7px;">${escapeGroceryHtml(new Date(voidedReceipt ? movement.voidedAt || movement.date : movement.date).toLocaleString())}</td>
                <td style="padding:7px; color:${issued || voidedReceipt ? '#c0392b' : reversed || supersededReceipt ? '#b9770e' : '#1e8449'}; font-weight:bold;">${escapeGroceryHtml(String(movement.type || '').replace(/_/g, ' '))}</td>
                <td style="padding:7px;">${escapeGroceryHtml(`${movement.productName} / ${movement.category} / ${movement.term}`)}</td>
                <td style="padding:7px;">${escapeGroceryHtml(received ? movement.purchasedBy || '—' : movement.takenBy || '—')}</td>
                <td style="padding:7px;">${escapeGroceryHtml(receiptDetails.filter(Boolean).join(' · ') || '—')}</td>
                <td style="padding:7px; text-align:right;">${quantityText} ${escapeGroceryHtml(movement.unit || '')}${balanceText}</td>
                <td style="padding:7px; text-align:right;">${supersededReceipt ? 'Superseded · ' : ''}${groceryMoney(amount)}</td>
                <td style="padding:7px;">${escapeGroceryHtml(actorText)}</td>
                <td style="padding:7px;">${issued ? issueActions : receiptActions || restoreAction}</td>
            </tr>`;
        }).join('')
        : '<tr><td colspan="9" style="padding:10px; color:#7f8c8d;">No grocery history matches these filters.</td></tr>';
    window.renderGroceryAnalytics();
    window.renderGroceryReport();
    window.enableInventoryModuleSelectSearch('groceries');
};

window.loadGroceryData = async function() {
    if (!canOperateGroceries()) {
        showGroceryStatus('Access denied. School groceries is available to admin staff only.', true);
        return;
    }
    if (window.groceryDataLoading) return window.groceryDataLoading;
    window.groceryDataLoading = (async () => {
        window.groceryCloudReady = false;
        const today = groceryToday();
        ['groceryPurchaseDate', 'groceryIssueDate'].forEach(id => {
            const input = document.getElementById(id);
            if (input && !input.value) input.value = today;
        });
        const cached = localStorage.getItem(GROCERY_LOCAL_KEY);
        if (cached) {
            try {
                const localData = JSON.parse(cached);
                window.groceryInventory = Array.isArray(localData.inventory) ? localData.inventory : [];
                window.groceryMovements = Array.isArray(localData.movements) ? localData.movements : [];
                window.groceryReviews = Array.isArray(localData.reviews) ? localData.reviews : [];
                window.renderGroceryModule();
            } catch (error) {
                console.error('Invalid grocery cache:', error);
                showGroceryStatus('The local grocery cache is unreadable. Cloud data will be loaded; do not make changes until loading succeeds.', true);
            }
        }
        if (!navigator.onLine || !window.supabaseClient) {
            window.groceryDataLoaded = false;
            showGroceryStatus('Cannot verify current grocery stock while offline. Reconnect and reopen School groceries before making changes.', true);
            return;
        }
        try {
            const { data, error } = await window.supabaseClient
                .from(GROCERY_TABLE)
                .select('inventory,movements,reviews,last_updated')
                .eq('id', GROCERY_LEDGER_ID)
                .maybeSingle();
            if (error) throw error;
            const cloudData = data || {};
            ['inventory', 'movements', 'reviews'].forEach(key => {
                if (data && !Array.isArray(cloudData[key])) {
                    throw new Error(`The saved grocery ${key} list is invalid.`);
                }
            });
            const inventory = cloudData.inventory || [];
            const movements = cloudData.movements || [];
            const reviews = cloudData.reviews || [];
            const validInventory = inventory.every(item => {
                if (!item || item.id == null || !item.name || !item.category || !item.unit || !item.term ||
                    !Number.isFinite(Number(item.quantity)) || Number(item.quantity) < 0 ||
                    !Number.isFinite(Number(item.unitPrice)) || Number(item.unitPrice) < 0) return false;
                if (item.issuePackSize == null) return true;
                const packSize = Number(item.issuePackSize);
                return Number.isFinite(packSize) && packSize > 0 && groceryRound(packSize, 3) === packSize;
            });
            if (!validInventory) {
                throw new Error('The saved grocery inventory contains an invalid product or quantity.');
            }
            inventory.forEach(item => {
                if (item.issuePackSize == null) item.issuePackSize = 1;
            });
            if (![...movements, ...reviews].every(entry => entry && typeof entry === 'object' && !Array.isArray(entry))) {
                throw new Error('The saved grocery history contains an invalid record.');
            }
            window.groceryInventory = inventory;
            window.groceryMovements = movements;
            window.groceryReviews = reviews;
            window.groceryDataRevision = data ? data.last_updated : null;
            window.groceryDataLoaded = true;
            window.groceryCloudReady = true;
            localStorage.setItem(GROCERY_LOCAL_KEY, JSON.stringify({
                inventory: window.groceryInventory,
                movements: window.groceryMovements,
                reviews: window.groceryReviews
            }));
            window.renderGroceryModule();
            showGroceryStatus(data ? 'Grocery stock verified from cloud.' : 'Grocery stock is verified and empty. Record a school purchase to begin.', false);
        } catch (error) {
            window.groceryDataLoaded = false;
            window.groceryCloudReady = false;
            console.error('Grocery stock load failed:', error);
            const missingTable = error && ['42P01', 'PGRST205'].includes(error.code);
            showGroceryStatus(missingTable
                ? 'The separate Supabase grocery table is not installed. Run database/school_grocery_ledger.sql in the Supabase SQL Editor, then reopen School groceries.'
                : `Could not verify grocery stock from its Supabase table: ${error.message || 'Unknown database error'}. Changes are disabled to prevent using stale figures.`, true);
        }
    })();
    try {
        await window.groceryDataLoading;
    } finally {
        window.groceryDataLoading = null;
    }
};

async function saveGroceryData() {
    if (!window.groceryCloudReady || !navigator.onLine || !window.supabaseClient) {
        throw new Error('Current grocery stock is not verified online. Reopen School groceries while connected before changing quantities.');
    }
    const now = new Date().toISOString();
    const groceryData = {
        inventory: window.groceryInventory,
        movements: window.groceryMovements,
        reviews: window.groceryReviews
    };
    let response;
    if (window.groceryDataRevision) {
        response = await window.supabaseClient.from(GROCERY_TABLE)
            .update({ ...groceryData, last_updated: now })
            .eq('id', GROCERY_LEDGER_ID)
            .eq('last_updated', window.groceryDataRevision)
            .select('id');
        if (response.error) throw response.error;
        if (!response.data || response.data.length !== 1) {
            window.groceryCloudReady = false;
            throw new Error('Grocery stock changed in another session. Reload the section before trying again; no local change was saved.');
        }
    } else {
        response = await window.supabaseClient.from(GROCERY_TABLE)
            .insert({ id: GROCERY_LEDGER_ID, ...groceryData, last_updated: now })
            .select('id');
        if (response.error) {
            if (response.error.code === '23505') {
                window.groceryCloudReady = false;
                throw new Error('Another session initialized the grocery ledger. Reload the section before trying again.');
            }
            throw response.error;
        }
        if (!response.data || response.data.length !== 1) throw new Error('The database did not confirm the new grocery ledger.');
    }
    window.groceryDataRevision = now;
    localStorage.setItem(GROCERY_LOCAL_KEY, JSON.stringify(groceryData));
}

async function commitGroceryChange(change, successMessage, failureNextStep) {
    const previous = JSON.stringify({
        inventory: window.groceryInventory,
        movements: window.groceryMovements,
        reviews: window.groceryReviews
    });
    try {
        change();
        await saveGroceryData();
        window.renderGroceryModule();
        showGroceryStatus(successMessage || 'Grocery transaction saved and confirmed by cloud.', false);
    } catch (error) {
        const restored = JSON.parse(previous);
        window.groceryInventory = restored.inventory;
        window.groceryMovements = restored.movements;
        window.groceryReviews = restored.reviews;
        window.renderGroceryModule();
        showGroceryStatus(
            `Transaction failed; no grocery change was saved. ${error.message || 'Unknown database error'} Next: ${failureNextStep || 'Check the connection and reload current grocery stock before retrying.'}`,
            true
        );
        throw error;
    }
}

window.updateGroceryIssueEstimate = function() {
    const productId = document.getElementById('groceryIssueProduct')?.value;
    const item = window.groceryInventory.find(entry => String(entry.id) === String(productId));
    const quantity = Number(document.getElementById('groceryIssueQty')?.value);
    const available = document.getElementById('groceryIssueAvailable');
    const estimate = document.getElementById('groceryIssueValue');
    if (available) available.value = item ? groceryStockLabel(item) : '';
    if (estimate) estimate.value = item && quantity > 0 ? groceryMoney(quantity * (Number(item.unitPrice) || 0)) : '';
};

window.onGroceryIssueProductChange = function() {
    const productId = document.getElementById('groceryIssueProduct')?.value;
    const item = window.groceryInventory.find(entry => String(entry.id) === String(productId));
    const quantity = document.getElementById('groceryIssueQty');
    if (quantity) quantity.value = item ? String(groceryPackSize(item)) : '';
    window.updateGroceryIssueEstimate();
};

window.updateGroceryPurchaseEstimate = function() {
    const quantityText = document.getElementById('groceryPurchaseQty')?.value.trim();
    const priceText = document.getElementById('groceryPurchasePrice')?.value.trim();
    const total = document.getElementById('groceryPurchaseTotal');
    const quantity = Number(quantityText);
    const price = Number(priceText);
    if (total) total.value = quantityText && priceText && Number.isFinite(quantity) && quantity > 0 &&
        Number.isFinite(price) && price >= 0 ? groceryMoney(quantity * price) : '';
};

window.clearGroceryPurchaseForm = function() {
    ['groceryPurchaseProduct', 'groceryPurchaseCategory', 'groceryPurchaseUnit', 'groceryPurchaseTerm',
        'groceryPurchaseQty', 'groceryPurchasePrice', 'groceryPurchaseBuyer', 'groceryPurchaseReceivedBy',
        'groceryPurchaseSupplier', 'groceryPurchasePaymentMethod']
        .forEach(id => {
            const input = document.getElementById(id);
            if (input) input.value = '';
        });
    document.getElementById('groceryPurchasePackSize').value = '1';
    document.getElementById('groceryPurchaseDate').value = groceryToday();
    window.updateGroceryPurchaseEstimate();
    showGroceryStatus('Purchase form cleared. Saved grocery stock and purchase history were not changed.', false);
    document.getElementById('groceryPurchaseProduct').focus();
};

window.updateGroceryReceiptEditEstimate = function() {
    const packsText = document.getElementById('groceryReceiptEditPacks')?.value.trim();
    const priceText = document.getElementById('groceryReceiptEditPrice')?.value.trim();
    const total = document.getElementById('groceryReceiptEditTotal');
    const packs = Number(packsText);
    const price = Number(priceText);
    if (total) total.value = packsText && priceText && Number.isFinite(packs) && packs > 0 &&
        Number.isFinite(price) && price >= 0 ? groceryMoney(packs * price) : '';
};

window.editGroceryReceipt = function(movementId) {
    if (!canManageGroceryProducts()) return showGroceryStatus('Access denied. Only the Chief Admin can edit grocery purchase receipts.', true);
    if (!requireGroceryWriteAccess()) return;
    const movement = window.groceryMovements.find(entry =>
        String(entry.id) === String(movementId) && entry.type === 'RECEIVED'
    );
    if (!movement) return showGroceryStatus('Purchase receipt not found. Reload grocery history and try again.', true);
    const item = window.groceryInventory.find(entry => String(entry.id) === String(movement.productId));
    const canChangeStock = canCorrectGroceryReceipt(movement) && Boolean(item);
    const packSize = Number(movement.issuePackSize);
    const packs = Number(movement.receivedPacks);
    const quantity = Number(movement.quantity);
    const pricePerPack = Number(movement.pricePerPack);
    const date = String(movement.date || '').slice(0, 10);
    if (!Number.isFinite(packSize) || packSize <= 0 || !Number.isFinite(packs) || packs <= 0 ||
        !Number.isFinite(quantity) || quantity <= 0 || Math.abs(groceryRound(packSize * packs, 3) - quantity) > 1e-9 ||
        groceryRound(packSize, 3) !== packSize || groceryRound(packs, 3) !== packs ||
        !Number.isFinite(pricePerPack) || pricePerPack < 0 || groceryRound(pricePerPack, 2) !== pricePerPack ||
        !groceryDateIsValid(date)) {
        return showGroceryStatus('This receipt has invalid saved quantities, price, or date and cannot be safely edited.', true);
    }
    document.getElementById('groceryReceiptEditId').value = movement.id;
    const productLabel = item ? groceryProductLabel(item) : groceryProductLabel(movement);
    document.getElementById('groceryReceiptEditProduct').textContent = `Product: ${productLabel}`;
    document.getElementById('groceryReceiptEditLockHint').textContent = canChangeStock
        ? 'This is the latest stock movement, so quantities, pack size, and price can be corrected.'
        : 'Later stock activity exists. You can edit the date, purchaser, receiver, supplier, or payment method; stock quantity, pack size, price, and void are locked.';
    document.getElementById('groceryReceiptEditPackSize').value = String(packSize);
    document.getElementById('groceryReceiptEditPackSize').readOnly = !canChangeStock;
    document.getElementById('groceryReceiptEditPacks').value = String(packs);
    document.getElementById('groceryReceiptEditPacks').readOnly = !canChangeStock;
    document.getElementById('groceryReceiptEditPrice').value = String(pricePerPack);
    document.getElementById('groceryReceiptEditPrice').readOnly = !canChangeStock;
    document.getElementById('groceryReceiptEditDate').value = date;
    document.getElementById('groceryReceiptEditBuyer').value = movement.purchasedBy || '';
    document.getElementById('groceryReceiptEditReceivedBy').value = movement.receivedBy || '';
    document.getElementById('groceryReceiptEditSupplier').value = movement.supplier || '';
    document.getElementById('groceryReceiptEditPaymentMethod').value = movement.paymentMethod || '';
    document.getElementById('groceryReceiptEditReason').value = '';
    window.updateGroceryReceiptEditEstimate();
    document.getElementById('groceryReceiptEditModal').style.display = 'flex';
};

window.closeGroceryReceiptEditModal = function() {
    const modal = document.getElementById('groceryReceiptEditModal');
    if (modal) modal.style.display = 'none';
};

window.saveGroceryReceiptEdit = async function() {
    if (!canManageGroceryProducts()) return showGroceryStatus('Access denied. Only the Chief Admin can edit grocery purchase receipts.', true);
    if (!requireGroceryWriteAccess()) return;
    const movementId = document.getElementById('groceryReceiptEditId').value;
    const movement = window.groceryMovements.find(entry =>
        String(entry.id) === String(movementId) && entry.type === 'RECEIVED'
    );
    if (!movement) return showGroceryStatus('Purchase receipt not found. Reload grocery history before saving.', true);
    const item = window.groceryInventory.find(entry => String(entry.id) === String(movement.productId));
    const canChangeStock = canCorrectGroceryReceipt(movement) && Boolean(item);
    const packSizeText = document.getElementById('groceryReceiptEditPackSize').value.trim();
    const packSize = Number(packSizeText);
    const packsText = document.getElementById('groceryReceiptEditPacks').value.trim();
    const packs = Number(packsText);
    const priceText = document.getElementById('groceryReceiptEditPrice').value.trim();
    const pricePerPack = Number(priceText);
    const date = document.getElementById('groceryReceiptEditDate').value;
    const purchasedBy = document.getElementById('groceryReceiptEditBuyer').value.trim();
    const receivedBy = document.getElementById('groceryReceiptEditReceivedBy').value.trim();
    const supplier = document.getElementById('groceryReceiptEditSupplier').value.trim();
    const paymentMethod = document.getElementById('groceryReceiptEditPaymentMethod').value;
    const reason = document.getElementById('groceryReceiptEditReason').value.trim();
    if (!packSizeText || !Number.isFinite(packSize) || packSize <= 0 || groceryRound(packSize, 3) !== packSize) {
        return showGroceryStatus('Pack size must be greater than zero and use no more than 3 decimal places.', true);
    }
    if (!packsText || !Number.isFinite(packs) || packs <= 0 || groceryRound(packs, 3) !== packs) {
        return showGroceryStatus('Number of packs must be greater than zero and use no more than 3 decimal places.', true);
    }
    const quantityExact = packs * packSize;
    if (!Number.isFinite(quantityExact) || quantityExact <= 0 ||
        Math.abs(groceryRound(quantityExact, 3) - quantityExact) > 1e-9) {
        return showGroceryStatus('Pack count × pack size must result in a base quantity with no more than 3 decimal places.', true);
    }
    if (!priceText || !Number.isFinite(pricePerPack) || pricePerPack < 0 || groceryRound(pricePerPack, 2) !== pricePerPack) {
        return showGroceryStatus('Enter a valid non-negative price per pack in cents.', true);
    }
    if (!groceryDateIsValid(date) || date > groceryToday()) return showGroceryStatus('Select a valid purchase / received date that is not in the future.', true);
    if (!purchasedBy || !receivedBy || !supplier || !paymentMethod) {
        return showGroceryStatus('Purchased by, goods received by, supplier / payee, and payment method are required.', true);
    }
    if (!reason || reason.length > 300) return showGroceryStatus('A correction reason of 1–300 characters is required.', true);

    const quantity = groceryRound(quantityExact, 3);
    const unitPrice = groceryRound(pricePerPack / packSize, 8);
    const totalValue = groceryRound(quantity * unitPrice, 2);
    const originalQuantity = Number(movement.quantity);
    const originalTotal = groceryReceiptTotal(movement);
    const originalPackSize = Number(movement.issuePackSize);
    const originalPacks = Number(movement.receivedPacks);
    const originalPricePerPack = Number(movement.pricePerPack);
    const stockFieldsChanged = packSize !== originalPackSize || packs !== originalPacks || pricePerPack !== originalPricePerPack;
    if (stockFieldsChanged && !canChangeStock) {
        return showGroceryStatus('Stock quantity, pack size, and price cannot be changed after later stock activity. Only receipt details can be edited.', true);
    }
    if (!stockFieldsChanged) {
        const previousDetails = {
            date: movement.date,
            purchasedBy: movement.purchasedBy || '',
            receivedBy: movement.receivedBy || '',
            supplier: movement.supplier || '',
            paymentMethod: movement.paymentMethod || ''
        };
        const detailsChanged = previousDetails.date !== groceryDateTime(date) ||
            previousDetails.purchasedBy !== purchasedBy || previousDetails.receivedBy !== receivedBy ||
            previousDetails.supplier !== supplier || previousDetails.paymentMethod !== paymentMethod;
        if (!detailsChanged) return showGroceryStatus('No receipt details were changed.', true);
        const actor = groceryActorName();
        const editedAt = new Date().toISOString();
        const previousSummary = `Previous details: date ${String(previousDetails.date || '').slice(0, 10)}, purchased by ${previousDetails.purchasedBy || '—'}, received by ${previousDetails.receivedBy || '—'}, supplier ${previousDetails.supplier || '—'}, payment ${previousDetails.paymentMethod || '—'}.`;
        try {
            await commitGroceryChange(() => {
                const edits = Array.isArray(movement.detailEdits) ? movement.detailEdits.slice() : [];
                edits.push({ editedAt, actor, reason, previousDetails });
                movement.detailEdits = edits;
                Object.assign(movement, {
                    date: groceryDateTime(date),
                    purchasedBy,
                    receivedBy,
                    supplier,
                    paymentMethod,
                    metadataEditedAt: editedAt,
                    metadataEditedBy: actor,
                    correctionReason: reason,
                    note: `${movement.note ? `${movement.note} · ` : ''}Receipt details edited by ${actor}. ${previousSummary} Reason: ${reason}`
                });
            },
            'Purchase receipt details corrected and synced. Previous details and the reason remain in the audit history.',
            'Reload current grocery stock and history before retrying the correction.');
            window.closeGroceryReceiptEditModal();
        } catch (error) {
            console.error('Grocery purchase receipt details correction failed:', error);
        }
        return;
    }
    if (!item) return showGroceryStatus('This product is no longer active, so stock values cannot be changed for its receipt.', true);
    const currentQuantity = Number(item.quantity);
    const currentUnitPrice = Number(item.unitPrice);
    if (!Number.isFinite(originalQuantity) || originalQuantity <= 0 ||
        !Number.isFinite(currentQuantity) || currentQuantity < originalQuantity ||
        !Number.isFinite(currentUnitPrice) || currentUnitPrice < 0) {
        return showGroceryStatus('Current stock no longer supports this correction. No receipt or stock changes were saved.', true);
    }
    const nextQuantity = groceryRound(currentQuantity - originalQuantity + quantity, 3);
    const nextValue = groceryRound(groceryRound(currentQuantity * currentUnitPrice, 2) - originalTotal + totalValue, 2);
    if (nextQuantity <= 0 || nextValue < 0) {
        return showGroceryStatus('This correction would create an invalid stock balance or inventory value. No changes were saved.', true);
    }
    const nextUnitPrice = groceryRound(nextValue / nextQuantity, 8);
    const correctionId = `GRM-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const actor = groceryActorName();
    const correctedMovement = {
        ...movement,
        id: correctionId,
        type: 'RECEIVED',
        receivedPacks: groceryRound(packs, 3),
        issuePackSize: packSize,
        pricePerPack: groceryRound(pricePerPack, 2),
        quantity,
        stockAfter: nextQuantity,
        unitPrice,
        totalValue,
        purchasedBy,
        receivedBy,
        supplier,
        paymentMethod,
        date: groceryDateTime(date),
        actor,
        correctionOf: movement.id,
        correctionReason: reason,
        note: `Corrected receipt ${movement.id}. Reason: ${reason}`
    };
    try {
        await commitGroceryChange(() => {
            item.quantity = nextQuantity;
            item.unitPrice = nextUnitPrice;
            item.issuePackSize = packSize;
            movement.type = 'RECEIPT_EDITED';
            movement.correctedAt = new Date().toISOString();
            movement.correctedBy = actor;
            movement.correctionReason = reason;
            movement.replacedBy = correctionId;
            movement.note = `${movement.note ? `${movement.note} · ` : ''}Superseded by ${correctionId}. Reason: ${reason}`;
            window.groceryMovements.push(correctedMovement);
        },
        'Purchase receipt corrected and synced. The original details remain in history, and reports use the corrected receipt. Next: verify stock and the receipt history.',
        'Reload current grocery stock and history before retrying the correction.');
        window.closeGroceryReceiptEditModal();
    } catch (error) {
        console.error('Grocery purchase receipt correction failed:', error);
    }
};

window.voidGroceryReceipt = async function(movementId) {
    if (!canManageGroceryProducts()) return showGroceryStatus('Access denied. Only the Chief Admin can void grocery purchase receipts.', true);
    if (!requireGroceryWriteAccess()) return;
    const movement = window.groceryMovements.find(entry =>
        String(entry.id) === String(movementId) && entry.type === 'RECEIVED'
    );
    if (!movement) return showGroceryStatus('Purchase receipt not found. Reload grocery history and try again.', true);
    if (!canCorrectGroceryReceipt(movement)) {
        return showGroceryStatus('This receipt cannot be voided while later stock movements exist. Correct or void those later movements first.', true);
    }
    const item = window.groceryInventory.find(entry => String(entry.id) === String(movement.productId));
    if (!item) return showGroceryStatus('This product is no longer active, so its receipt cannot be voided.', true);
    const quantity = Number(movement.quantity);
    const totalValue = groceryReceiptTotal(movement);
    const currentQuantity = Number(item.quantity);
    const currentUnitPrice = Number(item.unitPrice);
    if (!Number.isFinite(quantity) || quantity <= 0 || !Number.isFinite(currentQuantity) ||
        currentQuantity < quantity || !Number.isFinite(currentUnitPrice) || currentUnitPrice < 0) {
        return showGroceryStatus('Current stock no longer supports this receipt reversal. No changes were saved.', true);
    }
    const nextQuantity = groceryRound(currentQuantity - quantity, 3);
    const nextValue = groceryRound(groceryRound(currentQuantity * currentUnitPrice, 2) - totalValue, 2);
    if (nextQuantity < 0 || nextValue < 0 || (nextQuantity === 0 && nextValue !== 0)) {
        return showGroceryStatus('Voiding this receipt would create an invalid stock balance or inventory value. No changes were saved.', true);
    }
    const reason = window.prompt(`Why are you voiding the ${movement.receivedPacks} pack receipt for ${movement.productName}? Its stock will be removed and the original receipt will remain in the audit history.`);
    if (reason === null) return;
    if (!reason.trim() || reason.trim().length > 300) return showGroceryStatus('A void reason of 1–300 characters is required.', true);
    if (!window.confirm(`Void this receipt and remove ${quantity} ${movement.unit} of ${movement.productName} from stock? The audit history will be retained.`)) return;
    const actor = groceryActorName();
    const voidedAt = new Date().toISOString();
    const nextUnitPrice = nextQuantity > 0 ? groceryRound(Math.max(0, nextValue) / nextQuantity, 8) : 0;
    const restoredPackSize = groceryPackSizeBeforeReceipt(movement);
    try {
        await commitGroceryChange(() => {
            item.quantity = nextQuantity;
            item.unitPrice = nextUnitPrice;
            item.issuePackSize = restoredPackSize;
            movement.type = 'RECEIPT_VOIDED';
            movement.originalStockAfter = movement.stockAfter;
            movement.stockAfter = nextQuantity;
            movement.voidedAt = voidedAt;
            movement.voidedBy = actor;
            movement.voidReason = reason.trim();
            movement.restoredIssuePackSize = restoredPackSize;
            movement.note = `${movement.note ? `${movement.note} · ` : ''}Receipt voided by ${actor}. Issue pack size restored to ${restoredPackSize} ${item.unit} per pack. Reason: ${reason.trim()}`;
        },
        'Purchase receipt voided and synced. Its stock was removed, and the original receipt remains in history with the reason. Next: verify the balance and void record.',
        'Reload current grocery stock and history before retrying the receipt reversal.');
    } catch (error) {
        console.error('Grocery purchase receipt void failed:', error);
    }
};

window.receiveGroceryStock = async function() {
    if (!requireGroceryWriteAccess()) return;
    const name = document.getElementById('groceryPurchaseProduct').value.trim();
    const category = document.getElementById('groceryPurchaseCategory').value.trim();
    const unit = document.getElementById('groceryPurchaseUnit').value.trim();
    const packSizeText = document.getElementById('groceryPurchasePackSize').value.trim();
    const packSize = Number(packSizeText);
    const term = document.getElementById('groceryPurchaseTerm').value;
    const quantityText = document.getElementById('groceryPurchaseQty').value.trim();
    const packCount = Number(quantityText);
    const priceText = document.getElementById('groceryPurchasePrice').value.trim();
    const pricePerPack = Number(priceText);
    const receivedQuantityExact = packCount * packSize;
    const date = document.getElementById('groceryPurchaseDate').value;
    const purchasedBy = document.getElementById('groceryPurchaseBuyer').value.trim();
    const receivedBy = document.getElementById('groceryPurchaseReceivedBy').value.trim();
    const supplier = document.getElementById('groceryPurchaseSupplier').value.trim();
    const paymentMethod = document.getElementById('groceryPurchasePaymentMethod').value;
    if (!name || !category || !unit || !term) return showGroceryStatus('Product, type, base unit, and term are required.', true);
    if (!packSizeText || !Number.isFinite(packSize) || packSize <= 0 || groceryRound(packSize, 3) !== packSize) return showGroceryStatus('Pack size must be greater than zero and use no more than 3 decimal places.', true);
    if (!quantityText || !Number.isFinite(packCount) || packCount <= 0 || groceryRound(packCount, 3) !== packCount) return showGroceryStatus('Number of packs must be greater than zero and use no more than 3 decimal places.', true);
    if (!Number.isFinite(receivedQuantityExact) || receivedQuantityExact <= 0 ||
        Math.abs(groceryRound(receivedQuantityExact, 3) - receivedQuantityExact) > 1e-9) return showGroceryStatus('Pack count × pack size must result in a base quantity with no more than 3 decimal places.', true);
    if (!priceText || !Number.isFinite(pricePerPack) || pricePerPack < 0 || groceryRound(pricePerPack, 2) !== pricePerPack) return showGroceryStatus('Enter a valid price per pack in cents (for example 0.50).', true);
    if (!purchasedBy || !receivedBy || !supplier || !paymentMethod) return showGroceryStatus('Purchased by, goods received by, supplier / payee, and payment method are required.', true);
    if (!groceryDateIsValid(date)) return showGroceryStatus('Select a valid purchase / received date.', true);
    if (date > groceryToday()) return showGroceryStatus('A purchase / received date cannot be in the future.', true);
    const quantity = groceryRound(receivedQuantityExact, 3);
    const unitPrice = groceryRound(pricePerPack / packSize, 8);
    const normalized = value => String(value).trim().toLowerCase();
    const existing = window.groceryInventory.find(item =>
        normalized(item.name) === normalized(name) && normalized(item.category) === normalized(category) &&
        normalized(item.unit) === normalized(unit) && normalized(item.term) === normalized(term)
    );
    const movement = {
        id: `GRM-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        type: 'RECEIVED',
        productId: existing ? existing.id : `GRP-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        productName: name,
        category,
        unit,
        issuePackSize: packSize,
        term,
        receivedPacks: groceryRound(packCount, 3),
        pricePerPack: groceryRound(pricePerPack, 2),
        quantity,
        stockAfter: groceryRound(((existing && Number(existing.quantity)) || 0) + quantity, 3),
        unitPrice,
        totalValue: groceryRound(quantity * unitPrice, 2),
        purchasedBy,
        receivedBy,
        supplier,
        paymentMethod,
        date: groceryDateTime(date),
        actor: groceryActorName()
    };
    try {
        await commitGroceryChange(() => {
            if (existing) {
                const oldQuantity = Number(existing.quantity) || 0;
                const newQuantity = oldQuantity + movement.quantity;
                existing.issuePackSize = packSize;
                existing.unitPrice = newQuantity > 0
                    ? groceryRound((oldQuantity * Number(existing.unitPrice) + movement.quantity * movement.unitPrice) / newQuantity, 8)
                    : movement.unitPrice;
                existing.quantity = groceryRound(newQuantity, 3);
            } else {
                window.groceryInventory.push({
                    id: movement.productId, name, category, unit, issuePackSize: packSize, term,
                    quantity: movement.quantity, unitPrice: movement.unitPrice
                });
            }
            window.groceryMovements.push(movement);
        },
        'Purchase recorded and synced. Stock and purchase history have been updated. Next: verify the balance in the stock table.',
        'Check the connection and reload current stock before recording this purchase again.');
        ['groceryPurchaseProduct', 'groceryPurchaseCategory', 'groceryPurchaseUnit', 'groceryPurchaseQty', 'groceryPurchasePrice',
            'groceryPurchaseBuyer', 'groceryPurchaseReceivedBy', 'groceryPurchaseSupplier']
            .forEach(id => { document.getElementById(id).value = ''; });
        document.getElementById('groceryPurchasePackSize').value = '1';
        document.getElementById('groceryPurchasePaymentMethod').value = '';
        window.updateGroceryPurchaseEstimate();
    } catch (error) {
        console.error('Grocery purchase receipt failed:', error);
    }
};

window.addGroceryIssueItem = function(productId, quantityOverride) {
    if (!requireGroceryWriteAccess()) return false;
    const select = document.getElementById('groceryIssueProduct');
    const quantityInput = document.getElementById('groceryIssueQty');
    const selectedId = productId || select.value;
    const item = window.groceryInventory.find(entry => String(entry.id) === String(selectedId));
    if (!item) {
        showGroceryStatus('Select an available grocery product.', true);
        return false;
    }
    const quantityText = quantityOverride == null ? quantityInput.value.trim() : String(quantityOverride);
    const quantity = Number(quantityText);
    if (!quantityText || !Number.isFinite(quantity) || quantity <= 0 || groceryRound(quantity, 3) !== quantity) {
        showGroceryStatus('Issue quantity must be greater than zero and use no more than 3 decimal places.', true);
        return false;
    }
    const existing = window.groceryIssueCart.find(line => String(line.productId) === String(item.id));
    const totalQuantity = quantity + (existing ? Number(existing.quantity) : 0);
    if (totalQuantity > Number(item.quantity)) {
        showGroceryStatus(`Insufficient stock. ${groceryStockLabel(item)} are available; the listed quantity would exceed this.`, true);
        return false;
    }
    if (existing) existing.quantity = groceryRound(totalQuantity, 3);
    else window.groceryIssueCart.push({ productId: item.id, quantity: groceryRound(quantity, 3) });
    if (quantityOverride == null) quantityInput.value = '';
    window.updateGroceryIssueEstimate();
    renderGroceryIssueCart();
    showGroceryStatus(`${item.name} added to the issue request. Stock will change only when the full request is approved.`, false);
    return true;
};

window.quickAddGroceryProduct = function(productId) {
    const item = window.groceryInventory.find(entry => String(entry.id) === String(productId));
    if (!item) return showGroceryStatus('Grocery product not found. Reload stock and try again.', true);
    return window.addGroceryIssueItem(item.id, groceryPackSize(item));
};

window.updateGroceryIssueCartQuantity = function(index, quantityText) {
    const line = window.groceryIssueCart[index];
    if (!line) return;
    const item = window.groceryInventory.find(entry => String(entry.id) === String(line.productId));
    const quantity = Number(quantityText);
    if (!item || !Number.isFinite(quantity) || quantity <= 0 || groceryRound(quantity, 3) !== quantity) {
        showGroceryStatus('Each issue quantity must be greater than zero and use no more than 3 decimal places.', true);
        renderGroceryIssueCart();
        return;
    }
    if (quantity > Number(item.quantity)) {
        showGroceryStatus(`Insufficient stock. ${groceryStockLabel(item)} are available.`, true);
        renderGroceryIssueCart();
        return;
    }
    line.quantity = groceryRound(quantity, 3);
    renderGroceryIssueCart();
    showGroceryStatus(`${item.name} quantity updated in the draft request. Stock is unchanged until approval.`, false);
};

window.removeGroceryIssueItem = function(index) {
    if (!Number.isInteger(index) || index < 0 || index >= window.groceryIssueCart.length) return;
    const line = window.groceryIssueCart[index];
    const item = window.groceryInventory.find(entry => String(entry.id) === String(line.productId));
    window.groceryIssueCart.splice(index, 1);
    renderGroceryIssueCart();
    showGroceryStatus(`${item ? item.name : 'Product'} removed from the draft request. Stock is unchanged.`, false);
};

window.issueGroceryStock = async function() {
    if (window.groceryIssueSaving) return;
    if (!requireGroceryWriteAccess()) return;
    const takenBy = document.getElementById('groceryIssueTakenBy').value.trim();
    const department = document.getElementById('groceryIssueDepartment').value.trim();
    const date = document.getElementById('groceryIssueDate').value;
    const note = document.getElementById('groceryIssueNote').value.trim();
    if (!window.groceryIssueCart.length) return showGroceryStatus('Add at least one product to the issue request.', true);
    if (!takenBy || !department) return showGroceryStatus('Requested / taken by and department are required.', true);
    if (!groceryDateIsValid(date)) return showGroceryStatus('Select a valid issue date.', true);
    if (date > groceryToday()) return showGroceryStatus('An issue date cannot be in the future.', true);
    const lines = window.groceryIssueCart.map(line => ({
        line,
        item: window.groceryInventory.find(entry => String(entry.id) === String(line.productId))
    }));
    for (const { line, item } of lines) {
        const quantity = Number(line.quantity);
        if (!item) return showGroceryStatus('A listed product is no longer active. Remove it before submitting.', true);
        if (!Number.isFinite(quantity) || quantity <= 0 || groceryRound(quantity, 3) !== quantity) return showGroceryStatus('Each issue quantity must be greater than zero and use no more than 3 decimal places.', true);
        if (quantity > Number(item.quantity)) return showGroceryStatus(`Insufficient stock for ${item.name}. ${groceryStockLabel(item)} are available.`, true);
    }
    const totalEstimate = lines.reduce((sum, { line, item }) => sum + Number(line.quantity) * (Number(item.unitPrice) || 0), 0);
    if (!window.confirm(`Approve ${lines.length} product line(s), estimated at ${groceryMoney(totalEstimate)}, and deduct them from grocery stock?`)) return;
    const foodStudents = getFoodProgramStudentCount();
    const batchId = `GRB-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const movements = lines.map(({ line, item }) => ({
        id: `GRM-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        batchId,
        type: 'ISSUED',
        productId: item.id,
        productName: item.name,
        category: item.category,
        unit: item.unit,
        issuePackSize: groceryPackSize(item),
        term: item.term,
        quantity: groceryRound(Number(line.quantity), 3),
        stockAfter: groceryRound(Number(item.quantity) - Number(line.quantity), 3),
        unitPrice: Number(item.unitPrice) || 0,
        totalValue: groceryRound(Number(line.quantity) * (Number(item.unitPrice) || 0), 2),
        foodStudents,
        takenBy,
        department,
        note,
        date: groceryDateTime(date),
        actor: groceryActorName()
    }));
    const submitButton = document.getElementById('groceryIssueSubmitButton');
    const originalButtonText = submitButton ? submitButton.textContent : '';
    window.groceryIssueSaving = true;
    if (submitButton) {
        submitButton.disabled = true;
        submitButton.textContent = 'Saving issue...';
    }
    showGroceryStatus('Saving the grocery issue and verifying it with the cloud. Please wait.', false, 'Saving');
    try {
        await commitGroceryChange(() => {
            lines.forEach(({ line, item }) => {
                item.quantity = groceryRound(Number(item.quantity) - Number(line.quantity), 3);
            });
            window.groceryMovements.push(...movements);
        },
        'Issue approved and synced. The listed quantities were deducted from stock and recorded in history. Next: check the updated balance or issue history.',
        'Check current stock and the issue list, then reload verified grocery data before trying again.');
        window.groceryIssueCart = [];
        ['groceryIssueQty', 'groceryIssueTakenBy', 'groceryIssueDepartment', 'groceryIssueNote']
            .forEach(id => { document.getElementById(id).value = ''; });
        window.renderGroceryModule();
    } catch (error) {
        console.error('Grocery issue was not completed:', error);
    } finally {
        window.groceryIssueSaving = false;
        if (submitButton) {
            submitButton.disabled = false;
            submitButton.textContent = originalButtonText;
        }
    }
};

window.editGroceryProduct = function(productId) {
    if (!canManageGroceryProducts()) return showGroceryStatus('Access denied. Only the Chief Admin can edit grocery products.', true);
    if (!requireGroceryWriteAccess()) return;
    const item = window.groceryInventory.find(entry => String(entry.id) === String(productId));
    if (!item) return showGroceryStatus('Grocery product not found. Reload the section and try again.', true);
    document.getElementById('groceryEditId').value = item.id;
    document.getElementById('groceryEditName').value = item.name;
    document.getElementById('groceryEditCategory').value = item.category;
    document.getElementById('groceryEditUnit').value = item.unit;
    document.getElementById('groceryEditPackSize').value = groceryPackSize(item);
    document.getElementById('groceryEditTerm').value = item.term;
    document.getElementById('groceryEditQty').value = item.quantity;
    document.getElementById('groceryEditPrice').value = item.unitPrice;
    document.getElementById('groceryEditReason').value = '';
    document.getElementById('groceryEditModal').style.display = 'flex';
};

window.closeGroceryEditModal = function() {
    const modal = document.getElementById('groceryEditModal');
    if (modal) modal.style.display = 'none';
};

window.saveGroceryProductEdit = async function() {
    if (!canManageGroceryProducts()) return showGroceryStatus('Access denied. Only the Chief Admin can edit grocery products.', true);
    if (!requireGroceryWriteAccess()) return;
    const id = document.getElementById('groceryEditId').value;
    const name = document.getElementById('groceryEditName').value.trim();
    const category = document.getElementById('groceryEditCategory').value.trim();
    const unit = document.getElementById('groceryEditUnit').value.trim();
    const packSizeText = document.getElementById('groceryEditPackSize').value.trim();
    const packSize = Number(packSizeText);
    const term = document.getElementById('groceryEditTerm').value;
    const quantityText = document.getElementById('groceryEditQty').value.trim();
    const quantity = Number(quantityText);
    const priceText = document.getElementById('groceryEditPrice').value.trim();
    const unitPrice = Number(priceText);
    const reason = document.getElementById('groceryEditReason').value.trim();
    const item = window.groceryInventory.find(entry => String(entry.id) === String(id));
    if (!item) return showGroceryStatus('Grocery product not found. Reload the section before editing.', true);
    if (!name || !category || !unit || !term) return showGroceryStatus('Product, type, base unit, and term are required.', true);
    if (!packSizeText || !Number.isFinite(packSize) || packSize <= 0 || groceryRound(packSize, 3) !== packSize) return showGroceryStatus('Issue pack size must be greater than zero and use no more than 3 decimal places.', true);
    if (!quantityText || !Number.isFinite(quantity) || quantity < 0 || groceryRound(quantity, 3) !== quantity) return showGroceryStatus('Quantity must be zero or greater and use no more than 3 decimal places.', true);
    if (!priceText || !Number.isFinite(unitPrice) || unitPrice < 0 || groceryRound(unitPrice, 8) !== unitPrice) return showGroceryStatus('Enter a valid non-negative price per base unit with no more than 8 decimal places.', true);
    if (!reason || reason.length > 300) return showGroceryStatus('A reason of 1–300 characters is required.', true);
    const normalized = value => String(value).trim().toLowerCase();
    const duplicate = window.groceryInventory.find(entry => String(entry.id) !== String(id) &&
        normalized(entry.name) === normalized(name) && normalized(entry.category) === normalized(category) &&
        normalized(entry.unit) === normalized(unit) && normalized(entry.term) === normalized(term));
    if (duplicate) return showGroceryStatus('Another product already uses this name, type, unit, and term. Edit that record instead.', true);
    const previous = { name: item.name, category: item.category, unit: item.unit, issuePackSize: groceryPackSize(item), term: item.term, quantity: Number(item.quantity), unitPrice: Number(item.unitPrice) };
    if (previous.name === name && previous.category === category && previous.unit === unit &&
        previous.issuePackSize === packSize &&
        previous.term === term && previous.quantity === quantity && previous.unitPrice === unitPrice) {
        return showGroceryStatus('No changes were made to this grocery product.', true);
    }
    const delta = groceryRound(quantity - previous.quantity, 3);
    const movement = {
        id: `GRM-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        type: delta ? 'ADJUSTMENT' : 'PRODUCT_EDITED',
        productId: item.id,
        productName: name,
        category,
        unit,
        issuePackSize: packSize,
        term,
        quantity: delta,
        stockAfter: quantity,
        unitPrice,
        totalValue: groceryRound(Math.abs(delta) * unitPrice, 2),
        note: `Name "${previous.name}" -> "${name}", type "${previous.category}" -> "${category}", unit "${previous.unit}" -> "${unit}", issue pack size ${previous.issuePackSize} -> ${packSize}, term "${previous.term}" -> "${term}"; quantity ${previous.quantity} -> ${quantity}; unit price ${previous.unitPrice} -> ${unitPrice}. Reason: ${reason}`,
        date: new Date().toISOString(),
        actor: groceryActorName()
    };
    try {
        await commitGroceryChange(() => {
            Object.assign(item, { name, category, unit, issuePackSize: packSize, term, quantity, unitPrice });
            window.groceryMovements.push(movement);
        },
        'Product changes saved and synced. The audited product details and stock are updated. Next: verify the product in the stock table.',
        'Reload current grocery stock and product details before retrying the edit.');
        window.closeGroceryEditModal();
    } catch (error) {
        console.error('Grocery product edit failed:', error);
    }
};

window.deleteGroceryIssueMovement = async function(movementId) {
    if (!canManageGroceryProducts()) return showGroceryStatus('Access denied. Only the Chief Admin can delete grocery issue history.', true);
    if (!requireGroceryWriteAccess()) return;
    const movement = window.groceryMovements.find(entry =>
        String(entry.id) === String(movementId) && entry.type === 'ISSUED'
    );
    if (!movement) return showGroceryStatus('Grocery issue record not found. Reload the history and try again.', true);
    const item = window.groceryInventory.find(entry => String(entry.id) === String(movement.productId));
    if (!item) return showGroceryStatus('This product is no longer active, so its issue cannot be returned to stock.', true);
    const quantity = Number(movement.quantity);
    const nextQuantity = groceryRound(Number(item.quantity) + quantity, 3);
    if (!Number.isFinite(quantity) || quantity <= 0 || !Number.isFinite(nextQuantity)) {
        return showGroceryStatus('The issue record or current stock quantity is invalid; no history was changed.', true);
    }
    const reason = window.prompt(`Why are you deleting this ${movement.quantity} ${movement.unit} issue for ${movement.productName}? Its quantity will be returned to stock, and an audit reversal will be kept.`);
    if (reason === null) return;
    if (!reason.trim() || reason.trim().length > 300) return showGroceryStatus('A deletion reason of 1–300 characters is required.', true);
    if (!window.confirm(`Delete this issue from history and restore ${movement.quantity} ${movement.unit} to ${movement.productName} stock? The main financial records will not be changed.`)) return;
    const reversal = {
        id: `GRM-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        type: 'ISSUE_REVERSED',
        reversalOf: movement.id,
        batchId: movement.batchId || null,
        productId: item.id,
        productName: item.name,
        category: item.category,
        unit: item.unit,
        issuePackSize: groceryPackSize(item),
        term: item.term,
        quantity: groceryRound(quantity, 3),
        stockAfter: nextQuantity,
        unitPrice: Number(item.unitPrice) || 0,
        totalValue: groceryRound(quantity * (Number(item.unitPrice) || 0), 2),
        takenBy: movement.takenBy || '',
        department: movement.department || '',
        foodStudents: Number(movement.foodStudents) || 0,
        note: `Issue ${movement.id} removed by Chief Admin and returned to active stock. Original issue date: ${movement.date}. Reason: ${reason.trim()}`,
        date: new Date().toISOString(),
        actor: groceryActorName()
    };
    try {
        await commitGroceryChange(() => {
            item.quantity = nextQuantity;
            window.groceryMovements = window.groceryMovements.filter(entry => String(entry.id) !== String(movement.id));
            window.groceryMovements.push(reversal);
        },
        'Issue removed and synced. Its quantity was returned to stock and an audit reversal was recorded. Next: verify the balance and reversal in history.',
        'Reload issue history and current stock before attempting the reversal again.');
    } catch (error) {
        console.error('Grocery issue history deletion failed:', error);
    }
};

window.clearGroceryProductStock = async function(productId) {
    if (!canManageGroceryProducts()) return showGroceryStatus('Access denied. Only the Chief Admin can clear grocery stock.', true);
    if (!requireGroceryWriteAccess()) return;
    const item = window.groceryInventory.find(entry => String(entry.id) === String(productId));
    if (!item) return showGroceryStatus('Grocery product not found. Reload the section and try again.', true);
    const quantity = Number(item.quantity);
    if (!Number.isFinite(quantity) || quantity < 0 || groceryRound(quantity, 3) !== quantity) return showGroceryStatus('The current stock quantity is invalid; no stock was cleared.', true);
    if (quantity === 0) return showGroceryStatus('This product already has zero stock. Use Delete if you want to remove the empty product.', false);
    const value = groceryRound(quantity * (Number(item.unitPrice) || 0), 2);
    const reason = window.prompt(`Why are you clearing ${quantity} ${item.unit} of ${item.name}? The stock write-off will be recorded.`);
    if (reason === null) return;
    if (!reason.trim() || reason.trim().length > 300) return showGroceryStatus('A clear-stock reason of 1–300 characters is required.', true);
    if (!window.confirm(`Clear ${quantity} ${item.unit} (${groceryMoney(value)} estimated stock value) from active stock? This does not change financial records.`)) return;
    const movement = {
        id: `GRM-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        type: 'ADJUSTMENT',
        productId: item.id,
        productName: item.name,
        category: item.category,
        unit: item.unit,
        issuePackSize: groceryPackSize(item),
        term: item.term,
        quantity: groceryRound(-quantity, 3),
        stockAfter: 0,
        unitPrice: Number(item.unitPrice) || 0,
        totalValue: value,
        note: `Chief Admin cleared ${quantity} ${item.unit} from active stock. Estimated stock value: ${groceryMoney(value)}. Reason: ${reason.trim()}`,
        date: new Date().toISOString(),
        actor: groceryActorName()
    };
    try {
        await commitGroceryChange(() => {
            item.quantity = 0;
            window.groceryMovements.push(movement);
        },
        `${item.name} stock was cleared and the write-off was synced. Next: delete the empty product if it is no longer needed.`,
        'Reload current stock before attempting the write-off again.');
        window.groceryIssueCart = window.groceryIssueCart.filter(line => String(line.productId) !== String(item.id));
        window.renderGroceryModule();
    } catch (error) {
        console.error('Grocery stock clear failed:', error);
    }
};

window.deleteGroceryProduct = async function(productId) {
    if (!canManageGroceryProducts()) return showGroceryStatus('Access denied. Only the Chief Admin can delete grocery products.', true);
    if (!requireGroceryWriteAccess()) return;
    const item = window.groceryInventory.find(entry => String(entry.id) === String(productId));
    if (!item) return showGroceryStatus('Grocery product not found. Reload the section and try again.', true);
    if (Number(item.quantity) !== 0) return showGroceryStatus('This product still has stock. Use Clear stock first to record the write-off; stock cannot be silently discarded.', true);
    const reason = window.prompt(`Why are you deleting ${groceryProductLabel(item)}? This action will be recorded.`);
    if (reason === null) return;
    if (!reason.trim() || reason.trim().length > 300) return showGroceryStatus('A deletion reason of 1–300 characters is required.', true);
    if (!window.confirm(`Delete ${groceryProductLabel(item)} from active grocery stock? Its issue and purchase history will be retained.`)) return;
    const movement = {
        id: `GRM-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        type: 'PRODUCT_DELETED',
        productId: item.id,
        productName: item.name,
        category: item.category,
        unit: item.unit,
        term: item.term,
        quantity: 0,
        stockAfter: 0,
        unitPrice: Number(item.unitPrice) || 0,
        totalValue: 0,
        note: `Product removed from active grocery stock. Reason: ${reason.trim()}`,
        date: new Date().toISOString(),
        actor: groceryActorName()
    };
    try {
        await commitGroceryChange(() => {
            window.groceryInventory = window.groceryInventory.filter(entry => String(entry.id) !== String(productId));
            window.groceryMovements.push(movement);
        },
        `${item.name} was removed from active stock and synced. Purchase and issue history was retained. No further action is needed.`,
        'Reload current stock and confirm the product is still empty before retrying deletion.');
    } catch (error) {
        console.error('Grocery product deletion failed:', error);
    }
};

window.restoreGroceryProduct = async function(movementId) {
    if (!canManageGroceryProducts()) return showGroceryStatus('Access denied. Only the Chief Admin can restore grocery products.', true);
    if (!requireGroceryWriteAccess()) return;
    const movement = window.groceryMovements.find(entry =>
        String(entry.id) === String(movementId) && entry.type === 'PRODUCT_DELETED'
    );
    if (!movement) return showGroceryStatus('Archived grocery product record not found. Reload history and try again.', true);
    if (window.groceryInventory.some(item => String(item.id) === String(movement.productId))) {
        return showGroceryStatus('This product is already active in grocery stock.', true);
    }
    const movementIndex = window.groceryMovements.findIndex(entry => String(entry.id) === String(movement.id));
    if (window.groceryMovements.slice(movementIndex + 1).some(entry => String(entry.productId) === String(movement.productId))) {
        return showGroceryStatus('This product has later stock history and cannot be restored from this record. Check the newest product history first.', true);
    }
    const item = {
        id: movement.productId,
        name: String(movement.productName || '').trim(),
        category: String(movement.category || '').trim(),
        unit: String(movement.unit || '').trim(),
        issuePackSize: groceryPackSizeBeforeReceipt(movement),
        term: String(movement.term || 'General').trim(),
        quantity: 0,
        unitPrice: Number(movement.unitPrice) || 0
    };
    if (!item.name || !item.category || !item.unit || !item.term || !Number.isFinite(item.unitPrice) || item.unitPrice < 0) {
        return showGroceryStatus('The archived product details are incomplete, so it cannot be restored safely.', true);
    }
    const normalized = value => String(value).trim().toLowerCase();
    const duplicate = window.groceryInventory.find(entry =>
        normalized(entry.name) === normalized(item.name) &&
        normalized(entry.category) === normalized(item.category) &&
        normalized(entry.unit) === normalized(item.unit) &&
        normalized(entry.term) === normalized(item.term)
    );
    if (duplicate) return showGroceryStatus('A matching grocery product is already active. Edit that active product instead of restoring a duplicate.', true);
    const reason = window.prompt(`Why are you restoring ${groceryProductLabel(item)} to the active catalog? It will return with zero stock; earlier purchase and issue history will remain.`);
    if (reason === null) return;
    if (!reason.trim() || reason.trim().length > 300) return showGroceryStatus('A restore reason of 1–300 characters is required.', true);
    if (!window.confirm(`Restore ${groceryProductLabel(item)} to active stock with zero quantity?`)) return;
    const restoreMovement = {
        id: `GRM-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        type: 'PRODUCT_RESTORED',
        productId: item.id,
        productName: item.name,
        category: item.category,
        unit: item.unit,
        issuePackSize: item.issuePackSize,
        term: item.term,
        quantity: 0,
        stockAfter: 0,
        unitPrice: item.unitPrice,
        totalValue: 0,
        note: `Product restored to active grocery stock with zero quantity. Reason: ${reason.trim()}`,
        date: new Date().toISOString(),
        actor: groceryActorName()
    };
    try {
        await commitGroceryChange(() => {
            window.groceryInventory.push(item);
            window.groceryMovements.push(restoreMovement);
        },
        `${item.name} was restored to the active catalog with zero stock. Its earlier history remains available.`,
        'Reload current grocery stock and history before retrying the restore.');
    } catch (error) {
        console.error('Grocery product restore failed:', error);
    }
};

window.fetchTrueStudentBalance = async function(studentId) {
    // Fetch all active charges and payments from the relational ledger
    const { data: ledgerItems, error } = await window.supabaseClient
        .from('student_ledger')
        .select('*')
        .eq('student_id', studentId)
        .neq('status', 'VOID'); // Ignore voided items automatically

    if (error) return 0;

    let billed = 0, paid = 0;
    
    ledgerItems.forEach(item => {
        if (item.type === 'charge') billed += parseFloat(item.amount);
        if (item.type === 'payment') paid += parseFloat(item.amount);
    });

    return billed - paid;
};
window.populateEventHistory = function() {
    const eventSet = new Set();
    if (window.students) {
        window.students.forEach(student => {
            if (student.ledger) {
                student.ledger.forEach(item => {
                    if (item.type === 'charge' && item.desc && item.desc.includes('Event/Trip:')) {
                        const cleanName = item.desc.replace('Event/Trip:', '').trim();
                        if (cleanName) eventSet.add(cleanName);
                    }
                });
            }
        });
    }
    
    const datalist = document.getElementById('eventHistoryList');
    if (datalist) {
        datalist.innerHTML = '';
        eventSet.forEach(evt => {
            const option = document.createElement('option');
            option.value = evt;
            datalist.appendChild(option);
        });
    }
};
window.loadShopDataFromSource = async function() {
    try {
        const [txData, studentData, ledgers] = await Promise.all([
            window.fetchCompleteCloudTable('transactions'),
            window.fetchCompleteCloudTable('students'),
            window.fetchCompleteCloudTable('student_ledger')
        ]);
        window.transactions = txData;
        
        const ledgersByStudent = new Map();
        ledgers.forEach(entry => {
            const studentId = String(entry.student_id || '');
            if (!ledgersByStudent.has(studentId)) ledgersByStudent.set(studentId, []);
            ledgersByStudent.get(studentId).push(entry);
        });
        window.students = studentData.map(student => {
            student.ledger = ledgersByStudent.get(String(student.id)) || [];
            return student;
        });

        console.log("✅ Data successfully loaded from source!");
        
        if (typeof window.calculateShopBalance === 'function') {
            window.calculateShopBalance();
        }
        
    } catch (error) {
        console.error("Failed to load source data:", error);
    }
};
