// 1. HELPER: Auto-populate the Class/Grade dropdown based on your database
window.populatePreFilterGrades = function() {
    const gradeSelect = document.getElementById('preFilterGrade');
    if (!gradeSelect) return;
    
    const uniqueGrades = [...new Set(window.preStudents.map(s => s.grade))].sort();
    
    let html = '<option value="ALL">All Classes/Grades</option>';
    uniqueGrades.forEach(g => {
        html += `<option value="${g}">${g}</option>`;
    });
    
    const currentVal = gradeSelect.value;
    gradeSelect.innerHTML = html;
    if (uniqueGrades.includes(currentVal)) {
        gradeSelect.value = currentVal;
    }
};
// ==========================================
// CORE MIGRATION ENGINE (Handles DB logic)
// ==========================================
window.processSingleMigration = async function(preStudent) {
    // 1. Build the record for the main 'students' table WITHOUT forcing an ID.
    // The database sequence and trigger will automatically assign the STU- ID.
    const activeRecord = {
        name: preStudent.name,
        grade: preStudent.grade,
        phone: preStudent.phone || '',
        dob: preStudent.dob || null,
        status: 'ACTIVE',
        enrollment_status: 'active',
        balance_owing: 0,
        billing_plan: 'termly',
        enroll_date: new Date().toISOString().split('T')[0]
    };

    // 2. Insert into students and ask Supabase to return the generated data
    const { data: savedStudent, error: insErr } = await window.supabaseClient
        .from('students')
        .insert([activeRecord])
        .select()
        .single();

    if (insErr) throw insErr;
    
    // Grab the database-generated ID (e.g., STU-1051)
    const finalStudentId = savedStudent.id;

    // 3. Update their status in the pre_enrollments table so we know they are done
    const { error: updErr } = await window.supabaseClient
        .from('pre_enrollments')
        .update({ status: 'Migrated' })
        .eq('id', preStudent.id);
        
    if (updErr) throw updErr;

    return finalStudentId; // Return it so the UI can display success messages
};

// ==========================================
// SINGLE STUDENT MIGRATION (For the Table Button)
// ==========================================
window.migrateToActive = async function(preStudentId) {
    if (!confirm(`Move pre-student ${preStudentId} into the main active student database?`)) return;

    const student = window.preStudents.find(s => s.id === preStudentId);
    if (!student) return alert("Student data not found.");

    try {
        const newStuId = await window.processSingleMigration(student);
        alert(`✅ Success! Student moved to active list with official ID: ${newStuId}`);
        
        if (window.loadPreStudents) window.loadPreStudents(); 
    } catch (error) {
        console.error("Migration Error:", error);
        alert("❌ Failed to migrate student: " + error.message);
    }
};

// ==========================================
// BULK SEQUENTIAL MIGRATION (Executes one by one)
// ==========================================
window.migrateBulkPreStudents = async function() {
    // Filter to only get students who haven't been migrated yet
    const pendingStudents = window.preStudents.filter(s => s.status !== 'Migrated');
    
    if (pendingStudents.length === 0) {
        return alert("There are no pending students left to migrate.");
    }

    if (!confirm(`🚀 Are you sure you want to migrate ALL ${pendingStudents.length} pending students into the main database?\n\nThis will process them sequentially.`)) {
        return;
    }

    document.body.style.cursor = 'wait';
    let successCount = 0;
    let failCount = 0;

    // Using a for...of loop ensures they execute ONE AFTER ANOTHER, not all at once, 
    // protecting your database sequence from race conditions.
    for (const student of pendingStudents) {
        try {
            await window.processSingleMigration(student);
            successCount++;
        } catch (error) {
            console.error(`Failed to migrate ${student.name} (${student.id}):`, error);
            failCount++;
        }
    }

    document.body.style.cursor = 'default';
    alert(`🏁 Bulk Migration Complete!\n\n✅ Successfully Migrated: ${successCount}\n❌ Failed/Skipped: ${failCount}`);
    
    // Refresh the directory to remove the migrated students from view
    if (window.loadPreStudents) window.loadPreStudents();
};

// 2. UPDATED FILTER ENGINE: Replaces your old renderPreDirectory
window.renderPreDirectory = function() {
    const search = (document.getElementById('preFilterSearch').value || '').toLowerCase();
    const gradeFilter = document.getElementById('preFilterGrade').value;
    const admFilter = document.getElementById('preFilterAdmission').value;
    const uniFilter = document.getElementById('preFilterUniform').value;
    
    // NEW: Date Filters
    const startDate = document.getElementById('preFilterDateStart').value;
    const endDate = document.getElementById('preFilterDateEnd').value;
    
    const tbody = document.getElementById('preDirectoryBody');
    let html = '';
    
    let totAdm = 0; 
    let totUni = 0;
    let studentCount = 0;

    window.preStudents.forEach(s => {
        const admPaid = parseFloat(s.total_admission_paid || 0);
        const uniPaid = parseFloat(s.total_uniforms_paid || 0);

        // Assuming your date field in DB is 'created_at'. If it's 'enrollment_date', change it below.
        const recordDateRaw = s.created_at || s.date || ''; 
        const recordDate = recordDateRaw ? recordDateRaw.split('T')[0] : '';

        // Filter Checks
        if (gradeFilter !== 'ALL' && s.grade !== gradeFilter) return;
        if (search && !s.name.toLowerCase().includes(search) && !s.id.toLowerCase().includes(search)) return;
        if (admFilter === 'PAID' && admPaid <= 0) return;
        if (admFilter === 'UNPAID' && admPaid > 0) return;
        if (uniFilter === 'PAID' && uniPaid <= 0) return;
        if (uniFilter === 'UNPAID' && uniPaid > 0) return;
        
        // Date Logic Check
        if (startDate && recordDate < startDate) return;
        if (endDate && recordDate > endDate) return;

        // If it passes all filters, add to totals
        totAdm += admPaid;
        totUni += uniPaid;
        studentCount++;

        html += `
        <tr style="border-bottom: 1px solid #eee;">
            <td>${recordDate || '-'}</td>
            <td><strong>${s.id}</strong></td>
            <td>${s.name}</td>
            <td>${s.grade}</td>
            <td>${s.phone || '-'}</td>
            <td style="color: ${admPaid > 0 ? '#27ae60' : '#e74c3c'}; font-weight: bold;">$${admPaid.toFixed(2)}</td>
            <td style="color: ${uniPaid > 0 ? '#8e44ad' : '#7f8c8d'}; font-weight: bold;">$${uniPaid.toFixed(2)}</td>
            <td style="min-width: 170px;">
                <!-- NEW: Edit Button added here -->
                <button class="btn-standard" style="padding: 4px 8px; font-size: 11px; background: #3498db; color: white;" onclick="openEditPreStudent('${s.id}')">Edit</button>
                <button class="btn-standard btn-warning" style="padding: 4px 8px; font-size: 11px;" onclick="migrateToActive('${s.id}')">Migrate</button>
                <button class="btn-standard btn-danger" style="padding: 4px 8px; font-size: 11px; margin-left: 2px; background: #c0392b; color: white;" onclick="deletePreStudent('${s.id}')">Del</button>
            </td>
        </tr>`;
    });

    tbody.innerHTML = html || '<tr><td colspan="8" style="text-align:center; padding: 20px;">No students match the selected filters.</td></tr>';
    
    // Update the Summary Banner
    document.getElementById('preTotalAdm').innerText = totAdm.toFixed(2);
    document.getElementById('preTotalUni').innerText = totUni.toFixed(2);
    document.getElementById('preTotalStudents').innerText = studentCount;
};

