window.openEditPreStudent = function(id) {
    const student = window.preStudents.find(s => s.id === id);
    if (!student) return alert("Student not found!");

    document.getElementById('editPreId').value = student.id;
    document.getElementById('editPreName').value = student.name;
    document.getElementById('editPreGrade').value = student.grade;
    document.getElementById('editPrePhone').value = student.phone || '';

    document.getElementById('editPreStudentModal').style.display = 'block';
};

window.closeEditPreStudent = function() {
    document.getElementById('editPreStudentModal').style.display = 'none';
};

window.savePreStudent = async function() {
    const id = document.getElementById('editPreId').value;
    const name = document.getElementById('editPreName').value.trim();
    const grade = document.getElementById('editPreGrade').value.trim();
    const phone = document.getElementById('editPrePhone').value.trim();

    if (!name || !grade) {
        return alert("Name and Grade are required!");
    }

    try {
        // Update Supabase
        const { error } = await window.supabaseClient
            .from('pre_enrollments')
            .update({ name, grade, phone })
            .eq('id', id);

        if (error) throw error;

        alert("✅ Student updated successfully!");
        closeEditPreStudent();

        // Refresh Data
        if (typeof loadPreStudents === 'function') {
            await loadPreStudents(); 
        } else {
            // Local fallback array update if load function isn't mapped
            const student = window.preStudents.find(s => s.id === id);
            if(student) {
                student.name = name;
                student.grade = grade;
                student.phone = phone;
                window.renderPreDirectory();
            }
        }
    } catch (err) {
        alert("Error saving student: " + err.message);
    }
};

